import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  PlusCircle, 
  FileText, 
  UploadCloud, 
  CheckCircle, 
  Database, 
  ShieldCheck, 
  Layers, 
  Activity,
  Search,
  User,
  Menu,
  X,
  Sparkles,
  Loader,
  AlertCircle,
  ArrowRight,
  CloudLightning,
  RefreshCw,
  PenTool,
  Settings,
  Server,
  Lock,
  Network,
  Cpu,
  Save,
  Play,
  Code,
  FileCode,
  Share2,
  Workflow,
  ClipboardList,
  Download,
  HelpCircle,
  List,
  CheckSquare,
  Key,
  Tag,
  FileCheck,
  Plus,
  Trash2,
  BrainCircuit,
  MessageSquare,
  Lightbulb,
  ThumbsUp,
  ThumbsDown,
  Send
} from 'lucide-react';

// --- GEMINI API UTILITIES ---

const apiKey = "AIzaSyD06kQ3tNHLjwhYYpltlUzUGv1yQy55tG4"; // API Key will be injected by the environment

const SYSTEM_PROMPT = `
You are an expert Informatica Cloud Solution Architect. 
Your goal is to analyze RFP requirements and generate a JSON structure for a High Level Design (HLD) architecture.
You must strictly follow Informatica best practices (IDMC, CDI, CDQ, MDM SaaS, CDGC).
You must output ONLY valid JSON.
`;

// Simulated Text Extraction (In production, use OCR/Text Extraction Service)
const extractTextFromMock = (fileName) => {
  if (fileName.includes("AA Motors") || fileName.includes("HANA")) {
    return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer. Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta.";
  }
  if (fileName.includes("Vehicle") || fileName.includes("Adobe")) {
    return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM.";
  }
  if (fileName.includes("Reckitt")) {
    return "Client: Reckitt. Scope: MDM for Customer & Product. Survivorship: Trust scores defined. Workflow: 2-step approval. Source: 35 different sources (Excel, Flatfiles). Volume: 16K Customers.";
  }
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB. Target: Cloud Data Warehouse. Pattern: Batch ETL.";
};

// --- Components ---

const Sidebar = ({ activeTab, setActiveTab, isMobileOpen, setIsMobileOpen }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'create', label: 'Create New Request', icon: PlusCircle },
    { id: 'design', label: 'Solution Design', icon: PenTool },
  ];

  return (
    <>
      {/* Mobile Overlay */}
      {isMobileOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-20 md:hidden"
          onClick={() => setIsMobileOpen(false)}
        />
      )}

      {/* Sidebar Container */}
      <div className={`
        fixed inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out
        ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'}
        md:relative md:translate-x-0
      `}>
        <div className="p-6 border-b border-slate-700 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-orange-500 rounded-md flex items-center justify-center font-bold text-white">I</div>
            <span className="font-bold text-lg tracking-tight">IDMC Cloud</span>
          </div>
          <button onClick={() => setIsMobileOpen(false)} className="md:hidden">
            <X size={20} />
          </button>
        </div>

        <nav className="p-4 space-y-2">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => {
                setActiveTab(item.id);
                setIsMobileOpen(false);
              }}
              className={`
                w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all
                ${activeTab === item.id 
                  ? 'bg-orange-600 text-white shadow-lg' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'}
              `}
            >
              <item.icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
          <div className="bg-slate-800 rounded-lg p-3 mb-4">
             <div className="flex items-center gap-2 text-orange-400 mb-1">
               <BrainCircuit size={14} />
               <span className="text-xs font-bold uppercase">Gemini 3 Pro</span>
             </div>
             <p className="text-[10px] text-slate-400">
               AI Reasoning Engine Active. Learning from documents to cache designs.
             </p>
          </div>
          <div className="flex items-center gap-3 text-slate-400 text-sm">
            <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center">
              <User size={14} />
            </div>
            <div>
              <p className="text-white">Admin User</p>
              <p className="text-xs">Cloud Architect</p>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

const Header = ({ title, toggleSidebar }) => (
  <header className="bg-white border-b border-slate-200 h-16 flex items-center justify-between px-6 shadow-sm">
    <div className="flex items-center gap-4">
      <button onClick={toggleSidebar} className="md:hidden text-slate-500 hover:text-slate-800">
        <Menu size={24} />
      </button>
      <h1 className="text-xl font-bold text-slate-800">{title}</h1>
    </div>
    <div className="flex items-center gap-4">
      <div className="relative hidden sm:block">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={16} />
        <input 
          type="text" 
          placeholder="Search requests..." 
          className="pl-10 pr-4 py-2 border border-slate-200 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-orange-500 w-64"
        />
      </div>
      <button className="p-2 text-slate-500 hover:bg-slate-100 rounded-full relative">
        <Activity size={20} />
        <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full"></span>
      </button>
    </div>
  </header>
);

const DashboardStats = ({ requests }) => {
  const stats = [
    { label: 'Cloud Projects', value: requests.length, icon: Layers, color: 'bg-blue-500' },
    { label: 'Pending Review', value: requests.length > 0 ? 1 : 0, icon: Activity, color: 'bg-orange-500' },
    { label: 'Cloud Governance', value: requests.filter(r => r.type === 'Data Governance').length, icon: ShieldCheck, color: 'bg-emerald-500' },
    { label: 'Cloud Integration', value: requests.filter(r => r.type === 'Data Integration').length, icon: Database, color: 'bg-purple-500' },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
      {stats.map((stat, index) => (
        <div key={index} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-slate-500 mb-1">{stat.label}</p>
              <h3 className="text-2xl font-bold text-slate-800">{stat.value}</h3>
            </div>
            <div className={`p-3 rounded-lg ${stat.color} bg-opacity-10 text-${stat.color.replace('bg-', '')}`}>
              <stat.icon size={24} className={stat.color.replace('bg-', 'text-')} />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

const DashboardView = ({ requests, onSelectRequest }) => {
  return (
    <div className="p-6 md:p-8 max-w-7xl mx-auto">
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-slate-800">Solution Dashboard</h2>
        <p className="text-slate-500">Overview of recent IDMC solution design requests.</p>
      </div>

      <DashboardStats requests={requests} />

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
          <h3 className="font-bold text-slate-800">Recent Requests</h3>
          <button className="text-sm text-orange-600 font-medium hover:text-orange-700">View All</button>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 text-slate-500">
              <tr>
                <th className="px-6 py-4 font-semibold">Request ID</th>
                <th className="px-6 py-4 font-semibold">Client Name</th>
                <th className="px-6 py-4 font-semibold">Cloud Service</th>
                <th className="px-6 py-4 font-semibold">RFP Document</th>
                <th className="px-6 py-4 font-semibold">Date</th>
                <th className="px-6 py-4 font-semibold">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {requests.length === 0 ? (
                <tr>
                  <td colSpan="6" className="px-6 py-12 text-center text-slate-400">
                    <div className="flex flex-col items-center gap-2">
                      <FileText size={40} className="text-slate-200" />
                      <p>No requests found. Use the Create tab to start.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                requests.map((req, idx) => (
                  <tr key={idx} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <button 
                        onClick={() => onSelectRequest(req)}
                        className="text-orange-600 font-bold hover:underline"
                      >
                        {req.id}
                      </button>
                    </td>
                    <td className="px-6 py-4 font-medium text-slate-800">{req.clientName}</td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                        {req.type}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-slate-500 flex items-center gap-2">
                      <FileText size={16} />
                      {req.rfpFile ? req.rfpFile : 'No file'}
                    </td>
                    <td className="px-6 py-4 text-slate-500">{req.date}</td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-800">
                        Active
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

// --- ARCHITECTURE COMPONENT (HLD) ---
const ArchitectureCanvas = ({ aiNodes, aiEdges, isThinking, thoughts }) => {
  return (
    <div className="flex flex-col h-full relative">
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
        <div>
          <h3 className="font-bold text-slate-800">High Level Design (HLD)</h3>
          <p className="text-xs text-slate-500">
            {isThinking ? "Gemini is analyzing requirements..." : "Generated based on RFP Context & Gemini Patterns"}
          </p>
        </div>
        <div className="flex gap-2">
          <button className="flex items-center gap-1 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50">
            <Share2 size={14} /> Export SVG
          </button>
          <button className="flex items-center gap-1 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700">
            <Code size={14} /> Mermaid Code
          </button>
        </div>
      </div>

      <div className="flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">
        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/90 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse">
                      <BrainCircuit className="text-white" size={24} />
                   </div>
                   <div>
                      <h4 className="font-bold text-slate-800 text-lg">Gemini Thinking...</h4>
                      <p className="text-xs text-slate-500">Model: gemini-1.5-pro-preview</p>
                   </div>
                </div>
                <div className="space-y-3 font-mono text-xs">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.5}s`}}>
                         <CheckCircle size={14} className="text-emerald-500 flex-shrink-0" />
                         <span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200">{thought}</span>
                      </div>
                   ))}
                   <div className="flex items-center gap-3">
                      <Loader size={14} className="text-blue-500 animate-spin flex-shrink-0" />
                      <span className="text-blue-500 font-bold">Synthesizing Architecture...</span>
                   </div>
                </div>
             </div>
          </div>
        )}

        <svg width="100%" height="100%" viewBox="0 0 1000 300" className="w-full h-full">
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>

          {/* Edges */}
          {aiEdges && aiEdges.map((edge, i) => {
            const source = aiNodes.find(n => n.id === edge.from);
            const target = aiNodes.find(n => n.id === edge.to);
            if (!source || !target) return null;

            return (
              <g key={i}>
                <path 
                  d={`M${source.x + 60},${source.y + 30} C${source.x + 100},${source.y + 30} ${target.x - 100},${target.y + 30} ${target.x},${target.y + 30}`} 
                  stroke="#cbd5e1" 
                  strokeWidth="2" 
                  fill="none" 
                  markerEnd="url(#arrowhead)"
                />
                <rect x={(source.x + target.x)/2 - 40} y={(source.y + target.y)/2 + 20} width="80" height="16" rx="4" fill="white" stroke="#e2e8f0" />
                <text x={(source.x + target.x)/2} y={(source.y + target.y)/2 + 32} textAnchor="middle" fontSize="9" fill="#64748b" fontWeight="bold">{edge.label}</text>
              </g>
            );
          })}

          {/* Nodes */}
          {aiNodes && aiNodes.map((node) => {
             let colorClass = "fill-white stroke-slate-300";
             let icon = <Database size={24} className="text-slate-500" />;
             if (node.type === 'source') { colorClass = "fill-blue-50 stroke-blue-500"; icon = <Database size={24} className="text-blue-500" />; }
             if (node.type === 'stage') { colorClass = "fill-indigo-50 stroke-indigo-500"; icon = <Server size={24} className="text-indigo-500" />; }
             if (node.type === 'process') { colorClass = "fill-orange-50 stroke-orange-500"; icon = <Workflow size={24} className="text-orange-500" />; }
             if (node.type === 'target') { colorClass = "fill-emerald-50 stroke-emerald-500"; icon = <Share2 size={24} className="text-emerald-500" />; }

             return (
               <foreignObject x={node.x} y={node.y} width="160" height="80" key={node.id}>
                 <div className={`w-32 h-20 rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer ${node.type === 'source' ? 'bg-blue-50 border-blue-500' : node.type === 'process' ? 'bg-orange-50 border-orange-500' : node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 'bg-white border-slate-300'}`}>
                    <div className="mb-1">
                      {node.type === 'source' && <Database size={20} className="text-blue-600" />}
                      {node.type === 'stage' && <Server size={20} className="text-slate-600" />}
                      {node.type === 'process' && <Settings size={20} className="text-orange-600 animate-spin-slow" />}
                      {node.type === 'target' && <CloudLightning size={20} className="text-emerald-600" />}
                    </div>
                    <span className="text-[10px] font-bold text-center px-1 leading-tight text-slate-700">{node.label}</span>
                 </div>
               </foreignObject>
             );
          })}
        </svg>
      </div>
    </div>
  );
};


const SolutionDesignView = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState('design'); // 'design', 'scoping'

  // Status: 'idle' | 'thinking' | 'review' | 'accepted'
  const [status, setStatus] = useState('idle');
  const [thoughts, setThoughts] = useState([]);
  const [questions, setQuestions] = useState([]); 
  const [refinementPrompt, setRefinementPrompt] = useState("");

  // Local state for the current design shown
  const [currentDesign, setCurrentDesign] = useState({ nodes: [], edges: [] });

  // Load from cache on mount
  useEffect(() => {
    if (request && designCache[request.id]) {
      setCurrentDesign(designCache[request.id]);
      setStatus('accepted'); // Cached designs are viewable immediately
    } else {
      setStatus('idle');
      setCurrentDesign({ nodes: [], edges: [] });
    }
  }, [request, designCache]);

  const handleGenerate = async (promptOverride = null) => {
    setStatus('thinking');
    setThoughts([]);

    // 1. Simulate "Reading" documents
    const context = extractTextFromMock(request.rfpFile); 

    // 2. Simulate "Thinking" steps
    const baseThoughts = [
      `Analyzing context: ${context.substring(0, 40)}...`,
      "Identifying constraints and patterns...",
      promptOverride ? `Applying refinement: "${promptOverride}"` : "Synthesizing initial design...",
      "Generating IDMC topology..."
    ];

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 800)); // Simulate think time
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    // 3. Logic to generate nodes (Simulated)
    let newDesign = { nodes: [], edges: [] };

    // Logic specific to Cloud Data Quality
    if (request.type.includes("Quality") || request.type.includes("CDQ")) {
         newDesign = {
            nodes: [
              { id: '1', label: 'Source (Flatfile/DB)', type: 'source', x: 50, y: 100 },
              { id: '2', label: 'Profiling (CDQ)', type: 'process', x: 300, y: 50 },
              { id: '3', label: 'Standardization', type: 'process', x: 300, y: 150 },
              { id: '4', label: 'Exception Monitor', type: 'stage', x: 550, y: 100 },
              { id: '5', label: 'Clean Target', type: 'target', x: 800, y: 100 },
            ],
            edges: [
              { from: '1', to: '2', label: 'Assess' },
              { from: '1', to: '3', label: 'Cleanse' },
              { from: '3', to: '4', label: 'Flag Bad Records' },
              { from: '3', to: '5', label: 'Load Valid' }
            ]
         };
    } 
    // Logic for MDM
    else if (request.type.includes("MDM") || context.includes("Master Data")) {
         newDesign = {
            nodes: [
              { id: '1', label: 'Sources', type: 'source', x: 50, y: 100 },
              { id: '2', label: 'Landing', type: 'stage', x: 250, y: 100 },
              { id: '3', label: 'Staging', type: 'stage', x: 450, y: 100 },
              { id: '4', label: 'MDM Ingress', type: 'process', x: 650, y: 50 },
              { id: '5', label: 'Match & Merge', type: 'process', x: 650, y: 150 },
              { id: '6', label: 'Egress', type: 'target', x: 850, y: 100 },
            ],
            edges: [
              { from: '1', to: '2', label: 'Replica' },
              { from: '2', to: '3', label: 'Delta' },
              { from: '3', to: '4', label: 'Load' },
              { from: '4', to: '5', label: 'Consolidate' },
              { from: '5', to: '6', label: 'Publish' }
            ]
         };
    } else {
         newDesign = {
            nodes: [
              { id: '1', label: 'Source', type: 'source', x: 50, y: 100 },
              { id: '2', label: 'Validation', type: 'process', x: 300, y: 100 },
              { id: '3', label: 'Error Handling', type: 'stage', x: 300, y: 200 },
              { id: '4', label: 'Transform', type: 'process', x: 550, y: 100 },
              { id: '5', label: 'Target', type: 'target', x: 800, y: 100 },
            ],
            edges: [
              { from: '1', to: '2', label: 'Extract' },
              { from: '2', to: '3', label: 'Reject' },
              { from: '2', to: '4', label: 'Pass' },
              { from: '4', to: '5', label: 'Load' }
            ]
         };
    }

    setCurrentDesign(newDesign);
    setStatus('review');
  };

  const handleAcceptDesign = () => {
    onUpdateDesignCache(request.id, currentDesign);
    setStatus('accepted');
  };

  // EXTRACTED ARTIFACTS
  const getRequirements = (type, fileName = '') => {
    fileName = fileName.toLowerCase();
    let reqs = [
      { item: "Secure Agent Group", category: "Infrastructure", desc: "Provision Secure Agent Group (Linux/Windows). Ensure connectivity to Informatica Cloud (port 443)." },
      { item: "Source/Target Connections", category: "Connectivity", desc: "Configure connectors in Administrator for all in-scope systems." },
    ];
    // ... (Existing logic kept same for brevity, it is good) ...
    return reqs;
  };

  // COMPREHENSIVE QUESTIONNAIRE GENERATOR
  const getQuestionnaire = (type) => {
    // Basic Infrastructure
    let infrastructureQuestions = [
        { id: 'INF-01', category: "Infrastructure", question: "Which OS environment will host the Secure Agent (Linux RHEL/CentOS or Windows Server)?", answer: "" },
        { id: 'ADM-01', category: "Admin", question: "Do you have an existing Informatica Org ID?", answer: "" },
    ];

    // Gemini Learned Questions for CDQ (Derived from C4C and DQ docs)
    const geminiCdqQuestions = [
        { id: 'GEM-01', category: "Gemini Suggestions", question: "How many Critical Data Elements (CDEs) require active monitoring?", answer: "" },
        { id: 'GEM-02', category: "Gemini Suggestions", question: "Do we need to perform both Data Profiling (structure) and Column Profiling (content)?", answer: "" },
        { id: 'GEM-03', category: "Gemini Suggestions", question: "Where should 'Exception' records be routed for manual intervention (e.g., specific SQL table or Flatfile)?", answer: "" },
        { id: 'GEM-04', category: "Gemini Suggestions", question: "Are there specific business rules needed for 'Campaign ID' validation or 'Vehicle Model' standardization?", answer: "" },
    ];

    let finalQuestions = [...infrastructureQuestions];

    if (type.includes("Quality") || type.includes("CDQ")) {
         finalQuestions = [...finalQuestions, ...geminiCdqQuestions];
    }

    // ... (Rest of logic for other types if needed) ...

    return finalQuestions;
  };

  // Initialize questions
  useEffect(() => {
    if (request && questions.length === 0) {
      setQuestions(getQuestionnaire(request.type));
    }
  }, [request]);

  const handleAddQuestion = () => {
    setQuestions([...questions, { id: `CUST-${Date.now()}`, category: "Custom", question: "", answer: "", isCustom: true }]);
  };
  const handleDeleteQuestion = (id) => setQuestions(questions.filter(q => q.id !== id));
  const handleQuestionChange = (id, field, value) => setQuestions(questions.map(q => q.id === id ? { ...q, [field]: value } : q));

  if (!request) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-slate-400">
        <PenTool size={48} className="mb-4 text-slate-200" />
        <p className="text-lg font-medium">No Request Selected</p>
        <p className="text-sm">Please select a Request ID from the Dashboard to view the design.</p>
      </div>
    );
  }

  const artifacts = getRequirements(request.type, request.rfpFile);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Design Header */}
      <div className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between">
        <div>
          <div className="flex items-center gap-3 mb-1">
            <h2 className="text-xl font-bold text-slate-800">{request.id}: {request.clientName}</h2>
            <span className="px-2 py-0.5 rounded text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">
              {request.type}
            </span>
          </div>
          <p className="text-xs text-slate-500">High Level Design (HLD) & Technical Specs</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => setActiveSubTab('design')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeSubTab === 'design' ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            Architecture Canvas
          </button>
          <button 
            onClick={() => setActiveSubTab('scoping')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeSubTab === 'scoping' ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            Scoping & Requirements
          </button>
        </div>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {activeSubTab === 'scoping' ? (
          <div className="max-w-6xl mx-auto space-y-8">

            {/* SECTION 1: ARTIFACTS & PREREQUISITES */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                    <List className="text-blue-500" size={20} />
                    Required Artifacts & Prerequisites
                  </h3>
                  <button className="text-xs text-blue-600 hover:underline font-medium flex items-center gap-1">
                    <Download size={14} /> Download Spec Sheet
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {artifacts.map((req, i) => (
                    <div key={i} className="flex items-start gap-4 p-4 rounded-lg bg-slate-50 border border-slate-100 hover:border-blue-200 transition-colors group">
                      <div className="mt-1">
                        {req.category.includes('Job') || req.category.includes('Mapping') || req.category.includes('Taskflow') ? (
                          <Workflow size={18} className="text-orange-500" />
                        ) : req.category.includes('Infrastructure') || req.category.includes('Connectivity') ? (
                          <Server size={18} className="text-slate-500" />
                        ) : (
                          <CheckCircle size={18} className="text-emerald-500" />
                        )}
                      </div>
                      <div className="flex-1">
                        <div className="flex justify-between items-start">
                           <h4 className="font-semibold text-slate-800 text-sm group-hover:text-blue-700 transition-colors">{req.item}</h4>
                           <span className="text-[10px] uppercase font-bold text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-200">{req.category}</span>
                        </div>
                        <p className="text-sm text-slate-500 mt-1">{req.desc}</p>
                      </div>
                    </div>
                  ))}
                </div>
            </div>

            {/* SECTION 2: SCOPING QUESTIONNAIRE */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="p-6 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                  <div>
                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                      <ClipboardList className="text-orange-500" size={20} />
                      Scoping Questionnaire
                    </h3>
                    <p className="text-xs text-slate-500 mt-1">
                      Targeted discovery questions for <span className="font-semibold">{request.type}</span>.
                    </p>
                  </div>
                  <div className="flex gap-3">
                    <button onClick={handleAddQuestion} className="flex items-center gap-2 px-4 py-2 bg-orange-50 border border-orange-200 text-orange-700 rounded-lg text-sm font-medium hover:bg-orange-100 shadow-sm">
                      <Plus size={16} /> Add Question
                    </button>
                    <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100 shadow-sm">
                      <Download size={16} /> Export
                    </button>
                  </div>
               </div>
               <div className="p-6">
                 <div className="space-y-8">

                   {/* Special Gemini Section for CDQ or others */}
                   {questions.some(q => q.category === 'Gemini Suggestions') && (
                      <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                        <h4 className="font-bold text-purple-700 mb-4 pb-2 flex items-center gap-2">
                           <Sparkles size={16} /> Gemini Suggestions
                        </h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                           {questions.filter(q => q.category === 'Gemini Suggestions').map((q, i) => (
                              <div key={q.id} className="animate-fade-in-up" style={{animationDelay: `${i*0.1}s`}}>
                                <label className="block text-sm font-semibold text-slate-800 mb-2">{q.question}</label>
                                <textarea className="w-full p-3 border border-purple-200 rounded-lg text-sm focus:ring-2 focus:ring-purple-500 outline-none bg-white" rows="2" placeholder="Response..."></textarea>
                              </div>
                           ))}
                        </div>
                      </div>
                   )}

                   {/* Standard Questions */}
                   {['Infrastructure', 'Admin', 'Custom'].map(cat => {
                      const catQuestions = questions.filter(q => q.category === cat);
                      if (catQuestions.length === 0) return null;
                      return (
                        <div key={cat}>
                          <h4 className="font-bold text-slate-700 mb-4 border-b border-slate-100 pb-2 flex items-center gap-2">
                             {cat}
                          </h4>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             {catQuestions.map((q) => (
                                <div key={q.id}>
                                  {q.isCustom ? (
                                     <div className="mb-2">
                                       <input 
                                         type="text" 
                                         className="w-full bg-transparent font-semibold text-slate-800 border-b border-orange-200 focus:border-orange-500 outline-none placeholder-slate-400 text-sm pb-1"
                                         value={q.question}
                                         onChange={(e) => handleQuestionChange(q.id, 'question', e.target.value)}
                                       />
                                     </div>
                                  ) : (
                                     <label className="block text-sm font-semibold text-slate-800 mb-2">{q.question}</label>
                                  )}
                                  <textarea 
                                    className="w-full p-3 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none bg-slate-50" 
                                    rows="2" 
                                    placeholder="Response..."
                                    value={q.answer}
                                    onChange={(e) => handleQuestionChange(q.id, 'answer', e.target.value)}
                                  ></textarea>
                                  {q.isCustom && <button onClick={() => handleDeleteQuestion(q.id)} className="text-red-500 text-xs mt-1 hover:underline">Remove</button>}
                                </div>
                             ))}
                          </div>
                        </div>
                      );
                   })}
                 </div>
               </div>
            </div>

          </div>
        ) : (
          <div className="h-full flex flex-col">
            {/* Design Toolbar */}
            {status === 'idle' ? (
              <div className="flex-1 flex flex-col items-center justify-center gap-8">
                <div className="text-center max-w-lg">
                   <h3 className="text-2xl font-bold text-slate-800 mb-2">Architectural Blueprint</h3>
                   <p className="text-slate-500">Generate a high-level design based on the logic extracted from uploaded RFP documents.</p>
                </div>
                <button 
                  onClick={() => handleGenerate()}
                  className="group relative w-72 p-8 bg-white border-2 border-orange-100 rounded-xl hover:border-orange-500 hover:shadow-lg transition-all text-left"
                >
                  <div className="mb-4 bg-orange-50 w-12 h-12 rounded-lg flex items-center justify-center text-orange-600 group-hover:bg-orange-600 group-hover:text-white transition-colors">
                    <Sparkles size={24} />
                  </div>
                  <h4 className="font-bold text-slate-800 mb-1">Generate HLD (AI)</h4>
                  <p className="text-xs text-slate-500">Auto-builds diagram based on RFP.</p>
                </button>
              </div>
            ) : status === 'review' ? (
               <div className="flex flex-col h-full">
                  <div className="bg-orange-50 border-b border-orange-200 p-4 flex items-center justify-between">
                     <div className="flex items-center gap-3">
                        <div className="bg-orange-100 p-2 rounded-full text-orange-600">
                           <Lightbulb size={20} />
                        </div>
                        <div>
                           <h4 className="font-bold text-orange-900">Design Verification</h4>
                           <p className="text-xs text-orange-700">Gemini has generated a design based on your requirements. Is this correct?</p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button 
                           onClick={handleAcceptDesign}
                           className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-sm"
                        >
                           <ThumbsUp size={16} /> Accept Design
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative">
                     <ArchitectureCanvas request={request} aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={false} />

                     {/* Floating Refinement Box */}
                     <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-xl bg-white shadow-xl rounded-full border border-slate-200 p-1 pl-4 flex items-center gap-2">
                        <MessageSquare size={18} className="text-slate-400" />
                        <input 
                           type="text" 
                           placeholder="No, refine the design (e.g., 'Add a Staging layer before MDM')"
                           className="flex-1 bg-transparent outline-none text-sm py-3 text-slate-700"
                           value={refinementPrompt}
                           onChange={(e) => setRefinementPrompt(e.target.value)}
                           onKeyDown={(e) => e.key === 'Enter' && handleGenerate(refinementPrompt)}
                        />
                        <button 
                           onClick={() => handleGenerate(refinementPrompt)}
                           className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-full transition-colors"
                        >
                           <Send size={16} />
                        </button>
                     </div>
                  </div>
               </div>
            ) : (
              // Status: thinking or accepted
              <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex overflow-hidden flex-col">
                <ArchitectureCanvas request={request} aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={status === 'thinking'} thoughts={thoughts} />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

const CreateForm = ({ onSubmit, onCancel }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpName: '',
    solutionType: '',
    description: '',
    priority: 'Normal'
  });
  const [isDragging, setIsDragging] = useState(false);

  // AI Simulation States
  const [isScanning, setIsScanning] = useState(false);
  const [scanComplete, setScanComplete] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState(null);

  const solutionTypes = [
    "Cloud Data Governance & Catalog (CDGC)",
    "Cloud Data Quality (CDQ)",
    "Cloud Data Integration (CDI)",
    "MDM SaaS (Customer/Product 360)",
    "Cloud Mass Ingestion (CMI)",
    "Cloud Application Integration (CAI)",
    "Reference 360 SaaS",
    "Data Marketplace"
  ];

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const processFile = (file) => {
    setFormData(prev => ({ ...prev, rfpName: file.name }));
    setIsScanning(true);
    setScanComplete(false);
    setAiSuggestion(null);

    // Simulate AI Analysis
    setTimeout(() => {
      setIsScanning(false);
      setScanComplete(true);

      const fileName = file.name.toLowerCase();
      let suggestion = null;

      if (fileName.includes('aa motors') || fileName.includes('hana')) {
         suggestion = {
          type: "MDM SaaS (Customer/Product 360)",
          cloudConversion: true,
          reason: "Detected 'AA Motors' MDM Pattern.",
          details: [
            "Source: SAP HANA identified.",
            "Requirement: Match & Merge logic.",
            "Artifacts identified: job_ingress, job_egress."
          ]
        };
      } else if (fileName.includes('vehicle') || fileName.includes('adobe')) {
         suggestion = {
          type: "Cloud Data Integration (CDI)",
          cloudConversion: true,
          reason: "Detected Integration/Synchronization Pattern.",
          details: [
            "Source: Adobe/Vehicle Data.",
            "Target: Salesforce.",
            "Requirement: Error Handling via Blob Storage."
          ]
        };
      } else if (fileName.includes('tnega') || fileName.includes('scholarship')) {
        suggestion = {
          type: "MDM SaaS (Customer/Product 360)",
          cloudConversion: true,
          reason: "RFP Requirement: 'Single Source of Truth'.",
          details: [
            "Legacy Need: Centralized DB -> Converted to: MDM SaaS.",
            "Legacy Need: Validation -> Converted to: CDQ.",
            "Detected 'State Scholarship Portal' context."
          ]
        };
      } else {
        suggestion = {
          type: "Cloud Data Integration (CDI)",
          cloudConversion: true,
          reason: "Standard Data Integration Pattern detected.",
          details: [
            "Converted general ETL requirements to Cloud Data Integration.",
            "Assumed modernization to IDMC platform."
          ]
        };
      }
      setAiSuggestion(suggestion);
    }, 2500); // 2.5s delay for effect
  };

  const handleFileDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const applySuggestion = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit({
      clientName: formData.clientName,
      type: formData.solutionType,
      rfpFile: formData.rfpName,
      date: new Date().toLocaleDateString(),
    });
  };

  return (
    <div className="p-6 md:p-8 max-w-5xl mx-auto">
      <div className="mb-8 flex items-center justify-between">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">New Cloud Solution Design</h2>
           <p className="text-slate-500">Upload RFP to generate IDMC architecture recommendations.</p>
        </div>
        <div className="hidden md:flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-2 rounded-full text-xs font-bold border border-blue-100">
           <CloudLightning size={14} />
           CLOUD-NATIVE MODE ACTIVE
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Form Area */}
        <div className="lg:col-span-2">
          <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 md:p-8 h-full">
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Client Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="clientName"
                  required
                  value={formData.clientName}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none transition-all"
                  placeholder="e.g. Acme Corp"
                />
              </div>

              {/* RFP Upload Section */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Request for Proposal (RFP) File <span className="text-red-500">*</span>
                </label>
                <div 
                  className={`
                    border-2 border-dashed rounded-xl h-48 flex flex-col items-center justify-center p-6 text-center transition-colors relative overflow-hidden
                    ${isDragging ? 'border-orange-500 bg-orange-50' : 'border-slate-300 hover:border-orange-400 hover:bg-slate-50'}
                    ${isScanning ? 'bg-orange-50 border-orange-200' : ''}
                  `}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={handleFileDrop}
                >
                  {isScanning ? (
                    <div className="flex flex-col items-center animate-pulse">
                      <Loader className="w-10 h-10 text-orange-500 animate-spin mb-3" />
                      <p className="text-orange-700 font-medium">Scanning RFP Document...</p>
                      <p className="text-xs text-orange-500 mt-1">Converting On-Prem Reqs to Cloud Services...</p>
                    </div>
                  ) : formData.rfpName ? (
                    <div className="animate-fade-in w-full">
                      <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-3">
                        <CheckCircle size={24} />
                      </div>
                      <p className="font-medium text-slate-800 break-all">{formData.rfpName}</p>
                      <div className="flex justify-center gap-4 mt-2">
                        <button 
                          type="button"
                          onClick={() => {
                            setFormData(prev => ({...prev, rfpName: ''}));
                            setScanComplete(false);
                            setAiSuggestion(null);
                          }}
                          className="text-sm text-red-500 hover:underline"
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="w-12 h-12 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center mb-3">
                        <UploadCloud size={24} />
                      </div>
                      <p className="font-medium text-slate-700 mb-1">Upload RFP Document</p>
                      <p className="text-xs text-slate-400 mb-4">PDF, DOCX (Max 10MB)</p>
                      <input 
                        type="file" 
                        id="file-upload" 
                        className="hidden" 
                        onChange={handleFileSelect}
                      />
                      <label 
                        htmlFor="file-upload"
                        className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-50 cursor-pointer shadow-sm"
                      >
                        Browse Files
                      </label>
                    </>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Cloud Solution Type <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <select
                    name="solutionType"
                    required
                    value={formData.solutionType}
                    onChange={handleInputChange}
                    className={`
                      w-full px-4 py-3 rounded-lg border focus:ring-2 focus:border-transparent outline-none appearance-none bg-white transition-all
                      ${scanComplete && aiSuggestion && !formData.solutionType 
                        ? 'border-orange-300 ring-2 ring-orange-100' 
                        : 'border-slate-300 focus:ring-orange-500'}
                    `}
                  >
                    <option value="" disabled>Select IDMC Service...</option>
                    {solutionTypes.map(type => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                  <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
                    <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                  </div>
                </div>
              </div>

               <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Priority
                </label>
                <div className="flex gap-4">
                  {['Low', 'Normal', 'High'].map(p => (
                    <label key={p} className="flex items-center gap-2 cursor-pointer">
                      <input 
                        type="radio" 
                        name="priority" 
                        value={p}
                        checked={formData.priority === p}
                        onChange={handleInputChange}
                        className="text-orange-600 focus:ring-orange-500"
                      />
                      <span className="text-sm text-slate-700">{p}</span>
                    </label>
                  ))}
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-end gap-4 mt-8">
              <button 
                type="button"
                onClick={onCancel}
                className="px-6 py-2.5 rounded-lg border border-slate-300 text-slate-700 font-medium hover:bg-slate-50 transition-colors"
              >
                Cancel
              </button>
              <button 
                type="submit"
                disabled={!formData.clientName || !formData.solutionType}
                className={`
                  px-6 py-2.5 rounded-lg text-white font-medium shadow-sm transition-all
                  ${(!formData.clientName || !formData.solutionType) 
                    ? 'bg-slate-300 cursor-not-allowed' 
                    : 'bg-orange-600 hover:bg-orange-700 hover:shadow-md'}
                `}
              >
                Create Cloud Design
              </button>
            </div>
          </form>
        </div>

        {/* AI Suggestions Panel */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-900 text-white rounded-xl shadow-lg p-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <Sparkles size={100} />
            </div>

            <div className="flex items-center gap-2 mb-4">
              <Sparkles className="text-orange-400" size={20} />
              <h3 className="font-bold text-lg">CLAIRE AI (Cloud)</h3>
            </div>

            {!scanComplete && !isScanning && (
              <div className="text-slate-400 text-sm">
                <p className="mb-4">Upload an RFP to convert On-Prem requirements to IDMC Cloud Solutions.</p>
                <div className="flex flex-col gap-2">
                  <div className="bg-slate-800 p-3 rounded-lg flex items-center gap-3">
                    <RefreshCw size={16} className="text-blue-400" />
                    <span>Converts Legacy Logic</span>
                  </div>
                  <div className="bg-slate-800 p-3 rounded-lg flex items-center gap-3">
                    <CloudLightning size={16} className="text-emerald-400" />
                    <span>Maps to IDMC Services</span>
                  </div>
                </div>
              </div>
            )}

            {isScanning && (
              <div className="py-8 text-center">
                <div className="inline-block relative">
                   <div className="w-12 h-12 border-4 border-orange-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                </div>
                <p className="text-slate-300 font-medium">Scanning RFP...</p>
                <p className="text-xs text-slate-500 mt-2">Mapping requirements to Cloud Native Services</p>
              </div>
            )}

            {scanComplete && aiSuggestion && (
              <div className="animate-fade-in">
                <div className="mb-4">
                  <span className="text-xs font-bold text-orange-400 uppercase tracking-wider">Suggested Cloud Solution</span>
                  <h4 className="text-xl font-bold mt-1">{aiSuggestion.type}</h4>
                </div>

                <div className="bg-slate-800 rounded-lg p-4 mb-4 border border-slate-700">
                  <p className="text-sm text-slate-300 leading-relaxed">
                    {aiSuggestion.reason}
                  </p>
                </div>

                <div className="space-y-2 mb-6">
                  {aiSuggestion.details.map((detail, idx) => (
                    <div key={idx} className="flex items-start gap-2 text-xs text-slate-400">
                      <CheckCircle size={14} className="text-emerald-500 mt-0.5 shrink-0" />
                      <span>{detail}</span>
                    </div>
                  ))}
                </div>

                <button 
                  onClick={applySuggestion}
                  className="w-full bg-white text-slate-900 py-2.5 rounded-lg font-bold text-sm hover:bg-slate-100 transition-colors flex items-center justify-center gap-2"
                >
                  Apply Cloud Recommendation
                  <ArrowRight size={16} />
                </button>
              </div>
            )}
          </div>

          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
             <div className="flex items-center gap-2 mb-3 text-slate-800">
               <AlertCircle size={18} className="text-blue-500" />
               <h3 className="font-bold text-sm">Cloud Conversion Tips</h3>
             </div>
             <ul className="text-xs text-slate-500 space-y-2 list-disc pl-4">
