import { GoogleGenAI, Type, SchemaParams } from "@google/genai";
import { DesignData } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const architectureSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          label: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target'] },
          x: { type: Type.NUMBER, description: "X coordinate between 0 and 900" },
          y: { type: Type.NUMBER, description: "Y coordinate between 50 and 250" },
        },
        required: ['id', 'label', 'type', 'x', 'y'],
      },
    },
    edges: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          from: { type: Type.STRING },
          to: { type: Type.STRING },
          label: { type: Type.STRING },
        },
        required: ['from', 'to', 'label'],
      },
    },
  },
  required: ['nodes', 'edges'],
};

export const generateArchitectureDesign = async (
  context: string,
  solutionType: string
): Promise<DesignData> => {
  try {
    const model = 'gemini-2.5-flash';

    const prompt = `
      You are an expert Informatica Cloud Solution Architect.
      Create a High Level Design (HLD) diagram structure based on the following context and solution type.

      Solution Type: ${solutionType}
      Context/Requirements: ${context}

      Instructions:
      1. Define nodes (Source, Stage, Process, Target).
      2. Define edges connecting them.
      3. Assign X,Y coordinates for a canvas of width 1000px and height 300px.
         - Flow should generally go from Left (x=50) to Right (x=900).
         - Sources on left, Targets on right.
         - Processing logic in the middle.
         - Distribute Y coordinates to avoid overlap if there are parallel paths.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: architectureSchema,
        temperature: 0.2, // Low temperature for consistent structural output
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as DesignData;
    }
    throw new Error("No content generated");
  } catch (error) {
    console.error("Gemini generation error:", error);
    // Fallback if API fails or key is missing (for demo continuity)
    return {
      nodes: [
        { id: '1', label: 'Source System', type: 'source', x: 50, y: 100 },
        { id: '2', label: 'Cloud Ingress', type: 'stage', x: 250, y: 100 },
        { id: '3', label: 'Data Processing', type: 'process', x: 500, y: 100 },
        { id: '4', label: 'Target Warehouse', type: 'target', x: 800, y: 100 },
      ],
      edges: [
        { from: '1', to: '2', label: 'Secure Agent' },
        { from: '2', to: '3', label: 'Mapping' },
        { from: '3', to: '4', label: 'Load' },
      ],
    };
  }
};

