  CheckCircle, 
  ClipboardList, 
  Plus, 
  Sparkles, 
  PenTool, 
  Lightbulb, 
  ThumbsUp, 
  MessageSquare, 
  Send 
} from 'lucide-react';
import { RequestData, DesignData, Question, DesignCache } from '../types';
import ArchitectureCanvas from './ArchitectureCanvas';
import { generateArchitectureDesign } from '../services/geminiService';

interface SolutionDesignViewProps {
  request: RequestData | null;
  designCache: DesignCache;
  onUpdateDesignCache: (reqId: string, designData: DesignData) => void;
}

// Helper to simulate text extraction from mock files
const extractTextFromMock = (fileName: string) => {
  if (fileName.includes("AA Motors") || fileName.includes("HANA")) {
    return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer. Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta.";
  }
  if (fileName.includes("Vehicle") || fileName.includes("Adobe")) {
    return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM.";
  }
  if (fileName.includes("Reckitt")) {
    return "Client: Reckitt. Scope: MDM for Customer & Product. Survivorship: Trust scores defined. Workflow: 2-step approval. Source: 35 different sources (Excel, Flatfiles). Volume: 16K Customers.";
  }
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB. Target: Cloud Data Warehouse. Pattern: Batch ETL.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState<'design' | 'scoping'>('design');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [refinementPrompt, setRefinementPrompt] = useState("");
  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });

  useEffect(() => {
    if (request && designCache[request.id]) {
      setCurrentDesign(designCache[request.id]);
      setStatus('accepted');
    } else {
      setStatus('idle');
      setCurrentDesign({ nodes: [], edges: [] });
    }
  }, [request, designCache]);

  // Questions initialization
  useEffect(() => {
    if (request && questions.length === 0) {
      const infrastructureQuestions = [
        { id: 'INF-01', category: "Infrastructure", question: "Which OS environment will host the Secure Agent (Linux RHEL/CentOS or Windows Server)?", answer: "" },
        { id: 'ADM-01', category: "Admin", question: "Do you have an existing Informatica Org ID?", answer: "" },
      ];

      let extraQuestions: Question[] = [];
      if (request.type.includes("Quality") || request.type.includes("CDQ")) {
        extraQuestions = [
          { id: 'GEM-01', category: "Gemini Suggestions", question: "How many Critical Data Elements (CDEs) require active monitoring?", answer: "" },
          { id: 'GEM-02', category: "Gemini Suggestions", question: "Do we need to perform both Data Profiling (structure) and Column Profiling (content)?", answer: "" },
        ];
      }
      setQuestions([...infrastructureQuestions, ...extraQuestions]);
    }
  }, [request, questions.length]);

  const handleGenerate = async (promptOverride: string | null = null) => {
    if (!request) return;
    setStatus('thinking');
    setThoughts([]);

    // 1. Simulate "Thinking" steps
    const baseThoughts = [
      `Analyzing context: ${request.clientName} requirements...`,
      "Identifying constraints and patterns...",
      promptOverride ? `Applying refinement: "${promptOverride}"` : "Synthesizing initial design...",
      "Generating IDMC topology..."
    ];

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 800)); // Delay for UX
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    // 2. Real Gemini Call
    const context = extractTextFromMock(request.rfpFile) + (promptOverride ? ` Refinement: ${promptOverride}` : "");
    const newDesign = await generateArchitectureDesign(context, request.type);

    setCurrentDesign(newDesign);
    setStatus('review');
  };

  const handleAcceptDesign = () => {
    if (request) {
      onUpdateDesignCache(request.id, currentDesign);
      setStatus('accepted');
    }
  };

  const handleAddQuestion = () => {
    setQuestions([...questions, { id: `CUST-${Date.now()}`, category: "Custom", question: "", answer: "", isCustom: true }]);
  };

  const handleDeleteQuestion = (id: string) => setQuestions(questions.filter(q => q.id !== id));

  const handleQuestionChange = (id: string, field: 'question' | 'answer', value: string) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, [field]: value } : q));
  };

  if (!request) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-slate-400">
        <PenTool size={48} className="mb-4 text-slate-200" />
        <p className="text-lg font-medium">No Request Selected</p>
        <p className="text-sm">Please select a Request ID from the Dashboard to view the design.</p>
      </div>
    );
  }

  const artifacts = [
      { item: "Secure Agent Group", category: "Infrastructure", desc: "Provision Secure Agent Group (Linux/Windows). Ensure connectivity to Informatica Cloud (port 443)." },
      { item: "Source/Target Connections", category: "Connectivity", desc: "Configure connectors in Administrator for all in-scope systems." },
  ];

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-fade-in">
      {/* Design Header */}
      <div className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between">
        <div>
          <div className="flex items-center gap-3 mb-1">
            <h2 className="text-xl font-bold text-slate-800">{request.id}: {request.clientName}</h2>
            <span className="px-2 py-0.5 rounded text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">
              {request.type}
            </span>
          </div>
          <p className="text-xs text-slate-500">High Level Design (HLD) & Technical Specs</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => setActiveSubTab('design')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeSubTab === 'design' ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            Architecture Canvas
          </button>
          <button 
            onClick={() => setActiveSubTab('scoping')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeSubTab === 'scoping' ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            Scoping & Requirements
          </button>
        </div>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {activeSubTab === 'scoping' ? (
          <div className="max-w-6xl mx-auto space-y-8 animate-fade-in">
            {/* Artifacts */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                    <List className="text-blue-500" size={20} />
                    Required Artifacts & Prerequisites
                  </h3>
                  <button className="text-xs text-blue-600 hover:underline font-medium flex items-center gap-1">
                    <Download size={14} /> Download Spec Sheet
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {artifacts.map((req, i) => (
                    <div key={i} className="flex items-start gap-4 p-4 rounded-lg bg-slate-50 border border-slate-100 hover:border-blue-200 transition-colors group">
                      <div className="mt-1">
                        {req.category.includes('Job') || req.category.includes('Mapping') ? (
                          <Workflow size={18} className="text-orange-500" />
                        ) : req.category.includes('Infrastructure') ? (
                          <Server size={18} className="text-slate-500" />
                        ) : (
                          <CheckCircle size={18} className="text-emerald-500" />
                        )}
                      </div>
                      <div className="flex-1">
                        <div className="flex justify-between items-start">
                           <h4 className="font-semibold text-slate-800 text-sm group-hover:text-blue-700 transition-colors">{req.item}</h4>
                           <span className="text-[10px] uppercase font-bold text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-200">{req.category}</span>
                        </div>
                        <p className="text-sm text-slate-500 mt-1">{req.desc}</p>
                      </div>
                    </div>
                  ))}
                </div>
            </div>

            {/* Questionnaire */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="p-6 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                  <div>
                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                      <ClipboardList className="text-orange-500" size={20} />
                      Scoping Questionnaire
                    </h3>
                  </div>
                  <div className="flex gap-3">
                    <button onClick={handleAddQuestion} className="flex items-center gap-2 px-4 py-2 bg-orange-50 border border-orange-200 text-orange-700 rounded-lg text-sm font-medium hover:bg-orange-100 shadow-sm">
                      <Plus size={16} /> Add Question
                    </button>
                  </div>
               </div>
               <div className="p-6">
                 <div className="space-y-8">
                   {questions.some(q => q.category === 'Gemini Suggestions') && (
                      <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                        <h4 className="font-bold text-purple-700 mb-4 pb-2 flex items-center gap-2">
                           <Sparkles size={16} /> Gemini Suggestions
                        </h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                           {questions.filter(q => q.category === 'Gemini Suggestions').map((q, i) => (
                              <div key={q.id} className="animate-fade-in-up" style={{animationDelay: `${i*0.1}s`}}>
                                <label className="block text-sm font-semibold text-slate-800 mb-2">{q.question}</label>
                                <textarea className="w-full p-3 border border-purple-200 rounded-lg text-sm focus:ring-2 focus:ring-purple-500 outline-none bg-white" rows={2} placeholder="Response..." />
                              </div>
                           ))}
                        </div>
                      </div>
                   )}

                   {['Infrastructure', 'Admin', 'Custom'].map(cat => {
                      const catQuestions = questions.filter(q => q.category === cat);
                      if (catQuestions.length === 0) return null;
                      return (
                        <div key={cat}>
                          <h4 className="font-bold text-slate-700 mb-4 border-b border-slate-100 pb-2">{cat}</h4>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             {catQuestions.map((q) => (
                                <div key={q.id}>
                                  {q.isCustom ? (
                                     <div className="mb-2">
                                       <input 
                                         type="text" 
                                         className="w-full bg-transparent font-semibold text-slate-800 border-b border-orange-200 focus:border-orange-500 outline-none placeholder-slate-400 text-sm pb-1"
                                         value={q.question}
                                         onChange={(e) => handleQuestionChange(q.id, 'question', e.target.value)}
                                       />
                                     </div>
                                  ) : (
                                     <label className="block text-sm font-semibold text-slate-800 mb-2">{q.question}</label>
                                  )}
                                  <textarea 
                                    className="w-full p-3 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none bg-slate-50" 
                                    rows={2} 
                                    placeholder="Response..."
                                    value={q.answer}
                                    onChange={(e) => handleQuestionChange(q.id, 'answer', e.target.value)}
                                  />
                                  {q.isCustom && <button onClick={() => handleDeleteQuestion(q.id)} className="text-red-500 text-xs mt-1 hover:underline">Remove</button>}
                                </div>
                             ))}
                          </div>
                        </div>
                      );
                   })}
                 </div>
               </div>
            </div>
          </div>
        ) : (
          <div className="h-full flex flex-col">
            {status === 'idle' ? (
              <div className="flex-1 flex flex-col items-center justify-center gap-8 animate-fade-in">
                <div className="text-center max-w-lg">
                   <h3 className="text-2xl font-bold text-slate-800 mb-2">Architectural Blueprint</h3>
                   <p className="text-slate-500">Generate a high-level design based on the logic extracted from uploaded RFP documents.</p>
                </div>
                <button 
                  onClick={() => handleGenerate()}
                  className="group relative w-72 p-8 bg-white border-2 border-orange-100 rounded-xl hover:border-orange-500 hover:shadow-lg transition-all text-left"
                >
                  <div className="mb-4 bg-orange-50 w-12 h-12 rounded-lg flex items-center justify-center text-orange-600 group-hover:bg-orange-600 group-hover:text-white transition-colors">
                    <Sparkles size={24} />
                  </div>
                  <h4 className="font-bold text-slate-800 mb-1">Generate HLD (AI)</h4>
                  <p className="text-xs text-slate-500">Auto-builds diagram based on RFP.</p>
                </button>
              </div>
            ) : status === 'review' ? (
               <div className="flex flex-col h-full animate-fade-in">
                  <div className="bg-orange-50 border-b border-orange-200 p-4 flex items-center justify-between">
                     <div className="flex items-center gap-3">
                        <div className="bg-orange-100 p-2 rounded-full text-orange-600">
                           <Lightbulb size={20} />
                        </div>
                        <div>
                           <h4 className="font-bold text-orange-900">Design Verification</h4>
                           <p className="text-xs text-orange-700">Gemini has generated a design based on your requirements. Is this correct?</p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button 
                           onClick={handleAcceptDesign}
                           className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-sm transition-colors"
                        >
                           <ThumbsUp size={16} /> Accept Design
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative">
                     <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={false} thoughts={[]} />

                     {/* Floating Refinement Box */}
                     <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-xl bg-white shadow-xl rounded-full border border-slate-200 p-1 pl-4 flex items-center gap-2">
                        <MessageSquare size={18} className="text-slate-400" />
                        <input 
                           type="text" 
                           placeholder="No, refine the design (e.g., 'Add a Staging layer before MDM')"
                           className="flex-1 bg-transparent outline-none text-sm py-3 text-slate-700"
                           value={refinementPrompt}
                           onChange={(e) => setRefinementPrompt(e.target.value)}
                           onKeyDown={(e) => e.key === 'Enter' && handleGenerate(refinementPrompt)}
                        />
                        <button 
                           onClick={() => handleGenerate(refinementPrompt)}
                           className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-full transition-colors"
                        >
                           <Send size={16} />
                        </button>
                     </div>
                  </div>
               </div>
            ) : (
              // Status: thinking or accepted
              <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex overflow-hidden flex-col">
                <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={status === 'thinking'} thoughts={thoughts} />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SolutionDesignView;

