import { GoogleGenAI, Type, SchemaParams } from "@google/genai";
import { DesignData, Question, Requirement } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- KNOWLEDGE BASE FROM PDF ---
const INFORMATICA_KB = `
CONTEXT: Informatica Cloud Data Integration (CDI) & IDMC Platform.
KEY CONCEPTS:
- Secure Agent: Lightweight program to run tasks. Needs 443 outbound.
- Assets: Mappings, Taskflows, Synchronization, Replication, Mass Ingestion.
- Connectors: Salesforce, Snowflake, SAP HANA, Oracle, ADLS Gen2.
- Services: CDQ (Data Quality), CDGC (Governance), MDM SaaS (360), CAI (App Integration).
- Architecture Patterns:
  - ETL/ELT: Source -> Mapping -> Target.
  - MDM: Landing -> Staging -> Ingress -> Match/Merge -> Egress.
  - Quality: Profiling -> Scorecards -> Standardization -> Exception Mgmt.
GOVERNANCE SPECIFICS:
- Classification, Data Access Management, Consent Management are critical for MDM/Governance.
`;

const architectureSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          label: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target'] },
          x: { type: Type.NUMBER, description: "X coordinate (0-900)" },
          y: { type: Type.NUMBER, description: "Y coordinate (50-250)" },
        },
        required: ['id', 'label', 'type', 'x', 'y'],
      },
    },
    edges: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          from: { type: Type.STRING },
          to: { type: Type.STRING },
          label: { type: Type.STRING },
        },
        required: ['from', 'to', 'label'],
      },
    },
  },
  required: ['nodes', 'edges'],
};

const questionnaireSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    questions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING },
          question: { type: Type.STRING },
          answer: { type: Type.STRING },
        },
        required: ['id', 'category', 'question', 'answer'],
      },
    },
  },
  required: ['questions'],
};

const requirementsSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    requirements: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Infrastructure', 'Network', 'Security', 'License', 'Development'] },
          item: { type: Type.STRING },
          description: { type: Type.STRING },
          criticality: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
        },
        required: ['id', 'category', 'item', 'description', 'criticality'],
      },
    },
  },
  required: ['requirements'],
};

export const generateArchitectureDesign = async (
  context: string,
  solutionType: string
): Promise<DesignData> => {
  try {
    const model = 'gemini-3-pro-preview'; // Using 3 Pro for complex reasoning

    const prompt = `
      Act as an Informatica Cloud Solution Architect.
      Create a High Level Design (HLD) diagram structure.

      Knowledge Base: ${INFORMATICA_KB}
      Solution Type: ${solutionType}
      RFP/Context: ${context}

      Task:
      1. Analyze the RFP for key entities (Sources, Targets, Logic).
      2. If MDM/Governance is detected, include Consent/Classification logic if implied.
      3. Generate Nodes and Edges for the flow.
      4. Layout: Sources Left (x~50), Targets Right (x~900).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: architectureSchema,
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as DesignData;
    }
    throw new Error("No design generated");
  } catch (error) {
    console.error("Gemini design error:", error);
    return { nodes: [], edges: [] };
  }
};

export const generateIntelligentQuestionnaire = async (
  context: string,
  solutionType: string
): Promise<Question[]> => {
  try {
    const model = 'gemini-3-pro-preview';

    const prompt = `
      Act as an Informatica Presales Architect. 
      Generate a technical scoping questionnaire based on the Solution Type and RFP Context.

      Solution Type: ${solutionType}
      RFP Context: ${context}
      Knowledge Base: ${INFORMATICA_KB}

      Instructions:
      1. Generate 5-8 specific questions that clarify the requirements.
      2. If MDM is involved, ask about Match Rules, Survivorship, Consent.
      3. If CDQ is involved, ask about Dictionaries, Rule Specifications.
      4. If Infrastructure is vague, ask about Secure Agent OS, Firewall.
      5. Leave 'answer' empty string.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionnaireSchema,
      },
