// Helper to simulate text extraction from mock files - Extended for improved context
const extractTextFromMock = (fileName: string) => {
  if (fileName.includes("AA Motors") || fileName.includes("HANA")) {
    return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer (B2C). Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta. Needs Consent Management for GDPR compliance and Data Access management for regional sales teams.";
  }
  if (fileName.includes("Vehicle") || fileName.includes("Adobe")) {
    return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM. Volume: High frequency micro-batches.";
  }
  if (fileName.includes("Reckitt")) {
    return "Client: Reckitt. Scope: MDM for Customer & Product. Survivorship: Trust scores defined. Workflow: 2-step approval. Source: 35 different sources (Excel, Flatfiles). Volume: 16K Customers. Classification of PII data is required.";
  }
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB (Oracle). Target: Cloud Data Warehouse (Snowflake). Pattern: Batch ETL. Security: End-to-end encryption required.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState<'design' | 'requirements' | 'scoping'>('design');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);

  // Design Data
  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [questions, setQuestions] = useState<Question[]>([]);
  const [requirements, setRequirements] = useState<Requirement[]>([]);

  const [refinementPrompt, setRefinementPrompt] = useState("");

  // Load from cache or reset
  useEffect(() => {
    if (request) {
      if (designCache[request.id]) {
        const cached = designCache[request.id];
        setCurrentDesign(cached.design);
        setQuestions(cached.questions);
        setRequirements(cached.requirements);
        setStatus(cached.status);
      } else {
        setStatus('idle');
        setCurrentDesign({ nodes: [], edges: [] });
        setQuestions([]);
        setRequirements([]);
      }
    }
  }, [request, designCache]);

  const handleGenerate = async (promptOverride: string | null = null) => {
    if (!request) return;
    setStatus('thinking');
    setThoughts([]);

    // 1. Thinking Steps
    const baseThoughts = [
      `Reading RFP: ${request.rfpFile}...`,
      `Context: ${request.clientName} - ${request.type}`,
      "Analyzing MDM & Governance patterns...",
      promptOverride ? `Applying modification: "${promptOverride}"` : "Consulting Informatica Knowledge Base...",
      "Drafting HLD Architecture & Scoping..."
    ];

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 600)); 
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    const context = extractTextFromMock(request.rfpFile) + (promptOverride ? ` Refinement: ${promptOverride}` : "");

    // 2. Parallel Generation using Gemini 3 Pro
    try {
      const [design, generatedQuestions, generatedRequirements] = await Promise.all([
        generateArchitectureDesign(context, request.type),
        generateIntelligentQuestionnaire(context, request.type),
        generateProjectRequirements(context, request.type)
      ]);

      setCurrentDesign(design);

      // Merge new questions/reqs only if it's a fresh run, otherwise preserve user edits could be better but let's overwrite for "Regenerate"
      setQuestions(generatedQuestions);
      setRequirements(generatedRequirements);

      setStatus('review');
    } catch (e) {
      console.error("Generation failed", e);
      setStatus('idle');
    }
