interface CreateFormProps {
  onSubmit: (data: any) => void;
  onCancel: () => void;
}

const CreateForm: React.FC<CreateFormProps> = ({ onSubmit, onCancel }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpName: '',
    solutionType: '',
    description: '',
    priority: 'Normal'
  });
  const [isDragging, setIsDragging] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [scanComplete, setScanComplete] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiSuggestion | null>(null);

  const solutionTypes = [
    "Cloud Data Governance & Catalog (CDGC)",
    "Cloud Data Quality (CDQ)",
    "Cloud Data Integration (CDI)",
    "MDM SaaS (Customer/Product 360)",
    "Cloud Mass Ingestion (CMI)",
    "Cloud Application Integration (CAI)",
    "Reference 360 SaaS",
    "Data Marketplace"
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const processFile = (file: File) => {
    setFormData(prev => ({ ...prev, rfpName: file.name }));
    setIsScanning(true);
    setScanComplete(false);
    setAiSuggestion(null);

    // Simulate AI Analysis to determine solution type from filename/content
    setTimeout(() => {
      setIsScanning(false);
      setScanComplete(true);

      const fileName = file.name.toLowerCase();
      let suggestion: AiSuggestion | null = null;

      if (fileName.includes('aa motors') || fileName.includes('hana')) {
         suggestion = {
          type: "MDM SaaS (Customer/Product 360)",
          reason: "Detected 'AA Motors' MDM Pattern.",
          details: [
            "Source: SAP HANA identified.",
            "Requirement: Match & Merge logic.",
            "Artifacts identified: job_ingress, job_egress."
          ]
        };
      } else if (fileName.includes('vehicle') || fileName.includes('adobe')) {
         suggestion = {
          type: "Cloud Data Integration (CDI)",
          reason: "Detected Integration/Synchronization Pattern.",
          details: [
            "Source: Adobe/Vehicle Data.",
            "Target: Salesforce.",
            "Requirement: Error Handling via Blob Storage."
          ]
        };
      } else if (fileName.includes('reckitt')) {
        suggestion = {
          type: "MDM SaaS (Customer/Product 360)",
          reason: "Detected 'Reckitt' MDM/Governance Pattern.",
          details: [
            "Requirement: PII Classification.",
            "Requirement: Trust Scores & Survivorship.",
            "Source: Multiple Flatfiles."
          ]
        };
      } else {
        suggestion = {
          type: "Cloud Data Integration (CDI)",
          reason: "Standard Data Integration Pattern detected.",
          details: [
            "Converted general ETL requirements to Cloud Data Integration.",
            "Assumed modernization to IDMC platform."
          ]
        };
      }
      setAiSuggestion(suggestion);
    }, 2500); 
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const applySuggestion = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      clientName: formData.clientName,
      type: formData.solutionType,
      rfpFile: formData.rfpName,
      date: new Date().toLocaleDateString(),
    });
