  return (
    <div className="p-6 md:p-8 max-w-5xl mx-auto animate-fade-in">
      <div className="mb-8 flex items-center justify-between">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">New Cloud Solution Design</h2>
           <p className="text-slate-500">Upload RFP to generate IDMC architecture recommendations.</p>
        </div>
        <div className="hidden md:flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-2 rounded-full text-xs font-bold border border-blue-100">
           <CloudLightning size={14} />
