                    ${isDragging ? 'border-orange-500 bg-orange-50' : 'border-slate-300 hover:border-orange-400 hover:bg-slate-50'}
                    ${isScanning ? 'bg-orange-50 border-orange-200' : ''}
                  `}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={handleFileDrop}
                >
                  {isScanning ? (
                    <div className="flex flex-col items-center animate-pulse">
                      <Loader className="w-10 h-10 text-orange-500 animate-spin mb-3" />
                      <p className="text-orange-700 font-medium">Scanning RFP Document...</p>
                      <p className="text-xs text-orange-500 mt-1">Converting On-Prem Reqs to Cloud Services...</p>
