} from 'lucide-react';
import { Node, Edge } from '../types';

interface ArchitectureCanvasProps {
  aiNodes: Node[];
  aiEdges: Edge[];
  isThinking: boolean;
  thoughts: string[];
}

const ArchitectureCanvas: React.FC<ArchitectureCanvasProps> = ({ aiNodes, aiEdges, isThinking, thoughts }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [showMermaid, setShowMermaid] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Generate Mermaid Code
  const getMermaidCode = () => {
    if (!aiNodes.length) return "graph LR\n  NoData[No Design Generated]";

    let code = "graph LR\n";
    // Define styles
    code += "  classDef source fill:#eff6ff,stroke:#3b82f6,stroke-width:2px,color:#1e40af;\n";
    code += "  classDef stage fill:#f1f5f9,stroke:#64748b,stroke-width:2px,color:#334155;\n";
    code += "  classDef process fill:#fff7ed,stroke:#f97316,stroke-width:2px,color:#9a3412;\n";
    code += "  classDef target fill:#ecfdf5,stroke:#10b981,stroke-width:2px,color:#065f46;\n\n";

    aiNodes.forEach(node => {
      // Escape label quotes
      const label = node.label.replace(/"/g, "'");
      code += `  ${node.id}["${label}"]:::${node.type}\n`;
    });

    code += "\n";

    aiEdges.forEach(edge => {
      const label = edge.label ? `|"${edge.label}"|` : "";
      code += `  ${edge.from} -->${label} ${edge.to}\n`;
    });

    return code;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getMermaidCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Export Logic
  const handleExport = (format: 'svg' | 'png') => {
    if (!svgRef.current) return;

    const svgEl = svgRef.current;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svgEl);

    // Add XML namespaces
    if(!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)){
        source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if(!source.match(/^<svg[^>]+xmlns:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)){
        source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }

    // Add webfont for foreignObject if needed (simplified here to just prepending preamble)
    source = '<?xml version="1.0" standalone="no"?>\r\n' + source;

    if (format === 'svg') {
        const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
        const link = document.createElement("a");
        link.href = url;
        link.download = "architecture-design.svg";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        const img = new Image();
        img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
        img.onload = () => {
            const canvas = document.createElement("canvas");
            // Set canvas dimensions based on SVG viewbox
            canvas.width = 1000; 
            canvas.height = 300;
            const ctx = canvas.getContext("2d");
            if (ctx) {
                // White background for PNG
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                const pngUrl = canvas.toDataURL("image/png");
                const link = document.createElement("a");
                link.href = pngUrl;
                link.download = "architecture-design.png";
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        };
    }
    setShowExportMenu(false);
  };

  return (
    <div className="flex flex-col h-full relative group">
      {/* Header Toolbar */}
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center z-20">
        <div>
          <h3 className="font-bold text-slate-800">High Level Design (HLD)</h3>
          <p className="text-xs text-slate-500 hidden sm:block">
            {isThinking ? "Gemini is analyzing requirements..." : "Generated based on RFP Context & Gemini Patterns"}
          </p>
        </div>

        <div className="flex items-center gap-2 relative">
          {/* Export Dropdown */}
          <div className="relative">
             <button 
                onClick={() => setShowExportMenu(!showExportMenu)}
                className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50 transition-colors"
             >
                <Share2 size={14} /> 
                <span className="hidden sm:inline">Export</span>
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-1 w-32 bg-white rounded-lg shadow-xl border border-slate-200 py-1 z-30">
                   <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2">
                      <ImageIcon size={14} /> PNG Image
                   </button>
                   <button onClick={() => handleExport('svg')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2">
                      <FileCode size={14} /> SVG Vector
                   </button>
                </div>
             )}
          </div>

          <button 
             onClick={() => setShowMermaid(true)}
             className="flex items-center gap-2 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700 transition-colors"
          >
            <Code size={14} /> 
            <span className="hidden sm:inline">Mermaid</span>
          </button>
        </div>
      </div>

      {/* Canvas Area */}
      <div className="flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">
        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/95 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm transition-opacity duration-300">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse">
                      <BrainCircuit className="text-white" size={24} />
                   </div>
                   <div>
                      <h4 className="font-bold text-slate-800 text-lg">Gemini Thinking...</h4>
                      <p className="text-xs text-slate-500">Model: gemini-3-pro-preview</p>
                   </div>
                </div>
                <div className="space-y-3 font-mono text-xs max-h-60 overflow-y-auto">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.3}s`}}>
                         <CheckCircle size={14} className="text-emerald-500 flex-shrink-0" />
                         <span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200 shadow-sm">{thought}</span>
                      </div>
                   ))}
                   <div className="flex items-center gap-3 mt-4">
                      <Loader size={14} className="text-blue-500 animate-spin flex-shrink-0" />
                      <span className="text-blue-500 font-bold">Synthesizing Architecture...</span>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* The SVG Canvas */}
        <svg 
            ref={svgRef} 
            width="100%" 
            height="100%" 
            viewBox="0 0 1000 300" 
            className="w-full h-full select-none"
            preserveAspectRatio="xMidYMid meet"
        >
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>

          {/* Background for export (ensure white bg) */}
          <rect x="0" y="0" width="1000" height="300" fill="#ffffff" />

          {/* Edges */}
          {aiEdges && aiEdges.map((edge, i) => {
            const source = aiNodes.find(n => n.id === edge.from);
            const target = aiNodes.find(n => n.id === edge.to);
            if (!source || !target) return null;

            // Refined Curve Logic (Right of Source -> Left of Target)
            const sourceX = source.x + 160; // 160 is width
            const sourceY = source.y + 40;  // 40 is half height
            const targetX = target.x;
            const targetY = target.y + 40;

            const controlPointOffset = 60;

            return (
              <g key={i} className="animate-fade-in" style={{animationDelay: '0.5s'}}>
                <path 
                  d={`M ${sourceX} ${sourceY} C ${sourceX + controlPointOffset} ${sourceY}, ${targetX - controlPointOffset} ${targetY}, ${targetX} ${targetY}`} 
                  stroke="#cbd5e1" 
                  strokeWidth="2" 
                  fill="none" 
                  markerEnd="url(#arrowhead)"
                />
                {/* Edge Label Background & Text */}
                <rect 
                    x={(sourceX + targetX)/2 - 40} 
                    y={(sourceY + targetY)/2 - 10} 
                    width="80" 
                    height="20" 
                    rx="4" 
                    fill="white" 
                    stroke="#e2e8f0" 
                    strokeWidth="1"
                />
                <text 
                    x={(sourceX + targetX)/2} 
                    y={(sourceY + targetY)/2 + 4} 
                    textAnchor="middle" 
                    fontSize="10" 
                    fill="#64748b" 
                    fontWeight="600"
                    style={{ fontFamily: 'Inter, sans-serif' }}
                >
                    {edge.label}
                </text>
              </g>
            );
          })}

          {/* Nodes */}
          {aiNodes && aiNodes.map((node, i) => {
             // ForeignObject can be glitchy in exports. We use it for display, but for export we might need to inline styles carefully.
             return (
               <foreignObject 
                 x={node.x} 
                 y={node.y} 
                 width="160" 
                 height="80" 
                 key={node.id} 
                 className="animate-fade-in-up overflow-visible" 
                 style={{animationDelay: `${i * 0.1}s`}}
               >
                 <div className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white
                    ${node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                      node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                      node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                      'bg-white border-slate-300'}`}>
                    <div className="mb-1">
                      {node.type === 'source' && <Database size={20} className="text-blue-600" />}
                      {node.type === 'stage' && <Server size={20} className="text-slate-600" />}
                      {node.type === 'process' && <Settings size={20} className="text-orange-600 animate-spin-slow" />}
                      {node.type === 'target' && <CloudLightning size={20} className="text-emerald-600" />}
                    </div>
                    <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">
                        {node.label}
                    </span>
                 </div>
               </foreignObject>
             );
          })}
        </svg>
      </div>

      {/* Mermaid Code Modal */}
      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
               <h3 className="font-bold text-slate-800 flex items-center gap-2">
                 <Code size={18} className="text-blue-600" />
                 Mermaid.js Diagram Code
               </h3>
               <button onClick={() => setShowMermaid(false)} className="text-slate-400 hover:text-slate-700 transition-colors">
                 <X size={20} />
               </button>
            </div>
            <div className="flex-1 p-0 overflow-hidden relative group/code">
               <pre className="w-full h-full p-6 bg-slate-900 text-blue-100 font-mono text-xs overflow-auto">
                 {getMermaidCode()}
               </pre>
               <button 
                  onClick={copyToClipboard}
                  className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg backdrop-blur-md transition-all border border-white/10"
               >
                  {copied ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}
               </button>
            </div>
            <div className="p-4 border-t border-slate-200 flex justify-end gap-2 bg-slate-50">
               <button onClick={() => setShowMermaid(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition-colors">
                 Close
               </button>
               <button 
                 onClick={copyToClipboard} 
                 className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors flex items-center gap-2"
               >
                 {copied ? 'Copied!' : 'Copy Code'}
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ArchitectureCanvas;

import { GoogleGenAI, Type, SchemaParams } from "@google/genai";
import { DesignData, Question, Requirement } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- KNOWLEDGE BASE FROM PDF ---
const INFORMATICA_KB = `
CONTEXT: Informatica Cloud Data Integration (CDI) & IDMC Platform.
KEY CONCEPTS:
- Secure Agent: Lightweight program to run tasks. Needs 443 outbound.
- Assets: Mappings, Taskflows, Synchronization, Replication, Mass Ingestion.
- Connectors: Salesforce, Snowflake, SAP HANA, Oracle, ADLS Gen2.
- Services: CDQ (Data Quality), CDGC (Governance), MDM SaaS (360), CAI (App Integration).
- Architecture Patterns:
  - ETL/ELT: Source -> Mapping -> Target.
  - MDM: Landing -> Staging -> Ingress -> Match/Merge -> Egress.
  - Quality: Profiling -> Scorecards -> Standardization -> Exception Mgmt.
GOVERNANCE SPECIFICS:
- Classification, Data Access Management, Consent Management are critical for MDM/Governance.
`;

const architectureSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          label: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target'] },
          x: { type: Type.NUMBER, description: "X coordinate (0-900)" },
          y: { type: Type.NUMBER, description: "Y coordinate (50-250)" },
        },
        required: ['id', 'label', 'type', 'x', 'y'],
      },
    },
    edges: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          from: { type: Type.STRING },
          to: { type: Type.STRING },
          label: { type: Type.STRING },
        },
        required: ['from', 'to', 'label'],
      },
    },
  },
  required: ['nodes', 'edges'],
};

const questionnaireSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    questions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING },
          question: { type: Type.STRING },
          answer: { type: Type.STRING },
        },
        required: ['id', 'category', 'question', 'answer'],
      },
    },
  },
  required: ['questions'],
};

const requirementsSchema: SchemaParams = {
  type: Type.OBJECT,
  properties: {
    requirements: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Infrastructure', 'Network', 'Security', 'License', 'Development'] },
          item: { type: Type.STRING },
          description: { type: Type.STRING },
          criticality: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
        },
        required: ['id', 'category', 'item', 'description', 'criticality'],
      },
    },
  },
  required: ['requirements'],
};

export const generateArchitectureDesign = async (
  context: string,
  solutionType: string
): Promise<DesignData> => {
  try {
    const model = 'gemini-3-pro-preview'; // Using 3 Pro for complex reasoning

    const prompt = `
      Act as an Informatica Cloud Solution Architect.
      Create a High Level Design (HLD) diagram structure.

      Knowledge Base: ${INFORMATICA_KB}
      Solution Type: ${solutionType}
      RFP/Context: ${context}

      Task:
      1. Analyze the RFP for key entities (Sources, Targets, Logic).
      2. If MDM/Governance is detected, include Consent/Classification logic if implied.
      3. Generate Nodes and Edges for the flow.
      4. Layout: Sources Left (x~50), Targets Right (x~900).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: architectureSchema,
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as DesignData;
    }
    throw new Error("No design generated");
  } catch (error) {
    console.error("Gemini design error:", error);
    return { nodes: [], edges: [] };
  }
};

export const generateIntelligentQuestionnaire = async (
  context: string,
