  const getCriticalityColor = (level: string) => {
    switch(level) {
      case 'High': return 'bg-red-100 text-red-700 border-red-200';
      case 'Medium': return 'bg-orange-100 text-orange-700 border-orange-200';
      case 'Low': return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const getRequirementIcon = (cat: string) => {
    switch(cat) {
      case 'Infrastructure': return <Server size={18} />;
      case 'Network': return <Network size={18} />;
      case 'Security': return <ShieldCheck size={18} />;
      case 'License': return <Key size={18} />;
      default: return <CheckCircle size={18} />;
    }
  };

  // Helper to check for high priority keywords
  const isHighPriorityQuestion = (text: string) => {
    const lower = text.toLowerCase();
    return lower.includes('consent') || lower.includes('gdpr') || lower.includes('privacy') || lower.includes('pii');
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-fade-in">
