          >
            Blueprint
          </button>
           <button 
            onClick={() => setActiveSubTab('requirements')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeSubTab === 'requirements' ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            Requirements
          </button>
          <button 
            onClick={() => setActiveSubTab('scoping')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeSubTab === 'scoping' ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            Scoping
          </button>
