                      </h3>
                      <p className="text-xs text-slate-500 mt-1">Generated based on {request.type} and RFP analysis.</p>
                    </div>
                    <button className="text-xs text-blue-600 hover:underline font-medium flex items-center gap-1">
                      <Download size={14} /> Download Checklist
                    </button>
                 </div>

                 {requirements.length === 0 ? (
                    <div className="text-center py-12 text-slate-400">
                       <p>No requirements generated yet. Please generate the design first.</p>
                       <button onClick={() => setActiveSubTab('design')} className="mt-4 text-orange-600 underline">Go to Blueprint</button>
                    </div>
                 ) : (
                    <div className="grid grid-cols-1 gap-4">
                      {requirements.map((req, i) => (
