                           <ThumbsUp size={16} /> Accept & Save
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative">
                     <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={false} thoughts={[]} />

                     {/* Floating Refinement Box */}
