                           onKeyDown={(e) => {
                             if(e.key === 'Enter') {
                               handleGenerate((e.target as HTMLInputElement).value);
                               (e.target as HTMLInputElement).value = '';
                             }
                           }}
                        />
                     </div>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

