const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- SIMULATED IN-MEMORY VECTOR STORE / KNOWLEDGE BASE ---
// In a real app, this would be a vector DB. Here we append learned patterns.
let LEARNED_PATTERNS: string[] = [
  "Pattern: For SAP HANA sources, always use Mass Ingestion for initial load.",
  "Pattern: GDPR requests require a Masking transformation in the pipeline."
];

// --- KNOWLEDGE BASE FROM PDF ---
const INFORMATICA_KB = `
CONTEXT: Informatica Cloud Data Integration (CDI) & IDMC Platform.
KEY CONCEPTS:
- Secure Agent: Lightweight program to run tasks. Needs 443 outbound.
- Assets: Mappings, Taskflows, Synchronization, Replication, Mass Ingestion.
- Connectors: Salesforce, Snowflake, SAP HANA, Oracle, ADLS Gen2.
- Services: CDQ (Data Quality), CDGC (Governance), MDM SaaS (360), CAI (App Integration).
- Architecture Patterns:
  - ETL/ELT: Source -> Mapping -> Target.
  - MDM: Landing -> Staging -> Ingress -> Match/Merge -> Egress.
  - Quality: Profiling -> Scorecards -> Standardization -> Exception Mgmt.
GOVERNANCE SPECIFICS:
- Classification, Data Access Management, Consent Management are critical for MDM/Governance.
`;

const architectureSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          label: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target'] },
          x: { type: Type.NUMBER, description: "X coordinate (0-900)" },
          y: { type: Type.NUMBER, description: "Y coordinate (50-250)" },
        },
        required: ['id', 'label', 'type', 'x', 'y'],
      },
    },
    edges: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          from: { type: Type.STRING },
          to: { type: Type.STRING },
          label: { type: Type.STRING },
        },
        required: ['from', 'to', 'label'],
      },
    },
  },
  required: ['nodes', 'edges'],
};

const refinementSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    suggestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          impact: { type: Type.STRING, enum: ['Performance', 'Security', 'Governance', 'Reliability'] },
          // We ask Gemini to return the FULL modified design to make applying it easy
          suggestedDesign: architectureSchema
        },
        required: ['id', 'title', 'description', 'impact', 'suggestedDesign']
      }
    }
  },
  required: ['suggestions']
};

const questionnaireSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING },
          question: { type: Type.STRING },
          answer: { type: Type.STRING },
        },
        required: ['id', 'category', 'question', 'answer'],
      },
    },
  },
  required: ['questions'],
};

const requirementsSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    requirements: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Infrastructure', 'Network', 'Security', 'License', 'Development'] },
          item: { type: Type.STRING },
          description: { type: Type.STRING },
          criticality: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
        },
        required: ['id', 'category', 'item', 'description', 'criticality'],
      },
    },
  },
  required: ['requirements'],
};

// --- LEARNING FUNCTION ---
export const learnFromProject = async (context: string, finalDesign: DesignData) => {
  // In a real app, this sends data to a vector DB.
  // Here, we simulate "extracting a lesson" to update our in-memory patterns.
  try {
     const prompt = `
       Analyze this completed architecture design.
       Context: ${context}
       Design Nodes: ${JSON.stringify(finalDesign.nodes)}

       Extract 1 generic architectural rule or pattern from this that could apply to future projects.
       Keep it under 15 words.
       Output format: Just the string.
     `;
     const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: prompt
     });

     if (response.text) {
       const newPattern = `Pattern: ${response.text.trim()}`;
       if (!LEARNED_PATTERNS.includes(newPattern)) {
          LEARNED_PATTERNS.push(newPattern);
          console.log("Gemini Learned:", newPattern);
       }
     }
  } catch (e) {
    console.error("Learning failed", e);
  }
};

export const generateArchitectureDesign = async (
  context: string,
  solutionType: string
): Promise<DesignData> => {
  try {
    const model = 'gemini-3-pro-preview'; 

    const prompt = `
      Act as an Informatica Cloud Solution Architect.
      Create a High Level Design (HLD) diagram structure.

      Knowledge Base: ${INFORMATICA_KB}
      Learned Patterns (Apply these if relevant):
      ${LEARNED_PATTERNS.join('\n')}

      Solution Type: ${solutionType}
      RFP/Context: ${context}

      Task:
      1. Analyze the RFP for key entities (Sources, Targets, Logic).
      2. If MDM/Governance is detected, include Consent/Classification logic.
      3. Generate Nodes and Edges.
      4. Layout: Sources Left (x~50), Targets Right (x~900).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: architectureSchema,
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as DesignData;
    }
    throw new Error("No design generated");
  } catch (error) {
    console.error("Gemini design error:", error);
    return { nodes: [], edges: [] };
  }
};

