  aiEdges, 
  isThinking, 
  thoughts,
  context = "",
  onApplyRefinement
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [showMermaid, setShowMermaid] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Refinement State
  const [showInsights, setShowInsights] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [suggestions, setSuggestions] = useState<RefinementSuggestion[]>([]);

  // Generate Mermaid Code
  const getMermaidCode = () => {
    if (!aiNodes.length) return "graph LR\n  NoData[No Design Generated]";

    let code = "graph LR\n";
    // Define styles
    code += "  classDef source fill:#eff6ff,stroke:#3b82f6,stroke-width:2px,color:#1e40af;\n";
    code += "  classDef stage fill:#f1f5f9,stroke:#64748b,stroke-width:2px,color:#334155;\n";
    code += "  classDef process fill:#fff7ed,stroke:#f97316,stroke-width:2px,color:#9a3412;\n";
    code += "  classDef target fill:#ecfdf5,stroke:#10b981,stroke-width:2px,color:#065f46;\n\n";

    aiNodes.forEach(node => {
      // Escape label quotes
      const label = node.label.replace(/"/g, "'");
      code += `  ${node.id}["${label}"]:::${node.type}\n`;
    });

    code += "\n";

    aiEdges.forEach(edge => {
      const label = edge.label ? `|"${edge.label}"|` : "";
      code += `  ${edge.from} -->${label} ${edge.to}\n`;
    });

    return code;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getMermaidCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Export Logic
  const handleExport = (format: 'svg' | 'png') => {
    if (!svgRef.current) return;

    const svgEl = svgRef.current;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svgEl);

    // Add XML namespaces
    if(!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)){
        source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if(!source.match(/^<svg[^>]+xmlns:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)){
        source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" standalone="no"?>\r\n' + source;

    if (format === 'svg') {
        const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
        const link = document.createElement("a");
        link.href = url;
        link.download = "architecture-design.svg";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        const img = new Image();
        img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
        img.onload = () => {
            const canvas = document.createElement("canvas");
            canvas.width = 1000; 
            canvas.height = 300;
            const ctx = canvas.getContext("2d");
            if (ctx) {
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                const pngUrl = canvas.toDataURL("image/png");
                const link = document.createElement("a");
                link.href = pngUrl;
                link.download = "architecture-design.png";
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        };
    }
    setShowExportMenu(false);
  };

  const handleFetchRefinements = async () => {
    if (!context || !aiNodes.length) return;

    setIsRefining(true);
    setShowInsights(true);
    setSuggestions([]);

    try {
      const currentDesign = { nodes: aiNodes, edges: aiEdges };
      const newSuggestions = await generateDesignRefinements(currentDesign, context);
      setSuggestions(newSuggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefining(false);
    }
  };

  const applySuggestion = (suggestion: RefinementSuggestion) => {
    if (onApplyRefinement) {
      onApplyRefinement(suggestion.suggestedDesign);
      setSuggestions(prev => prev.filter(s => s.id !== suggestion.id)); // Remove applied
    }
  };

  return (
    <div className="flex flex-col h-full relative group">
      {/* Header Toolbar */}
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center z-20">
        <div>
          <h3 className="font-bold text-slate-800">High Level Design (HLD)</h3>
          <p className="text-xs text-slate-500 hidden sm:block">
            {isThinking ? "Gemini is analyzing requirements..." : "Generated based on RFP Context & Gemini Patterns"}
          </p>
        </div>

        <div className="flex items-center gap-2 relative">
           {/* Deep Learning / Insights Button */}
           <button 
             onClick={handleFetchRefinements}
             className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 border border-indigo-100 px-3 py-1.5 rounded hover:bg-indigo-100 transition-colors mr-2"
           >
             <Sparkles size={14} className={isRefining ? 'animate-spin' : ''} />
             <span className="hidden sm:inline">Gemini Insights</span>
           </button>

          {/* Export Dropdown */}
          <div className="relative">
             <button 
                onClick={() => setShowExportMenu(!showExportMenu)}
                className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50 transition-colors"
             >
                <Share2 size={14} /> 
                <span className="hidden sm:inline">Export</span>
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-1 w-32 bg-white rounded-lg shadow-xl border border-slate-200 py-1 z-30">
                   <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2">
                      <ImageIcon size={14} /> PNG Image
                   </button>
                   <button onClick={() => handleExport('svg')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2">
                      <FileCode size={14} /> SVG Vector
                   </button>
                </div>
             )}
          </div>

          <button 
             onClick={() => setShowMermaid(true)}
             className="flex items-center gap-2 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700 transition-colors"
          >
            <Code size={14} /> 
            <span className="hidden sm:inline">Mermaid</span>
          </button>
        </div>
      </div>

      {/* Canvas Area */}
      <div className="flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">

        {/* Gemini Insights Floating Panel */}
        {showInsights && (
           <div className="absolute top-4 left-4 z-20 w-72 bg-white/95 backdrop-blur-md rounded-xl shadow-xl border border-indigo-100 overflow-hidden flex flex-col max-h-[80%] animate-fade-in-up">
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 p-3 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2">
                    <BrainCircuit size={16} />
                    <span className="font-bold text-sm">Design Analysis</span>
                 </div>
                 <button onClick={() => setShowInsights(false)} className="hover:bg-white/20 rounded p-1">
                    <X size={14} />
                 </button>
              </div>
              <div className="p-4 overflow-y-auto flex-1">
                 {isRefining ? (
                    <div className="flex flex-col items-center justify-center py-8 text-center">
                       <Loader size={24} className="text-indigo-500 animate-spin mb-2" />
                       <p className="text-xs text-slate-500 font-medium">Comparing with 1,204 learned patterns...</p>
                    </div>
                 ) : suggestions.length > 0 ? (
                    <div className="space-y-3">
                       {suggestions.map((sug) => (
                          <div key={sug.id} className="bg-indigo-50 border border-indigo-100 rounded-lg p-3">
                             <div className="flex justify-between items-start mb-1">
                                <h5 className="font-bold text-slate-800 text-xs">{sug.title}</h5>
                                <span className="text-[9px] uppercase font-bold text-indigo-600 bg-white px-1.5 py-0.5 rounded border border-indigo-100">{sug.impact}</span>
                             </div>
                             <p className="text-[10px] text-slate-600 mb-2 leading-relaxed">{sug.description}</p>
                             <button 
                               onClick={() => applySuggestion(sug)}
                               className="w-full bg-white text-indigo-600 text-xs font-bold py-1.5 rounded border border-indigo-200 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1"
                             >
                                <Zap size={10} /> Apply Optimization
                             </button>
                          </div>
                       ))}
                    </div>
                 ) : (
                    <div className="text-center py-4 text-slate-400 text-xs">
                       <CheckCircle size={24} className="mx-auto mb-2 text-emerald-400" />
                       <p>No major refinements found. Design adheres to current best practices.</p>
                    </div>
                 )}
              </div>
           </div>
        )}

        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/95 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm transition-opacity duration-300">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse">
                      <BrainCircuit className="text-white" size={24} />
                   </div>
                   <div>
                      <h4 className="font-bold text-slate-800 text-lg">Gemini Thinking...</h4>
                      <p className="text-xs text-slate-500">Model: gemini-3-pro-preview</p>
                   </div>
                </div>
                <div className="space-y-3 font-mono text-xs max-h-60 overflow-y-auto">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.3}s`}}>
                         <CheckCircle size={14} className="text-emerald-500 flex-shrink-0" />
                         <span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200 shadow-sm">{thought}</span>
                      </div>
                   ))}
                   <div className="flex items-center gap-3 mt-4">
                      <Loader size={14} className="text-blue-500 animate-spin flex-shrink-0" />
                      <span className="text-blue-500 font-bold">Synthesizing Architecture...</span>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* The SVG Canvas */}
        <svg 
            ref={svgRef} 
            width="100%" 
            height="100%" 
            viewBox="0 0 1000 300" 
            className="w-full h-full select-none"
            preserveAspectRatio="xMidYMid meet"
        >
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>

          {/* Background for export (ensure white bg) */}
          <rect x="0" y="0" width="1000" height="300" fill="#ffffff" />

          {/* Edges */}
          {aiEdges && aiEdges.map((edge, i) => {
            const source = aiNodes.find(n => n.id === edge.from);
            const target = aiNodes.find(n => n.id === edge.to);
            if (!source || !target) return null;

            // Refined Curve Logic (Right of Source -> Left of Target)
            const sourceX = source.x + 160; // 160 is width
            const sourceY = source.y + 40;  // 40 is half height
            const targetX = target.x;
            const targetY = target.y + 40;

            const controlPointOffset = 60;

            return (
              <g key={i} className="animate-fade-in" style={{animationDelay: '0.5s'}}>
                <path 
                  d={`M ${sourceX} ${sourceY} C ${sourceX + controlPointOffset} ${sourceY}, ${targetX - controlPointOffset} ${targetY}, ${targetX} ${targetY}`} 
                  stroke="#cbd5e1" 
                  strokeWidth="2" 
                  fill="none" 
                  markerEnd="url(#arrowhead)"
                />
                {/* Edge Label Background & Text */}
                <rect 
                    x={(sourceX + targetX)/2 - 40} 
                    y={(sourceY + targetY)/2 - 10} 
                    width="80" 
                    height="20" 
                    rx="4" 
                    fill="white" 
                    stroke="#e2e8f0" 
                    strokeWidth="1"
                />
                <text 
                    x={(sourceX + targetX)/2} 
                    y={(sourceY + targetY)/2 + 4} 
                    textAnchor="middle" 
                    fontSize="10" 
                    fill="#64748b" 
                    fontWeight="600"
                    style={{ fontFamily: 'Inter, sans-serif' }}
                >
                    {edge.label}
                </text>
              </g>
            );
          })}

          {/* Nodes */}
          {aiNodes && aiNodes.map((node, i) => {
             // ForeignObject can be glitchy in exports. We use it for display, but for export we might need to inline styles carefully.
             return (
               <foreignObject 
                 x={node.x} 
                 y={node.y} 
                 width="160" 
                 height="80" 
                 key={node.id} 
                 className="animate-fade-in-up overflow-visible" 
                 style={{animationDelay: `${i * 0.1}s`}}
               >
                 <div className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white
                    ${node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                      node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                      node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                      'bg-white border-slate-300'}`}>
                    <div className="mb-1">
                      {node.type === 'source' && <Database size={20} className="text-blue-600" />}
                      {node.type === 'stage' && <Server size={20} className="text-slate-600" />}
                      {node.type === 'process' && <Settings size={20} className="text-orange-600 animate-spin-slow" />}
                      {node.type === 'target' && <CloudLightning size={20} className="text-emerald-600" />}
                    </div>
                    <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">
                        {node.label}
                    </span>
                 </div>
               </foreignObject>
             );
          })}
        </svg>
      </div>

      {/* Mermaid Code Modal */}
      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
               <h3 className="font-bold text-slate-800 flex items-center gap-2">
                 <Code size={18} className="text-blue-600" />
                 Mermaid.js Diagram Code
               </h3>
               <button onClick={() => setShowMermaid(false)} className="text-slate-400 hover:text-slate-700 transition-colors">
                 <X size={20} />
               </button>
            </div>
            <div className="flex-1 p-0 overflow-hidden relative group/code">
               <pre className="w-full h-full p-6 bg-slate-900 text-blue-100 font-mono text-xs overflow-auto">
                 {getMermaidCode()}
               </pre>
               <button 
                  onClick={copyToClipboard}
                  className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg backdrop-blur-md transition-all border border-white/10"
               >
                  {copied ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}
               </button>
            </div>
            <div className="p-4 border-t border-slate-200 flex justify-end gap-2 bg-slate-50">
               <button onClick={() => setShowMermaid(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition-colors">
                 Close
               </button>
               <button 
                 onClick={copyToClipboard} 
                 className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors flex items-center gap-2"
               >
                 {copied ? 'Copied!' : 'Copy Code'}
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ArchitectureCanvas;

import React, { useState, useEffect } from 'react';
import { 
  Download, 
  List, 
  Workflow, 
  Server, 
  CheckCircle, 
  ClipboardList, 
  Plus, 
  Sparkles, 
  PenTool, 
  Lightbulb, 
  ThumbsUp, 
  MessageSquare, 
  Send,
  ShieldCheck,
  Network,
  Key,
  Flag,
  FileText,
  Clock,
  Database,
  Users,
  Lock,
  Zap,
  BookOpen
} from 'lucide-react';
import { RequestData, DesignData, Question, Requirement, DesignCache, CachedRequestData } from '../types';
import ArchitectureCanvas from './ArchitectureCanvas';
import { 
  generateArchitectureDesign, 
  generateIntelligentQuestionnaire, 
  generateProjectRequirements,
  learnFromProject // Import the new learning function
} from '../services/geminiService';

interface SolutionDesignViewProps {
  request: RequestData | null;
  designCache: DesignCache;
  onUpdateDesignCache: (reqId: string, data: CachedRequestData) => void;
}

// Helper to simulate text extraction from mock files - Extended for improved context
const extractTextFromMock = (fileName: string) => {
  if (fileName.includes("AA Motors") || fileName.includes("HANA")) {
    return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer (B2C). Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta. Needs Consent Management for GDPR compliance and Data Access management for regional sales teams.";
  }
  if (fileName.includes("Vehicle") || fileName.includes("Adobe")) {
    return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM. Volume: High frequency micro-batches.";
  }
  if (fileName.includes("Reckitt")) {
    return "Client: Reckitt. Scope: MDM for Customer & Product. Survivorship: Trust scores defined. Workflow: 2-step approval. Source: 35 different sources (Excel, Flatfiles). Volume: 16K Customers. Classification of PII data is required.";
  }
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB (Oracle). Target: Cloud Data Warehouse (Snowflake). Pattern: Batch ETL. Security: End-to-end encryption required.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState<'initiation' | 'design' | 'requirements' | 'scoping'>('design');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);

  // Design Data
  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [questions, setQuestions] = useState<Question[]>([]);
  const [requirements, setRequirements] = useState<Requirement[]>([]);

  const [refinementPrompt, setRefinementPrompt] = useState("");

  // Load from cache or reset
  useEffect(() => {
    if (request) {
      if (designCache[request.id]) {
        const cached = designCache[request.id];
        setCurrentDesign(cached.design);
        setQuestions(cached.questions);
        setRequirements(cached.requirements);
        setStatus(cached.status);
      } else {
        setStatus('idle');
        setCurrentDesign({ nodes: [], edges: [] });
        setQuestions([]);
        setRequirements([]);
      }
    }
  }, [request, designCache]);

  const handleGenerate = async (promptOverride: string | null = null) => {
    if (!request) return;
    setStatus('thinking');
    setThoughts([]);

    // 1. Thinking Steps
    const baseThoughts = [
      `Reading RFP: ${request.rfpFile}...`,
      `Context: ${request.clientName} - ${request.type}`,
      "Analyzing MDM & Governance patterns...",
      promptOverride ? `Applying modification: "${promptOverride}"` : "Consulting Informatica Knowledge Base...",
      "Drafting HLD Architecture & Scoping..."
    ];

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 600)); 
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    const context = extractTextFromMock(request.rfpFile) + (promptOverride ? ` Refinement: ${promptOverride}` : "");

    // 2. Parallel Generation using Gemini 3 Pro
    try {
      const [design, generatedQuestions, generatedRequirements] = await Promise.all([
        generateArchitectureDesign(context, request.type),
        generateIntelligentQuestionnaire(context, request.type),
        generateProjectRequirements(context, request.type)
      ]);

      setCurrentDesign(design);

      // Merge new questions/reqs only if it's a fresh run, otherwise preserve user edits could be better but let's overwrite for "Regenerate"
      setQuestions(generatedQuestions);
      setRequirements(generatedRequirements);

      setStatus('review');
    } catch (e) {
      console.error("Generation failed", e);
      setStatus('idle');
    }
  };

  const handleAcceptDesign = () => {
    if (request) {
      const cacheData: CachedRequestData = {
        design: currentDesign,
        questions: questions,
        requirements: requirements,
        status: 'accepted'
      };
      onUpdateDesignCache(request.id, cacheData);
      setStatus('accepted');

      // Trigger Learning Process
      const context = extractTextFromMock(request.rfpFile);
      learnFromProject(context, currentDesign);
    }
  };

  const handleUpdateDesignFromRefinement = (newDesign: DesignData) => {
     setCurrentDesign(newDesign);
  };

  const handleAddQuestion = () => {
    setQuestions([...questions, { id: `CUST-${Date.now()}`, category: "Custom", question: "", answer: "", isCustom: true }]);
  };

  const handleDeleteQuestion = (id: string) => setQuestions(questions.filter(q => q.id !== id));

  const handleQuestionChange = (id: string, field: 'question' | 'answer', value: string) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, [field]: value } : q));
  };

  if (!request) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-slate-400">
        <PenTool size={48} className="mb-4 text-slate-200" />
        <p className="text-lg font-medium">No Request Selected</p>
        <p className="text-sm">Please select a Request ID from the Dashboard.</p>
      </div>
    );
  }

  const getCriticalityColor = (level: string) => {
    switch(level) {
      case 'High': return 'bg-red-100 text-red-700 border-red-200';
      case 'Medium': return 'bg-orange-100 text-orange-700 border-orange-200';
      case 'Low': return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const getRequirementIcon = (cat: string) => {
    switch(cat) {
      case 'Infrastructure': return <Server size={18} />;
      case 'Network': return <Network size={18} />;
      case 'Security': return <ShieldCheck size={18} />;
      case 'License': return <Key size={18} />;
      default: return <CheckCircle size={18} />;
    }
  };

  // Helper to check for high priority keywords
  const isHighPriorityQuestion = (text: string) => {
    const lower = text.toLowerCase();
    return lower.includes('consent') || lower.includes('gdpr') || lower.includes('privacy') || lower.includes('pii');
  };

  // Checklist Data for Project Initiation
  const initiationChecklist = [
    {
      title: "Business Context & Goals",
      icon: <Users size={20} className="text-blue-500" />,
      items: [
        "Primary Business Objectives & Success Criteria (KPIs)",
        "Key Stakeholders & Sign-off Authority",
        "Target Timeline & Milestones",
        "Current Pain Points in Data Process"
      ]
    },
    {
      title: "Data Landscape",
      icon: <Database size={20} className="text-indigo-500" />,
      items: [
        "Source Systems List (DB, API, File, SaaS)",
        "Data Volume (Historical Load vs Daily Delta)",
        "Data Format Specifications (JSON, XML, CSV, Parquet)",
        "Connectivity Details (VPN, VPC Peering, Public Internet)"
      ]
    },
    {
      title: "Integration Logic",
      icon: <Zap size={20} className="text-orange-500" />,
