    "Informatica Data Quality (IDQ)",
    "MDM Multidomain (On-Prem)",
    "Axon Data Governance",
    "Enterprise Data Catalog (EDC)",
    "Test Data Management (TDM)",
    "Data Engineering Integration (DEI)",
    "PowerExchange (Mainframe/CDC)"
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleDeploymentChange = (model: 'Cloud' | 'On-Premise') => {
    setFormData(prev => ({ 
      ...prev, 
      deploymentModel: model,
      solutionType: '' // Reset selection when model changes
    }));
  };

  const processFile = (file: File) => {
    setFormData(prev => ({ ...prev, rfpName: file.name }));
    setIsScanning(true);
    setScanComplete(false);
    setAiSuggestion(null);

    // Simulate AI Analysis
    setTimeout(() => {
      setIsScanning(false);
      setScanComplete(true);

      const fileName = file.name.toLowerCase();
      let suggestion: AiSuggestion | null = null;

      if (fileName.includes('aa motors') || fileName.includes('hana')) {
         suggestion = {
          deployment: 'Cloud',
          type: "MDM SaaS (Customer/Product 360)",
          reason: "Detected 'AA Motors' Cloud Modernization Pattern.",
          details: [
            "Source: SAP HANA identified.",
            "Requirement: Match & Merge logic.",
            "Artifacts identified: job_ingress, job_egress."
          ]
        };
      } else if (fileName.includes('legacy') || fileName.includes('mainframe') || fileName.includes('bank')) {
         suggestion = {
          deployment: 'On-Premise',
          type: "PowerCenter (PWC)",
          reason: "Detected Legacy Mainframe Integration.",
          details: [
             "Source: VSAM/Cobol Copybooks.",
             "Constraint: Data residency requires On-Premise processing.",
             "Recommendation: PowerCenter with PowerExchange."
          ]
        };
      } else if (fileName.includes('vehicle') || fileName.includes('adobe')) {
         suggestion = {
          deployment: 'Cloud',
          type: "Cloud Data Integration (CDI)",
          reason: "Detected Integration/Synchronization Pattern.",
          details: [
            "Source: Adobe/Vehicle Data.",
            "Target: Salesforce.",
            "Requirement: Error Handling via Blob Storage."
          ]
        };
      } else if (fileName.includes('reckitt')) {
        suggestion = {
          deployment: 'Cloud',
          type: "MDM SaaS (Customer/Product 360)",
          reason: "Detected 'Reckitt' MDM/Governance Pattern.",
          details: [
            "Requirement: PII Classification.",
            "Requirement: Trust Scores & Survivorship.",
            "Source: Multiple Flatfiles."
          ]
        };
      } else {
        suggestion = {
          deployment: 'Cloud',
          type: "Cloud Data Integration (CDI)",
          reason: "Standard Data Integration Pattern detected.",
          details: [
            "Converted general ETL requirements to Cloud Data Integration.",
            "Assumed modernization to IDMC platform."
          ]
        };
      }
      setAiSuggestion(suggestion);
    }, 2500); 
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const applySuggestion = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        deploymentModel: aiSuggestion.deployment,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      clientName: formData.clientName,
      deploymentModel: formData.deploymentModel,
      type: formData.solutionType,
      rfpFile: formData.rfpName,
      date: new Date().toLocaleDateString(),
    });
  };

  const activeServices = formData.deploymentModel === 'Cloud' ? cloudServices : onPremServices;

  return (
    <div className="p-6 md:p-8 max-w-5xl mx-auto animate-fade-in">
      <div className="mb-8 flex items-center justify-between">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">New Solution Design</h2>
           <p className="text-slate-500">Upload RFP to generate architectural recommendations.</p>
        </div>
        <div className={`hidden md:flex items-center gap-2 px-4 py-2 rounded-full text-xs font-bold border ${formData.deploymentModel === 'Cloud' ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-slate-100 text-slate-700 border-slate-200'}`}>
           {formData.deploymentModel === 'Cloud' ? <CloudLightning size={14} /> : <Server size={14} />}
           {formData.deploymentModel === 'Cloud' ? 'CLOUD-NATIVE MODE' : 'ON-PREMISE MODE'}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Form Area */}
        <div className="lg:col-span-2">
          <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 md:p-8 h-full flex flex-col">
            <div className="space-y-6 flex-1">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Client Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="clientName"
                  required
                  value={formData.clientName}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none transition-all"
                  placeholder="e.g. Acme Corp"
                />
              </div>

              {/* RFP Upload Section */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Request for Proposal (RFP) File <span className="text-red-500">*</span>
                </label>
                <div 
                  className={`
                    border-2 border-dashed rounded-xl h-48 flex flex-col items-center justify-center p-6 text-center transition-colors relative overflow-hidden
                    ${isDragging ? 'border-orange-500 bg-orange-50' : 'border-slate-300 hover:border-orange-400 hover:bg-slate-50'}
                    ${isScanning ? 'bg-orange-50 border-orange-200' : ''}
                  `}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={handleFileDrop}
                >
                  {isScanning ? (
                    <div className="flex flex-col items-center animate-pulse">
                      <Loader className="w-10 h-10 text-orange-500 animate-spin mb-3" />
                      <p className="text-orange-700 font-medium">Analyzing Requirements...</p>
                      <p className="text-xs text-orange-500 mt-1">Determining best-fit Deployment Model...</p>
                    </div>
                  ) : formData.rfpName ? (
                    <div className="animate-fade-in w-full">
                      <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-3">
                        <CheckCircle size={24} />
                      </div>
                      <p className="font-medium text-slate-800 break-all">{formData.rfpName}</p>
                      <div className="flex justify-center gap-4 mt-2">
                        <button 
                          type="button"
                          onClick={() => {
                            setFormData(prev => ({...prev, rfpName: ''}));
                            setScanComplete(false);
                            setAiSuggestion(null);
                          }}
                          className="text-sm text-red-500 hover:underline"
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="w-12 h-12 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center mb-3">
                        <UploadCloud size={24} />
                      </div>
                      <p className="font-medium text-slate-700 mb-1">Upload RFP Document</p>
                      <p className="text-xs text-slate-400 mb-4">PDF, DOCX (Max 10MB)</p>
                      <input 
                        type="file" 
                        id="file-upload" 
                        className="hidden" 
                        onChange={handleFileSelect}
                      />
                      <label 
                        htmlFor="file-upload"
                        className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-50 cursor-pointer shadow-sm"
                      >
                        Browse Files
                      </label>
                    </>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">
                    Deployment Model <span className="text-red-500">*</span>
                  </label>
                  <div className="flex p-1 bg-slate-100 rounded-lg border border-slate-200">
                    <button
                      type="button"
                      onClick={() => handleDeploymentChange('Cloud')}
                      className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all ${formData.deploymentModel === 'Cloud' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <Cloud size={16} /> Cloud
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDeploymentChange('On-Premise')}
                      className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all ${formData.deploymentModel === 'On-Premise' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <Server size={16} /> On-Premise
                    </button>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">
                    Technology Stack <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <select
                      name="solutionType"
                      required
                      value={formData.solutionType}
                      onChange={handleInputChange}
                      className={`
                        w-full px-4 py-3 rounded-lg border focus:ring-2 focus:border-transparent outline-none appearance-none bg-white transition-all
                        ${scanComplete && aiSuggestion && !formData.solutionType 
                          ? 'border-orange-300 ring-2 ring-orange-100' 
                          : 'border-slate-300 focus:ring-orange-500'}
                      `}
                    >
                      <option value="" disabled>Select {formData.deploymentModel} Service...</option>
                      {activeServices.map(type => (
                        <option key={type} value={type}>{type}</option>
                      ))}
                    </select>
                    <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
                      <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                    </div>
                  </div>
                </div>
              </div>

               <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Priority
                </label>
                <div className="flex gap-4">
                  {['Low', 'Normal', 'High'].map(p => (
                    <label key={p} className="flex items-center gap-2 cursor-pointer">
                      <input 
                        type="radio" 
                        name="priority" 
                        value={p}
                        checked={formData.priority === p}
                        onChange={handleInputChange}
                        className="text-orange-600 focus:ring-orange-500"
                      />
                      <span className="text-sm text-slate-700">{p}</span>
                    </label>
                  ))}
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-end gap-4 mt-8">
              <button 
                type="button"
                onClick={onCancel}
                className="px-6 py-2.5 rounded-lg border border-slate-300 text-slate-700 font-medium hover:bg-slate-50 transition-colors"
              >
                Cancel
              </button>
              <button 
                type="submit"
                disabled={!formData.clientName || !formData.solutionType}
                className={`
                  px-6 py-2.5 rounded-lg text-white font-medium shadow-sm transition-all
                  ${(!formData.clientName || !formData.solutionType) 
                    ? 'bg-slate-300 cursor-not-allowed' 
                    : 'bg-orange-600 hover:bg-orange-700 hover:shadow-md'}
                `}
              >
                Create Design
              </button>
            </div>
          </form>
        </div>

        {/* AI Suggestions Panel */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-900 text-white rounded-xl shadow-lg p-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <Sparkles size={100} />
            </div>

            <div className="flex items-center gap-2 mb-4">
              <Sparkles className="text-orange-400" size={20} />
              <h3 className="font-bold text-lg">CLAIRE AI</h3>
            </div>

            {!scanComplete && !isScanning && (
              <div className="text-slate-400 text-sm">
                <p className="mb-4">Upload an RFP to detect architecture requirements and deployment models.</p>
                <div className="flex flex-col gap-2">
                  <div className="bg-slate-800 p-3 rounded-lg flex items-center gap-3">
                    <RefreshCw size={16} className="text-blue-400" />
                    <span>Analyzes Context</span>
                  </div>
                  <div className="bg-slate-800 p-3 rounded-lg flex items-center gap-3">
                    <Server size={16} className="text-emerald-400" />
                    <span>Recommends Platform</span>
                  </div>
                </div>
              </div>
            )}

            {isScanning && (
              <div className="py-8 text-center">
                <div className="inline-block relative">
                   <div className="w-12 h-12 border-4 border-orange-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                </div>
                <p className="text-slate-300 font-medium">Scanning RFP...</p>
                <p className="text-xs text-slate-500 mt-2">Detecting Cloud vs On-Premise signals</p>
              </div>
            )}

            {scanComplete && aiSuggestion && (
              <div className="animate-fade-in">
                <div className="mb-4">
                  <span className="text-xs font-bold text-orange-400 uppercase tracking-wider">Suggested Architecture</span>
                  <div className="flex items-center gap-2 mt-1">
                     <h4 className="text-xl font-bold">{aiSuggestion.deployment}</h4>
                  </div>
                  <p className="text-sm text-slate-300 font-medium">{aiSuggestion.type.split('(')[0]}</p>
                </div>

                <div className="bg-slate-800 rounded-lg p-4 mb-4 border border-slate-700">
                  <p className="text-sm text-slate-300 leading-relaxed">
                    {aiSuggestion.reason}
                  </p>
                </div>

                <div className="space-y-2 mb-6">
                  {aiSuggestion.details.map((detail, idx) => (
                    <div key={idx} className="flex items-start gap-2 text-xs text-slate-400">
                      <CheckCircle size={14} className="text-emerald-500 mt-0.5 shrink-0" />
                      <span>{detail}</span>
                    </div>
                  ))}
                </div>

                <button 
                  onClick={applySuggestion}
                  className="w-full bg-white text-slate-900 py-2.5 rounded-lg font-bold text-sm hover:bg-slate-100 transition-colors flex items-center justify-center gap-2"
                >
                  Apply Recommendation
                  <ArrowRight size={16} />
                </button>
              </div>
            )}
          </div>

          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
             <div className="flex items-center gap-2 mb-3 text-slate-800">
               <AlertCircle size={18} className="text-blue-500" />
               <h3 className="font-bold text-sm">Platform Selection Tips</h3>
             </div>
             <ul className="text-xs text-slate-500 space-y-2 list-disc pl-4">
               <li><strong>IDMC (Cloud):</strong> Best for new projects, SaaS sources, and scalability.</li>
               <li><strong>PowerCenter (On-Prem):</strong> Best for legacy mainframe data, strict data residency without cloud bridging.</li>
               <li><strong>Hybrid:</strong> Use IDMC with Secure Agents behind your firewall.</li>
             </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreateForm;

