import React, { useState } from 'react';
import { 
  Layers, 
  Activity, 
  ShieldCheck, 
  Database, 
  FileText,
  Filter,
  ArrowUpRight,
  Server,
  Cloud
} from 'lucide-react';
import { RequestData } from '../types';

interface DashboardViewProps {
  requests: RequestData[];
  onSelectRequest: (req: RequestData) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ requests, onSelectRequest }) => {
  const [filterType, setFilterType] = useState('All');

  const categories = [
    { id: 'All', label: 'All Requests' },
    { id: 'Integration', label: 'Data Integration' },
    { id: 'Quality', label: 'Data Quality' },
    { id: 'Governance', label: 'Governance & Catalog' },
    { id: 'MDM', label: 'MDM & 360' },
  ];

  const filteredRequests = requests.filter(req => {
    if (filterType === 'All') return true;
    return req.type.includes(filterType) || (filterType === 'MDM' && req.type.includes('360'));
  });

  const stats = [
    { label: 'Total Requests', value: filteredRequests.length, icon: Layers, color: 'bg-indigo-500' },
    { label: 'Cloud Native', value: filteredRequests.filter(r => r.deploymentModel === 'Cloud').length, icon: Cloud, color: 'bg-blue-500' },
    { label: 'On-Premise', value: filteredRequests.filter(r => r.deploymentModel === 'On-Premise').length, icon: Server, color: 'bg-slate-500' },
    { label: 'High Priority', value: filteredRequests.length > 0 ? Math.floor(filteredRequests.length * 0.3) : 0, icon: Activity, color: 'bg-orange-500' },
  ];

  return (
    <div className="p-6 md:p-8 max-w-7xl mx-auto animate-fade-in">
      <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Solution Dashboard</h2>
          <p className="text-slate-500">Monitor and manage your data architecture requests.</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg border border-slate-200 shadow-sm overflow-x-auto">
          {categories.map(cat => (
             <button
               key={cat.id}
               onClick={() => setFilterType(cat.id)}
               className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap ${
                 filterType === cat.id 
                   ? 'bg-indigo-50 text-indigo-700' 
                   : 'text-slate-600 hover:bg-slate-50'
               }`}
             >
               {cat.label}
             </button>
          ))}
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {stats.map((stat, index) => (
          <div key={index} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 transition-all hover:shadow-md">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-500 mb-1">{stat.label}</p>
                <h3 className="text-3xl font-bold text-slate-800">{stat.value}</h3>
              </div>
              <div className={`p-3 rounded-xl ${stat.color} bg-opacity-10 text-${stat.color.replace('bg-', '')}`}>
                <stat.icon size={24} className={stat.color.replace('bg-', 'text-')} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Requests Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[400px]">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <div className="flex items-center gap-2">
             <Filter size={16} className="text-slate-400" />
             <h3 className="font-bold text-slate-800 text-sm uppercase tracking-wide">Request Queue</h3>
          </div>
          <span className="text-xs font-medium text-slate-500">{filteredRequests.length} Records found</span>
        </div>

        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 text-slate-500 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 font-semibold w-32">ID</th>
                <th className="px-6 py-4 font-semibold">Client</th>
                <th className="px-6 py-4 font-semibold">Deployment</th>
                <th className="px-6 py-4 font-semibold">Solution Type</th>
                <th className="px-6 py-4 font-semibold">Last Updated</th>
                <th className="px-6 py-4 font-semibold text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-20 text-center text-slate-400">
                    <div className="flex flex-col items-center gap-3">
                      <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center">
                         <FileText size={32} className="text-slate-300" />
                      </div>
                      <p>No requests match the current filter.</p>
                      <button 
                        onClick={() => setFilterType('All')}
                        className="text-indigo-600 font-medium hover:underline text-xs"
                      >
                        Clear filters
                      </button>
                    </div>
                  </td>
                </tr>
              ) : (
                filteredRequests.map((req, idx) => (
                  <tr key={idx} className="hover:bg-indigo-50/30 transition-colors group cursor-pointer" onClick={() => onSelectRequest(req)}>
                    <td className="px-6 py-4">
                      <span className="font-mono font-medium text-slate-600 group-hover:text-indigo-600">{req.id}</span>
                    </td>
                    <td className="px-6 py-4 font-bold text-slate-800">{req.clientName}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.deploymentModel === 'Cloud' 
                          ? 'bg-blue-50 text-blue-700 border-blue-100' 
                          : 'bg-slate-100 text-slate-700 border-slate-200'
                      }`}>
                         {req.deploymentModel === 'Cloud' ? <Cloud size={12} /> : <Server size={12} />}
                         {req.deploymentModel}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-slate-600">
                       {req.type}
                    </td>
                    <td className="px-6 py-4 text-slate-500">{req.date}</td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        className="text-indigo-600 hover:bg-indigo-50 p-2 rounded-full transition-colors opacity-0 group-hover:opacity-100"
                        title="Open Design"
                      >
                        <ArrowUpRight size={18} />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

