import React, { useState, useEffect } from 'react';
import { 
  CloudLightning, 
  Loader, 
  CheckCircle, 
  UploadCloud, 
  Sparkles, 
  RefreshCw, 
  AlertCircle,
  ArrowRight,
  Server,
  Cloud,
  Cpu,
  Search
} from 'lucide-react';
import { AiSuggestion } from '../types';

interface CreateFormProps {
  onSubmit: (data: any) => void;
  onCancel: () => void;
}

const CreateForm: React.FC<CreateFormProps> = ({ onSubmit, onCancel }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpName: '',
    deploymentModel: 'Cloud' as 'Cloud' | 'On-Premise',
    solutionType: '',
    description: '',
    priority: 'Normal'
  });

  // Step 1: Input Data -> Step 2: AI Analysis -> Step 3: Review Recommendation -> Step 4: Create
  const [step, setStep] = useState<'input' | 'analyzing' | 'recommendation'>('input');

  const [isDragging, setIsDragging] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiSuggestion | null>(null);

  const cloudServices = [
    "Cloud Data Governance & Catalog (CDGC)",
    "Cloud Data Quality (CDQ)",
    "Cloud Data Integration (CDI)",
    "MDM SaaS (Customer/Product 360)",
    "Cloud Mass Ingestion (CMI)",
    "Cloud Application Integration (CAI)",
  ];

  const onPremServices = [
    "PowerCenter (PWC)",
    "Informatica Data Quality (IDQ)",
    "MDM Multidomain (On-Prem)",
    "Enterprise Data Catalog (EDC)",
    "PowerExchange (Mainframe/CDC)"
  ];

  // Dynamic Tech Stack based on current selection
  const [availableServices, setAvailableServices] = useState<string[]>(cloudServices);

  useEffect(() => {
    setAvailableServices(formData.deploymentModel === 'Cloud' ? cloudServices : onPremServices);
    // If the currently selected type is invalid for the new model, reset it
    const currentServices = formData.deploymentModel === 'Cloud' ? cloudServices : onPremServices;
    if (!currentServices.includes(formData.solutionType)) {
       setFormData(prev => ({ ...prev, solutionType: '' }));
    }
  }, [formData.deploymentModel]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleDeploymentChange = (model: 'Cloud' | 'On-Premise') => {
    setFormData(prev => ({ ...prev, deploymentModel: model }));
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFormData(prev => ({ ...prev, rfpName: e.dataTransfer.files[0].name }));
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFormData(prev => ({ ...prev, rfpName: e.target.files[0].name }));
    }
  };

  // Trigger AI Analysis after data is entered
  const handleAnalyze = () => {
    setStep('analyzing');

    // Simulate AI Latency
    setTimeout(() => {
      const fileName = formData.rfpName.toLowerCase();
      let suggestion: AiSuggestion | null = null;

      // Logic to determine suggestion based on file name or simple heuristics
      if (fileName.includes('mainframe') || fileName.includes('legacy') || fileName.includes('bank')) {
         suggestion = {
            deployment: 'On-Premise',
            type: "PowerCenter (PWC)",
            reason: "Detected Mainframe/Cobol data sources which typically require data locality.",
            details: [
               "Source: Legacy Mainframe detected.",
               "Compliance: Data Residency identified.",
               "Recommendation: Use PowerExchange with On-Premise PowerCenter."
            ]
         };
      } else if (fileName.includes('consent') || fileName.includes('gdpr') || fileName.includes('governance')) {
         suggestion = {
            deployment: 'Cloud',
            type: "Cloud Data Governance & Catalog (CDGC)",
            reason: "Detected strong governance and lineage requirements.",
            details: [
               "Requirement: Regulatory Compliance (GDPR).",
               "Need: End-to-end Lineage.",
               "Recommendation: IDMC CDGC for automated scanning."
            ]
         };
      } else {
         suggestion = {
            deployment: 'Cloud',
            type: "Cloud Data Integration (CDI)",
            reason: "Standard modernization pattern detected for Cloud Data Warehouse.",
            details: [
               "Target: Snowflake/Databricks.",
               "Pattern: ELT/ETL.",
               "Recommendation: Cloud Native Integration."
            ]
         };
      }

      setAiSuggestion(suggestion);
      setStep('recommendation');
    }, 2500);
  };

  const acceptRecommendation = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        deploymentModel: aiSuggestion.deployment,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      clientName: formData.clientName,
      deploymentModel: formData.deploymentModel,
      type: formData.solutionType,
      rfpFile: formData.rfpName,
      date: new Date().toLocaleDateString(),
    });
  };

  return (
    <div className="p-6 md:p-8 max-w-6xl mx-auto animate-fade-in h-full flex flex-col">
      <div className="mb-8 flex items-center justify-between">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">New Solution Request</h2>
           <p className="text-slate-500">Define requirements or upload RFP for AI analysis.</p>
        </div>

        {/* Progress Stepper */}
        <div className="hidden md:flex items-center gap-2">
           <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold ${step === 'input' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
              <span className="w-5 h-5 rounded-full bg-white/20 flex items-center justify-center">1</span>
              Input
           </div>
           <div className="w-8 h-0.5 bg-slate-200"></div>
           <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold ${step === 'analyzing' ? 'bg-indigo-600 text-white' : step === 'recommendation' ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
              <span className="w-5 h-5 rounded-full bg-white/20 flex items-center justify-center">2</span>
              AI Analysis
           </div>
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* LEFT COLUMN: FORM INPUTS */}
        <div className="lg:col-span-8 flex flex-col">
          <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 md:p-8 flex-1 flex flex-col">

            <div className="space-y-6 flex-1">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Client Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="clientName"
                  required
                  value={formData.clientName}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
                  placeholder="e.g. Acme Corp"
                  disabled={step === 'analyzing'}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  RFP Document <span className="text-red-500">*</span>
                </label>
                <div 
                  className={`
                    border-2 border-dashed rounded-xl h-32 flex flex-col items-center justify-center p-4 text-center transition-colors relative overflow-hidden
                    ${isDragging ? 'border-indigo-500 bg-indigo-50' : 'border-slate-300 hover:border-indigo-400 hover:bg-slate-50'}
                  `}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={handleFileDrop}
                >
                  {formData.rfpName ? (
                    <div className="animate-fade-in w-full flex items-center justify-center gap-4">
                      <div className="w-10 h-10 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center">
                        <CheckCircle size={20} />
                      </div>
                      <div className="text-left">
                         <p className="font-medium text-slate-800 break-all text-sm">{formData.rfpName}</p>
                         <button 
                           type="button"
                           onClick={() => setFormData(prev => ({...prev, rfpName: ''}))}
                           className="text-xs text-red-500 hover:underline"
                           disabled={step === 'analyzing'}
                         >
                           Change File
                         </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="flex items-center gap-2 mb-2 text-slate-500">
                        <UploadCloud size={20} />
                        <span className="font-medium text-sm">Drag & Drop RFP here</span>
                      </div>
                      <input 
                        type="file" 
                        id="file-upload" 
                        className="hidden" 
                        onChange={handleFileSelect}
                        disabled={step === 'analyzing'}
                      />
                      <label 
                        htmlFor="file-upload"
                        className="text-xs text-indigo-600 font-bold hover:underline cursor-pointer"
                      >
                        or browse files
                      </label>
                    </>
                  )}
                </div>
              </div>

              {/* Deployment & Tech Stack (Manual Selection) */}
              <div className={`transition-opacity duration-500 ${step === 'recommendation' ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">
                      Deployment Model
                    </label>
                    <div className="flex p-1 bg-slate-100 rounded-lg border border-slate-200">
                      <button
                        type="button"
                        onClick={() => handleDeploymentChange('Cloud')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all ${formData.deploymentModel === 'Cloud' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                      >
                        <Cloud size={16} /> Cloud
                      </button>
                      <button
                        type="button"
                        onClick={() => handleDeploymentChange('On-Premise')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all ${formData.deploymentModel === 'On-Premise' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                      >
                        <Server size={16} /> On-Premise
                      </button>
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">
                      Technology Stack
                    </label>
                    <div className="relative">
                      <select
                        name="solutionType"
                        value={formData.solutionType}
                        onChange={handleInputChange}
                        className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none appearance-none bg-white transition-all text-sm"
                      >
                        <option value="" disabled>Select {formData.deploymentModel} Service...</option>
                        {availableServices.map(type => (
                          <option key={type} value={type}>{type}</option>
                        ))}
                      </select>
                      <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
                        <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-end gap-4 mt-8">
              {step === 'input' && (
                <button 
                  type="button"
                  onClick={handleAnalyze}
                  disabled={!formData.rfpName || !formData.clientName}
                  className={`
                    flex items-center gap-2 px-6 py-3 rounded-lg text-white font-bold shadow-sm transition-all
                    ${(!formData.rfpName || !formData.clientName) 
                      ? 'bg-slate-300 cursor-not-allowed' 
                      : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-md hover:scale-[1.02]'}
                  `}
                >
                  <Sparkles size={18} />
                  Analyze & Recommend
                </button>
              )}

              {step === 'recommendation' && (
                 <div className="flex gap-4 w-full justify-between items-center bg-emerald-50 p-4 rounded-xl border border-emerald-100 animate-fade-in-up">
                    <div className="flex items-center gap-3">
                       <CheckCircle className="text-emerald-600" size={24} />
                       <div>
                          <p className="text-sm font-bold text-emerald-800">Recommendation Ready</p>
                          <p className="text-xs text-emerald-600">Review the AI suggestion on the right panel.</p>
                       </div>
                    </div>
                    <div className="flex gap-3">
                       <button 
                         type="button"
                         onClick={() => setStep('input')}
                         className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-white rounded-lg transition-colors"
                       >
                         Back
                       </button>
                       <button 
                         type="submit"
                         className="px-6 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-sm flex items-center gap-2 transition-transform hover:scale-105"
                       >
                         Create Design <ArrowRight size={16} />
                       </button>
                    </div>
                 </div>
              )}
            </div>
          </form>
        </div>

        {/* RIGHT COLUMN: AI INSIGHTS */}
        <div className="lg:col-span-4 space-y-6">
           <div className={`bg-slate-900 text-white rounded-xl shadow-xl p-6 relative overflow-hidden transition-all duration-500 h-full flex flex-col ${step === 'analyzing' ? 'ring-4 ring-indigo-500/30' : ''}`}>

             <div className="absolute top-0 right-0 p-4 opacity-10">
                <Cpu size={120} />
             </div>

             <div className="flex items-center gap-2 mb-6 relative z-10">
                <div className="p-2 bg-indigo-500/20 rounded-lg">
                   <Sparkles className="text-indigo-400" size={20} />
                </div>
                <div>
                   <h3 className="font-bold text-lg">Architecture AI</h3>
                   <p className="text-xs text-slate-400">Gemini 3 Pro Engine</p>
                </div>
             </div>

             {step === 'input' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center text-slate-400 space-y-4">
                   <RefreshCw size={40} className="text-slate-700" />
                   <p className="text-sm">Enter client details and upload an RFP to trigger the architectural analysis engine.</p>
                </div>
             )}

             {step === 'analyzing' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center py-12">
                   <div className="relative">
                      <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                      <div className="absolute inset-0 flex items-center justify-center">
                         <div className="w-8 h-8 bg-indigo-500 rounded-full animate-pulse"></div>
                      </div>
                   </div>
                   <h4 className="text-lg font-bold mt-6 mb-2">Analyzing RFP...</h4>
                   <div className="text-xs text-slate-400 space-y-1">
                      <p>Scanning for compliance markers...</p>
                      <p>Identifying integration patterns...</p>
                      <p>Evaluating Cloud vs On-Prem constraints...</p>
                   </div>
                </div>
             )}

             {step === 'recommendation' && aiSuggestion && (
                <div className="animate-fade-in-up flex-1 flex flex-col">
                   <div className="mb-6">
                      <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest border border-indigo-500/30 px-2 py-1 rounded">Optimal Architecture</span>
                      <h2 className="text-2xl font-bold mt-3 mb-1">{aiSuggestion.deployment}</h2>
                      <p className="text-sm text-slate-300">{aiSuggestion.type}</p>
                   </div>

                   <div className="bg-slate-800/50 rounded-lg p-4 mb-4 border border-slate-700">
                      <p className="text-sm text-slate-300 italic">"{aiSuggestion.reason}"</p>
                   </div>

                   <div className="space-y-3 mb-8 flex-1">
                      {aiSuggestion.details.map((detail, idx) => (
                         <div key={idx} className="flex items-start gap-3 text-xs text-slate-400">
                            <CheckCircle size={14} className="text-emerald-500 mt-0.5 shrink-0" />
                            <span>{detail}</span>
                         </div>
                      ))}
                   </div>

                   {(formData.deploymentModel !== aiSuggestion.deployment || formData.solutionType !== aiSuggestion.type) && (
                      <button 
                        onClick={acceptRecommendation}
                        className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-xl transition-all flex items-center justify-center gap-2 hover:shadow-lg hover:shadow-indigo-500/20"
                      >
                        <Sparkles size={16} /> Apply AI Recommendation
                      </button>
                   )}
                   {(formData.deploymentModel === aiSuggestion.deployment && formData.solutionType === aiSuggestion.type) && (
                      <div className="w-full bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2">
                         <CheckCircle size={16} /> Recommendation Applied
                      </div>
                   )}
                </div>
             )}

           </div>
        </div>
      </div>
    </div>
  );
};

