import React, { useState, useEffect } from 'react';
import { 
  CloudLightning, 
  Loader, 
  CheckCircle, 
  UploadCloud, 
  Sparkles, 
  RefreshCw, 
  ArrowRight,
  Server,
  Cloud,
  Cpu,
  Users,
  Code2,
  ShieldAlert,
  Beaker
} from 'lucide-react';
import { AiSuggestion } from '../types';

interface CreateFormProps {
  onSubmit: (data: any) => void;
  onCancel: () => void;
}

const CreateForm: React.FC<CreateFormProps> = ({ onSubmit, onCancel }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpName: '',
    deploymentModel: 'Cloud' as 'Cloud' | 'On-Premise',
    solutionType: '',
    targetAudience: ['Developer'] as string[], // Default
    description: '',
    priority: 'Normal'
  });

  const [step, setStep] = useState<'input' | 'analyzing' | 'recommendation'>('input');
  const [isDragging, setIsDragging] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiSuggestion | null>(null);

  const cloudServices = [
    "Cloud Data Governance & Catalog (CDGC)",
    "Cloud Data Quality (CDQ)",
    "Cloud Data Integration (CDI)",
    "MDM SaaS (Customer/Product 360)",
    "Cloud Mass Ingestion (CMI)",
    "Cloud Application Integration (CAI)",
  ];

  const onPremServices = [
    "PowerCenter (PWC)",
    "Informatica Data Quality (IDQ)",
    "MDM Multidomain (On-Prem)",
    "Enterprise Data Catalog (EDC)",
    "PowerExchange (Mainframe/CDC)"
  ];

  const roles = [
    { id: 'Developer', label: 'Developer', icon: Code2, desc: 'Technical specs & mappings' },
    { id: 'Tester', label: 'Tester', icon: Beaker, desc: 'Test data & validation' },
    { id: 'Admin', label: 'Admin', icon: ShieldAlert, desc: 'Security & Infrastructure' }
  ];

  const [availableServices, setAvailableServices] = useState<string[]>(cloudServices);

  useEffect(() => {
    setAvailableServices(formData.deploymentModel === 'Cloud' ? cloudServices : onPremServices);
    const currentServices = formData.deploymentModel === 'Cloud' ? cloudServices : onPremServices;
    if (!currentServices.includes(formData.solutionType)) {
       setFormData(prev => ({ ...prev, solutionType: '' }));
    }
  }, [formData.deploymentModel]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const toggleRole = (roleId: string) => {
    setFormData(prev => {
      const current = prev.targetAudience;
      if (current.includes(roleId)) {
        if (current.length === 1) return prev; // Prevent empty
        return { ...prev, targetAudience: current.filter(r => r !== roleId) };
      } else {
        return { ...prev, targetAudience: [...current, roleId] };
      }
    });
  };

  const handleDeploymentChange = (model: 'Cloud' | 'On-Premise') => {
    setFormData(prev => ({ ...prev, deploymentModel: model }));
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFormData(prev => ({ ...prev, rfpName: e.dataTransfer.files[0].name }));
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFormData(prev => ({ ...prev, rfpName: e.target.files[0].name }));
    }
  };

  const handleAnalyze = () => {
    setStep('analyzing');
    setTimeout(() => {
      const fileName = formData.rfpName.toLowerCase();
      let suggestion: AiSuggestion | null = null;

      if (fileName.includes('mainframe') || fileName.includes('legacy')) {
         suggestion = {
            deployment: 'On-Premise',
            type: "PowerCenter (PWC)",
            reason: "Detected Mainframe/Cobol data sources.",
            details: ["Source: Legacy Mainframe.", "Compliance: Data Residency."]
         };
      } else if (fileName.includes('consent') || fileName.includes('gdpr')) {
         suggestion = {
            deployment: 'Cloud',
            type: "Cloud Data Governance & Catalog (CDGC)",
            reason: "Detected governance requirements.",
            details: ["Requirement: GDPR.", "Need: Lineage."]
         };
      } else {
         suggestion = {
            deployment: 'Cloud',
            type: "Cloud Data Integration (CDI)",
            reason: "Standard Cloud Modernization pattern.",
            details: ["Target: Snowflake.", "Pattern: ELT."]
         };
      }
      setAiSuggestion(suggestion);
      setStep('recommendation');
    }, 2500);
  };

  const acceptRecommendation = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        deploymentModel: aiSuggestion.deployment,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      clientName: formData.clientName,
      deploymentModel: formData.deploymentModel,
      type: formData.solutionType,
      rfpFile: formData.rfpName,
      targetAudience: formData.targetAudience,
      date: new Date().toLocaleDateString(),
    });
  };

  return (
    <div className="p-6 md:p-8 max-w-6xl mx-auto animate-fade-in h-full flex flex-col">
      <div className="mb-8 flex items-center justify-between">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">New Solution Request</h2>
           <p className="text-slate-500">Define requirements and target audience for AI analysis.</p>
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 flex flex-col">
          <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 md:p-8 flex-1 flex flex-col">
            <div className="space-y-6 flex-1">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Client Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="clientName"
                  required
                  value={formData.clientName}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="e.g. Acme Corp"
                  disabled={step === 'analyzing'}
                />
              </div>

              {/* Roles Section */}
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                   Target Design Audience <span className="text-red-500">*</span>
                </label>
                <p className="text-xs text-slate-500 mb-3">Gemini will tailor the output based on selected roles.</p>
                <div className="grid grid-cols-3 gap-3">
                  {roles.map((role) => {
                    const isSelected = formData.targetAudience.includes(role.id);
                    return (
                      <button
                        key={role.id}
                        type="button"
                        onClick={() => toggleRole(role.id)}
                        className={`
                          p-3 rounded-lg border text-left transition-all
                          ${isSelected 
                            ? 'bg-indigo-50 border-indigo-500 ring-1 ring-indigo-500' 
                            : 'bg-white border-slate-200 hover:border-slate-400'}
                        `}
                      >
                         <div className="flex items-center gap-2 mb-1">
                            <role.icon size={16} className={isSelected ? 'text-indigo-600' : 'text-slate-400'} />
                            <span className={`text-sm font-bold ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{role.label}</span>
                         </div>
                         <p className="text-[10px] text-slate-500 leading-tight">{role.desc}</p>
                      </button>
                    );
                  })}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  RFP Document <span className="text-red-500">*</span>
                </label>
                <div 
                  className={`
                    border-2 border-dashed rounded-xl h-24 flex flex-col items-center justify-center p-4 text-center transition-colors relative overflow-hidden
                    ${isDragging ? 'border-indigo-500 bg-indigo-50' : 'border-slate-300 hover:border-indigo-400 hover:bg-slate-50'}
                  `}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={handleFileDrop}
                >
                  {formData.rfpName ? (
                    <div className="animate-fade-in w-full flex items-center justify-center gap-4">
                      <div className="w-8 h-8 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center">
                        <CheckCircle size={16} />
                      </div>
                      <div className="text-left">
                         <p className="font-medium text-slate-800 break-all text-sm">{formData.rfpName}</p>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="flex items-center gap-2 mb-1 text-slate-500">
                        <UploadCloud size={20} />
                        <span className="font-medium text-sm">Drag & Drop RFP</span>
                      </div>
                      <input type="file" id="file-upload" className="hidden" onChange={handleFileSelect} disabled={step === 'analyzing'} />
                      <label htmlFor="file-upload" className="text-xs text-indigo-600 font-bold hover:underline cursor-pointer">or browse files</label>
                    </>
                  )}
                </div>
              </div>

              <div className={`transition-opacity duration-500 ${step === 'recommendation' ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Deployment Model</label>
                    <div className="flex p-1 bg-slate-100 rounded-lg border border-slate-200">
                      <button type="button" onClick={() => handleDeploymentChange('Cloud')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all ${formData.deploymentModel === 'Cloud' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
                        <Cloud size={16} /> Cloud
                      </button>
                      <button type="button" onClick={() => handleDeploymentChange('On-Premise')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all ${formData.deploymentModel === 'On-Premise' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
                        <Server size={16} /> On-Premise
                      </button>
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Technology Stack</label>
                    <div className="relative">
                      <select name="solutionType" value={formData.solutionType} onChange={handleInputChange} className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none appearance-none bg-white transition-all text-sm">
                        <option value="" disabled>Select {formData.deploymentModel} Service...</option>
                        {availableServices.map(type => <option key={type} value={type}>{type}</option>)}
                      </select>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-end gap-4 mt-8">
              {step === 'input' && (
                <button type="button" onClick={handleAnalyze} disabled={!formData.rfpName || !formData.clientName} className={`flex items-center gap-2 px-6 py-3 rounded-lg text-white font-bold shadow-sm transition-all ${(!formData.rfpName || !formData.clientName) ? 'bg-slate-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
                  <Sparkles size={18} /> Analyze & Recommend
                </button>
              )}
              {step === 'recommendation' && (
                 <div className="flex gap-4 w-full justify-between items-center bg-emerald-50 p-4 rounded-xl border border-emerald-100 animate-fade-in-up">
                    <div className="flex items-center gap-3">
                       <CheckCircle className="text-emerald-600" size={24} />
                       <div><p className="text-sm font-bold text-emerald-800">Recommendation Ready</p></div>
                    </div>
                    <div className="flex gap-3">
                       <button type="button" onClick={() => setStep('input')} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-white rounded-lg">Back</button>
                       <button type="submit" className="px-6 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-sm flex items-center gap-2">Create Design <ArrowRight size={16} /></button>
                    </div>
                 </div>
              )}
            </div>
          </form>
        </div>

        <div className="lg:col-span-4 space-y-6">
           <div className={`bg-slate-900 text-white rounded-xl shadow-xl p-6 relative overflow-hidden transition-all duration-500 h-full flex flex-col ${step === 'analyzing' ? 'ring-4 ring-indigo-500/30' : ''}`}>
             <div className="absolute top-0 right-0 p-4 opacity-10"><Cpu size={120} /></div>
             <div className="flex items-center gap-2 mb-6 relative z-10">
                <div className="p-2 bg-indigo-500/20 rounded-lg"><Sparkles className="text-indigo-400" size={20} /></div>
                <div><h3 className="font-bold text-lg">Architecture AI</h3><p className="text-xs text-slate-400">Gemini 3 Pro Engine</p></div>
             </div>
             {step === 'input' && <div className="flex-1 flex flex-col items-center justify-center text-center text-slate-400 space-y-4"><RefreshCw size={40} className="text-slate-700" /><p className="text-sm">Enter client details, select audience roles, and upload RFP.</p></div>}
             {step === 'analyzing' && <div className="flex-1 flex flex-col items-center justify-center text-center py-12"><div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div><h4 className="text-lg font-bold mt-6 mb-2">Analyzing RFP...</h4><p className="text-xs text-slate-400">Tailoring for: {formData.targetAudience.join(', ')}</p></div>}
             {step === 'recommendation' && aiSuggestion && (
                <div className="animate-fade-in-up flex-1 flex flex-col">
                   <div className="mb-6"><span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest border border-indigo-500/30 px-2 py-1 rounded">Optimal Architecture</span><h2 className="text-2xl font-bold mt-3 mb-1">{aiSuggestion.deployment}</h2><p className="text-sm text-slate-300">{aiSuggestion.type}</p></div>
                   <div className="bg-slate-800/50 rounded-lg p-4 mb-4 border border-slate-700"><p className="text-sm text-slate-300 italic">"{aiSuggestion.reason}"</p></div>
                   {(formData.deploymentModel !== aiSuggestion.deployment || formData.solutionType !== aiSuggestion.type) && (
                      <button onClick={acceptRecommendation} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-xl transition-all flex items-center justify-center gap-2"><Sparkles size={16} /> Apply AI Recommendation</button>
                   )}
                </div>
             )}
           </div>
        </div>
      </div>
    </div>
  );
};

export default CreateForm;

import React, { useRef, useState } from 'react';
import { 
  Database, 
  Server, 
  CloudLightning, 
  Settings, 
  Share2, 
  Code,
  BrainCircuit,
  CheckCircle,
  Loader,
  X,
  Copy,
  Check,
  Image as ImageIcon,
  FileCode,
  Sparkles,
  Zap,
  Info
} from 'lucide-react';
import { Node, Edge, RefinementSuggestion, DesignData } from '../types';
import { generateDesignRefinements } from '../services/geminiService';

interface ArchitectureCanvasProps {
  aiNodes: Node[];
  aiEdges: Edge[];
  isThinking: boolean;
  thoughts: string[];
  context?: string; 
  audience?: string[];
  onApplyRefinement?: (newDesign: DesignData) => void;
}

const ArchitectureCanvas: React.FC<ArchitectureCanvasProps> = ({ 
  aiNodes, 
  aiEdges, 
  isThinking, 
  thoughts,
  context = "",
  audience = [],
  onApplyRefinement
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [showMermaid, setShowMermaid] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Refinement State
  const [showInsights, setShowInsights] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [suggestions, setSuggestions] = useState<RefinementSuggestion[]>([]);

  // Hover State
  const [hoveredNode, setHoveredNode] = useState<Node | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const getMermaidCode = () => {
    if (!aiNodes.length) return "graph LR\n  NoData[No Design Generated]";
    let code = "graph LR\n";
    code += "  classDef source fill:#eff6ff,stroke:#3b82f6,stroke-width:2px,color:#1e40af;\n";
    code += "  classDef stage fill:#f1f5f9,stroke:#64748b,stroke-width:2px,color:#334155;\n";
    code += "  classDef process fill:#fff7ed,stroke:#f97316,stroke-width:2px,color:#9a3412;\n";
    code += "  classDef target fill:#ecfdf5,stroke:#10b981,stroke-width:2px,color:#065f46;\n\n";

    aiNodes.forEach(node => {
      const label = node.label.replace(/"/g, "'");
      code += `  ${node.id}["${label}"]:::${node.type}\n`;
    });
    code += "\n";
    aiEdges.forEach(edge => {
      const label = edge.label ? `|"${edge.label}"|` : "";
      code += `  ${edge.from} -->${label} ${edge.to}\n`;
    });
    return code;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getMermaidCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleExport = (format: 'svg' | 'png') => {
    if (!svgRef.current) return;
    const svgEl = svgRef.current;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svgEl);
    if(!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)){
        source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    source = '<?xml version="1.0" standalone="no"?>\r\n' + source;
    const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);

    if (format === 'svg') {
        const link = document.createElement("a");
        link.href = url;
        link.download = "architecture-design.svg";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        const img = new Image();
        img.src = url;
        img.onload = () => {
            const canvas = document.createElement("canvas");
            canvas.width = 1000; 
            canvas.height = 300;
            const ctx = canvas.getContext("2d");
            if (ctx) {
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                const link = document.createElement("a");
                link.href = canvas.toDataURL("image/png");
                link.download = "architecture-design.png";
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        };
    }
    setShowExportMenu(false);
  };

  const handleFetchRefinements = async () => {
    if (!context || !aiNodes.length) return;
    setIsRefining(true);
    setShowInsights(true);
    setSuggestions([]);
    try {
      const currentDesign = { nodes: aiNodes, edges: aiEdges };
      const newSuggestions = await generateDesignRefinements(currentDesign, context, audience);
      setSuggestions(newSuggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefining(false);
    }
  };

  const applySuggestion = (suggestion: RefinementSuggestion) => {
    if (onApplyRefinement) {
      onApplyRefinement(suggestion.suggestedDesign);
      setSuggestions(prev => prev.filter(s => s.id !== suggestion.id)); 
    }
  };

  return (
    <div className="flex flex-col h-full relative group">
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center z-20">
        <div>
          <h3 className="font-bold text-slate-800">High Level Design (HLD)</h3>
          <p className="text-xs text-slate-500 hidden sm:block">
            {isThinking ? "Gemini is analyzing requirements..." : "Hover over nodes for role-specific technical details"}
          </p>
        </div>

        <div className="flex items-center gap-2 relative">
           <button onClick={handleFetchRefinements} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 border border-indigo-100 px-3 py-1.5 rounded hover:bg-indigo-100 transition-colors mr-2">
             <Sparkles size={14} className={isRefining ? 'animate-spin' : ''} />
             <span className="hidden sm:inline">Gemini Insights</span>
           </button>

          <div className="relative">
             <button onClick={() => setShowExportMenu(!showExportMenu)} className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50 transition-colors">
                <Share2 size={14} /> <span className="hidden sm:inline">Export</span>
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-1 w-32 bg-white rounded-lg shadow-xl border border-slate-200 py-1 z-30">
                   <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><ImageIcon size={14} /> PNG Image</button>
                   <button onClick={() => handleExport('svg')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><FileCode size={14} /> SVG Vector</button>
                </div>
             )}
          </div>
          <button onClick={() => setShowMermaid(true)} className="flex items-center gap-2 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700 transition-colors">
            <Code size={14} /> <span className="hidden sm:inline">Mermaid</span>
          </button>
        </div>
      </div>

      <div className="flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">

        {/* Gemini Insights Floating Panel */}
        {showInsights && (
           <div className="absolute top-4 left-4 z-20 w-72 bg-white/95 backdrop-blur-md rounded-xl shadow-xl border border-indigo-100 overflow-hidden flex flex-col max-h-[80%] animate-fade-in-up">
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 p-3 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2"><BrainCircuit size={16} /><span className="font-bold text-sm">Design Analysis</span></div>
                 <button onClick={() => setShowInsights(false)} className="hover:bg-white/20 rounded p-1"><X size={14} /></button>
              </div>
              <div className="p-4 overflow-y-auto flex-1">
                 {isRefining ? (
                    <div className="flex flex-col items-center justify-center py-8 text-center"><Loader size={24} className="text-indigo-500 animate-spin mb-2" /><p className="text-xs text-slate-500 font-medium">Comparing with learned patterns...</p></div>
                 ) : suggestions.length > 0 ? (
                    <div className="space-y-3">
                       {suggestions.map((sug) => (
                          <div key={sug.id} className="bg-indigo-50 border border-indigo-100 rounded-lg p-3">
                             <div className="flex justify-between items-start mb-1"><h5 className="font-bold text-slate-800 text-xs">{sug.title}</h5><span className="text-[9px] uppercase font-bold text-indigo-600 bg-white px-1.5 py-0.5 rounded border border-indigo-100">{sug.impact}</span></div>
                             <p className="text-[10px] text-slate-600 mb-2 leading-relaxed">{sug.description}</p>
                             <button onClick={() => applySuggestion(sug)} className="w-full bg-white text-indigo-600 text-xs font-bold py-1.5 rounded border border-indigo-200 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1"><Zap size={10} /> Apply Optimization</button>
                          </div>
                       ))}
                    </div>
                 ) : (
                    <div className="text-center py-4 text-slate-400 text-xs"><CheckCircle size={24} className="mx-auto mb-2 text-emerald-400" /><p>No major refinements found.</p></div>
                 )}
              </div>
           </div>
        )}

        {/* Hover Tooltip */}
        {hoveredNode && (
          <div 
            className="absolute z-50 bg-slate-900 text-white p-3 rounded-lg shadow-xl max-w-xs pointer-events-none animate-fade-in text-xs border border-slate-700"
            style={{ 
              left: `${tooltipPos.x}px`, 
              top: `${tooltipPos.y - 10}px`,
              transform: 'translate(-50%, -100%)'
            }}
          >
             <div className="font-bold mb-1 flex items-center gap-2 border-b border-slate-700 pb-1">
               <Info size={12} className="text-indigo-400" />
               {hoveredNode.label}
             </div>
             <p className="text-slate-300 leading-relaxed">
               {hoveredNode.description || "No technical details available for this node."}
             </p>
          </div>
        )}

        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/95 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm transition-opacity duration-300">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse"><BrainCircuit className="text-white" size={24} /></div>
                   <div><h4 className="font-bold text-slate-800 text-lg">Gemini Thinking...</h4><p className="text-xs text-slate-500">Model: gemini-3-pro-preview</p></div>
                </div>
                <div className="space-y-3 font-mono text-xs max-h-60 overflow-y-auto">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.3}s`}}><CheckCircle size={14} className="text-emerald-500 flex-shrink-0" /><span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200 shadow-sm">{thought}</span></div>
                   ))}
                </div>
             </div>
          </div>
        )}

        <svg 
            ref={svgRef} 
            width="100%" 
            height="100%" 
            viewBox="0 0 1000 300" 
            className="w-full h-full select-none"
            preserveAspectRatio="xMidYMid meet"
        >
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>
          <rect x="0" y="0" width="1000" height="300" fill="#ffffff" />

          {aiEdges && aiEdges.map((edge, i) => {
            const source = aiNodes.find(n => n.id === edge.from);
            const target = aiNodes.find(n => n.id === edge.to);
            if (!source || !target) return null;
            const sourceX = source.x + 160; 
            const sourceY = source.y + 40;  
            const targetX = target.x;
            const targetY = target.y + 40;
            const controlPointOffset = 60;
            return (
              <g key={i} className="animate-fade-in" style={{animationDelay: '0.5s'}}>
                <path d={`M ${sourceX} ${sourceY} C ${sourceX + controlPointOffset} ${sourceY}, ${targetX - controlPointOffset} ${targetY}, ${targetX} ${targetY}`} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />
                <rect x={(sourceX + targetX)/2 - 40} y={(sourceY + targetY)/2 - 10} width="80" height="20" rx="4" fill="white" stroke="#e2e8f0" strokeWidth="1" />
                <text x={(sourceX + targetX)/2} y={(sourceY + targetY)/2 + 4} textAnchor="middle" fontSize="10" fill="#64748b" fontWeight="600" style={{ fontFamily: 'Inter, sans-serif' }}>{edge.label}</text>
              </g>
            );
          })}

          {aiNodes && aiNodes.map((node, i) => {
             return (
               <foreignObject 
                 x={node.x} y={node.y} width="160" height="80" key={node.id} 
                 className="animate-fade-in-up overflow-visible" 
                 style={{animationDelay: `${i * 0.1}s`}}
               >
                 <div 
                    className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white relative
                    ${node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                      node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                      node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                      'bg-white border-slate-300'}`}
                    onMouseEnter={(e) => {
                      const rect = e.currentTarget.getBoundingClientRect();
                      // Calculate position relative to svg/canvas container (which we assume spans the screen roughly)
                      // A simpler approach for the SVG overlay is passing x,y coords directly
                      setTooltipPos({ x: node.x + 80, y: node.y });
                      setHoveredNode(node);
                    }}
                    onMouseLeave={() => setHoveredNode(null)}
                 >
                    <div className="mb-1">
                      {node.type === 'source' && <Database size={20} className="text-blue-600" />}
                      {node.type === 'stage' && <Server size={20} className="text-slate-600" />}
                      {node.type === 'process' && <Settings size={20} className="text-orange-600 animate-spin-slow" />}
                      {node.type === 'target' && <CloudLightning size={20} className="text-emerald-600" />}
                    </div>
                    <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">{node.label}</span>
                 </div>
               </foreignObject>
             );
          })}
        </svg>
      </div>

      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50"><h3 className="font-bold text-slate-800 flex items-center gap-2"><Code size={18} className="text-blue-600" /> Mermaid.js Diagram Code</h3><button onClick={() => setShowMermaid(false)} className="text-slate-400 hover:text-slate-700 transition-colors"><X size={20} /></button></div>
            <div className="flex-1 p-0 overflow-hidden relative group/code"><pre className="w-full h-full p-6 bg-slate-900 text-blue-100 font-mono text-xs overflow-auto">{getMermaidCode()}</pre><button onClick={copyToClipboard} className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg backdrop-blur-md transition-all border border-white/10">{copied ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}</button></div>
            <div className="p-4 border-t border-slate-200 flex justify-end gap-2 bg-slate-50"><button onClick={() => setShowMermaid(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition-colors">Close</button><button onClick={copyToClipboard} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors flex items-center gap-2">{copied ? 'Copied!' : 'Copy Code'}</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ArchitectureCanvas;

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Bot, User, Minimize2 } from 'lucide-react';
import { sendChatMessage } from '../services/geminiService';

interface AiAssistantProps {
  context: string;
}

const AiAssistant: React.FC<AiAssistantProps> = ({ context }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{role: 'user' | 'model', text: string}[]>([
    { role: 'model', text: 'Hi! I am Gemini Architect. Ask me anything about this solution design.' }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const newMsg = { role: 'user' as const, text: input };
    setMessages(prev => [...prev, newMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ role: m.role, text: m.text }));
    const response = await sendChatMessage(history, input, context);

    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end">
      {isOpen ? (
        <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-80 md:w-96 h-[500px] flex flex-col overflow-hidden animate-fade-in-up">
          {/* Header */}
          <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-4 flex justify-between items-center text-white">
            <div className="flex items-center gap-2">
              <div className="bg-white/20 p-1 rounded-full"><Bot size={18} /></div>
              <div>
                <h3 className="font-bold text-sm">Gemini Architect</h3>
                <p className="text-[10px] text-indigo-100 flex items-center gap-1">
                   <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></span> Online
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1.5 rounded-lg transition-colors">
                <Minimize2 size={16} />
              </button>
            </div>
          </div>

          {/* Chat Area */}
          <div className="flex-1 overflow-y-auto p-4 bg-slate-50 space-y-4" ref={scrollRef}>
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] rounded-2xl px-4 py-2.5 text-xs md:text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-br-none' 
                    : 'bg-white border border-slate-200 text-slate-700 rounded-bl-none shadow-sm'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isTyping && (
               <div className="flex justify-start">
                  <div className="bg-white border border-slate-200 rounded-2xl rounded-bl-none px-4 py-3 shadow-sm">
                     <div className="flex gap-1">
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></span>
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></span>
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></span>
                     </div>
                  </div>
               </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-slate-100 flex gap-2">
            <input 
              type="text" 
              className="flex-1 bg-slate-100 border-transparent focus:bg-white focus:ring-2 focus:ring-indigo-500 rounded-xl px-4 py-2 text-sm outline-none transition-all"
              placeholder="Ask about architecture..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button 
              onClick={handleSend}
              disabled={!input.trim()}
              className="bg-indigo-600 text-white p-2.5 rounded-xl hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-indigo-600 hover:bg-indigo-700 text-white p-4 rounded-full shadow-lg shadow-indigo-500/30 transition-all hover:scale-110 flex items-center gap-2 group"
        >
          <Bot size={24} />
          <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-300 font-bold whitespace-nowrap">Chat with Gemini</span>
        </button>
      )}
    </div>
  );
};

export default AiAssistant;

import React, { useState, useEffect } from 'react';
import { 
  Download, 
  List, 
  Workflow, 
  Server, 
  CheckCircle, 
  ClipboardList, 
  Plus, 
  Sparkles, 
  PenTool, 
  Lightbulb, 
  ThumbsUp, 
  MessageSquare, 
  Send,
  ShieldCheck,
  Network,
  Key,
  Flag,
  FileText,
  Clock,
  Database,
  Users,
  Lock,
  Zap,
  BookOpen
} from 'lucide-react';
import { RequestData, DesignData, Question, Requirement, DesignCache, CachedRequestData, InitiationItem } from '../types';
