          description: { type: Type.STRING, description: "Detailed technical description for hover tooltip" },
          type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target'] },
          x: { type: Type.NUMBER },
          y: { type: Type.NUMBER },
        },
        required: ['id', 'label', 'type', 'x', 'y'],
      },
    },
    edges: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          from: { type: Type.STRING },
          to: { type: Type.STRING },
          label: { type: Type.STRING },
        },
        required: ['from', 'to', 'label'],
      },
    },
  },
  required: ['nodes', 'edges'],
};

const requirementsSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    requirements: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Infrastructure', 'Network', 'Security', 'License', 'Development', 'Testing', 'Admin'] },
          item: { type: Type.STRING },
          description: { type: Type.STRING },
          criticality: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
          audience: { type: Type.STRING, description: "Who this requirement is relevant for (e.g. Developer, Admin)"}
        },
        required: ['id', 'category', 'item', 'description', 'criticality'],
      },
    },
  },
  required: ['requirements'],
};

const initiationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    sections: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          iconType: { type: Type.STRING, enum: ['Users', 'Database', 'Zap', 'Lock', 'Clock'] },
          items: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ['title', 'iconType', 'items']
      }
    }
  },
  required: ['sections']
};

const questionnaireSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    questions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
