} from '../services/geminiService';

interface SolutionDesignViewProps {
  request: RequestData | null;
  designCache: DesignCache;
  onUpdateDesignCache: (reqId: string, data: CachedRequestData) => void;
}

const extractTextFromMock = (files: string[]) => {
  const combinedText = files.join(' ');
  // Basic mock simulation of context based on filenames
  if (combinedText.includes("AA Motors") || combinedText.includes("HANA")) return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer (B2C). Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta.";
  if (combinedText.includes("Vehicle") || combinedText.includes("Adobe")) return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM.";
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB (Oracle). Target: Cloud Data Warehouse (Snowflake). Pattern: Batch ETL. Security: End-to-end encryption required.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState<'initiation' | 'design' | 'requirements' | 'scoping' | 'attachments'>('design');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);

  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [questions, setQuestions] = useState<Question[]>([]);
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [initiationItems, setInitiationItems] = useState<InitiationItem[]>([]);

  // Local state for handling new uploads in this view
  const [localFiles, setLocalFiles] = useState<string[]>([]);

  const [refinementPrompt, setRefinementPrompt] = useState("");

  useEffect(() => {
    if (request) {
      setLocalFiles(request.rfpFiles || []); // Sync files
      if (designCache[request.id]) {
        const cached = designCache[request.id];
        setCurrentDesign(cached.design);
        setQuestions(cached.questions);
        setRequirements(cached.requirements);
        setInitiationItems(cached.initiation || []);
        setStatus(cached.status);
      } else {
        setStatus('idle');
        setCurrentDesign({ nodes: [], edges: [] });
        setQuestions([]);
        setRequirements([]);
        setInitiationItems([]);
      }
    }
  }, [request, designCache]);

  const handleGenerate = async (promptOverride: string | null = null) => {
    if (!request) return;
    setStatus('thinking');
    setThoughts([]);

    const audience = request.targetAudience || ['Developer']; // Fallback
    const baseThoughts = [
      `Reading ${localFiles.length} Documents...`,
      `Synthesizing technical architecture...`,
      "Analyzing MDM & Governance patterns...",
      "Drafting HLD Diagram..."
    ];

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 600)); 
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    const context = extractTextFromMock(localFiles) + (promptOverride ? ` Refinement: ${promptOverride}` : "");

    try {
      // NOTE: generateArchitectureDesign NO LONGER takes 'audience' to keep design pure technical
      const design = await generateArchitectureDesign(context, request.type);

      const [generatedQuestions, generatedRequirements, generatedInitiation] = await Promise.all([
        generateIntelligentQuestionnaire(context, request.type, audience),
        generateProjectRequirements(context, request.type, audience),
        generateInitiationChecklist(context, request.type, audience)
      ]);

      setCurrentDesign(design);
      setQuestions(generatedQuestions);
      setRequirements(generatedRequirements);
      setInitiationItems(generatedInitiation);
      setStatus('review');
    } catch (e) {
      console.error("Generation failed", e);
      setStatus('idle');
    }
  };

  const handleAcceptDesign = () => {
    if (request) {
      const cacheData: CachedRequestData = {
        design: currentDesign,
        questions: questions,
        requirements: requirements,
        initiation: initiationItems,
        status: 'accepted'
      };
      onUpdateDesignCache(request.id, cacheData);
      setStatus('accepted');
      const context = extractTextFromMock(localFiles);
      learnFromProject(context, currentDesign, request.targetAudience);
    }
  };

  const handleUpdateDesignFromRefinement = (newDesign: DesignData) => {
     setCurrentDesign(newDesign);
  };

  const handleAddFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFileName = e.target.files[0].name;
      if (!localFiles.includes(newFileName)) {
        setLocalFiles(prev => [...prev, newFileName]);
      }
    }
  };

  if (!request) return <div className="p-8 text-center text-slate-400">Select a request...</div>;

  const getCriticalityColor = (level: string) => {
    switch(level) {
      case 'High': return 'bg-red-100 text-red-700 border-red-200';
      case 'Medium': return 'bg-orange-100 text-orange-700 border-orange-200';
      default: return 'bg-blue-100 text-blue-700 border-blue-200';
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-fade-in relative">
      <AiAssistant context={extractTextFromMock(localFiles)} />

      <div className="bg-white border-b border-slate-200 px-8 py-4 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-3 mb-1">
            <h2 className="text-xl font-bold text-slate-800">{request.id}: {request.clientName}</h2>
            <div className="flex gap-1">
               <span className="px-2 py-0.5 rounded text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">{request.type}</span>
               {request.targetAudience?.map(role => (
                 <span key={role} className="px-2 py-0.5 rounded text-xs font-bold bg-indigo-50 text-indigo-600 border border-indigo-100">{role}</span>
               ))}
            </div>
          </div>
          <p className="text-xs text-slate-500">AI Managed • Context Aware</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 hide-scrollbar">
          {['attachments', 'initiation', 'design', 'requirements', 'scoping'].map((tab) => (
             <button 
               key={tab}
               onClick={() => setActiveSubTab(tab as any)}
               className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap capitalize ${activeSubTab === tab ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
             >
               {tab}
             </button>
          ))}
        </div>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">

        {activeSubTab === 'attachments' && (
          <div className="max-w-4xl mx-auto animate-fade-in">
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
               <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                  <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                    <Paperclip className="text-indigo-500" /> Attached Documents
                  </h3>
                  <div className="flex gap-2">
                    <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-medium transition-colors">
                      <Plus size={16} /> Add Document
                      <input type="file" className="hidden" onChange={handleAddFile} />
                    </label>
                  </div>
               </div>

               <div className="space-y-3 mb-8">
                  {localFiles.length === 0 ? (
                    <p className="text-slate-400 text-center py-8">No documents attached.</p>
                  ) : (
                    localFiles.map((file, idx) => (
                      <div key={idx} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-200 group">
                        <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center">
                            <FileText size={20} />
                          </div>
                          <div>
                            <p className="text-sm font-bold text-slate-800">{file}</p>
                            <p className="text-xs text-slate-500">Uploaded Doc</p>
                          </div>
                        </div>
                        <button className="text-slate-400 hover:text-red-500 transition-colors">
                          <X size={18} />
                        </button>
                      </div>
                    ))
                  )}
               </div>

               <div className="bg-orange-50 rounded-xl p-6 border border-orange-100 flex items-center justify-between">
                  <div>
                    <h4 className="font-bold text-orange-900 mb-1">Context Changed?</h4>
                    <p className="text-sm text-orange-700">If you've added new documents, regenerate the design to include new context.</p>
                  </div>
                  <button 
                    onClick={() => handleGenerate()} 
                    className="flex items-center gap-2 px-6 py-3 bg-orange-600 hover:bg-orange-700 text-white font-bold rounded-lg shadow-sm transition-all"
                  >
                    <RefreshCw size={18} /> Regenerate Design
                  </button>
               </div>
             </div>
          </div>
        )}

        {activeSubTab === 'initiation' && (
          <div className="max-w-6xl mx-auto animate-fade-in">
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
               <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
                  <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><BookOpen className="text-orange-500" /> AI-Generated Initiation Checklist</h3>
                  <button className="text-sm text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg">Export</button>
               </div>
               {initiationItems.length === 0 ? (
                 <div className="text-center py-8"><p className="text-slate-400">Generate the solution to see the checklist.</p></div>
               ) : (
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                   {initiationItems.map((sec, idx) => (
                     <div key={idx} className="bg-slate-50 rounded-xl p-5 border border-slate-200">
                        <div className="flex items-center gap-3 mb-4"><div className="bg-white p-2 rounded-lg shadow-sm"><CheckCircle size={20} className="text-blue-500"/></div><h4 className="font-bold text-slate-800 text-sm">{sec.title}</h4></div>
                        <ul className="space-y-3">{sec.items.map((it, i) => <li key={i} className="flex items-start gap-2 text-sm text-slate-600"><div className="mt-1 w-1.5 h-1.5 bg-slate-300 rounded-full shrink-0"/>{it}</li>)}</ul>
                     </div>
                   ))}
                 </div>
               )}
             </div>
          </div>
        )}

        {activeSubTab === 'requirements' && (
           <div className="max-w-6xl mx-auto space-y-6 animate-fade-in">
              <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                 <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><List className="text-blue-500" /> Role-Based Requirements</h3>
                 {requirements.length === 0 ? <p className="text-slate-400">No requirements generated.</p> : (
                    <div className="grid grid-cols-1 gap-4">
                      {requirements.map((req, i) => (
                        <div key={i} className="flex items-start gap-4 p-4 rounded-lg bg-slate-50 border border-slate-100">
                          <div className="p-2 rounded-lg bg-white border border-slate-200 text-slate-600"><CheckCircle size={18} /></div>
                          <div className="flex-1">
                             <div className="flex justify-between items-start mb-1">
                               <h4 className="font-semibold text-slate-800 text-sm">{req.item}</h4>
                               <div className="flex gap-2">
                                  {req.audience && <span className="text-[10px] bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded border border-indigo-200">{req.audience}</span>}
                                  <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded border ${getCriticalityColor(req.criticality)}`}>{req.criticality}</span>
                               </div>
                             </div>
                             <p className="text-sm text-slate-500">{req.description}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                 )}
              </div>
           </div>
        )}

        {activeSubTab === 'scoping' && (
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 max-w-6xl mx-auto animate-fade-in p-6">
                <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><ClipboardList className="text-orange-500" /> Scoping Questionnaire</h3>
                {questions.length === 0 ? <p className="text-slate-400">No questions generated.</p> : (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {questions.map((q, i) => (
                        <div key={i} className="p-3 rounded-lg border border-slate-200">
                           <label className="block text-sm font-semibold text-slate-800 mb-2">{q.question}</label>
                           <textarea className="w-full p-3 border border-slate-300 rounded-lg text-sm bg-white min-h-[80px]" placeholder="Pending Response..." defaultValue={q.answer} />
                        </div>
                      ))}
                   </div>
                )}
            </div>
        )}

        {activeSubTab === 'design' && (
          <div className="h-full flex flex-col">
            {status === 'idle' ? (
              <div className="flex-1 flex flex-col items-center justify-center gap-8 animate-fade-in">
                <div className="text-center max-w-lg">
                   <h3 className="text-2xl font-bold text-slate-800 mb-2">Architectural Blueprint</h3>
                   <p className="text-slate-500">Analyze {localFiles.length} files for pure technical solution flow.</p>
                </div>
                <button onClick={() => handleGenerate()} className="w-72 p-8 bg-white border-2 border-orange-100 rounded-xl hover:border-orange-500 hover:shadow-lg transition-all text-left">
                  <div className="mb-4 bg-orange-50 w-12 h-12 rounded-lg flex items-center justify-center text-orange-600"><Sparkles size={24} /></div>
                  <h4 className="font-bold text-slate-800 mb-1">Generate Solution (AI)</h4>
                </button>
              </div>
            ) : status === 'review' ? (
               <div className="flex flex-col h-full animate-fade-in">
                  <div className="bg-orange-50 border-b border-orange-200 p-4 flex justify-between items-center">
                     <div className="flex items-center gap-3"><div className="bg-orange-100 p-2 rounded-full text-orange-600"><Lightbulb size={20} /></div><div><h4 className="font-bold text-orange-900">Verify Design</h4><p className="text-xs text-orange-700">Generated for Technical Flow</p></div></div>
                     <div className="flex gap-2">
                        <button onClick={() => handleGenerate()} className="flex items-center gap-2 px-4 py-2 bg-white text-orange-600 border border-orange-200 rounded-lg text-sm font-bold hover:bg-orange-100"><RefreshCw size={16} /> Regenerate</button>
                        <button onClick={handleAcceptDesign} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-sm"><ThumbsUp size={16} /> Accept & Save</button>
                     </div>
                  </div>
                  <div className="flex-1 relative">
                     <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={false} thoughts={[]} context={extractTextFromMock(localFiles)} audience={request.targetAudience} onApplyRefinement={handleUpdateDesignFromRefinement} />
                     <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-xl bg-white shadow-xl rounded-full border border-slate-200 p-1 pl-4 flex items-center gap-2">
                        <MessageSquare size={18} className="text-slate-400" />
                        <input type="text" placeholder="Refine design..." className="flex-1 bg-transparent outline-none text-sm py-3 text-slate-700" value={refinementPrompt} onChange={(e) => setRefinementPrompt(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleGenerate(refinementPrompt)} />
                        <button onClick={() => handleGenerate(refinementPrompt)} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-full"><Send size={16} /></button>
                     </div>
                  </div>
               </div>
            ) : (
              <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex overflow-hidden flex-col">
                <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={status === 'thinking'} thoughts={thoughts} context={extractTextFromMock(localFiles)} audience={request.targetAudience} onApplyRefinement={handleUpdateDesignFromRefinement} />
                {status === 'accepted' && <div className="p-4 border-t border-slate-100 bg-slate-50 text-center"><p className="text-sm text-slate-500">Design Accepted.</p></div>}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SolutionDesignView;

import React, { useRef, useState, useEffect } from 'react';
import { 
  Database, 
  Server, 
  CloudLightning, 
  Settings, 
  Share2, 
  Code,
  BrainCircuit,
  CheckCircle,
  Loader,
  X,
  Copy,
  Check,
  Image as ImageIcon,
  FileCode,
  Sparkles,
  Zap,
  Info,
  ZoomIn,
  ZoomOut,
  Maximize
} from 'lucide-react';
import { Node, Edge, RefinementSuggestion, DesignData } from '../types';
import { generateDesignRefinements } from '../services/geminiService';

interface ArchitectureCanvasProps {
  aiNodes: Node[];
  aiEdges: Edge[];
  isThinking: boolean;
  thoughts: string[];
  context?: string; 
  audience?: string[];
  onApplyRefinement?: (newDesign: DesignData) => void;
}

const ArchitectureCanvas: React.FC<ArchitectureCanvasProps> = ({ 
  aiNodes, 
  aiEdges, 
  isThinking, 
  thoughts,
  context = "",
  audience = [],
  onApplyRefinement
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [showMermaid, setShowMermaid] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Zoom & Pan State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [startPan, setStartPan] = useState({ x: 0, y: 0 });

  // Refinement State
  const [showInsights, setShowInsights] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [suggestions, setSuggestions] = useState<RefinementSuggestion[]>([]);

  // Hover State
  const [hoveredNode, setHoveredNode] = useState<Node | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const getMermaidCode = () => {
    if (!aiNodes.length) return "graph LR\n  NoData[No Design Generated]";
    let code = "graph LR\n";
    code += "  classDef source fill:#eff6ff,stroke:#3b82f6,stroke-width:2px,color:#1e40af;\n";
    code += "  classDef stage fill:#f1f5f9,stroke:#64748b,stroke-width:2px,color:#334155;\n";
    code += "  classDef process fill:#fff7ed,stroke:#f97316,stroke-width:2px,color:#9a3412;\n";
    code += "  classDef target fill:#ecfdf5,stroke:#10b981,stroke-width:2px,color:#065f46;\n\n";

    aiNodes.forEach(node => {
      const label = node.label.replace(/"/g, "'");
      code += `  ${node.id}["${label}"]:::${node.type}\n`;
    });
    code += "\n";
    aiEdges.forEach(edge => {
      const label = edge.label ? `|"${edge.label}"|` : "";
      code += `  ${edge.from} -->${label} ${edge.to}\n`;
    });
    return code;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getMermaidCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleExport = (format: 'svg' | 'png') => {
    if (!svgRef.current) return;
    const svgEl = svgRef.current;

    // Create a clone to export without transforms/zoom for clean export, or keep as is.
    // Simpler to just serialize current state, but might be zoomed out.
    // For better export, reset transform temporarily
    const currentTransform = svgEl.getAttribute('transform');

    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svgEl);
    if(!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)){
        source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    source = '<?xml version="1.0" standalone="no"?>\r\n' + source;
    const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);

    if (format === 'svg') {
        const link = document.createElement("a");
        link.href = url;
        link.download = "architecture-design.svg";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        const img = new Image();
        img.src = url;
        img.onload = () => {
            const canvas = document.createElement("canvas");
            // Use static size for export or dynamic
            canvas.width = 1000; 
            canvas.height = 300;
            const ctx = canvas.getContext("2d");
            if (ctx) {
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                const link = document.createElement("a");
                link.href = canvas.toDataURL("image/png");
                link.download = "architecture-design.png";
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        };
    }
    setShowExportMenu(false);
  };

  const handleFetchRefinements = async () => {
    if (!context || !aiNodes.length) return;
    setIsRefining(true);
    setShowInsights(true);
    setSuggestions([]);
    try {
      const currentDesign = { nodes: aiNodes, edges: aiEdges };
      const newSuggestions = await generateDesignRefinements(currentDesign, context, audience);
      setSuggestions(newSuggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefining(false);
    }
  };

  const applySuggestion = (suggestion: RefinementSuggestion) => {
    if (onApplyRefinement) {
      onApplyRefinement(suggestion.suggestedDesign);
      setSuggestions(prev => prev.filter(s => s.id !== suggestion.id)); 
    }
  };

  // --- Zoom & Pan Handlers ---
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const scaleFactor = 0.05;
    const delta = e.deltaY > 0 ? -scaleFactor : scaleFactor;
    const newZoom = Math.max(0.5, Math.min(3, zoom + delta));
    setZoom(newZoom);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Only drag if clicking background (not buttons)
    if ((e.target as HTMLElement).tagName !== 'BUTTON') {
      setIsDragging(true);
      setStartPan({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging) {
      setPan({ x: e.clientX - startPan.x, y: e.clientY - startPan.y });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const resetView = () => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  };

  return (
    <div className="flex flex-col h-full relative group" ref={containerRef}>
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center z-20 shadow-sm">
        <div>
          <h3 className="font-bold text-slate-800">High Level Design (HLD)</h3>
          <p className="text-xs text-slate-500 hidden sm:block">
            {isThinking ? "AI is analyzing requirements..." : "Hover nodes • Scroll to Zoom • Drag to Pan"}
          </p>
        </div>

        <div className="flex items-center gap-2 relative">
           <button onClick={handleFetchRefinements} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 border border-indigo-100 px-3 py-1.5 rounded hover:bg-indigo-100 transition-colors mr-2">
             <Sparkles size={14} className={isRefining ? 'animate-spin' : ''} />
             <span className="hidden sm:inline">AI Insights</span>
           </button>

          <div className="relative">
             <button onClick={() => setShowExportMenu(!showExportMenu)} className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50 transition-colors">
                <Share2 size={14} /> <span className="hidden sm:inline">Export</span>
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-1 w-32 bg-white rounded-lg shadow-xl border border-slate-200 py-1 z-30">
                   <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><ImageIcon size={14} /> PNG Image</button>
                   <button onClick={() => handleExport('svg')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><FileCode size={14} /> SVG Vector</button>
                </div>
             )}
          </div>
          <button onClick={() => setShowMermaid(true)} className="flex items-center gap-2 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700 transition-colors">
            <Code size={14} /> <span className="hidden sm:inline">Mermaid</span>
          </button>
        </div>
      </div>

      <div 
        className="flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px] cursor-move"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >

        {/* Zoom Controls */}
        <div className="absolute bottom-4 left-4 flex flex-col gap-2 z-30">
          <button onClick={() => setZoom(z => Math.min(3, z + 0.2))} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50"><ZoomIn size={16} /></button>
          <button onClick={() => setZoom(z => Math.max(0.5, z - 0.2))} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50"><ZoomOut size={16} /></button>
          <button onClick={resetView} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50"><Maximize size={16} /></button>
        </div>

        {/* Gemini Insights Floating Panel */}
        {showInsights && (
           <div className="absolute top-4 left-4 z-20 w-72 bg-white/95 backdrop-blur-md rounded-xl shadow-xl border border-indigo-100 overflow-hidden flex flex-col max-h-[80%] animate-fade-in-up" onMouseDown={(e) => e.stopPropagation()}>
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 p-3 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2"><BrainCircuit size={16} /><span className="font-bold text-sm">Design Analysis</span></div>
                 <button onClick={() => setShowInsights(false)} className="hover:bg-white/20 rounded p-1"><X size={14} /></button>
              </div>
              <div className="p-4 overflow-y-auto flex-1">
                 {isRefining ? (
                    <div className="flex flex-col items-center justify-center py-8 text-center"><Loader size={24} className="text-indigo-500 animate-spin mb-2" /><p className="text-xs text-slate-500 font-medium">Comparing with learned patterns...</p></div>
                 ) : suggestions.length > 0 ? (
                    <div className="space-y-3">
                       {suggestions.map((sug) => (
                          <div key={sug.id} className="bg-indigo-50 border border-indigo-100 rounded-lg p-3">
                             <div className="flex justify-between items-start mb-1"><h5 className="font-bold text-slate-800 text-xs">{sug.title}</h5><span className="text-[9px] uppercase font-bold text-indigo-600 bg-white px-1.5 py-0.5 rounded border border-indigo-100">{sug.impact}</span></div>
                             <p className="text-[10px] text-slate-600 mb-2 leading-relaxed">{sug.description}</p>
                             <button onClick={() => applySuggestion(sug)} className="w-full bg-white text-indigo-600 text-xs font-bold py-1.5 rounded border border-indigo-200 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1"><Zap size={10} /> Apply Optimization</button>
                          </div>
                       ))}
                    </div>
                 ) : (
                    <div className="text-center py-4 text-slate-400 text-xs"><CheckCircle size={24} className="mx-auto mb-2 text-emerald-400" /><p>No major refinements found.</p></div>
                 )}
              </div>
           </div>
        )}

        {/* Hover Tooltip - Positioned fixed relative to container but updated by mouse coordinates */}
        {hoveredNode && (
          <div 
            className="absolute z-50 bg-slate-900 text-white p-3 rounded-lg shadow-xl max-w-xs pointer-events-none animate-fade-in text-xs border border-slate-700"
            style={{ 
              left: `${tooltipPos.x}px`, 
              top: `${tooltipPos.y - 10}px`,
              transform: 'translate(-50%, -100%)'
            }}
          >
             <div className="font-bold mb-1 flex items-center gap-2 border-b border-slate-700 pb-1">
               <Info size={12} className="text-indigo-400" />
               {hoveredNode.label}
             </div>
             <p className="text-slate-300 leading-relaxed">
               {hoveredNode.description || "No technical details available for this node."}
             </p>
          </div>
        )}

        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/95 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm transition-opacity duration-300">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse"><BrainCircuit className="text-white" size={24} /></div>
                   <div><h4 className="font-bold text-slate-800 text-lg">AI Thinking...</h4><p className="text-xs text-slate-500">Model: gemini-3-pro-preview</p></div>
                </div>
                <div className="space-y-3 font-mono text-xs max-h-60 overflow-y-auto">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.3}s`}}><CheckCircle size={14} className="text-emerald-500 flex-shrink-0" /><span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200 shadow-sm">{thought}</span></div>
                   ))}
                </div>
             </div>
          </div>
        )}

        <svg 
            ref={svgRef} 
            width="100%" 
            height="100%" 
            className="w-full h-full select-none"
        >
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>

          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`} style={{ transition: isDragging ? 'none' : 'transform 0.1s ease-out' }}>

            {aiEdges && aiEdges.map((edge, i) => {
              const source = aiNodes.find(n => n.id === edge.from);
              const target = aiNodes.find(n => n.id === edge.to);
              if (!source || !target) return null;
              const sourceX = source.x + 160; 
              const sourceY = source.y + 40;  
              const targetX = target.x;
              const targetY = target.y + 40;
              const controlPointOffset = 60;
              return (
                <g key={i} className="animate-fade-in" style={{animationDelay: '0.5s'}}>
                  <path d={`M ${sourceX} ${sourceY} C ${sourceX + controlPointOffset} ${sourceY}, ${targetX - controlPointOffset} ${targetY}, ${targetX} ${targetY}`} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />
                  <rect x={(sourceX + targetX)/2 - 40} y={(sourceY + targetY)/2 - 10} width="80" height="20" rx="4" fill="white" stroke="#e2e8f0" strokeWidth="1" />
                  <text x={(sourceX + targetX)/2} y={(sourceY + targetY)/2 + 4} textAnchor="middle" fontSize="10" fill="#64748b" fontWeight="600" style={{ fontFamily: 'Inter, sans-serif' }}>{edge.label}</text>
                </g>
              );
            })}

            {aiNodes && aiNodes.map((node, i) => {
              return (
                <foreignObject 
                  x={node.x} y={node.y} width="160" height="80" key={node.id} 
                  className="animate-fade-in-up overflow-visible" 
                  style={{animationDelay: `${i * 0.1}s`}}
                >
                  <div 
                      className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white relative
                      ${node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                        node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                        node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                        'bg-white border-slate-300'}`}
                      onMouseEnter={(e) => {
                        // We use the event client coordinates directly to position the tooltip
                        // This avoids complex matrix calculations for the transformed SVG group
                        const rect = e.currentTarget.getBoundingClientRect();
                        setTooltipPos({ x: rect.left + rect.width/2, y: rect.top });
                        setHoveredNode(node);
                      }}
                      onMouseLeave={() => setHoveredNode(null)}
                      onMouseDown={(e) => e.stopPropagation()} // Prevent pan start on node click
                  >
                      <div className="mb-1">
                        {node.type === 'source' && <Database size={20} className="text-blue-600" />}
                        {node.type === 'stage' && <Server size={20} className="text-slate-600" />}
                        {node.type === 'process' && <Settings size={20} className="text-orange-600 animate-spin-slow" />}
                        {node.type === 'target' && <CloudLightning size={20} className="text-emerald-600" />}
                      </div>
                      <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">{node.label}</span>
                  </div>
                </foreignObject>
              );
            })}
          </g>
        </svg>
      </div>

      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
