export const learnFromProject = async (context: string, finalDesign: DesignData, audience: string[]) => {
  try {
     const prompt = `
       Analyze this completed architecture design.
       Context: ${context}
       Roles Involved: ${audience.join(', ')}
       Design Nodes: ${JSON.stringify(finalDesign.nodes)}

       Extract 1 specific architectural rule or best practice from this that applies to these roles.
       Focus on nuances like "If role is Tester, verify TDM requirements" or "If role is Admin, check Firewall 443".
       Keep it under 20 words.
       Output format: Just the string.
     `;
     const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: prompt
     });

     if (response.text) {
       const newPattern = `Pattern (${audience[0]}): ${response.text.trim()}`;
       // Simple in-memory deduplication
       if (!LEARNED_PATTERNS.some(p => p.includes(response.text.trim().substring(0, 10)))) {
          LEARNED_PATTERNS.push(newPattern);
          console.log("AI Learned:", newPattern);
       }
