import React, { useState, useEffect, useMemo } from 'react';
import { 
  Calculator,
  Settings, 
  Download, 
  DollarSign, 
  Users, 
  Clock, 
  Database, 
  ShieldCheck, 
  Layers, 
  Globe,
  Calendar,
  RefreshCw,
  Lock,
  Unlock,
  Trash2,
  Plus,
  PieChart as IconPieChart,
  BarChart as IconBarChart,
  Menu,
  X
} from 'lucide-react';

// Using Recharts for Impactful Graphics
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  Tooltip as RechartsTooltip, 
  Legend,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid
} from 'recharts';

// --- Global Declaration for CDN Loaded Libraries ---
declare global {
  interface Window {
    XLSX: any;
  }
}

// --- Types & Interfaces ---

interface EffortDriver {
  id: string;
  label: string;
  category: 'simple' | 'medium' | 'complex' | 'fixed';
  defaultValue: number;
  multiplier: number; // Hours per unit
  description: string;
}

interface ModuleConfig {
  id: string;
  title: string;
  icon: React.ElementType;
  color: string;
  drivers: EffortDriver[];
}

interface ResourceRow {
  id: string;
  role: string;
  count: number;
  utilization: number; // 0-100%
  rate: number; // Daily Rate
  durationWeeks: number;
}

// --- ALL AVAILABLE MODULES CONFIGURATION ---

const ALL_MODULES_CONFIG: ModuleConfig[] = [
  {
    id: 'di',
    title: 'Cloud Data Integration',
    icon: Database,
    color: '#3B82F6', // Blue-500
    drivers: [
      { id: 'di_src', label: 'Source Systems', category: 'fixed', defaultValue: 3, multiplier: 8, description: 'Connection setup & analysis per source' },
      { id: 'di_map_s', label: 'Simple Mappings', category: 'simple', defaultValue: 10, multiplier: 8, description: 'Direct loads, minor transformations' },
      { id: 'di_map_m', label: 'Medium Mappings', category: 'medium', defaultValue: 15, multiplier: 16, description: 'Multiple joins, standard business logic' },
      { id: 'di_map_c', label: 'Complex Mappings', category: 'complex', defaultValue: 5, multiplier: 24, description: 'Complex logic, hierarchical data, stored procs' },
      { id: 'di_task', label: 'Task Flows', category: 'fixed', defaultValue: 5, multiplier: 4, description: 'Orchestration flows, scheduling' },
    ]
  },
  {
    id: 'dq',
    title: 'Cloud Data Quality',
    icon: ShieldCheck,
    color: '#10B981', // Emerald-500
    drivers: [
      { id: 'dq_prof', label: 'Profiling Objects', category: 'fixed', defaultValue: 20, multiplier: 2, description: 'Running and analyzing profiles per object' },
      { id: 'dq_rule_s', label: 'Simple Rules', category: 'simple', defaultValue: 10, multiplier: 2, description: 'Standardization, null checks' },
      { id: 'dq_rule_m', label: 'Medium Rules', category: 'medium', defaultValue: 10, multiplier: 6, description: 'Reference table lookups, conditional logic' },
      { id: 'dq_rule_c', label: 'Complex Rules', category: 'complex', defaultValue: 5, multiplier: 12, description: 'Parsing, advanced matching, address validation' },
      { id: 'dq_sc', label: 'Scorecards', category: 'fixed', defaultValue: 2, multiplier: 8, description: 'Scorecard configuration & visualization' },
    ]
  },
  {
    id: 'dg',
    title: 'Governance (CDGC)',
    icon: Globe,
    color: '#8B5CF6', // Violet-500
    drivers: [
      { id: 'dg_src', label: 'Resources (Scanners)', category: 'fixed', defaultValue: 4, multiplier: 8, description: 'Scanner configuration & connection' },
      { id: 'dg_term', label: 'Business Terms', category: 'simple', defaultValue: 100, multiplier: 0.5, description: 'Definition & approval (assuming bulk load)' },
      { id: 'dg_pol', label: 'Policies & Standards', category: 'medium', defaultValue: 10, multiplier: 4, description: 'Policy creation & linking' },
      { id: 'dg_lin', label: 'Lineage Validation', category: 'complex', defaultValue: 5, multiplier: 8, description: 'Manual verification of critical lineage paths' },
      { id: 'dg_kde', label: 'KDE Overlays', category: 'medium', defaultValue: 20, multiplier: 2, description: 'Linking DQ rules to Governance terms' },
      { id: 'dg_class', label: 'Custom Classification', category: 'medium', defaultValue: 50, multiplier: 4, description: 'Manual classification rules (approx 50% of Business Terms)' },
    ]
  },
  {
    id: 'mdm',
    title: 'MDM SaaS',
    icon: Layers,
    color: '#F59E0B', // Amber-500
    drivers: [
      { id: 'mdm_dom', label: 'Domains', category: 'fixed', defaultValue: 1, multiplier: 40, description: 'Domain model configuration' },
      { id: 'mdm_ing_s', label: 'Ingestion (Simple)', category: 'simple', defaultValue: 5, multiplier: 16, description: 'Direct ingestion from source' },
      { id: 'mdm_ing_c', label: 'Ingestion (Complex)', category: 'complex', defaultValue: 5, multiplier: 40, description: 'Complex cleansing & mapping during ingestion' },
      { id: 'mdm_match', label: 'Match Rules', category: 'complex', defaultValue: 4, multiplier: 24, description: 'Match rule tuning & merge logic' },
      { id: 'mdm_ui', label: 'UI Config', category: 'medium', defaultValue: 4, multiplier: 12, description: 'Screen layouts, hierarchy views' },
    ]
  }
];

// --- Main Component ---

export default function App() {
  const [activeTab, setActiveTab] = useState('dashboard');

  // Mobile Menu State
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Initialize with all modules active by default
  const [modules, setModules] = useState<ModuleConfig[]>(ALL_MODULES_CONFIG);
  const [inputs, setInputs] = useState<Record<string, number>>({});
  const [currency] = useState('USD');
  const [showConfig, setShowConfig] = useState(false);
  const [isExcelReady, setIsExcelReady] = useState(false);

  // Resource Planner State
  const [isAutoStaffing, setIsAutoStaffing] = useState(true);
  const [resourcePlan, setResourcePlan] = useState<ResourceRow[]>([]);

  // Initialize inputs on load & Load Excel Library
  useEffect(() => {
    // Initialize Inputs
    const initialInputs: Record<string, number> = {};
    ALL_MODULES_CONFIG.forEach(mod => {
      mod.drivers.forEach(driver => {
        if (initialInputs[driver.id] === undefined) {
          initialInputs[driver.id] = driver.defaultValue;
        }
      });
    });
    setInputs(prev => ({ ...initialInputs, ...prev }));

    // Load SheetJS from CDN dynamically
    if (!window.XLSX) {
      const script = document.createElement('script');
      script.src = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
      script.async = true;
      script.onload = () => setIsExcelReady(true);
      document.body.appendChild(script);
    } else {
      setIsExcelReady(true);
    }

    // Set Mobile Viewport
    let meta = document.querySelector('meta[name="viewport"]');
    if (!meta) {
      meta = document.createElement('meta');
      meta.setAttribute('name', 'viewport');
      document.head.appendChild(meta);
    }
    meta.setAttribute('content', 'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no');
  }, []);

  // Handle Resize for Mobile Menu
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 768) {
        setIsMobileMenuOpen(false);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // --- Core Calculations ---

  const baseCalculations = useMemo(() => {
    let totalTechHours = 0;
    const moduleBreakdown: Record<string, number> = {};

    // Initialize all potential keys to 0
    modules.forEach(m => moduleBreakdown[m.id] = 0);

    modules.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const qty = inputs[driver.id] || 0;
        modHours += qty * driver.multiplier;
      });
      moduleBreakdown[mod.id] = modHours;
      totalTechHours += modHours;
    });

    // Buffers
    const testingBuffer = totalTechHours * 0.30; 
    const grandTotalTechHours = totalTechHours + testingBuffer;

    // Timeline Logic
    const teamVelocityPerWeek = 3 * 40; 
    const inceptionWeeks = Math.max(2, grandTotalTechHours * 0.10 / teamVelocityPerWeek);

    const implementationWeeks: Record<string, number> = {};
    modules.forEach(mod => {
      implementationWeeks[mod.id] = moduleBreakdown[mod.id] / teamVelocityPerWeek;
    });

    const uatWeeks = Math.max(2, testingBuffer / teamVelocityPerWeek);
    const totalProjectWeeks = inceptionWeeks + Math.max(...Object.values(implementationWeeks), 0) + uatWeeks;

    return {
      moduleBreakdown,
      totalTechHours,
      testingBuffer,
      grandTotalTechHours,
      inceptionWeeks,
      implementationWeeks,
      uatWeeks,
      totalProjectWeeks
    };
  }, [inputs, modules]);

  // --- Resource Plan Logic ---

  useEffect(() => {
    if (isAutoStaffing) {
      const duration = Math.max(4, baseCalculations.totalProjectWeeks);
      const devCount = Math.ceil(baseCalculations.totalTechHours / (duration * 40 * 0.85)) || 1;
      const qaCount = Math.ceil(baseCalculations.testingBuffer / (duration * 40 * 0.85)) || 1;

      const newPlan: ResourceRow[] = [
        { id: 'pm', role: 'Project Manager', count: 1, utilization: 50, rate: 800, durationWeeks: duration },
        { id: 'arch', role: 'Solution Architect', count: 1, utilization: 25, rate: 950, durationWeeks: duration },
        { id: 'lead', role: 'Technical Lead', count: 1, utilization: 100, rate: 750, durationWeeks: duration },
        { id: 'dev', role: 'Developer/Consultant', count: devCount, utilization: 100, rate: 500, durationWeeks: duration },
        { id: 'qa', role: 'QA Specialist', count: qaCount, utilization: 100, rate: 450, durationWeeks: duration },
      ];
      setResourcePlan(newPlan);
    }
  }, [baseCalculations, isAutoStaffing]);

  // --- Final Financials ---

  const financialCalculations = useMemo(() => {
    let totalCost = 0;
    let totalDays = 0;

    resourcePlan.forEach(row => {
      const rowDays = (row.durationWeeks * 5) * row.count * (row.utilization / 100);
      const rowCost = rowDays * row.rate;
      totalCost += rowCost;
      totalDays += rowDays;
    });

    return { totalCost, totalDays };
  }, [resourcePlan]);

  // --- Chart Data Preparation ---
  const chartData = useMemo(() => {
    return modules.map(mod => ({
      name: mod.title,
      value: baseCalculations.moduleBreakdown[mod.id],
      color: mod.color
    })).filter(item => item.value > 0);
  }, [modules, baseCalculations]);

  const resourceChartData = useMemo(() => {
    return resourcePlan.map(r => ({
      name: r.role,
      cost: (r.durationWeeks * 5) * r.count * (r.utilization / 100) * r.rate,
      days: (r.durationWeeks * 5) * r.count * (r.utilization / 100)
    })).filter(i => i.cost > 0);
  }, [resourcePlan]);

  // --- Handlers ---

  const handleInputChange = (id: string, val: number) => {
    setInputs(prev => ({ ...prev, [id]: Math.max(0, val) }));
  };

  // Dynamic Driver Management
  const addDriver = (moduleId: string) => {
    const newId = `custom-driver-${Date.now()}`;
    const newDriver: EffortDriver = {
      id: newId,
      label: "New Component",
      category: "medium",
      defaultValue: 0,
      multiplier: 8,
      description: "Custom added component"
    };

    setModules(prev => prev.map(m => {
      if (m.id !== moduleId) return m;
      return {
        ...m,
        drivers: [...m.drivers, newDriver]
      };
    }));

    // Initialize input for new driver
    setInputs(prev => ({...prev, [newId]: 0}));
  };

  const removeDriver = (moduleId: string, driverId: string) => {
    setModules(prev => prev.map(m => {
      if (m.id !== moduleId) return m;
      return {
        ...m,
        drivers: m.drivers.filter(d => d.id !== driverId)
      };
    }));
  };

  const updateDriverField = (moduleId: string, driverId: string, field: keyof EffortDriver, value: any) => {
    setModules(prev => prev.map(m => {
      if (m.id !== moduleId) return m;
      return {
        ...m,
        drivers: m.drivers.map(d => d.id === driverId ? { ...d, [field]: value } : d)
      };
    }));
  };

  const handleResourceChange = (id: string, field: keyof ResourceRow, val: number) => {
    if (isAutoStaffing) setIsAutoStaffing(false);
    setResourcePlan(prev => prev.map(r => r.id === id ? { ...r, [field]: val } : r));
  };

  const addResourceRow = () => {
    setIsAutoStaffing(false);
    const newId = `custom-${Date.now()}`;
    setResourcePlan(prev => [...prev, { 
      id: newId, role: 'New Role', count: 1, utilization: 100, rate: 500, durationWeeks: baseCalculations.totalProjectWeeks 
    }]);
  };

  const removeResourceRow = (id: string) => {
    setIsAutoStaffing(false);
    setResourcePlan(prev => prev.filter(r => r.id !== id));
  };

  // --- EXCEL EXPORT FUNCTION (CDN Based + Gantt Chart) ---
  const exportXLSX = () => {
    if (!window.XLSX) {
      alert("Excel export library is still loading. Please try again in a few seconds.");
      return;
    }
    const XLSX = window.XLSX;

    // 1. Create a new workbook
    const workbook = XLSX.utils.book_new();

    // -- Sheet 1: Executive Summary --
    const summaryData = [
      ["INFORMATICA CLOUD ESTIMATION - EXECUTIVE SUMMARY"],
      ["Generated On", new Date().toLocaleDateString()],
      [""],
      ["PROJECT FINANCIALS", "", ""],
      ["Metric", "Value", "Notes"],
      ["Total Estimated Cost", financialCalculations.totalCost.toFixed(2), currency],
      ["Total Man Days", financialCalculations.totalDays.toFixed(1), "8 hours/day"],
      ["Total Technical Hours", baseCalculations.totalTechHours.toFixed(2), "Core Development Effort"],
      ["Grand Total Hours", baseCalculations.grandTotalTechHours.toFixed(2), "Incl. 30% Testing Buffer"],
      ["Estimated Duration", baseCalculations.totalProjectWeeks.toFixed(1) + " Weeks", "Timeline based on Resource Plan"],
      [""],
      ["EFFORT DISTRIBUTION BY MODULE", "", ""],
      ["Module", "Hours", "% of Total"],
      ...modules.map(m => {
        const hrs = baseCalculations.moduleBreakdown[m.id];
        const pct = baseCalculations.totalTechHours > 0 ? (hrs / baseCalculations.totalTechHours * 100).toFixed(1) : "0.0";
        return [m.title, hrs.toFixed(2), pct + "%"];
      })
    ];

    // Create Summary Sheet
    const summarySheet = XLSX.utils.aoa_to_sheet(summaryData);
    // Set column widths for Summary
    summarySheet['!cols'] = [{ wch: 35 }, { wch: 15 }, { wch: 30 }];
    XLSX.utils.book_append_sheet(workbook, summarySheet, "Executive Summary");

    // -- Sheet 2: Detailed Effort Breakdown --
    const breakdownHeader = ["Module", "Component / Driver", "Category", "Quantity", "Multiplier (Hrs/Unit)", "Total Hours", "Description"];
    const breakdownData = [breakdownHeader];

    modules.forEach(m => {
      m.drivers.forEach(d => {
        breakdownData.push([
          m.title,
          d.label,
          d.category,
          (inputs[d.id] || 0).toString(),
          d.multiplier.toString(),
          ((inputs[d.id] || 0) * d.multiplier).toFixed(2),
          d.description
        ]);
      });
    });
    const breakdownSheet = XLSX.utils.aoa_to_sheet(breakdownData);
    // Set column widths for Breakdown
    breakdownSheet['!cols'] = [{ wch: 25 }, { wch: 30 }, { wch: 10 }, { wch: 10 }, { wch: 15 }, { wch: 12 }, { wch: 40 }];
    XLSX.utils.book_append_sheet(workbook, breakdownSheet, "Detailed Effort");

    // -- Sheet 3: Staffing & Resource Plan --
    const resourceHeader = ["Role", "Count (FTE)", "Utilization %", "Duration (Weeks)", "Rate (Daily)", "Total Cost", "Total Days"];

    // Explicitly typing this array as (string | number)[][] to avoid TS2322 errors 
    const resourceData: (string | number)[][] = [resourceHeader];

    resourcePlan.forEach(r => {
      resourceData.push([
        r.role,
        r.count,
        r.utilization + "%",
        r.durationWeeks,
        r.rate,
        ((r.durationWeeks * 5) * r.count * (r.utilization / 100) * r.rate).toFixed(2),
        ((r.durationWeeks * 5) * r.count * (r.utilization / 100)).toFixed(1)
      ]);
    });
    const resourceSheet = XLSX.utils.aoa_to_sheet(resourceData);
    // Set column widths for Resources
    resourceSheet['!cols'] = [{ wch: 25 }, { wch: 12 }, { wch: 12 }, { wch: 15 }, { wch: 12 }, { wch: 15 }, { wch: 12 }];
    XLSX.utils.book_append_sheet(workbook, resourceSheet, "Staffing Plan");

    // -- Sheet 4: Timeline Data (GANTT CHART) --
    const totalWeeks = Math.ceil(baseCalculations.totalProjectWeeks) + 2; // Buffer
    const ganttHeader = ["Phase / Activity", "Start Week", "Duration (Wks)"];

    // Add Week Headers (W1, W2, ...)
    for (let i = 1; i <= totalWeeks; i++) {
        ganttHeader.push(`W${i}`);
    }

    const ganttData: (string | number)[][] = [ganttHeader];

    // Helper to generate visual bar row
    const createGanttRow = (name: string, start: number, duration: number) => {
        const row: (string | number)[] = [name, start.toFixed(1), duration.toFixed(1)];
        const startIdx = Math.floor(start); // 0-based relative to project start
        const endIdx = Math.floor(start + duration);

        for (let i = 1; i <= totalWeeks; i++) {
            // Check if current week column 'i' is within the start-end range
            // Logic: if current week index is greater than start offset AND less than or equal to end
            if (i > startIdx && i <= endIdx + 1) { 
               row.push("█████"); 
            } else {
               row.push("");
            }
        }
        return row;
    };

    // 1. Mobilization Phase
    ganttData.push(createGanttRow("Mobilization & Inception", 0, baseCalculations.inceptionWeeks));

    // 2. Implementation Phases (Modules)
    modules.forEach(m => {
        const duration = baseCalculations.implementationWeeks[m.id];
        if (duration > 0) {
            // Assumes parallel starts after inception
            ganttData.push(createGanttRow(`${m.title} Implementation`, baseCalculations.inceptionWeeks, duration));
        }
    });

    // 3. UAT & Cutover Phase
    // Starts after the longest implementation module finishes
    const maxModuleDuration = Math.max(...Object.values(baseCalculations.implementationWeeks));
