const CreateForm: React.FC<CreateFormProps> = ({ onSubmit, onCancel }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpFiles: [] as string[],
    product: '',
    deploymentModel: 'Cloud' as 'Cloud' | 'On-Premise',
    solutionType: '',
    targetAudience: ['Developer'] as string[], 
    description: '',
    priority: 'Normal'
  });

  const [mode, setMode] = useState<'design' | 'estimator'>('design');
  const [step, setStep] = useState<'input' | 'analyzing' | 'recommendation'>('input');
  const [isDragging, setIsDragging] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiSuggestion | null>(null);

  // Dynamic Options based on selection
  const [availableProducts] = useState<string[]>(Object.keys(PRODUCT_CATALOG).sort());
  const [availableDeployments, setAvailableDeployments] = useState<string[]>(['Cloud', 'On-Premise']);
  const [availableServices, setAvailableServices] = useState<string[]>([]);

  // Effect to update Deployment and Services based on Product selection
  useEffect(() => {
    if (formData.product && PRODUCT_CATALOG[formData.product]) {
      const productConfig = PRODUCT_CATALOG[formData.product];
      const validDeployments = Object.keys(productConfig).filter(k => productConfig[k].length > 0);
      setAvailableDeployments(validDeployments);

      // Reset deployment if current selection is invalid for new product
      if (!validDeployments.includes(formData.deploymentModel)) {
        setFormData(prev => ({ ...prev, deploymentModel: validDeployments[0] as any }));
      }
    } else {
      setAvailableDeployments([]);
      setAvailableServices([]);
    }
  }, [formData.product]);

  // Effect to update Services based on Deployment selection
  useEffect(() => {
    if (formData.product && formData.deploymentModel && PRODUCT_CATALOG[formData.product]) {
      const services = PRODUCT_CATALOG[formData.product][formData.deploymentModel] || [];
      setAvailableServices(services);

      // Reset solution type if invalid
      if (!services.includes(formData.solutionType)) {
        setFormData(prev => ({ ...prev, solutionType: '' }));
      }
    }
  }, [formData.product, formData.deploymentModel]);

  const roles = [
    { id: 'Developer', label: 'Developer', icon: Code2, desc: 'Technical specs & mappings' },
    { id: 'Tester', label: 'Tester', icon: Beaker, desc: 'Test data & validation' },
    { id: 'Admin', label: 'Admin', icon: ShieldAlert, desc: 'Security & Infrastructure' }
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const toggleRole = (roleId: string) => {
    setFormData(prev => {
      const current = prev.targetAudience;
      if (current.includes(roleId)) {
        if (current.length === 1) return prev; 
        return { ...prev, targetAudience: current.filter(r => r !== roleId) };
      } else {
        return { ...prev, targetAudience: [...current, roleId] };
      }
    });
  };

  const handleDeploymentChange = (model: 'Cloud' | 'On-Premise') => {
    setFormData(prev => ({ ...prev, deploymentModel: model }));
  };

  const processFiles = (files: FileList) => {
    const newFileNames = Array.from(files).map(f => f.name);
    setFormData(prev => {
      const combined = [...prev.rfpFiles, ...newFileNames];
      return { ...prev, rfpFiles: combined.slice(0, 5) };
    });
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files) processFiles(e.dataTransfer.files);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) processFiles(e.target.files);
  };

  const removeFile = (fileName: string) => {
    setFormData(prev => ({ ...prev, rfpFiles: prev.rfpFiles.filter(f => f !== fileName) }));
  };

  const handleAnalyze = () => {
    setStep('analyzing');
    setTimeout(() => {
      const combinedNames = formData.rfpFiles.join(' ').toLowerCase();
      let suggestion: AiSuggestion | null = null;

      // Smart Product Detection Simulation with expanded patterns
      if (combinedNames.includes('azure') || combinedNames.includes('factory') || combinedNames.includes('synapse')) {
         suggestion = {
            product: 'Azure Data Factory',
            deployment: 'Cloud',
            type: "Data Factory V2",
            reason: "Detected Azure ecosystem terms (ADF, Synapse) in documents.",
            details: ["Source: Azure Blob.", "Target: Synapse Analytics."]
         };
      } else if (combinedNames.includes('talend') || combinedNames.includes('studio') || combinedNames.includes('fabric')) {
         suggestion = {
            product: 'Talend',
            deployment: 'Cloud',
            type: "Talend Cloud Data Integration",
            reason: "Detected Talend Data Fabric terminology.",
            details: ["Pattern: Remote Engine.", "Transformation: TMC/Pipeline Designer."]
         };
      } else if (combinedNames.includes('databricks') || combinedNames.includes('delta') || combinedNames.includes('medallion')) {
         suggestion = {
            product: 'Databricks',
            deployment: 'Cloud',
            type: "Unity Catalog",
            reason: "Detected Databricks Lakehouse & Medallion Architecture terms.",
            details: ["Pattern: Bronze/Silver/Gold Layers.", "Governance: Unity Catalog."]
         };
      } else if (combinedNames.includes('profisee') || combinedNames.includes('golden record')) {
         suggestion = {
            product: 'Profisee',
            deployment: 'Cloud',
            type: "Profisee MDM SaaS",
            reason: "Detected Golden Record management requirements typical of Profisee MDM.",
            details: ["Pattern: Match & Merge.", "Governance: Stewardship Portal."]
         };
      } else if (combinedNames.includes('mainframe') || combinedNames.includes('cobol')) {
         suggestion = {
            product: 'Informatica',
            deployment: 'On-Premise',
            type: "PowerCenter",
            reason: "Detected Legacy Mainframe sources requiring robust on-prem connectivity.",
            details: ["Source: Cobol Copybook.", "Security: Data Residency/On-Prem Agent."]
         };
      } else if (combinedNames.includes('privacy') || combinedNames.includes('discovery') || combinedNames.includes('bigid')) {
         suggestion = {
            product: 'BigID',
            deployment: 'Cloud',
            type: "BigID Data Discovery",
            reason: "Detected Privacy/PII scanning requirements.",
            details: ["Focus: Sensitive Data Discovery.", "Integration: Connector Framework."]
         };
      } else {
         suggestion = {
            product: 'Informatica',
            deployment: 'Cloud',
            type: "Cloud Data Integration (CDI)",
            reason: "Standard Enterprise Cloud Modernization pattern detected.",
            details: ["Target: Cloud Data Warehouse.", "Pattern: ELT/ETL Modernization."]
         };
      }
      setAiSuggestion(suggestion);
      setStep('recommendation');
    }, 2500);
  };

  const acceptRecommendation = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        product: aiSuggestion.product,
        deploymentModel: aiSuggestion.deployment as any,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      clientName: formData.clientName,
      product: formData.product,
      deploymentModel: formData.deploymentModel,
      type: formData.solutionType,
      rfpFiles: formData.rfpFiles,
      targetAudience: formData.targetAudience,
      date: new Date().toLocaleDateString(),
      mode: mode // Pass the selected mode to open the correct view initially
    });
  };

  return (
    <div className="p-6 md:p-8 max-w-6xl mx-auto animate-fade-in h-full flex flex-col">
      <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">New Solution Request</h2>
           <p className="text-slate-500">Define requirements and choose your starting point.</p>
        </div>

        {/* Mode Toggles */}
        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button 
             onClick={() => setMode('design')}
             className={`flex items-center gap-2 px-6 py-2 rounded-md text-sm font-bold transition-all ${mode === 'design' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
           >
             <PenTool size={16} /> Solution Designer
           </button>
           <button 
             onClick={() => setMode('estimator')}
             className={`flex items-center gap-2 px-6 py-2 rounded-md text-sm font-bold transition-all ${mode === 'estimator' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
           >
             <Calculator size={16} /> Effort Estimator
           </button>
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 flex flex-col">
          <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 md:p-8 flex-1 flex flex-col">
            <div className="space-y-6 flex-1">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Client Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="clientName"
                  required
                  value={formData.clientName}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-900"
                  placeholder="e.g. Acme Corp"
                  disabled={step === 'analyzing'}
                />
              </div>

              {/* Roles Section - Only relevant for Design, implied for Estimator */}
              <div className={mode === 'estimator' ? 'opacity-50 pointer-events-none grayscale' : ''}>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                   Target Design Audience <span className="text-red-500">*</span>
                </label>
                <p className="text-xs text-slate-500 mb-3">AI will tailor the design & requirements based on selected roles.</p>
                <div className="grid grid-cols-3 gap-3">
                  {roles.map((role) => {
                    const isSelected = formData.targetAudience.includes(role.id);
                    return (
                      <button
                        key={role.id}
                        type="button"
                        onClick={() => toggleRole(role.id)}
                        className={`
                          p-3 rounded-lg border text-left transition-all
                          ${isSelected 
                            ? 'bg-indigo-50 border-indigo-500 ring-1 ring-indigo-500' 
                            : 'bg-white border-slate-200 hover:border-slate-400'}
                        `}
                      >
                         <div className="flex items-center gap-2 mb-1">
                            <role.icon size={16} className={isSelected ? 'text-indigo-600' : 'text-slate-400'} />
                            <span className={`text-sm font-bold ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{role.label}</span>
                         </div>
                         <p className="text-[10px] text-slate-500 leading-tight">{role.desc}</p>
                      </button>
                    );
                  })}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  RFP Documents (Max 5) <span className="text-red-500">*</span>
                </label>
                <div 
                  className={`
                    border-2 border-dashed rounded-xl flex flex-col items-center justify-center p-4 text-center transition-colors relative overflow-hidden mb-3
                    ${isDragging ? 'border-indigo-500 bg-indigo-50' : 'border-slate-300 hover:border-indigo-400 hover:bg-slate-50'}
                    ${formData.rfpFiles.length >= 5 ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
                  `}
                  style={{ minHeight: '100px' }}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={handleFileDrop}
                >
                    <div className="flex items-center gap-2 mb-1 text-slate-500">
                      <UploadCloud size={20} />
                      <span className="font-medium text-sm">Drag & Drop RFP Files</span>
                    </div>
                    <input type="file" id="file-upload" className="hidden" multiple onChange={handleFileSelect} disabled={step === 'analyzing' || formData.rfpFiles.length >= 5} />
                    <label htmlFor="file-upload" className={`text-xs text-indigo-600 font-bold hover:underline cursor-pointer ${formData.rfpFiles.length >= 5 ? 'pointer-events-none' : ''}`}>or browse files</label>
                </div>
                {formData.rfpFiles.length > 0 && (
                  <div className="space-y-2">
                    {formData.rfpFiles.map((file, idx) => (
                      <div key={idx} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-200 animate-fade-in">
                        <div className="flex items-center gap-3"><div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-lg flex items-center justify-center"><FileText size={16} /></div><span className="text-sm font-medium text-slate-700 truncate max-w-[200px]">{file}</span></div>
                        <button type="button" onClick={() => removeFile(file)} className="text-slate-400 hover:text-red-500 transition-colors" disabled={step === 'analyzing'}><X size={16} /></button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className={`transition-opacity duration-500 ${step === 'recommendation' ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                {/* Product Selection */}
                <div className="mb-6">
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Data Management Product</label>
                  <div className="relative">
                    <select name="product" value={formData.product} onChange={handleInputChange} className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none appearance-none bg-white transition-all text-sm">
                      <option value="" disabled>Select Product...</option>
                      {availableProducts.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                    <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500"><Layers size={16} /></div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Deployment Model</label>
                    <div className="flex p-1 bg-slate-100 rounded-lg border border-slate-200">
                      {availableDeployments.map((model) => (
                        <button
                          key={model}
                          type="button"
                          onClick={() => handleDeploymentChange(model as any)}
                          className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-md transition-all 
                            ${formData.deploymentModel === model 
                              ? 'bg-white text-indigo-600 shadow-sm' 
                              : 'text-slate-500 hover:text-slate-700'
                            }`}
                        >
                          {model === 'Cloud' ? <Cloud size={16} /> : <Server size={16} />} {model}
                        </button>
                      ))}
                      {availableDeployments.length === 0 && <span className="text-xs text-slate-400 p-2">Select a Product first</span>}
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Technology Stack</label>
                    <div className="relative">
                      <select name="solutionType" value={formData.solutionType} onChange={handleInputChange} className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none appearance-none bg-white transition-all text-sm" disabled={!formData.product}>
                        <option value="" disabled>Select {formData.deploymentModel} Service...</option>
                        {availableServices.map(type => <option key={type} value={type}>{type}</option>)}
                      </select>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-end gap-4 mt-8">
              {step === 'input' && (
                <button type="button" onClick={handleAnalyze} disabled={formData.rfpFiles.length === 0 || !formData.clientName} className={`flex items-center gap-2 px-6 py-3 rounded-lg text-white font-bold shadow-sm transition-all ${(formData.rfpFiles.length === 0 || !formData.clientName) ? 'bg-slate-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
                  <Sparkles size={18} /> Analyze & Recommend
                </button>
              )}
              {step === 'recommendation' && (
                 <div className="flex gap-4 w-full justify-between items-center bg-emerald-50 p-4 rounded-xl border border-emerald-100 animate-fade-in-up">
                    <div className="flex items-center gap-3"><CheckCircle className="text-emerald-600" size={24} /><div><p className="text-sm font-bold text-emerald-800">Recommendation Ready</p></div></div>
                    <div className="flex gap-3">
                       <button type="button" onClick={() => setStep('input')} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-white rounded-lg">Back</button>
                       <button 
                         type="submit" 
                         className={`px-6 py-2 text-white rounded-lg text-sm font-bold shadow-sm flex items-center gap-2 transition-colors ${mode === 'design' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-emerald-600 hover:bg-emerald-700'}`}
                        >
                         {mode === 'design' ? 'Create Design' : 'Create Estimation'} <ArrowRight size={16} />
                       </button>
                    </div>
                 </div>
              )}
            </div>
          </form>
        </div>

        <div className="lg:col-span-4 space-y-6">
           <div className={`bg-slate-900 text-white rounded-xl shadow-xl p-6 relative overflow-hidden transition-all duration-500 h-full flex flex-col ${step === 'analyzing' ? 'ring-4 ring-indigo-500/30' : ''}`}>
             <div className="absolute top-0 right-0 p-4 opacity-10"><Cpu size={120} /></div>
             <div className="flex items-center gap-2 mb-6 relative z-10">
                <div className="p-2 bg-indigo-500/20 rounded-lg"><Sparkles className="text-indigo-400" size={20} /></div>
                <div><h3 className="font-bold text-lg">Architecture AI</h3><p className="text-xs text-slate-400">AI Generation Engine</p></div>
             </div>
             {step === 'input' && <div className="flex-1 flex flex-col items-center justify-center text-center text-slate-400 space-y-4"><RefreshCw size={40} className="text-slate-700" /><p className="text-sm">Enter client details, select audience roles, and upload up to 5 RFP files.</p></div>}
             {step === 'analyzing' && <div className="flex-1 flex flex-col items-center justify-center text-center py-12"><div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div><h4 className="text-lg font-bold mt-6 mb-2">Analyzing {formData.rfpFiles.length} Document(s)...</h4><p className="text-xs text-slate-400">Tailoring for: {formData.targetAudience.join(', ')}</p></div>}
             {step === 'recommendation' && aiSuggestion && (
                <div className="animate-fade-in-up flex-1 flex flex-col">
                   <div className="mb-6"><span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest border border-indigo-500/30 px-2 py-1 rounded">Optimal Solution</span><h2 className="text-2xl font-bold mt-3 mb-1">{aiSuggestion.product}</h2><p className="text-sm text-slate-300">{aiSuggestion.type} ({aiSuggestion.deployment})</p></div>
                   <div className="bg-slate-800/50 rounded-lg p-4 mb-4 border border-slate-700"><p className="text-sm text-slate-300 italic">"{aiSuggestion.reason}"</p></div>
                   {(formData.product !== aiSuggestion.product || formData.solutionType !== aiSuggestion.type) && (
                      <button onClick={acceptRecommendation} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-xl transition-all flex items-center justify-center gap-2"><Sparkles size={16} /> Apply AI Recommendation</button>
                   )}
                </div>
             )}
           </div>
        </div>
      </div>
    </div>
  );
};

export default CreateForm;

