                     <div className="text-3xl font-bold text-slate-800">{baseCalculations.grandTotalTechHours.toFixed(0)} <span className="text-lg font-normal text-slate-400">hrs</span></div>
                  </div>
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                     <div className="flex items-center gap-3 mb-4"><div className="p-2 bg-green-100 text-green-600 rounded-lg"><DollarSign size={20}/></div><span className="text-sm font-medium text-slate-500 uppercase">Total Cost</span></div>
                     <div className="text-3xl font-bold text-slate-800">{formatCurrency(financialCalculations.totalCost)}</div>
                  </div>
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                     <div className="flex items-center gap-3 mb-4"><div className="p-2 bg-purple-100 text-purple-600 rounded-lg"><Calendar size={20}/></div><span className="text-sm font-medium text-slate-500 uppercase">Duration</span></div>
                     <div className="text-3xl font-bold text-slate-800">~{baseCalculations.totalProjectWeeks.toFixed(1)} <span className="text-lg font-normal text-slate-400">wks</span></div>
