                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
                     <h3 className="font-bold text-slate-800 mb-6">Resource Cost</h3>
                     <div className="flex-1 min-h-[300px]">
                         <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={resourceChartData} layout="vertical" margin={{ top: 5, right: 30, left: 10, bottom: 5 }}>
                               <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false}/>
                               <XAxis type="number" tickFormatter={(val) => `$${val/1000}k`} stroke="#9CA3AF" fontSize={12}/>
                               <YAxis dataKey="name" type="category" width={90} tick={{fontSize: 10, fill: '#4B5563'}} />
                               <RechartsTooltip formatter={(value: number) => formatCurrency(value)} />
                               <Bar dataKey="cost" fill="#3B82F6" radius={[0, 4, 4, 0]} barSize={20} />
                            </BarChart>
                         </ResponsiveContainer>
                     </div>
                  </div>
               </div>

               {/* 3. Detailed Input Table */}
               <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                  <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                     <h3 className="font-bold text-slate-800">Estimation Drivers</h3>
                     <button onClick={() => setShowConfig(!showConfig)} className="text-sm text-blue-600 font-medium flex items-center gap-1"><Settings size={14} /> Config</button>
                  </div>
                  <div className="p-6 space-y-8">
                     {modules.map(mod => (
                        <div key={mod.id}>
                           <div className="flex items-center gap-2 mb-4">
                              <mod.icon className="text-white p-1 rounded w-6 h-6" style={{backgroundColor: mod.color}} />
                              <h4 className="font-bold text-slate-800">{mod.title}</h4>
                           </div>
                           <table className="min-w-full divide-y divide-slate-100">
                              <thead className="bg-slate-50">
                                 <tr>
                                    <th className="px-4 py-2 text-left text-xs font-semibold text-slate-500 uppercase w-1/3">Driver</th>
                                    <th className="px-4 py-2 text-left text-xs font-semibold text-slate-500 uppercase">Category</th>
                                    <th className="px-4 py-2 text-left text-xs font-semibold text-slate-500 uppercase">Qty</th>
                                    <th className="px-4 py-2 text-left text-xs font-semibold text-slate-500 uppercase">Hours/Unit</th>
                                    <th className="px-4 py-2 text-right text-xs font-semibold text-slate-500 uppercase">Total</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-50">
                                 {mod.drivers.map(driver => (
                                    <tr key={driver.id}>
                                       <td className="px-4 py-3 text-sm font-medium text-slate-700">
                                          {driver.label}
                                          <p className="text-xs text-slate-400 font-normal">{driver.description}</p>
                                       </td>
                                       <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${driver.category === 'complex' ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'}`}>{driver.category}</span></td>
                                       <td className="px-4 py-3">
                                          <input 
                                            type="number" 
                                            min="0"
                                            className="w-20 border border-slate-300 rounded p-1 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                            value={estimationInputs[driver.id] || 0}
                                            onChange={(e) => setEstimationInputs(prev => ({...prev, [driver.id]: parseInt(e.target.value) || 0}))}
                                          />
                                       </td>
                                       <td className="px-4 py-3 text-sm text-slate-500">
                                          {showConfig ? (
                                             <input type="number" className="w-16 border rounded p-1" defaultValue={driver.multiplier} />
                                          ) : `${driver.multiplier} hrs`}
                                       </td>
                                       <td className="px-4 py-3 text-sm font-bold text-slate-800 text-right">
                                          {((estimationInputs[driver.id] || 0) * driver.multiplier).toFixed(1)}
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     ))}
                  </div>
               </div>

               {/* 4. Export */}
               <div className="flex justify-end">
                  <button onClick={exportXLSX} className={`flex items-center gap-2 px-6 py-3 rounded-lg text-white font-bold shadow-sm transition-all ${isExcelReady ? 'bg-green-600 hover:bg-green-700' : 'bg-slate-300 cursor-not-allowed'}`}>
                     <Download size={18} /> Export Full Report (XLSX)
                  </button>
               </div>

            </div>
        )}

        {/* --- DESIGN TAB (EXISTING) --- */}
        {activeSubTab === 'design' && (
          <div className="h-full flex flex-col">
            {status === 'idle' ? (
              <div className="flex-1 flex flex-col items-center justify-center gap-8 animate-fade-in">
                <div className="text-center max-w-lg">
                   <h3 className="text-2xl font-bold text-slate-800 mb-2">Architectural Blueprint</h3>
                   <p className="text-slate-500">Analyze {localFiles.length} files for pure technical solution flow.</p>
                </div>
                <button onClick={() => handleGenerate()} className="w-72 p-8 bg-white border-2 border-orange-100 rounded-xl hover:border-orange-500 hover:shadow-lg transition-all text-left">
                  <div className="mb-4 bg-orange-50 w-12 h-12 rounded-lg flex items-center justify-center text-orange-600"><Sparkles size={24} /></div>
                  <h4 className="font-bold text-slate-800 mb-1">Generate Solution (AI)</h4>
                </button>
              </div>
            ) : status === 'review' ? (
               <div className="flex flex-col h-full animate-fade-in">
                  <div className="bg-orange-50 border-b border-orange-200 p-4 flex justify-between items-center">
                     <div className="flex items-center gap-3"><div className="bg-orange-100 p-2 rounded-full text-orange-600"><Lightbulb size={20} /></div><div><h4 className="font-bold text-orange-900">Verify Design</h4><p className="text-xs text-orange-700">Generated for Technical Flow</p></div></div>
                     <div className="flex gap-2">
                        <button onClick={() => handleGenerate()} className="flex items-center gap-2 px-4 py-2 bg-white text-orange-600 border border-orange-200 rounded-lg text-sm font-bold hover:bg-orange-100"><RefreshCw size={16} /> Regenerate</button>
                        <button onClick={handleAcceptDesign} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-sm"><ThumbsUp size={16} /> Accept & Save</button>
                     </div>
                  </div>
                  <div className="flex-1 relative">
                     <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={false} thoughts={[]} context={extractTextFromMock(localFiles)} audience={request.targetAudience} onApplyRefinement={handleUpdateDesignFromRefinement} />
                     <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-xl bg-white shadow-xl rounded-full border border-slate-200 p-1 pl-4 flex items-center gap-2">
                        <MessageSquare size={18} className="text-slate-400" />
                        <input type="text" placeholder="Refine design..." className="flex-1 bg-transparent outline-none text-sm py-3 text-slate-700" value={refinementPrompt} onChange={(e) => setRefinementPrompt(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleGenerate(refinementPrompt)} />
                        <button onClick={() => handleGenerate(refinementPrompt)} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-full"><Send size={16} /></button>
                     </div>
                  </div>
               </div>
            ) : (
              <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex overflow-hidden flex-col">
                <ArchitectureCanvas aiNodes={currentDesign.nodes} aiEdges={currentDesign.edges} isThinking={status === 'thinking'} thoughts={thoughts} context={extractTextFromMock(localFiles)} audience={request.targetAudience} onApplyRefinement={handleUpdateDesignFromRefinement} />
                {status === 'accepted' && <div className="p-4 border-t border-slate-100 bg-slate-50 text-center"><p className="text-sm text-slate-500">Design Accepted.</p></div>}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

