  role: string;
  count: number;
  utilization: number; // 0-100%
  rate: number; // Daily Rate
  durationWeeks: number;
}

interface SolutionDesignViewProps {
  request: RequestData | null;
  designCache: DesignCache;
  onUpdateDesignCache: (reqId: string, data: CachedRequestData) => void;
}

const extractTextFromMock = (files: string[]) => {
  const combinedText = files.join(' ');
  if (combinedText.includes("AA Motors") || combinedText.includes("HANA")) return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer (B2C). Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta.";
  if (combinedText.includes("Vehicle") || combinedText.includes("Adobe")) return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM.";
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB (Oracle). Target: Cloud Data Warehouse (Snowflake). Pattern: Batch ETL. Security: End-to-end encryption required.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState<'initiation' | 'design' | 'requirements' | 'scoping' | 'attachments' | 'estimator'>('design');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);

  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [questions, setQuestions] = useState<Question[]>([]);
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [initiationItems, setInitiationItems] = useState<InitiationItem[]>([]);

  // Estimator State
  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [modules, setModules] = useState<ModuleConfig[]>(ALL_MODULES_CONFIG);
  const [isExcelReady, setIsExcelReady] = useState(false);
  const [isAutoStaffing, setIsAutoStaffing] = useState(true);
  const [resourcePlan, setResourcePlan] = useState<ResourceRow[]>([]);
  const [showConfig, setShowConfig] = useState(false);

  const [localFiles, setLocalFiles] = useState<string[]>([]);
  const [refinementPrompt, setRefinementPrompt] = useState("");

  // Load Excel Lib
  useEffect(() => {
    if (!window.XLSX) {
      const script = document.createElement('script');
      script.src = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
      script.async = true;
      script.onload = () => setIsExcelReady(true);
      document.body.appendChild(script);
    } else {
      setIsExcelReady(true);
    }
  }, []);

  useEffect(() => {
    if (request) {
      setLocalFiles(request.rfpFiles || []); 

      // If opened in estimator mode, default to that tab
      if (request.mode === 'estimator' && status === 'idle') {
         setActiveSubTab('estimator');
      }

      if (designCache[request.id]) {
        const cached = designCache[request.id];
        setCurrentDesign(cached.design);
        setQuestions(cached.questions);
        setRequirements(cached.requirements);
        setInitiationItems(cached.initiation || []);
        if (cached.estimationInputs) setEstimationInputs(cached.estimationInputs);
        setStatus(cached.status);
      } else {
        setStatus('idle');
        setCurrentDesign({ nodes: [], edges: [] });
        setQuestions([]);
        setRequirements([]);
        setInitiationItems([]);

        // Initialize Inputs
        const initialInputs: Record<string, number> = {};
        ALL_MODULES_CONFIG.forEach(mod => {
          mod.drivers.forEach(driver => {
            initialInputs[driver.id] = driver.defaultValue;
          });
        });
        setEstimationInputs(initialInputs);
      }
    }
  }, [request, designCache]);

  // --- Estimator Calculations ---
  const baseCalculations = useMemo(() => {
    let totalTechHours = 0;
    const moduleBreakdown: Record<string, number> = {};

    modules.forEach(m => moduleBreakdown[m.id] = 0);

    modules.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const qty = estimationInputs[driver.id] || 0;
        modHours += qty * driver.multiplier;
      });
      moduleBreakdown[mod.id] = modHours;
      totalTechHours += modHours;
    });

    const testingBuffer = totalTechHours * 0.30; 
    const grandTotalTechHours = totalTechHours + testingBuffer;
    const teamVelocityPerWeek = 3 * 40; 
    const inceptionWeeks = Math.max(2, grandTotalTechHours * 0.10 / teamVelocityPerWeek);

    const implementationWeeks: Record<string, number> = {};
    modules.forEach(mod => {
      implementationWeeks[mod.id] = moduleBreakdown[mod.id] / teamVelocityPerWeek;
    });

    const uatWeeks = Math.max(2, testingBuffer / teamVelocityPerWeek);
    const totalProjectWeeks = inceptionWeeks + Math.max(...Object.values(implementationWeeks), 0) + uatWeeks;

    return { moduleBreakdown, totalTechHours, testingBuffer, grandTotalTechHours, inceptionWeeks, implementationWeeks, uatWeeks, totalProjectWeeks };
  }, [estimationInputs, modules]);

  // --- Resource Plan Logic ---
  useEffect(() => {
    if (isAutoStaffing) {
      const duration = Math.max(4, baseCalculations.totalProjectWeeks);
      const devCount = Math.ceil(baseCalculations.totalTechHours / (duration * 40 * 0.85)) || 1;
      const qaCount = Math.ceil(baseCalculations.testingBuffer / (duration * 40 * 0.85)) || 1;

      const newPlan: ResourceRow[] = [
        { id: 'pm', role: 'Project Manager', count: 1, utilization: 50, rate: 800, durationWeeks: duration },
        { id: 'arch', role: 'Solution Architect', count: 1, utilization: 25, rate: 950, durationWeeks: duration },
        { id: 'lead', role: 'Technical Lead', count: 1, utilization: 100, rate: 750, durationWeeks: duration },
        { id: 'dev', role: 'Developer/Consultant', count: devCount, utilization: 100, rate: 500, durationWeeks: duration },
        { id: 'qa', role: 'QA Specialist', count: qaCount, utilization: 100, rate: 450, durationWeeks: duration },
      ];
      setResourcePlan(newPlan);
    }
  }, [baseCalculations, isAutoStaffing]);

  const financialCalculations = useMemo(() => {
    let totalCost = 0;
    let totalDays = 0;
    resourcePlan.forEach(row => {
      const rowDays = (row.durationWeeks * 5) * row.count * (row.utilization / 100);
      const rowCost = rowDays * row.rate;
      totalCost += rowCost;
      totalDays += rowDays;
    });
    return { totalCost, totalDays };
  }, [resourcePlan]);

  // Chart Data
  const chartData = useMemo(() => {
    return modules.map(mod => ({
      name: mod.title,
      value: baseCalculations.moduleBreakdown[mod.id],
      color: mod.color
    })).filter(item => item.value > 0);
  }, [modules, baseCalculations]);

  const resourceChartData = useMemo(() => {
    return resourcePlan.map(r => ({
      name: r.role,
      cost: (r.durationWeeks * 5) * r.count * (r.utilization / 100) * r.rate
    })).filter(i => i.cost > 0);
  }, [resourcePlan]);


  // --- Generation Handler ---
  const handleGenerate = async (promptOverride: string | null = null) => {
    if (!request) return;
    setStatus('thinking');
    setThoughts([]);

    const audience = request.targetAudience || ['Developer']; 
    const baseThoughts = [
      `Reading ${localFiles.length} Documents...`,
      `Synthesizing technical architecture...`,
      "Analyzing MDM & Governance patterns...",
      "Drafting HLD Diagram..."
    ];

    if (request.mode === 'estimator' || activeSubTab === 'estimator') {
        baseThoughts.push("Calculating effort drivers...");
        baseThoughts.push("Estimating resource plan...");
    }

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 600)); 
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    const context = extractTextFromMock(localFiles) + (promptOverride ? ` Refinement: ${promptOverride}` : "");

    try {
      const design = await generateArchitectureDesign(context, request.type);

      const [generatedQuestions, generatedRequirements, generatedInitiation, generatedEstimation] = await Promise.all([
        generateIntelligentQuestionnaire(context, request.type, audience),
        generateProjectRequirements(context, request.type, audience),
        generateInitiationChecklist(context, request.type, audience),
        generateEstimation(context, request.type)
      ]);

      setCurrentDesign(design);
      setQuestions(generatedQuestions);
      setRequirements(generatedRequirements);
      setInitiationItems(generatedInitiation);

      // Update Inputs safely
      setEstimationInputs(prev => ({...prev, ...generatedEstimation}));

      setStatus('review');
    } catch (e) {
      console.error("Generation failed", e);
      setStatus('idle');
    }
  };

  const handleAcceptDesign = () => {
    if (request) {
      const cacheData: CachedRequestData = {
        design: currentDesign,
        questions: questions,
        requirements: requirements,
        initiation: initiationItems,
        estimationInputs: estimationInputs,
        status: 'accepted'
      };
      onUpdateDesignCache(request.id, cacheData);
      setStatus('accepted');
      const context = extractTextFromMock(localFiles);
      learnFromProject(context, currentDesign, request.targetAudience);
    }
  };

  const handleUpdateDesignFromRefinement = (newDesign: DesignData) => {
     setCurrentDesign(newDesign);
  };

  const handleAddFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFileName = e.target.files[0].name;
      if (!localFiles.includes(newFileName)) {
        setLocalFiles(prev => [...prev, newFileName]);
      }
    }
  };

  // --- XLSX Export ---
  const exportXLSX = () => {
    if (!window.XLSX) { alert("Library loading..."); return; }
    const XLSX = window.XLSX;
    const workbook = XLSX.utils.book_new();

    const summaryData = [
      ["ESTIMATION SUMMARY"], ["Total Cost", financialCalculations.totalCost], ["Total Hours", baseCalculations.grandTotalTechHours]
    ];
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(summaryData), "Summary");
    XLSX.writeFile(workbook, "Estimation.xlsx");
  };

  if (!request) return <div className="p-8 text-center text-slate-400">Select a request...</div>;

  const getCriticalityColor = (level: string) => {
    switch(level) {
      case 'High': return 'bg-red-100 text-red-700 border-red-200';
      case 'Medium': return 'bg-orange-100 text-orange-700 border-orange-200';
      default: return 'bg-blue-100 text-blue-700 border-blue-200';
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-fade-in relative">
      <AiAssistant context={extractTextFromMock(localFiles)} />

      <div className="bg-white border-b border-slate-200 px-8 py-4 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-3 mb-1">
            <h2 className="text-xl font-bold text-slate-800">{request.id}: {request.clientName}</h2>
            <div className="flex gap-1">
               <span className="px-2 py-0.5 rounded text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">{request.type}</span>
            </div>
          </div>
          <p className="text-xs text-slate-500">AI Managed • Context Aware</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 hide-scrollbar">
          {['attachments', 'initiation', 'design', 'requirements', 'scoping', 'estimator'].map((tab) => (
             <button 
               key={tab}
               onClick={() => setActiveSubTab(tab as any)}
               className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap capitalize ${activeSubTab === tab ? 'bg-orange-100 text-orange-700' : 'text-slate-600 hover:bg-slate-100'}`}
             >
               {tab}
             </button>
          ))}
        </div>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">

        {/* EXISTING ATTACHMENTS TAB */}
        {activeSubTab === 'attachments' && (
          <div className="max-w-4xl mx-auto animate-fade-in">
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
               <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                  <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                    <Paperclip className="text-indigo-500" /> Attached Documents
                  </h3>
                  <div className="flex gap-2">
                    <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-medium transition-colors">
                      <Plus size={16} /> Add Document
                      <input type="file" className="hidden" onChange={handleAddFile} />
                    </label>
                  </div>
               </div>

               <div className="space-y-3 mb-8">
                  {localFiles.length === 0 ? (
                    <p className="text-slate-400 text-center py-8">No documents attached.</p>
                  ) : (
                    localFiles.map((file, idx) => (
                      <div key={idx} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-200 group">
                        <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center">
                            <FileText size={20} />
                          </div>
                          <div>
                            <p className="text-sm font-bold text-slate-800">{file}</p>
                            <p className="text-xs text-slate-500">Uploaded Doc</p>
                          </div>
                        </div>
                        <button className="text-slate-400 hover:text-red-500 transition-colors">
                          <X size={18} />
                        </button>
                      </div>
                    ))
                  )}
               </div>

               <div className="bg-orange-50 rounded-xl p-6 border border-orange-100 flex items-center justify-between">
                  <div>
                    <h4 className="font-bold text-orange-900 mb-1">Context Changed?</h4>
                    <p className="text-sm text-orange-700">If you've added new documents, regenerate the design to include new context.</p>
                  </div>
                  <button 
                    onClick={() => handleGenerate()} 
                    className="flex items-center gap-2 px-6 py-3 bg-orange-600 hover:bg-orange-700 text-white font-bold rounded-lg shadow-sm transition-all"
                  >
                    <RefreshCw size={18} /> Regenerate Design
                  </button>
               </div>
             </div>
          </div>
        )}

        {activeSubTab === 'initiation' && (
          <div className="max-w-6xl mx-auto animate-fade-in">
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
               <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
                  <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><BookOpen className="text-orange-500" /> AI-Generated Initiation Checklist</h3>
                  <button className="text-sm text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg">Export</button>
               </div>
               {initiationItems.length === 0 ? (
                 <div className="text-center py-8"><p className="text-slate-400">Generate the solution to see the checklist.</p></div>
               ) : (
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                   {initiationItems.map((sec, idx) => (
                     <div key={idx} className="bg-slate-50 rounded-xl p-5 border border-slate-200">
                        <div className="flex items-center gap-3 mb-4"><div className="bg-white p-2 rounded-lg shadow-sm"><CheckCircle size={20} className="text-blue-500"/></div><h4 className="font-bold text-slate-800 text-sm">{sec.title}</h4></div>
                        <ul className="space-y-3">{sec.items.map((it, i) => <li key={i} className="flex items-start gap-2 text-sm text-slate-600"><div className="mt-1 w-1.5 h-1.5 bg-slate-300 rounded-full shrink-0"/>{it}</li>)}</ul>
                     </div>
                   ))}
                 </div>
               )}
             </div>
          </div>
        )}

        {activeSubTab === 'requirements' && (
           <div className="max-w-6xl mx-auto space-y-6 animate-fade-in">
              <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                 <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><List className="text-blue-500" /> Role-Based Requirements</h3>
                 {requirements.length === 0 ? <p className="text-slate-400">No requirements generated.</p> : (
                    <div className="grid grid-cols-1 gap-4">
                      {requirements.map((req, i) => (
                        <div key={i} className="flex items-start gap-4 p-4 rounded-lg bg-slate-50 border border-slate-100">
                          <div className="p-2 rounded-lg bg-white border border-slate-200 text-slate-600"><CheckCircle size={18} /></div>
                          <div className="flex-1">
                             <div className="flex justify-between items-start mb-1">
                               <h4 className="font-semibold text-slate-800 text-sm">{req.item}</h4>
                               <div className="flex gap-2">
                                  {req.audience && <span className="text-[10px] bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded border border-indigo-200">{req.audience}</span>}
                                  <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded border ${getCriticalityColor(req.criticality)}`}>{req.criticality}</span>
                               </div>
                             </div>
                             <p className="text-sm text-slate-500">{req.description}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                 )}
              </div>
           </div>
        )}

        {activeSubTab === 'scoping' && (
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 max-w-6xl mx-auto animate-fade-in p-6">
                <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><ClipboardList className="text-orange-500" /> Scoping Questionnaire</h3>
                {questions.length === 0 ? <p className="text-slate-400">No questions generated.</p> : (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {questions.map((q, i) => (
                        <div key={i} className="p-3 rounded-lg border border-slate-200">
                           <label className="block text-sm font-semibold text-slate-800 mb-2">{q.question}</label>
                           <textarea className="w-full p-3 border border-slate-300 rounded-lg text-sm bg-white min-h-[80px]" placeholder="Pending Response..." defaultValue={q.answer} />
                        </div>
                      ))}
                   </div>
                )}
            </div>
        )}

        {/* --- ESTIMATOR TAB --- */}
        {activeSubTab === 'estimator' && (
            <div className="max-w-7xl mx-auto space-y-8 animate-fade-in">

               {/* 1. Dashboard / Summary */}
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                     <div className="flex items-center gap-3 mb-4"><div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Clock size={20}/></div><span className="text-sm font-medium text-slate-500 uppercase">Effort</span></div>
                     <div className="text-3xl font-bold text-slate-800">{baseCalculations.grandTotalTechHours.toFixed(0)} <span className="text-lg font-normal text-slate-400">hrs</span></div>
                  </div>
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                     <div className="flex items-center gap-3 mb-4"><div className="p-2 bg-green-100 text-green-600 rounded-lg"><DollarSign size={20}/></div><span className="text-sm font-medium text-slate-500 uppercase">Total Cost</span></div>
                     <div className="text-3xl font-bold text-slate-800">{formatCurrency(financialCalculations.totalCost)}</div>
                  </div>
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                     <div className="flex items-center gap-3 mb-4"><div className="p-2 bg-purple-100 text-purple-600 rounded-lg"><Calendar size={20}/></div><span className="text-sm font-medium text-slate-500 uppercase">Duration</span></div>
                     <div className="text-3xl font-bold text-slate-800">~{baseCalculations.totalProjectWeeks.toFixed(1)} <span className="text-lg font-normal text-slate-400">wks</span></div>
                  </div>
               </div>

               {/* 2. Charts Row */}
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
                     <h3 className="font-bold text-slate-800 mb-6">Effort Distribution</h3>
                     <div className="flex-1 min-h-[300px]">
                        <ResponsiveContainer width="100%" height="100%">
                           <PieChart>
                              <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                 {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                              </Pie>
                              <RechartsTooltip formatter={(value: number) => `${value.toFixed(0)} hrs`} />
                              <Legend verticalAlign="bottom" height={36}/>
                           </PieChart>
                        </ResponsiveContainer>
                     </div>
                  </div>

                  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
                     <h3 className="font-bold text-slate-800 mb-6">Resource Cost</h3>
                     <div className="flex-1 min-h-[300px]">
                         <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={resourceChartData} layout="vertical" margin={{ top: 5, right: 30, left: 10, bottom: 5 }}>
                               <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false}/>
                               <XAxis type="number" tickFormatter={(val) => `$${val/1000}k`} stroke="#9CA3AF" fontSize={12}/>
                               <YAxis dataKey="name" type="category" width={90} tick={{fontSize: 10, fill: '#4B5563'}} />
                               <RechartsTooltip formatter={(value: number) => formatCurrency(value)} />
                               <Bar dataKey="cost" fill="#3B82F6" radius={[0, 4, 4, 0]} barSize={20} />
                            </BarChart>
                         </ResponsiveContainer>
                     </div>
                  </div>
               </div>

               {/* 3. Detailed Input Table */}
               <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                  <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                     <h3 className="font-bold text-slate-800">Estimation Drivers</h3>
                     <button onClick={() => setShowConfig(!showConfig)} className="text-sm text-blue-600 font-medium flex items-center gap-1"><Settings size={14} /> Config</button>
                  </div>
                  <div className="p-6 space-y-8">
                     {modules.map(mod => (
                        <div key={mod.id}>
                           <div className="flex items-center gap-2 mb-4">
                              <mod.icon className="text-white p-1 rounded w-6 h-6" style={{backgroundColor: mod.color}} />
                              <h4 className="font-bold text-slate-800">{mod.title}</h4>
                           </div>
                           <table className="min-w-full divide-y divide-slate-100">
                              <thead className="bg-slate-50 font-[Arial]">
                                 <tr>
                                    <th className="px-4 py-2 text-left text-xs font-bold text-black uppercase w-1/3">Driver</th>
                                    <th className="px-4 py-2 text-left text-xs font-bold text-black uppercase">Category</th>
                                    <th className="px-4 py-2 text-left text-xs font-bold text-black uppercase">Qty</th>
                                    <th className="px-4 py-2 text-left text-xs font-bold text-black uppercase">Hours/Unit</th>
                                    <th className="px-4 py-2 text-right text-xs font-bold text-black uppercase">Total</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-50 font-[Cambria]">
                                 {mod.drivers.map(driver => (
                                    <tr key={driver.id}>
                                       <td className="px-4 py-3 text-sm font-medium text-slate-700">
                                          {driver.label}
                                          <p className="text-xs text-slate-400 font-normal">{driver.description}</p>
                                       </td>
                                       <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${driver.category === 'complex' ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'}`}>{driver.category}</span></td>
                                       <td className="px-4 py-3">
                                          <input 
                                            type="number" 
                                            min="0"
                                            className="w-20 bg-white border border-black rounded p-1 text-sm text-black focus:ring-2 focus:ring-blue-500 outline-none font-[Cambria]"
                                            value={estimationInputs[driver.id] || 0}
                                            onChange={(e) => setEstimationInputs(prev => ({...prev, [driver.id]: parseInt(e.target.value) || 0}))}
                                          />
                                       </td>
                                       <td className="px-4 py-3 text-sm text-slate-500">
                                          {showConfig ? (
                                             <input type="number" className="w-16 border rounded p-1" defaultValue={driver.multiplier} />
                                          ) : `${driver.multiplier} hrs`}
                                       </td>
                                       <td className="px-4 py-3 text-sm font-bold text-slate-800 text-right">
                                          {((estimationInputs[driver.id] || 0) * driver.multiplier).toFixed(1)}
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     ))}
                  </div>
               </div>

               {/* 4. Export */}
               <div className="flex justify-end">
                  <button onClick={exportXLSX} className={`flex items-center gap-2 px-6 py-3 rounded-lg text-white font-bold shadow-sm transition-all ${isExcelReady ? 'bg-green-600 hover:bg-green-700' : 'bg-slate-300 cursor-not-allowed'}`}>
                     <Download size={18} /> Export Full Report (XLSX)
                  </button>
               </div>

            </div>
        )}

        {/* --- DESIGN TAB (EXISTING) --- */}
        {activeSubTab === 'design' && (
          <div className="h-full flex flex-col relative bg-slate-50/50">
             {/* Background Blob Animation */}
             <div className="absolute inset-0 overflow-hidden pointer-events-none">
                <div className="absolute -top-[20%] -left-[10%] w-[500px] h-[500px] bg-purple-300/20 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-blob"></div>
                <div className="absolute -top-[20%] -right-[10%] w-[500px] h-[500px] bg-indigo-300/20 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-blob animation-delay-2000"></div>
                <div className="absolute -bottom-[20%] left-[20%] w-[500px] h-[500px] bg-blue-300/20 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-blob animation-delay-4000"></div>
             </div>

            {status === 'idle' ? (
              <div className="flex-1 flex flex-col items-center justify-center p-8 z-10">
                <div className="max-w-3xl w-full bg-white/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/60 p-10 text-center relative overflow-hidden">
                   <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>

                   <div className="mb-8 relative inline-block">
                      <div className="absolute inset-0 bg-indigo-500 blur-xl opacity-20 rounded-full"></div>
                      <div className="relative bg-gradient-to-br from-white to-slate-100 p-4 rounded-2xl shadow-inner border border-slate-100">
                         <PenTool size={48} className="text-indigo-600" />
                      </div>
                   </div>

                   <h3 className="text-3xl font-bold text-slate-800 mb-4 tracking-tight">Design Architecture</h3>
                   <p className="text-slate-600 text-lg mb-10 max-w-xl mx-auto leading-relaxed">
                     Generate a comprehensive High-Level Design (HLD) diagram and specifications based on your 
                     <span className="font-semibold text-indigo-700 bg-indigo-50 px-2 py-0.5 rounded mx-1">{localFiles.length} uploaded documents</span>.
                   </p>

                   <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
                      {[
                        { icon: Workflow, label: 'Data Pipelines', color: 'text-blue-500', bg: 'bg-blue-50' },
                        { icon: ShieldCheck, label: 'Quality Rules', color: 'text-emerald-500', bg: 'bg-emerald-50' },
                        { icon: Layers, label: 'MDM Models', color: 'text-amber-500', bg: 'bg-amber-50' }
                      ].map((item, i) => (
                        <div key={i} className={`${item.bg} p-4 rounded-2xl border border-transparent hover:border-slate-200 transition-all duration-300 hover:shadow-md`}>
                           <item.icon className={`${item.color} mb-2 mx-auto`} size={28} />
                           <p className="font-bold text-slate-700 text-sm">{item.label}</p>
                        </div>
                      ))}
                   </div>

                   <button 
                     onClick={() => handleGenerate()} 
                     className="w-full sm:w-auto px-10 py-4 bg-slate-900 hover:bg-slate-800 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5 flex items-center justify-center gap-3 mx-auto"
                   >
                     <Sparkles size={20} className="text-yellow-400" />
                     Generate Blueprint
                   </button>

                   <p className="mt-6 text-xs font-medium text-slate-400 uppercase tracking-widest">Powered by Google Gemini Pro</p>
                </div>
              </div>
            ) : status === 'review' ? (
               <div className="flex flex-col h-full animate-fade-in relative z-10">
                  <div className="bg-white/90 backdrop-blur-md border-b border-slate-200 p-4 flex justify-between items-center shadow-sm">
                     <div className="flex items-center gap-4">
                        <div className="bg-indigo-100 p-2.5 rounded-xl text-indigo-600 shadow-sm border border-indigo-200">
                          <Lightbulb size={24} />
                        </div>
                        <div>
                          <h4 className="font-bold text-slate-800 text-lg">Review Design</h4>
                          <p className="text-xs font-medium text-slate-500 flex items-center gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span> AI Generated
                          </p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button 
                          onClick={() => handleGenerate()} 
                          className="flex items-center gap-2 px-5 py-2.5 bg-white text-slate-600 border border-slate-200 rounded-xl text-sm font-bold hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm"
                        >
                          <RefreshCw size={16} /> Regenerate
                        </button>
                        <button 
                          onClick={handleAcceptDesign} 
                          className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all"
                        >
                          <ThumbsUp size={16} /> Accept Design
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative bg-white/50 backdrop-blur-sm">
                     <ArchitectureCanvas 
                       aiNodes={currentDesign.nodes} 
                       aiEdges={currentDesign.edges} 
                       isThinking={false} 
                       thoughts={[]} 
                       context={extractTextFromMock(localFiles)} 
                       audience={request.targetAudience} 
                       onApplyRefinement={handleUpdateDesignFromRefinement} 
                     />
                     <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-2xl">
                        <div className="bg-white/90 backdrop-blur-xl shadow-2xl rounded-2xl border border-white/50 p-2 flex items-center gap-2 mx-4">
                            <div className="p-3 bg-slate-100 rounded-xl text-slate-500">
                              <MessageSquare size={20} />
                            </div>
                            <input 
                              type="text" 
                              placeholder="Tell AI to refine the diagram (e.g. 'Add a staging layer')..." 
                              className="flex-1 bg-transparent outline-none text-sm py-2 px-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                              value={refinementPrompt} 
                              onChange={(e) => setRefinementPrompt(e.target.value)} 
                              onKeyDown={(e) => e.key === 'Enter' && handleGenerate(refinementPrompt)} 
                            />
                            <button 
                              onClick={() => handleGenerate(refinementPrompt)} 
                              className="bg-indigo-600 hover:bg-indigo-700 text-white p-3 rounded-xl transition-all shadow-md"
                            >
                              <Send size={18} />
                            </button>
                        </div>
                     </div>
                  </div>
               </div>
            ) : (
              <div className="flex-1 bg-white/50 backdrop-blur-sm rounded-xl shadow-sm border border-slate-200 flex overflow-hidden flex-col m-4 relative z-10">
                <ArchitectureCanvas 
                  aiNodes={currentDesign.nodes} 
                  aiEdges={currentDesign.edges} 
                  isThinking={status === 'thinking'} 
                  thoughts={thoughts} 
                  context={extractTextFromMock(localFiles)} 
                  audience={request.targetAudience} 
                  onApplyRefinement={handleUpdateDesignFromRefinement} 
                />
                {status === 'accepted' && (
                  <div className="p-3 border-t border-slate-200 bg-white text-center">
                    <p className="text-xs font-bold text-emerald-600 flex items-center justify-center gap-2">
                      <CheckCircle size={14} /> Design Accepted & Saved
                    </p>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SolutionDesignView;

export interface RequestData {
  id: string;
  clientName: string;
  product: string; // e.g., 'Informatica', 'Talend', 'Azure'
  deploymentModel: 'Cloud' | 'On-Premise' | 'Hybrid';
  type: string; // The specific tech stack/service
  rfpFiles: string[]; 
  targetAudience: string[]; 
  date: string;
  mode?: 'design' | 'estimator';
}

export interface Node {
  id: string;
  label: string;
  description?: string; 
  type: 'source' | 'stage' | 'process' | 'target';
  x: number;
  y: number;
}

export interface Edge {
  from: string;
  to: string;
  label: string;
}

export interface DesignData {
  nodes: Node[];
  edges: Edge[];
}

export interface Question {
  id: string;
  category: string;
  question: string;
  answer: string;
  isCustom?: boolean;
}

export interface Requirement {
  id: string;
  category: 'Infrastructure' | 'Network' | 'Security' | 'License' | 'Development' | 'Testing' | 'Admin';
  item: string;
  description: string;
  criticality: 'High' | 'Medium' | 'Low';
  audience?: string;
}

export interface DataQualityRule {
  id: string;
  name: string;
  description: string;
  type: 'Completeness' | 'Uniqueness' | 'Validity' | 'Consistency' | 'Accuracy' | 'Timeliness';
  criticality: 'High' | 'Medium' | 'Low';
}

export interface InitiationItem {
  title: string;
  iconType: string;
  items: string[];
}

// --- ESTIMATOR TYPES ---
export interface EffortDriver {
  id: string;
  label: string;
  category: 'simple' | 'medium' | 'complex' | 'fixed';
  defaultValue: number;
  multiplier: number; // Hours per unit
  description: string;
}

export interface ModuleConfig {
  id: string;
  title: string;
  icon?: any; // Avoiding complex types for icon in simple interface
  color: string;
  drivers: EffortDriver[];
}

export interface EstimationInputs {
  [driverId: string]: number;
}

export interface CachedRequestData {
  design: DesignData;
  questions: Question[];
  requirements: Requirement[];
  initiation: InitiationItem[];
  dataQualityRules?: DataQualityRule[];
  estimationInputs?: EstimationInputs;
