export const learnFromProject = async (context: string, finalDesign: DesignData, audience: string[]) => {
  try {
     const prompt = `
       Analyze this completed architecture design.
       Context: ${context}
       Roles Involved: ${audience.join(', ')}
       Design Nodes: ${JSON.stringify(finalDesign.nodes)}

       Extract 1 specific architectural rule or best practice from this that applies to these roles.
       Focus on nuances like "If role is Tester, verify TDM requirements" or "If role is Admin, check Firewall 443".
       Keep it under 20 words.
       Output format: Just the string.
     `;
     const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: prompt
     });

     if (response.text) {
       const newPattern = `Pattern (${audience[0]}): ${response.text.trim()}`;
       // Simple in-memory deduplication
       if (!LEARNED_PATTERNS.some(p => p.includes(response.text.trim().substring(0, 10)))) {
          LEARNED_PATTERNS.push(newPattern);
          console.log("AI Learned:", newPattern);
       }
     }
  } catch (e) {
    console.error("Learning failed", e);
  }
};

export const generateArchitectureDesign = async (
  context: string,
  solutionType: string
): Promise<DesignData> => {
  try {
    const prompt = `
      Act as a ${solutionType} Solution Architect.
      Create a High Level Design (HLD) diagram structure.

      CRITICAL INSTRUCTION: The design must be a pure technical solution flow independent of specific personnel roles. 
      Focus only on data movement, transformations, and component interaction specific to ${solutionType}.

      Knowledge Base: ${DATA_MANAGEMENT_KB}
      Learned Patterns: ${LEARNED_PATTERNS.join('\n')}

      Solution Type: ${solutionType}
      RFP/Context: ${context}

      Task:
      1. Analyze the RFP for key entities.
      2. Generate Nodes and Edges for the complete data pipeline.
      3. Populate the 'description' field for each node with technical specifications (e.g., protocols, data volumes, latency requirements).
      4. Layout: Sources Left (x~50), Targets Right (x~900).
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: architectureSchema,
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as DesignData;
    }
    return { nodes: [], edges: [] };
  } catch (error) {
    console.error("AI design error:", error);
    return { nodes: [], edges: [] };
  }
};

