import CreateForm from './components/CreateForm';
import SolutionDesignView from './components/SolutionDesign';
import LoginPage from './components/LoginPage';
import { RequestData, DesignCache } from './types';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Tabs: 'dashboard' | 'create' | 'design'
  const [activeTab, setActiveTab] = useState('dashboard');

  const [selectedRequest, setSelectedRequest] = useState<RequestData | null>(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [designCache, setDesignCache] = useState<DesignCache>({});

  // Refreshed state with diverse mock data
  const [requests, setRequests] = useState<RequestData[]>([
    {
      id: 'REQ-1005',
      clientName: 'HealthCare Plus',
      product: 'Databricks',
      deploymentModel: 'Cloud',
      type: 'Unity Catalog',
      rfpFiles: ['lakehouse_governance_rfp.pdf', 'hipaa_compliance.docx'],
      targetAudience: ['Admin', 'Developer'],
      date: '10/27/2023'
    },
    {
      id: 'REQ-1004',
      clientName: 'City Gov Dept',
      product: 'Profisee',
      deploymentModel: 'Cloud',
      type: 'Profisee MDM SaaS',
      rfpFiles: ['citizen_360_requirements.pdf'],
      targetAudience: ['Developer'],
      date: '10/26/2023'
    },
    {
      id: 'REQ-1003',
      clientName: 'Tech StartUp',
      product: 'Azure Data Factory',
      deploymentModel: 'Cloud',
      type: 'Data Factory V2',
      rfpFiles: ['analytics_pipeline.pdf'],
      targetAudience: ['Developer'],
      date: '10/26/2023'
    },
    {
      id: 'REQ-1002',
      clientName: 'Retail Giant',
      product: 'Informatica',
      deploymentModel: 'Cloud',
      type: 'MDM SaaS',
      rfpFiles: ['customer_360_view.docx', 'requirements_v2.pdf'],
      targetAudience: ['Developer', 'Tester'],
      date: '10/25/2023'
    },
    {
      id: 'REQ-1001',
      clientName: 'Global FinCorp',
      product: 'Informatica',
      deploymentModel: 'On-Premise',
      type: 'PowerCenter',
      rfpFiles: ['mainframe_migration_rfp.pdf'],
      targetAudience: ['Developer', 'Admin'],
      date: '10/24/2023'
    }
  ]);
  const [nextId, setNextId] = useState(1006);

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const handleCreateSubmit = (newRequest: any) => {
    const requestWithId: RequestData = {
      ...newRequest,
      id: `REQ-${nextId}`
    };
    setRequests([requestWithId, ...requests]);
    setNextId(prev => prev + 1);

    // Auto-redirect to design view for the new request
    setSelectedRequest(requestWithId);
    setActiveTab('design');
  };

  const handleSelectRequest = (req: RequestData) => {
    setSelectedRequest(req);
    setActiveTab('design');
  };

  const handleUpdateDesignCache = (reqId: string, designData: any) => {
    setDesignCache(prev => ({
      ...prev,
      [reqId]: designData
    }));
  };

  if (!isLoggedIn) {
    return <LoginPage onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden">
      <Sidebar 
        activeTab={activeTab === 'design' ? 'dashboard' : activeTab} // If in design, sidebar shows dashboard as active parent
        setActiveTab={setActiveTab} 
        isMobileOpen={isMobileOpen}
        setIsMobileOpen={setIsMobileOpen}
        onLogout={handleLogout}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <Header 
          title="HTC Data Management Accelerator" 
          toggleSidebar={() => setIsMobileOpen(true)}
        />

        <main className="flex-1 overflow-y-auto relative scroll-smooth bg-slate-50">
          {activeTab === 'dashboard' ? (
            <DashboardView requests={requests} onSelectRequest={handleSelectRequest} />
          ) : activeTab === 'design' ? (
            <SolutionDesignView 
               request={selectedRequest} 
               designCache={designCache}
               onUpdateDesignCache={handleUpdateDesignCache}
            />
          ) : (
            <CreateForm 
              onSubmit={handleCreateSubmit} 
              onCancel={() => setActiveTab('dashboard')} 
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

