        Current Knowledge Base Size: ${LEARNED_PATTERNS.length} patterns.

        Task:
        Identify a reusable pattern or architectural rule from this specific interaction. 
        If the User Refinement Prompt exists, focus on what was requested and how it changes standard designs.

        Format: "Pattern: [Condition] -> [Recommendation]"
        Max 25 words.
     `;

     const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt
     });

     if (response.text && response.text.trim().startsWith("Pattern:")) {
        savePattern(response.text.trim());
     }
   } catch (e) {
     console.error("Learning cycle failed", e);
   }
};

