                      {[
                        { icon: Workflow, label: 'Data Pipelines', color: 'text-blue-500', bg: 'bg-blue-50' },
                        { icon: ShieldCheck, label: 'Quality Rules', color: 'text-emerald-500', bg: 'bg-emerald-50' },
                        { icon: Layers, label: 'MDM Models', color: 'text-amber-500', bg: 'bg-amber-50' }
                      ].map((item, i) => (
                        <div key={i} className={`${item.bg} p-4 rounded-2xl border border-transparent hover:border-slate-200 transition-all duration-300 hover:shadow-md`}>
                           <item.icon className={`${item.color} mb-2 mx-auto`} size={28} />
                           <p className="font-bold text-slate-700 text-sm">{item.label}</p>
                        </div>
                      ))}
                   </div>

                   <button 
                     onClick={() => handleGenerate()} 
                     className="w-full sm:w-auto px-10 py-4 bg-slate-900 hover:bg-slate-800 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5 flex items-center justify-center gap-3 mx-auto"
                   >
                     <Sparkles size={20} className="text-yellow-400" />
                     Generate Blueprint
                   </button>

                   <p className="mt-6 text-xs font-medium text-slate-400 uppercase tracking-widest">Powered by Google Gemini Pro</p>
                </div>
              </div>
            ) : status === 'review' ? (
               <div className="flex flex-col h-full animate-fade-in relative z-10">
                  <div className="bg-white/90 backdrop-blur-md border-b border-slate-200 p-4 flex justify-between items-center shadow-sm">
                     <div className="flex items-center gap-4">
                        <div className="bg-indigo-100 p-2.5 rounded-xl text-indigo-600 shadow-sm border border-indigo-200">
                          <Lightbulb size={24} />
                        </div>
                        <div>
                          <h4 className="font-bold text-slate-800 text-lg">Review Design</h4>
                          <p className="text-xs font-medium text-slate-500 flex items-center gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span> AI Generated
                          </p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button 
                          onClick={() => handleGenerate()} 
                          className="flex items-center gap-2 px-5 py-2.5 bg-white text-slate-600 border border-slate-200 rounded-xl text-sm font-bold hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm"
                        >
                          <RefreshCw size={16} /> Regenerate
                        </button>
                        <button 
                          onClick={handleAcceptDesign} 
                          className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all"
                        >
                          <ThumbsUp size={16} /> Accept Design
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative bg-white/50 backdrop-blur-sm">
                     <ArchitectureCanvas 
                       aiNodes={currentDesign.nodes} 
                       aiEdges={currentDesign.edges} 
                       isThinking={false} 
                       thoughts={[]} 
                       context={getContextFromRequest(request)} 
                       audience={request.targetAudience} 
                       onApplyRefinement={handleUpdateDesignFromRefinement} 
                     />
                     <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-2xl">
                        <div className="bg-white/90 backdrop-blur-xl shadow-2xl rounded-2xl border border-white/50 p-2 flex items-center gap-2 mx-4">
                            <div className="p-3 bg-slate-100 rounded-xl text-slate-500">
                              <MessageSquare size={20} />
                            </div>
                            <input 
                              type="text" 
                              placeholder="Tell AI to refine the diagram (e.g. 'Add a staging layer')..." 
                              className="flex-1 bg-transparent outline-none text-sm py-2 px-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                              value={refinementPrompt} 
                              onChange={(e) => setRefinementPrompt(e.target.value)} 
                              onKeyDown={(e) => e.key === 'Enter' && handleGenerate(refinementPrompt)} 
                            />
                            <button 
                              onClick={() => handleGenerate(refinementPrompt)} 
                              className="bg-indigo-600 hover:bg-indigo-700 text-white p-3 rounded-xl transition-all shadow-md"
                            >
                              <Send size={18} />
                            </button>
                        </div>
                     </div>
                  </div>
               </div>
            ) : (
              <div className="flex-1 bg-white/50 backdrop-blur-sm rounded-xl shadow-sm border border-slate-200 flex overflow-hidden flex-col m-4 relative z-10">
                <ArchitectureCanvas 
                  aiNodes={currentDesign.nodes} 
                  aiEdges={currentDesign.edges} 
                  isThinking={status === 'thinking'} 
                  thoughts={thoughts} 
                  context={getContextFromRequest(request)} 
                  audience={request.targetAudience} 
                  onApplyRefinement={handleUpdateDesignFromRefinement} 
                />
                {status === 'accepted' && (
                  <div className="p-3 border-t border-slate-200 bg-white text-center">
                    <p className="text-xs font-bold text-emerald-600 flex items-center justify-center gap-2">
                      <CheckCircle size={14} /> Design Accepted & Saved
                    </p>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

