import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import { getRequest, updateRequest } from '@/lib/api';
import { useToast } from '@/components/ui/use-toast';
import { Loader } from 'lucide-react';
import { Sparkles } from 'lucide-react';

interface Request {
  id: string;
  name: string;
  description: string;
  status: string;
  mode: string;
  data?: any;
}

const SolutionDesignView = ({ requestId }: { requestId: string }) => {
  const [request, setRequest] = useState<Request | null>(null);
  const [status, setStatus] = useState<'idle' | 'loading' | 'thinking' | 'error'>('idle');
  const router = useRouter();
  const { data: session } = useSession();
  const { toast } = useToast();

  useEffect(() => {
    const fetchRequest = async () => {
      setStatus('loading');
      try {
        const data = await getRequest(requestId);
        if (data) {
          setRequest(data);
          setStatus(data.status === 'thinking' ? 'thinking' : 'idle');
        } else {
          toast({ title: 'Error', description: 'Request not found', variant: 'destructive' });
          router.push('/dashboard');
        }
      } catch (error) {
        console.error('Failed to fetch request:', error);
        toast({ title: 'Error', description: 'Failed to fetch request', variant: 'destructive' });
        setStatus('error');
      }
    };

    if (requestId) {
      fetchRequest();
    }
  }, [requestId, router, toast]);

  const handleGenerate = async (e: any, mode: string) => {
    e?.preventDefault();
    if (!request) return;

    setStatus('thinking');
    try {
      await updateRequest(requestId, { status: 'thinking' });
      const updatedRequest = await getRequest(requestId);
      if (updatedRequest) {
        setRequest(updatedRequest);
      }
      // handleHldGeneration({ requestId, mode });

      toast({
        title: 'Success',
        description: 'HLD generation started',
        duration: 5000,
      });
    } catch (error) {
      console.error('Failed to generate blueprint:', error);
      toast({
        title: 'Error',
        description: 'Failed to generate blueprint',
        variant: 'destructive',
      });
    } finally {
      setStatus('idle');
    }
  };

  if (!request) {
    return (
      <div className="flex items-center justify-center h-screen">
        <Loader className="animate-spin" size={32} />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-gray-100">
      <div className="bg-white shadow-md p-4">
        <h2 className="text-xl font-bold">{request.name}</h2>
        <div className="mt-2 text-gray-600">{request.description}</div>
      </div>
      <div className="flex items-center justify-between p-4 bg-white shadow-md">
        <div className="flex space-x-4">
          <button
            onClick={() => {
              // Set the active tab to design
            }}
            className="px-4 py-2 bg-gray-200 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            Design
          </button>
          <button
            onClick={() => {
              // Set the active tab to estimator
            }}
            className="px-4 py-2 bg-gray-200 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >

