               <div className="bg-orange-50 rounded-xl p-6 border border-orange-100 flex items-center justify-between">
                  <div>
                    <h4 className="font-bold text-orange-900 mb-1">Context Changed?</h4>
                    <p className="text-sm text-orange-700">If you've added new documents, regenerate to include new context.</p>
                  </div>
                  <button 
                    onClick={() => handleGenerate(null, request.mode || 'design')} 
                    className="flex items-center gap-2 px-6 py-3 bg-orange-600 hover:bg-orange-700 text-white font-bold rounded-lg shadow-sm transition-all"
                  >
                    <RefreshCw size={18} /> Recalculate
                  </button>
               </div>
             </div>
          </div>
        )}

        {/* DATA QUALITY TAB */}
        {activeSubTab === 'dataQuality' && (
           <div className="max-w-6xl mx-auto space-y-6 animate-fade-in">
              <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 relative">
                 <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-100">
                    <div className="flex items-center gap-3">
                       <div className="bg-emerald-100 p-2 rounded-lg text-emerald-600"><ShieldCheck size={24}/></div>
                       <div>
                         <h3 className="text-lg font-bold text-slate-800">Data Quality Rules</h3>
                         <p className="text-xs text-slate-500">Define validation logic for critical data elements</p>
                       </div>
                    </div>
                    <button 
                       onClick={() => setShowRuleForm(true)}
                       className="flex items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white rounded-lg text-sm font-bold transition-all shadow-sm"
                    >
                       <Plus size={16} /> Add Rule
                    </button>
                 </div>

                 {/* Add Rule Form */}
                 {showRuleForm && (
                    <div className="mb-8 p-6 bg-slate-50 rounded-xl border border-slate-200 animate-fade-in-up">
                       <div className="flex justify-between items-center mb-4">
                          <h4 className="font-bold text-slate-800 text-sm">New Rule Definition</h4>
