// Function called on every interaction to continuously improve the model
export const analyzeAndLearn = async (
  context: string, 
  userPrompt: string | null,
  generatedDesign: DesignData,
  audience: string[]
) => {
   // Run in background, do not block main thread significantly
   try {
     const prompt = `
        You are the "Meta-Learning Module" of the HTC Data Management Accelerator.
        Your goal is to improve future generations by analyzing the current interaction.

        Input Context: ${context}
        User Refinement Prompt: ${userPrompt || "None (Initial Generation)"}
        Generated Nodes: ${generatedDesign.nodes.map(n => n.label + '(' + n.type + ')').join(', ')}
        Target Audience: ${audience.join(', ')}

        Current Knowledge Base Size: ${LEARNED_PATTERNS.length} patterns.

        Task:
        Identify a reusable pattern or architectural rule from this specific interaction. 
        If the User Refinement Prompt exists, focus on what was requested and how it changes standard designs.

        Format: "Pattern: [Condition] -> [Recommendation]"
        Max 25 words.
     `;

     const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt
     });

     if (response.text && response.text.trim().startsWith("Pattern:")) {
        savePattern(response.text.trim());
     }
   } catch (e) {
     console.error("Learning cycle failed", e);
   }
};

