export const sendChatMessage = async (
  history: {role: string, text: string}[],
  newMessage: string,
  context: string
): Promise<string> => {
   try {
     const prompt = `
       You are "AI Architect", an AI assistant for Data Management Solution Design.
       Context of current project: ${context}

       History:
       ${history.map(h => `${h.role}: ${h.text}`).join('\n')}

       User: ${newMessage}

       Answer concisely (max 3 sentences) and technically.
     `;

     const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: prompt
     });

     // Opportunistic learning from chat interactions
     if (response.text) {
        // We asynchronously analyze deeply insightful chat interactions
        if (history.length > 2 && newMessage.length > 20) {
           analyzeAndLearn(context, newMessage, {nodes: [], edges: []}, []); 
        }
     }

     return response.text || "I'm processing that design request, please wait...";
   } catch (e) {
     return "I encountered a connection error. Please try again.";
   }
};

