// Logic to extract context either from prompts or files
const getContextFromRequest = (req: RequestData): string => {
  if (req.requirementsPrompt && req.requirementsPrompt.length > 20) {
     const fileSummary = req.rfpFiles.length > 0 ? ` Additionally, consider these files: ${req.rfpFiles.join(', ')}.` : '';
     return `User Requirements: ${req.requirementsPrompt}.${fileSummary}`;
  }

  // Mock extraction logic for demo purposes (in real app, this would be actual file content)
  const files = req.rfpFiles;
  const combinedText = files.join(' ');
  if (combinedText.includes("AA Motors") || combinedText.includes("HANA")) return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer (B2C). Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta.";
  if (combinedText.includes("Vehicle") || combinedText.includes("Adobe")) return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM.";
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB (Oracle). Target: Cloud Data Warehouse (Snowflake). Pattern: Batch ETL. Security: End-to-end encryption required.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache }) => {
  const [activeSubTab, setActiveSubTab] = useState<'initiation' | 'design' | 'requirements' | 'scoping' | 'attachments' | 'estimator' | 'dataQuality'>('design');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);

  // Design States
  const [designMode, setDesignMode] = useState<'hld' | 'table' | 'process'>('hld');
  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [tableDesign, setTableDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [processDesign, setProcessDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [tablePrompt, setTablePrompt] = useState("");
  const [processPrompt, setProcessPrompt] = useState("");

  const [questions, setQuestions] = useState<Question[]>([]);
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [initiationItems, setInitiationItems] = useState<InitiationItem[]>([]);
  const [dqRules, setDqRules] = useState<DataQualityRule[]>([]);

  // Estimator State
  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [modules, setModules] = useState<ModuleConfig[]>(ALL_MODULES_CONFIG);
  const [isExcelReady, setIsExcelReady] = useState(false);
  const [isAutoStaffing, setIsAutoStaffing] = useState(true);
  const [resourcePlan, setResourcePlan] = useState<ResourceRow[]>([]);
  const [showConfig, setShowConfig] = useState(false);

  const [localFiles, setLocalFiles] = useState<string[]>([]);
  const [refinementPrompt, setRefinementPrompt] = useState("");

  // DQ Form State
  const [showRuleForm, setShowRuleForm] = useState(false);
  const [newRule, setNewRule] = useState<Partial<DataQualityRule>>({
    name: '',
    description: '',
    type: 'Validity',
    criticality: 'Medium'
  });

  // Load Excel Lib
  useEffect(() => {
    if (!window.XLSX) {
      const script = document.createElement('script');
      script.src = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
      script.async = true;
      script.onload = () => setIsExcelReady(true);
      document.body.appendChild(script);
    } else {
      setIsExcelReady(true);
    }
  }, []);

  useEffect(() => {
    if (request) {
      setLocalFiles(request.rfpFiles || []); 

      // Auto-switch to estimator if mode is 'estimator' and we are idle (new request)
      if (request.mode === 'estimator' && status === 'idle') {
         setActiveSubTab('estimator');
         // Auto-trigger generation for estimator if prompt exists
         if (request.requirementsPrompt || request.rfpFiles.length > 0) {
            handleGenerate(null, 'estimator');
         }
      }

      if (designCache[request.id]) {
        const cached = designCache[request.id];
        setCurrentDesign(cached.design);
        if (cached.tableDesign) setTableDesign(cached.tableDesign);
        if (cached.processDesign) setProcessDesign(cached.processDesign);
        setQuestions(cached.questions);
        setRequirements(cached.requirements);
        setInitiationItems(cached.initiation || []);
        if (cached.dataQualityRules) setDqRules(cached.dataQualityRules);
        if (cached.estimationInputs) setEstimationInputs(cached.estimationInputs);
        setStatus(cached.status);
      } else {
        setStatus('idle');
        setCurrentDesign({ nodes: [], edges: [] });
        setTableDesign({ nodes: [], edges: [] });
        setProcessDesign({ nodes: [], edges: [] });
        setQuestions([]);
        setRequirements([]);
        setInitiationItems([]);
        setDqRules([]);

        // Initialize Inputs
        const initialInputs: Record<string, number> = {};
        ALL_MODULES_CONFIG.forEach(mod => {
          mod.drivers.forEach(driver => {
            initialInputs[driver.id] = driver.defaultValue;
          });
        });
        setEstimationInputs(initialInputs);
      }
    }
  }, [request, designCache]);

  // --- Estimator Calculations ---
  const baseCalculations = useMemo(() => {
    let totalTechHours = 0;
    const moduleBreakdown: Record<string, number> = {};

    modules.forEach(m => moduleBreakdown[m.id] = 0);

    modules.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const qty = estimationInputs[driver.id] || 0;
        modHours += qty * driver.multiplier;
      });
      moduleBreakdown[mod.id] = modHours;
      totalTechHours += modHours;
    });

    const testingBuffer = totalTechHours * 0.30; 
    const grandTotalTechHours = totalTechHours + testingBuffer;
    const teamVelocityPerWeek = 3 * 40; 
    const inceptionWeeks = Math.max(2, grandTotalTechHours * 0.10 / teamVelocityPerWeek);

    const implementationWeeks: Record<string, number> = {};
    modules.forEach(mod => {
      implementationWeeks[mod.id] = moduleBreakdown[mod.id] / teamVelocityPerWeek;
    });

    const uatWeeks = Math.max(2, testingBuffer / teamVelocityPerWeek);
    const totalProjectWeeks = inceptionWeeks + Math.max(...Object.values(implementationWeeks), 0) + uatWeeks;

    return { moduleBreakdown, totalTechHours, testingBuffer, grandTotalTechHours, inceptionWeeks, implementationWeeks, uatWeeks, totalProjectWeeks };
  }, [estimationInputs, modules]);

  // --- Resource Plan Logic ---
  useEffect(() => {
    if (isAutoStaffing) {
      const duration = Math.max(4, baseCalculations.totalProjectWeeks);
      const devCount = Math.ceil(baseCalculations.totalTechHours / (duration * 40 * 0.85)) || 1;
      const qaCount = Math.ceil(baseCalculations.testingBuffer / (duration * 40 * 0.85)) || 1;

      const newPlan: ResourceRow[] = [
        { id: 'pm', role: 'Project Manager', count: 1, utilization: 50, rate: 800, durationWeeks: duration },
        { id: 'arch', role: 'Solution Architect', count: 1, utilization: 25, rate: 950, durationWeeks: duration },
        { id: 'lead', role: 'Technical Lead', count: 1, utilization: 100, rate: 750, durationWeeks: duration },
        { id: 'dev', role: 'Developer/Consultant', count: devCount, utilization: 100, rate: 500, durationWeeks: duration },
        { id: 'qa', role: 'QA Specialist', count: qaCount, utilization: 100, rate: 450, durationWeeks: duration },
      ];
      setResourcePlan(newPlan);
    }
  }, [baseCalculations, isAutoStaffing]);

  const financialCalculations = useMemo(() => {
    let totalCost = 0;
    let totalDays = 0;
    resourcePlan.forEach(row => {
      const rowDays = (row.durationWeeks * 5) * row.count * (row.utilization / 100);
      const rowCost = rowDays * row.rate;
      totalCost += rowCost;
      totalDays += rowDays;
    });
    return { totalCost, totalDays };
  }, [resourcePlan]);

  // Chart Data
  const chartData = useMemo(() => {
    return modules.map(mod => ({
      name: mod.title,
      value: baseCalculations.moduleBreakdown[mod.id],
      color: mod.color
    })).filter(item => item.value > 0);
  }, [modules, baseCalculations]);

  const resourceChartData = useMemo(() => {
    return resourcePlan.map(r => ({
      name: r.role,
      cost: (r.durationWeeks * 5) * r.count * (r.utilization / 100) * r.rate
    })).filter(i => i.cost > 0);
  }, [resourcePlan]);


  // --- Generation Handler ---
  const handleGenerate = async (promptOverride: string | null = null, forcedMode: 'design' | 'estimator' = 'design') => {
    if (!request) return;
    setStatus('thinking');
    setThoughts([]);

    const audience = request.targetAudience || ['Developer']; 
    const context = getContextFromRequest(request) + (promptOverride ? ` Refinement: ${promptOverride}` : "");

    // Specific thoughts based on mode
    const baseThoughts = forcedMode === 'estimator' 
      ? [
          "Analyzing requirements for complexity...",
          "Inferring component counts from text...",
          "Calculating effort multipliers..."
        ]
      : [
          `Reading requirements...`,
          `Synthesizing technical architecture...`,
          "Analyzing MDM & Governance patterns...",
          "Drafting HLD Diagram..."
        ];

    if (activeSubTab === 'dataQuality') {
        baseThoughts.push("Identifying critical data elements...");
    }

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 600)); 
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    try {
      // Parallel execution for design mode, focused execution for estimator
      let design = currentDesign;
      let generatedQuestions = questions;
      let generatedRequirements = requirements;
      let generatedInitiation = initiationItems;
      let generatedEstimation = estimationInputs;
      let generatedRules = dqRules;

      if (forcedMode === 'design') {
          const results = await Promise.all([
            generateArchitectureDesign(context, request.type),
            generateIntelligentQuestionnaire(context, request.type, audience),
            generateProjectRequirements(context, request.type, audience),
            generateInitiationChecklist(context, request.type, audience),
            generateEstimation(context, request.type),
            generateDataQualityRules(context, request.type)
          ]);
          design = results[0];
          generatedQuestions = results[1];
          generatedRequirements = results[2];
          generatedInitiation = results[3];
          generatedEstimation = results[4];
          generatedRules = results[5];
      } else {
          // Estimator Mode: Just get estimation + basic requirements for context
          const results = await Promise.all([
             generateEstimation(context, request.type),
             generateProjectRequirements(context, request.type, audience) // Useful for assumptions
          ]);
          generatedEstimation = results[0];
          generatedRequirements = results[1];
      }

      setCurrentDesign(design);
      setQuestions(generatedQuestions);
      setRequirements(generatedRequirements);
      setInitiationItems(generatedInitiation);
      setDqRules(generatedRules);

      // Update Inputs safely
      setEstimationInputs(prev => ({...prev, ...generatedEstimation}));

      setStatus('review');

      // Trigger Continuous Learning in Background
      if (forcedMode === 'design') {
        analyzeAndLearn(context, promptOverride, design, audience);
      }

    } catch (e) {
      console.error("Generation failed", e);
      setStatus('idle');
    }
  };

  const handleExtraGeneration = async (type: 'table' | 'process') => {
     if (!request) return;
     setStatus('thinking');
     const context = getContextFromRequest(request);
     const prompt = type === 'table' ? tablePrompt : processPrompt;
     const audience = request.targetAudience || ['Developer'];

     try {
        if (type === 'table') {
           const design = await generateTableArchitecture(context, prompt || "Infer schema from requirements");
           setTableDesign(design);
           analyzeAndLearn(context, prompt, design, audience);
        } else {
           const design = await generateProcessArchitecture(context, prompt || "Infer detailed flow from requirements");
           setProcessDesign(design);
           analyzeAndLearn(context, prompt, design, audience);
        }
        setStatus('review');
     } catch(e) {
        console.error(e);
        setStatus('idle');
     }
  };

  const handleUpdateDesignFromRefinement = (newDesign: DesignData) => {
     if (designMode === 'hld') setCurrentDesign(newDesign);
     if (designMode === 'table') setTableDesign(newDesign);
     if (designMode === 'process') setProcessDesign(newDesign);
  };

  const saveToCache = () => {
    if (request) {
      const cacheData: CachedRequestData = {
        design: currentDesign,
        tableDesign: tableDesign,
        processDesign: processDesign,
        questions: questions,
        requirements: requirements,
        initiation: initiationItems,
        dataQualityRules: dqRules,
        estimationInputs: estimationInputs,
        status: 'accepted'
      };
      onUpdateDesignCache(request.id, cacheData);
    }
  };

  const handleAcceptDesign = () => {
    saveToCache();
    setStatus('accepted');
    const context = request ? getContextFromRequest(request) : "";
    if (request && request.mode !== 'estimator') {
         learnFromProject(context, currentDesign, request.targetAudience);
    }
  };

  // Auto-save secondary designs when generated
  useEffect(() => {
      if (tableDesign.nodes.length > 0 || processDesign.nodes.length > 0) {
          saveToCache();
      }
  }, [tableDesign, processDesign]);

  const handleAddFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFileName = e.target.files[0].name;
      if (!localFiles.includes(newFileName)) {
        setLocalFiles(prev => [...prev, newFileName]);
      }
    }
  };

  const handleSaveRule = () => {
     if (newRule.name && newRule.description) {
         setDqRules(prev => [...prev, {
             id: Math.random().toString(36).substr(2, 9),
             name: newRule.name!,
             description: newRule.description!,
             type: newRule.type as any,
             criticality: newRule.criticality as any
         }]);
         setNewRule({ name: '', description: '', type: 'Validity', criticality: 'Medium' });
         setShowRuleForm(false);
     }
  };

  const handleDeleteRule = (id: string) => {
      setDqRules(prev => prev.filter(r => r.id !== id));
  };

  // --- XLSX Export ---
  const exportXLSX = () => {
    if (!window.XLSX) { alert("Library loading..."); return; }
    const XLSX = window.XLSX;
    const workbook = XLSX.utils.book_new();

    const summaryData = [
      ["ESTIMATION SUMMARY"], ["Total Cost", financialCalculations.totalCost], ["Total Hours", baseCalculations.grandTotalTechHours]
    ];
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(summaryData), "Summary");

