               <div className="flex bg-slate-100 p-1 rounded-lg shadow-inner">
                 <button onClick={() => setDesignMode('hld')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${designMode === 'hld' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
                    <Network size={14} /> High Level Design
