                 <button onClick={() => setDesignMode('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${designMode === 'table' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
                    <Table size={14} /> Table Architecture
                 </button>
                 <button onClick={() => setDesignMode('process')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${designMode === 'process' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
                    <ArrowRightCircle size={14} /> Process Flow
                 </button>
               </div>
             </div>

            {/* Content Logic based on Design Mode and Existence of Design */}
            {(!showActiveDesignCanvas) ? (
              <div className="flex-1 flex flex-col items-center justify-center p-8 z-10 animate-fade-in">
                <div className="max-w-2xl w-full bg-white/90 backdrop-blur-xl rounded-2xl shadow-xl border border-white/60 p-8 text-center">
                   <div className="mb-6 inline-flex p-4 rounded-full bg-slate-50 border border-slate-100 shadow-sm">
                      {designMode === 'hld' && <PenTool size={32} className="text-indigo-600" />}
                      {designMode === 'table' && <Table size={32} className="text-blue-600" />}
                      {designMode === 'process' && <Workflow size={32} className="text-orange-600" />}
                   </div>

                   <h3 className="text-2xl font-bold text-slate-800 mb-2">
                      {designMode === 'hld' ? 'Generate Solution Blueprint' : 
                       designMode === 'table' ? 'Generate Table Schema (ERD)' : 
                       'Generate Data Flow Process'}
                   </h3>

                   <p className="text-slate-600 mb-8 max-w-lg mx-auto text-sm">
                     {designMode === 'hld' 
                        ? "Create a comprehensive High-Level Design (HLD) diagram based on your project requirements."
                        : designMode === 'table' 
                        ? "Generate entity-relationship diagrams from DDL queries or natural language descriptions."
                        : "Visualize detailed data transformation logic and process steps."}
                   </p>

                   {/* Input for Table/Process */}
                   {designMode !== 'hld' && (
                     <div className="mb-6 text-left">
                       <label className="block text-xs font-bold text-slate-700 uppercase mb-2">
                         {designMode === 'table' ? 'Enter DDL or Describe Entities' : 'Describe Process Logic'}
                       </label>
                       <textarea 
                          className="w-full p-3 border border-slate-300 rounded-lg text-sm bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all h-32"
                          placeholder={designMode === 'table' ? "e.g. CREATE TABLE Customer... or 'I need tables for an E-commerce system with Orders and Items'" : "e.g. 'Ingest from API, validate schema, filter nulls, enrich with CRM data, load to Snowflake'"}
                          value={designMode === 'table' ? tablePrompt : processPrompt}
                          onChange={(e) => designMode === 'table' ? setTablePrompt(e.target.value) : setProcessPrompt(e.target.value)}
                       />
                     </div>
                   )}

                   <button 
                     onClick={() => designMode === 'hld' ? handleGenerate() : handleExtraGeneration(designMode)} 
                     disabled={status === 'thinking'}
                     className={`w-full px-6 py-3 rounded-xl font-bold text-white shadow-lg transition-all transform hover:-translate-y-0.5 flex items-center justify-center gap-2
                       ${status === 'thinking' ? 'bg-slate-400 cursor-not-allowed' : designMode === 'hld' ? 'bg-slate-900 hover:bg-slate-800' : 'bg-indigo-600 hover:bg-indigo-700'}`}
                   >
                     {status === 'thinking' ? <Loader size={18} className="animate-spin" /> : <Sparkles size={18} className="text-yellow-300" />}
                     Generate Diagram
                   </button>
                </div>
              </div>
            ) : status === 'review' || status === 'accepted' ? (
               <div className="flex flex-col h-full animate-fade-in relative z-10">
                  <div className="bg-white/90 backdrop-blur-md border-b border-slate-200 p-4 flex justify-between items-center shadow-sm">
                     <div className="flex items-center gap-4">
                        <div className={`p-2 rounded-xl shadow-sm border ${designMode === 'hld' ? 'bg-indigo-100 text-indigo-600 border-indigo-200' : designMode === 'table' ? 'bg-blue-100 text-blue-600 border-blue-200' : 'bg-orange-100 text-orange-600 border-orange-200'}`}>
                          {designMode === 'hld' ? <Lightbulb size={20} /> : designMode === 'table' ? <Table size={20} /> : <Workflow size={20} />}
                        </div>
                        <div>
                          <h4 className="font-bold text-slate-800 text-sm">
                             {designMode === 'hld' ? 'Architecture Review' : designMode === 'table' ? 'Schema Review' : 'Process Logic Review'}
                          </h4>
                          <p className="text-[10px] font-medium text-slate-500 flex items-center gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span> AI Generated
                          </p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button 
                          onClick={() => designMode === 'hld' ? handleGenerate() : handleExtraGeneration(designMode)} 
                          className="flex items-center gap-2 px-4 py-2 bg-white text-slate-600 border border-slate-200 rounded-lg text-xs font-bold hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm"
                        >
                          <RefreshCw size={14} /> Regenerate
                        </button>
                        <button 
                          onClick={handleAcceptDesign} 
                          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-700 shadow-md shadow-indigo-200 transition-all"
                        >
                          <ThumbsUp size={14} /> Accept
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative bg-white/50 backdrop-blur-sm">
                     <ArchitectureCanvas 
                       aiNodes={activeDesignToRender.nodes} 
                       aiEdges={activeDesignToRender.edges} 
                       isThinking={false} 
                       thoughts={thoughts} 
                       context={getContextFromRequest(request) + (designMode === 'table' ? tablePrompt : designMode === 'process' ? processPrompt : "")} 
                       audience={request.targetAudience} 
                       onApplyRefinement={handleUpdateDesignFromRefinement} 
                     />

                     <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-2xl">
                        <div className="bg-white/90 backdrop-blur-xl shadow-2xl rounded-2xl border border-white/50 p-2 flex items-center gap-2 mx-4">
                            <div className="p-3 bg-slate-100 rounded-xl text-slate-500">
                              <MessageSquare size={20} />
                            </div>
                            <input 
                              type="text" 
                              placeholder={`Refine ${designMode} diagram (e.g. 'Add column X', 'Connect node Y')...`}
                              className="flex-1 bg-transparent outline-none text-sm py-2 px-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                              value={refinementPrompt} 
                              onChange={(e) => setRefinementPrompt(e.target.value)} 
                              onKeyDown={(e) => e.key === 'Enter' && (designMode === 'hld' ? handleGenerate(refinementPrompt) : handleExtraGeneration(designMode))} 
                            />
                            <button 
                              onClick={() => designMode === 'hld' ? handleGenerate(refinementPrompt) : handleExtraGeneration(designMode)} 
                              className="bg-indigo-600 hover:bg-indigo-700 text-white p-3 rounded-xl transition-all shadow-md"
                            >
                              <Send size={18} />
                            </button>
                        </div>
                     </div>
                  </div>
               </div>
            ) : null}
          </div>
        )}
      </div>
    </div>
  );
};

