                        >
                          <ThumbsUp size={14} /> Accept
                        </button>
                     </div>
                  </div>
                  <div className="flex-1 relative bg-white/50 backdrop-blur-sm">
                     <ArchitectureCanvas 
                       aiNodes={activeDesignToRender.nodes} 
                       aiEdges={activeDesignToRender.edges} 
                       isThinking={false} 
                       thoughts={thoughts} 
                       context={getContextFromRequest(request) + (designMode === 'table' ? tablePrompt : designMode === 'process' ? processPrompt : "")} 
                       audience={request.targetAudience} 
                       onApplyRefinement={handleUpdateDesignFromRefinement} 
                     />

                     <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-2xl">
                        <div className="bg-white/90 backdrop-blur-xl shadow-2xl rounded-2xl border border-white/50 p-2 flex items-center gap-2 mx-4">
                            <div className="p-3 bg-slate-100 rounded-xl text-slate-500">
                              <MessageSquare size={20} />
                            </div>
                            <input 
                              type="text" 
                              placeholder={`Refine ${designMode} diagram (e.g. 'Add column X', 'Connect node Y')...`}
                              className="flex-1 bg-transparent outline-none text-sm py-2 px-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                              value={refinementPrompt} 
                              onChange={(e) => setRefinementPrompt(e.target.value)} 
                              onKeyDown={(e) => e.key === 'Enter' && (designMode === 'hld' ? handleGenerate(refinementPrompt) : handleExtraGeneration(designMode))} 
                            />
                            <button 
                              onClick={() => designMode === 'hld' ? handleGenerate(refinementPrompt) : handleExtraGeneration(designMode)} 
                              className="bg-indigo-600 hover:bg-indigo-700 text-white p-3 rounded-xl transition-all shadow-md"
                            >
                              <Send size={18} />
                            </button>
                        </div>
                     </div>
                  </div>
               </div>
            ) : null}
          </div>
        )}
      </div>
    </div>
  );
};

