import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import DashboardView from './components/Dashboard';
import CreateForm from './components/CreateForm';
import SolutionDesignView from './components/SolutionDesign';
import StandaloneEstimator from './components/StandaloneEstimator';
import StandaloneArchitecture from './components/StandaloneArchitecture';
import StandaloneDataFlow from './components/StandaloneDataFlow';
import LoginPage from './components/LoginPage';
import { RequestData, DesignCache } from './types';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Tabs: 'dashboard' | 'create' | 'design' | 'adhoc-estimator' | 'adhoc-architecture' | 'adhoc-dataflow'
  const [activeTab, setActiveTab] = useState('dashboard');

  const [selectedRequest, setSelectedRequest] = useState<RequestData | null>(null);
