const StandaloneEstimator: React.FC = () => {
  const [context, setContext] = useState('');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inputs' | 'resources'>('dashboard');
  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [isGenerating, setIsGenerating] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showConfig, setShowConfig] = useState(false);

  // Initialize inputs with defaults
  useEffect(() => {
    const defaults: EstimationInputs = {};
    ALL_MODULES_CONFIG.forEach(m => m.drivers.forEach(d => defaults[d.id] = d.defaultValue));
    setEstimationInputs(defaults);
    setHistoryItems(getHistory('Estimator'));
  }, []);

  // --- Hybrid Calculation Logic (Calculated locally in React, not by AI) ---
  const calculations = useMemo(() => {
    let totalTechHours = 0;
    const toolDistribution: any[] = [];

    ALL_MODULES_CONFIG.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const val = estimationInputs[driver.id] || 0;
        modHours += val * driver.multiplier;
      });
      totalTechHours += modHours;
      if (modHours > 0) {
        toolDistribution.push({ name: mod.title, value: modHours, color: mod.color });
      }
    });

    const testingBuffer = totalTechHours * 0.30;
    const grandTotalHours = totalTechHours + testingBuffer;
    const durationWeeks = Math.max(4, Math.ceil(grandTotalHours / (3 * 40))); // Approx 3 FTE velocity
    const totalCost = grandTotalHours * 85; // Avg blended rate $85/hr

    // Resource Logic
    const devCount = Math.ceil(totalTechHours / (durationWeeks * 40 * 0.85)) || 1;
    const resources = [
        { role: 'Project Manager', count: 1, utilization: 50, rate: 800 },
        { role: 'Solution Architect', count: 1, utilization: 25, rate: 950 },
        { role: 'Tech Lead', count: 1, utilization: 100, rate: 750 },
        { role: 'Developer', count: devCount, utilization: 100, rate: 500 },
        { role: 'QA', count: Math.ceil(devCount/3), utilization: 100, rate: 450 },
    ];

    return { totalTechHours, grandTotalHours, durationWeeks, totalCost, toolDistribution, resources };
  }, [estimationInputs]);

  const handleGenerate = async () => {
    if (!context.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      // AI ONLY generates the input drivers (counts), it does NOT generate the full math/text.
      // This is the hybrid approach requested.
      const result = await generateDynamicEstimation(context);
      if (result) {
          setEstimationInputs(prev => ({...prev, ...result}));
          saveHistory('Estimator', context.substring(0, 40) + '...', result);
          setActiveTab('dashboard'); // Auto switch to results
      } else {
          setError("AI could not infer specific project drivers. Please verify requirements.");
      }
    } catch (e) {
      console.error(e);
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setContext(prev => prev + `\n[Context from attached file: ${e.target.files![0].name}]\n(Note to AI: Use the implied complexity from this file type to estimate effort.)`);
    }
  };

  const loadHistoryItem = (item: any) => {
    setContext(item.summary);
    setEstimationInputs(item.data);
    setShowHistory(false);
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);

  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden">

      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><Calculator size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800">Smart Project Estimator</h2>
               <p className="text-xs text-slate-500">Hybrid AI + Algorithmic Model (gemini-3-pro-preview)</p>
            </div>
         </div>
         <div className="flex gap-2">
            <button onClick={() => setShowHelp(true)} className="text-slate-500 hover:text-indigo-600"><HelpCircle size={20} /></button>
            <button onClick={() => setShowHistory(!showHistory)} className="flex items-center gap-2 text-slate-500 hover:text-indigo-600 text-sm font-medium"><History size={18} /> History</button>
         </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <AlertTriangle size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-16 right-4 z-50 w-72 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3">Recent Estimates</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
