                                            <th className="px-6 py-3 font-semibold">Role</th>
                                            <th className="px-6 py-3 font-semibold">Rate / Day</th>
                                            <th className="px-6 py-3 font-semibold text-center">Headcount</th>
                                            <th className="px-6 py-3 font-semibold text-center">Utilization</th>
                                            <th className="px-6 py-3 font-semibold text-right">Est. Cost</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-50">
                                        {calculations.finalResources.map((r, i) => (
                                            <tr key={i} className="hover:bg-slate-50 transition-colors">
                                                <td className="px-6 py-4 font-medium text-slate-700">{r.role}</td>
                                                <td className="px-6 py-4 text-slate-500">${r.rate}</td>
                                                <td className="px-6 py-4 text-center">
                                                    <div className="inline-flex items-center border rounded-lg bg-white">
                                                        <button 
                                                            className="px-2 py-1 hover:bg-slate-100 text-slate-500"
                                                            onClick={() => setCustomResourceCounts(prev => ({...prev, [r.id]: Math.max(0, (prev[r.id] || 1) - 1)}))}
                                                        >-</button>
                                                        <input 
                                                            type="number" 
                                                            className="w-12 text-center border-x p-1 outline-none text-slate-800 font-bold"
                                                            value={r.count}
                                                            onChange={(e) => setCustomResourceCounts(prev => ({...prev, [r.id]: parseInt(e.target.value) || 0}))}
                                                        />
                                                        <button 
                                                            className="px-2 py-1 hover:bg-slate-100 text-slate-500"
                                                            onClick={() => setCustomResourceCounts(prev => ({...prev, [r.id]: (prev[r.id] || 1) + 1}))}
                                                        >+</button>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-center text-slate-500">{(r.utilization * 100)}%</td>
                                                <td className="px-6 py-4 text-right font-bold text-slate-800">{formatCurrency(r.totalCost)}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                    <tfoot className="bg-slate-50 border-t border-slate-200">
                                        <tr>
                                            <td colSpan={4} className="px-6 py-4 text-right font-bold text-slate-600">Total Estimated Cost:</td>
                                            <td className="px-6 py-4 text-right font-bold text-emerald-600 text-lg">{formatCurrency(calculations.totalProjectCost)}</td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        </div>
                    )}

                    {/* TAB 3: TIMELINE */}
                    {activeTab === 'timeline' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <div>
                                    <h3 className="font-bold text-slate-800">Project Timeline</h3>
                                    <p className="text-xs text-slate-500">Total Duration: <span className="font-bold text-indigo-600">{calculations.calculatedDurationWeeks} Weeks</span> (Auto-scaled based on {calculations.grandTotalHours.toFixed(0)} hrs effort)</p>
                                </div>
                                <button className="text-sm font-bold text-white bg-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center gap-2"><Download size={16}/> Export Plan</button>
                            </div>
                            <div className="p-8">
                                <div className="space-y-6">
                                    {calculations.timelineData.map((phase, i) => (
                                        <div key={i} className="relative">
                                            <div className="flex justify-between items-end mb-2">
                                                <span className="text-sm font-bold text-slate-700">{phase.name}</span>
                                                <span className="text-xs text-slate-500">{phase.duration} Wks</span>
                                            </div>
                                            <div className="h-4 bg-slate-100 rounded-full w-full overflow-hidden relative">
                                                {/* Grid lines for weeks - purely visual */}
                                                <div className="absolute inset-0 flex">
                                                    {Array.from({length: calculations.calculatedDurationWeeks}).map((_, idx) => (
                                                        <div key={idx} className="flex-1 border-r border-white/50"></div>
                                                    ))}
                                                </div>
                                                <div 
                                                    className={`h-full rounded-full ${phase.color} shadow-sm transition-all duration-700`}
                                                    style={{
                                                        width: `${(phase.duration / calculations.calculatedDurationWeeks) * 100}%`,
                                                        marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`
                                                    }}
                                                ></div>
                                            </div>
                                            <div className="mt-1 flex justify-between text-[10px] text-slate-400">
                                                <span style={{marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + 1}</span>
                                                <span style={{marginRight: `${100 - ((phase.startOffset + phase.duration) / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + phase.duration}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="mt-8 pt-6 border-t border-slate-100 text-center">
                                    <p className="text-xs text-slate-400 italic">Timeline is derived from total effort hours divided by the effective team velocity. Adjust "Resource Plan" to compress or expand timelines.</p>
                                </div>
                            </div>
                        </div>
                    )}

                </div>
            )}
         </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-emerald-500" /> Estimator Guide</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>1. Input & Learn:</strong> Upload an RFP or a previous estimation Excel file. The AI learns the complexity patterns.</p>
                    <p><strong>2. Configure Drivers:</strong> The AI populates the driver counts (e.g., 50 tables). You can tweak these numbers, and the cost/effort updates instantly.</p>
                    <p><strong>3. Auto-Scale Resources:</strong> Go to the Resource tab. Increasing the headcount will automatically reduce the project timeline in the Timeline tab.</p>
                 </div>
              </div>
           </div>
      )}
    </div>
  );
};

