  // Resource State (Editable)
  const [customResourceCounts, setCustomResourceCounts] = useState<Record<string, number>>({
    'pm': 1, 'arch': 1, 'lead': 1, 'dev': 2, 'qa': 1
  });

  // Initialize
  useEffect(() => {
    const defaults: EstimationInputs = {};
    ALL_MODULES_CONFIG.forEach(m => m.drivers.forEach(d => defaults[d.id] = d.defaultValue));
    setEstimationInputs(defaults);
    setHistoryItems(getHistory('Estimator'));
  }, []);

  // --- RECALCULATION ENGINE ---
  const calculations = useMemo(() => {
    let totalTechHours = 0;
    const moduleBreakdown: Record<string, number> = {};

    // 1. Calculate Tech Hours from Drivers
    ALL_MODULES_CONFIG.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const val = estimationInputs[driver.id] || 0;
        modHours += val * driver.multiplier;
      });
      moduleBreakdown[mod.id] = modHours;
      totalTechHours += modHours;
    });

    const testingBuffer = totalTechHours * 0.30;
    const grandTotalHours = totalTechHours + testingBuffer;

    // 2. Resource & Duration Logic (Auto-Scalable)
    // Formula: Duration = TotalHours / (Headcount * Velocity)
    // Velocity assumed: 35 effective hours/week per person

    const resourceList = [
        { id: 'pm', role: 'Project Manager', rate: 800, utilization: 0.5 },
        { id: 'arch', role: 'Solution Architect', rate: 950, utilization: 0.25 },
        { id: 'lead', role: 'Tech Lead', rate: 750, utilization: 1.0 },
        { id: 'dev', role: 'Developer', rate: 500, utilization: 1.0 },
        { id: 'qa', role: 'QA Engineer', rate: 450, utilization: 1.0 },
    ];

    // Calculate effective team velocity based on current resource counts
    const effectiveDevCount = customResourceCounts['dev'] || 1;
    const weeklyVelocity = effectiveDevCount * 35; // 35 hours per dev per week

    // Derived Duration
    const calculatedDurationWeeks = Math.max(4, Math.ceil(grandTotalHours / weeklyVelocity));

    const finalResources = resourceList.map(r => ({
        ...r,
        count: customResourceCounts[r.id] || 1,
        totalCost: (calculatedDurationWeeks * 5) * (customResourceCounts[r.id] || 1) * r.rate * r.utilization
    }));

    const totalProjectCost = finalResources.reduce((acc, r) => acc + r.totalCost, 0);

    // 3. Timeline Phases Generation
    const phases = [
        { name: "Inception & Analysis", pct: 0.10, color: "bg-blue-500" },
        { name: "Design & Architecture", pct: 0.15, color: "bg-indigo-500" },
        { name: "Build & Implementation", pct: 0.50, color: "bg-emerald-500" },
        { name: "Testing (SIT/UAT)", pct: 0.20, color: "bg-orange-500" },
        { name: "Deployment & Go-Live", pct: 0.05, color: "bg-slate-700" }
    ];

    let currentStart = 0;
    const timelineData = phases.map(p => {
        const weeks = Math.max(1, Math.round(calculatedDurationWeeks * p.pct));
        const start = currentStart;
        currentStart += weeks;
        return { ...p, duration: weeks, startOffset: start };
    });

    return { 
        grandTotalHours, 
        calculatedDurationWeeks, 
        totalProjectCost, 
        moduleBreakdown, 
        finalResources,
        timelineData
    };
  }, [estimationInputs, customResourceCounts]);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    if (!context.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const [estimationResult, assumptionResult] = await Promise.all([
         generateDynamicEstimation(context),
         generateAssumptions(context)
      ]);

      if (estimationResult) {
          setEstimationInputs(prev => ({...prev, ...estimationResult}));
          // Auto-scale dev count based on complexity if needed (simple heuristic)
          const totalObj = Object.values(estimationResult).reduce((a,b) => a+b, 0);
          if (totalObj > 100) setCustomResourceCounts(prev => ({...prev, dev: 4, qa: 2}));
          else if (totalObj > 50) setCustomResourceCounts(prev => ({...prev, dev: 3, qa: 1}));

          setAiRationale(`Based on the requirements, I've identified ${totalObj} key estimation drivers. The complexity suggests a ${totalObj > 50 ? 'Medium-to-High' : 'Standard'} effort. I have pre-populated the driver table below which you can fine-tune.`);

          if (assumptionResult) setAssumptions(assumptionResult);

          const fullDataToSave = {
              data: estimationResult,
              assumptions: assumptionResult
          };

          saveHistory('Estimator', context.substring(0, 40) + '...', fullDataToSave, uploadedFiles);
          setHistoryItems(getHistory('Estimator'));
          setShowResults(true); // Reveal tabs
          setActiveTab('drivers');
      } else {
          setError("AI could not infer specific project drivers. Please verify requirements.");
      }
    } catch (e) {
      console.error(e);
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);

      // If it's an Excel file, try to parse it (Client-side simulation of learning)
      if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
         if (window.XLSX) {
             const reader = new FileReader();
             reader.onload = (evt) => {
                 const bstr = evt.target?.result;
                 const wb = window.XLSX.read(bstr, {type:'binary'});
                 const wsname = wb.SheetNames[0];
                 const ws = wb.Sheets[wsname];
                 const data = window.XLSX.utils.sheet_to_json(ws, {header:1});
                 // Flatten data to string for context
                 const csvLike = data.map((row: any[]) => row.join(' ')).join('\n').substring(0, 5000); // Limit context
                 setContext(prev => prev + `\n[Learned from ${file.name}]:\n${csvLike}\n(Use this historical data to calibrate complexity)`);
             };
             reader.readAsBinaryString(file);
         } else {
             setContext(prev => prev + `\n[Attached Estimation File: ${file.name}]`);
         }
      } else {
         setContext(prev => prev + `\n[Attached RFP: ${file.name}]`);
      }
    }
  };

  const loadHistoryItem = (item: any) => {
    setContext(item.summary);
    setEstimationInputs(item.data.data || item.data); // Backwards compat
    if (item.data.assumptions) setAssumptions(item.data.assumptions);
    setUploadedFiles(item.files || []);
    setShowResults(true);
    setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);

  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">

      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><Calculator size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800">Estimator</h2>
               <p className="text-xs text-slate-500">AI-Powered Driver Analysis & Resource Modeling</p>
            </div>
         </div>
         <div className="flex gap-2">
            <button onClick={() => setShowHelp(true)} className="text-slate-500 hover:text-indigo-600"><HelpCircle size={20} /></button>
            <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-100'}`}><History size={18} /> History</button>
         </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <AlertTriangle size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-16 right-4 z-50 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3">Recent Estimates</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
               {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> : 
               historyItems.map((h, i) => (
                  <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                     <div className="flex justify-between items-start mb-1">
                        <span className="font-bold text-slate-700 truncate max-w-[180px]">{h.summary}</span>
                        <span className="text-slate-400 text-[10px]">{h.date}</span>
                     </div>
                     {h.files && h.files.length > 0 && (
                        <div className="flex gap-1 mt-1">
                            {h.files.map((f: string, idx: number) => (
                                <span key={idx} className="bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded text-[9px] flex items-center gap-0.5 truncate max-w-[80px]">
                                    <FileText size={8}/> {f}
                                </span>
                            ))}
                        </div>
                     )}
                     <div 
                        className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                        onClick={(e) => handleDeleteHistory(h.id, e)}
                     >
                        <Trash2 size={14} />
                     </div>
                  </button>
               ))}
            </div>
         </div>
      )}

      <div className="flex-1 overflow-y-auto p-6 md:p-8">
         <div className="max-w-6xl mx-auto space-y-8">

            {/* 1. INPUT SECTION (Always Visible, but minimized when results show) */}
            <div className={`bg-white rounded-xl shadow-sm border border-slate-200 transition-all duration-500 ${showResults ? 'p-4' : 'p-8'}`}>
               <div className="flex justify-between items-center mb-4">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Sparkles className="text-indigo-500" size={18}/> Project Context & Learning</h3>
                  {showResults && <button onClick={() => setShowResults(false)} className="text-xs text-indigo-600 hover:underline">Edit Requirements</button>}
               </div>

               {!showResults ? (
                   <div className="space-y-4 animate-fade-in">
                        <p className="text-sm text-slate-500">
                            Describe your project or upload an RFP. You can also upload previous estimation Excel files to help the AI learn your complexity patterns.
                        </p>
                        <textarea 
                            value={context}
                            onChange={(e) => setContext(e.target.value)}
                            className="w-full h-40 p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                            placeholder="Example: Migration of 50 Oracle tables to Snowflake using Informatica. Includes Data Quality for Customer domain..."
                        />
                        <div className="flex flex-wrap gap-2 mb-4">
                            {uploadedFiles.map((f, i) => (
                                <span key={i} className="px-2 py-1 bg-slate-100 border border-slate-200 rounded text-xs text-slate-600 flex items-center gap-1">
                                    <FileSpreadsheet size={12}/> {f}
                                    <button onClick={() => setUploadedFiles(prev => prev.filter(file => file !== f))} className="hover:text-red-500 ml-1"><X size={10}/></button>
                                </span>
                            ))}
                        </div>
                        <div className="flex justify-between items-center pt-2">
                            <label className="flex items-center gap-2 cursor-pointer px-4 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-lg text-sm font-medium text-slate-600 transition-colors">
                                <UploadCloud size={18} /> Upload RFP / Excel
                                <input type="file" className="hidden" accept=".pdf,.docx,.txt,.xlsx,.xls" onChange={handleFileUpload} />
                            </label>
                            <button 
                                onClick={handleGenerate} 
                                disabled={!context.trim() || isGenerating} 
                                className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 shadow-md hover:shadow-lg"
                            >
                                {isGenerating ? <Loader size={18} className="animate-spin"/> : <Sparkles size={18}/>}
                                Generate Estimation
                            </button>
                        </div>
                   </div>
               ) : (
                   <div className="flex items-center justify-between text-sm text-slate-600">
                       <p className="truncate max-w-2xl italic">"{context.substring(0, 100)}..."</p>
                       <button onClick={handleGenerate} className="flex items-center gap-1 text-indigo-600 font-medium hover:text-indigo-800"><ArrowRight size={14}/> Re-Analyze</button>
                   </div>
               )}
            </div>

            {/* 2. RESULTS SECTION (Configurable Tabs) */}
            {showResults && (
                <div className="animate-fade-in-up">

                    {/* Navigation Tabs */}
                    <div className="flex gap-1 mb-6 bg-slate-200/50 p-1 rounded-xl inline-flex overflow-x-auto max-w-full">
                        <button onClick={() => setActiveTab('drivers')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'drivers' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>1. Drivers</button>
                        <button onClick={() => setActiveTab('resources')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'resources' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>2. Resources</button>
                        <button onClick={() => setActiveTab('timeline')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'timeline' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>3. Timeline</button>
                        <button onClick={() => setActiveTab('assumptions')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'assumptions' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>4. Assumptions & Scope</button>
                    </div>

                    {/* AI NLP Summary Block */}
                    <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl mb-6 flex items-start gap-3">
                        <BrainCircuit className="text-indigo-500 mt-1 flex-shrink-0" size={20} />
                        <div>
                            <h4 className="text-sm font-bold text-indigo-900 mb-1">AI Insight</h4>
                            <p className="text-sm text-indigo-800 leading-relaxed">{aiRationale}</p>
                        </div>
                    </div>

                    {/* TAB CONTENT */}

                    {/* TAB 1: DRIVERS */}
                    {activeTab === 'drivers' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                                <h3 className="font-bold text-slate-800 text-sm">Configurable Effort Drivers</h3>
                                <button onClick={() => setShowConfig(!showConfig)} className="text-xs text-blue-600 flex items-center gap-1 bg-white border border-blue-200 px-2 py-1 rounded hover:bg-blue-50"><Settings size={12}/> {showConfig ? 'Hide Config' : 'Edit Multipliers'}</button>
                            </div>
                            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                                {ALL_MODULES_CONFIG.map(mod => (
                                    <div key={mod.id} className="border border-slate-100 rounded-xl p-4 hover:border-slate-300 transition-colors">
                                        <h4 className="text-sm font-bold text-slate-700 uppercase mb-4 flex items-center gap-2">
                                            <mod.icon size={16} style={{color: mod.color}} /> {mod.title}
                                        </h4>
                                        <div className="space-y-3">
                                            {mod.drivers.map(driver => (
                                                <div key={driver.id} className="flex items-center justify-between group">
                                                    <div className="flex-1 pr-4">
                                                        <p className="text-sm font-medium text-slate-700">{driver.label}</p>
                                                        <p className="text-[10px] text-slate-400">{driver.description}</p>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <div className="flex flex-col items-end">
                                                            <input 
                                                                type="number" 
                                                                min="0"
                                                                className="w-16 p-1 border border-slate-300 rounded text-right font-mono text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                                                                value={estimationInputs[driver.id] || 0}
                                                                onChange={(e) => setEstimationInputs(prev => ({...prev, [driver.id]: parseInt(e.target.value) || 0}))}
                                                            />
                                                            <span className="text-[10px] text-slate-400">count</span>
                                                        </div>
                                                        {showConfig && (
                                                            <div className="flex flex-col items-end">
                                                                <input 
                                                                    type="number" 
                                                                    className="w-12 p-1 border border-slate-200 rounded text-right text-xs bg-slate-50" 
                                                                    defaultValue={driver.multiplier} 
                                                                />
                                                                <span className="text-[10px] text-slate-400">hrs/unit</span>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <div className="bg-slate-50 p-4 border-t border-slate-200 text-right">
                                <p className="text-sm font-medium text-slate-600">Total Derived Effort: <span className="font-bold text-slate-900">{calculations.grandTotalHours.toFixed(0)} Hours</span></p>
                            </div>
                        </div>
                    )}

                    {/* TAB 2: RESOURCES */}
                    {activeTab === 'resources' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-4 border-b border-slate-100 bg-slate-50">
                                <h3 className="font-bold text-slate-800 text-sm">Resource Plan & Costing</h3>
                                <p className="text-xs text-slate-500 mt-1">Adjust headcount to auto-scale project duration.</p>
                            </div>
                            <div className="p-0">
                                <table className="w-full text-left text-sm">
                                    <thead className="bg-slate-50 text-slate-500 border-b border-slate-100">
                                        <tr>
                                            <th className="px-6 py-3 font-semibold">Role</th>
                                            <th className="px-6 py-3 font-semibold">Rate / Day</th>
                                            <th className="px-6 py-3 font-semibold text-center">Headcount</th>
                                            <th className="px-6 py-3 font-semibold text-center">Utilization</th>
                                            <th className="px-6 py-3 font-semibold text-right">Est. Cost</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-50">
                                        {calculations.finalResources.map((r, i) => (
                                            <tr key={i} className="hover:bg-slate-50 transition-colors">
                                                <td className="px-6 py-4 font-medium text-slate-700">{r.role}</td>
                                                <td className="px-6 py-4 text-slate-500">${r.rate}</td>
                                                <td className="px-6 py-4 text-center">
                                                    <div className="inline-flex items-center border rounded-lg bg-white">
                                                        <button 
                                                            className="px-2 py-1 hover:bg-slate-100 text-slate-500"
                                                            onClick={() => setCustomResourceCounts(prev => ({...prev, [r.id]: Math.max(0, (prev[r.id] || 1) - 1)}))}
                                                        >-</button>
                                                        <input 
                                                            type="number" 
                                                            className="w-12 text-center border-x p-1 outline-none text-slate-800 font-bold"
                                                            value={r.count}
                                                            onChange={(e) => setCustomResourceCounts(prev => ({...prev, [r.id]: parseInt(e.target.value) || 0}))}
                                                        />
                                                        <button 
                                                            className="px-2 py-1 hover:bg-slate-100 text-slate-500"
                                                            onClick={() => setCustomResourceCounts(prev => ({...prev, [r.id]: (prev[r.id] || 1) + 1}))}
                                                        >+</button>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-center text-slate-500">{(r.utilization * 100)}%</td>
                                                <td className="px-6 py-4 text-right font-bold text-slate-800">{formatCurrency(r.totalCost)}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                    <tfoot className="bg-slate-50 border-t border-slate-200">
                                        <tr>
                                            <td colSpan={4} className="px-6 py-4 text-right font-bold text-slate-600">Total Estimated Cost:</td>
                                            <td className="px-6 py-4 text-right font-bold text-emerald-600 text-lg">{formatCurrency(calculations.totalProjectCost)}</td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        </div>
                    )}

                    {/* TAB 3: TIMELINE */}
                    {activeTab === 'timeline' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <div>
                                    <h3 className="font-bold text-slate-800">Project Timeline</h3>
                                    <p className="text-xs text-slate-500">Total Duration: <span className="font-bold text-indigo-600">{calculations.calculatedDurationWeeks} Weeks</span> (Auto-scaled based on {calculations.grandTotalHours.toFixed(0)} hrs effort)</p>
                                </div>
                                <button className="text-sm font-bold text-white bg-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center gap-2"><Download size={16}/> Export Plan</button>
                            </div>
                            <div className="p-8">
                                <div className="space-y-6">
                                    {calculations.timelineData.map((phase, i) => (
                                        <div key={i} className="relative">
                                            <div className="flex justify-between items-end mb-2">
                                                <span className="text-sm font-bold text-slate-700">{phase.name}</span>
                                                <span className="text-xs text-slate-500">{phase.duration} Wks</span>
                                            </div>
                                            <div className="h-4 bg-slate-100 rounded-full w-full overflow-hidden relative">
                                                {/* Grid lines for weeks - purely visual */}
                                                <div className="absolute inset-0 flex">
                                                    {Array.from({length: calculations.calculatedDurationWeeks}).map((_, idx) => (
                                                        <div key={idx} className="flex-1 border-r border-white/50"></div>
                                                    ))}
                                                </div>
                                                <div 
                                                    className={`h-full rounded-full ${phase.color} shadow-sm transition-all duration-700`}
                                                    style={{
                                                        width: `${(phase.duration / calculations.calculatedDurationWeeks) * 100}%`,
                                                        marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`
                                                    }}
                                                ></div>
                                            </div>
                                            <div className="mt-1 flex justify-between text-[10px] text-slate-400">
                                                <span style={{marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + 1}</span>
                                                <span style={{marginRight: `${100 - ((phase.startOffset + phase.duration) / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + phase.duration}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="mt-8 pt-6 border-t border-slate-100 text-center">
                                    <p className="text-xs text-slate-400 italic">Timeline is derived from total effort hours divided by the effective team velocity. Adjust "Resource Plan" to compress or expand timelines.</p>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* TAB 4: ASSUMPTIONS */}
                    {activeTab === 'assumptions' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <h3 className="font-bold text-slate-800 text-sm">Assumptions & Scope</h3>
                                <div className="flex gap-2">
