  date: string;
  mode?: 'design' | 'estimator';
}

export interface Node {
  id: string;
  label: string;
  description?: string; 
  type: 'source' | 'stage' | 'process' | 'target';
  x: number;
  y: number;
}

export interface Edge {
  from: string;
  to: string;
  label: string;
}

