    ]
  },
  {
    id: 'mdm',
    title: 'MDM SaaS',
    icon: Layers,
    color: '#F59E0B', 
    drivers: [
      { id: 'mdm_dom', label: 'Domains', category: 'fixed', defaultValue: 1, multiplier: 40, description: 'Domain model configuration' },
      { id: 'mdm_ing_s', label: 'Ingestion (Simple)', category: 'simple', defaultValue: 5, multiplier: 16, description: 'Direct ingestion from source' },
      { id: 'mdm_ing_c', label: 'Ingestion (Complex)', category: 'complex', defaultValue: 5, multiplier: 40, description: 'Complex cleansing & mapping during ingestion' },
      { id: 'mdm_match', label: 'Match Rules', category: 'complex', defaultValue: 4, multiplier: 24, description: 'Match rule tuning & merge logic' },
    ]
