                                            <td className="px-6 py-4 text-right font-bold text-emerald-600 text-lg">{formatCurrency(calculations.totalProjectCost)}</td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        </div>
                    )}

                    {/* TAB 3: TIMELINE */}
                    {activeTab === 'timeline' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <div>
                                    <h3 className="font-bold text-slate-800">Project Timeline</h3>
                                    <p className="text-xs text-slate-500">Total Duration: <span className="font-bold text-indigo-600">{calculations.calculatedDurationWeeks} Weeks</span> (Auto-scaled based on {calculations.grandTotalHours.toFixed(0)} hrs effort)</p>
                                </div>
                                <button className="text-sm font-bold text-white bg-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center gap-2"><Download size={16}/> Export Plan</button>
                            </div>
                            <div className="p-8">
                                <div className="space-y-6">
                                    {calculations.timelineData.map((phase, i) => (
                                        <div key={i} className="relative">
                                            <div className="flex justify-between items-end mb-2">
                                                <span className="text-sm font-bold text-slate-700">{phase.name}</span>
                                                <span className="text-xs text-slate-500">{phase.duration} Wks</span>
                                            </div>
                                            <div className="h-4 bg-slate-100 rounded-full w-full overflow-hidden relative">
                                                {/* Grid lines for weeks - purely visual */}
                                                <div className="absolute inset-0 flex">
                                                    {Array.from({length: calculations.calculatedDurationWeeks}).map((_, idx) => (
                                                        <div key={idx} className="flex-1 border-r border-white/50"></div>
                                                    ))}
                                                </div>
                                                <div 
                                                    className={`h-full rounded-full ${phase.color} shadow-sm transition-all duration-700`}
                                                    style={{
                                                        width: `${(phase.duration / calculations.calculatedDurationWeeks) * 100}%`,
                                                        marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`
                                                    }}
                                                ></div>
                                            </div>
                                            <div className="mt-1 flex justify-between text-[10px] text-slate-400">
                                                <span style={{marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + 1}</span>
                                                <span style={{marginRight: `${100 - ((phase.startOffset + phase.duration) / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + phase.duration}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="mt-8 pt-6 border-t border-slate-100 text-center">
                                    <p className="text-xs text-slate-400 italic">Timeline is derived from total effort hours divided by the effective team velocity. Adjust "Resource Plan" to compress or expand timelines.</p>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* TAB 4: ASSUMPTIONS */}
                    {activeTab === 'assumptions' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <h3 className="font-bold text-slate-800 text-sm">Assumptions & Scope</h3>
                                <div className="flex gap-2">
                                   <button className="text-xs text-green-600 bg-green-50 hover:bg-green-100 px-2 py-1 rounded border border-green-200 flex items-center gap-1" onClick={() => setAssumptions(prev => ({...prev, inScope: [...prev.inScope, "New Item"]}))}><Plus size={12}/> In Scope</button>
                                   <button className="text-xs text-red-600 bg-red-50 hover:bg-red-100 px-2 py-1 rounded border border-red-200 flex items-center gap-1" onClick={() => setAssumptions(prev => ({...prev, outScope: [...prev.outScope, "New Item"]}))}><Plus size={12}/> Out Scope</button>
                                </div>
                            </div>
                            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div>
                                    <h4 className="text-sm font-bold text-green-700 mb-4 flex items-center gap-2"><ListChecks size={16}/> In Scope</h4>
                                    <ul className="space-y-2">
                                        {assumptions.inScope.map((item, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-slate-700 bg-green-50/50 p-2 rounded border border-green-100 group">
                                                <span className="mt-1 w-1.5 h-1.5 bg-green-500 rounded-full shrink-0"/>
                                                <input 
                                                   className="bg-transparent w-full outline-none" 
                                                   value={item} 
                                                   onChange={(e) => {
                                                       const newItems = [...assumptions.inScope];
                                                       newItems[i] = e.target.value;
                                                       setAssumptions({...assumptions, inScope: newItems});
                                                   }}
                                                />
                                                <button onClick={() => setAssumptions(prev => ({...prev, inScope: prev.inScope.filter((_, idx) => idx !== i)}))} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={14}/></button>
                                            </li>
                                        ))}
                                        {assumptions.inScope.length === 0 && <p className="text-xs text-slate-400 italic">No in-scope items defined.</p>}
                                    </ul>
                                </div>
                                <div>
                                    <h4 className="text-sm font-bold text-red-700 mb-4 flex items-center gap-2"><X size={16}/> Out of Scope</h4>
                                    <ul className="space-y-2">
                                        {assumptions.outScope.map((item, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-slate-700 bg-red-50/50 p-2 rounded border border-red-100 group">
                                                <span className="mt-1 w-1.5 h-1.5 bg-red-500 rounded-full shrink-0"/>
                                                <input 
                                                   className="bg-transparent w-full outline-none" 
                                                   value={item} 
                                                   onChange={(e) => {
                                                       const newItems = [...assumptions.outScope];
                                                       newItems[i] = e.target.value;
                                                       setAssumptions({...assumptions, outScope: newItems});
                                                   }}
                                                />
                                                <button onClick={() => setAssumptions(prev => ({...prev, outScope: prev.outScope.filter((_, idx) => idx !== i)}))} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={14}/></button>
                                            </li>
                                        ))}
                                         {assumptions.outScope.length === 0 && <p className="text-xs text-slate-400 italic">No out-of-scope items defined.</p>}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    )}

                </div>
            )}
         </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
