         `;
     } else if (interactionType === 'acceptance') {
         taskInstruction = `
            CRITICAL TASK: The user ACCEPTED this design. This is a positive reinforcement.
            Extract the most distinct/unique architectural decision made here (e.g. specific tool choice, flow pattern) and save it as a "Proven Pattern".
         `;
     } else {
         taskInstruction = `
            Task: Extract a general architectural preference or constraint from this initial generation request.
         `;
     }

     const prompt = `
        You are the "Meta-Learning Module" of the Data Management Accelerator.
        Input Context: ${context}
        Interaction Type: ${interactionType}
        User Refinement: ${userPrompt || "N/A"}
        Current Knowledge Base Size: ${LEARNED_PATTERNS.length} patterns.

        ${taskInstruction}

        Output strictly one concise sentence starting with "Pattern:".
     `;

     const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt
     });

     if (response.text && response.text.trim().startsWith("Pattern:")) {
        savePattern(response.text.trim());
     }
   } catch (e) {
     console.error("Learning cycle failed", e);
   }
};

