    XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(summaryData), "Summary");

    // Add DQ Rules Sheet
    if (dqRules.length > 0) {
        const rulesData = [
            ["Rule Name", "Type", "Criticality", "Description"],
            ...dqRules.map(r => [r.name, r.type, r.criticality, r.description])
        ];
        XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(rulesData), "DQ Rules");
