     : ['design', 'dataQuality', 'estimator', 'requirements', 'initiation', 'scoping', 'attachments'];

  const activeDesignToRender = designMode === 'hld' ? currentDesign : designMode === 'table' ? tableDesign : processDesign;
  const showActiveDesignCanvas = (activeDesignToRender.nodes.length > 0) || (designMode === 'hld' && status === 'idle'); // HLD shows empty state card

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-fade-in relative">
