      Learned Patterns: ${LEARNED_PATTERNS.join('\n')}
      Context: ${context}

      Drivers to Estimate (Return counts for these keys):
      - di_src (Source Systems count)
      - di_map_s (Simple Mappings), di_map_m (Medium), di_map_c (Complex)
      - di_task (Task flows)
      - dq_prof (Profiling objects), dq_rule_s (Simple DQ Rules), dq_rule_m, dq_rule_c, dq_sc (Scorecards)
      - dg_src (Governance Resources), dg_term (Business Terms), dg_pol (Policies), dg_lin (Lineage), dg_kde, dg_class
      - mdm_dom (Domains), mdm_ing_s (Simple Ingestion), mdm_ing_c, mdm_match (Match Rules), mdm_ui

      Instructions:
      1. Be realistic. If the text says "Migrate 50 tables", assume approx 50 mappings split by complexity (e.g. 30 simple, 15 medium, 5 complex).
      2. If specific numbers are not found, infer them based on the text's complexity (Small/Medium/Large project).

      Output ONLY valid JSON.
    `;

    const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: simpleEstimationSchema,
      },
    }));

    const parsed = safeJsonParse(response.text, null);

    if (parsed && parsed.inputs) {
        const inputs: EstimationInputs = {};
        parsed.inputs.forEach((item: any) => {
            inputs[item.driverId] = item.value;
        });
        return inputs;
    }
    return null;
  } catch (e) {
    console.error("Dynamic estimation input generation failed", e);
    return null;
  }
};

