                                   <button className="text-xs text-red-600 bg-red-50 hover:bg-red-100 px-2 py-1 rounded border border-red-200 flex items-center gap-1" onClick={() => setAssumptions(prev => ({...prev, outScope: [...prev.outScope, "New Item"]}))}><Plus size={12}/> Out Scope</button>
                                </div>
                            </div>
                            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div>
                                    <h4 className="text-sm font-bold text-green-700 mb-4 flex items-center gap-2"><ListChecks size={16}/> In Scope</h4>
                                    <ul className="space-y-2">
                                        {assumptions.inScope.map((item, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-slate-700 bg-green-50/50 p-2 rounded border border-green-100 group">
                                                <span className="mt-1 w-1.5 h-1.5 bg-green-500 rounded-full shrink-0"/>
                                                <input 
                                                   className="bg-transparent w-full outline-none" 
                                                   value={item} 
                                                   onChange={(e) => {
                                                       const newItems = [...assumptions.inScope];
                                                       newItems[i] = e.target.value;
                                                       setAssumptions({...assumptions, inScope: newItems});
                                                   }}
                                                />
                                                <button onClick={() => setAssumptions(prev => ({...prev, inScope: prev.inScope.filter((_, idx) => idx !== i)}))} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={14}/></button>
                                            </li>
                                        ))}
                                        {assumptions.inScope.length === 0 && <p className="text-xs text-slate-400 italic">No in-scope items defined.</p>}
                                    </ul>
                                </div>
                                <div>
                                    <h4 className="text-sm font-bold text-red-700 mb-4 flex items-center gap-2"><X size={16}/> Out of Scope</h4>
                                    <ul className="space-y-2">
                                        {assumptions.outScope.map((item, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-slate-700 bg-red-50/50 p-2 rounded border border-red-100 group">
                                                <span className="mt-1 w-1.5 h-1.5 bg-red-500 rounded-full shrink-0"/>
                                                <input 
                                                   className="bg-transparent w-full outline-none" 
                                                   value={item} 
                                                   onChange={(e) => {
                                                       const newItems = [...assumptions.outScope];
                                                       newItems[i] = e.target.value;
                                                       setAssumptions({...assumptions, outScope: newItems});
                                                   }}
                                                />
                                                <button onClick={() => setAssumptions(prev => ({...prev, outScope: prev.outScope.filter((_, idx) => idx !== i)}))} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={14}/></button>
                                            </li>
                                        ))}
                                         {assumptions.outScope.length === 0 && <p className="text-xs text-slate-400 italic">No out-of-scope items defined.</p>}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    )}

                </div>
            )}
         </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-emerald-500" /> Estimator Guide</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>1. Input & Learn:</strong> Upload an RFP or a previous estimation Excel file. The AI learns the complexity patterns.</p>
                    <p><strong>2. Configure Drivers:</strong> The AI populates the driver counts (e.g., 50 tables). You can tweak these numbers, and the cost/effort updates instantly.</p>
                    <p><strong>3. Auto-Scale Resources:</strong> Go to the Resource tab. Increasing the headcount will automatically reduce the project timeline in the Timeline tab.</p>
                 </div>
              </div>
           </div>
      )}
    </div>
  );
};

