              <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 relative">
                 <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-100">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2"><ShieldCheck className="text-emerald-500"/> Data Quality Rules</h3>
                    <button onClick={() => setShowRuleForm(true)} className="flex items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white rounded-lg text-sm font-bold shadow-sm">
