                        <Loader size={24} className="animate-spin mb-4 text-emerald-500" />
                        <p>AI is defining quality rules...</p>
                    </div>
                 ) : (
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                           {dqRules.map((rule) => (
