interface StandaloneEstimatorProps {
  embedded?: boolean;
  initialContext?: string;
  initialInputs?: EstimationInputs;
  onSave?: (inputs: EstimationInputs) => void;
}

const StandaloneEstimator: React.FC<StandaloneEstimatorProps> = ({ 
  embedded = false, 
  initialContext = '', 
  initialInputs, 
  onSave 
}) => {
  const [context, setContext] = useState(initialContext);
  // New State: Result View is hidden initially for standalone, but shown for embedded if data exists
  const [showResults, setShowResults] = useState(embedded && initialInputs ? true : false);
  const [activeTab, setActiveTab] = useState<'drivers' | 'resources' | 'timeline' | 'assumptions'>('drivers');

  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [assumptions, setAssumptions] = useState<AssumptionData>({ inScope: [], outScope: [] });

  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);

  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);

  // AI Rationale (NLP Output)
  const [aiRationale, setAiRationale] = useState<string>("Analyzing project requirements...");

  // Resource State (Editable)
  const [customResourceCounts, setCustomResourceCounts] = useState<Record<string, number>>({
    'pm': 1, 'arch': 1, 'lead': 1, 'dev': 2, 'qa': 1
  });

  // Initialize
  useEffect(() => {
    if (initialInputs) {
        setEstimationInputs(initialInputs);
    } else {
        const defaults: EstimationInputs = {};
        ALL_MODULES_CONFIG.forEach(m => m.drivers.forEach(d => defaults[d.id] = d.defaultValue));
        setEstimationInputs(defaults);
    }

    // Only load history if standalone
    if (!embedded) {
        setHistoryItems(getHistory('Estimator'));
    }
  }, [initialInputs, embedded]);

  // Sync back to parent if embedded
  useEffect(() => {
      if (embedded && onSave && Object.keys(estimationInputs).length > 0) {
          onSave(estimationInputs);
      }
  }, [estimationInputs, embedded, onSave]);

  // Update context if prop changes
  useEffect(() => {
      if (initialContext) setContext(initialContext);
  }, [initialContext]);

  // Timer Effect
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // --- RECALCULATION ENGINE ---
  const calculations = useMemo(() => {
    let totalTechHours = 0;
    const moduleBreakdown: Record<string, number> = {};

    // 1. Calculate Tech Hours from Drivers
    ALL_MODULES_CONFIG.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const val = estimationInputs[driver.id] || 0;
        modHours += val * driver.multiplier;
      });
      moduleBreakdown[mod.id] = modHours;
      totalTechHours += modHours;
    });

    const testingBuffer = totalTechHours * 0.30;
    const grandTotalHours = totalTechHours + testingBuffer;

    // 2. Resource & Duration Logic (Auto-Scalable)
    // Formula: Duration = TotalHours / (Headcount * Velocity)
    // Velocity assumed: 35 effective hours/week per person

    const resourceList = [
        { id: 'pm', role: 'Project Manager', rate: 800, utilization: 0.5 },
        { id: 'arch', role: 'Solution Architect', rate: 950, utilization: 0.25 },
        { id: 'lead', role: 'Tech Lead', rate: 750, utilization: 1.0 },
        { id: 'dev', role: 'Developer', rate: 500, utilization: 1.0 },
        { id: 'qa', role: 'QA Engineer', rate: 450, utilization: 1.0 },
    ];

    // Calculate effective team velocity based on current resource counts
    const effectiveDevCount = customResourceCounts['dev'] || 1;
    const weeklyVelocity = effectiveDevCount * 35; // 35 hours per dev per week

    // Derived Duration
    const calculatedDurationWeeks = Math.max(4, Math.ceil(grandTotalHours / weeklyVelocity));

    const finalResources = resourceList.map(r => ({
        ...r,
        count: customResourceCounts[r.id] || 1,
        totalCost: (calculatedDurationWeeks * 5) * (customResourceCounts[r.id] || 1) * r.rate * r.utilization
    }));

    const totalProjectCost = finalResources.reduce((acc, r) => acc + r.totalCost, 0);

    // 3. Timeline Phases Generation
    const phases = [
        { name: "Inception & Analysis", pct: 0.10, color: "bg-blue-500" },
        { name: "Design & Architecture", pct: 0.15, color: "bg-indigo-500" },
        { name: "Build & Implementation", pct: 0.50, color: "bg-emerald-500" },
        { name: "Testing (SIT/UAT)", pct: 0.20, color: "bg-orange-500" },
        { name: "Deployment & Go-Live", pct: 0.05, color: "bg-slate-700" }
    ];

    let currentStart = 0;
    const timelineData = phases.map(p => {
        const weeks = Math.max(1, Math.round(calculatedDurationWeeks * p.pct));
        const start = currentStart;
        currentStart += weeks;
        return { ...p, duration: weeks, startOffset: start };
    });

    return { 
        grandTotalHours, 
        calculatedDurationWeeks, 
        totalProjectCost, 
        moduleBreakdown, 
        finalResources,
        timelineData
    };
  }, [estimationInputs, customResourceCounts]);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    if (!context.trim()) return;
    setIsGenerating(true);
    setEta(8); // Estimated 8 seconds
    setError(null);
    try {
      const [estimationResult, assumptionResult] = await Promise.all([
         generateDynamicEstimation(context),
         generateAssumptions(context)
      ]);

      if (estimationResult) {
          setEstimationInputs(prev => ({...prev, ...estimationResult}));
          // Auto-scale dev count based on complexity if needed (simple heuristic)
          const totalObj = Object.values(estimationResult).reduce((a,b) => a+b, 0);
          if (totalObj > 100) setCustomResourceCounts(prev => ({...prev, dev: 4, qa: 2}));
          else if (totalObj > 50) setCustomResourceCounts(prev => ({...prev, dev: 3, qa: 1}));

          setAiRationale(`Based on the requirements, I've identified ${totalObj} key estimation drivers. The complexity suggests a ${totalObj > 50 ? 'Medium-to-High' : 'Standard'} effort. I have pre-populated the driver table below which you can fine-tune.`);

          if (assumptionResult) setAssumptions(assumptionResult);

          const fullDataToSave = {
              data: estimationResult,
              assumptions: assumptionResult
          };

          if (!embedded) {
             saveHistory('Estimator', context.substring(0, 40) + '...', fullDataToSave, uploadedFiles);
             setHistoryItems(getHistory('Estimator'));
          }
          setShowResults(true); // Reveal tabs
          setActiveTab('drivers');

          // Trigger background learning
          setIsLearning(true);
          analyzeAndLearn(context, null, estimationResult, ['Manager'], 'initial').finally(() => setIsLearning(false));

      } else {
          setError("AI could not infer specific project drivers. Please verify requirements.");
      }
    } catch (e) {
      console.error(e);
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);

      if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
         // Excel parsing logic ...
         setContext(prev => prev + `\n[Attached Estimation File: ${file.name}]`);
      } else {
         setContext(prev => prev + `\n[Attached RFP: ${file.name}]`);
      }
    }
  };

  const loadHistoryItem = (item: any) => {
    setContext(item.summary);
    setEstimationInputs(item.data.data || item.data); // Backwards compat
    if (item.data.assumptions) setAssumptions(item.data.assumptions);
    setUploadedFiles(item.files || []);
    setShowResults(true);
    setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const exportXLSX = () => {
    if (!window.XLSX) { alert("Library loading..."); return; }
    const XLSX = window.XLSX;
    const wb = XLSX.utils.book_new();

    // Sheet 1: Executive Summary
    const summaryData = [
      ["EXECUTIVE SUMMARY"],
      ["Project Context", context.substring(0, 200) + "..."],
      ["AI Analysis", aiRationale],
      [],
      ["KEY METRICS"],
      ["Total Estimated Cost", calculations.totalProjectCost],
      ["Total Effort (Hours)", calculations.grandTotalHours],
      ["Estimated Duration", `${calculations.calculatedDurationWeeks} Weeks`],
      [],
      ["Generated By", "DataArch AI Accelerator"]
    ];
    const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(wb, wsSummary, "Summary");

    // Sheet 2: Detailed Drivers
    const driverHeader = [["Module", "Driver Name", "Category", "Quantity", "Multiplier (Hrs)", "Total Hours", "Description"]];
    const driverRows: any[] = [];
    ALL_MODULES_CONFIG.forEach(mod => {
        mod.drivers.forEach(d => {
            const qty = estimationInputs[d.id] || 0;
            if (qty > 0) {
                driverRows.push([mod.title, d.label, d.category, qty, d.multiplier, qty * d.multiplier, d.description]);
            }
        });
    });
    const wsDrivers = XLSX.utils.aoa_to_sheet([...driverHeader, ...driverRows]);
    XLSX.utils.book_append_sheet(wb, wsDrivers, "Complexity Drivers");

    // Sheet 3: Resource Plan
    const resHeader = [["Role", "Headcount", "Daily Rate", "Utilization %", "Cost"]];
    const resRows = calculations.finalResources.map(r => [
        r.role, r.count, r.rate, r.utilization * 100, r.totalCost
    ]);
    const wsRes = XLSX.utils.aoa_to_sheet([...resHeader, ...resRows]);
    XLSX.utils.book_append_sheet(wb, wsRes, "Resource Plan");

    // Sheet 4: Timeline
    const timeHeader = [["Phase", "Duration (Weeks)", "Start Week", "End Week"]];
    const timeRows = calculations.timelineData.map(t => [
        t.name, t.duration, t.startOffset + 1, t.startOffset + t.duration
    ]);
    const wsTime = XLSX.utils.aoa_to_sheet([...timeHeader, ...timeRows]);
    XLSX.utils.book_append_sheet(wb, wsTime, "Timeline");

    // Sheet 5: Assumptions
    const asmHeader = [["Type", "Item"]];
    const asmRows = [
        ...assumptions.inScope.map(i => ["In Scope", i]),
        ...assumptions.outScope.map(i => ["Out of Scope", i])
    ];
    const wsAsm = XLSX.utils.aoa_to_sheet([...asmHeader, ...asmRows]);
    XLSX.utils.book_append_sheet(wb, wsAsm, "Assumptions");

    XLSX.writeFile(wb, "Project_Estimation_Report.xlsx");

    // Trigger learning on Export (Reinforce current config)
    setIsLearning(true);
    analyzeAndLearn(context, "User Finalized Estimate", estimationInputs, ['Manager'], 'acceptance').finally(() => setIsLearning(false));
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);

  return (
    <div className={`flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in ${embedded ? 'bg-transparent' : ''}`}>

      {/* Header - Hidden if Embedded */}
      {!embedded && (
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
