                    <tr key={idx} className="hover:bg-indigo-50/30 transition-colors cursor-pointer group" onClick={() => onSelectRequest(req)}>
                        <td className="px-6 py-4 font-bold text-slate-800">{req.clientName}</td>
                        <td className="px-6 py-4">
                            <div className="flex flex-col">
                                <span className="font-medium text-slate-700">{req.product}</span>
                                <span className="text-xs text-slate-500">{req.type}</span>
                            </div>
                        </td>
                        <td className="px-6 py-4">
                            <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${getStatusColor(req.status)}`}>
                                {req.status}
                            </span>
                        </td>
                        <td className="px-6 py-4 text-slate-500">
                           {req.rfpFiles.length > 0 ? (
                              <div className="flex items-center gap-1"><FileText size={14}/> {req.rfpFiles.length}</div>
                           ) : <span className="text-slate-300">-</span>}
                        </td>
                        <td className="px-6 py-4 text-slate-500">{req.date}</td>
                        <td className="px-6 py-4 text-right">
                            <div className="flex justify-end gap-2">
                                <button className="text-slate-400 group-hover:text-indigo-600 transition-colors bg-white p-2 rounded-full shadow-sm border border-slate-100"><ArrowUpRight size={18} /></button>
                                <button 
                                    className="text-slate-400 hover:text-red-500 transition-colors bg-white p-2 rounded-full shadow-sm border border-slate-100"
                                    onClick={(e) => { e.stopPropagation(); onDeleteRequest(req.id); }}
                                >
                                    <Trash2 size={18} />
                                </button>
                            </div>
                        </td>
                    </tr>
                   ))
                )}
                </tbody>
              </table>
          </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-indigo-500" /> Design Module Help</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>Overview:</strong> The Design Hub is your central command for managing solution architecture requests.</p>
                    <p><strong>How to use:</strong></p>
                    <ul className="list-disc pl-5 space-y-2">
                       <li>Click <strong>New Request</strong> to start a new AI-driven design session.</li>
                       <li>Select an existing request to resume design, view estimations, or refine architecture.</li>
                       <li>Use the search bar to filter by client name or technology.</li>
                    </ul>
                 </div>
              </div>
           </div>
        )}
    </div>
  );
};

