import React, { useState, useEffect } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  HelpCircle,
  X,
  BrainCircuit,
  Lock,
  Wand2
} from 'lucide-react';
import { generateDataQualityRules, generateDQCleanseRules, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule, DQCleanseRule } from '../types';

const StandaloneDataQuality: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'validation' | 'cleanse'>('validation');

  // Validation State
  const [cdeContext, setCdeContext] = useState('');
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);

  // Cleanse State
  const [profileFile, setProfileFile] = useState<File | null>(null);
  const [cleanseRules, setCleanseRules] = useState<DQCleanseRule[]>([]);

  // Common State
  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isLearning, setIsLearning] = useState(false);

  // Timer Effect
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  const handleGenerateValidation = async () => {
    if (!cdeContext.trim()) return;
    setIsGenerating(true);
    setEta(8);
    setError(null);
    try {
      const rules = await generateDataQualityRules(cdeContext, "Informatica Cloud Data Quality");
      setValidationRules(rules);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(cdeContext, "Generated DQ Validation Rules", rules, ['Data Steward'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate validation rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleUploadProfile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setProfileFile(e.target.files[0]);
    }
  };

  const handleGenerateCleanse = async () => {
    if (!profileFile) return;
    setIsGenerating(true);
    setEta(12);
    setError(null);
    try {
      // Simulate file reading or just use file name as context trigger
      const context = `Profile File Name: ${profileFile.name}. [Simulation: High noise in 'Address' column, inconsistent casing in 'CustomerName', duplicates found in 'Email'].`;
      const rules = await generateDQCleanseRules(context);
      setCleanseRules(rules);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(context, "Generated DQ Cleanse Rules", rules, ['Data Engineer'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate cleanse rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><ShieldCheck size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Data Quality Studio
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Validation & Cleansing Logic Generator (IDQ/CDQ)</p>
            </div>
         </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <X size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-6 md:p-8">
         <div className="max-w-6xl mx-auto space-y-8">

            {/* Tabs */}
            <div className="flex gap-1 mb-6 bg-slate-200/50 p-1 rounded-xl inline-flex overflow-x-auto max-w-full">
                <button 
                  onClick={() => setActiveTab('validation')} 
                  className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap flex items-center gap-2 ${activeTab === 'validation' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  <CheckCircle size={16} /> DQ Validation Rules
                </button>
                <button 
                  onClick={() => setActiveTab('cleanse')} 
                  className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap flex items-center gap-2 ${activeTab === 'cleanse' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  <Wand2 size={16} /> DQ Cleanse Rules
                </button>
            </div>

            {/* TAB 1: VALIDATION RULES */}
            {activeTab === 'validation' && (
               <div className="animate-fade-in space-y-6">
                  {/* Input Area */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                     <div className="mb-4">
                        <label className="block text-sm font-bold text-slate-700 mb-2">Define Critical Data Elements (CDEs)</label>
                        <textarea 
                           className="w-full p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500 outline-none min-h-[100px]"
                           placeholder="Enter CDEs and context (e.g., Customer Email, Order Amount, Shipping Address). Mention specific business constraints."
                           value={cdeContext}
                           onChange={(e) => setCdeContext(e.target.value)}
                        />
                     </div>
                     <div className="flex justify-end">
                        <button 
                           onClick={handleGenerateValidation}
                           disabled={!cdeContext.trim() || isGenerating}
                           className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50"
                        >
                           {isGenerating ? <Loader size={16} className="animate-spin" /> : <Sparkles size={16} />}
                           {isGenerating && eta > 0 ? `Generating (${eta}s)` : 'Suggest Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area */}
                  {validationRules.length > 0 && (
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {validationRules.map((rule) => (
                           <div key={rule.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                              <div className="flex justify-between items-start mb-3">
                                 <h4 className="font-bold text-slate-800 text-sm">{rule.name}</h4>
                                 <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${rule.criticality === 'High' ? 'bg-red-50 text-red-700 border-red-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>{rule.criticality}</span>
                              </div>
                              <p className="text-xs text-slate-600 mb-3">{rule.description}</p>
                              <div className="bg-slate-50 p-2 rounded border border-slate-100">
                                 <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Logic / Expression</p>
                                 <code className="text-xs text-slate-700 font-mono">{rule.logic || "N/A"}</code>
                              </div>
                              <div className="mt-3 pt-3 border-t border-slate-100 flex justify-between items-center">
                                 <span className="text-[10px] text-slate-400">Dimension: {rule.type}</span>
                              </div>
                           </div>
                        ))}
                     </div>
                  )}
               </div>
            )}

            {/* TAB 2: CLEANSE RULES */}
            {activeTab === 'cleanse' && (
               <div className="animate-fade-in space-y-6">
                  {/* Upload Area */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                     <h3 className="font-bold text-slate-800 mb-2">Upload Profile for Cleansing Analysis</h3>
                     <p className="text-xs text-slate-500 mb-4">Upload an Informatica "Rule Based Profile" export or a sample dataset to generate cleansing logic.</p>

                     {!profileFile ? (
                        <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                           <div className="flex flex-col items-center justify-center pt-5 pb-6">
                              <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                              <p className="text-sm text-slate-500"><span className="font-semibold">Click to upload profile</span></p>
                           </div>
                           <input type="file" className="hidden" onChange={handleUploadProfile} />
                        </label>
                     ) : (
                        <div className="flex items-center justify-between p-4 bg-blue-50 border border-blue-100 rounded-lg">
                           <div className="flex items-center gap-3">
                              <div className="p-2 bg-blue-100 text-blue-600 rounded"><FileText size={20} /></div>
                              <div>
                                 <p className="text-sm font-bold text-slate-700">{profileFile.name}</p>
                                 <p className="text-xs text-slate-500">Ready for analysis</p>
                              </div>
                           </div>
                           <button onClick={() => setProfileFile(null)} className="text-slate-400 hover:text-red-500"><X size={18} /></button>
                        </div>
                     )}

                     <div className="flex justify-end mt-4">
                        <button 
                           onClick={handleGenerateCleanse}
                           disabled={!profileFile || isGenerating}
                           className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                           {isGenerating ? <Loader size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                           {isGenerating && eta > 0 ? `Analysing Profile (${eta}s)` : 'Generate Cleanse Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area */}
                  {cleanseRules.length > 0 ? (
                     <div className="grid grid-cols-1 gap-4">
                        {cleanseRules.map((rule) => (
                           <div key={rule.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-shadow">
                              <div className="flex-1">
                                 <div className="flex items-center gap-2 mb-2">
                                    <span className="px-2 py-1 bg-indigo-50 text-indigo-700 text-[10px] font-bold uppercase rounded border border-indigo-100">{rule.transformationType}</span>
                                    <h4 className="font-bold text-slate-800 text-sm">Cleanse: {rule.element}</h4>
                                 </div>
                                 <p className="text-sm text-slate-600 leading-relaxed mb-2">{rule.logic}</p>
                                 <div className="text-xs text-slate-400 flex items-center gap-1"><BrainCircuit size={12}/> Suggested Asset: <span className="font-mono text-slate-600">{rule.informaticaAsset}</span></div>
                              </div>
                           </div>
                        ))}
                     </div>
                  ) : (
                     !isGenerating && (
                        <div className="text-center py-10">
                           <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300">
                              <Lock size={24} />
                           </div>
                           <p className="text-slate-400 text-sm">Cleansing rules are locked until a profile is uploaded.</p>
                        </div>
                     )
                  )}
               </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default StandaloneDataQuality;

