import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Bot, User, Minimize2, Book } from 'lucide-react';
import { sendChatMessage } from '../services/geminiService';

interface AiAssistantProps {
  context: string;
}

const APP_KNOWLEDGE_BASE = `
SYSTEM IDENTITY: You are the DataArch AI Assistant, an expert embedded within the "DataArch AI" web application.
YOUR GOAL: Help users navigate the app and answer questions about data architecture.

APP MODULES & NAVIGATION GUIDANCE:
1. **Dashboard**: The landing page. Shows an overview of all requests and statistics.
2. **Design Hub / Solution Designer**: The main module for creating new projects.
   - Use this when the user has an RFP, a Requirements Document, or wants to design a full end-to-end solution.
   - It generates High-Level Designs, Requirements, and Scoping Questions.
3. **Estimator (Ad-hoc)**: A dedicated calculator for project costs and timelines.
   - Use this when the user asks about "pricing", "effort", "staffing", or "how long a project will take".
   - It uses "Drivers" (like number of tables, complexity) to calculate hours.
4. **Architecture Flow (Ad-hoc)**: A drawing tool for system diagrams.
   - Use this when the user wants to "draw a diagram", "visualize a system", or "create an HLD" without a full project context.
5. **Data Flow (Ad-hoc)**: A drawing tool specifically for ETL/Data Movement.
   - Use this for "mappings", "transformations", "ETL logic", or "lineage".
6. **Data Quality (Ad-hoc)**: A tool for DQ rules.
   - Use this when users need "validation rules", "cleansing logic", or "Informatica CDQ rules".

INSTRUCTION:
- If a user asks how to do something, tell them which module to use.
- You cannot physically click buttons for them, but you can guide them: "Please navigate to the [Module Name] tab in the sidebar."
- Keep answers concise and helpful.
`;

const AiAssistant: React.FC<AiAssistantProps> = ({ context }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{role: 'user' | 'model', text: string}[]>([
    { role: 'model', text: 'Hi! I am the DataArch Assistant. I can help you navigate the app or answer architecture questions.' }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const newMsg = { role: 'user' as const, text: input };
    setMessages(prev => [...prev, newMsg]);
    setInput('');
    setIsTyping(true);

    // Combine Global App Knowledge with the specific Page Context
    const fullContext = `${APP_KNOWLEDGE_BASE}\n\nCURRENT PAGE CONTEXT:\n${context}`;

    const history = messages.map(m => ({ role: m.role, text: m.text }));
    const response = await sendChatMessage(history, input, fullContext);

    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end">
      {isOpen ? (
        <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-80 md:w-96 h-[500px] flex flex-col overflow-hidden animate-fade-in-up">
          {/* Header */}
          <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-4 flex justify-between items-center text-white">
            <div className="flex items-center gap-2">
              <div className="bg-white/20 p-1 rounded-full"><Bot size={18} /></div>
              <div>
                <h3 className="font-bold text-sm">AI Architect</h3>
                <p className="text-[10px] text-indigo-100 flex items-center gap-1">
                   <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></span> Online
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1.5 rounded-lg transition-colors">
                <Minimize2 size={16} />
              </button>
            </div>
          </div>

          {/* Chat Area */}
          <div className="flex-1 overflow-y-auto p-4 bg-slate-50 space-y-4" ref={scrollRef}>
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-2xl px-4 py-2.5 text-xs md:text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-br-none' 
                    : 'bg-white border border-slate-200 text-slate-700 rounded-bl-none shadow-sm'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isTyping && (
               <div className="flex justify-start">
                  <div className="bg-white border border-slate-200 rounded-2xl rounded-bl-none px-4 py-3 shadow-sm">
                     <div className="flex gap-1">
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></span>
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></span>
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></span>
                     </div>
                  </div>
               </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-slate-100 flex gap-2">
            <input 
              type="text" 
              className="flex-1 bg-slate-100 border-transparent focus:bg-white focus:ring-2 focus:ring-indigo-500 rounded-xl px-4 py-2 text-sm outline-none transition-all"
              placeholder="Ask about features or architecture..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button 
              onClick={handleSend}
              disabled={!input.trim()}
              className="bg-indigo-600 text-white p-2.5 rounded-xl hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-indigo-600 hover:bg-indigo-700 text-white p-4 rounded-full shadow-lg shadow-indigo-500/30 transition-all hover:scale-110 flex items-center gap-2 group"
        >
          <Bot size={24} />
          <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-300 font-bold whitespace-nowrap">Chat with AI</span>
        </button>
      )}
    </div>
  );
};

export default AiAssistant;

import React, { useRef, useState, useEffect, useImperativeHandle, forwardRef } from 'react';
import { 
  Database, 
  Server, 
  CloudLightning, 
  Settings, 
  Share2, 
  Code,
  BrainCircuit,
  CheckCircle,
  Loader,
  X,
  Copy,
  Check,
  Image as ImageIcon,
  FileCode,
  Sparkles,
  Zap,
  Info,
  ZoomIn,
  ZoomOut,
  Maximize,
  MessageSquare,
  Send
} from 'lucide-react';
import { Node, Edge, RefinementSuggestion, DesignData, ArchitectureCanvasHandle } from '../types';
import { generateDesignRefinements } from '../services/geminiService';

interface ArchitectureCanvasProps {
  aiNodes: Node[];
  aiEdges: Edge[];
  isThinking: boolean;
  thoughts: string[];
  context?: string; 
  audience?: string[];
  onApplyRefinement?: (newDesign: DesignData) => void;
  // New props for unified re-input
  onRefine?: (prompt: string) => void;
  refinementPlaceholder?: string;
}

const ArchitectureCanvas = forwardRef<ArchitectureCanvasHandle, ArchitectureCanvasProps>(({ 
  aiNodes, 
  aiEdges, 
  isThinking, 
  thoughts,
  context = "",
  audience = [],
  onApplyRefinement,
  onRefine,
  refinementPlaceholder = "Refine diagram..."
}, ref) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [showMermaid, setShowMermaid] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Refinement Input State
  const [refineInput, setRefineInput] = useState("");

  // Zoom & Pan State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [startPan, setStartPan] = useState({ x: 0, y: 0 });

  // Refinement State
  const [showInsights, setShowInsights] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [suggestions, setSuggestions] = useState<RefinementSuggestion[]>([]);

  // Hover State
  const [hoveredNode, setHoveredNode] = useState<Node | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  // Expose export function to parent
  useImperativeHandle(ref, () => ({
    exportImage: (format: 'png' | 'svg') => handleExport(format)
  }));

  const getMermaidCode = () => {
    if (!aiNodes.length) return "graph LR\n  NoData[No Design Generated]";
    let code = "graph LR\n";
    code += "  classDef source fill:#eff6ff,stroke:#3b82f6,stroke-width:2px,color:#1e40af;\n";
    code += "  classDef stage fill:#f1f5f9,stroke:#64748b,stroke-width:2px,color:#334155;\n";
    code += "  classDef process fill:#fff7ed,stroke:#f97316,stroke-width:2px,color:#9a3412;\n";
    code += "  classDef target fill:#ecfdf5,stroke:#10b981,stroke-width:2px,color:#065f46;\n\n";

    aiNodes.forEach(node => {
      const label = node.label.replace(/"/g, "'");
      code += `  ${node.id}["${label}"]:::${node.type}\n`;
    });
    code += "\n";
    aiEdges.forEach(edge => {
      const label = edge.label ? `|"${edge.label}"|` : "";
      code += `  ${edge.from} -->${label} ${edge.to}\n`;
    });
    return code;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getMermaidCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleExport = (format: 'svg' | 'png') => {
    if (!svgRef.current) return;
    const svgEl = svgRef.current;

    // Serialize current state
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svgEl);
    if(!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)){
        source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    source = '<?xml version="1.0" standalone="no"?>\r\n' + source;
    const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);

    if (format === 'svg') {
        const link = document.createElement("a");
        link.href = url;
        link.download = `solution-design-${Date.now()}.svg`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        const img = new Image();
        img.src = url;
        img.onload = () => {
            const canvas = document.createElement("canvas");
            // Use dynamic size based on SVG viewBox or current client size
            const rect = svgEl.getBoundingClientRect();
            canvas.width = rect.width * 2; // 2x for better quality
            canvas.height = rect.height * 2;
            const ctx = canvas.getContext("2d");
            if (ctx) {
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                const link = document.createElement("a");
                link.href = canvas.toDataURL("image/png");
                link.download = `solution-design-${Date.now()}.png`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        };
    }
    setShowExportMenu(false);
  };

  const handleFetchRefinements = async () => {
    if (!context || !aiNodes.length) return;
    setIsRefining(true);
    setShowInsights(true);
    setSuggestions([]);
    try {
      const currentDesign = { nodes: aiNodes, edges: aiEdges };
      const newSuggestions = await generateDesignRefinements(currentDesign, context, audience);
      setSuggestions(newSuggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefining(false);
    }
  };

  const applySuggestion = (suggestion: RefinementSuggestion) => {
    if (onApplyRefinement) {
      onApplyRefinement(suggestion.suggestedDesign);
      setSuggestions(prev => prev.filter(s => s.id !== suggestion.id)); 
    }
  };

  const submitRefinement = () => {
      if (onRefine && refineInput.trim()) {
          onRefine(refineInput);
          setRefineInput("");
      }
  };

  // --- Zoom & Pan Handlers ---
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const scaleFactor = 0.05;
    const delta = e.deltaY > 0 ? -scaleFactor : scaleFactor;
    const newZoom = Math.max(0.5, Math.min(3, zoom + delta));
    setZoom(newZoom);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Only drag if clicking background (not buttons)
    if ((e.target as HTMLElement).tagName !== 'BUTTON' && (e.target as HTMLElement).tagName !== 'INPUT') {
      setIsDragging(true);
      setStartPan({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging) {
      setPan({ x: e.clientX - startPan.x, y: e.clientY - startPan.y });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const resetView = () => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  };

  return (
    <div className="flex flex-col h-full relative group" ref={containerRef}>
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center z-20 shadow-sm">
        <div>
          <h3 className="font-bold text-slate-800">High Level Design (HLD)</h3>
          <p className="text-xs text-slate-500 hidden sm:block">
            {isThinking ? "AI is analyzing requirements..." : "Hover nodes • Scroll to Zoom • Drag to Pan"}
          </p>
        </div>

        <div className="flex items-center gap-2 relative">
           <button onClick={handleFetchRefinements} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 border border-indigo-100 px-3 py-1.5 rounded hover:bg-indigo-100 transition-colors mr-2">
             <Sparkles size={14} className={isRefining ? 'animate-spin' : ''} />
             <span className="hidden sm:inline">AI Insights</span>
           </button>

          {/* Local Export Menu (kept for convenience, but parent can also trigger) */}
          <div className="relative">
             <button onClick={() => setShowExportMenu(!showExportMenu)} className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50 transition-colors">
                <Share2 size={14} /> <span className="hidden sm:inline">Export</span>
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-1 w-32 bg-white rounded-lg shadow-xl border border-slate-200 py-1 z-30">
                   <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><ImageIcon size={14} /> PNG Image</button>
                   <button onClick={() => handleExport('svg')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><FileCode size={14} /> SVG Vector</button>
                </div>
             )}
          </div>
          <button onClick={() => setShowMermaid(true)} className="flex items-center gap-2 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700 transition-colors">
            <Code size={14} /> <span className="hidden sm:inline">Mermaid</span>
          </button>
        </div>
      </div>

      <div 
        className="flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px] cursor-move"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >

        {/* Zoom Controls */}
        <div className="absolute bottom-4 left-4 flex flex-col gap-2 z-30">
          <button onClick={() => setZoom(z => Math.min(3, z + 0.2))} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50"><ZoomIn size={16} /></button>
          <button onClick={() => setZoom(z => Math.max(0.5, z - 0.2))} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50"><ZoomOut size={16} /></button>
          <button onClick={resetView} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50"><Maximize size={16} /></button>
        </div>

        {/* UNIFIED GRAPHICS-FRIENDLY COMMAND BAR */}
        {onRefine && !isThinking && aiNodes.length > 0 && (
            <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-lg px-4 z-40">
                <div className="bg-white/90 backdrop-blur-md shadow-2xl rounded-2xl border border-indigo-100 p-2 flex items-center gap-2 animate-fade-in-up ring-1 ring-indigo-200/50">
                    <div className="p-2 bg-indigo-50 rounded-xl text-indigo-500">
                        <MessageSquare size={18} />
                    </div>
                    <input 
                        type="text" 
                        placeholder={refinementPlaceholder}
                        className="flex-1 bg-transparent outline-none text-sm py-2 px-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                        value={refineInput} 
                        onChange={(e) => setRefineInput(e.target.value)} 
                        onKeyDown={(e) => e.key === 'Enter' && submitRefinement()} 
                    />
                    <button 
                        onClick={submitRefinement} 
                        className="bg-indigo-600 hover:bg-indigo-700 text-white p-2.5 rounded-xl transition-all shadow-md shadow-indigo-200 hover:scale-105 active:scale-95"
                    >
                        <Send size={16} />
                    </button>
                </div>
            </div>
        )}

        {/* Gemini Insights Floating Panel */}
        {showInsights && (
           <div className="absolute top-4 left-4 z-20 w-72 bg-white/95 backdrop-blur-md rounded-xl shadow-xl border border-indigo-100 overflow-hidden flex flex-col max-h-[80%] animate-fade-in-up" onMouseDown={(e) => e.stopPropagation()}>
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 p-3 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2"><BrainCircuit size={16} /><span className="font-bold text-sm">Design Analysis</span></div>
                 <button onClick={() => setShowInsights(false)} className="hover:bg-white/20 rounded p-1"><X size={14} /></button>
              </div>
              <div className="p-4 overflow-y-auto flex-1">
                 {isRefining ? (
                    <div className="flex flex-col items-center justify-center py-8 text-center"><Loader size={24} className="text-indigo-500 animate-spin mb-2" /><p className="text-xs text-slate-500 font-medium">Comparing with learned patterns...</p></div>
                 ) : suggestions.length > 0 ? (
                    <div className="space-y-3">
                       {suggestions.map((sug) => (
                          <div key={sug.id} className="bg-indigo-50 border border-indigo-100 rounded-lg p-3">
                             <div className="flex justify-between items-start mb-1"><h5 className="font-bold text-slate-800 text-xs">{sug.title}</h5><span className="text-[9px] uppercase font-bold text-indigo-600 bg-white px-1.5 py-0.5 rounded border border-indigo-100">{sug.impact}</span></div>
                             <p className="text-[10px] text-slate-600 mb-2 leading-relaxed">{sug.description}</p>
                             <button onClick={() => applySuggestion(sug)} className="w-full bg-white text-indigo-600 text-xs font-bold py-1.5 rounded border border-indigo-200 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1"><Zap size={10} /> Apply Optimization</button>
                          </div>
                       ))}
                    </div>
                 ) : (
                    <div className="text-center py-4 text-slate-400 text-xs"><CheckCircle size={24} className="mx-auto mb-2 text-emerald-400" /><p>No major refinements found.</p></div>
                 )}
              </div>
           </div>
        )}

        {/* Hover Tooltip - Positioned fixed relative to container but updated by mouse coordinates */}
        {hoveredNode && (
          <div 
            className="absolute z-50 bg-slate-900 text-white p-3 rounded-lg shadow-xl max-w-xs pointer-events-none animate-fade-in text-xs border border-slate-700"
            style={{ 
              left: `${tooltipPos.x}px`, 
              top: `${tooltipPos.y - 10}px`,
              transform: 'translate(-50%, -100%)'
            }}
          >
             <div className="font-bold mb-1 flex items-center gap-2 border-b border-slate-700 pb-1">
               <Info size={12} className="text-indigo-400" />
               {hoveredNode.label}
             </div>
             <p className="text-slate-300 leading-relaxed">
               {hoveredNode.description || "No technical details available for this node."}
             </p>
          </div>
        )}

        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/95 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm transition-opacity duration-300">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse"><BrainCircuit className="text-white" size={24} /></div>
                   <div><h4 className="font-bold text-slate-800 text-lg">AI Thinking...</h4><p className="text-xs text-slate-500">Model: gemini-3-pro-preview</p></div>
                </div>
                <div className="space-y-3 font-mono text-xs max-h-60 overflow-y-auto">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.3}s`}}><CheckCircle size={14} className="text-emerald-500 flex-shrink-0" /><span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200 shadow-sm">{thought}</span></div>
                   ))}
                </div>
             </div>
          </div>
        )}

        <svg 
            ref={svgRef} 
            width="100%" 
            height="100%" 
            className="w-full h-full select-none"
        >
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>

          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`} style={{ transition: isDragging ? 'none' : 'transform 0.1s ease-out' }}>

            {aiEdges && aiEdges.map((edge, i) => {
              const source = aiNodes.find(n => n.id === edge.from);
              const target = aiNodes.find(n => n.id === edge.to);
              if (!source || !target) return null;
              const sourceX = source.x + 160; 
              const sourceY = source.y + 40;  
              const targetX = target.x;
              const targetY = target.y + 40;
              const controlPointOffset = 60;
              return (
                <g key={i} className="animate-fade-in" style={{animationDelay: '0.5s'}}>
                  <path d={`M ${sourceX} ${sourceY} C ${sourceX + controlPointOffset} ${sourceY}, ${targetX - controlPointOffset} ${targetY}, ${targetX} ${targetY}`} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />
                  <rect x={(sourceX + targetX)/2 - 40} y={(sourceY + targetY)/2 - 10} width="80" height="20" rx="4" fill="white" stroke="#e2e8f0" strokeWidth="1" />
                  <text x={(sourceX + targetX)/2} y={(sourceY + targetY)/2 + 4} textAnchor="middle" fontSize="10" fill="#64748b" fontWeight="600" style={{ fontFamily: 'Inter, sans-serif' }}>{edge.label}</text>
                </g>
              );
            })}

            {aiNodes && aiNodes.map((node, i) => {
              return (
                <foreignObject 
                  x={node.x} y={node.y} width="160" height="80" key={node.id} 
                  className="animate-fade-in-up overflow-visible" 
                  style={{animationDelay: `${i * 0.1}s`}}
                >
                  <div 
                      className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white relative
                      ${node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                        node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                        node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                        'bg-white border-slate-300'}`}
                      onMouseEnter={(e) => {
                        const rect = e.currentTarget.getBoundingClientRect();
                        setTooltipPos({ x: rect.left + rect.width/2, y: rect.top });
                        setHoveredNode(node);
                      }}
                      onMouseLeave={() => setHoveredNode(null)}
                      onMouseDown={(e) => e.stopPropagation()} 
                  >
                      <div className="mb-1">
                        {node.type === 'source' && <Database size={20} className="text-blue-600" />}
                        {node.type === 'stage' && <Server size={20} className="text-slate-600" />}
                        {node.type === 'process' && <Settings size={20} className="text-orange-600 animate-spin-slow" />}
                        {node.type === 'target' && <CloudLightning size={20} className="text-emerald-600" />}
                      </div>
                      <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">{node.label}</span>
                  </div>
                </foreignObject>
              );
            })}
          </g>
        </svg>
      </div>

      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50"><h3 className="font-bold text-slate-800 flex items-center gap-2"><Code size={18} className="text-blue-600" /> Mermaid.js Diagram Code</h3><button onClick={() => setShowMermaid(false)} className="text-slate-400 hover:text-slate-700 transition-colors"><X size={20} /></button></div>
            <div className="flex-1 p-0 overflow-hidden relative group/code"><pre className="w-full h-full p-6 bg-slate-900 text-blue-100 font-mono text-xs overflow-auto">{getMermaidCode()}</pre><button onClick={copyToClipboard} className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg backdrop-blur-md transition-all border border-white/10">{copied ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}</button></div>
            <div className="p-4 border-t border-slate-200 flex justify-end gap-2 bg-slate-50"><button onClick={() => setShowMermaid(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition-colors">Close</button><button onClick={copyToClipboard} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors flex items-center gap-2">{copied ? 'Copied!' : 'Copy Code'}</button></div>
          </div>
        </div>
      )}
    </div>
  );
});

export default ArchitectureCanvas;

import React, { useState, useEffect, useRef } from 'react';
import { Network, Sparkles, Loader, Send, UploadCloud, History, HelpCircle, X, AlertTriangle, Trash2, FileText, Share2, ImageIcon, FileCode, BrainCircuit, Code } from 'lucide-react';
import ArchitectureCanvas from './ArchitectureCanvas';
import { generateArchitectureDesign, analyzeAndLearn, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import { DesignData, ArchitectureCanvasHandle } from '../types';

const StandaloneArchitecture: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [mermaidHints, setMermaidHints] = useState('');
  const [design, setDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);
  const [thoughts, setThoughts] = useState<string[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [isLearning, setIsLearning] = useState(false);

  const canvasRef = useRef<ArchitectureCanvasHandle>(null);

  useEffect(() => {
     setHistoryItems(getHistory('Architecture'));
  }, [design]);

  // Timer Effect
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  const handleGenerate = async (overridePrompt?: string) => {
    let input = overridePrompt || prompt;
    if (!input.trim()) return;

    // Append Mermaid Hints to input context if present
    if (mermaidHints.trim()) {
        input += `\n[Context: The user provided this existing Mermaid code as a reference structure: \n${mermaidHints}\n]`;
    }

    setIsGenerating(true);
    setEta(10); // Estimated 10s
    setError(null);
    setThoughts(['Analyzing requirements...', 'Identifying components...', 'Structuring architecture...']);

    try {
      const result = await generateArchitectureDesign(input, "General Architecture");
      if (result && result.nodes.length > 0) {
        setDesign(result);

        // Trigger learning
        setIsLearning(true);
        const interactionType = overridePrompt ? 'refinement' : 'initial';
        analyzeAndLearn(input, overridePrompt || null, result, ['Architect'], interactionType).finally(() => setIsLearning(false));

        saveHistory('Architecture', input.substring(0, 40) + '...', result, uploadedFiles);
      } else {
        setError("AI could not generate a valid diagram structure. Please add more details to your prompt.");
      }
    } catch (e) {
      console.error(e);
      setError("System error during generation. Please try again.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleRefinement = (newDesign: DesignData) => {
      setDesign(newDesign);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);
      setPrompt(prev => prev + ` [Context from file: ${file.name}]\n(Note: Extract architecture patterns from this file) `);
    }
  };

  const loadHistory = (item: any) => {
     setPrompt(item.summary);
     setDesign(item.data);
     setUploadedFiles(item.files || []);
     setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const triggerExport = (format: 'png' | 'svg') => {
      if (canvasRef.current) {
          canvasRef.current.exportImage(format);
          setShowExportMenu(false);
          // Reinforce learning on export
          setIsLearning(true);
          analyzeAndLearn(prompt, "User Exported Design", design, ['Architect'], 'acceptance').finally(() => setIsLearning(false));
      }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      <div className="bg-white border-b border-slate-200 p-4 shadow-sm z-10 flex justify-between items-center">
        <div>
           <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               <Network className="text-indigo-600"/> Architecture Flow Designer
               {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
           </h2>
           <p className="text-xs text-slate-500">Generate and refine system architecture diagrams using AI.</p>
        </div>
        <div className="flex gap-2">
           <div className="relative">
             <button 
                onClick={() => setShowExportMenu(!showExportMenu)} 
                disabled={design.nodes.length === 0}
                className={`flex items-center gap-2 text-sm font-bold px-4 py-2 rounded-lg transition-colors shadow-sm ${design.nodes.length === 0 ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
             >
                <Share2 size={16} /> Export Solution
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-200 py-2 z-50 animate-fade-in-up">
                   <button onClick={() => triggerExport('png')} className="w-full text-left px-4 py-3 text-sm hover:bg-slate-50 flex items-center gap-3 text-slate-700"><ImageIcon size={16} /> Export as PNG</button>
                   <button onClick={() => triggerExport('svg')} className="w-full text-left px-4 py-3 text-sm hover:bg-slate-50 flex items-center gap-3 text-slate-700"><FileCode size={16} /> Export as SVG</button>
                </div>
             )}
           </div>
           <button onClick={() => setShowHelp(true)} className="flex items-center gap-2 text-sm font-medium text-slate-600 hover:bg-slate-100 px-3 py-2 rounded-lg transition-colors">
              <HelpCircle size={18} /> Help
           </button>
           <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-100'}`}>
              <History size={18} /> History
           </button>
        </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg">
           <AlertTriangle size={16} />
           <span className="text-sm">{error}</span>
           <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-20 right-4 z-50 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3">Recent Designs</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
               {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
               historyItems.map((h, i) => (
                  <button key={i} onClick={() => loadHistory(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                     <div className="truncate font-medium text-slate-700 mb-1">{h.summary}</div>
                     {h.files && h.files.length > 0 && (
                        <div className="flex gap-1">
                            {h.files.map((f: string, idx: number) => (
                                <span key={idx} className="bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded text-[9px] flex items-center gap-0.5 truncate max-w-[80px]">
                                    <FileText size={8}/> {f}
                                </span>
                            ))}
                        </div>
                     )}
                     <div 
