                 aiNodes={design.nodes} 
                 aiEdges={design.edges} 
                 isThinking={isGenerating} 
                 thoughts={thoughts}
                 context={prompt}
                 onApplyRefinement={handleRefinement}
                 onRefine={(p) => {
