export const generateEstimation = async (
    context: string,
    solutionType: string
): Promise<EstimationInputs> => {
    try {
        const prompt = `
            Act as an estimator for ${solutionType}.
            Context: ${context}

            Based on the complexity, provide values for the following drivers (if applicable):
            - di_src, di_map_s, di_map_m, di_map_c, di_task, dq_prof, dq_rule_s, dq_rule_m, dq_rule_c, dg_src, dg_term, dg_pol, mdm_dom, mdm_ing_s, mdm_match

            Return a JSON object where keys are driver IDs and values are numbers.
        `;

         const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: simpleEstimationSchema
            }
        }));

        const parsed = safeJsonParse(response.text, { inputs: [] });
        const inputs: EstimationInputs = {};
        if (parsed.inputs && Array.isArray(parsed.inputs)) {
            parsed.inputs.forEach((item: any) => {
                inputs[item.driverId] = item.value;
            });
        }
        return inputs;
    } catch (e) {
        return {};
    }
};

