import React, { useState, useEffect } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  HelpCircle,
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet
} from 'lucide-react';
import { generateDataQualityRules, generateDQCleanseRules, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule, DQCleanseRule } from '../types';

const StandaloneDataQuality: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'validation' | 'cleanse'>('validation');
  const [isValidationComplete, setIsValidationComplete] = useState(false);

  // Validation State
  const [cdeContext, setCdeContext] = useState('');
  const [validationFile, setValidationFile] = useState<File | null>(null);
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);

  // Cleanse State
  const [cleanseContext, setCleanseContext] = useState('');
  const [profileFile, setProfileFile] = useState<File | null>(null);
  const [cleanseRules, setCleanseRules] = useState<DQCleanseRule[]>([]);

  // Common State
  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isLearning, setIsLearning] = useState(false);

  // Timer Effect
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  const handleValidationFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setValidationFile(e.target.files[0]);
    }
  };

  const handleProfileFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setProfileFile(e.target.files[0]);
    }
  };

  const handleGenerateValidation = async () => {
    if (!cdeContext.trim()) return;
    setIsGenerating(true);
    setEta(3); // Reduced ETA since we are using Flash and expecting extraction
    setError(null);
    try {
      const fullContext = `
        User NLP Requirements: ${cdeContext}
        ${validationFile ? `File Context (Profile/Raw Data): File named "${validationFile.name}". If this is a Profile export, it may contain existing rule logic to extract.` : ''}
      `;

      const rules = await generateDataQualityRules(fullContext, "Informatica Cloud Data Quality");
      setValidationRules(rules);
      setIsValidationComplete(true);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(fullContext, "Generated DQ Validation Rules", rules, ['Data Steward'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate validation rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleGenerateCleanse = async () => {
    if (!profileFile && !cleanseContext.trim()) {
        setError("Please provide either a Profile File or Description.");
        return;
    }
    setIsGenerating(true);
    setEta(12);
    setError(null);
    try {
      const fullContext = `
         Rule Based Profile Input: ${profileFile ? `File "${profileFile.name}"` : "Not provided"}.
         User Cleansing NLP Requirements: ${cleanseContext || "Auto-detect cleansing needs based on profile"}.
      `;
      const rules = await generateDQCleanseRules(fullContext);
      setCleanseRules(rules);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(fullContext, "Generated DQ Cleanse Rules", rules, ['Data Engineer'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate cleanse rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><ShieldCheck size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Data Quality Studio
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Validation & Cleansing Logic Generator (IDQ/CDQ)</p>
            </div>
         </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <X size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-6 md:p-8">
         <div className="max-w-6xl mx-auto space-y-8">

            {/* Step Navigation */}
            <div className="flex gap-4 mb-6">
                <button 
                  onClick={() => setActiveTab('validation')} 
                  className={`flex-1 p-4 rounded-xl border transition-all flex flex-col gap-2 ${activeTab === 'validation' ? 'bg-white border-emerald-500 shadow-md ring-1 ring-emerald-100' : 'bg-slate-100 border-transparent text-slate-500 hover:bg-white hover:border-slate-200'}`}
                >
                  <div className="flex justify-between items-center w-full">
                      <div className="flex items-center gap-2 font-bold text-sm"><CheckCircle size={18} className={activeTab === 'validation' ? 'text-emerald-500' : ''}/> Step 1: Validation Rules</div>
                      {isValidationComplete && <span className="bg-emerald-100 text-emerald-700 text-[10px] px-2 py-0.5 rounded-full font-bold">Completed</span>}
                  </div>
                  <p className="text-xs text-left opacity-80">Define business rules using NLP and Raw Source Data.</p>
                </button>

                <button 
                  onClick={() => isValidationComplete && setActiveTab('cleanse')} 
                  disabled={!isValidationComplete}
                  className={`flex-1 p-4 rounded-xl border transition-all flex flex-col gap-2 ${activeTab === 'cleanse' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-100' : 'bg-slate-100 border-transparent text-slate-400'}`}
                >
                  <div className="flex justify-between items-center w-full">
                      <div className="flex items-center gap-2 font-bold text-sm">
                          {isValidationComplete ? <Wand2 size={18} className={activeTab === 'cleanse' ? 'text-blue-500' : ''}/> : <Lock size={16} />} 
                          Step 2: Cleanse Rules
                      </div>
                  </div>
                  <p className="text-xs text-left opacity-80">Generate transformation logic from Rule Based Profiles.</p>
                </button>
            </div>

            {/* TAB 1: VALIDATION RULES */}
            {activeTab === 'validation' && (
               <div className="animate-fade-in space-y-6">
                  {/* Inputs */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <BrainCircuit size={16} className="text-purple-500"/> 1. Define Rules (NLP)
                        </label>
                        <textarea 
                           className="w-full p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500 outline-none min-h-[140px]"
                           placeholder="Describe your validation needs (e.g. 'Ensure Email has valid format, Order Amount > 0, Shipping Address must be present if Method is Delivery')."
                           value={cdeContext}
                           onChange={(e) => setCdeContext(e.target.value)}
                        />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <Database size={16} className="text-blue-500"/> 2. Raw Source Data / Profile (Optional)
                        </label>
                        {!validationFile ? (
                            <label className="flex flex-col items-center justify-center w-full h-[140px] border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                    <p className="text-sm text-slate-500">Upload Data or Rule Profile</p>
                                    <p className="text-xs text-slate-400 mt-1">(CSV, Excel, JSON)</p>
                                </div>
                                <input type="file" className="hidden" onChange={handleValidationFileUpload} />
                            </label>
                        ) : (
                            <div className="h-[140px] flex items-center justify-center">
                                <div className="flex items-center justify-between p-4 bg-emerald-50 border border-emerald-100 rounded-lg w-full">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-emerald-100 text-emerald-600 rounded"><FileSpreadsheet size={20} /></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">{validationFile.name}</p>
                                            <p className="text-xs text-slate-500">File Context Loaded</p>
                                        </div>
                                    </div>
                                    <button onClick={() => setValidationFile(null)} className="text-slate-400 hover:text-red-500"><X size={18} /></button>
                                </div>
                            </div>
                        )}
                     </div>
                     <div className="lg:col-span-2 flex justify-end">
                        <button 
                           onClick={handleGenerateValidation}
                           disabled={!cdeContext.trim() || isGenerating}
                           className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 shadow-md"
                        >
                           {isGenerating ? <Loader size={18} className="animate-spin" /> : <Sparkles size={18} />}
                           {isGenerating && eta > 0 ? `Analysing Data (${eta}s)` : 'Generate Validation Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area */}
                  {validationRules.length > 0 && (
                     <div className="animate-fade-in-up">
                         <div className="flex justify-between items-center mb-4">
                             <h3 className="font-bold text-slate-800">Generated Validation Rules</h3>
                             {!activeTab.includes('cleanse') && (
                                <button 
                                    onClick={() => setActiveTab('cleanse')} 
                                    className="text-xs flex items-center gap-1 text-blue-600 font-bold hover:underline"
                                >
                                    Next: Define Cleansing Rules <ArrowRight size={12}/>
                                </button>
                             )}
                         </div>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {validationRules.map((rule) => (
                            <div key={rule.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                                <div className="flex justify-between items-start mb-3">
                                    <h4 className="font-bold text-slate-800 text-sm">{rule.name}</h4>
                                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${rule.criticality === 'High' ? 'bg-red-50 text-red-700 border-red-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>{rule.criticality}</span>
                                </div>
                                <p className="text-xs text-slate-600 mb-3">{rule.description}</p>
                                <div className="bg-slate-50 p-2 rounded border border-slate-100">
                                    <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Logic / Expression</p>
                                    <code className="text-xs text-slate-700 font-mono">{rule.logic || "N/A"}</code>
                                </div>
                                <div className="mt-3 pt-3 border-t border-slate-100 flex justify-between items-center">
                                    <span className="text-[10px] text-slate-400">Dimension: {rule.type}</span>
                                </div>
                            </div>
                            ))}
                         </div>
                     </div>
                  )}
               </div>
            )}

            {/* TAB 2: CLEANSE RULES */}
            {activeTab === 'cleanse' && (
               <div className="animate-fade-in space-y-6">
                  {/* Input Area */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <FileText size={16} className="text-orange-500"/> 1. Rule Based Profile (Required)
                        </label>
                        {!profileFile ? (
                            <label className="flex flex-col items-center justify-center w-full h-[140px] border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                    <p className="text-sm text-slate-500">Upload IDQ/CDQ Profile Export</p>
                                    <p className="text-xs text-slate-400 mt-1">(XML, JSON, Excel)</p>
                                </div>
                                <input type="file" className="hidden" onChange={handleProfileFileUpload} />
                            </label>
                        ) : (
                            <div className="h-[140px] flex items-center justify-center">
                                <div className="flex items-center justify-between p-4 bg-blue-50 border border-blue-100 rounded-lg w-full">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-blue-100 text-blue-600 rounded"><FileText size={20} /></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">{profileFile.name}</p>
                                            <p className="text-xs text-slate-500">Profile Ready</p>
                                        </div>
                                    </div>
                                    <button onClick={() => setProfileFile(null)} className="text-slate-400 hover:text-red-500"><X size={18} /></button>
                                </div>
                            </div>
                        )}
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <BrainCircuit size={16} className="text-purple-500"/> 2. Cleansing Instructions (NLP)
                        </label>
                        <textarea 
                           className="w-full p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none min-h-[140px]"
                           placeholder="Refine cleansing logic (e.g., 'Standardize State to 2-char code', 'Parse FullName to First/Last', 'Remove special characters from ID')."
                           value={cleanseContext}
                           onChange={(e) => setCleanseContext(e.target.value)}
                        />
                     </div>
                     <div className="lg:col-span-2 flex justify-end">
                        <button 
                           onClick={handleGenerateCleanse}
                           disabled={(!profileFile && !cleanseContext) || isGenerating}
                           className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
                        >
                           {isGenerating ? <Loader size={18} className="animate-spin" /> : <RefreshCw size={18} />}
                           {isGenerating && eta > 0 ? `Processing Rules (${eta}s)` : 'Generate Cleanse Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area */}
                  {cleanseRules.length > 0 ? (
                     <div className="grid grid-cols-1 gap-4 animate-fade-in-up">
                        {cleanseRules.map((rule) => (
                           <div key={rule.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-shadow">
                              <div className="flex-1">
                                 <div className="flex items-center gap-2 mb-2">
                                    <span className="px-2 py-1 bg-indigo-50 text-indigo-700 text-[10px] font-bold uppercase rounded border border-indigo-100">{rule.transformationType}</span>
                                    <h4 className="font-bold text-slate-800 text-sm">Cleanse: {rule.element}</h4>
                                 </div>
                                 <p className="text-sm text-slate-600 leading-relaxed mb-2">{rule.logic}</p>
                                 <div className="text-xs text-slate-400 flex items-center gap-1"><BrainCircuit size={12}/> Suggested Asset: <span className="font-mono text-slate-600">{rule.informaticaAsset}</span></div>
                              </div>
                           </div>
                        ))}
                     </div>
                  ) : (
                     !isGenerating && (
                        <div className="text-center py-10">
                           <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300">
                              <Lock size={24} />
                           </div>
                           <p className="text-slate-400 text-sm">Cleansing rules are locked until a profile is uploaded.</p>
                        </div>
                     )
                  )}
               </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default StandaloneDataQuality;

export interface RequestData {
  id: string;
  clientName: string;
  product: string; // e.g., 'Informatica', 'Talend', 'Azure'
  deploymentModel: 'Cloud' | 'On-Premise' | 'Hybrid';
  type: string; // The specific tech stack/service
  rfpFiles: string[];
  requirementsPrompt?: string; // New field for natural language input 
  targetAudience: string[]; 
  date: string;
  mode?: 'design' | 'estimator' | 'dq';
  status: 'Not Started' | 'In Progress' | 'Completed';
}

export interface Node {
  id: string;
  label: string;
  description?: string; 
  type: 'source' | 'stage' | 'process' | 'target';
  x: number;
  y: number;
}

export interface Edge {
  from: string;
  to: string;
  label: string;
}

export interface DesignData {
  nodes: Node[];
  edges: Edge[];
}

export interface Question {
  id: string;
  category: string;
  question: string;
  answer: string;
  isCustom?: boolean;
}

export interface Requirement {
  id: string;
  category: 'Infrastructure' | 'Network' | 'Security' | 'License' | 'Development' | 'Testing' | 'Admin';
  item: string;
  description: string;
  criticality: 'High' | 'Medium' | 'Low';
  audience?: string;
}

export interface DataQualityRule {
  id: string;
  element: string; // Grouping key: e.g., "Email", "Phone", "Customer ID"
  name: string; // Human readable name
  informaticaAssetName: string; // Technical name: e.g., "rs_Email_Validity"
  description: string;
  type: 'Completeness' | 'Uniqueness' | 'Validity' | 'Consistency' | 'Accuracy' | 'Timeliness';
  criticality: 'High' | 'Medium' | 'Low';
  logic?: string; // Pseudocode or expression
}

export interface DQCleanseRule {
  id: string;
  element: string;
  transformationType: 'Standardizer' | 'Parser' | 'Labeler' | 'Deduplicate' | 'Merge';
  logic: string;
  informaticaAsset?: string; // Suggested Informatica asset name
}

export interface InitiationItem {
  title: string;
  iconType: string;
  items: string[];
}

export interface ProjectStats {
  executiveSummary: string;
  riskScore: number; // 0-100
  complexityScore: number; // 0-100
  technicalDebt: 'Low' | 'Medium' | 'High';
  keyRisks: string[];
  successProbability: number;
}

export interface RoadmapPhase {
  phase: string;
  duration: string;
  focus: string;
  deliverables: string[];
}

// --- ESTIMATOR TYPES ---
export interface EffortDriver {
  id: string;
  label: string;
  category: 'simple' | 'medium' | 'complex' | 'fixed';
  defaultValue: number;
  multiplier: number; // Hours per unit
  description: string;
}

export interface ModuleConfig {
  id: string;
  title: string;
