            Return a JSON object where keys are driver IDs and values are numbers.
        `;

         const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: simpleEstimationSchema
            }
        }));

        const parsed = safeJsonParse(response.text, { inputs: [] });
        const inputs: EstimationInputs = {};
        if (parsed.inputs && Array.isArray(parsed.inputs)) {
            parsed.inputs.forEach((item: any) => {
                inputs[item.driverId] = item.value;
            });
        }
        return inputs;
    } catch (e) {
        return {};
    }
};

