import { GoogleGenAI, Type, Schema, GenerateContentResponse } from "@google/genai";
import { DesignData, Question, Requirement, RefinementSuggestion, InitiationItem, EstimationInputs, DataQualityRule, AssumptionData, ProjectStats, RoadmapPhase, DQCleanseRule } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- EXPANDED KNOWLEDGE BASE (Injected from User Images) ---
// Persistent Learning Storage
const STORE_KEY = 'accelerator_learned_patterns';
const HISTORY_KEY = 'accelerator_module_history';

const DEFAULT_PATTERNS = [
  "Pattern: For SAP HANA sources, always use Mass Ingestion for initial load to minimize source system impact.",
  "Pattern: GDPR requests require a Masking transformation in the pipeline for PII fields (Email, Phone, SSN).",
  "Pattern: Databricks Medallion Architecture (Bronze->Silver->Gold) is preferred for large-scale data lakes.",
  "Pattern: For Snowflake targets, prioritize 'COPY INTO' or Snowpipe for high-volume ingestion over row-by-row inserts.",
  "Pattern: Government RFPs often require FedRAMP compliance and strict data residency checks.",
  "Pattern: MDM implementations usually require a 'Survivorship Rule' definition phase before technical match/merge configuration.",
  "Pattern: Data Mesh architectures require decentralized domain ownership but centralized policy management (Federated Governance).",
  "Pattern: Real-time fraud detection RFPs usually imply Kafka/Event Hub ingress -> Stream Processing -> NoSQL lookup.",
  // Injected from User Images
  "Pattern: Vehicle Data Integration: SAP S4HANA -> IICS Mass Ingestion -> Landing (Raw) -> Staging (Cleansed) -> MDM SaaS -> Salesforce.",
  "Pattern: Salesforce Extraction: Extract Jobs -> SQL Server Staging (1:1 Sync) -> Stored Proc (Transformation) -> Adobe Blob Storage.",
  "Pattern: MDM Golden Record Flow: Load Landing -> DQ Validation -> DQ Cleansing -> Match & Merge -> Golden Record -> Publish to Downstream.",
  "Pattern: Parallel Processing: Split large entities (e.g., Vehicle, Asset, Warranty) into parallel IICS mappings after common prerequisites are met.",
  "Pattern: Delta Load Logic: Check CDC/Timestamp -> If Delta -> Extract Changed Records -> Upsert to Target; Else -> Full Truncate/Load."
];

let LEARNED_PATTERNS: string[] = [];

// Initialize patterns from local storage if available
try {
  if (typeof window !== 'undefined' && window.localStorage) {
    const stored = localStorage.getItem(STORE_KEY);
    LEARNED_PATTERNS = stored ? JSON.parse(stored) : [...DEFAULT_PATTERNS];
  } else {
    LEARNED_PATTERNS = [...DEFAULT_PATTERNS];
  }
} catch (e) {
  LEARNED_PATTERNS = [...DEFAULT_PATTERNS];
}

// Utility: Safe JSON Parse to prevent app crashes
const safeJsonParse = <T>(text: string | undefined, fallback: T): T => {
  if (!text) return fallback;
  try {
    // Remove markdown code blocks if present (e.g. ```json ... ```)
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanText) as T;
  } catch (e) {
    console.error("JSON Parse Error:", e);
    return fallback;
  }
};

const savePattern = (newPattern: string) => {
   if (!newPattern || newPattern.length < 10) return;

   const isDuplicate = LEARNED_PATTERNS.some(p => 
     p.toLowerCase().includes(newPattern.toLowerCase()) || 
     newPattern.toLowerCase().includes(p.toLowerCase()) ||
     (p.substring(0, 20) === newPattern.substring(0, 20))
   );

   if (!isDuplicate) {
      LEARNED_PATTERNS.push(newPattern);
      if (LEARNED_PATTERNS.length > 50) LEARNED_PATTERNS.shift(); 

      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          localStorage.setItem(STORE_KEY, JSON.stringify(LEARNED_PATTERNS));
        }
      } catch (e) {} 
      console.log("🧠 AI Model Learned New Strategy:", newPattern);
   }
};

// History Management
export const saveHistory = (module: string, summary: string, data: any, files: string[] = []) => {
  try {
    const historyItem = {
      id: Date.now().toString(),
      date: new Date().toLocaleDateString(),
      module,
      summary,
      data,
      files // Add attached files to history
    };
    const existing = localStorage.getItem(HISTORY_KEY);
    const history = existing ? JSON.parse(existing) : [];
    history.unshift(historyItem);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, 30))); // Keep last 30
  } catch (e) {
    console.error("Failed to save history", e);
  }
};

export const getHistory = (module: string) => {
  try {
    const existing = localStorage.getItem(HISTORY_KEY);
    const history = existing ? JSON.parse(existing) : [];
    if (module === 'All') return history;
    return history.filter((h: any) => h.module === module);
  } catch (e) {
    return [];
  }
};

export const deleteHistory = (id: string) => {
    try {
        const existing = localStorage.getItem(HISTORY_KEY);
        if (!existing) return;
        const history = JSON.parse(existing);
        const newHistory = history.filter((h: any) => h.id !== id);
        localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
    } catch (e) {
        console.error("Failed to delete history item", e);
    }
};

// Helper: Retry with Exponential Backoff
const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 3, delay = 2000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    // Check for 503 Service Unavailable, 429 Too Many Requests, or specific error messages
    const isOverloaded = 
      error?.status === 503 || 
      error?.code === 503 || 
      error?.status === 429 || 
      error?.message?.includes('overloaded') ||
      error?.message?.includes('capacity');

    if (retries > 0 && isOverloaded) {
      console.warn(`Gemini API overloaded. Retrying in ${delay}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return retryWithBackoff(fn, retries - 1, delay * 2); // Exponential backoff
    }
    throw error;
  }
};

