export const analyzeAndLearn = async (
  context: string, 
  userPrompt: string | null,
  generatedOutput: any,
  audience: string[] = ['Architect'],
  interactionType: 'initial' | 'refinement' | 'acceptance' = 'initial'
) => {
   // Background learning - fire and forget
   try {
     let taskInstruction = "";
     if (interactionType === 'refinement') {
         taskInstruction = `
            CRITICAL TASK: The user wasn't satisfied with the previous result and provided this refinement: "${userPrompt}".
            Compare this intent against the context. 
            Formulate a specific "Anti-Pattern" or "Correction Pattern" to prevent this mistake in future.
            Example: "Pattern: When context mentions X, avoid Y, instead ensure Z."
         `;
     } else if (interactionType === 'acceptance') {
         taskInstruction = `
            CRITICAL TASK: The user ACCEPTED this result (Design/Estimation/Flow). This is a positive reinforcement.
            Analyze the 'Generated Output' structure (which might be a Graph, a JSON of counts, or a List).
            Extract the most distinct/unique decision made here (e.g. specific tool choice, complexity weighting, or flow pattern) and save it as a "Proven Pattern".
         `;
     } else {
         taskInstruction = `
            Task: Extract a general domain preference or constraint from this initial generation request.
         `;
     }

     const prompt = `
        You are the "Meta-Learning Module" of the Data Management Accelerator.
        Input Context: ${context}
        Interaction Type: ${interactionType}
        User Refinement: ${userPrompt || "N/A"}
        Generated Output Preview: ${JSON.stringify(generatedOutput).substring(0, 1000)}...
        Current Knowledge Base Size: ${LEARNED_PATTERNS.length} patterns.

        ${taskInstruction}

        Output strictly one concise sentence starting with "Pattern:".
     `;

     // Use gemini-2.5-flash for background tasks to avoid overloading pro model
     const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt
     }));

     if (response.text && response.text.trim().startsWith("Pattern:")) {
        savePattern(response.text.trim());
     }
   } catch (e) {
     console.error("Learning cycle failed", e);
   }
};

