export const generateEstimation = async (
    context: string,
    solutionType: string
): Promise<EstimationInputs> => {
    try {
        const prompt = `
            Act as an estimator for ${solutionType}.
            Context: ${context}

            Based on the complexity, provide values for the following drivers (if applicable):
            - di_src, di_map_s, di_map_m, di_map_c, di_task, dq_prof, dq_rule_s, dq_rule_m, dq_rule_c, dg_src, dg_term, dg_pol, mdm_dom, mdm_ing_s, mdm_match

            Return a JSON object where keys are driver IDs and values are numbers.
        `;

         const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: simpleEstimationSchema
            }
        }));

        const parsed = safeJsonParse(response.text, { inputs: [] });
        const inputs: EstimationInputs = {};
        if (parsed.inputs && Array.isArray(parsed.inputs)) {
            parsed.inputs.forEach((item: any) => {
                inputs[item.driverId] = item.value;
            });
        }
        return inputs;
    } catch (e) {
        return {};
    }
};

export const generateDataQualityRules = async (
    context: string,
    solutionType: string
): Promise<DataQualityRule[]> => {
    try {
        const prompt = `
            Act as a Data Steward/Developer using Informatica CDQ.

            TASK: 
            Analyze input to identify Critical Data Elements (CDEs) and generate dimension-wise rules.

            STRATEGY (Learned from User Profiles):
            1. NAMING CONVENTION: Use 'rs_<Element>_<Dimension>' (e.g. rs_Email_Validity, rs_City_Accuracy) or 'Rule_<Element>_<Dimension>' (e.g. Rule_Title_Completeness).
            2. STRUCTURE: Group rules by the Business Element (e.g., 'Email', 'Phone', 'Address').
            3. LOGIC: Mimic standard IDQ logic. **Specifically scan for Accuracy Rules**: If data involves IDs (National ID, Email, Phone) or specific codes, generate specific Regex or Reference Table lookup rules (e.g., "Check dictionary d_Country_ISO", "Match Regex ^[A-Z]{2}"). Label these as 'Accuracy'.

            INPUT CONTEXT: ${context}
            SOLUTION: ${solutionType}

            INSTRUCTIONS:
            - If input contains existing rules (JSON export pattern), EXTRACT them mapped to this schema.
            - If input is just NLP ("Check email"), GENERATE rules for Validity, Accuracy, Completeness, etc.
            - populate 'element' with the CDE name.
            - populate 'informaticaAssetName' with the technical rule name.
        `;

         const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: dqRulesSchema
            }
        }));

        return safeJsonParse(response.text, []);
    } catch (e) {
        return [];
    }
};

