                                >
                                    <Trash2 size={18} />
                                </button>
                            </div>
                        </td>
                    </tr>
                   ))
                )}
                </tbody>
              </table>
          </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-indigo-500" /> Design Module Help</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>Overview:</strong> The Design Hub is your central command for managing solution architecture requests.</p>
                    <p><strong>How to use:</strong></p>
                    <ul className="list-disc pl-5 space-y-2">
                       <li>Click <strong>New Request</strong> to start a new AI-driven design session.</li>
                       <li>Select an existing request to resume design, view estimations, or refine architecture.</li>
                       <li>Use the search bar to filter by client name or technology.</li>
                    </ul>
                 </div>
              </div>
           </div>
        )}
    </div>
  );
};

