// Helper to aggregate services for HTC Solution
const aggregateServices = (deployment: 'Cloud' | 'On-Premise') => {
  const allServices: string[] = [];
  Object.values(BASE_CATALOG).forEach((prod: any) => {
    if (prod[deployment]) {
      allServices.push(...prod[deployment]);
    }
  });
  return Array.from(new Set(allServices)).sort();
};

const PRODUCT_CATALOG = {
  ...BASE_CATALOG,
  "HTC Enterprise Data Management": {
    "Cloud": aggregateServices("Cloud"),
    "On-Premise": aggregateServices("On-Premise")
  }
};

const CreateForm: React.FC<CreateFormProps> = ({ onSubmit, onCancel, userProfile }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpFiles: [] as string[],
    requirementsPrompt: '',
    product: '',
    deploymentModel: 'Cloud' as 'Cloud' | 'On-Premise',
    solutionType: '',
    targetAudience: ['Developer'] as string[], 
    description: '',
    priority: 'Normal'
  });

  const [inputType, setInputType] = useState<'upload' | 'prompt'>('upload');
  const [step, setStep] = useState<'input' | 'analyzing' | 'recommendation'>('input');
  const [isDragging, setIsDragging] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiSuggestion | null>(null);

  // Dynamic Options based on selection
  const [availableProducts] = useState<string[]>(Object.keys(PRODUCT_CATALOG).sort());
  const [availableDeployments, setAvailableDeployments] = useState<string[]>(['Cloud', 'On-Premise']);
  const [availableServices, setAvailableServices] = useState<string[]>([]);

  // Apply User Profile Defaults
  useEffect(() => {
    if (userProfile && userProfile.preferences) {
        setFormData(prev => ({
            ...prev,
            product: prev.product || userProfile.preferences.defaultProduct || '',
            deploymentModel: (userProfile.preferences.defaultDeployment !== 'Hybrid' ? userProfile.preferences.defaultDeployment : 'Cloud') as any
        }));
    }
  }, [userProfile]);

  // Effect to update Deployment and Services based on Product selection
  useEffect(() => {
    if (formData.product && PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG]) {
      const productConfig = PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG];
      const validDeployments = Object.keys(productConfig).filter(k => productConfig[k].length > 0);
      setAvailableDeployments(validDeployments);

      // Reset deployment if current selection is invalid for new product
      if (!validDeployments.includes(formData.deploymentModel)) {
        setFormData(prev => ({ ...prev, deploymentModel: validDeployments[0] as any }));
      }
    } else {
      setAvailableDeployments([]);
      setAvailableServices([]);
    }
  }, [formData.product]);

  // Effect to update Services based on Deployment selection
  useEffect(() => {
    if (formData.product && formData.deploymentModel && PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG]) {
      const services = PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG][formData.deploymentModel] || [];
      setAvailableServices(services);

      // Reset solution type if invalid
      if (!services.includes(formData.solutionType)) {
        setFormData(prev => ({ ...prev, solutionType: '' }));
      }
    }
  }, [formData.product, formData.deploymentModel]);

  const roles = [
    { id: 'Developer', label: 'Developer', icon: Code2, desc: 'Technical specs & mappings' },
    { id: 'Tester', label: 'Tester', icon: Beaker, desc: 'Test data & validation' },
    { id: 'Admin', label: 'Admin', icon: ShieldAlert, desc: 'Security & Infrastructure' }
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const toggleRole = (roleId: string) => {
    setFormData(prev => {
      const current = prev.targetAudience;
      if (current.includes(roleId)) {
        if (current.length === 1) return prev; 
        return { ...prev, targetAudience: current.filter(r => r !== roleId) };
      } else {
        return { ...prev, targetAudience: [...current, roleId] };
      }
    });
  };

  const handleDeploymentChange = (model: 'Cloud' | 'On-Premise') => {
    setFormData(prev => ({ ...prev, deploymentModel: model }));
  };

  const processFiles = (files: FileList) => {
    const newFileNames = Array.from(files).map(f => f.name);
    setFormData(prev => {
      const combined = [...prev.rfpFiles, ...newFileNames];
      return { ...prev, rfpFiles: combined.slice(0, 5) };
    });
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files) processFiles(e.dataTransfer.files);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) processFiles(e.target.files);
  };

  const removeFile = (fileName: string) => {
    setFormData(prev => ({ ...prev, rfpFiles: prev.rfpFiles.filter(f => f !== fileName) }));
  };

  const handleAnalyze = () => {
    setStep('analyzing');
    setTimeout(() => {
      const combinedNames = formData.rfpFiles.join(' ').toLowerCase();
      const promptText = formData.requirementsPrompt.toLowerCase();

      // Inject User Preference into Analysis Context
      let userPrefContext = "";
      if (userProfile && userProfile.preferences.defaultProduct) {
          userPrefContext = ` [USER PREFERENCE CONTEXT: The user prefers '${userProfile.preferences.defaultProduct}' and '${userProfile.preferences.defaultDeployment}' deployment. Prioritize these unless requirements strictly contradict.]`;
      }

      const combinedContext = combinedNames + " " + promptText + userPrefContext;

      let suggestion: AiSuggestion | null = null;

      // Smart Product Detection Simulation with expanded patterns
      // Note: In a real implementation, we would send 'combinedContext' to the AI service.
      // Here we simulate the AI's "preference awareness".

      if (userProfile?.preferences.defaultProduct && !combinedContext.includes('azure') && !combinedContext.includes('aws') && !combinedContext.includes('talend')) {
          // If no specific tech mentioned in requirements, fallback to preference
          const pref = userProfile.preferences.defaultProduct;
          suggestion = {
            product: pref,
            deployment: userProfile.preferences.defaultDeployment === 'Hybrid' ? 'Cloud' : userProfile.preferences.defaultDeployment,
            type: "Recommended Platform",
            reason: `Requirements align with your preferred stack: ${pref}.`,
            details: ["Aligned with User Profile.", "Standard Reference Architecture."]
          };
      } else if (combinedContext.includes('azure') || combinedContext.includes('factory') || combinedContext.includes('synapse')) {
         suggestion = {
            product: 'Azure Data Factory',
            deployment: 'Cloud',
            type: "Data Factory V2",
            reason: "Detected Azure ecosystem terms (ADF, Synapse) in input.",
            details: ["Source: Azure Blob.", "Target: Synapse Analytics."]
         };
      } else if (combinedContext.includes('talend') || combinedContext.includes('studio') || combinedContext.includes('fabric')) {
         suggestion = {
            product: 'Talend',
            deployment: 'Cloud',
            type: "Talend Cloud Data Integration",
            reason: "Detected Talend Data Fabric terminology.",
            details: ["Pattern: Remote Engine.", "Transformation: TMC/Pipeline Designer."]
         };
      } else if (combinedContext.includes('databricks') || combinedContext.includes('delta') || combinedContext.includes('medallion')) {
         suggestion = {
            product: 'Databricks',
            deployment: 'Cloud',
            type: "Unity Catalog",
            reason: "Detected Databricks Lakehouse & Medallion Architecture terms.",
            details: ["Pattern: Bronze/Silver/Gold Layers.", "Governance: Unity Catalog."]
         };
      } else if (combinedContext.includes('profisee') || combinedContext.includes('golden record')) {
         suggestion = {
            product: 'Profisee',
            deployment: 'Cloud',
            type: "Profisee MDM SaaS",
            reason: "Detected Golden Record management requirements typical of Profisee MDM.",
            details: ["Pattern: Match & Merge.", "Governance: Stewardship Portal."]
         };
      } else if (combinedContext.includes('mainframe') || combinedContext.includes('cobol')) {
         suggestion = {
            product: 'Informatica',
            deployment: 'On-Premise',
            type: "PowerCenter",
            reason: "Detected Legacy Mainframe sources requiring robust on-prem connectivity.",
            details: ["Source: Cobol Copybook.", "Security: Data Residency/On-Prem Agent."]
         };
      } else if (combinedContext.includes('privacy') || combinedContext.includes('discovery') || combinedContext.includes('bigid')) {
         suggestion = {
            product: 'BigID',
            deployment: 'Cloud',
            type: "BigID Data Discovery",
            reason: "Detected Privacy/PII scanning requirements.",
            details: ["Focus: Sensitive Data Discovery.", "Integration: Connector Framework."]
         };
      } else {
         suggestion = {
            product: 'Informatica',
            deployment: 'Cloud',
            type: "Cloud Data Integration (CDI)",
            reason: "Standard Enterprise Cloud Modernization pattern detected.",
            details: ["Target: Cloud Data Warehouse.", "Pattern: ELT/ETL Modernization."]
         };
      }
      setAiSuggestion(suggestion);
      setStep('recommendation');
    }, 2500);
  };

  const acceptRecommendation = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        product: aiSuggestion.product,
        deploymentModel: aiSuggestion.deployment as any,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Inject user preference into prompt for downstream consumption if not already explicitly stated
    let refinedPrompt = formData.requirementsPrompt;
    if (userProfile && !refinedPrompt.toLowerCase().includes('prefer')) {
        refinedPrompt += `\n[System Note: User Preference is ${userProfile.preferences.defaultProduct} on ${userProfile.preferences.defaultDeployment}. Consider this in design generation.]`;
    }

    onSubmit({
      clientName: formData.clientName,
      product: formData.product,
      deploymentModel: formData.deploymentModel,
      type: formData.solutionType,
      rfpFiles: formData.rfpFiles,
      requirementsPrompt: refinedPrompt,
      targetAudience: formData.targetAudience,
      date: new Date().toLocaleDateString(),
      mode: 'design'
    });
  };

  const isFormValid = () => {
    const hasInput = inputType === 'upload' ? formData.rfpFiles.length > 0 : formData.requirementsPrompt.length > 20;
    return formData.clientName && hasInput;
  };

  return (
    <div className="p-6 md:p-8 max-w-6xl mx-auto animate-fade-in h-full flex flex-col">
      <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">
             New Solution Request
