import React, { useState, useEffect } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  HelpCircle,
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet,
  LayoutGrid,
  BarChart2,
  List
} from 'lucide-react';
import { generateDataQualityRules, generateDQCleanseRules, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule, DQCleanseRule } from '../types';

interface GroupedRules {
  [element: string]: DataQualityRule[];
}

const StandaloneDataQuality: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'validation' | 'cleanse'>('validation');
  const [isValidationComplete, setIsValidationComplete] = useState(false);

  // Validation State
  const [cdeContext, setCdeContext] = useState('');
  const [validationFile, setValidationFile] = useState<File | null>(null);
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);
  const [groupedRules, setGroupedRules] = useState<GroupedRules>({});
  const [selectedElement, setSelectedElement] = useState<string | null>(null);

  // Cleanse State
  const [cleanseContext, setCleanseContext] = useState('');
  const [profileFile, setProfileFile] = useState<File | null>(null);
  const [cleanseRules, setCleanseRules] = useState<DQCleanseRule[]>([]);

  // Common State
  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isLearning, setIsLearning] = useState(false);

  // Timer Effect
  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // Group Rules logic
  useEffect(() => {
    if (validationRules.length > 0) {
        const grouped: GroupedRules = {};
        validationRules.forEach(rule => {
            const key = rule.element || "General";
            if (!grouped[key]) grouped[key] = [];
            grouped[key].push(rule);
        });
        setGroupedRules(grouped);
    }
  }, [validationRules]);

  const handleValidationFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setValidationFile(e.target.files[0]);
    }
  };

  const handleProfileFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setProfileFile(e.target.files[0]);
    }
  };

  const handleGenerateValidation = async () => {
    if (!cdeContext.trim()) return;
    setIsGenerating(true);
    setEta(3); // Reduced ETA since we are using Flash and expecting extraction
    setError(null);
    try {
      const fullContext = `
        User NLP Requirements: ${cdeContext}
        ${validationFile ? `File Context (Profile/Raw Data): File named "${validationFile.name}". If this is a Profile export (JSON), EXTRACT existing rules matching 'RULE_SPECIFICATION' pattern.` : ''}
      `;

      const rules = await generateDataQualityRules(fullContext, "Informatica Cloud Data Quality");
      setValidationRules(rules);
      setIsValidationComplete(true);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(fullContext, "Generated DQ Validation Rules", rules, ['Data Steward'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate validation rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleGenerateCleanse = async () => {
    if (!profileFile && !cleanseContext.trim()) {
        setError("Please provide either a Profile File or Description.");
        return;
    }
    setIsGenerating(true);
    setEta(12);
    setError(null);
    try {
      const fullContext = `
         Rule Based Profile Input: ${profileFile ? `File "${profileFile.name}"` : "Not provided"}.
         User Cleansing NLP Requirements: ${cleanseContext || "Auto-detect cleansing needs based on profile"}.
      `;
      const rules = await generateDQCleanseRules(fullContext);
      setCleanseRules(rules);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(fullContext, "Generated DQ Cleanse Rules", rules, ['Data Engineer'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate cleanse rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const getDimensionStats = (rules: DataQualityRule[]) => {
      const stats: Record<string, number> = {};
      rules.forEach(r => {
          stats[r.type] = (stats[r.type] || 0) + 1;
      });
      return stats;
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><ShieldCheck size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Data Quality Studio
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Validation & Cleansing Logic Generator (IDQ/CDQ)</p>
            </div>
         </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <X size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {/* Drill-down Sidebar */}
      {selectedElement && groupedRules[selectedElement] && (
          <div className="absolute top-0 right-0 h-full w-96 bg-white shadow-2xl z-40 border-l border-slate-200 flex flex-col animate-fade-in-up">
              <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <div>
                      <h3 className="font-bold text-slate-800">{selectedElement}</h3>
                      <p className="text-xs text-slate-500">{groupedRules[selectedElement].length} Rules Defined</p>
                  </div>
                  <button onClick={() => setSelectedElement(null)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={18}/></button>
              </div>
              <div className="p-4 flex-1 overflow-y-auto">
                  <div className="mb-6">
                      <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Coverage Statistics</h4>
                      <div className="space-y-2">
                          {Object.entries(getDimensionStats(groupedRules[selectedElement] as DataQualityRule[])).map(([dim, count]) => (
                              <div key={dim} className="flex items-center justify-between text-sm">
                                  <span className="text-slate-600 font-medium">{dim}</span>
                                  <div className="flex items-center gap-2">
                                      <div className="w-24 h-2 bg-slate-100 rounded-full overflow-hidden">
                                          <div className="h-full bg-emerald-500" style={{width: `${(count / (groupedRules[selectedElement] as DataQualityRule[]).length) * 100}%`}}></div>
                                      </div>
                                      <span className="text-slate-800 font-bold">{count}</span>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>

                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Rule Specifications</h4>
                  <div className="space-y-3">
                      {(groupedRules[selectedElement] as DataQualityRule[]).map((rule, idx) => (
                          <div key={idx} className="p-3 border border-slate-100 rounded-lg bg-white shadow-sm">
                              <div className="flex justify-between items-start mb-1">
                                  <span className="text-xs font-mono font-bold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded break-all">{rule.informaticaAssetName}</span>
                                  <span className={`text-[9px] uppercase font-bold px-1.5 py-0.5 rounded border ${rule.criticality === 'High' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-blue-50 text-blue-600 border-blue-100'}`}>{rule.criticality}</span>
                              </div>
                              <p className="text-xs text-slate-600 mt-2 line-clamp-3">{rule.description}</p>
                              {rule.logic && (
                                <div className="mt-2 pt-2 border-t border-slate-50">
                                    <p className="text-[10px] text-slate-400 font-mono">{rule.logic}</p>
                                </div>
                              )}
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      <div className="flex-1 overflow-y-auto p-6 md:p-8">
         <div className="max-w-6xl mx-auto space-y-8">

            {/* Step Navigation */}
            <div className="flex gap-4 mb-6">
                <button 
                  onClick={() => setActiveTab('validation')} 
                  className={`flex-1 p-4 rounded-xl border transition-all flex flex-col gap-2 ${activeTab === 'validation' ? 'bg-white border-emerald-500 shadow-md ring-1 ring-emerald-100' : 'bg-slate-100 border-transparent text-slate-500 hover:bg-white hover:border-slate-200'}`}
                >
                  <div className="flex justify-between items-center w-full">
                      <div className="flex items-center gap-2 font-bold text-sm"><CheckCircle size={18} className={activeTab === 'validation' ? 'text-emerald-500' : ''}/> Step 1: Validation Rules</div>
                      {isValidationComplete && <span className="bg-emerald-100 text-emerald-700 text-[10px] px-2 py-0.5 rounded-full font-bold">Completed</span>}
                  </div>
                  <p className="text-xs text-left opacity-80">Define business rules using NLP and Raw Source Data.</p>
                </button>

                <button 
                  onClick={() => isValidationComplete && setActiveTab('cleanse')} 
                  disabled={!isValidationComplete}
                  className={`flex-1 p-4 rounded-xl border transition-all flex flex-col gap-2 ${activeTab === 'cleanse' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-100' : 'bg-slate-100 border-transparent text-slate-400'}`}
                >
                  <div className="flex justify-between items-center w-full">
                      <div className="flex items-center gap-2 font-bold text-sm">
                          {isValidationComplete ? <Wand2 size={18} className={activeTab === 'cleanse' ? 'text-blue-500' : ''}/> : <Lock size={16} />} 
                          Step 2: Cleanse Rules
                      </div>
                  </div>
                  <p className="text-xs text-left opacity-80">Generate transformation logic from Rule Based Profiles.</p>
                </button>
            </div>

            {/* TAB 1: VALIDATION RULES */}
            {activeTab === 'validation' && (
               <div className="animate-fade-in space-y-6">
                  {/* Inputs */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <BrainCircuit size={16} className="text-purple-500"/> 1. Define Rules (NLP)
                        </label>
                        <textarea 
                           className="w-full p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500 outline-none min-h-[140px]"
                           placeholder="Describe your validation needs (e.g. 'Ensure Email has valid format, Order Amount > 0, Shipping Address must be present if Method is Delivery')."
                           value={cdeContext}
                           onChange={(e) => setCdeContext(e.target.value)}
                        />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <Database size={16} className="text-blue-500"/> 2. Raw Source Data / Profile (Optional)
                        </label>
                        {!validationFile ? (
                            <label className="flex flex-col items-center justify-center w-full h-[140px] border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                    <p className="text-sm text-slate-500">Upload Data or Rule Profile</p>
                                    <p className="text-xs text-slate-400 mt-1">(CSV, Excel, JSON)</p>
                                </div>
                                <input type="file" className="hidden" onChange={handleValidationFileUpload} />
                            </label>
                        ) : (
                            <div className="h-[140px] flex items-center justify-center">
                                <div className="flex items-center justify-between p-4 bg-emerald-50 border border-emerald-100 rounded-lg w-full">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-emerald-100 text-emerald-600 rounded"><FileSpreadsheet size={20} /></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">{validationFile.name}</p>
                                            <p className="text-xs text-slate-500">File Context Loaded</p>
                                        </div>
                                    </div>
                                    <button onClick={() => setValidationFile(null)} className="text-slate-400 hover:text-red-500"><X size={18} /></button>
                                </div>
                            </div>
                        )}
                     </div>
                     <div className="lg:col-span-2 flex justify-end">
                        <button 
                           onClick={handleGenerateValidation}
                           disabled={!cdeContext.trim() || isGenerating}
                           className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 shadow-md"
                        >
                           {isGenerating ? <Loader size={18} className="animate-spin" /> : <Sparkles size={18} />}
                           {isGenerating && eta > 0 ? `Analysing Data (${eta}s)` : 'Generate Validation Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area - CRITICAL DATA ELEMENTS GRID */}
                  {validationRules.length > 0 && (
                     <div className="animate-fade-in-up">
                         <div className="flex justify-between items-center mb-4">
                             <h3 className="font-bold text-slate-800 flex items-center gap-2"><LayoutGrid size={18} className="text-indigo-500"/> Critical Data Elements ({Object.keys(groupedRules).length})</h3>
                             {!activeTab.includes('cleanse') && (
                                <button 
                                    onClick={() => setActiveTab('cleanse')} 
                                    className="text-xs flex items-center gap-1 text-blue-600 font-bold hover:underline"
                                >
                                    Next: Define Cleansing Rules <ArrowRight size={12}/>
                                </button>
                             )}
                         </div>

                         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {Object.entries(groupedRules).map(([element, rules]) => {
                                const stats = getDimensionStats(rules);
                                return (
                                    <button 
                                        key={element} 
                                        onClick={() => setSelectedElement(element)}
                                        className={`text-left bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-lg transition-all group relative overflow-hidden ${selectedElement === element ? 'ring-2 ring-indigo-500' : ''}`}
                                    >
                                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Database size={64}/></div>
                                        <div className="relative z-10">
                                            <h4 className="text-lg font-bold text-slate-800 mb-1">{element}</h4>
                                            <p className="text-xs text-slate-500 mb-4">{rules.length} Rules Defined</p>

                                            <div className="flex flex-wrap gap-2">
                                                {Object.entries(stats).slice(0, 3).map(([dim, count]) => (
                                                    <span key={dim} className="px-2 py-1 bg-slate-50 border border-slate-100 rounded-md text-[10px] font-bold text-slate-600 flex items-center gap-1">
                                                        {dim} <span className="bg-slate-200 px-1.5 rounded-full text-slate-700">{count}</span>
                                                    </span>
                                                ))}
                                                {Object.keys(stats).length > 3 && <span className="px-2 py-1 bg-slate-50 text-[10px] text-slate-400">+{Object.keys(stats).length - 3} more</span>}
                                            </div>
                                        </div>
                                        <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500 transform scale-x-0 group-hover:scale-x-100 transition-transform origin-left"></div>
                                    </button>
                                );
                            })}
                         </div>
                         <p className="text-center text-xs text-slate-400 mt-6 flex items-center justify-center gap-2"><ArrowRight size={14}/> Click on a card to view dimension-wise statistics and rule specifications.</p>
                     </div>
                  )}
               </div>
            )}

            {/* TAB 2: CLEANSE RULES */}
            {activeTab === 'cleanse' && (
               <div className="animate-fade-in space-y-6">
                  {/* Input Area */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <FileText size={16} className="text-orange-500"/> 1. Rule Based Profile (Required)
                        </label>
                        {!profileFile ? (
                            <label className="flex flex-col items-center justify-center w-full h-[140px] border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                    <p className="text-sm text-slate-500">Upload IDQ/CDQ Profile Export</p>
                                    <p className="text-xs text-slate-400 mt-1">(XML, JSON, Excel)</p>
                                </div>
                                <input type="file" className="hidden" onChange={handleProfileFileUpload} />
                            </label>
                        ) : (
                            <div className="h-[140px] flex items-center justify-center">
                                <div className="flex items-center justify-between p-4 bg-blue-50 border border-blue-100 rounded-lg w-full">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-blue-100 text-blue-600 rounded"><FileText size={20} /></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">{profileFile.name}</p>
                                            <p className="text-xs text-slate-500">Profile Ready</p>
                                        </div>
                                    </div>
                                    <button onClick={() => setProfileFile(null)} className="text-slate-400 hover:text-red-500"><X size={18} /></button>
                                </div>
                            </div>
                        )}
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <BrainCircuit size={16} className="text-purple-500"/> 2. Cleansing Instructions (NLP)
                        </label>
                        <textarea 
                           className="w-full p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none min-h-[140px]"
                           placeholder="Refine cleansing logic (e.g., 'Standardize State to 2-char code', 'Parse FullName to First/Last', 'Remove special characters from ID')."
                           value={cleanseContext}
                           onChange={(e) => setCleanseContext(e.target.value)}
                        />
                     </div>
                     <div className="lg:col-span-2 flex justify-end">
                        <button 
                           onClick={handleGenerateCleanse}
                           disabled={(!profileFile && !cleanseContext) || isGenerating}
                           className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
                        >
                           {isGenerating ? <Loader size={18} className="animate-spin" /> : <RefreshCw size={18} />}
                           {isGenerating && eta > 0 ? `Processing Rules (${eta}s)` : 'Generate Cleanse Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area */}
                  {cleanseRules.length > 0 ? (
                     <div className="grid grid-cols-1 gap-4 animate-fade-in-up">
                        {cleanseRules.map((rule) => (
                           <div key={rule.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-shadow">
                              <div className="flex-1">
                                 <div className="flex items-center gap-2 mb-2">
                                    <span className="px-2 py-1 bg-indigo-50 text-indigo-700 text-[10px] font-bold uppercase rounded border border-indigo-100">{rule.transformationType}</span>
                                    <h4 className="font-bold text-slate-800 text-sm">Cleanse: {rule.element}</h4>
                                 </div>
                                 <p className="text-sm text-slate-600 leading-relaxed mb-2">{rule.logic}</p>
                                 <div className="text-xs text-slate-400 flex items-center gap-1"><BrainCircuit size={12}/> Suggested Asset: <span className="font-mono text-slate-600">{rule.informaticaAsset}</span></div>
                              </div>
                           </div>
                        ))}
                     </div>
                  ) : (
                     !isGenerating && (
                        <div className="text-center py-10">
                           <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300">
                              <Lock size={24} />
                           </div>
                           <p className="text-slate-400 text-sm">Cleansing rules are locked until a profile is uploaded.</p>
                        </div>
                     )
                  )}
               </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default StandaloneDataQuality;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Table, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  History, 
  HelpCircle, 
  X, 
  AlertTriangle, 
  Trash2, 
  FileText, 
  Share2, 
  ImageIcon, 
  FileCode, 
  BrainCircuit, 
  Code,
  Database
} from 'lucide-react';
import ArchitectureCanvas from './ArchitectureCanvas';
import { generateERD, analyzeAndLearn, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import { DesignData, ArchitectureCanvasHandle } from '../types';

const StandaloneERDiagram: React.FC = () => {
  const [ddlInput, setDdlInput] = useState('');
  const [logicInput, setLogicInput] = useState('');
  const [design, setDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);
  const [thoughts, setThoughts] = useState<string[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [isLearning, setIsLearning] = useState(false);

  const canvasRef = useRef<ArchitectureCanvasHandle>(null);

  useEffect(() => {
     setHistoryItems(getHistory('ERDiagram'));
  }, [design]);

  // Timer Effect
  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  const handleGenerate = async (overridePrompt?: string) => {
    const context = ddlInput;
    const userPrompt = overridePrompt || logicInput;

    if (!context.trim() && !userPrompt.trim()) return;

    setIsGenerating(true);
    setEta(12); // Estimated 12s
    setError(null);
    setThoughts(['Parsing DDL structure...', 'Identifying Primary & Foreign Keys...', 'Resolving Relationships...', 'Generating Entity Model...']);

    try {
      const result = await generateERD(context, userPrompt);
      if (result && result.nodes.length > 0) {
        setDesign(result);

        // Trigger learning
        setIsLearning(true);
        const interactionType = overridePrompt ? 'refinement' : 'initial';
        analyzeAndLearn(context + "\n" + userPrompt, overridePrompt || null, result, ['Database Architect'], interactionType).finally(() => setIsLearning(false));

        saveHistory('ERDiagram', `ERD: ${userPrompt.substring(0, 30)}...`, result, uploadedFiles);
      } else {
        setError("AI could not generate a valid ERD. Please ensure your DDL or description is clear.");
      }
    } catch (e) {
      console.error(e);
      setError("System error during generation. Please try again.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleRefinement = (newDesign: DesignData) => {
      setDesign(newDesign);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);
      // If it's a .sql file, maybe load content directly? For now, simulate context.
      setDdlInput(prev => prev + `\n[Attached File: ${file.name} - contains DDL/Schema]\n`);
    }
  };

  const loadHistory = (item: any) => {
     // We store the prompt in summary usually, but here we might need better reconstruction
     // For simplicity, we just load the diagram
     setLogicInput(item.summary);
     setDesign(item.data);
     setUploadedFiles(item.files || []);
     setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const triggerExport = (format: 'png' | 'svg') => {
      if (canvasRef.current) {
          canvasRef.current.exportImage(format);
          setShowExportMenu(false);
          // Reinforce learning on export
          setIsLearning(true);
          analyzeAndLearn(ddlInput, "User Exported ERD", design, ['Database Architect'], 'acceptance').finally(() => setIsLearning(false));
      }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      <div className="bg-white border-b border-slate-200 p-4 shadow-sm z-10 flex justify-between items-center">
        <div>
           <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               <Table className="text-purple-600"/> ER Diagram Generator
               {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
           </h2>
           <p className="text-xs text-slate-500">Generate Entity-Relationship Diagrams from SQL DDL and NLP.</p>
        </div>
        <div className="flex gap-2">
           <div className="relative">
             <button 
                onClick={() => setShowExportMenu(!showExportMenu)} 
                disabled={design.nodes.length === 0}
                className={`flex items-center gap-2 text-sm font-bold px-4 py-2 rounded-lg transition-colors shadow-sm ${design.nodes.length === 0 ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-purple-600 text-white hover:bg-purple-700'}`}
             >
                <Share2 size={16} /> Export Solution
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-200 py-2 z-50 animate-fade-in-up">
                   <button onClick={() => triggerExport('png')} className="w-full text-left px-4 py-3 text-sm hover:bg-slate-50 flex items-center gap-3 text-slate-700"><ImageIcon size={16} /> Export as PNG</button>
                   <button onClick={() => triggerExport('svg')} className="w-full text-left px-4 py-3 text-sm hover:bg-slate-50 flex items-center gap-3 text-slate-700"><FileCode size={16} /> Export as SVG</button>
                </div>
             )}
           </div>
           <button onClick={() => setShowHelp(true)} className="flex items-center gap-2 text-sm font-medium text-slate-600 hover:bg-slate-100 px-3 py-2 rounded-lg transition-colors">
              <HelpCircle size={18} /> Help
           </button>
           <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-purple-50 text-purple-600' : 'text-slate-600 hover:bg-slate-100'}`}>
              <History size={18} /> History
           </button>
        </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg">
           <AlertTriangle size={16} />
           <span className="text-sm">{error}</span>
           <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-20 right-4 z-50 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3">Recent Models</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
               {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
               historyItems.map((h, i) => (
                  <button key={i} onClick={() => loadHistory(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                     <div className="truncate font-medium text-slate-700 mb-1">{h.summary}</div>
                     {h.files && h.files.length > 0 && (
                        <div className="flex gap-1">
                            {h.files.map((f: string, idx: number) => (
                                <span key={idx} className="bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded text-[9px] flex items-center gap-0.5 truncate max-w-[80px]">
                                    <FileText size={8}/> {f}
                                </span>
                            ))}
                        </div>
                     )}
                     <div 
                        className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                        onClick={(e) => handleDeleteHistory(h.id, e)}
                     >
                        <Trash2 size={14} />
                     </div>
                  </button>
               ))}
            </div>
         </div>
      )}

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-purple-500" /> ER Diagram Guide</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>Supported Inputs:</strong></p>
                    <ul className="list-disc pl-5 space-y-2">
                       <li><strong>DDL:</strong> Paste raw `CREATE TABLE` statements.</li>
                       <li><strong>Business Logic:</strong> Describe relationships ("Users place Orders").</li>
                       <li><strong>Hybrid:</strong> Paste DDL and ask AI to "infer missing foreign keys".</li>
                    </ul>
                    <p className="bg-purple-50 p-2 rounded border border-purple-100 text-purple-700">
                        <strong>Tip:</strong> Click "Mermaid" in the canvas to see the generated `erDiagram` code!
                    </p>
                 </div>
              </div>
           </div>
      )}

      <div className="flex-1 relative">
         {design.nodes.length === 0 && !isGenerating ? (
            <div className="absolute inset-0 flex items-center justify-center bg-slate-50 z-10">
               <div className="bg-white p-8 rounded-2xl shadow-xl max-w-2xl w-full text-center">
                  <div className="w-16 h-16 bg-purple-50 text-purple-600 rounded-full flex items-center justify-center mx-auto mb-4">
                     <Table size={32} />
                  </div>
                  <h3 className="text-xl font-bold text-slate-800 mb-2">Create Data Model</h3>
                  <p className="text-slate-500 mb-6 text-sm">Convert SQL DDL or Natural Language descriptions into Entity Relationship Diagrams.</p>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-left mb-4">
                      <div>
                          <label className="block text-xs font-bold text-slate-600 mb-2 flex items-center gap-2"><Database size={12}/> SQL DDL (Source/Target)</label>
                          <textarea 
                            value={ddlInput}
                            onChange={(e) => setDdlInput(e.target.value)}
                            className="w-full h-32 bg-slate-50 border border-slate-300 rounded-lg p-3 text-xs font-mono focus:ring-1 focus:ring-purple-500 outline-none resize-none"
                            placeholder="CREATE TABLE Customers (ID int, Name varchar...)"
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-600 mb-2 flex items-center gap-2"><BrainCircuit size={12}/> Business Logic / NLP</label>
                          <textarea 
                            value={logicInput}
                            onChange={(e) => setLogicInput(e.target.value)}
                            className="w-full h-32 bg-slate-50 border border-slate-300 rounded-lg p-3 text-xs focus:ring-1 focus:ring-purple-500 outline-none resize-none"
                            placeholder="Customers place Orders. An Order belongs to one Customer. Orders contain multiple Products..."
                          />
                      </div>
                  </div>

                  <div className="flex justify-between gap-2">
                     <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-500 hover:text-purple-600 border border-slate-200 px-3 py-2 rounded-lg hover:border-purple-300 transition-all">
                        <UploadCloud size={16} /> Upload SQL File
                        <input type="file" className="hidden" onChange={handleFileUpload} />
                     </label>
                     <button 
                        onClick={() => handleGenerate()}
                        disabled={!ddlInput.trim() && !logicInput.trim()}
                        className="flex-1 bg-purple-600 hover:bg-purple-700 text-white font-bold py-2 rounded-lg transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                     >
                        <Sparkles size={18} /> Generate ERD
                     </button>
                  </div>
               </div>
            </div>
         ) : (
            <div className="h-full relative">
               <ArchitectureCanvas 
                 ref={canvasRef}
                 aiNodes={design.nodes} 
                 aiEdges={design.edges} 
                 isThinking={isGenerating} 
                 thoughts={thoughts}
                 context={ddlInput + '\n' + logicInput}
                 onApplyRefinement={handleRefinement}
                 onRefine={(p) => {
                     // We just use the refinement prompt as the "logic" input for re-generation context
                     setLogicInput(p);
                     handleGenerate(p);
                 }}
                 refinementPlaceholder="Refine model (e.g. 'Add User table linked to Orders')..."
               />
            </div>
         )}
      </div>
    </div>
  );
};

export default StandaloneERDiagram;

export const generateIntelligentQuestionnaire = async (
