  embedded = false, 
  initialContext = '', 
  initialInputs, 
  onSave 
}) => {
  const [context, setContext] = useState(initialContext);
  // New State: Result View is hidden initially for standalone, but shown for embedded if data exists
  const [showResults, setShowResults] = useState(embedded && initialInputs ? true : false);
  const [activeTab, setActiveTab] = useState<'drivers' | 'resources' | 'timeline' | 'assumptions'>('drivers');

  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [assumptions, setAssumptions] = useState<AssumptionData>({ inScope: [], outScope: [] });

  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);

  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);

  // AI Rationale (NLP Output)
  const [aiRationale, setAiRationale] = useState<string>("Analyzing project requirements...");

  // Resource State (Editable)
  const [customResourceCounts, setCustomResourceCounts] = useState<Record<string, number>>({
    'pm': 1, 'arch': 1, 'lead': 1, 'dev': 2, 'qa': 1
  });

  // Initialize
  useEffect(() => {
    if (initialInputs) {
        setEstimationInputs(initialInputs);
    } else {
        const defaults: EstimationInputs = {};
        ALL_MODULES_CONFIG.forEach(m => m.drivers.forEach(d => defaults[d.id] = d.defaultValue));
        setEstimationInputs(defaults);
    }

    // Only load history if standalone
    if (!embedded) {
        setHistoryItems(getHistory('Estimator'));
    }
  }, [initialInputs, embedded]);

  // Sync back to parent if embedded
  useEffect(() => {
      if (embedded && onSave && Object.keys(estimationInputs).length > 0) {
          onSave(estimationInputs);
      }
  }, [estimationInputs, embedded, onSave]);

  // Update context if prop changes
  useEffect(() => {
      if (initialContext) setContext(initialContext);
  }, [initialContext]);

  // Timer Effect
  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // --- RECALCULATION ENGINE ---
  const calculations = useMemo(() => {
    let totalTechHours = 0;
    const moduleBreakdown: Record<string, number> = {};

    // 1. Calculate Tech Hours from Drivers
    ALL_MODULES_CONFIG.forEach(mod => {
      let modHours = 0;
      mod.drivers.forEach(driver => {
        const val = estimationInputs[driver.id] || 0;
        modHours += val * driver.multiplier;
      });
      moduleBreakdown[mod.id] = modHours;
      totalTechHours += modHours;
    });

    const testingBuffer = totalTechHours * 0.30;
    const grandTotalHours = totalTechHours + testingBuffer;

    // 2. Resource & Duration Logic (Auto-Scalable)
    // Formula: Duration = TotalHours / (Headcount * Velocity)
    // Velocity assumed: 35 effective hours/week per person

    const resourceList = [
        { id: 'pm', role: 'Project Manager', rate: 800, utilization: 0.5 },
        { id: 'arch', role: 'Solution Architect', rate: 950, utilization: 0.25 },
        { id: 'lead', role: 'Tech Lead', rate: 750, utilization: 1.0 },
        { id: 'dev', role: 'Developer', rate: 500, utilization: 1.0 },
        { id: 'qa', role: 'QA Engineer', rate: 450, utilization: 1.0 },
    ];

    // Calculate effective team velocity based on current resource counts
    const effectiveDevCount = customResourceCounts['dev'] || 1;
    const weeklyVelocity = effectiveDevCount * 35; // 35 hours per dev per week

    // Derived Duration
    const calculatedDurationWeeks = Math.max(4, Math.ceil(grandTotalHours / weeklyVelocity));

    const finalResources = resourceList.map(r => ({
        ...r,
        count: customResourceCounts[r.id] || 1,
        totalCost: (calculatedDurationWeeks * 5) * (customResourceCounts[r.id] || 1) * r.rate * r.utilization
    }));

    const totalProjectCost = finalResources.reduce((acc, r) => acc + r.totalCost, 0);

    // 3. Timeline Phases Generation
    const phases = [
        { name: "Inception & Analysis", pct: 0.10, color: "bg-blue-500" },
        { name: "Design & Architecture", pct: 0.15, color: "bg-indigo-500" },
        { name: "Build & Implementation", pct: 0.50, color: "bg-emerald-500" },
        { name: "Testing (SIT/UAT)", pct: 0.20, color: "bg-orange-500" },
        { name: "Deployment & Go-Live", pct: 0.05, color: "bg-slate-700" }
    ];

    let currentStart = 0;
    const timelineData = phases.map(p => {
        const weeks = Math.max(1, Math.round(calculatedDurationWeeks * p.pct));
        const start = currentStart;
        currentStart += weeks;
        return { ...p, duration: weeks, startOffset: start };
    });

    return { 
        grandTotalHours, 
        calculatedDurationWeeks, 
        totalProjectCost, 
        moduleBreakdown, 
        finalResources,
        timelineData
    };
  }, [estimationInputs, customResourceCounts]);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    if (!context.trim()) return;
    setIsGenerating(true);
    setEta(8); // Estimated 8 seconds
    setError(null);
    try {
      const [estimationResult, assumptionResult] = await Promise.all([
         generateDynamicEstimation(context),
         generateAssumptions(context)
      ]);

      if (estimationResult && estimationResult.inputs) {
          setEstimationInputs(prev => ({...prev, ...estimationResult.inputs}));
          // Auto-scale dev count based on complexity if needed (simple heuristic)
          // Ensure inputs values are numbers for reduce
          const totalObj = Object.values(estimationResult.inputs).reduce((a: number, b: number) => a + (b || 0), 0);

          if (totalObj > 100) setCustomResourceCounts(prev => ({...prev, dev: 4, qa: 2}));
          else if (totalObj > 50) setCustomResourceCounts(prev => ({...prev, dev: 3, qa: 1}));

          setAiRationale(estimationResult.rationale || `Based on the requirements, I've identified ${totalObj} key estimation drivers.`);

          if (assumptionResult) setAssumptions(assumptionResult);

          const fullDataToSave = {
              data: estimationResult.inputs,
              rationale: estimationResult.rationale,
              assumptions: assumptionResult
          };

          if (!embedded) {
             saveHistory('Estimator', context.substring(0, 40) + '...', fullDataToSave, uploadedFiles);
             setHistoryItems(getHistory('Estimator'));
          }
          setShowResults(true); // Reveal tabs
          setActiveTab('drivers');

          // Trigger background learning
          setIsLearning(true);
          analyzeAndLearn(context, null, estimationResult.inputs, ['Manager'], 'initial').finally(() => setIsLearning(false));

      } else {
          setError("AI could not infer specific project drivers. Please verify requirements.");
      }
    } catch (e) {
      console.error(e);
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);

      if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
         // Excel parsing logic ...
         setContext(prev => prev + `\n[Attached Estimation File: ${file.name}]`);
      } else {
         setContext(prev => prev + `\n[Attached RFP: ${file.name}]`);
      }
    }
  };

  const loadHistoryItem = (item: any) => {
    setContext(item.summary);
    // Handle both old and new history structures
    const inputData = item.data.data || item.data;
    setEstimationInputs(inputData);
    if (item.data.rationale) setAiRationale(item.data.rationale);
    if (item.data.assumptions) setAssumptions(item.data.assumptions);
    setUploadedFiles(item.files || []);
    setShowResults(true);
    setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const exportXLSX = () => {
    if (!window.XLSX) { alert("Library loading..."); return; }
    const XLSX = window.XLSX;
    const wb = XLSX.utils.book_new();

    // Sheet 1: Executive Summary
    const summaryData = [
      ["EXECUTIVE SUMMARY"],
      ["Project Context", context.substring(0, 200) + "..."],
      ["AI Analysis", aiRationale],
      [],
      ["KEY METRICS"],
      ["Total Estimated Cost", calculations.totalProjectCost],
      ["Total Effort (Hours)", calculations.grandTotalHours],
      ["Estimated Duration", `${calculations.calculatedDurationWeeks} Weeks`],
      [],
      ["Generated By", "DataArch AI Accelerator"]
    ];
    const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(wb, wsSummary, "Summary");

    // Sheet 2: Detailed Drivers
    const driverHeader = [["Module", "Driver Name", "Category", "Quantity", "Multiplier (Hrs)", "Total Hours", "Description"]];
    const driverRows: any[] = [];
    ALL_MODULES_CONFIG.forEach(mod => {
        mod.drivers.forEach(d => {
            const qty = estimationInputs[d.id] || 0;
            if (qty > 0) {
                driverRows.push([mod.title, d.label, d.category, qty, d.multiplier, qty * d.multiplier, d.description]);
            }
        });
    });
    const wsDrivers = XLSX.utils.aoa_to_sheet([...driverHeader, ...driverRows]);
    XLSX.utils.book_append_sheet(wb, wsDrivers, "Complexity Drivers");

    // Sheet 3: Resource Plan
    const resHeader = [["Role", "Headcount", "Daily Rate", "Utilization %", "Cost"]];
    const resRows = calculations.finalResources.map(r => [
        r.role, r.count, r.rate, r.utilization * 100, r.totalCost
    ]);
    const wsRes = XLSX.utils.aoa_to_sheet([...resHeader, ...resRows]);
    XLSX.utils.book_append_sheet(wb, wsRes, "Resource Plan");

    // Sheet 4: Timeline
    const timeHeader = [["Phase", "Duration (Weeks)", "Start Week", "End Week"]];
    const timeRows = calculations.timelineData.map(t => [
        t.name, t.duration, t.startOffset + 1, t.startOffset + t.duration
    ]);
    const wsTime = XLSX.utils.aoa_to_sheet([...timeHeader, ...timeRows]);
    XLSX.utils.book_append_sheet(wb, wsTime, "Timeline");

    // Sheet 5: Assumptions
    const asmHeader = [["Type", "Item"]];
    const asmRows = [
        ...assumptions.inScope.map(i => ["In Scope", i]),
        ...assumptions.outScope.map(i => ["Out of Scope", i])
    ];
    const wsAsm = XLSX.utils.aoa_to_sheet([...asmHeader, ...asmRows]);
    XLSX.utils.book_append_sheet(wb, wsAsm, "Assumptions");

    XLSX.writeFile(wb, "Project_Estimation_Report.xlsx");

    // Trigger learning on Export (Reinforce current config)
    setIsLearning(true);
    analyzeAndLearn(context, "User Finalized Estimate", estimationInputs, ['Manager'], 'acceptance').finally(() => setIsLearning(false));
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);

  return (
    <div className={`flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in ${embedded ? 'bg-transparent' : ''}`}>

      {/* Header - Hidden if Embedded */}
      {!embedded && (
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><Calculator size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Estimator
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Driver Analysis & Resource Modeling</p>
            </div>
         </div>
         <div className="flex gap-2">
            <button onClick={exportXLSX} className="hidden md:flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-bold px-4 py-2 rounded-lg transition-colors shadow-sm">
                <FileSpreadsheet size={16} /> Export Solution
            </button>
            <button onClick={() => setShowHelp(true)} className="text-slate-500 hover:text-indigo-600"><HelpCircle size={20} /></button>
            <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-100'}`}><History size={18} /> History</button>
         </div>
      </div>
      )}

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <AlertTriangle size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-16 right-4 z-50 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3">Recent Estimates</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
               {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> : 
               historyItems.map((h, i) => (
                  <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                     <div className="flex justify-between items-start mb-1">
                        <span className="font-bold text-slate-700 truncate max-w-[180px]">{h.summary}</span>
                        <span className="text-slate-400 text-[10px]">{h.date}</span>
                     </div>
                     {h.files && h.files.length > 0 && (
                        <div className="flex gap-1 mt-1">
                            {h.files.map((f: string, idx: number) => (
                                <span key={idx} className="bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded text-[9px] flex items-center gap-0.5 truncate max-w-[80px]">
                                    <FileText size={8}/> {f}
                                </span>
                            ))}
                        </div>
                     )}
                     <div 
                        className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                        onClick={(e) => handleDeleteHistory(h.id, e)}
                     >
                        <Trash2 size={14} />
                     </div>
                  </button>
               ))}
            </div>
         </div>
      )}

      <div className={`flex-1 overflow-y-auto ${embedded ? 'p-0' : 'p-6 md:p-8'}`}>
         <div className="max-w-6xl mx-auto space-y-8">

            {/* 1. INPUT SECTION (Minimizable) */}
            <div className={`bg-white rounded-xl shadow-sm border border-slate-200 transition-all duration-500 ${showResults ? 'p-4' : 'p-8'}`}>
               <div className="flex justify-between items-center mb-4">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Sparkles className="text-indigo-500" size={18}/> {embedded ? 'Estimation Logic' : 'Project Context & Learning'}</h3>
                  {showResults && <button onClick={() => setShowResults(false)} className="text-xs text-indigo-600 hover:underline">Edit Inputs</button>}
               </div>

               {!showResults ? (
                   <div className="space-y-4 animate-fade-in">
                        <p className="text-sm text-slate-500">
                            Describe your project or upload an RFP.
                        </p>
                        <textarea 
                            value={context}
                            onChange={(e) => setContext(e.target.value)}
                            className="w-full h-40 p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                            placeholder="Example: Migration of 50 Oracle tables to Snowflake using Informatica. Includes Data Quality for Customer domain..."
                        />
                        <div className="flex flex-wrap gap-2 mb-4">
                            {uploadedFiles.map((f, i) => (
                                <span key={i} className="px-2 py-1 bg-slate-100 border border-slate-200 rounded text-xs text-slate-600 flex items-center gap-1">
                                    <FileSpreadsheet size={12}/> {f}
                                    <button onClick={() => setUploadedFiles(prev => prev.filter(file => file !== f))} className="hover:text-red-500 ml-1"><X size={10}/></button>
                                </span>
                            ))}
                        </div>
                        <div className="flex justify-between items-center pt-2">
                            <label className="flex items-center gap-2 cursor-pointer px-4 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-lg text-sm font-medium text-slate-600 transition-colors">
                                <UploadCloud size={18} /> Upload RFP / Excel
                                <input type="file" className="hidden" accept=".pdf,.docx,.txt,.xlsx,.xls" onChange={handleFileUpload} />
                            </label>
                            <button 
                                onClick={handleGenerate} 
                                disabled={!context.trim() || isGenerating} 
                                className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 shadow-md hover:shadow-lg min-w-[180px] justify-center"
                            >
                                {isGenerating ? (
                                    <>
                                        <Loader size={18} className="animate-spin"/> 
                                        <span>{eta > 0 ? `Analysing (${eta}s)` : 'Working...'}</span>
                                    </>
                                ) : (
                                    <>
                                        <Sparkles size={18}/>
                                        {embedded ? 'Update Estimate' : 'Generate Estimation'}
                                    </>
                                )}
                            </button>
                        </div>
                   </div>
               ) : (
                   <div className="flex items-center justify-between text-sm text-slate-600">
                       <p className="truncate max-w-2xl italic">Context Loaded: "{context.substring(0, 100)}..."</p>
                       <button onClick={handleGenerate} className="flex items-center gap-1 text-indigo-600 font-medium hover:text-indigo-800"><ArrowRight size={14}/> Re-Analyze</button>
                   </div>
               )}
            </div>

            {/* 2. RESULTS SECTION (Configurable Tabs) */}
            {showResults && (
                <div className="animate-fade-in-up">

                    {/* Navigation Tabs */}
                    <div className="flex gap-1 mb-6 bg-slate-200/50 p-1 rounded-xl inline-flex overflow-x-auto max-w-full">
                        <button onClick={() => setActiveTab('drivers')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'drivers' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>1. Drivers</button>
                        <button onClick={() => setActiveTab('resources')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'resources' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>2. Resources</button>
                        <button onClick={() => setActiveTab('timeline')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'timeline' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>3. Timeline</button>
                        <button onClick={() => setActiveTab('assumptions')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${activeTab === 'assumptions' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>4. Assumptions & Scope</button>
                    </div>

                    {/* AI NLP Summary Block */}
                    <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl mb-6 flex items-start gap-3">
                        <BrainCircuit className="text-indigo-500 mt-1 flex-shrink-0" size={20} />
                        <div>
                            <h4 className="text-sm font-bold text-indigo-900 mb-1">AI Insight</h4>
                            <p className="text-sm text-indigo-800 leading-relaxed">{aiRationale}</p>
                        </div>
                    </div>

                    {/* TAB CONTENT */}

                    {/* TAB 1: DRIVERS */}
                    {activeTab === 'drivers' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                                <h3 className="font-bold text-slate-800 text-sm">Configurable Effort Drivers</h3>
                                <button onClick={() => setShowConfig(!showConfig)} className="text-xs text-blue-600 flex items-center gap-1 bg-white border border-blue-200 px-2 py-1 rounded hover:bg-blue-50"><Settings size={12}/> {showConfig ? 'Hide Config' : 'Edit Multipliers'}</button>
                            </div>
                            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                                {ALL_MODULES_CONFIG.map(mod => (
                                    <div key={mod.id} className="border border-slate-100 rounded-xl p-4 hover:border-slate-300 transition-colors">
                                        <h4 className="text-sm font-bold text-slate-700 uppercase mb-4 flex items-center gap-2">
                                            <mod.icon size={16} style={{color: mod.color}} /> {mod.title}
                                        </h4>
                                        <div className="space-y-3">
                                            {mod.drivers.map(driver => (
                                                <div key={driver.id} className="flex items-center justify-between group">
                                                    <div className="flex-1 pr-4">
                                                        <p className="text-sm font-medium text-slate-700">{driver.label}</p>
                                                        <p className="text-[10px] text-slate-400">{driver.description}</p>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <div className="flex flex-col items-end">
                                                            <input 
                                                                type="number" 
                                                                min="0"
                                                                className="w-16 p-1 border border-slate-300 rounded text-right font-mono text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                                                                value={estimationInputs[driver.id] || 0}
                                                                onChange={(e) => setEstimationInputs(prev => ({...prev, [driver.id]: parseInt(e.target.value) || 0}))}
                                                            />
                                                            <span className="text-[10px] text-slate-400">count</span>
                                                        </div>
                                                        {showConfig && (
                                                            <div className="flex flex-col items-end">
                                                                <input 
                                                                    type="number" 
                                                                    className="w-12 p-1 border border-slate-200 rounded text-right text-xs bg-slate-50" 
                                                                    defaultValue={driver.multiplier} 
                                                                />
                                                                <span className="text-[10px] text-slate-400">hrs/unit</span>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <div className="bg-slate-50 p-4 border-t border-slate-200 text-right">
                                <p className="text-sm font-medium text-slate-600">Total Derived Effort: <span className="font-bold text-slate-900">{calculations.grandTotalHours.toFixed(0)} Hours</span></p>
                            </div>
                        </div>
                    )}

                    {/* TAB 2: RESOURCES */}
                    {activeTab === 'resources' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-4 border-b border-slate-100 bg-slate-50">
                                <h3 className="font-bold text-slate-800 text-sm">Resource Plan & Costing</h3>
                                <p className="text-xs text-slate-500 mt-1">Adjust headcount to auto-scale project duration.</p>
                            </div>
                            <div className="p-0">
                                <table className="w-full text-left text-sm">
                                    <thead className="bg-slate-50 text-slate-500 border-b border-slate-100">
                                        <tr>
                                            <th className="px-6 py-3 font-semibold">Role</th>
                                            <th className="px-6 py-3 font-semibold">Rate / Day</th>
                                            <th className="px-6 py-3 font-semibold text-center">Headcount</th>
                                            <th className="px-6 py-3 font-semibold text-center">Utilization</th>
                                            <th className="px-6 py-3 font-semibold text-right">Est. Cost</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-50">
                                        {calculations.finalResources.map((r, i) => (
                                            <tr key={i} className="hover:bg-slate-50 transition-colors">
                                                <td className="px-6 py-4 font-medium text-slate-700">{r.role}</td>
                                                <td className="px-6 py-4 text-slate-500">${r.rate}</td>
                                                <td className="px-6 py-4 text-center">
                                                    <div className="inline-flex items-center border rounded-lg bg-white">
                                                        <button 
                                                            className="px-2 py-1 hover:bg-slate-100 text-slate-500"
                                                            onClick={() => setCustomResourceCounts(prev => ({...prev, [r.id]: Math.max(0, (prev[r.id] || 1) - 1)}))}
                                                        >-</button>
                                                        <input 
                                                            type="number" 
                                                            className="w-12 text-center border-x p-1 outline-none text-slate-800 font-bold"
                                                            value={r.count}
                                                            onChange={(e) => setCustomResourceCounts(prev => ({...prev, [r.id]: parseInt(e.target.value) || 0}))}
                                                        />
                                                        <button 
                                                            className="px-2 py-1 hover:bg-slate-100 text-slate-500"
                                                            onClick={() => setCustomResourceCounts(prev => ({...prev, [r.id]: (prev[r.id] || 1) + 1}))}
                                                        >+</button>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-center text-slate-500">{(r.utilization * 100)}%</td>
                                                <td className="px-6 py-4 text-right font-bold text-slate-800">{formatCurrency(r.totalCost)}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                    <tfoot className="bg-slate-50 border-t border-slate-200">
                                        <tr>
                                            <td colSpan={4} className="px-6 py-4 text-right font-bold text-slate-600">Total Estimated Cost:</td>
                                            <td className="px-6 py-4 text-right font-bold text-emerald-600 text-lg">{formatCurrency(calculations.totalProjectCost)}</td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        </div>
                    )}

                    {/* TAB 3: TIMELINE */}
                    {activeTab === 'timeline' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <div>
                                    <h3 className="font-bold text-slate-800">Project Timeline</h3>
                                    <p className="text-xs text-slate-500">Total Duration: <span className="font-bold text-indigo-600">{calculations.calculatedDurationWeeks} Weeks</span> (Auto-scaled based on {calculations.grandTotalHours.toFixed(0)} hrs effort)</p>
                                </div>
                                <button className="text-sm font-bold text-white bg-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center gap-2"><Download size={16}/> Export Plan</button>
                            </div>
                            <div className="p-8">
                                <div className="space-y-6">
                                    {calculations.timelineData.map((phase, i) => (
                                        <div key={i} className="relative">
                                            <div className="flex justify-between items-end mb-2">
                                                <span className="text-sm font-bold text-slate-700">{phase.name}</span>
                                                <span className="text-xs text-slate-500">{phase.duration} Wks</span>
                                            </div>
                                            <div className="h-4 bg-slate-100 rounded-full w-full overflow-hidden relative">
                                                {/* Grid lines for weeks - purely visual */}
                                                <div className="absolute inset-0 flex">
                                                    {Array.from({length: calculations.calculatedDurationWeeks}).map((_, idx) => (
                                                        <div key={idx} className="flex-1 border-r border-white/50"></div>
                                                    ))}
                                                </div>
                                                <div 
                                                    className={`h-full rounded-full ${phase.color} shadow-sm transition-all duration-700`}
                                                    style={{
                                                        width: `${(phase.duration / calculations.calculatedDurationWeeks) * 100}%`,
                                                        marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`
                                                    }}
                                                ></div>
                                            </div>
                                            <div className="mt-1 flex justify-between text-[10px] text-slate-400">
                                                <span style={{marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + 1}</span>
                                                <span style={{marginRight: `${100 - ((phase.startOffset + phase.duration) / calculations.calculatedDurationWeeks) * 100}%`}}>Week {phase.startOffset + phase.duration}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="mt-8 pt-6 border-t border-slate-100 text-center">
                                    <p className="text-xs text-slate-400 italic">Timeline is derived from total effort hours divided by the effective team velocity. Adjust "Resource Plan" to compress or expand timelines.</p>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* TAB 4: ASSUMPTIONS */}
                    {activeTab === 'assumptions' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                            <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                                <h3 className="font-bold text-slate-800 text-sm">Assumptions & Scope</h3>
                                <div className="flex gap-2">
                                   <button className="text-xs text-green-600 bg-green-50 hover:bg-green-100 px-2 py-1 rounded border border-green-200 flex items-center gap-1" onClick={() => setAssumptions(prev => ({...prev, inScope: [...prev.inScope, "New Item"]}))}><Plus size={12}/> In Scope</button>
                                   <button className="text-xs text-red-600 bg-red-50 hover:bg-red-100 px-2 py-1 rounded border border-red-200 flex items-center gap-1" onClick={() => setAssumptions(prev => ({...prev, outScope: [...prev.outScope, "New Item"]}))}><Plus size={12}/> Out Scope</button>
                                </div>
                            </div>
                            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div>
                                    <h4 className="text-sm font-bold text-green-700 mb-4 flex items-center gap-2"><ListChecks size={16}/> In Scope</h4>
                                    <ul className="space-y-2">
                                        {assumptions.inScope.map((item, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-slate-700 bg-green-50/50 p-2 rounded border border-green-100 group">
                                                <span className="mt-1 w-1.5 h-1.5 bg-green-500 rounded-full shrink-0"/>
                                                <input 
                                                   className="bg-transparent w-full outline-none" 
                                                   value={item} 
                                                   onChange={(e) => {
                                                       const newItems = [...assumptions.inScope];
                                                       newItems[i] = e.target.value;
                                                       setAssumptions({...assumptions, inScope: newItems});
                                                   }}
                                                />
                                                <button onClick={() => setAssumptions(prev => ({...prev, inScope: prev.inScope.filter((_, idx) => idx !== i)}))} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={14}/></button>
                                            </li>
                                        ))}
                                        {assumptions.inScope.length === 0 && <p className="text-xs text-slate-400 italic">No in-scope items defined.</p>}
                                    </ul>
                                </div>
                                <div>
                                    <h4 className="text-sm font-bold text-red-700 mb-4 flex items-center gap-2"><X size={16}/> Out of Scope</h4>
                                    <ul className="space-y-2">
                                        {assumptions.outScope.map((item, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-slate-700 bg-red-50/50 p-2 rounded border border-red-100 group">
                                                <span className="mt-1 w-1.5 h-1.5 bg-red-500 rounded-full shrink-0"/>
                                                <input 
                                                   className="bg-transparent w-full outline-none" 
                                                   value={item} 
                                                   onChange={(e) => {
                                                       const newItems = [...assumptions.outScope];
                                                       newItems[i] = e.target.value;
                                                       setAssumptions({...assumptions, outScope: newItems});
                                                   }}
                                                />
                                                <button onClick={() => setAssumptions(prev => ({...prev, outScope: prev.outScope.filter((_, idx) => idx !== i)}))} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={14}/></button>
                                            </li>
                                        ))}
                                         {assumptions.outScope.length === 0 && <p className="text-xs text-slate-400 italic">No out-of-scope items defined.</p>}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    )}

                </div>
            )}
         </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-emerald-500" /> Estimator Guide</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>1. Input & Learn:</strong> Upload an RFP or a previous estimation Excel file. The AI learns the complexity patterns.</p>
                    <p><strong>2. Configure Drivers:</strong> The AI populates the driver counts (e.g., 50 tables). You can tweak these numbers, and the cost/effort updates instantly.</p>
                    <p><strong>3. Auto-Scale Resources:</strong> Go to the Resource tab. Increasing the headcount will automatically reduce the project timeline in the Timeline tab.</p>
                 </div>
              </div>
           </div>
      )}
    </div>
  );
};

export default StandaloneEstimator;

import React, { useState, useEffect } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  HelpCircle, 
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet,
  LayoutGrid,
  BarChart2,
  List
} from 'lucide-react';
import { generateDataQualityRules, generateDQCleanseRules, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule, DQCleanseRule } from '../types';

interface GroupedRules {
  [element: string]: DataQualityRule[];
}

const StandaloneDataQuality: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'validation' | 'cleanse'>('validation');
  const [isValidationComplete, setIsValidationComplete] = useState(false);

  // Validation State
  const [cdeContext, setCdeContext] = useState('');
  const [validationFile, setValidationFile] = useState<File | null>(null);
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);
  const [groupedRules, setGroupedRules] = useState<GroupedRules>({});
  const [selectedElement, setSelectedElement] = useState<string | null>(null);

  // Cleanse State
  const [cleanseContext, setCleanseContext] = useState('');
  const [profileFile, setProfileFile] = useState<File | null>(null);
  const [cleanseRules, setCleanseRules] = useState<DQCleanseRule[]>([]);

  // Common State
  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isLearning, setIsLearning] = useState(false);

  // Timer Effect
  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // Group Rules logic
  useEffect(() => {
    if (validationRules.length > 0) {
        const grouped: GroupedRules = {};
        validationRules.forEach(rule => {
            const key = rule.element || "General";
            if (!grouped[key]) grouped[key] = [];
            grouped[key].push(rule);
        });
        setGroupedRules(grouped);
    }
  }, [validationRules]);

  const handleValidationFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setValidationFile(e.target.files[0]);
    }
  };

  const handleProfileFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setProfileFile(e.target.files[0]);
    }
  };

  const handleGenerateValidation = async () => {
    if (!cdeContext.trim()) return;
    setIsGenerating(true);
    setEta(3); // Reduced ETA since we are using Flash and expecting extraction
    setError(null);
    try {
      const fullContext = `
        User NLP Requirements: ${cdeContext}
        ${validationFile ? `File Context (Profile/Raw Data): File named "${validationFile.name}". If this is a Profile export (JSON), EXTRACT existing rules matching 'RULE_SPECIFICATION' pattern.` : ''}
      `;

      const rules = await generateDataQualityRules(fullContext, "Informatica Cloud Data Quality");
      setValidationRules(rules);
      setIsValidationComplete(true);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(fullContext, "Generated DQ Validation Rules", rules, ['Data Steward'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate validation rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const handleGenerateCleanse = async () => {
    if (!profileFile && !cleanseContext.trim()) {
        setError("Please provide either a Profile File or Description.");
        return;
    }
    setIsGenerating(true);
    setEta(12);
    setError(null);
    try {
      const fullContext = `
         Rule Based Profile Input: ${profileFile ? `File "${profileFile.name}"` : "Not provided"}.
         User Cleansing NLP Requirements: ${cleanseContext || "Auto-detect cleansing needs based on profile"}.
      `;
      const rules = await generateDQCleanseRules(fullContext);
      setCleanseRules(rules);

      // Learn
      setIsLearning(true);
      analyzeAndLearn(fullContext, "Generated DQ Cleanse Rules", rules, ['Data Engineer'], 'initial').finally(() => setIsLearning(false));
    } catch (e) {
      setError("Failed to generate cleanse rules.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const getDimensionStats = (rules: DataQualityRule[]) => {
      const stats: Record<string, number> = {};
      if (!rules) return stats;
      rules.forEach(r => {
          stats[r.type] = (stats[r.type] || 0) + 1;
      });
      return stats;
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><ShieldCheck size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Data Quality Studio
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Validation & Cleansing Logic Generator (IDQ/CDQ)</p>
            </div>
         </div>
      </div>

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <X size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {/* Drill-down Sidebar */}
      {selectedElement && groupedRules[selectedElement] && (
          <div className="absolute top-0 right-0 h-full w-96 bg-white shadow-2xl z-40 border-l border-slate-200 flex flex-col animate-fade-in-up">
              <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <div>
                      <h3 className="font-bold text-slate-800">{selectedElement}</h3>
                      <p className="text-xs text-slate-500">{groupedRules[selectedElement].length} Rules Defined</p>
                  </div>
                  <button onClick={() => setSelectedElement(null)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={18}/></button>
              </div>
              <div className="p-4 flex-1 overflow-y-auto">
                  <div className="mb-6">
                      <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Coverage Statistics</h4>
                      <div className="space-y-2">
                          {Object.entries(getDimensionStats(groupedRules[selectedElement])).map(([dim, count]) => (
                              <div key={dim} className="flex items-center justify-between text-sm">
                                  <span className="text-slate-600 font-medium">{dim}</span>
                                  <div className="flex items-center gap-2">
                                      <div className="w-24 h-2 bg-slate-100 rounded-full overflow-hidden">
                                          <div className="h-full bg-emerald-500" style={{width: `${(count / groupedRules[selectedElement].length) * 100}%`}}></div>
                                      </div>
                                      <span className="text-slate-800 font-bold">{count}</span>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>

                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Rule Specifications</h4>
                  <div className="space-y-3">
                      {groupedRules[selectedElement].map((rule, idx) => (
                          <div key={idx} className="p-3 border border-slate-100 rounded-lg bg-white shadow-sm">
                              <div className="flex justify-between items-start mb-1">
                                  <span className="text-xs font-mono font-bold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded break-all">{rule.informaticaAssetName}</span>
                                  <span className={`text-[9px] uppercase font-bold px-1.5 py-0.5 rounded border ${rule.criticality === 'High' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-blue-50 text-blue-600 border-blue-100'}`}>{rule.criticality}</span>
                              </div>
                              <p className="text-xs text-slate-600 mt-2 line-clamp-3">{rule.description}</p>
                              {rule.logic && (
                                <div className="mt-2 pt-2 border-t border-slate-50">
                                    <p className="text-[10px] text-slate-400 font-mono">{rule.logic}</p>
                                </div>
                              )}
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      <div className="flex-1 overflow-y-auto p-6 md:p-8">
         <div className="max-w-6xl mx-auto space-y-8">

            {/* Step Navigation */}
            <div className="flex gap-4 mb-6">
                <button 
                  onClick={() => setActiveTab('validation')} 
                  className={`flex-1 p-4 rounded-xl border transition-all flex flex-col gap-2 ${activeTab === 'validation' ? 'bg-white border-emerald-500 shadow-md ring-1 ring-emerald-100' : 'bg-slate-100 border-transparent text-slate-500 hover:bg-white hover:border-slate-200'}`}
                >
                  <div className="flex justify-between items-center w-full">
                      <div className="flex items-center gap-2 font-bold text-sm"><CheckCircle size={18} className={activeTab === 'validation' ? 'text-emerald-500' : ''}/> Step 1: Validation Rules</div>
                      {isValidationComplete && <span className="bg-emerald-100 text-emerald-700 text-[10px] px-2 py-0.5 rounded-full font-bold">Completed</span>}
                  </div>
                  <p className="text-xs text-left opacity-80">Define business rules using NLP and Raw Source Data.</p>
                </button>

                <button 
                  onClick={() => isValidationComplete && setActiveTab('cleanse')} 
                  disabled={!isValidationComplete}
                  className={`flex-1 p-4 rounded-xl border transition-all flex flex-col gap-2 ${activeTab === 'cleanse' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-100' : 'bg-slate-100 border-transparent text-slate-400'}`}
                >
                  <div className="flex justify-between items-center w-full">
                      <div className="flex items-center gap-2 font-bold text-sm">
                          {isValidationComplete ? <Wand2 size={18} className={activeTab === 'cleanse' ? 'text-blue-500' : ''}/> : <Lock size={16} />} 
                          Step 2: Cleanse Rules
                      </div>
                  </div>
                  <p className="text-xs text-left opacity-80">Generate transformation logic from Rule Based Profiles.</p>
                </button>
            </div>

            {/* TAB 1: VALIDATION RULES */}
            {activeTab === 'validation' && (
               <div className="animate-fade-in space-y-6">
                  {/* Inputs */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <BrainCircuit size={16} className="text-purple-500"/> 1. Define Rules (NLP)
                        </label>
                        <textarea 
                           className="w-full p-4 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500 outline-none min-h-[140px]"
                           placeholder="Describe your validation needs (e.g. 'Ensure Email has valid format, Order Amount > 0, Shipping Address must be present if Method is Delivery')."
                           value={cdeContext}
                           onChange={(e) => setCdeContext(e.target.value)}
                        />
                     </div>
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <Database size={16} className="text-blue-500"/> 2. Raw Source Data / Profile (Optional)
                        </label>
                        {!validationFile ? (
                            <label className="flex flex-col items-center justify-center w-full h-[140px] border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                    <p className="text-sm text-slate-500">Upload Data or Rule Profile</p>
                                    <p className="text-xs text-slate-400 mt-1">(CSV, Excel, JSON)</p>
                                </div>
                                <input type="file" className="hidden" onChange={handleValidationFileUpload} />
                            </label>
                        ) : (
                            <div className="h-[140px] flex items-center justify-center">
                                <div className="flex items-center justify-between p-4 bg-emerald-50 border border-emerald-100 rounded-lg w-full">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-emerald-100 text-emerald-600 rounded"><FileSpreadsheet size={20} /></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">{validationFile.name}</p>
                                            <p className="text-xs text-slate-500">File Context Loaded</p>
                                        </div>
                                    </div>
                                    <button onClick={() => setValidationFile(null)} className="text-slate-400 hover:text-red-500"><X size={18} /></button>
                                </div>
                            </div>
                        )}
                     </div>
                     <div className="lg:col-span-2 flex justify-end">
                        <button 
                           onClick={handleGenerateValidation}
                           disabled={!cdeContext.trim() || isGenerating}
                           className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center gap-2 transition-all disabled:opacity-50 shadow-md"
                        >
                           {isGenerating ? <Loader size={18} className="animate-spin" /> : <Sparkles size={18} />}
                           {isGenerating && eta > 0 ? `Analysing Data (${eta}s)` : 'Generate Validation Rules'}
                        </button>
                     </div>
                  </div>

                  {/* Results Area - CRITICAL DATA ELEMENTS GRID */}
                  {validationRules.length > 0 && (
                     <div className="animate-fade-in-up">
                         <div className="flex justify-between items-center mb-4">
                             <h3 className="font-bold text-slate-800 flex items-center gap-2"><LayoutGrid size={18} className="text-indigo-500"/> Critical Data Elements ({Object.keys(groupedRules).length})</h3>
                             {!activeTab.includes('cleanse') && (
                                <button 
                                    onClick={() => setActiveTab('cleanse')} 
                                    className="text-xs flex items-center gap-1 text-blue-600 font-bold hover:underline"
                                >
                                    Next: Define Cleansing Rules <ArrowRight size={12}/>
                                </button>
                             )}
                         </div>

                         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
