// --- Helpers ---

async function retryWithBackoff<T>(fn: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
    try {
        return await fn();
    } catch (error) {
        if (retries === 0) throw error;
        await new Promise(resolve => setTimeout(resolve, delay));
        return retryWithBackoff(fn, retries - 1, delay * 2);
    }
}

function safeJsonParse<T>(text: string | undefined, fallback: T): T {
    if (!text) return fallback;
    try {
        // Remove Markdown code blocks if present
        const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanText) as T;
    } catch (e) {
        console.error("JSON Parse Error:", e);
        return fallback;
    }
}

// --- Local Storage History ---

export const saveHistory = (type: string, summary: string, data: any, files: string[]) => {
    const key = `history_${type}`;
    const newItem = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString(),
        summary,
        data,
        files
    };
    const existing = JSON.parse(localStorage.getItem(key) || '[]');
    localStorage.setItem(key, JSON.stringify([newItem, ...existing].slice(0, 50)));
};

export const getHistory = (type: string) => {
    return JSON.parse(localStorage.getItem(`history_${type}`) || '[]');
};

export const deleteHistory = (id: string) => {
    // Search across all types or passed type. Implementation simplified to search known types if generic.
    // For now assuming caller knows context or we just search all.
    const types = ['Architecture', 'Estimator', 'DataFlow', 'DataQuality', 'ERDiagram'];
    types.forEach(t => {
        const key = `history_${t}`;
        const existing = JSON.parse(localStorage.getItem(key) || '[]');
        const filtered = existing.filter((item: any) => item.id !== id);
        if (existing.length !== filtered.length) {
            localStorage.setItem(key, JSON.stringify(filtered));
        }
    });
};

