        history.forEach(h => prompt += `${h.role}: ${h.text}\n`);
        prompt += `user: ${message}\n`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt
        });
        return response.text || "I'm not sure how to respond.";
    } catch (e) { return "Error connecting to AI."; }
};

export const generateDynamicEstimation = async (context: string): Promise<{inputs: EstimationInputs, rationale: string}> => {
    try {
        const prompt = `
            Act as a Technical Project Manager.
            Analyze the provided context (RFP text, user description, or file content) to estimate the complexity drivers.

            Context: ${context}

            CLOUD CONVERSION TIPS (Apply these to your logic):
            1. 'Lift & Shift' implies simpler mappings (High % of di_map_s).
            2. 'Refactoring' or 'Modernization' implies complex mappings (Higher % of di_map_c).
            3. 'Migration' of tables usually follows a 60/30/10 distribution (Simple/Medium/Complex) unless specified otherwise.
               - Example: "50 Tables" -> 30 di_map_s, 15 di_map_m, 5 di_map_c.
            4. 'Real-time' implies Task Flows (di_task) and Mass Ingestion (mdm_ing_s).

            Drivers to Estimate (Return counts for these keys):
            - di_src (Source Systems count)
            - di_map_s (Simple Mappings), di_map_m (Medium), di_map_c (Complex)
            - di_task (Task flows)
            - dq_prof (Profiling objects), dq_rule_s (Simple DQ Rules), dq_rule_m, dq_rule_c, dq_sc (Scorecards)
            - dg_src (Governance Resources), dg_term (Business Terms), dg_pol (Policies), dg_lin (Lineage)
            - mdm_dom (Domains), mdm_ing_s (Simple Ingestion), mdm_ing_c, mdm_match (Match Rules)

            Instructions:
            1. Be realistic. Extract quantities from text. If text says "50 tables", use the distribution logic above.
            2. If specific numbers are not found, infer them based on the text's complexity (Small/Medium/Large project).
            3. Provide a 'rationale' string explaining how you derived these numbers, specifically referencing any Cloud Conversion tips applied.
        `;

        const response = await retryWithBackoff(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        inputs: {
                            type: Type.OBJECT,
                            properties: {
                                di_src: { type: Type.NUMBER },
                                di_map_s: { type: Type.NUMBER },
                                di_map_m: { type: Type.NUMBER },
                                di_map_c: { type: Type.NUMBER },
                                di_task: { type: Type.NUMBER },
                                dq_prof: { type: Type.NUMBER },
                                dq_rule_s: { type: Type.NUMBER },
                                dq_rule_m: { type: Type.NUMBER },
                                dq_rule_c: { type: Type.NUMBER },
                                dq_sc: { type: Type.NUMBER },
                                dg_src: { type: Type.NUMBER },
                                dg_term: { type: Type.NUMBER },
                                dg_pol: { type: Type.NUMBER },
                                dg_lin: { type: Type.NUMBER },
                                mdm_dom: { type: Type.NUMBER },
                                mdm_ing_s: { type: Type.NUMBER },
                                mdm_ing_c: { type: Type.NUMBER },
                                mdm_match: { type: Type.NUMBER },
                            }
                        },
                        rationale: { type: Type.STRING }
                    },
                    required: ["inputs", "rationale"]
                }
            }
        }));
        return safeJsonParse(response.text, { inputs: {}, rationale: "" });
    } catch (e) {
        return { inputs: {}, rationale: "" };
    }
};

export const generateAssumptions = async (context: string): Promise<AssumptionData> => {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: `List In-Scope and Out-of-Scope assumptions for: ${context}`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        inScope: { type: Type.ARRAY, items: { type: Type.STRING } },
                        outScope: { type: Type.ARRAY, items: { type: Type.STRING } }
                    }
                }
            }
        });
        return safeJsonParse(response.text, { inScope: [], outScope: [] });
    } catch (e) { return { inScope: [], outScope: [] }; }
};

