            - dq_prof (Profiling objects), dq_rule_s (Simple DQ Rules), dq_rule_m, dq_rule_c, dq_sc (Scorecards)
            - dg_src (Governance Resources), dg_term (Business Terms), dg_pol (Policies), dg_lin (Lineage)
            - mdm_dom (Domains), mdm_ing_s (Simple Ingestion), mdm_ing_c, mdm_match (Match Rules)

            Instructions:
            1. Be realistic. Extract quantities from text. If text says "50 tables", use the distribution logic above.
            2. If specific numbers are not found, infer them based on the text's complexity (Small/Medium/Large project).
            3. Provide a 'rationale' string explaining how you derived these numbers, specifically referencing any Cloud Conversion tips applied.
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        inputs: {
                            type: Type.OBJECT,
                            properties: {
                                di_src: { type: Type.NUMBER },
                                di_map_s: { type: Type.NUMBER },
                                di_map_m: { type: Type.NUMBER },
                                di_map_c: { type: Type.NUMBER },
                                di_task: { type: Type.NUMBER },
                                dq_prof: { type: Type.NUMBER },
                                dq_rule_s: { type: Type.NUMBER },
                                dq_rule_m: { type: Type.NUMBER },
                                dq_rule_c: { type: Type.NUMBER },
                                dq_sc: { type: Type.NUMBER },
                                dg_src: { type: Type.NUMBER },
                                dg_term: { type: Type.NUMBER },
                                dg_pol: { type: Type.NUMBER },
                                dg_lin: { type: Type.NUMBER },
                                mdm_dom: { type: Type.NUMBER },
                                mdm_ing_s: { type: Type.NUMBER },
                                mdm_ing_c: { type: Type.NUMBER },
                                mdm_match: { type: Type.NUMBER },
                            }
                        },
                        rationale: { type: Type.STRING }
                    },
                    required: ["inputs", "rationale"]
                }
            }
        }));
        return safeJsonParse(response.text, { inputs: {}, rationale: "" });
