            )}

            {/* TAB 2: CLEANSE RULES */}
            {activeTab === 'cleanse' && (
               <div className="animate-fade-in space-y-6">
                  {/* Input Area */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                            <FileText size={16} className="text-orange-500"/> 1. Rule Based Profile (Required)
                        </label>
                        {!profileFile ? (
                            <label className="flex flex-col items-center justify-center w-full h-[140px] border-2 border-dashed border-slate-300 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                    <p className="text-sm text-slate-500">Upload IDQ/CDQ Profile Export</p>
                                    <p className="text-xs text-slate-400 mt-1">(XML, JSON, Excel)</p>
