                                    className="w-full h-64 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm leading-relaxed"
                                    placeholder="e.g. This project aims to migrate an on-premise Oracle Data Warehouse to Snowflake on AWS. We need to use Informatica IDMC for ETL. Key constraints include GDPR compliance for customer data..."
                                />
                            </div>
                            <div className="flex justify-between">
                                <button onClick={() => setPhase('learn')} className="text-slate-500 font-medium text-sm hover:text-slate-800">Back</button>
                                <button 
                                    onClick={startGeneration} 
                                    disabled={!projectContext.trim()}
                                    className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 shadow-lg transition-transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <Sparkles size={18} /> Generate Document
                                </button>
                            </div>
                        </div>
                    )}

                    {/* PHASE 3: DASHBOARD / PREVIEW */}
                    {phase === 'dashboard' && (
                        <div className="animate-fade-in-up space-y-6">
                            <div className="flex justify-between items-center">
                                <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><BookOpen size={20} className="text-indigo-500"/> Document Dashboard</h3>
                                <div className="flex items-center gap-2">
                                    {isGenerating && <div className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full animate-pulse"><Loader size={12} className="animate-spin"/> AI Writer Active</div>}
                                    <span className="text-xs text-slate-500 font-medium">Template: {getActiveTemplate().name}</span>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                                {/* Sidebar Navigation */}
                                <div className="lg:col-span-1 space-y-2">
                                    {generatedSections.map((sec, idx) => (
                                        <button 
                                            key={sec.id}
                                            onClick={() => document.getElementById(sec.id)?.scrollIntoView({ behavior: 'smooth' })}
                                            className={`w-full text-left p-3 rounded-lg text-xs font-medium flex justify-between items-center transition-all ${sec.status === 'generated' ? 'bg-white border border-slate-200 text-slate-700 hover:border-indigo-300' : 'bg-slate-50 border border-transparent text-slate-400'}`}
                                        >
                                            <span className="truncate">{idx + 1}. {sec.title}</span>
                                            {sec.status === 'generated' ? <CheckCircle size={14} className="text-emerald-500"/> : activeSectionId === sec.id ? <Loader size={14} className="animate-spin text-indigo-500"/> : <div className="w-3 h-3 rounded-full bg-slate-200"></div>}
                                        </button>
                                    ))}
                                    <div className="pt-4 border-t border-slate-200 mt-4">
                                        <button onClick={() => setPhase('input')} className="w-full text-center text-xs text-slate-500 hover:text-indigo-600">Edit Context</button>
                                    </div>
                                </div>

                                {/* Content Area */}
                                <div className="lg:col-span-3 space-y-6">
                                    {generatedSections.map((sec) => (
                                        <div key={sec.id} id={sec.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden scroll-mt-24">
                                            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                                                <h4 className="font-bold text-slate-800">{sec.title}</h4>
                                                <div className="flex gap-2">
                                                    <button onClick={() => handleRegenerateSection(sec.id)} className="p-1.5 hover:bg-white rounded-md text-slate-400 hover:text-indigo-600 transition-colors" title="Regenerate Section">
                                                        <RefreshCw size={14} className={activeSectionId === sec.id ? 'animate-spin' : ''} />
                                                    </button>
                                                </div>
                                            </div>
                                            <div className="p-6 min-h-[150px]">
                                                {sec.status === 'pending' ? (
                                                    <div className="h-full flex flex-col items-center justify-center text-slate-300">
                                                        {activeSectionId === sec.id ? (
                                                            <>
                                                                <Loader size={24} className="animate-spin mb-2 text-indigo-400"/>
                                                                <p className="text-xs">Generating content...</p>
                                                            </>
                                                        ) : (
                                                            <p className="text-xs">Waiting in queue...</p>
                                                        )}
                                                    </div>
                                                ) : (
                                                    <div className="prose prose-sm max-w-none text-slate-600">
                                                        {sec.content.split('\n').map((line, i) => (
                                                            <p key={i} className="mb-2">{line.replace(/^\*\*(.*?)\*\*$/, '$1')}</p> 
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                </div>
            </div>
        </div>
    );
};

