import React, { useState, useEffect } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Loader, 
  Sparkles, 
  CheckCircle, 
  BookOpen, 
  Edit3, 
  Download, 
  LayoutTemplate,
  ArrowRight,
  Eye,
  RefreshCw,
  Plus,
  Trash2,
  FileBox,
  Network,
  ArrowRightCircle,
  Table
} from 'lucide-react';
import { DocumentSection, DocumentTemplate, DesignData } from '../types';
import { analyzeDocumentStructure, generateDocumentContent, saveHistory, generateTableArchitecture, generateProcessArchitecture } from '../services/geminiService';
import ArchitectureCanvas from './ArchitectureCanvas';

const DEFAULT_TEMPLATES: DocumentTemplate[] = [
    {
        id: 'hld',
        name: 'High Level Design (HLD)',
        description: 'Strategic overview of the system architecture.',
        sections: ['Executive Summary', 'Business Requirements', 'Solution Architecture', 'Technology Stack', 'Security & Compliance', 'Assumptions & Constraints']
    },
    {
        id: 'lld',
        name: 'Low Level Design (LLD)',
        description: 'Detailed component-level specifications.',
        sections: ['Component Specifications', 'Data Model (Schema)', 'API Interface Definitions', 'Error Handling', 'Logging & Monitoring', 'Deployment Specs']
    },
    {
        id: 'migration',
        name: 'Migration Strategy',
        description: 'Plan for moving data/apps from legacy to new systems.',
        sections: ['Current State Assessment', 'Migration Approach (Big Bang vs Phased)', 'Data Mapping Strategy', 'Cutover Plan', 'Rollback Strategy']
    }
];

const DocumentGenerator: React.FC = () => {
    // Phase Management: 'learn' | 'input' | 'dashboard'
    const [phase, setPhase] = useState<'learn' | 'input' | 'dashboard'>('learn');

    // Learning State
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('hld');
    const [customTemplate, setCustomTemplate] = useState<DocumentTemplate | null>(null);
    const [learningFiles, setLearningFiles] = useState<string[]>([]);
    const [isLearning, setIsLearning] = useState(false);

    // Input State
    const [projectContext, setProjectContext] = useState('');

    // Generation State
    const [generatedSections, setGeneratedSections] = useState<DocumentSection[]>([]);
    const [isGenerating, setIsGenerating] = useState(false);
    const [activeSectionId, setActiveSectionId] = useState<string | null>(null);

    // Diagram State
    const [diagramType, setDiagramType] = useState<'table' | 'process'>('table');
    const [archFlowDesign, setArchFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [dataFlowDesign, setDataFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [isDiagramGenerating, setIsDiagramGenerating] = useState(false);
    const [activeDashboardTab, setActiveDashboardTab] = useState<'text' | 'diagrams'>('text');

    // ---------------- HANDLERS: LEARNING PHASE ----------------

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setIsLearning(true);
            const fileNames = Array.from(e.target.files).map((f: any) => f.name).join(', ');
            setLearningFiles(prev => [...prev, ...Array.from(e.target.files!).map((f: any) => f.name)]);

            try {
                // Simulate file content reading by passing names (in real app, read FileReader)
                const structure = await analyzeDocumentStructure(`Files uploaded: ${fileNames}. Analyze these filenames and infer the typical structure of such solution documents.`);

                const newTemplate: DocumentTemplate = {
                    id: 'custom-learned',
                    name: 'Learned from Uploads',
                    description: `Structure derived from ${e.target.files.length} example files.`,
                    sections: structure
                };
                setCustomTemplate(newTemplate);
                setSelectedTemplateId('custom-learned');
            } catch (e) {
                console.error(e);
            } finally {
                setIsLearning(false);
            }
        }
    };

    const getActiveTemplate = () => {
        if (selectedTemplateId === 'custom-learned' && customTemplate) return customTemplate;
        return DEFAULT_TEMPLATES.find(t => t.id === selectedTemplateId) || DEFAULT_TEMPLATES[0];
    };

    const startInputPhase = () => {
        setPhase('input');
    };

    // ---------------- HANDLERS: INPUT PHASE ----------------

    const startGeneration = async () => {
        if (!projectContext.trim()) return;

        const template = getActiveTemplate();
        // Initialize sections
        const initialSections: DocumentSection[] = template.sections.map((title, idx) => ({
            id: `sec-${idx}`,
            title,
            content: '',
            status: 'pending'
        }));

        setGeneratedSections(initialSections);
        setPhase('dashboard');

        // Start sequential generation (in background)
        generateSectionsSequentially(initialSections, projectContext);

        // Start Diagram Generation
        generateDiagrams(projectContext);
    };

    const generateDiagrams = async (context: string) => {
        setIsDiagramGenerating(true);
        try {
            const arch = await generateTableArchitecture(context, "Infer schema and table architecture");
            setArchFlowDesign(arch);

            const data = await generateProcessArchitecture(context, "Infer data flow and processing steps");
            setDataFlowDesign(data);
        } catch (e) {
            console.error("Diagram generation failed", e);
        } finally {
            setIsDiagramGenerating(false);
        }
    };

    const generateSectionsSequentially = async (sections: DocumentSection[], context: string) => {
        const allHeaders = sections.map(s => s.title);
        const newSections = [...sections];

        for (let i = 0; i < newSections.length; i++) {
            // Update UI to show generating
            setActiveSectionId(newSections[i].id);
            setIsGenerating(true);

            const content = await generateDocumentContent(newSections[i].title, context, allHeaders);

            newSections[i] = { ...newSections[i], content, status: 'generated' };
            setGeneratedSections([...newSections]);
        }
        setIsGenerating(false);
        setActiveSectionId(null);
    };

    const handleRegenerateSection = async (sectionId: string) => {
        const idx = generatedSections.findIndex(s => s.id === sectionId);
        if (idx === -1) return;

        setActiveSectionId(sectionId);
        setIsGenerating(true);
        const newContent = await generateDocumentContent(generatedSections[idx].title, projectContext, generatedSections.map(s => s.title));

        const newSections = [...generatedSections];
        newSections[idx] = { ...newSections[idx], content: newContent, status: 'generated' };
        setGeneratedSections(newSections);
        setIsGenerating(false);
        setActiveSectionId(null);
    };

    const exportToWord = () => {
        const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Export HTML to Word Document with JavaScript</title></head><body>`;
        const footer = "</body></html>";

        let bodyHTML = `<h1>${getActiveTemplate().name}</h1>`;
        bodyHTML += `<p><strong>Client Context:</strong> ${projectContext.substring(0, 200)}...</p><hr/>`;

        // Append Diagrams if available (Placeholder text for Word as images are hard to embed via simple HTML)
        if (archFlowDesign.nodes.length > 0 || dataFlowDesign.nodes.length > 0) {
            bodyHTML += `<h2>Generated Diagrams</h2>`;
            if (archFlowDesign.nodes.length > 0) bodyHTML += `<p><em>[Architecture Flow Diagram Generated - See attached image]</em></p>`;
            if (dataFlowDesign.nodes.length > 0) bodyHTML += `<p><em>[Data Flow Diagram Generated - See attached image]</em></p>`;
            bodyHTML += `<hr/>`;
        }

        generatedSections.forEach(sec => {
            bodyHTML += `<h2>${sec.title}</h2>`;
            // Simple markdown-ish to HTML conversion
            let htmlContent = sec.content
                .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                .replace(/\n/g, '<br/>');
            bodyHTML += `<div>${htmlContent}</div><br/>`;
        });

        const sourceHTML = header + bodyHTML + footer;
        const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(sourceHTML);

        const fileDownload = document.createElement("a");
        document.body.appendChild(fileDownload);
        fileDownload.href = source;
        fileDownload.download = `solution_document_${Date.now()}.doc`;
        fileDownload.click();
        document.body.removeChild(fileDownload);
    };

    const handleRefineDiagram = (prompt: string) => {
        // Simple re-trigger for now
        if (diagramType === 'table') {
            setIsDiagramGenerating(true);
            generateTableArchitecture(projectContext + " " + prompt, "").then(d => {
                setArchFlowDesign(d);
                setIsDiagramGenerating(false);
            });
        } else {
            setIsDiagramGenerating(true);
            generateProcessArchitecture(projectContext + " " + prompt, "").then(d => {
                setDataFlowDesign(d);
                setIsDiagramGenerating(false);
            });
