                                        <div className="flex bg-white p-1 rounded-lg shadow-sm border border-slate-200">
                                            <button onClick={() => setDiagramType('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'table' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <Table size={14} /> Architecture Flow
                                            </button>
                                            <button onClick={() => setDiagramType('process')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'process' ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <ArrowRightCircle size={14} /> Data Flow
                                            </button>
                                        </div>
                                    </div>
                                    <div className="flex-1 relative">
                                        {isDiagramGenerating ? (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/50 backdrop-blur-sm z-30">
                                                <Loader size={32} className="animate-spin text-pink-500 mb-2"/>
                                                <p className="text-sm text-slate-500">Generating diagram...</p>
                                            </div>
                                        ) : (
                                            <ArchitectureCanvas 
                                                aiNodes={diagramType === 'table' ? archFlowDesign.nodes : dataFlowDesign.nodes} 
                                                aiEdges={diagramType === 'table' ? archFlowDesign.edges : dataFlowDesign.edges} 
                                                isThinking={false} 
                                                thoughts={[]} 
                                                context={projectContext}
                                                onRefine={handleRefineDiagram}
                                                refinementPlaceholder={`Refine ${diagramType === 'table' ? 'Architecture' : 'Data'} Flow...`}
                                            />
                                        )}
                                        {(!isDiagramGenerating && (diagramType === 'table' ? archFlowDesign.nodes.length === 0 : dataFlowDesign.nodes.length === 0)) && (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400">
                                                <Network size={48} className="mb-4 opacity-20" />
                                                <p>No diagram generated yet.</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                </div>
            </div>
        </div>
    );
};

