                                    <Download size={16} /> Download PPT
                                </button>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {generatedSlides.map((slide, idx) => (
                                    <div key={slide.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[300px]">
                                        <div className="bg-slate-50 border-b border-slate-100 p-4 flex justify-between items-center">
                                            <h4 className="font-bold text-slate-800 flex items-center gap-2">
                                                <span className="bg-slate-200 text-slate-600 text-[10px] w-5 h-5 rounded-full flex items-center justify-center">{idx + 1}</span>
                                                {slide.title}
                                            </h4>
                                            <button onClick={() => handleRegenerateSlide(idx)} className="text-slate-400 hover:text-orange-600" title="Regenerate Slide">
                                                <RefreshCw size={14} className={activeSlideIndex === idx ? 'animate-spin' : ''}/>
                                            </button>
                                        </div>
                                        <div className="p-6 flex-1 overflow-y-auto">
                                            <ul className="space-y-2 list-disc pl-4 text-sm text-slate-600">
                                                {slide.bulletPoints.map((bp, i) => (
                                                    <li key={i}>{bp}</li>
                                                ))}
                                            </ul>
                                        </div>
                                        <div className="bg-slate-50/50 p-3 border-t border-slate-100 text-xs text-slate-400 italic">
