export default DashboardView;

import React, { useState, useEffect } from 'react';
import { 
  Plus, 
  ArrowUpRight, 
  Search, 
  FileText,
  HelpCircle,
  X,
  Filter,
  Trash2,
  ArrowLeft
} from 'lucide-react';
import CreateForm from './CreateForm';
import { RequestData, UserProfile } from '../types';

interface DesignHubProps {
  requests: RequestData[];
  onRequestCreate: (data: any) => void;
  onSelectRequest: (req: RequestData) => void;
  onDeleteRequest: (id: string) => void;
  userProfile?: UserProfile;
  setHasUnsavedChanges: (val: boolean) => void; // New Prop
  handleSwitchTab: (tab: string) => void; // For Back navigation
}

const DesignHub: React.FC<DesignHubProps> = ({ 
  requests, 
  onRequestCreate, 
  onSelectRequest, 
  onDeleteRequest, 
  userProfile, 
  setHasUnsavedChanges,
  handleSwitchTab
}) => {
  const [view, setView] = useState<'list' | 'create'>('list');
  const [showHelp, setShowHelp] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Watch for view change to clean up dirty state
  useEffect(() => {
      if (view === 'list') {
          setHasUnsavedChanges(false);
      }
  }, [view, setHasUnsavedChanges]);

  // Pass this down to form to set dirty state when user types
  const handleFormDirty = (isDirty: boolean) => {
      setHasUnsavedChanges(isDirty);
  };

  const handleBackToOverview = () => {
      // Using handleSwitchTab here would trigger the global guard if dirty,
      // but we are staying within module. We need to manually check here or
      // leverage the global guard. For simpler UX, we can just switch views if clean.
      // But if we want consistent guard, we should use a method that checks dirty.
      // Since this is intra-module, we can just check local logic or set view.
      // Let's rely on the parent's guard for TAB switching, but simpler check here.
      setView('list');
  };

  const filteredRequests = requests.filter(r => 
    r.clientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.type.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusColor = (status: string) => {
      switch(status) {
          case 'Completed': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
          case 'In Progress': return 'bg-blue-100 text-blue-700 border-blue-200';
          default: return 'bg-slate-100 text-slate-600 border-slate-200';
      }
  };

  if (view === 'create') {
    return (
      <div className="relative">
        <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm sticky top-0 z-30">
            <button onClick={handleBackToOverview} className="text-sm font-bold text-slate-500 hover:text-slate-800 flex items-center gap-2">
                <ArrowLeft size={16}/> Back to Request List
            </button>
        </div>
        <CreateForm 
           onSubmit={(data) => {
             onRequestCreate(data);
             setView('list'); 
             setHasUnsavedChanges(false);
           }} 
           onCancel={() => {
               setView('list');
               setHasUnsavedChanges(false);
           }} 
           userProfile={userProfile}
           onDirtyChange={handleFormDirty} // Propagate dirty state
        />
        {/* Help Toggle on Create View too */}
        <button 
           onClick={() => setShowHelp(!showHelp)} 
           className="fixed bottom-6 left-6 z-40 bg-white p-3 rounded-full shadow-lg border border-slate-200 text-indigo-600 hover:text-indigo-800 transition-colors"
           title="Help & Context Guide"
        >
           <HelpCircle size={24} />
        </button>
        {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-indigo-500" /> Design Module Help</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>Input Types:</strong> This module works best with specific inputs to generate accurate solution blueprints.</p>
                    <ul className="list-disc pl-5 space-y-2">
                       <li><strong>RFP Documents (PDF/DOCX):</strong> Upload Request for Proposal documents to let AI extract requirements automatically.</li>
                       <li><strong>Architecture Questionnaires:</strong> Upload filled architecture scoping questionnaires.</li>
                       <li><strong>Natural Language:</strong> Describe the scope like "Migrate SAP to Snowflake".</li>
                    </ul>
                    <p className="bg-indigo-50 p-3 rounded-lg border border-indigo-100 text-indigo-800 text-xs">
                       <strong>Tip:</strong> The AI learns from previous inputs. If you have specific standards, mentioning them in the prompt helps (e.g., "Use naming convention X").
                    </p>
                 </div>
              </div>
           </div>
        )}
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 max-w-7xl mx-auto h-full flex flex-col relative animate-fade-in">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Solution Design Hub</h2>
          <p className="text-slate-500">Manage solution requests and generate new architecture blueprints.</p>
        </div>
        <div className="flex gap-3">
           <button onClick={() => setShowHelp(true)} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-600 bg-white border border-slate-200 rounded-lg hover:bg-slate-50">
             <HelpCircle size={16} /> Help
           </button>
           <button onClick={() => setView('create')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold shadow-md hover:bg-indigo-700 transition-all hover:scale-105">
             <Plus size={18} /> New Request
           </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm mb-6 flex items-center gap-4">
         <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search by client or technology..." 
              className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>
         <button className="p-2 text-slate-500 hover:bg-slate-100 rounded-lg"><Filter size={20} /></button>
      </div>

      {/* Request List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
          <div className="overflow-x-auto flex-1">
              <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-100">
                <tr>
                    <th className="px-6 py-4 font-semibold">Client Name</th>
                    <th className="px-6 py-4 font-semibold">Product / Tech Stack</th>
                    <th className="px-6 py-4 font-semibold">Status</th>
                    <th className="px-6 py-4 font-semibold">Files</th>
                    <th className="px-6 py-4 font-semibold">Date</th>
                    <th className="px-6 py-4 font-semibold text-right">Action</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                {filteredRequests.length === 0 ? (
                   <tr>
                      <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                         No requests found. Click "New Request" to start.
                      </td>
                   </tr>
                ) : (
                   filteredRequests.map((req, idx) => (
                    <tr key={idx} className="hover:bg-indigo-50/30 transition-colors cursor-pointer group" onClick={() => onSelectRequest(req)}>
                        <td className="px-6 py-4 font-bold text-slate-800">{req.clientName}</td>
                        <td className="px-6 py-4">
                            <div className="flex flex-col">
                                <span className="font-medium text-slate-700">{req.product}</span>
                                <span className="text-xs text-slate-500">{req.type}</span>
                            </div>
                        </td>
                        <td className="px-6 py-4">
                            <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${getStatusColor(req.status)}`}>
                                {req.status}
                            </span>
                        </td>
                        <td className="px-6 py-4 text-slate-500">
                           {req.rfpFiles.length > 0 ? (
                              <div className="flex items-center gap-1"><FileText size={14}/> {req.rfpFiles.length}</div>
                           ) : <span className="text-slate-300">-</span>}
                        </td>
                        <td className="px-6 py-4 text-slate-500">{req.date}</td>
                        <td className="px-6 py-4 text-right">
                            <div className="flex justify-end gap-2">
                                <button className="text-slate-400 group-hover:text-indigo-600 transition-colors bg-white p-2 rounded-full shadow-sm border border-slate-100"><ArrowUpRight size={18} /></button>
                                <button 
                                    className="text-slate-400 hover:text-red-500 transition-colors bg-white p-2 rounded-full shadow-sm border border-slate-100"
                                    onClick={(e) => { e.stopPropagation(); onDeleteRequest(req.id); }}
                                >
                                    <Trash2 size={18} />
                                </button>
                            </div>
                        </td>
                    </tr>
                   ))
                )}
                </tbody>
              </table>
          </div>
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-indigo-500" /> Design Module Help</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>Overview:</strong> The Design Hub is your central command for managing solution architecture requests.</p>
                    <p><strong>How to use:</strong></p>
                    <ul className="list-disc pl-5 space-y-2">
                       <li>Click <strong>New Request</strong> to start a new AI-driven design session.</li>
                       <li>Select an existing request to resume design, view estimations, or refine architecture.</li>
                       <li>Use the search bar to filter by client name or technology.</li>
                    </ul>
                 </div>
              </div>
           </div>
        )}
    </div>
  );
};

export default DesignHub;

import React, { useState, useEffect } from 'react';
import { 
  CloudLightning, 
  Loader, 
  CheckCircle, 
  UploadCloud, 
  Sparkles, 
  RefreshCw, 
  ArrowRight,
  Server,
  Cloud,
  Cpu,
  Users,
  Code2,
  ShieldAlert,
  Beaker,
  X,
  FileText,
  Database,
  Layers,
  Calculator,
  PenTool,
  MessageSquareText,
  FileUp,
  BrainCircuit
} from 'lucide-react';
import { AiSuggestion, UserProfile } from '../types';

interface CreateFormProps {
  onSubmit: (data: any) => void;
  onCancel: () => void;
  userProfile?: UserProfile;
  onDirtyChange?: (isDirty: boolean) => void; // New prop
}

// Configuration for Product Catalog
const BASE_CATALOG: Record<string, any> = {
  "Informatica": {
    "Cloud": [
      "Cloud Data Integration (CDI)", "Cloud Data Quality (CDQ)", "MDM SaaS", "Cloud Mass Ingestion", "Cloud Data Governance (CDGC)"
    ],
    "On-Premise": [
      "PowerCenter", "Informatica Data Quality (IDQ)", "MDM Multidomain", "Enterprise Data Catalog (EDC)"
    ]
  },
  "Talend": {
    "Cloud": [
      "Talend Cloud Data Integration", "Talend Pipeline Designer", "Stitch Data Loader"
    ],
    "On-Premise": [
      "Talend Open Studio", "Talend Data Fabric", "Talend ESB"
    ]
  },
  "Azure Data Factory": {
    "Cloud": [
      "Data Factory V2", "Synapse Analytics Pipelines", "Azure Purview"
    ],
    "On-Premise": [
      "SSIS (via IR)", "SQL Server Data Tools"
    ]
  },
  "Matillion": {
    "Cloud": [
      "Matillion for Snowflake", "Matillion for Redshift", "Matillion for Databricks"
    ],
    "On-Premise": [] 
  },
  "AWS Glue": {
    "Cloud": [
      "AWS Glue ETL", "AWS Glue DataBrew", "AWS Lake Formation"
    ],
    "On-Premise": []
  },
  "Profisee": {
    "Cloud": ["Profisee MDM SaaS", "Profisee Governance"],
    "On-Premise": ["Profisee Platform"]
  },
  "BigID": {
    "Cloud": ["BigID Data Discovery", "BigID Privacy", "BigID Security"],
    "On-Premise": ["BigID Enterprise"]
  },
  "Ataccama": {
    "Cloud": ["Ataccama ONE Gen2", "Data Quality Cloud", "MDM Cloud"],
    "On-Premise": ["Ataccama ONE On-Prem"]
  },
  "Databricks": {
    "Cloud": ["Delta Live Tables", "Unity Catalog", "Databricks SQL", "Workflows"],
    "On-Premise": []
  }
};

// Helper to aggregate services for HTC Solution
const aggregateServices = (deployment: 'Cloud' | 'On-Premise') => {
  const allServices: string[] = [];
  Object.values(BASE_CATALOG).forEach((prod: any) => {
    if (prod[deployment]) {
      allServices.push(...prod[deployment]);
    }
  });
  return Array.from(new Set(allServices)).sort();
};

const PRODUCT_CATALOG = {
  ...BASE_CATALOG,
  "HTC Enterprise Data Management": {
    "Cloud": aggregateServices("Cloud"),
    "On-Premise": aggregateServices("On-Premise")
  }
};

const CreateForm: React.FC<CreateFormProps> = ({ onSubmit, onCancel, userProfile, onDirtyChange }) => {
  const [formData, setFormData] = useState({
    clientName: '',
    rfpFiles: [] as string[],
    requirementsPrompt: '',
    product: '',
    deploymentModel: 'Cloud' as 'Cloud' | 'On-Premise',
    solutionType: '',
    targetAudience: ['Developer'] as string[], 
    description: '',
    priority: 'Normal'
  });

  const [inputType, setInputType] = useState<'upload' | 'prompt'>('upload');
  const [step, setStep] = useState<'input' | 'analyzing' | 'recommendation'>('input');
  const [isDragging, setIsDragging] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<AiSuggestion | null>(null);

  // Dynamic Options based on selection
  const [availableProducts] = useState<string[]>(Object.keys(PRODUCT_CATALOG).sort());
  const [availableDeployments, setAvailableDeployments] = useState<string[]>(['Cloud', 'On-Premise']);
  const [availableServices, setAvailableServices] = useState<string[]>([]);

  // Track dirty status
  useEffect(() => {
      const isDirty = formData.clientName !== '' || formData.requirementsPrompt !== '' || formData.rfpFiles.length > 0;
      if (onDirtyChange) onDirtyChange(isDirty);
  }, [formData, onDirtyChange]);

  // Apply User Profile Defaults
  useEffect(() => {
    if (userProfile && userProfile.preferences) {
        setFormData(prev => ({
            ...prev,
            product: prev.product || userProfile.preferences.defaultProduct || '',
            deploymentModel: (userProfile.preferences.defaultDeployment !== 'Hybrid' ? userProfile.preferences.defaultDeployment : 'Cloud') as any
        }));
    }
  }, [userProfile]);

  // Effect to update Deployment and Services based on Product selection
  useEffect(() => {
    if (formData.product && PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG]) {
      const productConfig = PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG];
      const validDeployments = Object.keys(productConfig).filter(k => productConfig[k].length > 0);
      setAvailableDeployments(validDeployments);

      // Reset deployment if current selection is invalid for new product
      if (!validDeployments.includes(formData.deploymentModel)) {
        setFormData(prev => ({ ...prev, deploymentModel: validDeployments[0] as any }));
      }
    } else {
      setAvailableDeployments([]);
      setAvailableServices([]);
    }
  }, [formData.product]);

  // Effect to update Services based on Deployment selection
  useEffect(() => {
    if (formData.product && formData.deploymentModel && PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG]) {
      const services = PRODUCT_CATALOG[formData.product as keyof typeof PRODUCT_CATALOG][formData.deploymentModel] || [];
      setAvailableServices(services);

      // Reset solution type if invalid
      if (!services.includes(formData.solutionType)) {
        setFormData(prev => ({ ...prev, solutionType: '' }));
      }
    }
  }, [formData.product, formData.deploymentModel]);

  const roles = [
    { id: 'Developer', label: 'Developer', icon: Code2, desc: 'Technical specs & mappings' },
    { id: 'Tester', label: 'Tester', icon: Beaker, desc: 'Test data & validation' },
    { id: 'Admin', label: 'Admin', icon: ShieldAlert, desc: 'Security & Infrastructure' }
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const toggleRole = (roleId: string) => {
    setFormData(prev => {
      const current = prev.targetAudience;
      if (current.includes(roleId)) {
        if (current.length === 1) return prev; 
        return { ...prev, targetAudience: current.filter(r => r !== roleId) };
      } else {
        return { ...prev, targetAudience: [...current, roleId] };
      }
    });
  };

  const handleDeploymentChange = (model: 'Cloud' | 'On-Premise') => {
    setFormData(prev => ({ ...prev, deploymentModel: model }));
  };

  const processFiles = (files: FileList) => {
    const newFileNames = Array.from(files).map(f => f.name);
    setFormData(prev => {
      const combined = [...prev.rfpFiles, ...newFileNames];
      return { ...prev, rfpFiles: combined.slice(0, 5) };
    });
  };

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files) processFiles(e.dataTransfer.files);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) processFiles(e.target.files);
  };

  const removeFile = (fileName: string) => {
    setFormData(prev => ({ ...prev, rfpFiles: prev.rfpFiles.filter(f => f !== fileName) }));
  };

  const handleAnalyze = () => {
    setStep('analyzing');
    setTimeout(() => {
      const combinedNames = formData.rfpFiles.join(' ').toLowerCase();
      const promptText = formData.requirementsPrompt.toLowerCase();

      // Inject User Preference into Analysis Context
      let userPrefContext = "";
      if (userProfile && userProfile.preferences.defaultProduct) {
          userPrefContext = ` [USER PREFERENCE CONTEXT: The user prefers '${userProfile.preferences.defaultProduct}' and '${userProfile.preferences.defaultDeployment}' deployment. Prioritize these unless requirements strictly contradict.]`;
      }

      const combinedContext = combinedNames + " " + promptText + userPrefContext;

      let suggestion: AiSuggestion | null = null;

      // Smart Product Detection Simulation with expanded patterns
      // Note: In a real implementation, we would send 'combinedContext' to the AI service.
      // Here we simulate the AI's "preference awareness".

      if (userProfile?.preferences.defaultProduct && !combinedContext.includes('azure') && !combinedContext.includes('aws') && !combinedContext.includes('talend')) {
          // If no specific tech mentioned in requirements, fallback to preference
          const pref = userProfile.preferences.defaultProduct;
          suggestion = {
            product: pref,
            deployment: userProfile.preferences.defaultDeployment === 'Hybrid' ? 'Cloud' : userProfile.preferences.defaultDeployment,
            type: "Recommended Platform",
            reason: `Requirements align with your preferred stack: ${pref}.`,
            details: ["Aligned with User Profile.", "Standard Reference Architecture."]
          };
      } else if (combinedContext.includes('azure') || combinedContext.includes('factory') || combinedContext.includes('synapse')) {
         suggestion = {
            product: 'Azure Data Factory',
            deployment: 'Cloud',
            type: "Data Factory V2",
            reason: "Detected Azure ecosystem terms (ADF, Synapse) in input.",
            details: ["Source: Azure Blob.", "Target: Synapse Analytics."]
         };
      } else if (combinedContext.includes('talend') || combinedContext.includes('studio') || combinedContext.includes('fabric')) {
         suggestion = {
            product: 'Talend',
            deployment: 'Cloud',
            type: "Talend Cloud Data Integration",
            reason: "Detected Talend Data Fabric terminology.",
            details: ["Pattern: Remote Engine.", "Transformation: TMC/Pipeline Designer."]
         };
      } else if (combinedContext.includes('databricks') || combinedContext.includes('delta') || combinedContext.includes('medallion')) {
         suggestion = {
            product: 'Databricks',
            deployment: 'Cloud',
            type: "Unity Catalog",
            reason: "Detected Databricks Lakehouse & Medallion Architecture terms.",
            details: ["Pattern: Bronze/Silver/Gold Layers.", "Governance: Unity Catalog."]
         };
      } else if (combinedContext.includes('profisee') || combinedContext.includes('golden record')) {
         suggestion = {
            product: 'Profisee',
            deployment: 'Cloud',
            type: "Profisee MDM SaaS",
            reason: "Detected Golden Record management requirements typical of Profisee MDM.",
            details: ["Pattern: Match & Merge.", "Governance: Stewardship Portal."]
         };
      } else if (combinedContext.includes('mainframe') || combinedContext.includes('cobol')) {
         suggestion = {
            product: 'Informatica',
            deployment: 'On-Premise',
            type: "PowerCenter",
            reason: "Detected Legacy Mainframe sources requiring robust on-prem connectivity.",
            details: ["Source: Cobol Copybook.", "Security: Data Residency/On-Prem Agent."]
         };
      } else if (combinedContext.includes('privacy') || combinedContext.includes('discovery') || combinedContext.includes('bigid')) {
         suggestion = {
            product: 'BigID',
            deployment: 'Cloud',
            type: "BigID Data Discovery",
            reason: "Detected Privacy/PII scanning requirements.",
            details: ["Focus: Sensitive Data Discovery.", "Integration: Connector Framework."]
         };
      } else {
         suggestion = {
            product: 'Informatica',
            deployment: 'Cloud',
            type: "Cloud Data Integration (CDI)",
            reason: "Standard Enterprise Cloud Modernization pattern detected.",
            details: ["Target: Cloud Data Warehouse.", "Pattern: ELT/ETL Modernization."]
         };
      }
      setAiSuggestion(suggestion);
      setStep('recommendation');
    }, 2500);
  };

  const acceptRecommendation = () => {
    if (aiSuggestion) {
      setFormData(prev => ({
        ...prev,
        product: aiSuggestion.product,
        deploymentModel: aiSuggestion.deployment as any,
        solutionType: aiSuggestion.type
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Inject user preference into prompt for downstream consumption if not already explicitly stated
    let refinedPrompt = formData.requirementsPrompt;
    if (userProfile && !refinedPrompt.toLowerCase().includes('prefer')) {
        refinedPrompt += `\n[System Note: User Preference is ${userProfile.preferences.defaultProduct} on ${userProfile.preferences.defaultDeployment}. Consider this in design generation.]`;
    }

    onSubmit({
      clientName: formData.clientName,
      product: formData.product,
      deploymentModel: formData.deploymentModel,
      type: formData.solutionType,
      rfpFiles: formData.rfpFiles,
      requirementsPrompt: refinedPrompt,
      targetAudience: formData.targetAudience,
      date: new Date().toLocaleDateString(),
      mode: 'design'
    });
  };

  const isFormValid = () => {
    const hasInput = inputType === 'upload' ? formData.rfpFiles.length > 0 : formData.requirementsPrompt.length > 20;
    return formData.clientName && hasInput;
  };

  return (
    <div className="p-6 md:p-8 max-w-6xl mx-auto animate-fade-in h-full flex flex-col">
      <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">
             New Solution Request
           </h2>
           <p className="text-slate-500">
             Design comprehensive architecture and technical specifications with AI.
           </p>
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 flex flex-col">
          <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 md:p-8 flex-1 flex flex-col relative overflow-hidden">
            {/* Top accent bar */}
            <div className="absolute top-0 left-0 right-0 h-1 bg-indigo-500"></div>

            <div className="space-y-6 flex-1">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">
                  Client Name <span className="text-red-500">*</span>
                </label>
