                                    </button>
                                ))}

                                {/* Custom / Learned Template */}
                                <div className={`relative p-6 rounded-xl border-2 border-dashed flex flex-col items-center justify-center text-center transition-all ${selectedTemplateId === 'custom-learned' ? 'border-indigo-500 bg-indigo-50' : 'border-slate-300 hover:bg-slate-50'}`}>
