                                        <div className="w-full text-left" onClick={() => setSelectedTemplateId('custom-learned')}>
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-slate-800 mb-2">{customTemplate.name}</h4>
                                                <span className="bg-pink-100 text-pink-700 text-[10px] font-bold px-2 py-1 rounded-full">AI Learned</span>
