                                    Next: Define Context <ArrowRight size={18} />
                                </button>
                            </div>
                        </div>
                    )}

                    {/* PHASE 2: CONTEXT INPUT */}
                    {phase === 'input' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 animate-fade-in-up">
                            <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2"><Edit3 size={20} className="text-blue-500"/> Project Context</h3>
                            <div className="mb-6">
                                <div className="flex items-center gap-3 mb-2">
                                    <div className="p-2 bg-slate-100 rounded-lg"><FileBox size={16} className="text-slate-600"/></div>
                                    <span className="text-sm font-medium text-slate-700">Selected Template: <span className="font-bold text-indigo-600">{getActiveTemplate().name}</span></span>
                                </div>
                                <div className="h-px bg-slate-100 w-full mb-6"></div>
                                <label className="block text-sm font-bold text-slate-700 mb-2">Describe the Solution</label>
                                <p className="text-xs text-slate-500 mb-3">Provide technical details, scope, constraints, and preferred technologies. The more detail, the better the document.</p>
                                <textarea 
                                    value={projectContext}
                                    onChange={(e) => setProjectContext(e.target.value)}
                                    className="w-full h-64 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm leading-relaxed"
                                    placeholder="e.g. This project aims to migrate an on-premise Oracle Data Warehouse to Snowflake on AWS. We need to use Informatica IDMC for ETL. Key constraints include GDPR compliance for customer data..."
                                />
                            </div>
                            <div className="flex justify-between">
                                <button onClick={() => setPhase('learn')} className="text-slate-500 font-medium text-sm hover:text-slate-800">Back</button>
                                <button 
                                    onClick={startGeneration} 
                                    disabled={!projectContext.trim()}
                                    className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 shadow-lg transition-transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <Sparkles size={18} /> Generate Document
                                </button>
                            </div>
                        </div>
                    )}

                    {/* PHASE 3: DASHBOARD / PREVIEW */}
                    {phase === 'dashboard' && (
                        <div className="animate-fade-in-up space-y-6">
                            <div className="flex justify-between items-center">
                                <div className="flex items-center gap-4">
                                    <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><BookOpen size={20} className="text-indigo-500"/> Document Dashboard</h3>
                                    {/* Dashboard Tabs */}
                                    <div className="flex bg-slate-100 p-1 rounded-lg">
                                        <button onClick={() => setActiveDashboardTab('text')} className={`px-4 py-1 text-xs font-bold rounded-md transition-all ${activeDashboardTab === 'text' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Document Text</button>
                                        <button onClick={() => setActiveDashboardTab('diagrams')} className={`px-4 py-1 text-xs font-bold rounded-md transition-all ${activeDashboardTab === 'diagrams' ? 'bg-white text-pink-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Technical Diagrams</button>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    {isGenerating && <div className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full animate-pulse"><Loader size={12} className="animate-spin"/> AI Writer Active</div>}
                                    <span className="text-xs text-slate-500 font-medium hidden md:inline">Template: {getActiveTemplate().name}</span>
                                </div>
                            </div>

                            {activeDashboardTab === 'text' ? (
                                <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                                    {/* Sidebar Navigation */}
                                    <div className="lg:col-span-1 space-y-2">
                                        {generatedSections.map((sec, idx) => (
                                            <button 
                                                key={sec.id}
                                                onClick={() => document.getElementById(sec.id)?.scrollIntoView({ behavior: 'smooth' })}
                                                className={`w-full text-left p-3 rounded-lg text-xs font-medium flex justify-between items-center transition-all ${sec.status === 'generated' ? 'bg-white border border-slate-200 text-slate-700 hover:border-indigo-300' : 'bg-slate-50 border border-transparent text-slate-400'}`}
                                            >
                                                <span className="truncate">{idx + 1}. {sec.title}</span>
                                                {sec.status === 'generated' ? <CheckCircle size={14} className="text-emerald-500"/> : activeSectionId === sec.id ? <Loader size={14} className="animate-spin text-indigo-500"/> : <div className="w-3 h-3 rounded-full bg-slate-200"></div>}
                                            </button>
                                        ))}
                                        <div className="pt-4 border-t border-slate-200 mt-4">
                                            <button onClick={() => setPhase('input')} className="w-full text-center text-xs text-slate-500 hover:text-indigo-600">Edit Context</button>
                                        </div>
                                    </div>

                                    {/* Content Area */}
                                    <div className="lg:col-span-3 space-y-6">
                                        {generatedSections.map((sec) => (
                                            <div key={sec.id} id={sec.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden scroll-mt-24">
                                                <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                                                    <h4 className="font-bold text-slate-800">{sec.title}</h4>
                                                    <div className="flex gap-2">
                                                        <button onClick={() => handleRegenerateSection(sec.id)} className="p-1.5 hover:bg-white rounded-md text-slate-400 hover:text-indigo-600 transition-colors" title="Regenerate Section">
                                                            <RefreshCw size={14} className={activeSectionId === sec.id ? 'animate-spin' : ''} />
                                                        </button>
                                                    </div>
                                                </div>
                                                <div className="p-6 min-h-[150px]">
                                                    {sec.status === 'pending' ? (
                                                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                                                            {activeSectionId === sec.id ? (
                                                                <>
                                                                    <Loader size={24} className="animate-spin mb-2 text-indigo-400"/>
                                                                    <p className="text-xs">Generating content...</p>
                                                                </>
                                                            ) : (
                                                                <p className="text-xs">Waiting in queue...</p>
                                                            )}
                                                        </div>
                                                    ) : (
                                                        <div className="prose prose-sm max-w-none text-slate-600">
                                                            {sec.content.split('\n').map((line, i) => (
                                                                <p key={i} className="mb-2">{line.replace(/^\*\*(.*?)\*\*$/, '$1')}</p> 
                                                            ))}
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ) : (
                                // Diagram View
                                <div className="h-[600px] bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden">
                                    <div className="bg-slate-50 border-b border-slate-200 p-2 flex justify-center sticky top-0 items-center gap-4 z-20">
                                        <div className="flex bg-white p-1 rounded-lg shadow-sm border border-slate-200">
                                            <button onClick={() => setDiagramType('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'table' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <Table size={14} /> Architecture Flow
                                            </button>
                                            <button onClick={() => setDiagramType('process')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'process' ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <ArrowRightCircle size={14} /> Data Flow
                                            </button>
                                        </div>
                                    </div>
                                    <div className="flex-1 relative">
                                        {isDiagramGenerating ? (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/50 backdrop-blur-sm z-30">
                                                <Loader size={32} className="animate-spin text-pink-500 mb-2"/>
                                                <p className="text-sm text-slate-500">Generating diagram...</p>
                                            </div>
                                        ) : (
                                            <ArchitectureCanvas 
                                                aiNodes={diagramType === 'table' ? archFlowDesign.nodes : dataFlowDesign.nodes} 
                                                aiEdges={diagramType === 'table' ? archFlowDesign.edges : dataFlowDesign.edges} 
                                                isThinking={false} 
                                                thoughts={[]} 
                                                context={projectContext}
                                                onRefine={handleRefineDiagram}
                                                refinementPlaceholder={`Refine ${diagramType === 'table' ? 'Architecture' : 'Data'} Flow...`}
                                            />
                                        )}
                                        {(!isDiagramGenerating && (diagramType === 'table' ? archFlowDesign.nodes.length === 0 : dataFlowDesign.nodes.length === 0)) && (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400">
                                                <Network size={48} className="mb-4 opacity-20" />
                                                <p>No diagram generated yet.</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                </div>
            </div>
        </div>
    );
};

export default DocumentGenerator;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import DashboardView from './components/Dashboard';
import DesignHub from './components/DesignHub';
import SolutionDesignView from './components/SolutionDesign';
import StandaloneEstimator from './components/StandaloneEstimator';
import StandaloneArchitecture from './components/StandaloneArchitecture';
import StandaloneDataFlow from './components/StandaloneDataFlow';
import StandaloneDataQuality from './components/StandaloneDataQuality';
import StandaloneERDiagram from './components/StandaloneERDiagram';
import DocumentGenerator from './components/DocumentGenerator';
import CaseStoryGenerator from './components/CaseStoryGenerator';
import LoginPage from './components/LoginPage';
import UserGuide from './components/UserGuide';
import UserProfileModal from './components/UserProfileModal';
import { RequestData, DesignCache, UserProfile } from './types';
import { AlertTriangle, X } from 'lucide-react';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Tabs: 'dashboard' | 'design-module' | 'design' | 'doc-generator' | 'case-story' | 'adhoc-estimator' | 'adhoc-architecture' | 'adhoc-dataflow' | 'adhoc-dq' | 'adhoc-er'
  const [activeTab, setActiveTab] = useState('dashboard');

  const [selectedRequest, setSelectedRequest] = useState<RequestData | null>(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [designCache, setDesignCache] = useState<DesignCache>({});
  const [showGuide, setShowGuide] = useState(false);

  // Navigation Guard State
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [showNavigationAlert, setShowNavigationAlert] = useState(false);
  const [pendingTab, setPendingTab] = useState<string | null>(null);

  // User Profile State
  const [showProfile, setShowProfile] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile>({
    name: 'Alex Architect',
    email: 'alex.arch@data.inc',
    role: 'Senior Solution Architect',
    preferences: {
      defaultProduct: '',
      defaultDeployment: 'Cloud'
    }
  });

  // Mock Data
  const [requests, setRequests] = useState<RequestData[]>([
    {
      id: 'REQ-1005',
      clientName: 'HealthCare Plus',
      product: 'Databricks',
      deploymentModel: 'Cloud',
      type: 'Unity Catalog',
      rfpFiles: ['lakehouse_governance_rfp.pdf', 'hipaa_compliance.docx'],
      targetAudience: ['Admin', 'Developer'],
      date: '10/27/2023',
      status: 'In Progress'
    },
    {
      id: 'REQ-1004',
      clientName: 'City Gov Dept',
      product: 'Profisee',
      deploymentModel: 'Cloud',
      type: 'Profisee MDM SaaS',
      rfpFiles: ['citizen_360_requirements.pdf'],
      targetAudience: ['Developer'],
      date: '10/26/2023',
      status: 'Not Started'
    },
    {
      id: 'REQ-1003',
      clientName: 'Tech StartUp',
      product: 'Azure Data Factory',
      deploymentModel: 'Cloud',
      type: 'Data Factory V2',
      rfpFiles: ['analytics_pipeline.pdf'],
      targetAudience: ['Developer'],
      date: '10/26/2023',
      status: 'Completed'
    },
    {
      id: 'REQ-1002',
      clientName: 'Retail Giant',
      product: 'Informatica',
      deploymentModel: 'Cloud',
      type: 'MDM SaaS',
      rfpFiles: ['customer_360_view.docx', 'requirements_v2.pdf'],
      targetAudience: ['Developer', 'Tester'],
      date: '10/25/2023',
      status: 'Completed'
    },
    {
      id: 'REQ-1001',
      clientName: 'Global FinCorp',
      product: 'Informatica',
      deploymentModel: 'On-Premise',
      type: 'PowerCenter',
      rfpFiles: ['mainframe_migration_rfp.pdf'],
      targetAudience: ['Developer', 'Admin'],
      date: '10/24/2023',
      status: 'Completed'
    }
  ]);
  const [nextId, setNextId] = useState(1006);

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  // Safe Navigation Handler
  const handleSwitchTab = (tab: string) => {
      if (hasUnsavedChanges) {
          setPendingTab(tab);
          setShowNavigationAlert(true);
      } else {
          setActiveTab(tab);
      }
  };

  const confirmNavigation = () => {
      if (pendingTab) {
          setActiveTab(pendingTab);
          setHasUnsavedChanges(false);
          setShowNavigationAlert(false);
          setPendingTab(null);
      }
  };

  const cancelNavigation = () => {
      setShowNavigationAlert(false);
      setPendingTab(null);
  };

  const handleCreateSubmit = (newRequest: any) => {
    const requestWithId: RequestData = {
      ...newRequest,
      id: `REQ-${nextId}`,
      status: 'Not Started'
    };
    setRequests([requestWithId, ...requests]);
    setNextId(prev => prev + 1);

    // Auto-redirect to design view for the new request
    setSelectedRequest(requestWithId);
    setActiveTab('design');
    setHasUnsavedChanges(false); // Reset dirty flag after creation
  };

  const handleSelectRequest = (req: RequestData) => {
    // Check for unsaved changes before switching contexts
    if (hasUnsavedChanges) {
        // Simple alert for intra-dashboard switches for now, or assume this is handled by tab switching if view changes
        if(!confirm("You have unsaved changes. Discard them?")) return;
        setHasUnsavedChanges(false);
    }
    setSelectedRequest(req);
    setActiveTab('design');
  };

  const handleDeleteRequest = (id: string) => {
    if (confirm("Are you sure you want to delete this request?")) {
        setRequests(prev => prev.filter(r => r.id !== id));
        if (selectedRequest?.id === id) {
            setSelectedRequest(null);
            setActiveTab('design-module');
        }
    }
  };

  const handleUpdateDesignCache = (reqId: string, designData: any) => {
    setDesignCache(prev => ({
      ...prev,
      [reqId]: designData
    }));
  };

  const handleUpdateRequestStatus = (reqId: string, status: 'Not Started' | 'In Progress' | 'Completed') => {
      setRequests(prev => prev.map(req => req.id === reqId ? { ...req, status } : req));
      if (selectedRequest && selectedRequest.id === reqId) {
          setSelectedRequest(prev => prev ? { ...prev, status } : null);
      }
  };

  if (!isLoggedIn) {
    return <LoginPage onLogin={handleLogin} />;
  }

  // Determine header title based on active tab
  const getHeaderTitle = () => {
    switch(activeTab) {
      case 'dashboard': return 'System Dashboard';
      case 'design-module': return 'Solution Designer';
      case 'design': return `Design: ${selectedRequest?.id || ''}`;
      case 'doc-generator': return 'Document Generator';
      case 'case-story': return 'Case Story Generator';
      case 'adhoc-estimator': return 'Smart Project Estimator';
      case 'adhoc-architecture': return 'Architecture Flow Designer';
      case 'adhoc-dataflow': return 'Data Flow Designer';
      case 'adhoc-dq': return 'Data Quality Studio';
      case 'adhoc-er': return 'ER Diagram Generator';
      default: return 'DataArch AI Platform';
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden relative">

      {/* Global Navigation Alert Modal */}
      {showNavigationAlert && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in p-4">
              <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 relative border border-slate-200">
                  <div className="flex items-center gap-3 text-red-600 mb-4">
                      <div className="p-2 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
                      <h3 className="text-lg font-bold">Unsaved Changes</h3>
                  </div>
                  <p className="text-slate-600 text-sm mb-6 leading-relaxed">
                      You have unsaved work in progress. If you navigate away now, your current changes will be lost.
                  </p>
                  <div className="flex gap-3 justify-end">
                      <button 
                          onClick={cancelNavigation} 
                          className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg text-sm transition-colors"
                      >
                          Continue Editing
                      </button>
                      <button 
                          onClick={confirmNavigation} 
                          className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-bold rounded-lg text-sm transition-colors shadow-md"
                      >
                          Discard & Leave
                      </button>
                  </div>
              </div>
          </div>
      )}

      <Sidebar 
        activeTab={activeTab === 'design' ? 'design-module' : activeTab} 
        setActiveTab={setActiveTab} // Keeping for internal simple switches if needed
        handleSwitchTab={handleSwitchTab} // Use this for protected switches
        isMobileOpen={isMobileOpen}
        setIsMobileOpen={setIsMobileOpen}
        onLogout={handleLogout}
        userProfile={userProfile}
        onOpenProfile={() => setShowProfile(true)}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <Header 
          title={getHeaderTitle()} 
          toggleSidebar={() => setIsMobileOpen(true)}
          onOpenGuide={() => setShowGuide(true)}
        />

        <main className="flex-1 overflow-y-auto relative scroll-smooth bg-slate-50">

          <UserGuide isOpen={showGuide} onClose={() => setShowGuide(false)} />
          <UserProfileModal 
             isOpen={showProfile}
             onClose={() => setShowProfile(false)}
             profile={userProfile}
             onSave={(p) => setUserProfile(p)}
          />

          <div className={`h-full ${activeTab === 'dashboard' ? 'block' : 'hidden'}`}>
            <DashboardView 
                requests={requests} 
                onSelectRequest={handleSelectRequest} 
                onDeleteRequest={handleDeleteRequest}
                setActiveTab={setActiveTab}
                handleSwitchTab={handleSwitchTab}
            />
          </div>

          <div className={`h-full ${activeTab === 'design' ? 'block' : 'hidden'}`}>
             <SolutionDesignView 
               request={selectedRequest} 
               designCache={designCache}
               onUpdateDesignCache={handleUpdateDesignCache}
               onUpdateRequestStatus={handleUpdateRequestStatus}
             />
          </div>

          <div className={`h-full ${activeTab === 'design-module' ? 'block' : 'hidden'}`}>
            <DesignHub 
              requests={requests}
              onRequestCreate={handleCreateSubmit} 
              onSelectRequest={handleSelectRequest}
              onDeleteRequest={handleDeleteRequest}
              userProfile={userProfile}
              setHasUnsavedChanges={setHasUnsavedChanges}
              handleSwitchTab={handleSwitchTab}
            />
          </div>

          <div className={`h-full ${activeTab === 'doc-generator' ? 'block' : 'hidden'}`}>
            <DocumentGenerator setHasUnsavedChanges={setHasUnsavedChanges} />
          </div>

          <div className={`h-full ${activeTab === 'case-story' ? 'block' : 'hidden'}`}>
            <CaseStoryGenerator setHasUnsavedChanges={setHasUnsavedChanges} />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-estimator' ? 'block' : 'hidden'}`}>
            <StandaloneEstimator />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-architecture' ? 'block' : 'hidden'}`}>
            <StandaloneArchitecture />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-dataflow' ? 'block' : 'hidden'}`}>
            <StandaloneDataFlow />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-dq' ? 'block' : 'hidden'}`}>
            <StandaloneDataQuality />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-er' ? 'block' : 'hidden'}`}>
            <StandaloneERDiagram />
          </div>

        </main>
      </div>
    </div>
  );
};

export default App;

