declare const PptxGenJS: any;

interface CaseStoryGeneratorProps {
  setHasUnsavedChanges: (val: boolean) => void;
}

const DEFAULT_PPT_TEMPLATES: CaseStoryTemplate[] = [
    {
        id: 'standard',
        name: 'Standard Case Study',
        description: 'Classic 4-slide structure: Challenge, Solution, Result.',
        slides: [
            { title: "Project Overview", description: "Client background and high-level summary." },
            { title: "Business Challenges", description: "Pain points, legacy issues, and drivers." },
            { title: "Solution Architecture", description: "Tech stack, design patterns, and implementation." },
            { title: "Outcomes & Benefits", description: "ROI, performance gains, and future value." }
        ]
    },
    {
        id: 'technical',
        name: 'Technical Deep Dive',
        description: 'Focus on architecture, data flows, and engineering.',
        slides: [
            { title: "Technical Context", description: "Existing landscape and technical constraints." },
            { title: "Architecture Design", description: "Detailed diagram explanation and component breakdown." },
            { title: "Data Flow & Logic", description: "ETL/ELT processes and transformation logic." },
            { title: "Tech Stack & Tools", description: "List of technologies and their roles." }
        ]
    }
];

const CaseStoryGenerator: React.FC<CaseStoryGeneratorProps> = ({ setHasUnsavedChanges }) => {
    const [phase, setPhase] = useState<'learn' | 'input' | 'dashboard'>('learn');

    // Learning
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('standard');
    const [customTemplate, setCustomTemplate] = useState<CaseStoryTemplate | null>(null);
    const [isLearning, setIsLearning] = useState(false);

    // Input
    const [projectContext, setProjectContext] = useState('');

    // Generation
    const [generatedSlides, setGeneratedSlides] = useState<SlideContent[]>([]);
    const [isGenerating, setIsGenerating] = useState(false);
    const [activeSlideIndex, setActiveSlideIndex] = useState<number | null>(null);

    // Update dirty state
    useEffect(() => {
        if (projectContext.trim().length > 0 && phase !== 'dashboard') {
            setHasUnsavedChanges(true);
        } else {
            setHasUnsavedChanges(false);
        }
    }, [projectContext, phase, setHasUnsavedChanges]);

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setIsLearning(true);
            const fileNames = Array.from(e.target.files).map((f: any) => f.name).join(', ');

            try {
                // Simulate context from file names for the "Learning" prompt
                const structure = await analyzePPTStructure(`Uploaded PPT Files: ${fileNames}. Extract the slide sequence.`);

                const newTemplate: CaseStoryTemplate = {
                    id: 'custom-learned',
                    name: 'Learned from Uploads',
                    description: `Structure derived from ${e.target.files.length} presentation files.`,
                    slides: structure
                };
                setCustomTemplate(newTemplate);
                setSelectedTemplateId('custom-learned');
            } catch (e) {
                console.error(e);
            } finally {
                setIsLearning(false);
            }
        }
    };

    const getActiveTemplate = () => {
        if (selectedTemplateId === 'custom-learned' && customTemplate) return customTemplate;
        return DEFAULT_PPT_TEMPLATES.find(t => t.id === selectedTemplateId) || DEFAULT_PPT_TEMPLATES[0];
    };

    const startGeneration = async () => {
        if (!projectContext.trim()) return;

        const template = getActiveTemplate();
        setPhase('dashboard');
        setGeneratedSlides([]);
        setHasUnsavedChanges(false); // Reset dirty flag once generated (or keep true if we consider generated content unsaved)

        const slides: SlideContent[] = [];

        // Progressive generation
        for (let i = 0; i < template.slides.length; i++) {
            setActiveSlideIndex(i);
            setIsGenerating(true);
            const slideContent = await generateSlideContent(template.slides[i], projectContext);
            slides.push(slideContent);
            setGeneratedSlides([...slides]);
        }
        setIsGenerating(false);
        setActiveSlideIndex(null);
    };

    const handleRegenerateSlide = async (index: number) => {
        const template = getActiveTemplate();
        setActiveSlideIndex(index);
        setIsGenerating(true);
        const newContent = await generateSlideContent(template.slides[index], projectContext);

        const updated = [...generatedSlides];
        updated[index] = newContent;
        setGeneratedSlides(updated);

        setIsGenerating(false);
        setActiveSlideIndex(null);
    };

    const exportToPPT = () => {
        if (typeof PptxGenJS === 'undefined') {
            alert("PPT Generator library not loaded.");
            return;
        }

        const pptx = new PptxGenJS();
        pptx.layout = 'LAYOUT_16x9';

        // Master Slide / Theme
        pptx.defineSlideMaster({
            title: 'MASTER_SLIDE',
            background: { color: 'F1F5F9' },
            objects: [
                { rect: { x: 0, y: 0, w: '100%', h: 0.75, fill: '4F46E5' } }, // Header Bar
                { text: { text: 'Case Story', options: { x: 0.5, y: 0.15, w: 9, h: 0.5, fontSize: 20, color: 'FFFFFF', bold: true } } },
                { rect: { x: 0, y: 6.9, w: '100%', h: 0.6, fill: 'FFFFFF' } }, // Footer
                { text: { text: 'Generated by DataArch AI', options: { x: 0.5, y: 7.0, w: 5, h: 0.4, fontSize: 10, color: '64748B' } } }
            ]
        });

        // Title Slide
        let slide = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
        slide.addText(getActiveTemplate().name, { x: 1, y: 2.5, w: 8, h: 1, fontSize: 36, color: '1E293B', bold: true, align: 'center' });
        slide.addText(`Client Context: ${projectContext.substring(0, 50)}...`, { x: 1.5, y: 3.5, w: 7, h: 0.5, fontSize: 18, color: '64748B', align: 'center' });

        // Content Slides
        generatedSlides.forEach(s => {
            slide = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
            // Slide Title
            slide.addText(s.title, { x: 0.5, y: 1, w: 9, h: 0.8, fontSize: 28, color: '1E293B', bold: true });

            // Bullet Points
            const bullets = s.bulletPoints.map(bp => ({ text: bp, options: { fontSize: 16, color: '334155', bullet: true, breakLine: true } }));
            slide.addText(bullets, { x: 0.5, y: 2, w: 9, h: 4, lineSpacing: 32 });

            // Speaker Notes
            slide.addNotes(s.speakerNotes);
        });

        pptx.writeFile({ fileName: `Case_Story_${Date.now()}.pptx` });
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Presentation size={20}/></div>
                    <div>
                        <h2 className="font-bold text-slate-800">Case Story PPT Generator</h2>
                        <p className="text-xs text-slate-500">AI-Powered Slide Deck Creator</p>
                    </div>
                </div>
                {phase !== 'learn' && (
                    <button onClick={() => setPhase('learn')} className="text-xs font-bold text-slate-500 hover:text-slate-700 flex items-center gap-1">
                        <ArrowLeft size={14}/> Back to Templates
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-y-auto p-6 md:p-8">
                <div className="max-w-6xl mx-auto space-y-8">

                    {/* Stepper */}
                    <div className="flex items-center justify-center mb-8">
                        <div className={`flex items-center gap-2 ${phase === 'learn' ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">1</div>
                            <span>Template</span>
                        </div>
                        <div className="w-16 h-0.5 bg-slate-200 mx-4"></div>
                        <div className={`flex items-center gap-2 ${phase === 'input' ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">2</div>
                            <span>Context</span>
                        </div>
                        <div className="w-16 h-0.5 bg-slate-200 mx-4"></div>
                        <div className={`flex items-center gap-2 ${phase === 'dashboard' ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">3</div>
                            <span>Preview</span>
                        </div>
                    </div>

                    {/* PHASE 1: LEARN */}
                    {phase === 'learn' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 animate-fade-in-up">
                            <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2"><Layout size={20} className="text-orange-500"/> Select Slide Structure</h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                                {DEFAULT_PPT_TEMPLATES.map(t => (
                                    <button 
                                        key={t.id}
                                        onClick={() => setSelectedTemplateId(t.id)}
                                        className={`text-left p-6 rounded-xl border-2 transition-all ${selectedTemplateId === t.id ? 'border-orange-500 bg-orange-50 shadow-md' : 'border-slate-100 hover:border-orange-200 hover:bg-slate-50'}`}
                                    >
                                        <h4 className="font-bold text-slate-800 mb-2">{t.name}</h4>
                                        <p className="text-sm text-slate-500 mb-4">{t.description}</p>
                                        <div className="space-y-1">
                                            {t.slides.map((s, i) => (
                                                <div key={i} className="text-xs text-slate-600 flex items-center gap-2"><div className="w-1.5 h-1.5 bg-slate-300 rounded-full"></div> {s.title}</div>
                                            ))}
                                        </div>
                                    </button>
                                ))}

                                {/* Custom / Learned */}
                                <div className={`relative p-6 rounded-xl border-2 border-dashed flex flex-col items-center justify-center text-center transition-all ${selectedTemplateId === 'custom-learned' ? 'border-orange-500 bg-orange-50' : 'border-slate-300 hover:bg-slate-50'}`}>
                                    {isLearning ? (
                                        <div className="space-y-3">
                                            <Loader size={24} className="animate-spin text-orange-600 mx-auto"/>
                                            <p className="text-sm font-bold text-orange-700">Analyzing Slides...</p>
                                        </div>
                                    ) : customTemplate ? (
                                        <div className="w-full text-left" onClick={() => setSelectedTemplateId('custom-learned')}>
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-slate-800 mb-2">{customTemplate.name}</h4>
                                                <span className="bg-orange-100 text-orange-700 text-[10px] font-bold px-2 py-1 rounded-full">AI Learned</span>
                                            </div>
                                            <p className="text-sm text-slate-500 mb-4">{customTemplate.description}</p>
                                            <div className="space-y-1 mb-4">
                                                {customTemplate.slides.map((s, i) => (
                                                    <div key={i} className="text-xs text-slate-600 flex items-center gap-2"><div className="w-1.5 h-1.5 bg-slate-300 rounded-full"></div> {s.title}</div>
                                                ))}
                                            </div>
                                            <button onClick={(e) => { e.stopPropagation(); setCustomTemplate(null); setSelectedTemplateId('standard'); }} className="text-xs text-red-500 hover:underline">Reset</button>
                                        </div>
                                    ) : (
                                        <>
                                            <div className="bg-orange-100 p-3 rounded-full text-orange-600 mb-3"><UploadCloud size={24}/></div>
                                            <h4 className="font-bold text-slate-700 mb-1">Upload Sample PPT</h4>
                                            <p className="text-xs text-slate-500 mb-4 px-4">Upload existing Case Studies to learn their structure.</p>
                                            <label className="cursor-pointer bg-white border border-slate-300 hover:border-orange-500 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold shadow-sm transition-all">
                                                Browse Files
                                                <input type="file" className="hidden" multiple onChange={handleFileUpload} />
                                            </label>
                                        </>
                                    )}
                                </div>
                            </div>

                            <div className="flex justify-end">
                                <button onClick={() => setPhase('input')} className="flex items-center gap-2 bg-orange-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-orange-700 shadow-lg transition-transform active:scale-95">
                                    Next: Project Details <ArrowRight size={18} />
                                </button>
                            </div>
                        </div>
                    )}

                    {/* PHASE 2: INPUT */}
                    {phase === 'input' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 animate-fade-in-up">
                            <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2"><Edit3 size={20} className="text-blue-500"/> Project Context</h3>
                            <textarea 
                                value={projectContext}
                                onChange={(e) => setProjectContext(e.target.value)}
                                className="w-full h-64 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none text-sm leading-relaxed"
                                placeholder="Describe the client, the problem they faced, the solution provided (tech stack, approach), and the business outcomes (metrics). E.g. 'Client: Acme Retail. Challenge: Slow reporting. Solution: Migrated to Snowflake. Impact: 50% faster queries.'"
                            />
                            <div className="flex justify-end mt-4">
                                <button 
                                    onClick={startGeneration} 
                                    disabled={!projectContext.trim()}
                                    className="flex items-center gap-2 bg-orange-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-orange-700 shadow-lg transition-transform active:scale-95 disabled:opacity-50"
                                >
                                    <Sparkles size={18} /> Generate Slides
                                </button>
                            </div>
                        </div>
                    )}

                    {/* PHASE 3: DASHBOARD */}
                    {phase === 'dashboard' && (
                        <div className="animate-fade-in-up space-y-6">
                            <div className="flex justify-between items-center">
                                <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><MonitorPlay size={20} className="text-orange-500"/> Slide Deck Preview</h3>
                                <button onClick={exportToPPT} className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700 shadow-md transition-all">
                                    <Download size={16} /> Download PPT
                                </button>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {generatedSlides.map((slide, idx) => (
                                    <div key={slide.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[300px]">
                                        <div className="bg-slate-50 border-b border-slate-100 p-4 flex justify-between items-center">
                                            <h4 className="font-bold text-slate-800 flex items-center gap-2">
                                                <span className="bg-slate-200 text-slate-600 text-[10px] w-5 h-5 rounded-full flex items-center justify-center">{idx + 1}</span>
                                                {slide.title}
                                            </h4>
                                            <button onClick={() => handleRegenerateSlide(idx)} className="text-slate-400 hover:text-orange-600" title="Regenerate Slide">
                                                <RefreshCw size={14} className={activeSlideIndex === idx ? 'animate-spin' : ''}/>
                                            </button>
                                        </div>
                                        <div className="p-6 flex-1 overflow-y-auto">
                                            <ul className="space-y-2 list-disc pl-4 text-sm text-slate-600">
                                                {slide.bulletPoints.map((bp, i) => (
                                                    <li key={i}>{bp}</li>
                                                ))}
                                            </ul>
                                        </div>
                                        <div className="bg-slate-50/50 p-3 border-t border-slate-100 text-xs text-slate-400 italic">
                                            <span className="font-bold">Speaker Notes:</span> {slide.speakerNotes.substring(0, 80)}...
                                        </div>
                                    </div>
                                ))}
                                {isGenerating && activeSlideIndex === null && (
                                    <div className="flex flex-col items-center justify-center h-[300px] border-2 border-dashed border-slate-200 rounded-xl">
                                        <Loader size={24} className="animate-spin text-orange-500 mb-2"/>
                                        <p className="text-sm text-slate-400">Finalizing deck...</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                </div>
            </div>
        </div>
    );
};

export default CaseStoryGenerator;

import React, { useState, useEffect } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Loader, 
  Sparkles, 
  CheckCircle, 
  BookOpen, 
  Edit3, 
  Download, 
  LayoutTemplate,
  ArrowRight,
  Eye,
  RefreshCw,
  Plus,
  Trash2,
  FileBox,
  Network,
  ArrowRightCircle,
  Table,
  GripVertical,
  Pencil
} from 'lucide-react';
import { DocumentSection, DocumentTemplate, DesignData } from '../types';
import { analyzeDocumentStructure, generateDocumentContent, saveHistory, generateTableArchitecture, generateProcessArchitecture } from '../services/geminiService';
import ArchitectureCanvas from './ArchitectureCanvas';

interface DocumentGeneratorProps {
  setHasUnsavedChanges?: (val: boolean) => void;
}

const DEFAULT_TEMPLATES: DocumentTemplate[] = [
    {
        id: 'hld',
        name: 'High Level Design (HLD)',
        description: 'Strategic overview of the system architecture.',
        sections: ['Executive Summary', 'Business Requirements', 'Solution Architecture', 'Technology Stack', 'Security & Compliance', 'Assumptions & Constraints']
    },
    {
        id: 'lld',
        name: 'Low Level Design (LLD)',
        description: 'Detailed component-level specifications.',
        sections: ['Component Specifications', 'Data Model (Schema)', 'API Interface Definitions', 'Error Handling', 'Logging & Monitoring', 'Deployment Specs']
    },
    {
        id: 'migration',
        name: 'Migration Strategy',
        description: 'Plan for moving data/apps from legacy to new systems.',
        sections: ['Current State Assessment', 'Migration Approach (Big Bang vs Phased)', 'Data Mapping Strategy', 'Cutover Plan', 'Rollback Strategy']
    }
];

const DocumentGenerator: React.FC<DocumentGeneratorProps> = ({ setHasUnsavedChanges }) => {
    // Phase Management: 'learn' | 'structure' | 'input' | 'dashboard'
    const [phase, setPhase] = useState<'learn' | 'structure' | 'input' | 'dashboard'>('learn');

    // Learning State
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('hld');
    const [customTemplate, setCustomTemplate] = useState<DocumentTemplate | null>(null);
    const [learningFiles, setLearningFiles] = useState<string[]>([]);
    const [isLearning, setIsLearning] = useState(false);

    // Structure Editing State (Manual + AI)
    const [editableSections, setEditableSections] = useState<string[]>([]);
    const [newSectionName, setNewSectionName] = useState("");

    // Input State
    const [projectContext, setProjectContext] = useState('');

    // Generation State
    const [generatedSections, setGeneratedSections] = useState<DocumentSection[]>([]);
    const [isGenerating, setIsGenerating] = useState(false);
    const [activeSectionId, setActiveSectionId] = useState<string | null>(null);

    // Manual Content Editing
    const [editingSectionId, setEditingSectionId] = useState<string | null>(null);
    const [editContentBuffer, setEditContentBuffer] = useState("");

    // Diagram State
    const [diagramType, setDiagramType] = useState<'table' | 'process'>('table');
    const [archFlowDesign, setArchFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [dataFlowDesign, setDataFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [isDiagramGenerating, setIsDiagramGenerating] = useState(false);
    const [activeDashboardTab, setActiveDashboardTab] = useState<'text' | 'diagrams'>('text');

    // Watch for unsaved changes
    useEffect(() => {
        if (setHasUnsavedChanges) {
            // Consider dirty if we are in input or dashboard editing mode
            if ((projectContext.trim().length > 0 && phase !== 'dashboard') || editingSectionId !== null) {
                setHasUnsavedChanges(true);
            } else {
                setHasUnsavedChanges(false);
            }
        }
    }, [projectContext, phase, editingSectionId, setHasUnsavedChanges]);

    // ---------------- HANDLERS: LEARNING PHASE ----------------

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setIsLearning(true);
            const fileNames = Array.from(e.target.files).map((f: any) => f.name).join(', ');
            setLearningFiles(prev => [...prev, ...Array.from(e.target.files!).map((f: any) => f.name)]);

            try {
                // Learning from "Context" of the files
                const structure = await analyzeDocumentStructure(`Files uploaded: ${fileNames}. Analyze these filenames and infer the typical structure of such solution documents.`);

                const newTemplate: DocumentTemplate = {
                    id: 'custom-learned',
                    name: 'Learned from Uploads',
                    description: `Structure derived from ${e.target.files.length} example files.`,
                    sections: structure
                };
                setCustomTemplate(newTemplate);
                setSelectedTemplateId('custom-learned');
                setEditableSections(structure);

                // Move to Structure Review Phase
                setPhase('structure');
            } catch (e) {
                console.error(e);
            } finally {
                setIsLearning(false);
            }
        }
    };

    const handleStandardTemplateSelect = (id: string) => {
        setSelectedTemplateId(id);
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === id);
        if (t) {
            setEditableSections([...t.sections]);
            setPhase('structure'); // Go to structure review
        }
    };

    // ---------------- HANDLERS: STRUCTURE PHASE ----------------

    const addSection = () => {
        if (newSectionName.trim()) {
            setEditableSections([...editableSections, newSectionName.trim()]);
            setNewSectionName("");
        }
    };

    const removeSection = (index: number) => {
        const newSections = [...editableSections];
        newSections.splice(index, 1);
        setEditableSections(newSections);
    };

    const confirmStructure = () => {
        setPhase('input');
    };

    // ---------------- HANDLERS: INPUT PHASE ----------------

    const startGeneration = async () => {
        if (!projectContext.trim()) return;

        // Initialize sections from the editable list
        const initialSections: DocumentSection[] = editableSections.map((title, idx) => ({
            id: `sec-${idx}`,
            title,
            content: '',
            status: 'pending'
        }));

        setGeneratedSections(initialSections);
        setPhase('dashboard');
        if(setHasUnsavedChanges) setHasUnsavedChanges(false); 

        // Start sequential generation (in background)
        generateSectionsSequentially(initialSections, projectContext);

        // Start Diagram Generation
        generateDiagrams(projectContext);
    };

    const generateDiagrams = async (context: string) => {
        setIsDiagramGenerating(true);
        try {
            const arch = await generateTableArchitecture(context, "Infer schema and table architecture");
            setArchFlowDesign(arch);

            const data = await generateProcessArchitecture(context, "Infer data flow and processing steps");
            setDataFlowDesign(data);
        } catch (e) {
            console.error("Diagram generation failed", e);
        } finally {
            setIsDiagramGenerating(false);
        }
    };

    const generateSectionsSequentially = async (sections: DocumentSection[], context: string) => {
        const allHeaders = sections.map(s => s.title);
        const newSections = [...sections];

        for (let i = 0; i < newSections.length; i++) {
            setActiveSectionId(newSections[i].id);
            setIsGenerating(true);

            const content = await generateDocumentContent(newSections[i].title, context, allHeaders);

            newSections[i] = { ...newSections[i], content, status: 'generated' };
            setGeneratedSections([...newSections]);
        }
        setIsGenerating(false);
        setActiveSectionId(null);
    };

    // ---------------- HANDLERS: EDITING ----------------

    const startEditingSection = (section: DocumentSection) => {
        setEditingSectionId(section.id);
        setEditContentBuffer(section.content);
    };

    const saveEditingSection = () => {
        if (editingSectionId) {
            setGeneratedSections(prev => prev.map(s => s.id === editingSectionId ? { ...s, content: editContentBuffer, status: 'edited' } : s));
            setEditingSectionId(null);
            setEditContentBuffer("");
        }
    };

    const cancelEditingSection = () => {
        setEditingSectionId(null);
        setEditContentBuffer("");
    };

    const handleRegenerateSection = async (sectionId: string) => {
        const idx = generatedSections.findIndex(s => s.id === sectionId);
        if (idx === -1) return;

        setActiveSectionId(sectionId);
        setIsGenerating(true);
        const newContent = await generateDocumentContent(generatedSections[idx].title, projectContext, generatedSections.map(s => s.title));

        const newSections = [...generatedSections];
        newSections[idx] = { ...newSections[idx], content: newContent, status: 'generated' };
        setGeneratedSections(newSections);
        setIsGenerating(false);
        setActiveSectionId(null);
    };

    const exportToWord = () => {
        const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Export HTML to Word Document with JavaScript</title></head><body>`;
        const footer = "</body></html>";

        let bodyHTML = `<h1>Solution Design Document</h1>`;
        bodyHTML += `<p><strong>Client Context:</strong> ${projectContext.substring(0, 200)}...</p><hr/>`;

        if (archFlowDesign.nodes.length > 0 || dataFlowDesign.nodes.length > 0) {
            bodyHTML += `<h2>Generated Diagrams</h2>`;
            if (archFlowDesign.nodes.length > 0) bodyHTML += `<p><em>[Architecture Flow Diagram Generated - See attached image]</em></p>`;
            if (dataFlowDesign.nodes.length > 0) bodyHTML += `<p><em>[Data Flow Diagram Generated - See attached image]</em></p>`;
            bodyHTML += `<hr/>`;
        }

        generatedSections.forEach(sec => {
            bodyHTML += `<h2>${sec.title}</h2>`;
            let htmlContent = sec.content
                .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                .replace(/\n/g, '<br/>');
            bodyHTML += `<div>${htmlContent}</div><br/>`;
        });

        const sourceHTML = header + bodyHTML + footer;
        const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(sourceHTML);

        const fileDownload = document.createElement("a");
        document.body.appendChild(fileDownload);
        fileDownload.href = source;
        fileDownload.download = `solution_document_${Date.now()}.doc`;
        fileDownload.click();
        document.body.removeChild(fileDownload);
    };

    const handleRefineDiagram = (prompt: string) => {
        if (diagramType === 'table') {
            setIsDiagramGenerating(true);
            generateTableArchitecture(projectContext + " " + prompt, "").then(d => {
                setArchFlowDesign(d);
                setIsDiagramGenerating(false);
            });
        } else {
            setIsDiagramGenerating(true);
            generateProcessArchitecture(projectContext + " " + prompt, "").then(d => {
                setDataFlowDesign(d);
                setIsDiagramGenerating(false);
            });
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-pink-100 text-pink-600 rounded-lg"><FileText size={20}/></div>
                    <div>
                        <h2 className="font-bold text-slate-800">Solution Architect Doc Generator</h2>
                        <p className="text-xs text-slate-500">AI-Powered Documentation Engine</p>
                    </div>
                </div>
                {phase === 'dashboard' && (
                    <button onClick={exportToWord} className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700 shadow-md transition-all">
                        <Download size={16} /> Export to Word
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-y-auto p-6 md:p-8">
                <div className="max-w-6xl mx-auto space-y-8">

                    {/* Stepper */}
                    <div className="flex items-center justify-center mb-8">
                        <div className={`flex items-center gap-2 ${phase === 'learn' ? 'text-indigo-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">1</div>
                            <span>Template</span>
                        </div>
                        <div className="w-16 h-0.5 bg-slate-200 mx-4"></div>
                        <div className={`flex items-center gap-2 ${phase === 'structure' ? 'text-indigo-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">2</div>
                            <span>Structure</span>
                        </div>
                        <div className="w-16 h-0.5 bg-slate-200 mx-4"></div>
                        <div className={`flex items-center gap-2 ${phase === 'input' ? 'text-indigo-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">3</div>
                            <span>Context</span>
                        </div>
                        <div className="w-16 h-0.5 bg-slate-200 mx-4"></div>
                        <div className={`flex items-center gap-2 ${phase === 'dashboard' ? 'text-indigo-600 font-bold' : 'text-slate-400'}`}>
                            <div className="w-8 h-8 rounded-full border-2 flex items-center justify-center border-current">4</div>
                            <span>Result</span>
                        </div>
                    </div>

                    {/* PHASE 1: LEARN */}
                    {phase === 'learn' && (
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 animate-fade-in-up">
                            <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2"><LayoutTemplate size={20} className="text-pink-500"/> Select Document Template</h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                                {DEFAULT_TEMPLATES.map(t => (
                                    <button 
                                        key={t.id}
                                        onClick={() => handleStandardTemplateSelect(t.id)}
                                        className={`text-left p-6 rounded-xl border-2 transition-all border-slate-100 hover:border-indigo-200 hover:bg-slate-50`}
                                    >
                                        <h4 className="font-bold text-slate-800 mb-2">{t.name}</h4>
                                        <p className="text-sm text-slate-500 mb-4">{t.description}</p>
                                        <div className="flex flex-wrap gap-2">
                                            {t.sections.slice(0, 3).map((s, i) => (
                                                <span key={i} className="text-[10px] bg-white border border-slate-200 px-2 py-1 rounded text-slate-600">{s}</span>
