                            <div className="flex justify-between items-center mb-6">
                                <div>
                                    <h3 className="text-2xl font-bold text-slate-800">Review Document Outline</h3>
                                    <p className="text-slate-500 text-sm">Drag to reorder or add new sections before generating.</p>
                                </div>
                                <button onClick={() => setPhase('setup')} className="text-sm text-slate-500 hover:text-slate-800">Back</button>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 space-y-2 mb-6 custom-scrollbar">
                                {editableSections.map((sec, idx) => (
                                    <div key={idx} className="flex items-center gap-3 p-3 bg-white border border-slate-200 rounded-lg group hover:border-pink-300 hover:shadow-sm transition-all">
                                        <div className="text-slate-300 cursor-move hover:text-slate-500 flex flex-col gap-0.5">
                                            <button onClick={() => handleMoveSection(idx, -1)} className="hover:text-pink-500"><ChevronRight size={12} className="-rotate-90"/></button>
                                            <button onClick={() => handleMoveSection(idx, 1)} className="hover:text-pink-500"><ChevronRight size={12} className="rotate-90"/></button>
                                        </div>
                                        <div className="flex-1 font-bold text-sm text-slate-700">{idx + 1}. {sec}</div>
                                        <button onClick={() => removeSection(idx)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16} /></button>
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-2 pt-4 border-t border-slate-100">
                                <input 
                                    type="text" 
                                    value={newSectionName}
                                    onChange={(e) => setNewSectionName(e.target.value)}
                                    placeholder="Add new section title..."
                                    className="flex-1 border border-slate-300 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-pink-500 bg-white text-slate-900"
                                    onKeyDown={(e) => e.key === 'Enter' && addSection()}
                                />
                                <button onClick={addSection} className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl font-bold text-sm hover:bg-slate-200"><Plus size={18} /></button>
                                <button 
                                    onClick={goToWorkspace}
                                    className="ml-4 flex items-center gap-2 bg-pink-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-pink-700 shadow-lg transition-transform hover:scale-105 active:scale-95"
                                >
                                    <Sparkles size={18} /> Generate Document
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- PHASE 3: WORKSPACE (EDITOR) --- */}
                {phase === 'workspace' && (
                    <div className="flex h-full">
                        {/* Sidebar: Outline */}
                        <div className="w-72 bg-white border-r border-slate-200 flex flex-col shrink-0">
                            <div className="p-4 border-b border-slate-100">
                                <div className="flex bg-slate-100 p-1 rounded-lg mb-2">
                                    <button onClick={() => setActiveWorkspaceTab('doc')} className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${activeWorkspaceTab === 'doc' ? 'bg-white text-pink-600 shadow-sm' : 'text-slate-500'}`}>Content</button>
                                    <button onClick={() => setActiveWorkspaceTab('diagrams')} className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${activeWorkspaceTab === 'diagrams' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>Diagrams</button>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto p-2 space-y-1 custom-scrollbar">
                                {activeWorkspaceTab === 'doc' ? (
                                    generatedSections.map((sec, idx) => (
                                        <button 
                                            key={sec.id}
                                            onClick={() => document.getElementById(sec.id)?.scrollIntoView({ behavior: 'smooth' })}
                                            className={`w-full text-left p-3 rounded-lg text-xs font-medium flex justify-between items-center transition-all ${sec.status === 'generated' || sec.status === 'edited' ? 'bg-white border border-slate-200 text-slate-700 hover:border-pink-300' : 'bg-slate-50 border border-transparent text-slate-400'}`}
                                        >
                                            <span className="truncate">{idx + 1}. {sec.title}</span>
                                            {activeSectionId === sec.id ? <Loader size={12} className="animate-spin text-pink-500"/> : (sec.status === 'generated' || sec.status === 'edited') && <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>}
                                        </button>
                                    ))
                                ) : (
                                    <div className="p-4 text-xs text-slate-500 text-center">
