import React, { useState, useEffect } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Loader, 
  Sparkles, 
  CheckCircle, 
  BookOpen, 
  Edit3, 
  Download, 
  LayoutTemplate,
  ArrowRight,
  RefreshCw,
  Plus,
  Trash2,
  Network,
