                {step === 'input' && (
                    <div className="flex-1 flex flex-col justify-center items-center text-center space-y-6 opacity-80">
                        <FileText size={48} className="text-slate-600" />
                        <p className="text-sm leading-relaxed max-w-xs">
                            "I'm ready to analyze your documents. Upload your RFP or paste requirements, and I'll infer the optimal tech stack and deployment model."
                        </p>
                    </div>
                )}

                {step === 'analyzing' && (
                    <div className="flex-1 flex flex-col justify-center items-center text-center space-y-6 animate-fade-in-up">
                        <div className="relative">
                            <div className="w-20 h-20 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin"></div>
                            <div className="absolute inset-0 flex items-center justify-center"><Sparkles size={24} className="text-indigo-400 animate-pulse"/></div>
                        </div>
                        <h4 className="text-xl font-bold text-white">Analyzing Context...</h4>
                        <div className="space-y-2 text-xs text-slate-400 font-mono">
                            <p>Reading {formData.rfpFiles.length} file(s)...</p>
                            <p>Identifying integration patterns...</p>
                            <p>Matching with {userProfile?.preferences.defaultProduct} preference...</p>
                        </div>
                    </div>
                )}

                {step === 'recommendation' && aiSuggestion && (
                    <div className="flex-1 animate-fade-in-up space-y-6">
                        <div className="bg-slate-800/50 p-6 rounded-2xl border border-slate-700/50 backdrop-blur-sm">
                            <div className="flex items-center gap-2 mb-4 text-emerald-400 text-xs font-bold uppercase tracking-wider">
                                <Lightbulb size={14} /> Recommendation
                            </div>
                            <h2 className="text-2xl font-bold text-white mb-1">{aiSuggestion.product}</h2>
                            <p className="text-sm text-slate-400 mb-4">{aiSuggestion.type} ({aiSuggestion.deployment})</p>
                            <div className="h-px bg-slate-700/50 w-full mb-4"></div>
                            <p className="text-sm text-slate-300 italic leading-relaxed">"{aiSuggestion.reason}"</p>
                        </div>

                        <div className="space-y-2">
                            <p className="text-xs font-bold text-slate-500 uppercase">Suggested Configuration</p>
                            {aiSuggestion.details.map((detail, i) => (
                                <div key={i} className="flex items-center gap-3 p-3 rounded-lg bg-slate-800/30 border border-slate-700/30 text-sm text-slate-300">
                                    <CheckCircle size={16} className="text-indigo-400 shrink-0"/> {detail}
                                </div>
                            ))}
                        </div>

                        <button onClick={acceptRecommendation} className="w-full py-3 bg-indigo-600/20 hover:bg-indigo-600/30 border border-indigo-500/50 text-indigo-300 rounded-xl text-sm font-bold transition-all">
                            Accept Recommendation
                        </button>

                        <div className="pt-4 border-t border-slate-800">
                            <label className="text-xs font-bold text-slate-500 block mb-2">Or Override Manually:</label>
                            <select 
                                name="product" 
                                value={formData.product} 
                                onChange={handleInputChange} 
                                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-300 focus:ring-1 focus:ring-indigo-500 outline-none"
                            >
                                <option value="" disabled>Select Product...</option>
                                {availableProducts.map(p => <option key={p} value={p}>{p}</option>)}
                            </select>
                        </div>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

