import ArchitectureCanvas from './ArchitectureCanvas';
import { generateArchitectureDesign, analyzeAndLearn, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import { DesignData, ArchitectureCanvasHandle } from '../types';

const StandaloneArchitecture: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [design, setDesign] = useState<DesignData>({ nodes: [], edges: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);

  const canvasRef = useRef<ArchitectureCanvasHandle>(null);

  useEffect(() => { setHistoryItems(getHistory('Architecture')); }, [design]);

  const handleGenerate = async (overridePrompt?: string) => {
    let input = overridePrompt || prompt;
    if (!input.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const result = await generateArchitectureDesign(input, "General Architecture");
      if (result && result.nodes.length > 0) {
        setDesign(result);
        setIsLearning(true);
        const interactionType = overridePrompt ? 'refinement' : 'initial';
        analyzeAndLearn(input, overridePrompt || null, result, ['Architect'], interactionType).finally(() => setIsLearning(false));
        saveHistory('Architecture', input.substring(0, 40) + '...', result, uploadedFiles);
      } else {
        setError("Could not generate valid diagram. Try adding more details.");
      }
    } catch (e) {
      setError("System error during generation.");
    } finally {
      setIsGenerating(false);
    }
  };

  const loadHistory = (item: any) => {
     setPrompt(item.summary);
     setDesign(item.data);
     setShowHistory(false);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden">

      {/* Floating Header */}
      <div className="absolute top-4 left-4 right-4 z-20 flex justify-between items-start pointer-events-none">
          <div className="bg-white/90 backdrop-blur-md border border-slate-200 p-3 rounded-2xl shadow-sm pointer-events-auto flex items-center gap-3">
              <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl"><Network size={20}/></div>
              <div>
                  <h2 className="text-sm font-bold text-slate-800">Architecture Lab</h2>
                  <p className="text-[10px] text-slate-500">AI-Powered Diagramming</p>
              </div>
          </div>

          <div className="flex gap-2 pointer-events-auto">
              <button onClick={() => setShowHistory(!showHistory)} className="p-3 bg-white/90 backdrop-blur-md border border-slate-200 rounded-xl shadow-sm text-slate-600 hover:text-indigo-600 transition-colors">
                  <History size={20} />
              </button>
              <button onClick={() => canvasRef.current?.exportImage('png')} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-colors">
                  <Share2 size={20} />
              </button>
          </div>
      </div>

      {/* History Panel */}
      {showHistory && (
         <div className="absolute top-20 right-4 z-30 w-72 bg-white/95 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3 text-slate-800">Recent Designs</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
               {historyItems.map((h, i) => (
                  <button key={i} onClick={() => loadHistory(h)} className="w-full text-left p-3 hover:bg-indigo-50 rounded-xl text-xs group transition-all">
                     <div className="font-bold text-slate-700 truncate">{h.summary}</div>
                     <div className="text-[10px] text-slate-400">{h.date}</div>
                  </button>
               ))}
            </div>
         </div>
      )}

      {/* Main Canvas Area */}
      <div className="flex-1 relative bg-slate-50">
         {design.nodes.length === 0 && !isGenerating ? (
            <div className="absolute inset-0 flex items-center justify-center z-10 p-4">
               <div className="bg-white p-8 rounded-3xl shadow-xl max-w-lg w-full text-center border border-slate-100">
                  <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-6">
                     <BrainCircuit size={32} />
                  </div>
                  <h3 className="text-2xl font-bold text-slate-800 mb-2">Start Designing</h3>
                  <p className="text-slate-500 mb-8 text-sm">Describe your architecture (e.g. "Microservices on AWS with Redis")</p>

                  <div className="relative">
                      <input 
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
                        className="w-full pl-4 pr-12 py-4 rounded-xl border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm"
                        placeholder="Type requirements..."
                      />
                      <button 
                        onClick={() => handleGenerate()}
                        className="absolute right-2 top-2 p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors"
                      >
                        <Sparkles size={20} />
                      </button>
                  </div>
               </div>
            </div>
         ) : (
            <ArchitectureCanvas 
                 ref={canvasRef}
                 aiNodes={design.nodes} 
                 aiEdges={design.edges} 
                 isThinking={isGenerating} 
                 thoughts={['Analyzing structure...', 'Optimizing layout...']}
                 context={prompt}
                 onRefine={(p) => { setPrompt(p); handleGenerate(p); }}
                 refinementPlaceholder="Describe changes (e.g. 'Add a load balancer')..."
            />
         )}
      </div>
    </div>
  );
};

