                                          {rules.slice(0, 3).map((r, i) => (
                                              <div key={i} className="bg-white p-2 rounded-lg border border-slate-100 text-xs text-slate-600 shadow-sm">
                                                  {r.description}
                                              </div>
                                          ))}
                                          {rules.length > 3 && <div className="text-[10px] text-slate-400 font-bold text-center">+{rules.length - 3} more</div>}
                                      </div>
                                  </div>
                              ))}
                          </div>
                      </div>
                  )}
              </div>
          )}

          {activeTab === 'cleanse' && (
              <div className="flex-1 flex items-center justify-center text-slate-400">
                  <div className="text-center">
                      <Wand2 size={48} className="mx-auto mb-4 opacity-20"/>
                      <p>Cleansing Module Placeholder (Same Modern Style)</p>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

