        <div className="p-5 border-b border-slate-800/50">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-indigo-500 to-purple-600 p-2 rounded-xl shadow-lg shadow-indigo-900/50 ring-1 ring-white/10">
               <BrainCircuit size={22} className="text-white" />
            </div>
            <div>
               <h1 className="font-bold text-base leading-tight tracking-tight text-white">DataArch<span className="text-indigo-400">AI</span></h1>
               <p className="text-[10px] text-slate-500 uppercase tracking-widest font-semibold">Enterprise v2.0</p>
            </div>
            <button onClick={() => setIsMobileOpen(false)} className="md:hidden ml-auto text-slate-400 hover:text-white">
              <X size={20} />
            </button>
          </div>
        </div>

        {/* Navigation Scroll Area */}
        <nav className="flex-1 overflow-y-auto px-3 py-4 space-y-1 custom-scrollbar">

          {/* Dashboard (Always Top) */}
          <button
            onClick={() => { handleSwitchTab('dashboard'); setIsMobileOpen(false); }}
            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200 mb-6 group ${activeTab === 'dashboard' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <LayoutDashboard size={18} />
            <span className="font-semibold text-sm">Command Center</span>
          </button>

          {/* Groups */}
          {navGroups.map((group) => (
            <div key={group.id} className="mb-2">
              <button 
                onClick={() => toggleGroup(group.id)}
                className="w-full flex items-center justify-between px-3 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider hover:text-slate-300 transition-colors"
              >
                <div className="flex items-center gap-2">
                   <group.icon size={12} /> {group.title}
                </div>
                {expandedGroups[group.id] ? <ChevronDown size={12}/> : <ChevronRight size={12}/>}
              </button>

              {expandedGroups[group.id] && (
                <div className="space-y-0.5 mt-1 ml-1 animate-fade-in">
                  {group.items.map(item => {
                    const isActive = activeTab === item.id;
                    return (
                      <button
                        key={item.id}
                        onClick={() => { handleSwitchTab(item.id); setIsMobileOpen(false); }}
                        className={`
                          w-full flex items-center gap-3 px-3 py-2 rounded-lg transition-all duration-200 text-sm border-l-2
                          ${isActive 
                            ? 'bg-slate-800/80 text-white border-indigo-500' 
