               <History size={12} />
               <span className="text-[10px] font-bold uppercase tracking-wide">Local Session</span>
             </div>
             <p className="text-[10px] text-slate-500 leading-tight">
               Changes are auto-saved to your browser storage.
             </p>
          </div>

          <button 
            onClick={onOpenProfile}
            className="flex items-center justify-between w-full group p-2 rounded-lg hover:bg-slate-800/50 transition-colors"
          >
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-indigo-900 to-slate-800 flex items-center justify-center border border-slate-700 shadow-inner relative">
                <User size={14} className="text-indigo-300" />
                <div className="absolute -bottom-0.5 -right-0.5 bg-emerald-500 w-2.5 h-2.5 rounded-full border-2 border-slate-900"></div>
              </div>
              <div className="text-left">
                <p className="text-white text-xs font-bold truncate w-28">{userProfile?.name || 'Architect'}</p>
                <p className="text-[10px] text-slate-500 truncate">{userProfile?.role || 'User'}</p>
              </div>
            </div>
            <Settings size={14} className="text-slate-600 group-hover:text-indigo-400 transition-colors" />
          </button>

          <button onClick={onLogout} className="w-full mt-2 flex items-center justify-center gap-2 text-[10px] uppercase font-bold text-slate-500 hover:text-red-400 transition-colors py-2 border-t border-slate-800/50">
             <LogOut size={12} /> Sign Out
          </button>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import DashboardView from './components/Dashboard';
import DesignHub from './components/DesignHub';
import SolutionDesignView from './components/SolutionDesign';
import StandaloneEstimator from './components/StandaloneEstimator';
import StandaloneArchitecture from './components/StandaloneArchitecture';
import StandaloneDataFlow from './components/StandaloneDataFlow';
import StandaloneDataQuality from './components/StandaloneDataQuality';
import StandaloneERDiagram from './components/StandaloneERDiagram';
import DocumentGenerator from './components/DocumentGenerator';
import CaseStoryGenerator from './components/CaseStoryGenerator';
import ProjectDescriber from './components/ProjectDescriber';
import LoginPage from './components/LoginPage';
import UserGuide from './components/UserGuide';
import UserProfileModal from './components/UserProfileModal';
import { RequestData, DesignCache, UserProfile } from './types';
import { AlertTriangle, X } from 'lucide-react';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Tabs: 'dashboard' | 'design-module' | 'design' | 'doc-generator' | 'case-story' | 'adhoc-estimator' | 'adhoc-architecture' | 'adhoc-dataflow' | 'adhoc-dq' | 'adhoc-er' | 'project-describer'
  const [activeTab, setActiveTab] = useState('dashboard');

  const [selectedRequest, setSelectedRequest] = useState<RequestData | null>(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [designCache, setDesignCache] = useState<DesignCache>({});
  const [showGuide, setShowGuide] = useState(false);

  // Navigation Guard State
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [showNavigationAlert, setShowNavigationAlert] = useState(false);
  const [pendingTab, setPendingTab] = useState<string | null>(null);

  // User Profile State
  const [showProfile, setShowProfile] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile>({
    name: 'Alex Architect',
    email: 'alex.arch@data.inc',
    role: 'Senior Solution Architect',
    preferences: {
      defaultProduct: '',
      defaultDeployment: 'Cloud'
    }
  });

  // Mock Data
  const [requests, setRequests] = useState<RequestData[]>([
    {
      id: 'REQ-1005',
      clientName: 'HealthCare Plus',
      product: 'Databricks',
      deploymentModel: 'Cloud',
      type: 'Unity Catalog',
      rfpFiles: ['lakehouse_governance_rfp.pdf', 'hipaa_compliance.docx'],
      targetAudience: ['Admin', 'Developer'],
      date: '10/27/2023',
      status: 'In Progress'
    },
    {
      id: 'REQ-1004',
      clientName: 'City Gov Dept',
      product: 'Profisee',
      deploymentModel: 'Cloud',
      type: 'Profisee MDM SaaS',
      rfpFiles: ['citizen_360_requirements.pdf'],
      targetAudience: ['Developer'],
      date: '10/26/2023',
      status: 'Not Started'
    },
    {
      id: 'REQ-1003',
      clientName: 'Tech StartUp',
      product: 'Azure Data Factory',
      deploymentModel: 'Cloud',
      type: 'Data Factory V2',
      rfpFiles: ['analytics_pipeline.pdf'],
      targetAudience: ['Developer'],
      date: '10/26/2023',
      status: 'Completed'
    },
    {
      id: 'REQ-1002',
      clientName: 'Retail Giant',
      product: 'Informatica',
      deploymentModel: 'Cloud',
      type: 'MDM SaaS',
      rfpFiles: ['customer_360_view.docx', 'requirements_v2.pdf'],
      targetAudience: ['Developer', 'Tester'],
      date: '10/25/2023',
      status: 'Completed'
    },
    {
      id: 'REQ-1001',
      clientName: 'Global FinCorp',
      product: 'Informatica',
      deploymentModel: 'On-Premise',
      type: 'PowerCenter',
      rfpFiles: ['mainframe_migration_rfp.pdf'],
      targetAudience: ['Developer', 'Admin'],
      date: '10/24/2023',
      status: 'Completed'
    }
  ]);
  const [nextId, setNextId] = useState(1006);

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  // Safe Navigation Handler
  const handleSwitchTab = (tab: string) => {
      if (hasUnsavedChanges) {
          setPendingTab(tab);
          setShowNavigationAlert(true);
      } else {
          setActiveTab(tab);
      }
  };

  const confirmNavigation = () => {
      if (pendingTab) {
          setActiveTab(pendingTab);
          setHasUnsavedChanges(false);
          setShowNavigationAlert(false);
          setPendingTab(null);
      }
  };

  const cancelNavigation = () => {
      setShowNavigationAlert(false);
      setPendingTab(null);
  };

  const handleCreateSubmit = (newRequest: any) => {
    const requestWithId: RequestData = {
      ...newRequest,
      id: `REQ-${nextId}`,
      status: 'Not Started'
    };
    setRequests([requestWithId, ...requests]);
    setNextId(prev => prev + 1);

    // Auto-redirect to design view for the new request
    setSelectedRequest(requestWithId);
    setActiveTab('design');
    setHasUnsavedChanges(false); // Reset dirty flag after creation
  };

  const handleSelectRequest = (req: RequestData) => {
    // Check for unsaved changes before switching contexts
    if (hasUnsavedChanges) {
        // Simple alert for intra-dashboard switches for now, or assume this is handled by tab switching if view changes
        if(!confirm("You have unsaved changes. Discard them?")) return;
        setHasUnsavedChanges(false);
    }
    setSelectedRequest(req);
    setActiveTab('design');
  };

  const handleDeleteRequest = (id: string) => {
    if (confirm("Are you sure you want to delete this request?")) {
        setRequests(prev => prev.filter(r => r.id !== id));
        if (selectedRequest?.id === id) {
            setSelectedRequest(null);
            setActiveTab('design-module');
        }
    }
  };

  const handleUpdateDesignCache = (reqId: string, designData: any) => {
    setDesignCache(prev => ({
      ...prev,
      [reqId]: designData
    }));
  };

  const handleUpdateRequestStatus = (reqId: string, status: 'Not Started' | 'In Progress' | 'Completed') => {
      setRequests(prev => prev.map(req => req.id === reqId ? { ...req, status } : req));
      if (selectedRequest && selectedRequest.id === reqId) {
          setSelectedRequest(prev => prev ? { ...prev, status } : null);
      }
  };

  if (!isLoggedIn) {
    return <LoginPage onLogin={handleLogin} />;
  }

  // Determine header title based on active tab
  const getHeaderTitle = () => {
    switch(activeTab) {
      case 'dashboard': return 'System Dashboard';
      case 'design-module': return 'Solution Designer';
      case 'design': return `Design: ${selectedRequest?.id || ''}`;
      case 'doc-generator': return 'Document Generator';
      case 'case-story': return 'Case Story Generator';
      case 'project-describer': return 'Project Describer';
      case 'adhoc-estimator': return 'Smart Project Estimator';
      case 'adhoc-architecture': return 'Architecture Flow Designer';
      case 'adhoc-dataflow': return 'Data Flow Designer';
      case 'adhoc-dq': return 'Data Quality Studio';
      case 'adhoc-er': return 'ER Diagram Generator';
      default: return 'DataArch AI Platform';
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden relative">

      {/* Global Navigation Alert Modal */}
      {showNavigationAlert && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in p-4">
              <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 relative border border-slate-200">
                  <div className="flex items-center gap-3 text-red-600 mb-4">
                      <div className="p-2 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
                      <h3 className="text-lg font-bold">Unsaved Changes</h3>
                  </div>
                  <p className="text-slate-600 text-sm mb-6 leading-relaxed">
                      You have unsaved work in progress. If you navigate away now, your current changes will be lost.
                  </p>
                  <div className="flex gap-3 justify-end">
                      <button 
                          onClick={cancelNavigation} 
                          className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg text-sm transition-colors"
                      >
                          Continue Editing
                      </button>
                      <button 
                          onClick={confirmNavigation} 
                          className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-bold rounded-lg text-sm transition-colors shadow-md"
                      >
                          Discard & Leave
                      </button>
                  </div>
              </div>
          </div>
      )}

      <Sidebar 
        activeTab={activeTab === 'design' ? 'design-module' : activeTab} 
        setActiveTab={setActiveTab} // Keeping for internal simple switches if needed
        handleSwitchTab={handleSwitchTab} // Use this for protected switches
        isMobileOpen={isMobileOpen}
        setIsMobileOpen={setIsMobileOpen}
        onLogout={handleLogout}
        userProfile={userProfile}
        onOpenProfile={() => setShowProfile(true)}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <Header 
          title={getHeaderTitle()} 
          toggleSidebar={() => setIsMobileOpen(true)}
          onOpenGuide={() => setShowGuide(true)}
        />

        <main className="flex-1 overflow-y-auto relative scroll-smooth bg-slate-50">

          <UserGuide isOpen={showGuide} onClose={() => setShowGuide(false)} />
          <UserProfileModal 
             isOpen={showProfile}
             onClose={() => setShowProfile(false)}
             profile={userProfile}
             onSave={(p) => setUserProfile(p)}
          />

          <div className={`h-full ${activeTab === 'dashboard' ? 'block' : 'hidden'}`}>
            <DashboardView 
                requests={requests} 
                onSelectRequest={handleSelectRequest} 
                onDeleteRequest={handleDeleteRequest}
                setActiveTab={setActiveTab}
                handleSwitchTab={handleSwitchTab}
            />
          </div>

          <div className={`h-full ${activeTab === 'design' ? 'block' : 'hidden'}`}>
             <SolutionDesignView 
               request={selectedRequest} 
               designCache={designCache}
               onUpdateDesignCache={handleUpdateDesignCache}
               onUpdateRequestStatus={handleUpdateRequestStatus}
             />
          </div>

          <div className={`h-full ${activeTab === 'design-module' ? 'block' : 'hidden'}`}>
            <DesignHub 
              requests={requests}
              onRequestCreate={handleCreateSubmit} 
              onSelectRequest={handleSelectRequest}
              onDeleteRequest={handleDeleteRequest}
              userProfile={userProfile}
              setHasUnsavedChanges={setHasUnsavedChanges}
              handleSwitchTab={handleSwitchTab}
            />
          </div>

          <div className={`h-full ${activeTab === 'doc-generator' ? 'block' : 'hidden'}`}>
            <DocumentGenerator setHasUnsavedChanges={setHasUnsavedChanges} />
          </div>

          <div className={`h-full ${activeTab === 'case-story' ? 'block' : 'hidden'}`}>
            <CaseStoryGenerator setHasUnsavedChanges={setHasUnsavedChanges} />
          </div>

          <div className={`h-full ${activeTab === 'project-describer' ? 'block' : 'hidden'}`}>
            <ProjectDescriber />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-estimator' ? 'block' : 'hidden'}`}>
            <StandaloneEstimator />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-architecture' ? 'block' : 'hidden'}`}>
            <StandaloneArchitecture />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-dataflow' ? 'block' : 'hidden'}`}>
            <StandaloneDataFlow />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-dq' ? 'block' : 'hidden'}`}>
            <StandaloneDataQuality />
          </div>

          <div className={`h-full ${activeTab === 'adhoc-er' ? 'block' : 'hidden'}`}>
            <StandaloneERDiagram />
          </div>

        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Sparkles, 
  Loader, 
  ArrowRight,
  BookOpen,
  Info,
  X,
  History,
  Trash2
} from 'lucide-react';
import { generateProjectUnderstanding, saveHistory, getHistory, deleteHistory } from '../services/geminiService';

const ProjectDescriber: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [summary, setSummary] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('Describer'));
  }, [summary]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = Array.from(e.target.files) as File[];
      setUploadedFiles(prev => [...prev, ...files.map(f => f.name)]);
      // In a real app, we'd read the file content here. 
      // For this demo, we assume the filename gives context or prompt is augmented.
      setInputText(prev => prev + `\n[Context attached from file: ${files[0].name}]`);
    }
  };

  const handleGenerate = async () => {
    if (!inputText.trim()) return;
    setIsGenerating(true);
    try {
      const result = await generateProjectUnderstanding(inputText);
      setSummary(result);
      saveHistory('Describer', inputText.substring(0, 40) + '...', { text: result }, uploadedFiles);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const loadHistoryItem = (item: any) => {
      setInputText(item.summary);
      setSummary(item.data.text);
      setUploadedFiles(item.files || []);
      setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      deleteHistory(id);
      setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">
        {/* Header */}
        <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-teal-600 text-white rounded-lg shadow-sm"><BookOpen size={20}/></div>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg">Project Describer</h2>
                    <p className="text-xs text-slate-500">Instant RFP Summarization & Insights</p>
                </div>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-teal-50 text-teal-600' : 'text-slate-600 hover:bg-slate-100'}`}>
                    <History size={18} /> History
                </button>
            </div>
        </div>

        {/* History Dropdown */}
        {showHistory && (
            <div className="absolute top-16 right-6 z-30 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
                <h3 className="font-bold text-sm mb-3">Recent Insights</h3>
                <div className="space-y-2 max-h-60 overflow-y-auto">
                    {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                    historyItems.map((h, i) => (
                        <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                            <div className="truncate font-medium text-slate-700 mb-1">{h.summary}</div>
                            <span className="text-slate-400 text-[10px]">{h.date}</span>
                            <div 
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                onClick={(e) => handleDeleteHistory(h.id, e)}
                            >
                                <Trash2 size={14} />
                            </div>
                        </button>
                    ))}
                </div>
            </div>
        )}

        <div className="flex-1 flex overflow-hidden">

            {/* LEFT: INPUT AREA */}
            <div className="w-full lg:w-1/2 p-8 overflow-y-auto border-r border-slate-200 bg-white">
                <div className="max-w-xl mx-auto space-y-6">
                    <div>
                        <h3 className="text-lg font-bold text-slate-800 mb-2">Input Source</h3>
                        <p className="text-sm text-slate-500 mb-4">Paste RFP content, Questionnaire text, or upload files.</p>

                        <div className="mb-4">
                            <label className="flex flex-col items-center justify-center w-full h-24 border-2 border-dashed border-slate-300 rounded-xl cursor-pointer hover:bg-slate-50 hover:border-teal-400 transition-all bg-slate-50">
                                <div className="flex flex-col items-center justify-center pt-2 pb-3">
                                    <UploadCloud className="w-6 h-6 mb-2 text-slate-400" />
                                    <p className="text-xs text-slate-500 font-bold">Attach Documents (PDF, DOCX)</p>
                                </div>
                                <input type="file" className="hidden" multiple onChange={handleFileUpload} />
                            </label>
                            {uploadedFiles.length > 0 && (
                                <div className="flex flex-wrap gap-2 mt-2">
                                    {uploadedFiles.map((f, i) => (
                                        <span key={i} className="px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded border border-slate-200 flex items-center gap-1">
                                            <FileText size={10}/> {f}
                                        </span>
                                    ))}
                                </div>
                            )}
                        </div>

                        <textarea 
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            className="w-full h-64 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none text-sm leading-relaxed bg-white text-slate-900 placeholder:text-slate-400 resize-none shadow-sm"
                            placeholder="Paste your RFP text here..."
                        />
                    </div>

                    <button 
                        onClick={handleGenerate}
                        disabled={!inputText.trim() || isGenerating}
                        className="w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg bg-teal-600 hover:bg-teal-700 hover:scale-[1.02] flex items-center justify-center gap-3 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {isGenerating ? <Loader size={20} className="animate-spin"/> : <Sparkles size={20} />}
                        Analyze & Explain
                    </button>
                </div>
            </div>

            {/* RIGHT: OUTPUT AREA */}
            <div className="w-full lg:w-1/2 p-8 overflow-y-auto bg-slate-50 relative">
                {summary ? (
                    <div className="max-w-2xl mx-auto space-y-6 animate-fade-in-up">
                        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                            <div className="flex items-center gap-2 mb-6 border-b border-slate-100 pb-4">
                                <Info size={20} className="text-teal-600"/>
                                <h3 className="font-bold text-xl text-slate-800">Project Understanding</h3>
                            </div>
                            <div className="prose prose-sm max-w-none text-slate-700 leading-relaxed">
                                {summary.split('\n').map((line, i) => {
                                    if (line.startsWith('# ')) return <h2 key={i} className="text-lg font-bold text-slate-900 mt-6 mb-3">{line.replace('# ', '')}</h2>;
                                    if (line.startsWith('## ')) return <h3 key={i} className="text-md font-bold text-slate-800 mt-4 mb-2">{line.replace('## ', '')}</h3>;
                                    if (line.startsWith('- ')) return <li key={i} className="ml-4 list-disc marker:text-teal-500 mb-1">{line.replace('- ', '')}</li>;
                                    return <p key={i} className="mb-2">{line}</p>;
                                })}
                            </div>
                        </div>
                    </div>
                ) : (
