import React, { useState, useEffect } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Sparkles, 
  Loader, 
  ArrowRight,
  BookOpen,
  Info,
  X,
  History,
  Trash2,
  CheckCircle2,
  BrainCircuit,
  Target,
  Layers,
