  Eye,
  Cpu
} from 'lucide-react';
import { generateProjectUnderstanding, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import { ProjectDescriptionResponse } from '../types';

const ProjectDescriber: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [resultData, setResultData] = useState<ProjectDescriptionResponse | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);

  // Thinking State
  const [thinkingStep, setThinkingStep] = useState(0);
  const [thoughtLog, setThoughtLog] = useState<string[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('Describer'));
  }, [resultData]);

  // Simulate thinking steps
  useEffect(() => {
      let interval: any;
      if (isGenerating) {
          setThinkingStep(0);
          setThoughtLog([]);
          const steps = [
              "Parsing RFP context...",
              "Identifying core business objectives...",
              "Analyzing implicit technical constraints...",
              "Mapping required technology stack...",
              "Synthesizing executive summary..."
          ];
          let i = 0;
          interval = setInterval(() => {
              if (i < steps.length) {
                  setThoughtLog(prev => [...prev, steps[i]]);
                  setThinkingStep(i + 1);
                  i++;
              }
          }, 1500);
      }
      return () => clearInterval(interval);
  }, [isGenerating]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = Array.from(e.target.files) as File[];
      setUploadedFiles(prev => [...prev, ...files.map(f => f.name)]);
      setInputText(prev => prev + `\n[Context attached from file: ${files[0].name}]`);
    }
  };

  const handleGenerate = async () => {
    if (!inputText.trim()) return;
    setIsGenerating(true);
    setResultData(null);
    try {
      const result = await generateProjectUnderstanding(inputText);
      setResultData(result);
      saveHistory('Describer', inputText.substring(0, 40) + '...', { data: result }, uploadedFiles);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const loadHistoryItem = (item: any) => {
      setInputText(item.summary);
      setResultData(item.data.data);
      setUploadedFiles(item.files || []);
      setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      deleteHistory(id);
      setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 text-slate-100 relative overflow-hidden animate-fade-in">
        {/* Ambient Background */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
            <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-teal-900/20 rounded-full blur-[100px] animate-blob"></div>
            <div className="absolute bottom-[-20%] left-[-10%] w-[500px] h-[500px] bg-indigo-900/20 rounded-full blur-[100px] animate-blob animation-delay-2000"></div>
        </div>

        {/* Header */}
        <div className="bg-slate-900/80 backdrop-blur-md border-b border-slate-700/50 px-6 py-4 flex justify-between items-center z-20 shrink-0">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-teal-500/10 border border-teal-500/20 text-teal-400 rounded-lg shadow-sm shadow-teal-900/20"><BrainCircuit size={20}/></div>
                <div>
                    <h2 className="font-bold text-slate-100 text-lg tracking-tight">Neural Project Describer</h2>
                    <p className="text-xs text-slate-400 font-mono">Gemini Pro Reasoning Engine</p>
                </div>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-teal-500/20 text-teal-300' : 'text-slate-400 hover:bg-slate-800'}`}>
                    <History size={18} /> History
                </button>
            </div>
        </div>

        {/* History Dropdown */}
        {showHistory && (
            <div className="absolute top-16 right-6 z-30 w-80 bg-slate-800 rounded-xl shadow-2xl border border-slate-700 p-4 animate-fade-in-up">
                <h3 className="font-bold text-sm mb-3 text-slate-300">Previous Analyses</h3>
                <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar">
                    {historyItems.length === 0 ? <p className="text-xs text-slate-500 text-center py-2">No history available</p> :
                    historyItems.map((h, i) => (
                        <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-700/50 rounded-lg border border-slate-700 text-xs group relative transition-all">
                            <div className="truncate font-medium text-slate-300 mb-1">{h.summary}</div>
