                            <div 
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-700 rounded p-1 hover:text-red-400 cursor-pointer"
                                onClick={(e) => handleDeleteHistory(h.id, e)}
                            >
                                <Trash2 size={14} />
                            </div>
                        </button>
                    ))}
                </div>
            </div>
        )}

        <div className="flex-1 flex overflow-hidden relative z-10">

            {/* LEFT: INPUT AREA */}
            <div className="w-full lg:w-1/3 p-6 overflow-y-auto border-r border-slate-700/50 bg-slate-900/50">
