import React, { useState, useEffect } from 'react';
import { 
  Database, 
  ArrowRight, 
  Sparkles, 
  Loader, 
  Download, 
  UploadCloud, 
  FileSpreadsheet, 
  Table, 
  Settings,
  Grid
} from 'lucide-react';
import { generateDataDictionary } from '../services/geminiService';
import { DataDictionaryItem } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

const StandaloneDataDictionary: React.FC = () => {
  // Step 1: Configuration
  const [project, setProject] = useState('');
  const [module, setModule] = useState('');
  const [inputType, setInputType] = useState<'text' | 'file'>('text');
  const [inputText, setInputText] = useState('');
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);

  // Step 2: Generation
  const [isGenerating, setIsGenerating] = useState(false);
  const [dataDictionary, setDataDictionary] = useState<DataDictionaryItem[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);
      // In a real app, read file content. Here we simulate context.
      setInputText(prev => prev + `\n[Context from uploaded file: ${file.name}]`);
    }
  };

  const handleGenerate = async () => {
    if (!project || !module || !inputText.trim()) {
      setError("Please complete all fields.");
      return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const result = await generateDataDictionary(inputText, project, module);
      setDataDictionary(result);
    } catch (e) {
      setError("Failed to generate dictionary. Try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleExportExcel = () => {
    if (typeof window.XLSX === 'undefined') {
        alert("Excel library not loaded.");
        return;
    }

    // Prepare data for Excel
    const wsData = dataDictionary.map(item => ({
        "Table Name": item.tableName,
        "Column Name": item.columnName,
        "Data Type": item.dataType,
        "Length": item.length || '',
        "Constraint": item.constraint || '',
        "Description": item.description,
        "Business Rule": item.businessRule || ''
    }));

    const wb = window.XLSX.utils.book_new();
    const ws = window.XLSX.utils.json_to_sheet(wsData);

    // Auto-width columns
    const wscols = [
        {wch: 20}, {wch: 20}, {wch: 15}, {wch: 10}, {wch: 15}, {wch: 50}, {wch: 30}
    ];
    ws['!cols'] = wscols;

    window.XLSX.utils.book_append_sheet(wb, ws, "DataDictionary");
    window.XLSX.writeFile(wb, `${project}_${module}_DataDictionary.xlsx`);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">
        {/* Header */}
        <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 text-white rounded-lg shadow-sm"><FileSpreadsheet size={20}/></div>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg">Data Dictionary Generator</h2>
                    <p className="text-xs text-slate-500">Automated Metadata Extraction & Excel Export</p>
                </div>
            </div>
            {dataDictionary.length > 0 && (
                <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-md transition-all">
                    <Download size={16} /> Export to Excel
                </button>
            )}
        </div>

        <div className="flex-1 flex overflow-hidden">

            {/* LEFT: CONFIGURATION */}
            <div className="w-80 bg-white border-r border-slate-200 p-6 overflow-y-auto flex flex-col gap-6 shrink-0">
                <div>
                    <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 flex items-center gap-2">
                        <Settings size={14}/> Configuration
                    </h3>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Main Project</label>
                            <input 
                                className="w-full p-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                value={project}
                                onChange={(e) => setProject(e.target.value)}
                                placeholder="e.g. Finance Transformation"
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Sub-Module</label>
                            <input 
                                className="w-full p-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                value={module}
                                onChange={(e) => setModule(e.target.value)}
                                placeholder="e.g. General Ledger"
                            />
                        </div>
                    </div>
                </div>

                <div className="h-px bg-slate-100"></div>

                <div className="flex-1 flex flex-col">
                    <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 flex items-center gap-2">
                        <Database size={14}/> Input Data
                    </h3>

                    <div className="flex bg-slate-100 p-1 rounded-lg mb-3">
                        <button onClick={() => setInputType('text')} className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${inputType === 'text' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>DDL / Text</button>
                        <button onClick={() => setInputType('file')} className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${inputType === 'file' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>File Upload</button>
                    </div>

                    {inputType === 'text' ? (
                        <textarea 
                            className="flex-1 w-full p-3 border border-slate-300 rounded-lg text-xs font-mono resize-none focus:ring-2 focus:ring-blue-500 outline-none"
                            placeholder="Paste CREATE TABLE statements or JSON structure here..."
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                        />
                    ) : (
                        <div className="flex-1 border-2 border-dashed border-slate-300 rounded-lg flex flex-col items-center justify-center p-4 bg-slate-50">
                            <UploadCloud size={24} className="text-slate-400 mb-2"/>
                            <p className="text-xs text-center text-slate-500 font-medium">Upload DDL or Spec</p>
                            <input type="file" className="hidden" id="dict-upload" onChange={handleFileUpload} />
                            <label htmlFor="dict-upload" className="mt-2 text-[10px] bg-white border border-slate-300 px-2 py-1 rounded cursor-pointer hover:bg-slate-50">Choose File</label>
                            {uploadedFileName && <p className="text-[10px] text-blue-600 mt-2 truncate max-w-full font-bold">{uploadedFileName}</p>}
                        </div>
                    )}
                </div>

                <button 
                    onClick={handleGenerate}
                    disabled={isGenerating}
                    className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                    {isGenerating ? <Loader size={16} className="animate-spin"/> : <Sparkles size={16}/>}
                    Generate Dictionary
                </button>
                {error && <p className="text-xs text-red-500 text-center">{error}</p>}
            </div>

            {/* RIGHT: PREVIEW GRID */}
            <div className="flex-1 bg-slate-100 p-8 overflow-hidden flex flex-col">
                {dataDictionary.length === 0 ? (
                    <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
                        <Grid size={48} className="mb-4 opacity-20"/>
                        <p className="text-sm font-medium">Ready to generate.</p>
                        <p className="text-xs mt-1">Configure your project and provide schema input.</p>
                    </div>
                ) : (
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 flex flex-col overflow-hidden">
                        <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                            <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">{project} / {module}</div>
                            <div className="text-xs text-slate-400">{dataDictionary.length} Columns Found</div>
                        </div>
                        <div className="flex-1 overflow-auto">
                            <table className="w-full text-left text-sm border-collapse">
                                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                                    <tr>
                                        <th className="p-3 font-bold text-slate-600 border-b border-r border-slate-200 w-32">Table Name</th>
                                        <th className="p-3 font-bold text-slate-600 border-b border-r border-slate-200 w-32">Column</th>
                                        <th className="p-3 font-bold text-slate-600 border-b border-r border-slate-200 w-24">Type</th>
                                        <th className="p-3 font-bold text-slate-600 border-b border-r border-slate-200 w-16">Len</th>
                                        <th className="p-3 font-bold text-slate-600 border-b border-r border-slate-200 w-20">Constraint</th>
                                        <th className="p-3 font-bold text-slate-600 border-b border-slate-200">Description</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {dataDictionary.map((row, i) => (
                                        <tr key={i} className="hover:bg-slate-50 group transition-colors">
                                            <td className="p-3 border-r border-slate-100 text-slate-700 font-medium">{row.tableName}</td>
                                            <td className="p-3 border-r border-slate-100 text-slate-800 font-bold">{row.columnName}</td>
                                            <td className="p-3 border-r border-slate-100 text-blue-600 font-mono text-xs">{row.dataType}</td>
                                            <td className="p-3 border-r border-slate-100 text-slate-500 text-xs">{row.length}</td>
                                            <td className="p-3 border-r border-slate-100 text-slate-500 text-xs">
                                                {row.constraint && <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[10px] font-bold border border-slate-200">{row.constraint}</span>}
                                            </td>
                                            <td className="p-3 text-slate-600 text-xs leading-relaxed">{row.description}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}
            </div>

        </div>
    </div>
  );
};

