  PenTool, 
  FileText, 
  Presentation, 
  BrainCircuit, 
  Sparkles,
  Search,
  Zap,
  Target,
  FileSpreadsheet,
  CheckCircle,
  RefreshCw,
  Cpu
} from 'lucide-react';
import { generateDynamicUserGuide } from '../services/geminiService';
import { GuideSection } from '../types';

interface UserGuideProps {
  isOpen: boolean;
  onClose: () => void;
}

// The "Truth" of the application features that the AI will learn from.
// Including the NEW features (Data Dictionary, Project Describer).
const CURRENT_APP_FEATURES = `
1. Solution Designer (Design Hub): Central module for end-to-end architectural blueprinting. Takes RFPs/Requirements, generates High Level Designs (HLD), Requirements lists, and Scoping Questions.
2. Project Describer: A "Neural" AI module that summarizes complex RFPs or questionnaires into executive summaries, objectives, and technical constraints using a "Thinking" process.
3. Data Dictionary Generator: A dedicated tool to convert SQL DDL or text descriptions into standardized Excel data dictionaries with business definitions.
4. Smart Estimator: Calculates project effort, cost, and timelines based on complexity drivers (e.g., number of tables, complexity of mappings). Supports Data Integration, DQ, Governance, and MDM drivers.
5. Architecture Lab: A freehand diagramming tool for system flows. Supports text-to-diagram (NLP) and Mermaid.js syntax.
6. Data Flow Designer: Specifically for ETL/Data Movement visualization.
7. Data Quality Studio: Generates validation rules and cleansing logic for Informatica CDQ/IDQ based on natural language requirements.
8. Doc Generator: Automates the creation of Word documents (HLD/LLD) based on project context and templates.
9. Case Story Generator: Creates PowerPoint slide decks for project case studies based on success stories or technical implementations.
10. AI Assistant: A chat bot that helps navigate the application.
`;

const UserGuide: React.FC<UserGuideProps> = ({ isOpen, onClose }) => {
  const [loading, setLoading] = useState(true);
  const [learningStep, setLearningStep] = useState(0); // 0: Idle, 1: Scanning, 2: Analyzing, 3: Synthesizing
  const [guideData, setGuideData] = useState<GuideSection[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState<string>('All');

  // Load or Generate Guide
  useEffect(() => {
    if (isOpen) {
        const cached = localStorage.getItem('ai_user_guide_v2');
        if (cached) {
            setGuideData(JSON.parse(cached));
            setLoading(false);
        } else {
            refreshGuide();
        }
    }
  }, [isOpen]);

  const refreshGuide = async () => {
      setLoading(true);
      setLearningStep(1);

      // Simulate scanning steps for "Deep Learning" effect
      setTimeout(() => setLearningStep(2), 1500); // Analying Data Dictionary...
      setTimeout(() => setLearningStep(3), 3000); // Synthesizing Knowledge...

      try {
          // AI Call
          const sections = await generateDynamicUserGuide(CURRENT_APP_FEATURES);
          setGuideData(sections);
          localStorage.setItem('ai_user_guide_v2', JSON.stringify(sections));
      } catch (e) {
          console.error("Failed to generate guide", e);
      } finally {
          setLoading(false);
          setLearningStep(0);
      }
  };

  if (!isOpen) return null;

  const filteredGuide = guideData.filter(section => {
      const matchesSearch = section.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            section.description.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = activeCategory === 'All' || section.category === activeCategory;
      return matchesSearch && matchesCategory;
  });

  const categories = ['All', 'Strategy', 'Technical', 'Documentation', 'Insights'];

  const getIconForSection = (title: string) => {
      const t = title.toLowerCase();
      if (t.includes('design')) return PenTool;
      if (t.includes('describer')) return BookOpen;
      if (t.includes('dictionary')) return FileSpreadsheet;
      if (t.includes('estimat')) return Calculator;
      if (t.includes('qual')) return ShieldCheck;
      if (t.includes('doc')) return FileText;
      if (t.includes('case')) return Presentation;
      if (t.includes('arch') || t.includes('flow')) return Network;
      return Layers;
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/80 backdrop-blur-md animate-fade-in p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl h-[85vh] flex flex-col overflow-hidden relative border border-slate-700/50">

        {/* Header */}
        <div className="bg-slate-900 p-8 text-white relative overflow-hidden shrink-0">
           <div className="absolute top-0 right-0 p-8 opacity-10"><BrainCircuit size={200} /></div>
           <div className="absolute -bottom-10 -left-10 w-64 h-64 bg-indigo-600/30 rounded-full blur-3xl"></div>

           <div className="relative z-10 flex justify-between items-start">
              <div>
                 <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/20 border border-indigo-500/30 text-indigo-300 text-xs font-bold uppercase mb-4 backdrop-blur-md">
