                   />
               </div>
               <div className="flex gap-2 overflow-x-auto hide-scrollbar">
                   {categories.map(cat => (
                       <button 
                          key={cat}
                          onClick={() => setActiveCategory(cat)}
                          className={`px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap transition-all ${activeCategory === cat ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/50' : 'bg-slate-800/50 text-slate-400 hover:bg-slate-800'}`}
                       >
                           {cat}
                       </button>
                   ))}
               </div>
           </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-8 bg-slate-50 relative">
            {loading ? (
                <div className="flex flex-col items-center justify-center h-full space-y-6">
                    <div className="relative">
                        <div className="w-24 h-24 rounded-full border-4 border-indigo-100 border-t-indigo-600 animate-spin"></div>
                        <div className="absolute inset-0 flex items-center justify-center">
                            <BrainCircuit size={32} className="text-indigo-600 animate-pulse"/>
                        </div>
                    </div>
                    <div className="text-center space-y-2">
                        <h3 className="text-xl font-bold text-slate-800">Updating Knowledge Graph...</h3>
                        <p className="text-sm text-slate-500 font-mono">
                            {learningStep === 1 && "Scanning codebase for new modules..."}
                            {learningStep === 2 && "Analyzing 'Data Dictionary' capabilities..."}
                            {learningStep === 3 && "Synthesizing best practices..."}
                        </p>
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {filteredGuide.map((section, idx) => {
                        const Icon = getIconForSection(section.title);
                        return (
                            <div key={idx} className="bg-white rounded-2xl border border-slate-200 p-6 hover:shadow-xl hover:border-indigo-200 transition-all group relative overflow-hidden">
                                <div className="absolute top-0 right-0 p-6 opacity-5 group-hover:opacity-10 transition-opacity transform group-hover:scale-110 duration-500">
                                    <Icon size={100} />
                                </div>

                                <div className="relative z-10">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                            <Icon size={24} />
                                        </div>
                                        <span className="text-[10px] uppercase font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded border border-slate-200">
                                            {section.category}
                                        </span>
                                    </div>

                                    <h3 className="text-xl font-bold text-slate-800 mb-2 group-hover:text-indigo-700 transition-colors">{section.title}</h3>
                                    <p className="text-sm text-slate-600 leading-relaxed mb-4">{section.description}</p>

                                    <div className="space-y-3 mb-6">
                                        {section.features.slice(0, 3).map((feat, i) => (
                                            <div key={i} className="flex items-start gap-2 text-xs text-slate-500">
                                                <CheckCircle size={12} className="text-emerald-500 mt-0.5 shrink-0" />
                                                {feat}
                                            </div>
                                        ))}
                                    </div>

                                    <div className="bg-slate-50 rounded-lg p-3 border border-slate-100 flex gap-3 items-start">
                                        <Zap size={16} className="text-amber-500 mt-0.5 shrink-0" />
                                        <div>
                                            <div className="text-[10px] font-bold text-slate-400 uppercase">Pro Tip</div>
                                            <p className="text-xs text-slate-700 font-medium italic">"{section.bestPractice}"</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default UserGuide;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Database, 
  ArrowRight, 
  Sparkles, 
  Loader, 
  Download, 
  UploadCloud, 
  FileSpreadsheet, 
  Table as TableIcon, 
  Settings, 
  Grid,
  PieChart as PieChartIcon,
  List,
  Search,
  CheckCircle2,
  AlertCircle,
  FileText,
  RefreshCw,
  ArrowLeft,
  LayoutDashboard
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  Tooltip as RechartsTooltip, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid,
  Legend
} from 'recharts';
import { generateDataDictionary } from '../services/geminiService';
import { DataDictionaryItem } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899', '#6366F1'];

const StandaloneDataDictionary: React.FC = () => {
  // View State
  const [viewMode, setViewMode] = useState<'input' | 'dashboard'>('input');
  const [activeTab, setActiveTab] = useState<'summary' | 'dictionary' | 'tables'>('summary');

  // Configuration State
  const [project, setProject] = useState('');
  const [module, setModule] = useState('');
  const [inputType, setInputType] = useState<'text' | 'file'>('text');
  const [inputText, setInputText] = useState('');
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);

  // Data State
  const [isGenerating, setIsGenerating] = useState(false);
  const [dataDictionary, setDataDictionary] = useState<DataDictionaryItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
      const totalColumns = dataDictionary.length;
      const uniqueTables = Array.from(new Set(dataDictionary.map(i => i.tableName)));
      const totalTables = uniqueTables.length;

      // Data Type Distribution
      const typeCounts: Record<string, number> = {};
      dataDictionary.forEach(item => {
          // Simplify types (e.g. VARCHAR(50) -> VARCHAR)
          const simpleType = item.dataType?.split('(')[0]?.toUpperCase() || 'UNKNOWN';
          typeCounts[simpleType] = (typeCounts[simpleType] || 0) + 1;
      });
      const typeData = Object.entries(typeCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 7); // Top 7 types

      // Columns per Table
      const colsPerTable: Record<string, number> = {};
      dataDictionary.forEach(item => {
          colsPerTable[item.tableName] = (colsPerTable[item.tableName] || 0) + 1;
      });
      const tableData = Object.entries(colsPerTable)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 10); // Top 10 tables

      // Constraint Stats
      const pkCount = dataDictionary.filter(i => i.constraint?.toUpperCase().includes('PK') || i.constraint?.toUpperCase().includes('PRIMARY')).length;
      const fkCount = dataDictionary.filter(i => i.constraint?.toUpperCase().includes('FK') || i.constraint?.toUpperCase().includes('FOREIGN')).length;

      return { totalColumns, totalTables, typeData, tableData, uniqueTables, pkCount, fkCount };
  }, [dataDictionary]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);
      setInputText(prev => prev + `\n[Context from uploaded file: ${file.name}]`);
    }
  };

  const handleGenerate = async () => {
    if (!project || !module || !inputText.trim()) {
      setError("Please fill in Project, Module, and provide Input Data.");
      return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const result = await generateDataDictionary(inputText, project, module);
      if (result && result.length > 0) {
          setDataDictionary(result);
          setViewMode('dashboard');
          setActiveTab('summary');
      } else {
          setError("No data dictionary items could be generated. Please check your input format.");
      }
    } catch (e) {
      setError("Failed to generate dictionary. Try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleExportExcel = () => {
    if (typeof window.XLSX === 'undefined') {
        alert("Excel library not loaded.");
        return;
    }

    const wb = window.XLSX.utils.book_new();

    // Sheet 1: Executive Summary (Stats)
    const summaryData = [
        ["Data Dictionary Summary"],
        ["Project", project],
        ["Module", module],
        ["Generated Date", new Date().toLocaleDateString()],
        [""],
        ["Statistics"],
        ["Total Tables", stats.totalTables],
        ["Total Columns", stats.totalColumns],
        ["Primary Keys", stats.pkCount],
        ["Foreign Keys", stats.fkCount]
    ];
    const wsSummary = window.XLSX.utils.aoa_to_sheet(summaryData);
    window.XLSX.utils.book_append_sheet(wb, wsSummary, "Executive Summary");

    // Sheet 2: Data Dictionary (Main Data)
    const dictData = dataDictionary.map(item => ({
        "Table Name": item.tableName,
        "Column Name": item.columnName,
        "Data Type": item.dataType,
        "Length": item.length || '',
        "Constraint": item.constraint || '',
        "Description": item.description,
        "Business Rule": item.businessRule || ''
    }));
    const wsDict = window.XLSX.utils.json_to_sheet(dictData);
    // Auto-width
    const wscols = [{wch: 25}, {wch: 25}, {wch: 15}, {wch: 10}, {wch: 15}, {wch: 60}, {wch: 40}];
    wsDict['!cols'] = wscols;
    window.XLSX.utils.book_append_sheet(wb, wsDict, "Data_Dictionary");

    // Sheet 3: Table List (Unique Tables)
    const tableListData = stats.uniqueTables.map(t => ({
        "Table Name": t,
        "Column Count": dataDictionary.filter(d => d.tableName === t).length,
        "Description": dataDictionary.find(d => d.tableName === t)?.description ? `Stores info related to ${t}` : "" 
    }));
    const wsTables = window.XLSX.utils.json_to_sheet(tableListData);
    wsTables['!cols'] = [{wch: 30}, {wch: 15}, {wch: 50}];
    window.XLSX.utils.book_append_sheet(wb, wsTables, "Table_List");

    window.XLSX.writeFile(wb, `${project}_${module}_DataDictionary.xlsx`);
  };

  const filteredDictionary = dataDictionary.filter(item => 
      item.tableName.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.columnName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // --- INPUT VIEW ---
  if (viewMode === 'input') {
      return (
        <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in items-center justify-center p-6">
            <div className="w-full max-w-4xl bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden flex flex-col md:flex-row h-[600px]">

                {/* Left Panel: Branding */}
                <div className="md:w-1/3 bg-slate-900 p-8 flex flex-col justify-between text-white relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-blue-500 rounded-full blur-[60px] opacity-30"></div>

                    <div className="relative z-10">
                        <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center mb-6 shadow-lg shadow-blue-900/50">
                            <FileSpreadsheet size={24} className="text-white"/>
                        </div>
                        <h2 className="text-2xl font-bold mb-2">Data Dictionary Generator</h2>
                        <p className="text-blue-200 text-sm leading-relaxed">
                            Transform raw DDL scripts or technical specifications into a standardized, business-ready data dictionary.
                        </p>
                    </div>

                    <div className="relative z-10 space-y-4 text-xs text-slate-400">
                        <div className="flex items-center gap-3">
                            <CheckCircle2 size={16} className="text-emerald-500"/>
                            <span>Automated Metadata Extraction</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle2 size={16} className="text-emerald-500"/>
                            <span>Business Description Inference</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle2 size={16} className="text-emerald-500"/>
                            <span>Multi-Sheet Excel Export</span>
                        </div>
                    </div>
                </div>

                {/* Right Panel: Form */}
                <div className="md:w-2/3 p-8 md:p-10 flex flex-col overflow-y-auto">
                    <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <Settings size={20} className="text-slate-400"/> Project Configuration
                    </h3>

                    <div className="space-y-6 flex-1">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase">Project Name</label>
                                <input 
                                    className="w-full p-3 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all"
                                    placeholder="e.g. Finance Data Lake"
                                    value={project}
                                    onChange={(e) => setProject(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase">Sub-Module</label>
                                <input 
                                    className="w-full p-3 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all"
                                    placeholder="e.g. General Ledger"
                                    value={module}
                                    onChange={(e) => setModule(e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase">Input Source</label>
                            <div className="flex gap-2 p-1 bg-slate-100 rounded-xl w-fit mb-2">
                                <button onClick={() => setInputType('text')} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${inputType === 'text' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>Paste DDL / Text</button>
                                <button onClick={() => setInputType('file')} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${inputType === 'file' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>Upload File</button>
                            </div>

                            {inputType === 'text' ? (
                                <textarea 
                                    className="w-full h-48 p-4 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none text-xs font-mono leading-relaxed resize-none transition-all"
                                    placeholder="CREATE TABLE Customers ( ID INT PRIMARY KEY, Name VARCHAR(100)... );"
                                    value={inputText}
                                    onChange={(e) => setInputText(e.target.value)}
                                />
                            ) : (
                                <div className="border-2 border-dashed border-slate-300 rounded-xl h-48 flex flex-col items-center justify-center bg-slate-50 hover:bg-slate-100 transition-colors relative">
                                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileUpload} />
                                    <UploadCloud size={32} className="text-slate-400 mb-2"/>
                                    <p className="text-sm font-bold text-slate-600">{uploadedFileName || "Click or Drag file here"}</p>
                                    <p className="text-xs text-slate-400 mt-1">SQL, TXT, JSON, DOCX</p>
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-100">
                        {error && <div className="mb-4 text-xs text-red-500 bg-red-50 p-2 rounded flex items-center gap-2"><AlertCircle size={14}/> {error}</div>}
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02]"
                        >
                            {isGenerating ? <Loader size={20} className="animate-spin"/> : <Sparkles size={20}/>}
                            Generate Data Dictionary
                        </button>
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">

        {/* Top Navigation Bar */}
        <div className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-4">
                <button onClick={() => setViewMode('input')} className="p-2 hover:bg-slate-100 rounded-lg text-slate-500 transition-colors">
                    <ArrowLeft size={20}/>
                </button>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                        {project} <span className="text-slate-300">/</span> {module}
                    </h2>
                    <p className="text-xs text-slate-500">Dictionary Dashboard</p>
                </div>
            </div>
            <div className="flex gap-3">
                <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-md transition-all hover:shadow-emerald-200">
                    <Download size={16} /> Export Excel
                </button>
                <button onClick={() => setViewMode('input')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-50 transition-all">
                    <RefreshCw size={16} /> New Analysis
                </button>
            </div>
        </div>

        {/* Tab Bar */}
        <div className="bg-white border-b border-slate-200 px-6">
            <div className="flex gap-6">
                <button onClick={() => setActiveTab('summary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'summary' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <PieChartIcon size={16}/> Executive Summary
                </button>
                <button onClick={() => setActiveTab('dictionary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'dictionary' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <Grid size={16}/> Data Dictionary
                </button>
                <button onClick={() => setActiveTab('tables')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'tables' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <List size={16}/> Table Register
                </button>
            </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 md:p-8">
            <div className="max-w-7xl mx-auto h-full">

                {/* --- TAB 1: SUMMARY DASHBOARD --- */}
                {activeTab === 'summary' && (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">

                        {/* Key Metrics */}
                        <div className="lg:col-span-2 grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Tables</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalTables}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Columns</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalColumns}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Primary Keys</div>
                                <div className="text-3xl font-bold text-indigo-600">{stats.pkCount}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Foreign Keys</div>
                                <div className="text-3xl font-bold text-pink-600">{stats.fkCount}</div>
                            </div>
                        </div>

                        {/* Chart: Data Types */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <PieChartIcon size={18} className="text-blue-500"/> Data Type Distribution
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={stats.typeData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                        >
                                            {stats.typeData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Legend verticalAlign="bottom" height={36} iconType="circle"/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Chart: Table Complexity */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <LayoutDashboard size={18} className="text-emerald-500"/> Top Tables by Column Count
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats.tableData} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                        <RechartsTooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Bar dataKey="value" fill="#10B981" radius={[0, 4, 4, 0]} barSize={20} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
