  const [context, setContext] = useState(initialContext);
  const [showResults, setShowResults] = useState(embedded && initialInputs ? true : false);
  const [activeTab, setActiveTab] = useState<'drivers' | 'resources' | 'timeline' | 'assumptions'>('drivers');

  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [assumptions, setAssumptions] = useState<AssumptionData>({ inScope: [], outScope: [] });

  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);

  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);
  const [aiRationale, setAiRationale] = useState<string>("Analyzing project requirements...");

  const [customResourceCounts, setCustomResourceCounts] = useState<Record<string, number>>({
    'pm': 1, 'arch': 1, 'lead': 1, 'dev': 2, 'qa': 1
  });

  useEffect(() => {
    if (initialInputs) {
        setEstimationInputs(initialInputs);
    } else {
        const defaults: EstimationInputs = {};
        ALL_MODULES_CONFIG.forEach(m => m.drivers.forEach(d => defaults[d.id] = d.defaultValue));
        setEstimationInputs(defaults);
    }
    if (!embedded) setHistoryItems(getHistory('Estimator'));
  }, [initialInputs, embedded]);

  useEffect(() => {
      if (embedded && onSave && Object.keys(estimationInputs).length > 0) {
          onSave(estimationInputs);
      }
  }, [estimationInputs, embedded, onSave]);

  useEffect(() => { if (initialContext) setContext(initialContext); }, [initialContext]);

  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // --- CALCULATION ENGINE ---
  const calculations = useMemo(() => {
    let totalTechHours = 0;
    ALL_MODULES_CONFIG.forEach(mod => {
      mod.drivers.forEach(driver => {
        const val = estimationInputs[driver.id] || 0;
        totalTechHours += val * driver.multiplier;
      });
    });

    const testingBuffer = totalTechHours * 0.30;
    const grandTotalHours = totalTechHours + testingBuffer;

    const resourceList = [
        { id: 'pm', role: 'Project Manager', rate: 800, utilization: 0.5 },
        { id: 'arch', role: 'Solution Architect', rate: 950, utilization: 0.25 },
        { id: 'lead', role: 'Tech Lead', rate: 750, utilization: 1.0 },
        { id: 'dev', role: 'Developer', rate: 500, utilization: 1.0 },
        { id: 'qa', role: 'QA Engineer', rate: 450, utilization: 1.0 },
    ];

    const effectiveDevCount = customResourceCounts['dev'] || 1;
    const weeklyVelocity = effectiveDevCount * 35; 
    const calculatedDurationWeeks = Math.max(4, Math.ceil(grandTotalHours / weeklyVelocity));

    const finalResources = resourceList.map(r => ({
        ...r,
        count: customResourceCounts[r.id] || 1,
        totalCost: (calculatedDurationWeeks * 5) * (customResourceCounts[r.id] || 1) * r.rate * r.utilization
    }));

    const totalProjectCost = finalResources.reduce((acc, r) => acc + r.totalCost, 0);

    const phases = [
        { name: "Inception", pct: 0.10, color: "bg-blue-500" },
        { name: "Design", pct: 0.15, color: "bg-indigo-500" },
        { name: "Build", pct: 0.50, color: "bg-emerald-500" },
        { name: "Testing", pct: 0.20, color: "bg-orange-500" },
        { name: "Deploy", pct: 0.05, color: "bg-slate-700" }
    ];

    let currentStart = 0;
    const timelineData = phases.map(p => {
        const weeks = Math.max(1, Math.round(calculatedDurationWeeks * p.pct));
        const start = currentStart;
        currentStart += weeks;
        return { ...p, duration: weeks, startOffset: start };
    });

    return { grandTotalHours, calculatedDurationWeeks, totalProjectCost, finalResources, timelineData };
  }, [estimationInputs, customResourceCounts]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);

      const reader = new FileReader();
      reader.onload = (evt) => {
        const content = evt.target?.result;
        if (typeof content === 'string') {
          // If it's a text-readable file, append context
          setContext(prev => prev + `\n\n[Content from ${file.name}]:\n${content.substring(0, 5000)}... (truncated)`);
        } else {
          // If binary (like xlsx unparsed here), just add name reference
          setContext(prev => prev + `\n\n[Attached Reference File: ${file.name}]`);
        }
      };

      // Try to read as text first
      if (file.name.match(/\.(txt|csv|json|md|xml|sql)$/i)) {
        reader.readAsText(file);
      } else {
        // For binaries, we just use the name for now as the "Prompt" to the AI
        setContext(prev => prev + `\n\n[Attached Reference File: ${file.name}]`);
      }
    }
  };

  const removeFile = (fileName: string) => {
    setUploadedFiles(prev => prev.filter(f => f !== fileName));
    // Note: We don't remove text from context to avoid complex string manipulation, 
    // user can manually edit the text area if needed.
  };

  const handleGenerate = async () => {
    if (!context.trim()) return;
    setIsGenerating(true);
    setEta(8);
    setError(null);
    try {
      const [estimationResult, assumptionResult] = await Promise.all([
         generateDynamicEstimation(context),
         generateAssumptions(context)
      ]);

      if (estimationResult && estimationResult.inputs) {
          setEstimationInputs(prev => ({...prev, ...estimationResult.inputs}));
          const totalObj = Object.values(estimationResult.inputs as Record<string, number>).reduce((a: number, b: number) => a + (b || 0), 0);
          if (totalObj > 100) setCustomResourceCounts(prev => ({...prev, dev: 4, qa: 2}));
          else if (totalObj > 50) setCustomResourceCounts(prev => ({...prev, dev: 3, qa: 1}));

          setAiRationale(estimationResult.rationale || "Estimation updated based on requirements.");
          if (assumptionResult) setAssumptions(assumptionResult);

          if (!embedded) {
             saveHistory('Estimator', context.substring(0, 40) + '...', { data: estimationResult.inputs, rationale: estimationResult.rationale, assumptions: assumptionResult }, uploadedFiles);
             setHistoryItems(getHistory('Estimator'));
          }
          setShowResults(true);
          setActiveTab('drivers');
          setIsLearning(true);
          analyzeAndLearn(context, null, estimationResult.inputs, ['Manager'], 'initial').finally(() => setIsLearning(false));
      } else {
          setError("AI could not infer specific project drivers.");
      }
    } catch (e) {
      setError("An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const loadHistoryItem = (item: any) => {
    setContext(item.summary);
    const inputData = item.data.data || item.data;
    setEstimationInputs(inputData);
    if (item.data.rationale) setAiRationale(item.data.rationale);
    if (item.data.assumptions) setAssumptions(item.data.assumptions);
    setUploadedFiles(item.files || []);
    setShowResults(true);
    setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);

  return (
    <div className={`flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in ${embedded ? 'bg-transparent' : ''}`}>

      {/* Header - Hidden if Embedded */}
      {!embedded && (
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><Calculator size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Estimator
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Driver Analysis & Resource Modeling</p>
            </div>
         </div>
         <div className="flex gap-2">
            <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-100'}`}><History size={18} /> History</button>
         </div>
      </div>
      )}

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <AlertTriangle size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-16 right-4 z-50 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
            <h3 className="font-bold text-sm mb-3">Recent Estimates</h3>
            <div className="space-y-2 max-h-60 overflow-y-auto">
               {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> : 
               historyItems.map((h, i) => (
                  <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                     <div className="flex justify-between items-start mb-1">
                        <span className="font-bold text-slate-700 truncate max-w-[180px]">{h.summary}</span>
                        <span className="text-slate-400 text-[10px]">{h.date}</span>
                     </div>
                     <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer" onClick={(e) => handleDeleteHistory(h.id, e)}><Trash2 size={14} /></div>
                  </button>
               ))}
            </div>
         </div>
      )}

      <div className={`flex-1 overflow-y-auto ${embedded ? 'p-0' : 'p-6 md:p-8'}`}>
         <div className="max-w-7xl mx-auto space-y-8">

            {/* KPI Cards (Always Visible if Results) */}
            {showResults && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-fade-in-up">
                    <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
                        <div>
                            <p className="text-xs font-bold text-slate-400 uppercase">Estimated Cost</p>
                            <h3 className="text-2xl font-bold text-emerald-600">{formatCurrency(calculations.totalProjectCost)}</h3>
                        </div>
                        <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><DollarSign size={24}/></div>
                    </div>
                    <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
                        <div>
                            <p className="text-xs font-bold text-slate-400 uppercase">Total Effort</p>
                            <h3 className="text-2xl font-bold text-blue-600">{calculations.grandTotalHours.toFixed(0)} <span className="text-sm text-slate-400 font-medium">Hrs</span></h3>
                        </div>
                        <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><Clock size={24}/></div>
                    </div>
                    <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
                        <div>
                            <p className="text-xs font-bold text-slate-400 uppercase">Duration</p>
                            <h3 className="text-2xl font-bold text-indigo-600">{calculations.calculatedDurationWeeks} <span className="text-sm text-slate-400 font-medium">Weeks</span></h3>
                        </div>
                        <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calendar size={24}/></div>
                    </div>
                </div>
            )}

            {/* Input / Re-Run Section */}
            <div className={`bg-white rounded-xl shadow-sm border border-slate-200 transition-all duration-500 ${showResults ? 'p-4' : 'p-8'}`}>
               {!showResults ? (
                   <div className="space-y-4 animate-fade-in">
                        <div className="flex items-center gap-3 mb-2">
                            <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg"><Sparkles size={20}/></div>
                            <h3 className="font-bold text-slate-800 text-lg">New Estimation</h3>
                        </div>
                        <p className="text-sm text-slate-500">Describe the project scope or upload a questionnaire (Excel/PDF) to auto-populate drivers.</p>

                        <textarea 
                            value={context}
                            onChange={(e) => setContext(e.target.value)}
                            className="w-full h-32 p-4 border border-slate-300 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none bg-slate-50 focus:bg-white transition-colors"
                            placeholder="e.g. Migration of 50 Oracle tables to Snowflake, with high complexity data quality rules..."
                        />

                        {/* File Upload Section */}
                        <div className="flex gap-2 flex-wrap">
                            <label className="flex items-center gap-2 cursor-pointer bg-slate-50 hover:bg-slate-100 text-slate-600 px-4 py-2 rounded-lg text-xs font-bold border border-slate-200 transition-colors">
                                <Paperclip size={14} /> Attach Questionnaire
                                <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.csv,.json,.md,.xlsx,.xls,.pdf,.docx" />
                            </label>
                            {uploadedFiles.map((file, i) => (
                                <div key={i} className="flex items-center gap-1 bg-indigo-50 text-indigo-700 px-3 py-2 rounded-lg text-xs border border-indigo-100">
                                    <FileText size={12} /> {file}
                                    <button onClick={() => removeFile(file)} className="hover:text-red-500 ml-1"><X size={12}/></button>
                                </div>
                            ))}
                        </div>

                        <button 
                            onClick={handleGenerate} 
                            disabled={!context.trim() || isGenerating} 
                            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all shadow-md hover:shadow-lg disabled:opacity-50 mt-4"
                        >
                            {isGenerating ? <Loader size={18} className="animate-spin"/> : <Calculator size={18}/>}
                            {isGenerating && eta > 0 ? `Calculating (${eta}s)` : 'Calculate Estimate'}
                        </button>
                   </div>
               ) : (
                   <div className="flex items-center justify-between">
                       <div className="flex items-center gap-3">
                           <div className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg"><FileText size={16}/></div>
                           <p className="text-sm text-slate-600 truncate max-w-xl italic">"{context.substring(0, 100)}..."</p>
                       </div>
                       <div className="flex items-center gap-2">
                           <label className="cursor-pointer text-xs font-bold text-slate-500 hover:text-indigo-600 flex items-center gap-1 bg-slate-50 px-2 py-1.5 rounded hover:bg-slate-100 transition-colors">
                               <UploadCloud size={12} /> Add File
                               <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.csv,.json,.md,.xlsx,.xls,.pdf,.docx" />
                           </label>
                           <button onClick={handleGenerate} className="text-xs font-bold text-indigo-600 hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-colors flex items-center gap-1">
                               <ArrowRight size={12}/> Re-Analyze
                           </button>
                       </div>
                   </div>
               )}
            </div>

            {/* Detailed Views */}
            {showResults && (
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in-up">
                    <div className="border-b border-slate-200 flex">
                        {['drivers', 'resources', 'timeline', 'assumptions'].map((tab) => (
                            <button 
                                key={tab}
                                onClick={() => setActiveTab(tab as any)}
                                className={`flex-1 py-4 text-sm font-bold text-center border-b-2 transition-colors capitalize ${activeTab === tab ? 'border-indigo-600 text-indigo-600 bg-indigo-50/30' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>

                    <div className="p-6">
                        {activeTab === 'drivers' && (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {ALL_MODULES_CONFIG.map(mod => (
                                    <div key={mod.id} className="border border-slate-100 rounded-xl p-5 hover:border-slate-300 transition-colors bg-slate-50/50">
                                        <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 flex items-center gap-2">
                                            <mod.icon size={14} style={{color: mod.color}} /> {mod.title}
                                        </h4>
                                        <div className="space-y-4">
                                            {mod.drivers.map(driver => (
                                                <div key={driver.id} className="flex items-center justify-between">
                                                    <div className="flex-1">
                                                        <p className="text-sm font-bold text-slate-700">{driver.label}</p>
                                                        <p className="text-[10px] text-slate-400">{driver.description}</p>
                                                    </div>
                                                    <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-lg p-1">
                                                        <button className="w-6 h-6 flex items-center justify-center hover:bg-slate-100 rounded text-slate-500" onClick={() => setEstimationInputs(p => ({...p, [driver.id]: Math.max(0, (p[driver.id]||0)-1)}))}>-</button>
                                                        <input 
                                                            className="w-10 text-center text-sm font-bold text-slate-800 outline-none" 
                                                            value={estimationInputs[driver.id] || 0} 
                                                            onChange={(e) => setEstimationInputs(p => ({...p, [driver.id]: parseInt(e.target.value)||0}))}
                                                        />
                                                        <button className="w-6 h-6 flex items-center justify-center hover:bg-slate-100 rounded text-slate-500" onClick={() => setEstimationInputs(p => ({...p, [driver.id]: (p[driver.id]||0)+1}))}>+</button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        {activeTab === 'resources' && (
                            <div className="overflow-x-auto">
                                <table className="w-full text-sm">
                                    <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
                                        <tr>
                                            <th className="px-4 py-3 text-left">Role</th>
                                            <th className="px-4 py-3 text-center">Headcount</th>
                                            <th className="px-4 py-3 text-right">Rate/Day</th>
                                            <th className="px-4 py-3 text-right">Cost</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {calculations.finalResources.map(r => (
                                            <tr key={r.id} className="hover:bg-slate-50">
                                                <td className="px-4 py-3 font-medium text-slate-700 flex items-center gap-2"><Users size={14} className="text-slate-400"/> {r.role}</td>
                                                <td className="px-4 py-3 text-center">
                                                    <div className="inline-flex items-center border rounded-lg bg-white">
                                                        <button className="px-2 py-1 hover:bg-slate-100" onClick={() => setCustomResourceCounts(p => ({...p, [r.id]: Math.max(0, (p[r.id]||1)-1)}))}>-</button>
                                                        <span className="w-8 text-center font-bold">{r.count}</span>
                                                        <button className="px-2 py-1 hover:bg-slate-100" onClick={() => setCustomResourceCounts(p => ({...p, [r.id]: (p[r.id]||1)+1}))}>+</button>
                                                    </div>
                                                </td>
                                                <td className="px-4 py-3 text-right text-slate-500">${r.rate}</td>
                                                <td className="px-4 py-3 text-right font-bold text-slate-800">{formatCurrency(r.totalCost)}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}

                        {activeTab === 'timeline' && (
                            <div className="space-y-6 pt-2">
                                {calculations.timelineData.map((phase, i) => (
                                    <div key={i} className="relative">
                                        <div className="flex justify-between text-xs font-bold text-slate-600 mb-1">
                                            <span>{phase.name}</span>
                                            <span>{phase.duration} Wks</span>
                                        </div>
                                        <div className="h-3 bg-slate-100 rounded-full overflow-hidden">
                                            <div 
                                                className={`h-full ${phase.color} shadow-sm`} 
                                                style={{
                                                    width: `${(phase.duration / calculations.calculatedDurationWeeks) * 100}%`,
                                                    marginLeft: `${(phase.startOffset / calculations.calculatedDurationWeeks) * 100}%`
                                                }}
                                            ></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        {activeTab === 'assumptions' && (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-3">
                                    <h4 className="text-sm font-bold text-emerald-700 flex items-center gap-2"><ListChecks size={16}/> In Scope</h4>
                                    {assumptions.inScope.map((item, i) => (
                                        <div key={i} className="bg-emerald-50 border border-emerald-100 p-2 rounded text-xs text-slate-700 flex gap-2">
                                            <div className="mt-1 w-1.5 h-1.5 rounded-full bg-emerald-500 shrink-0"/> {item}
                                        </div>
                                    ))}
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-sm font-bold text-red-700 flex items-center gap-2"><X size={16}/> Out of Scope</h4>
                                    {assumptions.outScope.map((item, i) => (
                                        <div key={i} className="bg-red-50 border border-red-100 p-2 rounded text-xs text-slate-700 flex gap-2">
                                            <div className="mt-1 w-1.5 h-1.5 rounded-full bg-red-500 shrink-0"/> {item}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default StandaloneEstimator;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Calculator, 
  Settings, 
  Download, 
  Clock, 
  DollarSign, 
  Calendar, 
  Sparkles,
  Loader,
  UploadCloud, 
  History,
  HelpCircle,
  X,
  AlertTriangle,
  Database,
  ShieldCheck,
  Globe,
  Layers,
  FileSpreadsheet,
  ArrowRight,
  BrainCircuit,
  FileText,
  Trash2,
  ListChecks,
  Plus,
  Users,
  Paperclip,
  Microscope
} from 'lucide-react';
import { generateDynamicEstimation, generateAssumptions, saveHistory, getHistory, deleteHistory, analyzeAndLearn } from '../services/geminiService';
import { ModuleConfig, EstimationInputs, AssumptionData } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

// --- CONFIGURATION ---
const ALL_MODULES_CONFIG: ModuleConfig[] = [
  {
    id: 'di',
    title: 'Data Integration',
    icon: Database,
    color: '#3B82F6', 
    drivers: [
      { id: 'di_src', label: 'Source Systems', category: 'fixed', defaultValue: 3, multiplier: 8, description: 'Connection setup & analysis per source' },
      { id: 'di_map_s', label: 'Simple Mappings', category: 'simple', defaultValue: 10, multiplier: 8, description: 'Direct loads, minor transformations' },
      { id: 'di_map_m', label: 'Medium Mappings', category: 'medium', defaultValue: 15, multiplier: 16, description: 'Multiple joins, standard business logic' },
      { id: 'di_map_c', label: 'Complex Mappings', category: 'complex', defaultValue: 5, multiplier: 24, description: 'Complex logic, hierarchical data, stored procs' },
