const safeJsonParse = <T>(text: string | undefined, fallback: T): T => {
    if (!text) return fallback;
    try {
        const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanText) as T;
    } catch (e) {
        console.warn("JSON Parse Error", e);
        return fallback;
    }
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error) {
        if (retries === 0) throw error;
        await new Promise(resolve => setTimeout(resolve, delay));
        return retryWithBackoff(fn, retries - 1, delay * 2);
    }
};

// --- History Management ---

export const getHistory = (type: string): any[] => {
    const item = localStorage.getItem(`history_${type}`);
    return item ? JSON.parse(item) : [];
};

export const saveHistory = (type: string, summary: string, data: any, files: string[] = []) => {
    const history = getHistory(type);
    const newItem = {
        id: Date.now().toString(),
        type,
        summary,
        data,
        files,
        date: new Date().toLocaleDateString()
    };
    localStorage.setItem(`history_${type}`, JSON.stringify([newItem, ...history].slice(0, 20)));
};

export const deleteHistory = (id: string) => {
    const types = ['Estimator', 'Architecture', 'DataFlow', 'ERDiagram', 'DataQuality', 'CaseStory', 'Describer', 'DataDictionary'];
    types.forEach(type => {
        const hist = getHistory(type);
        const filtered = hist.filter((h: any) => h.id !== id);
        if (hist.length !== filtered.length) {
            localStorage.setItem(`history_${type}`, JSON.stringify(filtered));
        }
    });
};

// --- Knowledge Base (Learning) Functions ---

const getLearnedPatterns = (): LearnedPattern[] => {
    const item = localStorage.getItem('kb_patterns');
    return item ? JSON.parse(item) : [];
};

const saveLearnedPattern = (pattern: LearnedPattern) => {
    const existing = getLearnedPatterns();
    // Avoid duplicates roughly by text check
    if (!existing.find(p => p.rule === pattern.rule)) {
        localStorage.setItem('kb_patterns', JSON.stringify([pattern, ...existing].slice(0, 50)));
    }
};

const retrieveRelevantPatterns = (context: string): string[] => {
    const patterns = getLearnedPatterns();
    const contextLower = context.toLowerCase();

    // Simple keyword matching: if the context mentions a tag found in the pattern, include the pattern
    const relevant = patterns.filter(p => {
        return p.tags.some(tag => contextLower.includes(tag.toLowerCase()));
    });

    return relevant.map(p => `[Learned Preference]: ${p.rule}`);
};

export const analyzeAndLearn = async (context: string, prompt: string | null, data: any, audience: string[], type: string) => {
    // Only learn on specific triggers to avoid noise
    if (type !== 'acceptance' && type !== 'refinement') return;

    try {
        const learningPrompt = `
            You are a Knowledge Management AI. 
            Analyze the following Project Context and the Final Design/Estimates provided.
            Extract 1 (one) generic, reusable architectural rule or preference that should be applied to future projects similar to this one.

            Context: ${context} ${prompt ? 'User Feedback: ' + prompt : ''}
            Design Summary: ${JSON.stringify(data).substring(0, 500)}...

            Output JSON: { "tags": ["Keyword1", "Keyword2"], "rule": "Concise rule string" }
            Example: { "tags": ["SAP", "Migration"], "rule": "When migrating SAP Data, always include a specialized staging layer for IDocs." }
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: learningPrompt,
            config: { responseMimeType: "application/json" }
        });

        const result = safeJsonParse(response.text, { tags: [], rule: "" });
        if (result.rule && result.tags.length > 0) {
            saveLearnedPattern({
                id: Date.now().toString(),
                tags: result.tags,
                rule: result.rule,
                timestamp: Date.now()
            });
            console.log("Learned new pattern:", result.rule);
        }
    } catch (e) {
        console.error("Learning failed", e);
    }
};
