export const generateDynamicEstimation = async (context: string): Promise<{inputs: EstimationInputs, rationale: string}> => {
    try {
        const prompt = `
            Act as a Technical Project Manager performing a rigorous effort estimation.
            You must analyze the input context (RFP text, File Summaries) to populate key effort drivers.

            Context: ${context}

            STEP 1: LIST ENTITIES (Chain of Thought)
            - Internally list all source systems, tables, and files mentioned.
            - If an Excel summary says "Sheet 'Customers': 5000 rows", that counts as 1 Entity/Table.
            - If text says "Migrate 50 tables", use 50.

            STEP 2: CLASSIFY COMPLEXITY
            - Simple Mapping (1:1 move): Default 60% of tables.
            - Medium Mapping (Joins/Lookups): Default 30% of tables.
            - Complex Mapping (Aggregates/Procedures): Default 10% of tables.
            - Apply this ratio to the total count if specific complexity isn't stated.

            STEP 3: ASSIGN DRIVERS
            Return counts for the following keys:
            - di_src (Source Systems count)
            - di_map_s (Simple Mappings), di_map_m (Medium), di_map_c (Complex)
            - di_task (Task flows - usually 1 per 5 mappings)
            - dq_prof (Profiling objects - usually equal to total tables)
            - dq_rule_s (Simple DQ Rules), dq_rule_m, dq_rule_c, dq_sc (Scorecards)
            - dg_src (Governance Resources), dg_term (Business Terms), dg_pol (Policies), dg_lin (Lineage)
            - mdm_dom (Domains), mdm_ing_s (Simple Ingestion), mdm_ing_c, mdm_match (Match Rules)

            Provide a detailed 'rationale' string. It MUST explain the math:
            e.g., "Found 20 tables in Excel summary. Applied 60/30/10 split: 12 Simple, 6 Medium, 2 Complex. Added 1 Task flow per 5 mappings (Total 4)."
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        inputs: {
                            type: Type.OBJECT,
                            properties: {
                                di_src: { type: Type.NUMBER },
                                di_map_s: { type: Type.NUMBER },
                                di_map_m: { type: Type.NUMBER },
                                di_map_c: { type: Type.NUMBER },
                                di_task: { type: Type.NUMBER },
                                dq_prof: { type: Type.NUMBER },
                                dq_rule_s: { type: Type.NUMBER },
                                dq_rule_m: { type: Type.NUMBER },
                                dq_rule_c: { type: Type.NUMBER },
                                dq_sc: { type: Type.NUMBER },
                                dg_src: { type: Type.NUMBER },
                                dg_term: { type: Type.NUMBER },
                                dg_pol: { type: Type.NUMBER },
                                dg_lin: { type: Type.NUMBER },
                                mdm_dom: { type: Type.NUMBER },
                                mdm_ing_s: { type: Type.NUMBER },
                                mdm_ing_c: { type: Type.NUMBER },
                                mdm_match: { type: Type.NUMBER },
                            }
                        },
                        rationale: { type: Type.STRING }
                    },
                    required: ["inputs", "rationale"]
                }
            }
        }));
        return safeJsonParse(response.text, { inputs: {}, rationale: "" });
    } catch (e) {
        return { inputs: {}, rationale: "" };
    }
};

