interface StandaloneEstimatorProps {
  embedded?: boolean;
  initialContext?: string;
  initialInputs?: EstimationInputs;
  onSave?: (inputs: EstimationInputs) => void;
}

const StandaloneEstimator: React.FC<StandaloneEstimatorProps> = ({ 
  embedded = false, 
  initialContext = '', 
  initialInputs, 
  onSave 
}) => {
  const [context, setContext] = useState(initialContext);
  const [showResults, setShowResults] = useState(embedded && initialInputs ? true : false);
  const [activeTab, setActiveTab] = useState<'drivers' | 'resources' | 'timeline' | 'assumptions'>('drivers');

  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [assumptions, setAssumptions] = useState<AssumptionData>({ inScope: [], outScope: [] });

  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);

  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [showHelp, setShowHelp] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showConfig, setShowConfig] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);
  const [aiRationale, setAiRationale] = useState<string>("Analyzing project requirements...");

  const [customResourceCounts, setCustomResourceCounts] = useState<Record<string, number>>({
    'pm': 1, 'arch': 1, 'lead': 1, 'dev': 2, 'qa': 1
  });

  useEffect(() => {
    if (initialInputs) {
        setEstimationInputs(initialInputs);
    } else {
        const defaults: EstimationInputs = {};
        ALL_MODULES_CONFIG.forEach(m => m.drivers.forEach(d => defaults[d.id] = d.defaultValue));
        setEstimationInputs(defaults);
    }
    if (!embedded) setHistoryItems(getHistory('Estimator'));
  }, [initialInputs, embedded]);

  useEffect(() => {
      if (embedded && onSave && Object.keys(estimationInputs).length > 0) {
          onSave(estimationInputs);
      }
  }, [estimationInputs, embedded, onSave]);

  useEffect(() => { if (initialContext) setContext(initialContext); }, [initialContext]);

  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // --- CALCULATION ENGINE ---
  const calculations = useMemo(() => {
    let totalTechHours = 0;
    ALL_MODULES_CONFIG.forEach(mod => {
      mod.drivers.forEach(driver => {
        const val = estimationInputs[driver.id] || 0;
        totalTechHours += val * driver.multiplier;
      });
    });

    const testingBuffer = totalTechHours * 0.30;
    const grandTotalHours = totalTechHours + testingBuffer;

    const resourceList = [
        { id: 'pm', role: 'Project Manager', rate: 800, utilization: 0.5 },
        { id: 'arch', role: 'Solution Architect', rate: 950, utilization: 0.25 },
        { id: 'lead', role: 'Tech Lead', rate: 750, utilization: 1.0 },
        { id: 'dev', role: 'Developer', rate: 500, utilization: 1.0 },
        { id: 'qa', role: 'QA Engineer', rate: 450, utilization: 1.0 },
    ];

    const effectiveDevCount = customResourceCounts['dev'] || 1;
    const weeklyVelocity = effectiveDevCount * 35; 
    const calculatedDurationWeeks = Math.max(4, Math.ceil(grandTotalHours / weeklyVelocity));

    const finalResources = resourceList.map(r => ({
        ...r,
        count: customResourceCounts[r.id] || 1,
        totalCost: (calculatedDurationWeeks * 5) * (customResourceCounts[r.id] || 1) * r.rate * r.utilization
    }));

    const totalProjectCost = finalResources.reduce((acc, r) => acc + r.totalCost, 0);

    const phases = [
        { name: "Inception", pct: 0.10, color: "bg-blue-500" },
        { name: "Design", pct: 0.15, color: "bg-indigo-500" },
        { name: "Build", pct: 0.50, color: "bg-emerald-500" },
        { name: "Testing", pct: 0.20, color: "bg-orange-500" },
        { name: "Deploy", pct: 0.05, color: "bg-slate-700" }
    ];

    let currentStart = 0;
    const timelineData = phases.map(p => {
        const weeks = Math.max(1, Math.round(calculatedDurationWeeks * p.pct));
        const start = currentStart;
        currentStart += weeks;
        return { ...p, duration: weeks, startOffset: start };
    });

    return { grandTotalHours, calculatedDurationWeeks, totalProjectCost, finalResources, timelineData };
  }, [estimationInputs, customResourceCounts]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);

      const reader = new FileReader();

      // Excel/CSV Handling for PRECISE Volume Counting
      if (file.name.match(/\.(xlsx|xls|csv)$/i)) {
          reader.onload = (evt) => {
              if (typeof window.XLSX !== 'undefined') {
                  try {
                      const bstr = evt.target?.result;
                      const wb = window.XLSX.read(bstr, { type: 'binary' });

                      let summary = `\n[Structured Analysis of ${file.name}]:\n`;
                      let totalRows = 0;

                      wb.SheetNames.forEach((sheetName: string) => {
                          const ws = wb.Sheets[sheetName];
                          const data = window.XLSX.utils.sheet_to_json(ws, { header: 1 });
                          const rowCount = data.length > 1 ? data.length - 1 : 0;
                          const colCount = data.length > 0 ? (data[0] as any[]).length : 0;
                          totalRows += rowCount;
                          summary += `- Sheet '${sheetName}': ${rowCount} rows, ${colCount} columns.\n`;
                      });

                      summary += `TOTAL ROWS DETECTED: ${totalRows}\n`;
                      setContext(prev => prev + summary);
                  } catch (e) {
                      setContext(prev => prev + `\n[Error parsing Excel: ${file.name}. Treating as text.]`);
                  }
              }
          };
          reader.readAsBinaryString(file);
      } else {
          // Text Handling
          reader.onload = (evt) => {
            const content = evt.target?.result;
            if (typeof content === 'string') {
              setContext(prev => prev + `\n\n[Content from ${file.name}]:\n${content.substring(0, 5000)}... (truncated)`);
            }
          };
          reader.readAsText(file);
      }
    }
  };

  const removeFile = (fileName: string) => {
    setUploadedFiles(prev => prev.filter(f => f !== fileName));
  };

  const handleGenerate = async () => {
    if (!context.trim()) return;
    setIsGenerating(true);
    setEta(8);
    setError(null);
    try {
      const [estimationResult, assumptionResult] = await Promise.all([
         generateDynamicEstimation(context),
         generateAssumptions(context)
      ]);

      if (estimationResult && estimationResult.inputs) {
          setEstimationInputs(prev => ({...prev, ...estimationResult.inputs}));

          // Heuristic to scale resources based on object count
          const totalObj = Object.values(estimationResult.inputs as Record<string, number>).reduce((a: number, b: number) => a + (b || 0), 0);
          if (totalObj > 100) setCustomResourceCounts(prev => ({...prev, dev: 4, qa: 2}));
          else if (totalObj > 50) setCustomResourceCounts(prev => ({...prev, dev: 3, qa: 1}));

          setAiRationale(estimationResult.rationale || "Estimation updated based on requirements.");
          if (assumptionResult) setAssumptions(assumptionResult);

          if (!embedded) {
             saveHistory('Estimator', context.substring(0, 40) + '...', { data: estimationResult.inputs, rationale: estimationResult.rationale, assumptions: assumptionResult }, uploadedFiles);
             setHistoryItems(getHistory('Estimator'));
          }
          setShowResults(true);
          setActiveTab('drivers');
          setIsLearning(true);
          analyzeAndLearn(context, null, estimationResult.inputs, ['Manager'], 'initial').finally(() => setIsLearning(false));
      } else {
          setError("AI could not infer specific project drivers.");
      }
    } catch (e) {
      setError("An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
      setEta(0);
    }
  };

  const loadHistoryItem = (item: any) => {
    setContext(item.summary);
    const inputData = item.data.data || item.data;
    setEstimationInputs(inputData);
    if (item.data.rationale) setAiRationale(item.data.rationale);
    if (item.data.assumptions) setAssumptions(item.data.assumptions);
    setUploadedFiles(item.files || []);
    setShowResults(true);
    setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteHistory(id);
    setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);

  return (
    <div className={`flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in ${embedded ? 'bg-transparent' : ''}`}>

      {/* Header - Hidden if Embedded */}
      {!embedded && (
      <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm z-10">
         <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><Calculator size={20}/></div>
            <div>
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                   Estimator
                   {isLearning && <span className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded text-[10px] uppercase font-bold animate-pulse"><BrainCircuit size={10} /> Learning</span>}
               </h2>
               <p className="text-xs text-slate-500">AI-Powered Driver Analysis & Resource Modeling</p>
            </div>
         </div>
         <div className="flex gap-2">
            <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-3 py-2 rounded-lg transition-colors ${showHistory ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-100'}`}><History size={18} /> History</button>
         </div>
      </div>
      )}

      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg animate-fade-in">
           <AlertTriangle size={16} /> <span className="text-sm">{error}</span> <button onClick={() => setError(null)}><X size={14}/></button>
        </div>
      )}

      {showHistory && (
         <div className="absolute top-16 right-4 z-50 w-80 bg-white rounded-xl shadow-xl border border-slate-200 p-4 animate-fade-in-up">
