  BrainCircuit,
  CheckCircle,
  Loader,
  X,
  Copy,
  Check,
  Image as ImageIcon,
  FileCode,
  Sparkles,
  Zap,
  Info,
  ZoomIn,
  ZoomOut,
  Maximize,
  MessageSquare,
  Send,
  Move,
  Table,
  Layers,
  FileText
} from 'lucide-react';
import { Node, Edge, RefinementSuggestion, DesignData, ArchitectureCanvasHandle } from '../types';
import { generateDesignRefinements } from '../services/geminiService';

interface ArchitectureCanvasProps {
  aiNodes: Node[];
  aiEdges: Edge[];
  isThinking: boolean;
  thoughts: string[];
  context?: string; 
  audience?: string[];
  onApplyRefinement?: (newDesign: DesignData) => void;
  // New props for unified re-input
  onRefine?: (prompt: string) => void;
  refinementPlaceholder?: string;
}

const ArchitectureCanvas = forwardRef<ArchitectureCanvasHandle, ArchitectureCanvasProps>(({ 
  aiNodes, 
  aiEdges, 
  isThinking, 
  thoughts,
  context = "",
  audience = [],
  onApplyRefinement,
  onRefine,
  refinementPlaceholder = "Refine diagram..."
}, ref) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [showMermaid, setShowMermaid] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Refinement Input State
  const [refineInput, setRefineInput] = useState("");

  // Zoom & Pan State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [startPan, setStartPan] = useState({ x: 0, y: 0 });
  const dragStartRef = useRef({ x: 0, y: 0 }); // Track start pos to distinguish click vs drag

  // Refinement State
  const [showInsights, setShowInsights] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [suggestions, setSuggestions] = useState<RefinementSuggestion[]>([]);

  // Hover & Selection State
  const [hoveredNode, setHoveredNode] = useState<Node | null>(null);
  const [selectedNode, setSelectedNode] = useState<Node | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  // Expose export function to parent
  useImperativeHandle(ref, () => ({
    exportImage: (format: 'png' | 'svg') => handleExport(format)
  }));

  const getMermaidCode = () => {
    if (!aiNodes.length) return "graph LR\n  NoData[No Design Generated]";

    // Detect if this is an ER Diagram based on node types
    const isERD = aiNodes.some(n => n.type === 'table');

    if (isERD) {
       let code = "erDiagram\n";
       aiNodes.forEach(node => {
          // Extract columns from description if formatted as such
          // Assumes description might have "PK: ID (int)\nCol2 (string)" format
          const cleanName = node.label.replace(/\s+/g, '_');
          code += `  ${cleanName} {\n`;

          if (node.description) {
              const lines = node.description.split('\n').slice(0, 10); // Limit lines
              lines.forEach(line => {
                  // Simple cleanup to make it look like attribute
                  let attr = line.replace(/[:()]/g, ' ').trim();
                  if(attr.length > 0) code += `    string ${attr.replace(/\s+/g, '_')}\n`;
              });
          }
          code += "  }\n";
       });

       aiEdges.forEach(edge => {
           // Try to find node names
           const fromNode = aiNodes.find(n => n.id === edge.from);
           const toNode = aiNodes.find(n => n.id === edge.to);
           if (fromNode && toNode) {
               const fromName = fromNode.label.replace(/\s+/g, '_');
               const toName = toNode.label.replace(/\s+/g, '_');
               // Default to 1 to many if not specified
               const relType = edge.label.includes('1:1') ? '||--||' : '||--|{';
               const label = edge.label.replace(/[:]/g, '');
               code += `  ${fromName} ${relType} ${toName} : "${label}"\n`;
           }
       });
       return code;
    } 

    // Default Flowchart
    let code = "graph LR\n";
    code += "  classDef source fill:#eff6ff,stroke:#3b82f6,stroke-width:2px,color:#1e40af;\n";
    code += "  classDef stage fill:#f1f5f9,stroke:#64748b,stroke-width:2px,color:#334155;\n";
    code += "  classDef process fill:#fff7ed,stroke:#f97316,stroke-width:2px,color:#9a3412;\n";
    code += "  classDef target fill:#ecfdf5,stroke:#10b981,stroke-width:2px,color:#065f46;\n\n";

    aiNodes.forEach(node => {
      const label = node.label.replace(/"/g, "'");
      code += `  ${node.id}["${label}"]:::${node.type}\n`;
    });
    code += "\n";
    aiEdges.forEach(edge => {
      const label = edge.label ? `|"${edge.label}"|` : "";
      code += `  ${edge.from} -->${label} ${edge.to}\n`;
    });
    return code;
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(getMermaidCode());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleExport = (format: 'svg' | 'png') => {
    if (!svgRef.current) return;
    const svgEl = svgRef.current;

    // Serialize current state
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svgEl);
    if(!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)){
        source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    source = '<?xml version="1.0" standalone="no"?>\r\n' + source;
    const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);

    if (format === 'svg') {
        const link = document.createElement("a");
        link.href = url;
        link.download = `solution-design-${Date.now()}.svg`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        const img = new Image();
        img.src = url;
        img.onload = () => {
            const canvas = document.createElement("canvas");
            // Use dynamic size based on SVG viewBox or current client size
            const rect = svgEl.getBoundingClientRect();
            canvas.width = rect.width * 2; // 2x for better quality
            canvas.height = rect.height * 2;
            const ctx = canvas.getContext("2d");
            if (ctx) {
                ctx.fillStyle = "#ffffff";
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                const link = document.createElement("a");
                link.href = canvas.toDataURL("image/png");
                link.download = `solution-design-${Date.now()}.png`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        };
    }
    setShowExportMenu(false);
  };

  const handleFetchRefinements = async () => {
    if (!context || !aiNodes.length) return;
    setIsRefining(true);
    setShowInsights(true);
    setSuggestions([]);
    try {
      const currentDesign = { nodes: aiNodes, edges: aiEdges };
      const newSuggestions = await generateDesignRefinements(currentDesign, context, audience);
      setSuggestions(newSuggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefining(false);
    }
  };

  const applySuggestion = (suggestion: RefinementSuggestion) => {
    if (onApplyRefinement) {
      onApplyRefinement(suggestion.suggestedDesign);
      setSuggestions(prev => prev.filter(s => s.id !== suggestion.id)); 
    }
  };

  const submitRefinement = () => {
      if (onRefine && refineInput.trim()) {
          onRefine(refineInput);
          setRefineInput("");
      }
  };

  // --- Zoom & Pan Handlers ---
  const handleWheel = (e: React.WheelEvent) => {
    // Zoom towards mouse cursor
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    let delta = -e.deltaY;
    const wheelSensitivity = 0.1; 
    const step = delta > 0 ? wheelSensitivity : -wheelSensitivity;
    const newZoom = Math.max(0.2, Math.min(5, zoom + step));

    const worldX = (mouseX - pan.x) / zoom;
    const worldY = (mouseY - pan.y) / zoom;

    const newPanX = mouseX - (worldX * newZoom);
    const newPanY = mouseY - (worldY * newZoom);

    setZoom(newZoom);
    setPan({ x: newPanX, y: newPanY });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Only drag if clicking background (not buttons or inputs)
    if ((e.target as HTMLElement).tagName !== 'BUTTON' && (e.target as HTMLElement).tagName !== 'INPUT' && (e.target as HTMLElement).tagName !== 'TEXTAREA') {
      setIsDragging(true);
      setStartPan({ x: e.clientX - pan.x, y: e.clientY - pan.y });
      dragStartRef.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging) {
      setPan({ x: e.clientX - startPan.x, y: e.clientY - startPan.y });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      // If mouse hasn't moved much, treat as click to deselect
      const dist = Math.sqrt(Math.pow(e.clientX - dragStartRef.current.x, 2) + Math.pow(e.clientY - dragStartRef.current.y, 2));
      if (dist < 5) {
          // Deselect only if clicking the background directly (handled via bubbling if not stopped by children)
          if ((e.target as HTMLElement).tagName !== 'BUTTON' && (e.target as HTMLElement).tagName !== 'INPUT') {
             setSelectedNode(null);
          }
      }
  };

  const handleNodeClick = (node: Node, e: React.MouseEvent) => {
      e.stopPropagation();
      const dist = Math.sqrt(Math.pow(e.clientX - dragStartRef.current.x, 2) + Math.pow(e.clientY - dragStartRef.current.y, 2));
      if (dist < 5) {
          setSelectedNode(node);
          setHoveredNode(null); // Clear tooltip
      }
  };

  const resetView = () => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  };

  return (
    <div className="flex flex-col h-full relative group" ref={containerRef}>
      <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center z-20 shadow-sm">
        <div>
          <h3 className="font-bold text-slate-800 flex items-center gap-2">
            High Level Design (HLD)
            <span className="text-[10px] font-normal text-slate-400 bg-white px-2 py-0.5 rounded border border-slate-200 shadow-sm">
                {(zoom * 100).toFixed(0)}%
            </span>
          </h3>
          <p className="text-xs text-slate-500 hidden sm:block">
            {isThinking ? "AI is analyzing requirements..." : "Scroll to Zoom • Drag to Pan • Click Node for Details"}
          </p>
        </div>

        <div className="flex items-center gap-2 relative">
           <button onClick={handleFetchRefinements} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 border border-indigo-100 px-3 py-1.5 rounded hover:bg-indigo-100 transition-colors mr-2">
             <Sparkles size={14} className={isRefining ? 'animate-spin' : ''} />
             <span className="hidden sm:inline">AI Insights</span>
           </button>

          {/* Local Export Menu */}
          <div className="relative">
             <button onClick={() => setShowExportMenu(!showExportMenu)} className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-white border border-slate-300 px-3 py-1.5 rounded hover:bg-slate-50 transition-colors">
                <Share2 size={14} /> <span className="hidden sm:inline">Export</span>
             </button>
             {showExportMenu && (
                <div className="absolute right-0 top-full mt-1 w-32 bg-white rounded-lg shadow-xl border border-slate-200 py-1 z-30">
                   <button onClick={() => handleExport('png')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><ImageIcon size={14} /> PNG Image</button>
                   <button onClick={() => handleExport('svg')} className="w-full text-left px-4 py-2 text-xs hover:bg-slate-50 flex items-center gap-2"><FileCode size={14} /> SVG Vector</button>
                </div>
             )}
          </div>
          <button onClick={() => setShowMermaid(true)} className="flex items-center gap-2 text-xs font-bold text-white bg-blue-600 px-3 py-1.5 rounded hover:bg-blue-700 transition-colors">
            <Code size={14} /> <span className="hidden sm:inline">Mermaid</span>
          </button>
        </div>
      </div>

      <div 
        className={`flex-1 bg-white relative overflow-hidden flex items-center justify-center bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px] ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onClick={handleBackgroundClick}
      >

        {/* Zoom Controls */}
        <div className="absolute bottom-4 left-4 flex flex-col gap-2 z-30">
          <button onClick={() => setZoom(z => Math.min(5, z + 0.2))} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50 text-slate-600"><ZoomIn size={16} /></button>
          <button onClick={() => setZoom(z => Math.max(0.2, z - 0.2))} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50 text-slate-600"><ZoomOut size={16} /></button>
          <button onClick={resetView} className="p-2 bg-white border border-slate-200 rounded shadow hover:bg-slate-50 text-slate-600" title="Reset View"><Maximize size={16} /></button>
        </div>

        {/* UNIFIED GRAPHICS-FRIENDLY COMMAND BAR */}
        {onRefine && !isThinking && aiNodes.length > 0 && (
            <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-lg px-4 z-40">
                <div className="bg-white/90 backdrop-blur-md shadow-2xl rounded-2xl border border-indigo-100 p-2 flex items-center gap-2 animate-fade-in-up ring-1 ring-indigo-200/50">
                    <div className="p-2 bg-indigo-50 rounded-xl text-indigo-500">
                        <MessageSquare size={18} />
                    </div>
                    <input 
                        type="text" 
                        placeholder={refinementPlaceholder}
                        className="flex-1 bg-transparent outline-none text-sm py-2 px-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                        value={refineInput} 
                        onChange={(e) => setRefineInput(e.target.value)} 
                        onKeyDown={(e) => e.key === 'Enter' && submitRefinement()} 
                    />
                    <button 
                        onClick={submitRefinement} 
                        className="bg-indigo-600 hover:bg-indigo-700 text-white p-2.5 rounded-xl transition-all shadow-md shadow-indigo-200 hover:scale-105 active:scale-95"
                    >
                        <Send size={16} />
                    </button>
                </div>
            </div>
        )}

        {/* Gemini Insights Floating Panel */}
        {showInsights && (
           <div className="absolute top-4 left-4 z-20 w-72 bg-white/95 backdrop-blur-md rounded-xl shadow-xl border border-indigo-100 overflow-hidden flex flex-col max-h-[80%] animate-fade-in-up" onMouseDown={(e) => e.stopPropagation()}>
              <div className="bg-gradient-to-r from-indigo-500 to-purple-600 p-3 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2"><BrainCircuit size={16} /><span className="font-bold text-sm">Design Analysis</span></div>
                 <button onClick={() => setShowInsights(false)} className="hover:bg-white/20 rounded p-1"><X size={14} /></button>
              </div>
              <div className="p-4 overflow-y-auto flex-1">
                 {isRefining ? (
                    <div className="flex flex-col items-center justify-center py-8 text-center"><Loader size={24} className="text-indigo-500 animate-spin mb-2" /><p className="text-xs text-slate-500 font-medium">Comparing with learned patterns...</p></div>
                 ) : suggestions.length > 0 ? (
                    <div className="space-y-3">
                       {suggestions.map((sug) => (
                          <div key={sug.id} className="bg-indigo-50 border border-indigo-100 rounded-lg p-3">
                             <div className="flex justify-between items-start mb-1"><h5 className="font-bold text-slate-800 text-xs">{sug.title}</h5><span className="text-[9px] uppercase font-bold text-indigo-600 bg-white px-1.5 py-0.5 rounded border border-indigo-100">{sug.impact}</span></div>
                             <p className="text-[10px] text-slate-600 mb-2 leading-relaxed">{sug.description}</p>
                             <button onClick={() => applySuggestion(sug)} className="w-full bg-white text-indigo-600 text-xs font-bold py-1.5 rounded border border-indigo-200 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1"><Zap size={10} /> Apply Optimization</button>
                          </div>
                       ))}
                    </div>
                 ) : (
                    <div className="text-center py-4 text-slate-400 text-xs"><CheckCircle size={24} className="mx-auto mb-2 text-emerald-400" /><p>No major refinements found.</p></div>
                 )}
              </div>
           </div>
        )}

        {/* NODE DETAILS PANEL (Interactive Selection) */}
        {selectedNode && (
            <div className="absolute top-4 right-4 z-50 w-80 bg-white/95 backdrop-blur-md rounded-xl shadow-2xl border border-slate-200 animate-fade-in-up flex flex-col overflow-hidden ring-1 ring-slate-900/5" onMouseDown={(e) => e.stopPropagation()}>
                {/* Header */}
                <div className="bg-slate-50/80 p-4 border-b border-slate-200 flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        {selectedNode.type === 'source' && <Database size={16} className="text-blue-600" />}
                        {selectedNode.type === 'stage' && <Server size={16} className="text-slate-600" />}
                        {selectedNode.type === 'process' && <Settings size={16} className="text-orange-600" />}
                        {selectedNode.type === 'target' && <CloudLightning size={16} className="text-emerald-600" />}
                        {selectedNode.type === 'table' && <Table size={16} className="text-purple-600" />}
                        <h3 className="font-bold text-slate-800 text-sm truncate max-w-[180px]">{selectedNode.label}</h3>
                    </div>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setSelectedNode(null); }} 
                        className="text-slate-400 hover:text-slate-700 hover:bg-slate-200 rounded p-1 transition-colors"
                    >
                        <X size={16}/>
                    </button>
                </div>

                {/* Content */}
                <div className="p-5 space-y-5 overflow-y-auto max-h-[60vh]">
                    <div>
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Component Type</label>
                        <span className={`inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold capitalize border ${
                            selectedNode.type === 'source' ? 'bg-blue-50 text-blue-700 border-blue-100' : 
                            selectedNode.type === 'process' ? 'bg-orange-50 text-orange-700 border-orange-100' : 
                            selectedNode.type === 'target' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 
                            selectedNode.type === 'table' ? 'bg-purple-50 text-purple-700 border-purple-100' :
                            'bg-slate-100 text-slate-700 border-slate-200'
                        }`}>
                            {selectedNode.type}
                        </span>
                    </div>

                    <div>
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Description</label>
                        <div className="text-sm text-slate-600 leading-relaxed bg-slate-50 p-3 rounded-lg border border-slate-100">
                            {selectedNode.description ? selectedNode.description.split('\n').map((line, i) => (
                                <p key={i} className="mb-1 last:mb-0">{line}</p>
                            )) : <span className="text-slate-400 italic">No description provided by AI.</span>}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-2">
                        <div className="bg-slate-50 p-2 rounded border border-slate-100 text-center">
                            <span className="block text-[10px] text-slate-400 uppercase">Incoming</span>
                            <span className="font-bold text-slate-700">{aiEdges.filter(e => e.to === selectedNode.id).length}</span>
                        </div>
                        <div className="bg-slate-50 p-2 rounded border border-slate-100 text-center">
                            <span className="block text-[10px] text-slate-400 uppercase">Outgoing</span>
                            <span className="font-bold text-slate-700">{aiEdges.filter(e => e.from === selectedNode.id).length}</span>
                        </div>
                    </div>

                    <div className="pt-4 border-t border-slate-100 flex justify-between items-center text-[10px] text-slate-400 font-mono">
                        <span>ID: {selectedNode.id}</span>
                        <span>{Math.round(selectedNode.x)}, {Math.round(selectedNode.y)}</span>
                    </div>
                </div>
            </div>
        )}

        {/* Fixed Hover Tooltip - Robust Positioning (Only if not selected) */}
        {hoveredNode && !isDragging && !selectedNode && (
          <div 
            className="fixed z-[100] bg-slate-900/95 backdrop-blur-md text-white p-4 rounded-xl shadow-2xl max-w-xs pointer-events-none animate-fade-in border border-slate-700/50"
            style={{ 
              left: `${tooltipPos.x}px`, 
              top: `${tooltipPos.y - 16}px`,
              transform: 'translate(-50%, -100%)'
            }}
          >
             <div className="font-bold mb-2 flex items-center gap-2 border-b border-slate-700/50 pb-2 text-sm text-indigo-300">
               <Info size={14} />
               {hoveredNode.label}
             </div>
             <p className="text-slate-300 text-xs leading-relaxed font-medium whitespace-pre-line">
               {hoveredNode.description || "Click for details."}
             </p>
             {/* Tooltip Arrow */}
             <div className="absolute left-1/2 bottom-0 transform -translate-x-1/2 translate-y-full w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent border-t-[8px] border-t-slate-900/95"></div>
          </div>
        )}

        {/* Thinking Overlay */}
        {isThinking && (
          <div className="absolute inset-0 bg-white/95 z-10 flex flex-col items-center justify-center p-8 backdrop-blur-sm transition-opacity duration-300">
             <div className="w-full max-w-lg">
                <div className="flex items-center gap-3 mb-6">
                   <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center animate-pulse"><BrainCircuit className="text-white" size={24} /></div>
                   <div><h4 className="font-bold text-slate-800 text-lg">AI Thinking...</h4><p className="text-xs text-slate-500">Model: gemini-3-pro-preview</p></div>
                </div>
                <div className="space-y-3 font-mono text-xs max-h-60 overflow-y-auto">
                   {thoughts.map((thought, i) => (
                      <div key={i} className="flex items-center gap-3 animate-fade-in-up" style={{animationDelay: `${i * 0.3}s`}}><CheckCircle size={14} className="text-emerald-500 flex-shrink-0" /><span className="text-slate-600 bg-slate-100 px-3 py-2 rounded-lg w-full border border-slate-200 shadow-sm">{thought}</span></div>
                   ))}
                </div>
             </div>
          </div>
        )}

        <svg 
            ref={svgRef} 
            width="100%" 
            height="100%" 
            className="w-full h-full select-none"
        >
           <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
            </marker>
          </defs>

          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`} style={{ transition: isDragging ? 'none' : 'transform 0.1s ease-out' }}>

            {aiEdges && aiEdges.map((edge, i) => {
              const source = aiNodes.find(n => n.id === edge.from);
              const target = aiNodes.find(n => n.id === edge.to);
              if (!source || !target) return null;
              const sourceX = source.x + 160; 
              const sourceY = source.y + 40;  
              const targetX = target.x;
              const targetY = target.y + 40;
              const controlPointOffset = 60;
              return (
                <g key={i} className="animate-fade-in" style={{animationDelay: '0.5s'}}>
                  <path d={`M ${sourceX} ${sourceY} C ${sourceX + controlPointOffset} ${sourceY}, ${targetX - controlPointOffset} ${targetY}, ${targetX} ${targetY}`} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />
                  <rect x={(sourceX + targetX)/2 - 40} y={(sourceY + targetY)/2 - 10} width="80" height="20" rx="4" fill="white" stroke="#e2e8f0" strokeWidth="1" />
                  <text x={(sourceX + targetX)/2} y={(sourceY + targetY)/2 + 4} textAnchor="middle" fontSize="10" fill="#64748b" fontWeight="600" style={{ fontFamily: 'Inter, sans-serif' }}>{edge.label}</text>
                </g>
              );
            })}

            {aiNodes && aiNodes.map((node, i) => {
              const isSelected = selectedNode?.id === node.id;
              return (
                <foreignObject 
                  x={node.x} y={node.y} width="160" height="80" key={node.id} 
                  className="animate-fade-in-up overflow-visible" 
                  style={{animationDelay: `${i * 0.1}s`}}
                >
                  <div 
                      className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white relative group
                      ${isSelected ? 'ring-4 ring-indigo-200 border-indigo-600 scale-105 z-10 shadow-xl' : ''}
                      ${!isSelected && node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                        !isSelected && node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                        !isSelected && node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                        !isSelected && node.type === 'table' ? 'bg-purple-50 border-purple-500' :
                        !isSelected ? 'bg-white border-slate-300' : ''}`}
                      onMouseEnter={(e) => {
                        if(!isDragging) {
                            const rect = e.currentTarget.getBoundingClientRect();
                            setTooltipPos({ x: rect.left + rect.width/2, y: rect.top });
                            setHoveredNode(node);
                        }
                      }}
                      onMouseLeave={() => setHoveredNode(null)}
                      onClick={(e) => handleNodeClick(node, e)}
                  >
                      <div className="mb-1">
                        {node.type === 'source' && <Database size={20} className={isSelected ? 'text-indigo-600' : 'text-blue-600'} />}
                        {node.type === 'stage' && <Server size={20} className={isSelected ? 'text-indigo-600' : 'text-slate-600'} />}
                        {node.type === 'process' && <Settings size={20} className={`text-orange-600 ${isSelected ? 'text-indigo-600' : 'animate-spin-slow'}`} />}
                        {node.type === 'target' && <CloudLightning size={20} className={isSelected ? 'text-indigo-600' : 'text-emerald-600'} />}
                        {node.type === 'table' && <Table size={20} className={isSelected ? 'text-indigo-600' : 'text-purple-600'} />}
                      </div>
                      <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">{node.label}</span>

                      {/* Interaction hint */}
                      <div className={`absolute -top-1 -right-1 transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                         <div className={`text-white rounded-full p-1 shadow-sm flex items-center justify-center w-5 h-5 ${isSelected ? 'bg-indigo-600' : 'bg-slate-400'}`}>
                             {isSelected ? <Check size={10} /> : <Info size={10} />}
                         </div>
                      </div>
                  </div>
                </foreignObject>
              );
            })}
          </g>
        </svg>
      </div>

      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
