                            selectedNode.type === 'process' ? 'bg-orange-50 text-orange-700 border-orange-100' : 
                            selectedNode.type === 'target' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 
                            selectedNode.type === 'table' ? 'bg-purple-50 text-purple-700 border-purple-100' :
