        {/* Fixed Hover Tooltip - Robust Positioning (Only if not selected) */}
        {hoveredNode && !isDragging && !selectedNode && (
          <div 
            className="fixed z-[100] bg-slate-900/95 backdrop-blur-md text-white p-4 rounded-xl shadow-2xl max-w-xs pointer-events-none animate-fade-in border border-slate-700/50"
            style={{ 
