                  <div 
                      className={`w-[158px] h-[78px] rounded-xl border-2 flex flex-col items-center justify-center shadow-sm transition-all hover:scale-105 cursor-pointer select-none bg-white relative group
                      ${isSelected ? 'ring-4 ring-indigo-200 border-indigo-600 scale-105 z-10 shadow-xl' : ''}
                      ${!isSelected && node.type === 'source' ? 'bg-blue-50 border-blue-500' : 
                        !isSelected && node.type === 'process' ? 'bg-orange-50 border-orange-500' : 
                        !isSelected && node.type === 'target' ? 'bg-emerald-50 border-emerald-500' : 
                        !isSelected && node.type === 'table' ? 'bg-purple-50 border-purple-500' :
                        !isSelected ? 'bg-white border-slate-300' : ''}`}
                      onMouseEnter={(e) => {
                        if(!isDragging) {
                            const rect = e.currentTarget.getBoundingClientRect();
                            setTooltipPos({ x: rect.left + rect.width/2, y: rect.top });
                            setHoveredNode(node);
                        }
                      }}
                      onMouseLeave={() => setHoveredNode(null)}
                      onClick={(e) => handleNodeClick(node, e)}
                  >
                      <div className="mb-1">
                        {node.type === 'source' && <Database size={20} className={isSelected ? 'text-indigo-600' : 'text-blue-600'} />}
                        {node.type === 'stage' && <Server size={20} className={isSelected ? 'text-indigo-600' : 'text-slate-600'} />}
                        {node.type === 'process' && <Settings size={20} className={`text-orange-600 ${isSelected ? 'text-indigo-600' : 'animate-spin-slow'}`} />}
                        {node.type === 'target' && <CloudLightning size={20} className={isSelected ? 'text-indigo-600' : 'text-emerald-600'} />}
                        {node.type === 'table' && <Table size={20} className={isSelected ? 'text-indigo-600' : 'text-purple-600'} />}
                      </div>
                      <span className="text-[11px] font-bold text-center px-2 leading-tight text-slate-800 line-clamp-2 w-full break-words">{node.label}</span>

                      {/* Interaction hint */}
                      <div className={`absolute -top-1 -right-1 transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                         <div className={`text-white rounded-full p-1 shadow-sm flex items-center justify-center w-5 h-5 ${isSelected ? 'bg-indigo-600' : 'bg-slate-400'}`}>
                             {isSelected ? <Check size={10} /> : <Info size={10} />}
                         </div>
                      </div>
                  </div>
                </foreignObject>
              );
            })}
          </g>
        </svg>
      </div>

      {showMermaid && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50"><h3 className="font-bold text-slate-800 flex items-center gap-2"><Code size={18} className="text-blue-600" /> Mermaid.js Diagram Code</h3><button onClick={() => setShowMermaid(false)} className="text-slate-400 hover:text-slate-700 transition-colors"><X size={20} /></button></div>
            <div className="flex-1 p-0 overflow-hidden relative group/code"><pre className="w-full h-full p-6 bg-slate-900 text-blue-100 font-mono text-xs overflow-auto">{getMermaidCode()}</pre><button onClick={copyToClipboard} className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg backdrop-blur-md transition-all border border-white/10">{copied ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} />}</button></div>
            <div className="p-4 border-t border-slate-200 flex justify-end gap-2 bg-slate-50"><button onClick={() => setShowMermaid(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition-colors">Close</button><button onClick={copyToClipboard} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors flex items-center gap-2">{copied ? 'Copied!' : 'Copy Code'}</button></div>
          </div>
        </div>
      )}
    </div>
  );
});

