export const generateIntelligentQuestionnaire = async (
    context: string,
    solutionType: string,
    audience: string[] = []
): Promise<Question[]> => {
    try {
        const prompt = `
            Act as a Project Manager. Generate a scoping questionnaire for a ${solutionType} project.
            Context: ${context}
            Audience: ${audience.join(', ')}

            CRITICAL INSTRUCTION:
            - Scan the context for "GDPR", "Privacy", "PII", or "Compliance".
            - IF FOUND (especially for MDM/Governance), YOU MUST add specific questions about:
              1. Consent Management (How is consent captured/updated?).
              2. Data Classification (How are sensitive fields identified/tagged?).

            Generate 5-7 crucial questions that clear up ambiguity in the requirements.
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            id: { type: Type.STRING },
                            category: { type: Type.STRING },
                            question: { type: Type.STRING },
                            answer: { type: Type.STRING },
                            isCustom: { type: Type.BOOLEAN }
                        },
                        required: ["id", "category", "question", "answer"]
                    }
                }
            }
        }));

        return safeJsonParse(response.text, []);
    } catch (e) {
        console.error(e);
        return [];
    }
};

