  // Dynamic Options
  const [availableProducts] = useState<string[]>(Object.keys(PRODUCT_CATALOG).sort());
  const [availableDeployments, setAvailableDeployments] = useState<string[]>(['Cloud', 'On-Premise']);
  const [availableServices, setAvailableServices] = useState<string[]>([]);

  // Track dirty status - Check against initial empty state
  useEffect(() => {
      const isDirty = formData.clientName !== '' || formData.requirementsPrompt !== '' || formData.rfpFiles.length > 0;
      if (onDirtyChange) onDirtyChange(isDirty);
  }, [formData.clientName, formData.requirementsPrompt, formData.rfpFiles, onDirtyChange]);

  // Apply User Profile Defaults
  useEffect(() => {
    if (userProfile && userProfile.preferences) {
