  const [historyItems, setHistoryItems] = useState<any[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('DataDictionary'));
  }, [dataDictionary]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
      const totalColumns = dataDictionary.length;
      const uniqueTables = Array.from(new Set(dataDictionary.map(i => i.tableName)));
      const totalTables = uniqueTables.length;

      // Data Type Distribution
      const typeCounts: Record<string, number> = {};
      dataDictionary.forEach(item => {
          // Simplify types (e.g. VARCHAR(50) -> VARCHAR)
          const simpleType = item.dataType?.split('(')[0]?.toUpperCase().trim() || 'UNKNOWN';
          typeCounts[simpleType] = (typeCounts[simpleType] || 0) + 1;
      });
      const typeData = Object.entries(typeCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 7); // Top 7 types

      // Columns per Table (Top 10)
      const colsPerTable: Record<string, number> = {};
      dataDictionary.forEach(item => {
          colsPerTable[item.tableName] = (colsPerTable[item.tableName] || 0) + 1;
      });
      const tableData = Object.entries(colsPerTable)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 10); 

      // Constraint Stats
      const pkCount = dataDictionary.filter(i => i.constraint && (i.constraint.toUpperCase().includes('PK') || i.constraint.toUpperCase().includes('PRIMARY'))).length;
      const fkCount = dataDictionary.filter(i => i.constraint && (i.constraint.toUpperCase().includes('FK') || i.constraint.toUpperCase().includes('FOREIGN'))).length;

      // Completeness (Description populated)
      const describedCount = dataDictionary.filter(i => i.description && i.description.length > 5).length;
      const completenessPct = totalColumns > 0 ? Math.round((describedCount / totalColumns) * 100) : 0;

      return { totalColumns, totalTables, typeData, tableData, uniqueTables, pkCount, fkCount, completenessPct };
  }, [dataDictionary]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);

      // Handle Excel/CSV Parsing Client-Side
      if (file.name.match(/\.(xlsx|xls|csv)$/i)) {
          if (typeof window.XLSX === 'undefined') {
              setInputText(prev => prev + `\n[Error: Excel library not loaded. Treating as binary.]`);
              return;
          }

          const reader = new FileReader();
          reader.onload = (evt) => {
              try {
                  const bstr = evt.target?.result;
                  const wb = window.XLSX.read(bstr, { type: 'binary' });

                  let extractedText = `\n[Context from ${file.name}]:\n`;

                  // Iterate through sheets
                  wb.SheetNames.forEach((sheetName: string) => {
                      const ws = wb.Sheets[sheetName];
                      // Get raw data (arrays of arrays)
                      const data = window.XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

                      if (data && data.length > 0) {
                          const headers = data[0] as string[];
                          extractedText += `\n--- TABLE: ${sheetName} ---\n`;
                          extractedText += `Columns: ${headers.join(', ')}\n`;

                          // Add sample data (first 3 rows) to help AI infer types
                          if (data.length > 1) {
                              extractedText += `Sample Data (First 3 rows):\n`;
                              data.slice(1, 4).forEach((row: any[]) => {
                                  extractedText += JSON.stringify(row) + "\n";
                              });
                          }
                      }
                  });

                  setInputText(prev => prev + extractedText);
              } catch (err) {
                  console.error("Excel parse error", err);
                  setInputText(prev => prev + `\n[Error parsing Excel file. Please use text input.]`);
              }
          };
          reader.readAsBinaryString(file);
      } else {
          // Normal text file handling (SQL, TXT, JSON)
          const reader = new FileReader();
          reader.onload = (evt) => {
              if (evt.target?.result) {
                  setInputText(prev => prev + `\n[Context from ${file.name}]:\n${evt.target.result}`);
              }
          };
          reader.readAsText(file);
      }
    }
  };

  const handleGenerate = async () => {
    if (!project || !module || !inputText.trim()) {
      setError("Please fill in Project, Module, and provide Input Data.");
      return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const result = await generateDataDictionary(inputText, project, module);
      if (result && result.length > 0) {
          setDataDictionary(result);
          saveHistory('DataDictionary', `${project} - ${module}`, {
              project,
              module,
              dictionary: result,
              inputText
          });
          setViewMode('dashboard');
          setActiveTab('summary');
      } else {
          setError("No data dictionary items could be generated. Please check your input format.");
      }
    } catch (e) {
      setError("Failed to generate dictionary. Try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const loadHistoryItem = (item: any) => {
      const data = item.data;
      setProject(data.project);
      setModule(data.module);
      setDataDictionary(data.dictionary);
      if(data.inputText) setInputText(data.inputText);
      setViewMode('dashboard');
      setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      deleteHistory(id);
      setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const handleExportExcel = () => {
    if (typeof window.XLSX === 'undefined') {
        alert("Excel library not loaded.");
        return;
    }

    const wb = window.XLSX.utils.book_new();

    // Sheet 1: Executive Summary (Stats)
    const summaryData = [
        ["Data Dictionary Summary"],
        ["Project", project],
        ["Module", module],
        ["Generated Date", new Date().toLocaleDateString()],
        [""],
        ["Metric", "Value"],
        ["Total Tables", stats.totalTables],
        ["Total Columns", stats.totalColumns],
        ["Primary Keys", stats.pkCount],
        ["Foreign Keys", stats.fkCount],
        ["Description Completeness", `${stats.completenessPct}%`]
    ];
    const wsSummary = window.XLSX.utils.aoa_to_sheet(summaryData);
    window.XLSX.utils.book_append_sheet(wb, wsSummary, "Summary");

    // Sheet 2: Data Dictionary (Main Data)
    const dictData = dataDictionary.map(item => ({
        "Table Name": item.tableName,
        "Column Name": item.columnName,
        "Data Type": item.dataType,
        "Length": item.length || '',
        "Constraint": item.constraint || '',
        "Description": item.description,
        "Business Rule": item.businessRule || ''
    }));
    const wsDict = window.XLSX.utils.json_to_sheet(dictData);
    // Auto-width
    const wscols = [{wch: 25}, {wch: 25}, {wch: 15}, {wch: 10}, {wch: 15}, {wch: 60}, {wch: 40}];
    wsDict['!cols'] = wscols;
    window.XLSX.utils.book_append_sheet(wb, wsDict, "Dictionary");

    // Sheet 3: Table List (Unique Tables)
    const tableListData = stats.uniqueTables.map(t => {
        const firstCol = dataDictionary.find(d => d.tableName === t);
        const colCount = dataDictionary.filter(d => d.tableName === t).length;
        // Try to find a table-level description if possible, otherwise infer
        const desc = firstCol?.description ? `Stores entity data for ${t}.` : ""; 
        return {
            "Table Name": t,
            "Column Count": colCount,
            "Description": desc
        };
    });
    const wsTables = window.XLSX.utils.json_to_sheet(tableListData);
    wsTables['!cols'] = [{wch: 30}, {wch: 15}, {wch: 50}];
    window.XLSX.utils.book_append_sheet(wb, wsTables, "Tables");

    window.XLSX.writeFile(wb, `${project}_${module}_DataDictionary.xlsx`);
  };

  const filteredDictionary = dataDictionary.filter(item => 
      item.tableName.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.columnName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // --- INPUT VIEW ---
  if (viewMode === 'input') {
      return (
        <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in items-center justify-center p-6">

            {/* History Dropdown */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Saved Dictionaries</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                        {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                        historyItems.map((h, i) => (
                            <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                                <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                                <span className="text-slate-400 text-[10px]">{h.date}</span>
                                <div 
                                    className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                    onClick={(e) => handleDeleteHistory(h.id, e)}
                                >
                                    <Trash2 size={14} />
                                </div>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            <div className="w-full max-w-4xl bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden flex flex-col md:flex-row h-[600px] relative">

                {/* Header Actions */}
                <div className="absolute top-4 right-4 z-20">
                    <button onClick={() => setShowHistory(!showHistory)} className="p-2 bg-white/20 hover:bg-white/30 text-slate-500 hover:text-slate-800 rounded-lg backdrop-blur-md transition-colors">
                        <History size={20} />
                    </button>
                </div>

                {/* Left Panel: Branding */}
                <div className="md:w-1/3 bg-slate-900 p-8 flex flex-col justify-between text-white relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-blue-500 rounded-full blur-[60px] opacity-30"></div>

                    <div className="relative z-10">
                        <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center mb-6 shadow-lg shadow-blue-900/50">
                            <FileSpreadsheet size={24} className="text-white"/>
                        </div>
                        <h2 className="text-2xl font-bold mb-2">Data Dictionary Generator</h2>
                        <p className="text-blue-200 text-sm leading-relaxed">
                            Transform raw DDL scripts, Excel datasets, or technical specs into a standardized data dictionary.
                        </p>
                    </div>

                    <div className="relative z-10 space-y-4 text-xs text-slate-400">
                        <div className="flex items-center gap-3">
                            <CheckCircle2 size={16} className="text-emerald-500"/>
                            <span>Metadata Extraction (DDL/XLSX)</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle2 size={16} className="text-emerald-500"/>
                            <span>Business Description Inference</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle2 size={16} className="text-emerald-500"/>
                            <span>Multi-Sheet Excel Export</span>
                        </div>
                    </div>
                </div>

                {/* Right Panel: Form */}
                <div className="md:w-2/3 p-8 md:p-10 flex flex-col overflow-y-auto">
                    <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <Settings size={20} className="text-slate-400"/> Project Configuration
                    </h3>

                    <div className="space-y-6 flex-1">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase">Project Name</label>
                                <input 
                                    className="w-full p-3 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all"
                                    placeholder="e.g. Finance Data Lake"
                                    value={project}
                                    onChange={(e) => setProject(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase">Sub-Module</label>
                                <input 
                                    className="w-full p-3 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all"
                                    placeholder="e.g. General Ledger"
                                    value={module}
                                    onChange={(e) => setModule(e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase">Input Source</label>
                            <div className="flex gap-2 p-1 bg-slate-100 rounded-xl w-fit mb-2">
                                <button onClick={() => setInputType('text')} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${inputType === 'text' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>Paste DDL / Text</button>
                                <button onClick={() => setInputType('file')} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${inputType === 'file' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>Upload File</button>
                            </div>

                            {inputType === 'text' ? (
                                <textarea 
                                    className="w-full h-48 p-4 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none text-xs font-mono leading-relaxed resize-none transition-all"
                                    placeholder="CREATE TABLE Customers ( ID INT PRIMARY KEY, Name VARCHAR(100)... );"
                                    value={inputText}
                                    onChange={(e) => setInputText(e.target.value)}
                                />
                            ) : (
                                <div className="border-2 border-dashed border-slate-300 rounded-xl h-48 flex flex-col items-center justify-center bg-slate-50 hover:bg-slate-100 transition-colors relative">
                                    <input 
                                        type="file" 
                                        className="absolute inset-0 opacity-0 cursor-pointer" 
                                        onChange={handleFileUpload} 
                                        accept=".sql,.txt,.json,.docx,.xlsx,.xls,.csv"
                                    />
                                    <UploadCloud size={32} className="text-slate-400 mb-2"/>
                                    <p className="text-sm font-bold text-slate-600">{uploadedFileName || "Click or Drag file here"}</p>
                                    <p className="text-xs text-slate-400 mt-1">SQL, TXT, JSON, XLSX, CSV</p>
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-100">
                        {error && <div className="mb-4 text-xs text-red-500 bg-red-50 p-2 rounded flex items-center gap-2"><AlertCircle size={14}/> {error}</div>}
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02]"
                        >
                            {isGenerating ? <Loader size={20} className="animate-spin"/> : <Sparkles size={20}/>}
                            Generate Data Dictionary
                        </button>
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">

        {/* Top Navigation Bar */}
        <div className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-4">
                <button onClick={() => setViewMode('input')} className="p-2 hover:bg-slate-100 rounded-lg text-slate-500 transition-colors">
                    <ArrowLeft size={20}/>
                </button>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                        {project} <span className="text-slate-300">/</span> {module}
                    </h2>
                    <p className="text-xs text-slate-500">Dictionary Dashboard</p>
                </div>
            </div>
            <div className="flex gap-3">
                <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-md transition-all hover:shadow-emerald-200">
                    <Download size={16} /> Export Excel
                </button>
                <button onClick={() => setViewMode('input')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-50 transition-all">
                    <RefreshCw size={16} /> New Analysis
                </button>
            </div>
        </div>

        {/* Tab Bar */}
        <div className="bg-white border-b border-slate-200 px-6">
            <div className="flex gap-6">
                <button onClick={() => setActiveTab('summary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'summary' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <PieChartIcon size={16}/> Summary
                </button>
                <button onClick={() => setActiveTab('dictionary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'dictionary' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <Grid size={16}/> Dictionary
                </button>
                <button onClick={() => setActiveTab('tables')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'tables' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <List size={16}/> Tables
                </button>
            </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 md:p-8">
            <div className="max-w-7xl mx-auto h-full">

                {/* --- TAB 1: SUMMARY DASHBOARD --- */}
                {activeTab === 'summary' && (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">

                        {/* Key Metrics */}
                        <div className="lg:col-span-2 grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Tables</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalTables}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Columns</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalColumns}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Completeness</div>
                                <div className="text-3xl font-bold text-emerald-600 flex items-center gap-1">
                                    {stats.completenessPct}<span className="text-lg">%</span>
                                </div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Key Constraints</div>
                                <div className="text-3xl font-bold text-indigo-600 flex items-center gap-1">
                                    {stats.pkCount + stats.fkCount} <Key size={16} className="text-indigo-400"/>
                                </div>
                            </div>
                        </div>

                        {/* Chart: Data Types */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <PieChartIcon size={18} className="text-blue-500"/> Data Type Distribution
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={stats.typeData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                        >
                                            {stats.typeData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Legend verticalAlign="bottom" height={36} iconType="circle"/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Chart: Table Complexity */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <LayoutDashboard size={18} className="text-emerald-500"/> Top Tables by Column Count
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats.tableData} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                        <RechartsTooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Bar dataKey="value" fill="#10B981" radius={[0, 4, 4, 0]} barSize={20} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- TAB 2: DATA DICTIONARY GRID --- */}
                {activeTab === 'dictionary' && (
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden animate-fade-in">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                            <div className="relative w-64">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                                <input 
                                    type="text" 
                                    placeholder="Filter columns..." 
                                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                            <div className="text-xs text-slate-400 font-medium">
                                Showing {filteredDictionary.length} items
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto">
                            <table className="w-full text-left text-sm border-collapse">
                                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm text-slate-500 text-xs uppercase font-bold tracking-wider">
                                    <tr>
                                        <th className="p-4 border-b border-r border-slate-200 w-48">Table Name</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-48">Column</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-32">Type</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-24">Length</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-32">Constraint</th>
                                        <th className="p-4 border-b border-slate-200">Description</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {filteredDictionary.map((row, i) => (
                                        <tr key={i} className="hover:bg-slate-50/80 transition-colors">
                                            <td className="p-4 border-r border-slate-100 font-medium text-slate-700">{row.tableName}</td>
                                            <td className="p-4 border-r border-slate-100 font-bold text-slate-800">{row.columnName}</td>
                                            <td className="p-4 border-r border-slate-100 text-blue-600 font-mono text-xs">{row.dataType}</td>
                                            <td className="p-4 border-r border-slate-100 text-slate-500 text-xs">{row.length || '-'}</td>
                                            <td className="p-4 border-r border-slate-100">
                                                {row.constraint && (
                                                    <span className={`inline-flex px-2 py-0.5 rounded text-[10px] font-bold border ${row.constraint.includes('PK') ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-slate-100 text-slate-600 border-slate-200'}`}>
                                                        {row.constraint}
                                                    </span>
                                                )}
                                            </td>
                                            <td className="p-4 text-slate-600 text-xs leading-relaxed">{row.description}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* --- TAB 3: TABLE LIST --- */}
                {activeTab === 'tables' && (
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 p-6">
                            {stats.uniqueTables.map((tableName, i) => {
                                const colCount = dataDictionary.filter(d => d.tableName === tableName).length;
                                const desc = dataDictionary.find(d => d.tableName === tableName)?.description || "Standard entity table.";
                                return (
                                    <div key={i} className="bg-slate-50 p-5 rounded-xl border border-slate-200 hover:border-blue-300 hover:shadow-md transition-all group">
                                        <div className="flex justify-between items-start mb-2">
                                            <div className="flex items-center gap-2">
                                                <div className="p-1.5 bg-white rounded-lg border border-slate-200 text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                                    <TableIcon size={16}/>
                                                </div>
                                                <h4 className="font-bold text-slate-800 text-sm">{tableName}</h4>
                                            </div>
                                            <span className="bg-white px-2 py-0.5 rounded text-[10px] font-bold text-slate-500 border border-slate-200">{colCount} Cols</span>
                                        </div>
                                        <p className="text-xs text-slate-500 line-clamp-2 leading-relaxed">
                                            Stores information regarding {tableName.toLowerCase().replace(/_/g, ' ')}. {desc}
                                        </p>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

            </div>
        </div>
    </div>
  );
};

