      {/* Progress Stepper */}
      <div className="flex gap-4 mb-8">
          <button onClick={() => setActiveTab('validation')} className={`flex-1 p-5 rounded-2xl border transition-all text-left relative overflow-hidden group ${activeTab === 'validation' ? 'bg-white border-emerald-500 shadow-md' : 'bg-slate-100 border-transparent opacity-60 hover:opacity-100'}`}>
              <div className="relative z-10">
                  <div className="flex justify-between items-center mb-1">
                      <span className="text-xs font-bold uppercase tracking-wider text-emerald-600">Step 01</span>
