          <button onClick={() => isValidationComplete && setActiveTab('cleanse')} disabled={!isValidationComplete} className={`flex-1 p-5 rounded-2xl border transition-all text-left relative overflow-hidden group ${activeTab === 'cleanse' ? 'bg-white border-blue-500 shadow-md' : 'bg-slate-100 border-transparent opacity-60'}`}>
              <div className="relative z-10">
                  <div className="flex justify-between items-center mb-1">
                      <span className="text-xs font-bold uppercase tracking-wider text-blue-600">Step 02</span>
