                          <p className="text-slate-500 text-center mb-8">Type requirements like "Email must be valid format" or "Order Date cannot be future".</p>
                          <div className="w-full relative">
                              <textarea 
                                value={cdeContext}
                                onChange={(e) => setCdeContext(e.target.value)}
