                                placeholder="Enter validation logic..."
                              />
                              <button 
                                onClick={handleGenerateValidation}
                                disabled={!cdeContext.trim() || isGenerating}
                                className="absolute bottom-4 right-4 bg-emerald-600 hover:bg-emerald-700 text-white p-2 rounded-lg transition-colors shadow-lg disabled:opacity-50"
                              >
                                {isGenerating ? <Loader size={20} className="animate-spin"/> : <ArrowRight size={20}/>}
                              </button>
                          </div>
                      </div>
                  ) : (
                      <div className="h-full flex flex-col">
                          <div className="flex justify-between items-center mb-6">
                              <h3 className="font-bold text-lg text-slate-800">Generated Rules ({validationRules.length})</h3>
                              <button onClick={() => setValidationRules([])} className="text-xs font-bold text-slate-500 hover:text-red-500">Reset</button>
                          </div>
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 overflow-y-auto pb-4">
                              {(Object.entries(groupedRules) as [string, DataQualityRule[]][]).map(([elem, rules]) => (
                                  <div key={elem} className="bg-slate-50 p-5 rounded-2xl border border-slate-200 hover:border-emerald-200 hover:shadow-md transition-all group">
                                      <div className="flex items-center gap-2 mb-3">
                                          <Database size={16} className="text-emerald-600"/>
