                                    <div className="mb-6">
                                        <h3 className="text-lg font-bold text-slate-800 mb-2">3. Reference Files</h3>
                                        <div className="flex gap-4 items-start">
                                            <label className="flex-1 flex flex-col items-center justify-center h-32 border-2 border-dashed border-slate-300 rounded-xl cursor-pointer hover:bg-slate-50 hover:border-pink-400 transition-all bg-white">
                                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
