                                ) : (
                                    <div className="p-4 text-xs text-slate-500 text-center">
                                        Use the main view to interact with diagrams.
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Main: Content Editor or Canvas */}
                        <div className="flex-1 overflow-y-auto bg-slate-50 p-8 relative">
                            {activeWorkspaceTab === 'doc' ? (
                                <div className="max-w-4xl mx-auto space-y-8 pb-20">
                                    {generatedSections.map((sec) => (
                                        <div key={sec.id} id={sec.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden group">
                                            <div className="bg-white px-8 py-6 border-b border-slate-100 flex justify-between items-center sticky top-0 z-10">
                                                <h4 className="font-bold text-slate-800 text-lg">{sec.title}</h4>
                                                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    {editingSectionId !== sec.id && (
                                                        <button onClick={() => startEditing(sec)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-blue-600 transition-colors" title="Edit Content">
                                                            <Pencil size={16} />
                                                        </button>
                                                    )}
                                                    <button onClick={() => handleRegenerateSection(sec.id)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-pink-600 transition-colors" title="Regenerate with AI">
                                                        <RefreshCw size={16} className={activeSectionId === sec.id ? 'animate-spin' : ''} />
                                                    </button>
                                                </div>
                                            </div>

                                            <div className="p-8 min-h-[200px]">
                                                {editingSectionId === sec.id ? (
                                                    <div className="animate-fade-in">
                                                        <textarea 
                                                            value={editContentBuffer}
                                                            onChange={(e) => setEditContentBuffer(e.target.value)}
                                                            className="w-full h-96 p-4 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-mono leading-relaxed bg-white text-slate-800 resize-y"
                                                        />
                                                        <div className="flex justify-end gap-2 mt-4">
                                                            <button onClick={() => setEditingSectionId(null)} className="px-4 py-2 text-sm rounded border border-slate-300 hover:bg-slate-50 text-slate-600 font-bold">Cancel</button>
                                                            <button onClick={saveEditing} className="px-4 py-2 text-sm rounded bg-indigo-600 hover:bg-indigo-700 text-white font-bold">Save Changes</button>
                                                        </div>
                                                    </div>
                                                ) : sec.status === 'pending' ? (
                                                    <div className="h-full flex flex-col items-center justify-center text-slate-300 py-12">
                                                        {activeSectionId === sec.id ? (
                                                            <>
                                                                <Loader size={32} className="animate-spin mb-3 text-pink-400"/>
                                                                <p className="text-sm font-medium">AI is writing content...</p>
                                                            </>
                                                        ) : (
                                                            <div className="flex flex-col items-center gap-2">
                                                                <div className="w-12 h-2 bg-slate-100 rounded-full"></div>
                                                                <div className="w-8 h-2 bg-slate-100 rounded-full"></div>
                                                                <p className="text-xs mt-2">Waiting in queue</p>
                                                            </div>
                                                        )}
                                                    </div>
                                                ) : (
                                                    <div className="prose prose-sm max-w-none text-slate-700 leading-relaxed" onDoubleClick={() => startEditing(sec)}>
                                                        {sec.content.split('\n').map((line, i) => (
                                                            <p key={i} className="mb-3">{line.replace(/^\*\*(.*?)\*\*$/, '$1')}</p> 
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                // Diagram View
                                <div className="h-full flex flex-col">
                                    <div className="mb-4 flex justify-center">
                                        <div className="bg-white p-1 rounded-lg shadow-sm border border-slate-200 inline-flex">
                                            <button onClick={() => setDiagramType('table')} className={`px-4 py-2 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'table' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <Table size={14} /> Architecture Flow
                                            </button>
                                            <button onClick={() => setDiagramType('process')} className={`px-4 py-2 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'process' ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <ArrowRightCircle size={14} /> Data Flow
                                            </button>
                                        </div>
                                    </div>
                                    <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative">
                                        {isDiagramGenerating ? (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/80 backdrop-blur-sm z-30">
                                                <Loader size={32} className="animate-spin text-pink-500 mb-2"/>
                                                <p className="text-sm text-slate-500">Generating diagram...</p>
                                            </div>
                                        ) : (
                                            <ArchitectureCanvas 
                                                aiNodes={diagramType === 'table' ? archFlowDesign.nodes : dataFlowDesign.nodes} 
                                                aiEdges={diagramType === 'table' ? archFlowDesign.edges : dataFlowDesign.edges} 
                                                isThinking={false} 
                                                thoughts={[]} 
                                                context={projectContext}
                                                onRefine={handleRefineDiagram}
                                                refinementPlaceholder={`Refine ${diagramType === 'table' ? 'Architecture' : 'Data'} Flow...`}
                                            />
                                        )}
                                        {(!isDiagramGenerating && (diagramType === 'table' ? archFlowDesign.nodes.length === 0 : dataFlowDesign.nodes.length === 0)) && (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400">
                                                <Network size={48} className="mb-4 opacity-20" />
                                                <p>No diagram generated yet.</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                )}

            </div>
        </div>
    );
};

export default DocumentGenerator;

import React, { useState, useEffect } from 'react';
import { 
  Presentation, 
  UploadCloud, 
  Loader, 
  Sparkles, 
  CheckCircle, 
  MonitorPlay, 
  Edit3, 
  Download, 
  Layout, 
  ArrowRight, 
  ArrowLeft,
  RefreshCw,
  FileText,
  Pencil,
  ChevronRight,
  Monitor,
  History,
  Trash2
} from 'lucide-react';
import { analyzePPTStructure, generateSlideContent, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import { CaseStoryTemplate, SlideContent } from '../types';

declare const PptxGenJS: any;

interface CaseStoryGeneratorProps {
  setHasUnsavedChanges: (val: boolean) => void;
}

const DEFAULT_PPT_TEMPLATES: CaseStoryTemplate[] = [
    {
        id: 'standard',
        name: 'Standard Case Study',
        description: 'Classic 4-slide structure: Challenge, Solution, Result.',
        slides: [
            { title: "Project Overview", description: "Client background and high-level summary." },
            { title: "Business Challenges", description: "Pain points, legacy issues, and drivers." },
            { title: "Solution Architecture", description: "Tech stack, design patterns, and implementation." },
            { title: "Outcomes & Benefits", description: "ROI, performance gains, and future value." }
        ]
    },
    {
        id: 'technical',
        name: 'Technical Deep Dive',
        description: 'Focus on architecture, data flows, and engineering.',
        slides: [
            { title: "Technical Context", description: "Existing landscape and technical constraints." },
            { title: "Architecture Design", description: "Detailed diagram explanation and component breakdown." },
            { title: "Data Flow & Logic", description: "ETL/ELT processes and transformation logic." },
            { title: "Tech Stack & Tools", description: "List of technologies and their roles." }
        ]
    }
];

const CaseStoryGenerator: React.FC<CaseStoryGeneratorProps> = ({ setHasUnsavedChanges }) => {
    // Phase: 'setup' (Unified) -> 'workspace' (Preview/Edit)
    const [phase, setPhase] = useState<'setup' | 'workspace'>('setup');

    // Learning
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('standard');
    const [customTemplate, setCustomTemplate] = useState<CaseStoryTemplate | null>(null);
    const [isLearning, setIsLearning] = useState(false);

    // Input
    const [projectContext, setProjectContext] = useState('');
    const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);

    // Generation
    const [generatedSlides, setGeneratedSlides] = useState<SlideContent[]>([]);
    const [isGenerating, setIsGenerating] = useState(false);
    const [activeSlideIndex, setActiveSlideIndex] = useState<number | null>(null);

    // Editing State
    const [editingSlideId, setEditingSlideId] = useState<string | null>(null);

    // History State
    const [showHistory, setShowHistory] = useState(false);
    const [historyItems, setHistoryItems] = useState<any[]>([]);

    useEffect(() => {
        setHistoryItems(getHistory('CaseStory'));
    }, []);

    // Update dirty state
    useEffect(() => {
        if (projectContext.trim().length > 0 && phase !== 'workspace') {
            setHasUnsavedChanges(true);
        } else {
            setHasUnsavedChanges(false);
        }
    }, [projectContext, phase, setHasUnsavedChanges]);

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setIsLearning(true);
            const files = Array.from(e.target.files);
            setUploadedFiles(files);
            const fileNames = files.map((f: any) => f.name).join(', ');

            try {
                const structure = await analyzePPTStructure(`Uploaded PPT Files: ${fileNames}. Extract the slide sequence.`);
                const newTemplate: CaseStoryTemplate = {
                    id: 'custom-learned',
                    name: 'Learned from Uploads',
                    description: `Structure derived from ${files.length} presentation files.`,
                    slides: structure
                };
                setCustomTemplate(newTemplate);
                setSelectedTemplateId('custom-learned');
            } catch (e) {
                console.error(e);
            } finally {
                setIsLearning(false);
            }
        }
    };

    const getActiveTemplate = () => {
        if (selectedTemplateId === 'custom-learned' && customTemplate) return customTemplate;
        return DEFAULT_PPT_TEMPLATES.find(t => t.id === selectedTemplateId) || DEFAULT_PPT_TEMPLATES[0];
    };

    const startGeneration = async () => {
        if (!projectContext.trim() && uploadedFiles.length === 0) return;

        const template = getActiveTemplate();
        setPhase('workspace');
        setGeneratedSlides([]);
        setHasUnsavedChanges(false);

        const slides: SlideContent[] = [];

        // Use filenames in context if available
        const fullContext = projectContext + (uploadedFiles.length > 0 ? ` [Ref Files: ${uploadedFiles.map(f=>f.name).join(', ')}]` : "");

        for (let i = 0; i < template.slides.length; i++) {
            setActiveSlideIndex(i);
            setIsGenerating(true);
            const slideContent = await generateSlideContent(template.slides[i], fullContext);
            slides.push(slideContent);
            setGeneratedSlides([...slides]);
        }
        setIsGenerating(false);
        setActiveSlideIndex(null);

        // Save History
        saveHistory('CaseStory', projectContext.substring(0, 40) + '...', {
            context: projectContext,
            slides: slides
        });
        setHistoryItems(getHistory('CaseStory'));
    };

    const handleRegenerateSlide = async (index: number) => {
        const template = getActiveTemplate();
        setActiveSlideIndex(index);
        setIsGenerating(true);
        const newContent = await generateSlideContent(template.slides[index], projectContext);

        const updated = [...generatedSlides];
        updated[index] = newContent;
        setGeneratedSlides(updated);

        setIsGenerating(false);
        setActiveSlideIndex(null);
    };

    const updateSlideContent = (index: number, field: keyof SlideContent, value: any) => {
        const updated = [...generatedSlides];
        updated[index] = { ...updated[index], [field]: value };
        setGeneratedSlides(updated);
    };

    const updateBulletPoint = (slideIndex: number, bpIndex: number, text: string) => {
        const updated = [...generatedSlides];
        const newBullets = [...updated[slideIndex].bulletPoints];
        newBullets[bpIndex] = text;
        updated[slideIndex] = { ...updated[slideIndex], bulletPoints: newBullets };
        setGeneratedSlides(updated);
    };

    const exportToPPT = () => {
        if (typeof PptxGenJS === 'undefined') {
            alert("PPT Generator library not loaded.");
            return;
        }

        const pptx = new PptxGenJS();
        pptx.layout = 'LAYOUT_16x9';

        pptx.defineSlideMaster({
            title: 'MASTER_SLIDE',
            background: { color: 'F1F5F9' },
            objects: [
                { rect: { x: 0, y: 0, w: '100%', h: 0.75, fill: 'EA580C' } }, // Header Bar (Orange)
                { text: { text: 'Case Story', options: { x: 0.5, y: 0.15, w: 9, h: 0.5, fontSize: 20, color: 'FFFFFF', bold: true } } },
                { rect: { x: 0, y: 6.9, w: '100%', h: 0.6, fill: 'FFFFFF' } }, 
                { text: { text: 'Generated by DataArch AI', options: { x: 0.5, y: 7.0, w: 5, h: 0.4, fontSize: 10, color: '64748B' } } }
            ]
        });

        let slide = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
        slide.addText(getActiveTemplate().name, { x: 1, y: 2.5, w: 8, h: 1, fontSize: 36, color: '1E293B', bold: true, align: 'center' });
        slide.addText(`Client Context: ${projectContext.substring(0, 50)}...`, { x: 1.5, y: 3.5, w: 7, h: 0.5, fontSize: 18, color: '64748B', align: 'center' });

        generatedSlides.forEach(s => {
            slide = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
            slide.addText(s.title, { x: 0.5, y: 1, w: 9, h: 0.8, fontSize: 28, color: '1E293B', bold: true });
            const bullets = s.bulletPoints.map(bp => ({ text: bp, options: { fontSize: 16, color: '334155', bullet: true, breakLine: true } }));
            slide.addText(bullets, { x: 0.5, y: 2, w: 9, h: 4, lineSpacing: 32 });
            slide.addNotes(s.speakerNotes);
        });

        pptx.writeFile({ fileName: `Case_Story_${Date.now()}.pptx` });
    };

    // --- HISTORY HANDLERS ---
    const loadHistoryItem = (item: any) => {
        const data = item.data;
        setProjectContext(data.context);
        setGeneratedSlides(data.slides);
        setPhase('workspace');
        setShowHistory(false);
    };

    const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        deleteHistory(id);
        setHistoryItems(prev => prev.filter(h => h.id !== id));
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in overflow-hidden">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-20 shrink-0">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-orange-600 text-white rounded-lg shadow-sm"><Presentation size={20}/></div>
                    <div>
                        <h2 className="font-bold text-slate-800 text-lg">Case Story Generator</h2>
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                            <span className={phase === 'setup' ? 'font-bold text-orange-600' : ''}>Setup</span>
                            <ChevronRight size={12}/>
                            <span className={phase === 'workspace' ? 'font-bold text-orange-600' : ''}>Slides</span>
                        </div>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-4 py-2 rounded-lg transition-colors shadow-sm border ${showHistory ? 'bg-orange-50 text-orange-600 border-orange-200' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}>
                        <History size={18} /> History
                    </button>
                    {phase === 'workspace' && (
                        <button onClick={exportToPPT} className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-slate-800 shadow-md">
                            <Download size={14} /> Download PPT
                        </button>
                    )}
                </div>
            </div>

            {/* History Panel */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Recent Presentations</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                    {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                    historyItems.map((h, i) => (
                        <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                            <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                            <span className="text-slate-400 text-[10px]">{h.date}</span>
                            <div 
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                onClick={(e) => handleDeleteHistory(h.id, e)}
                            >
                                <Trash2 size={14} />
                            </div>
                        </button>
                    ))}
                    </div>
                </div>
            )}

            {/* MAIN CONTENT */}
            <div className="flex-1 overflow-hidden relative">

                {/* --- PHASE 1: UNIFIED SETUP --- */}
                {phase === 'setup' && (
                    <div className="h-full overflow-y-auto p-8 max-w-7xl mx-auto">
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
                            {/* Left: Template Selection */}
                            <div className="lg:col-span-4 space-y-6">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 mb-2">1. Choose Style</h3>
                                    <p className="text-xs text-slate-500 mb-4">Select the slide narrative structure.</p>
                                    <div className="space-y-3">
                                        {DEFAULT_PPT_TEMPLATES.map(t => (
                                            <button 
                                                key={t.id}
                                                onClick={() => setSelectedTemplateId(t.id)}
                                                className={`w-full text-left p-4 rounded-xl border-2 transition-all group ${selectedTemplateId === t.id ? 'border-orange-500 bg-orange-50 ring-1 ring-orange-200' : 'border-slate-200 hover:border-slate-300 bg-white'}`}
                                            >
                                                <div className="flex justify-between items-start">
                                                    <h4 className={`font-bold ${selectedTemplateId === t.id ? 'text-orange-700' : 'text-slate-700'}`}>{t.name}</h4>
                                                    {selectedTemplateId === t.id && <CheckCircle size={16} className="text-orange-600"/>}
                                                </div>
                                                <p className="text-xs text-slate-500 mt-1">{t.description}</p>
                                            </button>
                                        ))}
                                        {customTemplate && (
                                            <button 
                                                onClick={() => setSelectedTemplateId('custom-learned')}
                                                className={`w-full text-left p-4 rounded-xl border-2 transition-all ${selectedTemplateId === 'custom-learned' ? 'border-orange-500 bg-orange-50' : 'border-slate-200 bg-white'}`}
                                            >
                                                <div className="flex justify-between items-start">
                                                    <h4 className="font-bold text-orange-700">Learned Structure</h4>
                                                    <Sparkles size={16} className="text-orange-600"/>
                                                </div>
                                                <p className="text-xs text-slate-500 mt-1">From uploaded slides.</p>
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Right: Context & Files */}
                            <div className="lg:col-span-8 flex flex-col h-full">
                                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex-1 flex flex-col">
                                    <div className="mb-6">
                                        <h3 className="text-lg font-bold text-slate-800 mb-2">2. Project Context</h3>
                                        <p className="text-xs text-slate-500 mb-4">Provide details for the slide content.</p>
                                        <textarea 
                                            value={projectContext}
                                            onChange={(e) => setProjectContext(e.target.value)}
                                            className="w-full h-40 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none text-sm leading-relaxed bg-white text-slate-900 placeholder:text-slate-400"
                                            placeholder="Client: Acme Retail. Challenge: Slow reporting. Solution: Migrated to Snowflake. Impact: 50% faster queries..."
                                        />
                                    </div>

                                    <div className="mb-6">
                                        <h3 className="text-lg font-bold text-slate-800 mb-2">3. Reference Decks</h3>
                                        <div className="flex gap-4 items-start">
                                            <label className="flex-1 flex flex-col items-center justify-center h-32 border-2 border-dashed border-slate-300 rounded-xl cursor-pointer hover:bg-slate-50 hover:border-orange-400 transition-all bg-white">
                                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                                    {isLearning ? <Loader size={24} className="animate-spin text-orange-500"/> : <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />}
                                                    <p className="text-sm text-slate-600 font-bold">{isLearning ? 'Analyzing Structure...' : 'Click to Upload PPT'}</p>
                                                    <p className="text-xs text-slate-400">PPTX files</p>
                                                </div>
                                                <input type="file" className="hidden" multiple onChange={handleFileUpload} />
                                            </label>
                                            <div className="w-1/3 space-y-2">
                                                {uploadedFiles.map((f, i) => (
                                                    <div key={i} className="flex items-center gap-2 p-2 bg-slate-100 rounded-lg text-xs text-slate-600 border border-slate-200">
                                                        <Presentation size={12}/> <span className="truncate">{f.name}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="mt-auto flex justify-end">
                                        <button 
                                            onClick={startGeneration}
                                            disabled={!projectContext && uploadedFiles.length === 0}
                                            className="flex items-center gap-2 bg-orange-600 text-white px-8 py-4 rounded-xl font-bold hover:bg-orange-700 shadow-lg hover:shadow-orange-200 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                        >
                                            <Sparkles size={18} /> Generate Slides
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- PHASE 2: WORKSPACE (SLIDE EDIT) --- */}
                {phase === 'workspace' && (
                    <div className="flex h-full">
                        {/* Slide Navigator */}
                        <div className="w-64 bg-slate-50 border-r border-slate-200 flex flex-col shrink-0 overflow-y-auto p-4 space-y-4">
                            {generatedSlides.length === 0 && isGenerating && (
                                <div className="text-center py-8 text-slate-400">
                                    <Loader size={24} className="animate-spin text-orange-500 mx-auto mb-2"/>
                                    <p className="text-xs">Drafting slides...</p>
                                </div>
                            )}
                            {generatedSlides.map((slide, idx) => (
                                <button 
                                    key={idx}
                                    onClick={() => document.getElementById(`slide-${idx}`)?.scrollIntoView({ behavior: 'smooth' })}
                                    className="w-full aspect-video bg-white border border-slate-300 rounded-lg shadow-sm hover:ring-2 hover:ring-orange-400 transition-all p-2 flex flex-col justify-center items-center relative group"
                                >
                                    <div className="text-[8px] font-bold text-slate-700 text-center line-clamp-2 w-full px-1">{slide.title}</div>
                                    <div className="absolute top-2 left-2 text-[10px] font-bold text-slate-400">{idx + 1}</div>
                                    {activeSlideIndex === idx && <div className="absolute inset-0 bg-white/50 flex items-center justify-center"><Loader size={16} className="animate-spin text-orange-600"/></div>}
                                </button>
                            ))}
                        </div>

                        {/* Main Editor Canvas */}
                        <div className="flex-1 overflow-y-auto bg-slate-100 p-8">
                            <div className="max-w-4xl mx-auto space-y-12 pb-20">
                                {generatedSlides.map((slide, idx) => (
                                    <div key={idx} id={`slide-${idx}`} className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col aspect-[16/9] relative group">

                                        {/* Slide Header */}
                                        <div className="bg-slate-50 border-b border-slate-200 p-6 flex justify-between items-center h-20 shrink-0">
                                            <div className="flex items-center gap-4 w-full">
                                                <span className="bg-slate-200 text-slate-600 text-xs w-6 h-6 rounded-full flex items-center justify-center font-bold shrink-0">{idx + 1}</span>
                                                {editingSlideId === slide.id ? (
                                                    <input 
                                                        className="bg-white border border-orange-300 rounded px-2 py-1 text-xl font-bold text-slate-800 outline-none w-full"
                                                        value={slide.title}
                                                        onChange={(e) => updateSlideContent(idx, 'title', e.target.value)}
                                                        autoFocus
                                                    />
                                                ) : (
                                                    <h4 className="text-xl font-bold text-slate-800 line-clamp-1">{slide.title}</h4>
                                                )}
                                            </div>
                                            <div className="flex gap-2 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => setEditingSlideId(editingSlideId === slide.id ? null : slide.id)} className={`p-2 rounded-lg hover:bg-slate-200 ${editingSlideId === slide.id ? 'text-blue-600' : 'text-slate-400'}`} title="Edit Text">
                                                    <Pencil size={16} />
                                                </button>
                                                <button onClick={() => handleRegenerateSlide(idx)} className="p-2 rounded-lg hover:bg-slate-200 text-slate-400 hover:text-orange-600" title="Regenerate Slide">
                                                    <RefreshCw size={16} className={activeSlideIndex === idx ? 'animate-spin' : ''}/>
                                                </button>
                                            </div>
                                        </div>

                                        {/* Slide Body */}
                                        <div className="p-8 flex-1 overflow-y-auto bg-white">
                                            <ul className="space-y-4 list-disc pl-5 text-lg text-slate-700 leading-relaxed">
                                                {slide.bulletPoints.map((bp, i) => (
                                                    <li key={i} className="pl-2">
                                                        {editingSlideId === slide.id ? (
                                                            <textarea 
                                                                className="w-full bg-slate-50 border border-slate-200 rounded p-2 text-lg outline-none focus:ring-2 focus:ring-orange-500 resize-none"
                                                                value={bp}
                                                                onChange={(e) => updateBulletPoint(idx, i, e.target.value)}
                                                                rows={2}
                                                            />
                                                        ) : bp}
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>

                                        {/* Slide Footer / Notes */}
                                        <div className="bg-slate-50 p-4 border-t border-slate-200 text-xs text-slate-500 h-24 shrink-0 overflow-y-auto">
                                            <span className="font-bold block mb-1 text-slate-400 uppercase tracking-wider text-[10px]">Speaker Notes</span> 
                                            {editingSlideId === slide.id ? (
                                                <textarea 
                                                    className="w-full bg-white border border-slate-200 rounded p-2 text-xs outline-none resize-none h-full"
                                                    value={slide.speakerNotes}
                                                    onChange={(e) => updateSlideContent(idx, 'speakerNotes', e.target.value)}
                                                />
                                            ) : (
                                                <p>{slide.speakerNotes}</p>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default CaseStoryGenerator;

import React, { useState, useEffect } from 'react';
import { 
  Plus, 
  ArrowUpRight, 
  Search, 
  FileText,
  HelpCircle,
  X,
  Filter,
  Trash2,
  ArrowLeft,
  LayoutGrid,
  List as ListIcon,
  Clock,
  MoreHorizontal,
  FolderOpen,
  PieChart
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import CreateForm from './CreateForm';
import { RequestData, UserProfile } from '../types';

interface DesignHubProps {
  requests: RequestData[];
  onRequestCreate: (data: any) => void;
  onSelectRequest: (req: RequestData) => void;
  onDeleteRequest: (id: string) => void;
  userProfile?: UserProfile;
  setHasUnsavedChanges: (val: boolean) => void;
  handleSwitchTab: (tab: string) => void;
}

const DesignHub: React.FC<DesignHubProps> = ({ 
  requests, 
  onRequestCreate, 
  onSelectRequest, 
  onDeleteRequest, 
  userProfile, 
  setHasUnsavedChanges,
  handleSwitchTab
}) => {
  const [view, setView] = useState<'hub' | 'create'>('hub');
  const [displayMode, setDisplayMode] = useState<'grid' | 'list'>('grid');
  const [showHelp, setShowHelp] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'In Progress' | 'Completed' | 'Not Started'>('All');

  // Watch for view change to clean up dirty state
  useEffect(() => {
      if (view === 'hub') {
          setHasUnsavedChanges(false);
      }
  }, [view, setHasUnsavedChanges]);

  const handleFormDirty = (isDirty: boolean) => {
      setHasUnsavedChanges(isDirty);
  };

  const handleBackToOverview = () => {
      setView('hub');
  };

  const filteredRequests = requests.filter(r => {
    const matchesSearch = r.clientName.toLowerCase().includes(searchTerm.toLowerCase()) || r.type.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'All' || r.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  // Metrics Data
  const statusCounts = [
      { name: 'Completed', value: requests.filter(r => r.status === 'Completed').length, color: '#10B981' },
      { name: 'In Progress', value: requests.filter(r => r.status === 'In Progress').length, color: '#3B82F6' },
      { name: 'Not Started', value: requests.filter(r => r.status === 'Not Started').length, color: '#94A3B8' },
  ];

  const getStatusColor = (status: string) => {
      switch(status) {
          case 'Completed': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
          case 'In Progress': return 'bg-blue-100 text-blue-700 border-blue-200';
          default: return 'bg-slate-100 text-slate-600 border-slate-200';
      }
  };

  if (view === 'create') {
    return (
      <div className="relative h-full flex flex-col bg-slate-50">
        <div className="bg-white border-b border-slate-200 p-4 px-8 flex justify-between items-center shadow-sm sticky top-0 z-30">
            <button onClick={handleBackToOverview} className="text-sm font-bold text-slate-500 hover:text-slate-800 flex items-center gap-2 transition-colors">
                <ArrowLeft size={16}/> Back to Design Hub
            </button>
        </div>
        <div className="flex-1 overflow-hidden">
            <CreateForm 
            onSubmit={(data) => {
                onRequestCreate(data);
                setView('hub'); 
                setHasUnsavedChanges(false);
            }} 
            onCancel={() => {
                setView('hub');
                setHasUnsavedChanges(false);
            }} 
            userProfile={userProfile}
            onDirtyChange={handleFormDirty} 
            />
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 max-w-7xl mx-auto h-full flex flex-col relative animate-fade-in space-y-6">

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Solution Design Hub</h2>
          <p className="text-slate-500 mt-1">Manage, track, and initiate architectural blueprints.</p>
        </div>
        <div className="flex gap-3">
           <button onClick={() => setShowHelp(true)} className="flex items-center gap-2 px-4 py-2.5 text-sm font-bold text-slate-600 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors shadow-sm">
             <HelpCircle size={16} /> Help
           </button>
           <button onClick={() => setView('create')} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all hover:scale-105 active:scale-95">
             <Plus size={18} /> New Request
           </button>
        </div>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-3 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
             <div className="flex-1">
                <h4 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4">Design Velocity</h4>
                <div className="h-24 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={statusCounts} layout="vertical" barSize={12}>
                            <XAxis type="number" hide />
                            <YAxis dataKey="name" type="category" width={80} tick={{fontSize: 10, fill: '#64748B'}} axisLine={false} tickLine={false} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                            <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                                {statusCounts.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={entry.color} />
                                ))}
                            </Bar>
                        </BarChart>
                    </ResponsiveContainer>
                </div>
             </div>
             <div className="w-px h-24 bg-slate-100 mx-8 hidden md:block"></div>
             <div className="flex gap-8">
                 <div className="text-center">
                     <div className="text-3xl font-bold text-indigo-600">{requests.length}</div>
                     <div className="text-xs text-slate-400 font-bold uppercase mt-1">Total Designs</div>
                 </div>
                 <div className="text-center">
                     <div className="text-3xl font-bold text-emerald-500">{statusCounts[0].value}</div>
                     <div className="text-xs text-slate-400 font-bold uppercase mt-1">Deployed</div>
                 </div>
             </div>
          </div>

          <div className="bg-indigo-600 p-6 rounded-2xl shadow-lg text-white flex flex-col justify-between relative overflow-hidden group cursor-pointer" onClick={() => setView('create')}>
              <div className="absolute -right-4 -top-4 bg-white/10 w-24 h-24 rounded-full blur-xl group-hover:bg-white/20 transition-colors"></div>
              <div className="relative z-10">
                  <div className="w-10 h-10 bg-white/20 rounded-lg flex items-center justify-center mb-4 backdrop-blur-sm"><Plus size={24} /></div>
                  <h3 className="font-bold text-lg leading-tight">Start New Architecture</h3>
                  <p className="text-indigo-200 text-xs mt-2">AI-assisted setup</p>
              </div>
          </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-2 rounded-xl border border-slate-200 shadow-sm">
         <div className="flex items-center gap-2 w-full md:w-auto p-1">
            <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input 
                type="text" 
                placeholder="Search clients or stacks..." 
                className="w-full pl-9 pr-4 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white text-slate-900"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
            <div className="h-6 w-px bg-slate-200 mx-2 hidden md:block"></div>
            <div className="flex gap-1 overflow-x-auto hide-scrollbar">
                {['All', 'In Progress', 'Completed', 'Not Started'].map((status) => (
                    <button
                        key={status}
                        onClick={() => setStatusFilter(status as any)}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap transition-colors ${statusFilter === status ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:bg-slate-50'}`}
                    >
                        {status}
                    </button>
                ))}
            </div>
         </div>
         <div className="flex gap-2 p-1">
             <button onClick={() => setDisplayMode('grid')} className={`p-2 rounded-lg transition-colors ${displayMode === 'grid' ? 'bg-slate-100 text-slate-800' : 'text-slate-400 hover:text-slate-600'}`}><LayoutGrid size={18} /></button>
             <button onClick={() => setDisplayMode('list')} className={`p-2 rounded-lg transition-colors ${displayMode === 'list' ? 'bg-slate-100 text-slate-800' : 'text-slate-400 hover:text-slate-600'}`}><ListIcon size={18} /></button>
         </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto min-h-0">
          {filteredRequests.length === 0 ? (
             <div className="flex flex-col items-center justify-center h-64 text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
                 <FolderOpen size={48} className="mb-4 opacity-20"/>
                 <p className="text-sm font-medium">No designs found matching your filters.</p>
                 <button onClick={() => {setSearchTerm(''); setStatusFilter('All');}} className="text-indigo-600 text-xs font-bold mt-2 hover:underline">Clear Filters</button>
             </div>
          ) : (
             <div className={displayMode === 'grid' ? "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6" : "space-y-3"}>
                {filteredRequests.map((req) => (
                    <div 
                        key={req.id} 
                        onClick={() => onSelectRequest(req)}
                        className={`
                            bg-white border border-slate-200 hover:border-indigo-300 hover:shadow-md transition-all cursor-pointer group relative overflow-hidden
                            ${displayMode === 'grid' ? 'rounded-2xl p-6 flex flex-col h-full' : 'rounded-xl p-4 flex items-center justify-between'}
                        `}
                    >   
                        {/* Grid View Content */}
                        {displayMode === 'grid' && (
                            <>
                                <div className="flex justify-between items-start mb-4 relative z-10">
                                    <div className="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold text-xs border border-indigo-100">
                                        {req.clientName.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div className="flex gap-2">
                                        <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase border ${getStatusColor(req.status)}`}>{req.status}</span>
                                    </div>
                                </div>
                                <h3 className="text-lg font-bold text-slate-800 mb-1 group-hover:text-indigo-600 transition-colors relative z-10">{req.clientName}</h3>
                                <p className="text-xs text-slate-500 mb-4 relative z-10">{req.type} ({req.deploymentModel})</p>

                                <div className="mt-auto pt-4 border-t border-slate-100 flex justify-between items-center relative z-20">
                                    <div className="flex items-center gap-2 text-xs text-slate-400">
                                        <Clock size={12} /> {req.date}
                                    </div>
                                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button 
                                            type="button"
                                            className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors z-30"
                                            onClick={(e) => { 
                                                e.stopPropagation(); 
                                                e.preventDefault();
                                                onDeleteRequest(req.id); 
                                            }}
                                            onMouseDown={(e) => e.stopPropagation()}
                                        >
                                            <Trash2 size={14} />
                                        </button>
                                        <div className="bg-indigo-50 text-indigo-600 p-1.5 rounded-lg"><ArrowUpRight size={14} /></div>
                                    </div>
                                </div>
                                {/* Decorative Gradient */}
                                <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-indigo-50/50 to-transparent rounded-bl-full pointer-events-none z-0"></div>
                            </>
                        )}

                        {/* List View Content */}
                        {displayMode === 'list' && (
                            <>
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold text-xs border border-indigo-100">
                                        {req.clientName.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div>
                                        <h3 className="text-sm font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{req.clientName}</h3>
                                        <p className="text-xs text-slate-500">{req.type} • <span className="text-slate-400">{req.id}</span></p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-6">
                                    <div className="hidden md:flex items-center gap-2 text-xs text-slate-400 bg-slate-50 px-2 py-1 rounded">
                                        <FileText size={12} /> {req.rfpFiles.length} Files
                                    </div>
                                    <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase border ${getStatusColor(req.status)}`}>{req.status}</span>
                                    <div className="w-px h-8 bg-slate-100 mx-2"></div>
                                    <button 
                                        type="button"
                                        className="text-slate-300 hover:text-red-500 transition-colors p-2 hover:bg-slate-100 rounded-lg z-20"
                                        onClick={(e) => { 
                                            e.stopPropagation();
                                            e.preventDefault(); 
                                            onDeleteRequest(req.id); 
                                        }}
                                        onMouseDown={(e) => e.stopPropagation()}
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                    <ArrowUpRight size={18} className="text-slate-300 group-hover:text-indigo-500" />
                                </div>
                            </>
                        )}
                    </div>
                ))}
             </div>
          )}
      </div>

      {/* Help Modal */}
      {showHelp && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 animate-fade-in">
              <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                 <button onClick={() => setShowHelp(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
                 <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2"><HelpCircle className="text-indigo-500" /> Design Hub Guide</h3>
                 <div className="space-y-4 text-sm text-slate-600">
                    <p><strong>Design Hub v2.0:</strong> This is your command center for all architecture initiatives.</p>
                    <ul className="list-disc pl-5 space-y-2">
                       <li><strong>Create:</strong> Use the big purple card or the "New Request" button to start an AI-assisted design session.</li>
                       <li><strong>Manage:</strong> Switch between Grid and List views to organize your work. Use filters to find specific designs.</li>
                       <li><strong>Track:</strong> The metrics bar at the top gives you a live pulse on your design velocity and deployment status.</li>
                    </ul>
                 </div>
              </div>
           </div>
        )}
    </div>
  );
};

export default DesignHub;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet,
  LayoutGrid,
  History,
  Trash2,
  PieChart as PieChartIcon,
  BarChart as BarChartIcon,
  ArrowLeft,
  Search,
  Download,
  AlertTriangle,
  List
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  Tooltip as RechartsTooltip, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Legend 
} from 'recharts';
import { generateDataQualityRules, saveHistory, getHistory, deleteHistory, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

const StandaloneDataQuality: React.FC = () => {
  // View State
  const [viewMode, setViewMode] = useState<'input' | 'dashboard'>('input');
  const [activeTab, setActiveTab] = useState<'summary' | 'rules' | 'cleanse'>('summary');

  // Input State
  const [cdeContext, setCdeContext] = useState('');
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);

  // Data State
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // History State
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('DataQuality'));
  }, [validationRules]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
      const totalRules = validationRules.length;
      const uniqueElements = Array.from(new Set(validationRules.map(r => r.element)));

      // Dimension Distribution (Validity, Completeness, etc.)
      const dimCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const type = r.type || 'General';
          dimCounts[type] = (dimCounts[type] || 0) + 1;
      });
      const dimensionData = Object.entries(dimCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

      // Rules per Element (Top 10)
      const elemCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const elem = r.element || 'Unknown';
          elemCounts[elem] = (elemCounts[elem] || 0) + 1;
      });
      const elementData = Object.entries(elemCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 10);

      // Criticality
      const highCritCount = validationRules.filter(r => r.criticality === 'High').length;
      const medCritCount = validationRules.filter(r => r.criticality === 'Medium').length;

      return { totalRules, uniqueElements, dimensionData, elementData, highCritCount, medCritCount };
  }, [validationRules]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);

      const reader = new FileReader();
      reader.onload = (evt) => {
          if (evt.target?.result) {
              const content = evt.target.result as string;
              // Simple text extraction attempt
              setCdeContext(prev => prev + `\n\n[Context from ${file.name}]:\n${content.substring(0, 3000)}...`);
          }
      };
      reader.readAsText(file);
    }
  };

  const handleGenerate = async () => {
    if (!cdeContext.trim()) {
        setError("Please describe your data or requirements.");
        return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const rules = await generateDataQualityRules(`User Requirements: ${cdeContext}`, "Informatica CDQ");

      if (rules && rules.length > 0) {
          setValidationRules(rules);
          saveHistory('DataQuality', cdeContext.substring(0, 40) + '...', { 
              rules, 
              context: cdeContext 
          });
          analyzeAndLearn(cdeContext, "DQ Rules", rules, ['Steward'], 'initial');
          setViewMode('dashboard');
          setActiveTab('summary');
      } else {
          setError("No rules could be generated. Please provide more specific requirements.");
      }
    } catch (e) {
      setError("Generation failed. Please try again.");
    } finally { 
        setIsGenerating(false); 
    }
  };

  const loadHistoryItem = (item: any) => {
      const data = item.data;
      setValidationRules(data.rules || []);
      setCdeContext(data.context || item.summary);
      setViewMode('dashboard');
      setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      deleteHistory(id);
      setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const handleExportExcel = () => {
    if (typeof window.XLSX === 'undefined') {
        alert("Excel library not loaded.");
        return;
    }
    const wb = window.XLSX.utils.book_new();

    const ruleData = validationRules.map(r => ({
        "Data Element": r.element,
        "Rule Name": r.name,
        "Technical Asset": r.informaticaAssetName,
        "Dimension": r.type,
        "Criticality": r.criticality,
        "Description": r.description,
        "Logic": r.logic || ''
    }));

    const ws = window.XLSX.utils.json_to_sheet(ruleData);
    const wscols = [{wch: 20}, {wch: 30}, {wch: 25}, {wch: 15}, {wch: 10}, {wch: 50}, {wch: 40}];
    ws['!cols'] = wscols;
    window.XLSX.utils.book_append_sheet(wb, ws, "DQ Rules");
    window.XLSX.writeFile(wb, `DataQuality_Rules.xlsx`);
  };

  const filteredRules = validationRules.filter(r => 
      r.element.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // --- INPUT VIEW ---
  if (viewMode === 'input') {
      return (
        <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in items-center justify-center p-6">

            {/* History Dropdown */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Saved Rulesets</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                        {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                        historyItems.map((h, i) => (
                            <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                                <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                                <span className="text-slate-400 text-[10px]">{h.date}</span>
                                <div 
                                    className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                    onClick={(e) => handleDeleteHistory(h.id, e)}
                                >
                                    <Trash2 size={14} />
                                </div>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            <div className="w-full max-w-4xl bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden flex flex-col md:flex-row h-[600px] relative">

                {/* Header Actions */}
                <div className="absolute top-4 right-4 z-20">
                    <button onClick={() => setShowHistory(!showHistory)} className="p-2 bg-white/20 hover:bg-white/30 text-slate-500 hover:text-slate-800 rounded-lg backdrop-blur-md transition-colors">
                        <History size={20} />
                    </button>
                </div>

                {/* Left Panel: Branding */}
                <div className="md:w-1/3 bg-slate-900 p-8 flex flex-col justify-between text-white relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    <div className="absolute bottom-[-50px] left-[-50px] w-40 h-40 bg-emerald-500 rounded-full blur-[60px] opacity-30"></div>

                    <div className="relative z-10">
                        <div className="w-12 h-12 bg-emerald-600 rounded-xl flex items-center justify-center mb-6 shadow-lg shadow-emerald-900/50">
                            <ShieldCheck size={24} className="text-white"/>
                        </div>
                        <h2 className="text-2xl font-bold mb-2">Data Quality Studio</h2>
                        <p className="text-emerald-200 text-sm leading-relaxed">
                            Define validation logic and cleansing rules automatically from business requirements.
                        </p>
                    </div>

                    <div className="relative z-10 space-y-4 text-xs text-slate-400">
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Automated Rule Generation</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Dimension Classification</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Informatica CDQ Asset Naming</span>
                        </div>
                    </div>
                </div>

                {/* Right Panel: Form */}
                <div className="md:w-2/3 p-8 md:p-10 flex flex-col overflow-y-auto">
                    <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <BrainCircuit size={20} className="text-emerald-600"/> Rule Configuration
                    </h3>

                    <div className="space-y-6 flex-1">
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase">Input Requirements</label>
                            <textarea 
                                className="w-full h-64 p-4 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none text-sm leading-relaxed resize-none transition-all"
                                placeholder="Describe your data quality needs... E.g., 'Ensure Customer Email is valid format. Order Date cannot be in the future. Product ID must match the reference list.'"
                                value={cdeContext}
                                onChange={(e) => setCdeContext(e.target.value)}
                            />
                        </div>

                        <div className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-100">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-white rounded-lg border border-slate-200 text-slate-400">
                                    <UploadCloud size={18}/>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-700">{uploadedFileName || "Upload Specification"}</p>
                                    <p className="text-[10px] text-slate-400">PDF, DOCX, TXT</p>
                                </div>
                            </div>
                            <label className="cursor-pointer text-xs font-bold text-emerald-600 hover:text-emerald-700 bg-white px-3 py-1.5 rounded-lg border border-emerald-100 hover:border-emerald-200 transition-all shadow-sm">
                                Browse
                                <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.doc,.docx,.pdf"/>
                            </label>
                        </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-100">
                        {error && <div className="mb-4 text-xs text-red-500 bg-red-50 p-2 rounded flex items-center gap-2"><AlertTriangle size={14}/> {error}</div>}
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold shadow-lg shadow-emerald-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02]"
                        >
                            {isGenerating ? <Loader size={20} className="animate-spin"/> : <Sparkles size={20}/>}
                            Generate Rules
                        </button>
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">

        {/* Top Navigation Bar */}
        <div className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-4">
                <button onClick={() => setViewMode('input')} className="p-2 hover:bg-slate-100 rounded-lg text-slate-500 transition-colors">
                    <ArrowLeft size={20}/>
                </button>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                        DQ Studio <span className="text-slate-300">/</span> Ruleset
                    </h2>
                    <p className="text-xs text-slate-500">Automated Validation Logic</p>
                </div>
            </div>
            <div className="flex gap-3">
                <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-md transition-all hover:shadow-emerald-200">
                    <Download size={16} /> Export Excel
                </button>
                <button onClick={() => setViewMode('input')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-50 transition-all">
                    <RefreshCw size={16} /> New Ruleset
                </button>
            </div>
        </div>

        {/* Tab Bar */}
        <div className="bg-white border-b border-slate-200 px-6">
            <div className="flex gap-6">
                <button onClick={() => setActiveTab('summary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'summary' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <PieChartIcon size={16}/> Summary
                </button>
                <button onClick={() => setActiveTab('rules')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'rules' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <List size={16}/> Validation Rules
                </button>
                <button onClick={() => setActiveTab('cleanse')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'cleanse' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <Wand2 size={16}/> Cleansing Logic
                </button>
            </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 md:p-8">
            <div className="max-w-7xl mx-auto h-full">

                {/* --- TAB 1: SUMMARY DASHBOARD --- */}
                {activeTab === 'summary' && (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">

                        {/* Key Metrics */}
                        <div className="lg:col-span-2 grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Rules</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalRules}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">High Criticality</div>
                                <div className="text-3xl font-bold text-red-500 flex items-center gap-1">
                                    {stats.highCritCount} <AlertTriangle size={16}/>
                                </div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Data Elements</div>
                                <div className="text-3xl font-bold text-emerald-600">{stats.uniqueElements.length}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Medium Criticality</div>
                                <div className="text-3xl font-bold text-orange-500">{stats.medCritCount}</div>
                            </div>
                        </div>

                        {/* Chart: Dimensions */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <PieChartIcon size={18} className="text-emerald-500"/> Dimension Distribution
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={stats.dimensionData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                        >
                                            {stats.dimensionData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Legend verticalAlign="bottom" height={36} iconType="circle"/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Chart: Top Elements */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <BarChartIcon size={18} className="text-blue-500"/> Top Elements by Rule Count
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats.elementData} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                        <RechartsTooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Bar dataKey="value" fill="#3B82F6" radius={[0, 4, 4, 0]} barSize={20} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- TAB 2: RULES GRID --- */}
                {activeTab === 'rules' && (
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden animate-fade-in">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                            <div className="relative w-72">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                                <input 
                                    type="text" 
                                    placeholder="Filter by name, element, description..." 
                                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                            <div className="text-xs text-slate-400 font-medium">
                                {filteredRules.length} rules found
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto">
                            <table className="w-full text-left text-sm border-collapse">
                                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm text-slate-500 text-xs uppercase font-bold tracking-wider">
                                    <tr>
                                        <th className="p-4 border-b border-r border-slate-200 w-48">Data Element</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-48">Rule Name</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-32">Dimension</th>
                                        <th className="p-4 border-b border-r border-slate-200 w-24">Criticality</th>
                                        <th className="p-4 border-b border-slate-200">Logic & Description</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {filteredRules.map((rule, i) => (
                                        <tr key={i} className="hover:bg-slate-50/80 transition-colors group">
                                            <td className="p-4 border-r border-slate-100 font-bold text-slate-700 flex items-center gap-2">
                                                <Database size={14} className="text-slate-400 group-hover:text-emerald-500 transition-colors"/>
                                                {rule.element}
                                            </td>
                                            <td className="p-4 border-r border-slate-100 text-slate-600 font-medium text-xs">
                                                {rule.name}
                                                <div className="text-[10px] text-slate-400 mt-0.5">{rule.informaticaAssetName}</div>
                                            </td>
                                            <td className="p-4 border-r border-slate-100">
                                                <span className="bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-[10px] font-bold border border-indigo-100">
                                                    {rule.type}
                                                </span>
                                            </td>
                                            <td className="p-4 border-r border-slate-100">
                                                <span className={`inline-flex px-2 py-1 rounded text-[10px] font-bold border ${rule.criticality === 'High' ? 'bg-red-50 text-red-600 border-red-200' : rule.criticality === 'Medium' ? 'bg-orange-50 text-orange-600 border-orange-200' : 'bg-blue-50 text-blue-600 border-blue-200'}`}>
                                                    {rule.criticality}
                                                </span>
                                            </td>
                                            <td className="p-4">
                                                <p className="text-slate-700 text-xs leading-relaxed mb-1">{rule.description}</p>
                                                {rule.logic && <p className="text-[10px] font-mono text-slate-500 bg-slate-50 p-1.5 rounded border border-slate-100">{rule.logic}</p>}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* --- TAB 3: CLEANSE LOGIC --- */}
                {activeTab === 'cleanse' && (
                    <div className="flex flex-col h-full items-center justify-center bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-fade-in text-center">
                        <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mb-6">
                            <Wand2 size={40} />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Cleansing Logic Designer</h3>
                        <p className="text-slate-500 max-w-md mx-auto mb-8">
                            This module will allow for automated generation of standardization, parsing, and deduplication logic based on the validation rules.
                        </p>
                        <button disabled className="px-6 py-3 bg-slate-100 text-slate-400 rounded-xl font-bold cursor-not-allowed">
                            Coming Soon in v2.1
                        </button>
                    </div>
                )}

            </div>
        </div>
    </div>
  );
};

export default StandaloneDataQuality;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet,
  LayoutGrid,
  History,
  Trash2,
  PieChart as PieChartIcon,
  BarChart as BarChartIcon,
  ArrowLeft,
  Search,
  Download,
  AlertTriangle,
  List,
  ChevronDown,
  ChevronRight
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  Tooltip as RechartsTooltip, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Legend 
} from 'recharts';
import { generateDataQualityRules, saveHistory, getHistory, deleteHistory, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

// Restored Interface
interface GroupedRules { [element: string]: DataQualityRule[]; }

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

const StandaloneDataQuality: React.FC = () => {
  // View State
  const [viewMode, setViewMode] = useState<'input' | 'dashboard'>('input');
  const [activeTab, setActiveTab] = useState<'summary' | 'rules' | 'cleanse'>('summary');

  // Input State
  const [cdeContext, setCdeContext] = useState('');
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);

  // Data State
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);

  // Restored Grouping State
  const [groupedRules, setGroupedRules] = useState<GroupedRules>({});

  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // History State
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('DataQuality'));
  }, [validationRules]);

  // Restored Grouping Logic
  useEffect(() => {
    if (validationRules.length > 0) {
        const grouped: GroupedRules = {};
        validationRules.forEach(rule => {
            const key = rule.element || "General";
            if (!grouped[key]) grouped[key] = [];
            grouped[key].push(rule);
        });
        setGroupedRules(grouped);
    } else {
        setGroupedRules({});
    }
  }, [validationRules]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
      const totalRules = validationRules.length;
      const uniqueElements = Array.from(new Set(validationRules.map(r => r.element)));

      // Dimension Distribution (Validity, Completeness, etc.)
      const dimCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const type = r.type || 'General';
          dimCounts[type] = (dimCounts[type] || 0) + 1;
      });
      const dimensionData = Object.entries(dimCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

      // Rules per Element (Top 10)
      const elemCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const elem = r.element || 'Unknown';
          elemCounts[elem] = (elemCounts[elem] || 0) + 1;
      });
      const elementData = Object.entries(elemCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 10);

      // Criticality
      const highCritCount = validationRules.filter(r => r.criticality === 'High').length;
      const medCritCount = validationRules.filter(r => r.criticality === 'Medium').length;

      return { totalRules, uniqueElements, dimensionData, elementData, highCritCount, medCritCount };
  }, [validationRules]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);

      const reader = new FileReader();
      reader.onload = (evt) => {
          if (evt.target?.result) {
              const content = evt.target.result as string;
              // Simple text extraction attempt
              setCdeContext(prev => prev + `\n\n[Context from ${file.name}]:\n${content.substring(0, 3000)}...`);
          }
      };
      reader.readAsText(file);
    }
  };

  const handleGenerate = async () => {
    if (!cdeContext.trim()) {
        setError("Please describe your data or requirements.");
        return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const rules = await generateDataQualityRules(`User Requirements: ${cdeContext}`, "Informatica CDQ");

      if (rules && rules.length > 0) {
          setValidationRules(rules);
          saveHistory('DataQuality', cdeContext.substring(0, 40) + '...', { 
              rules, 
              context: cdeContext 
          });
          analyzeAndLearn(cdeContext, "DQ Rules", rules, ['Steward'], 'initial');
          setViewMode('dashboard');
          setActiveTab('summary');
      } else {
          setError("No rules could be generated. Please provide more specific requirements.");
      }
    } catch (e) {
      setError("Generation failed. Please try again.");
    } finally { 
        setIsGenerating(false); 
    }
  };

  const loadHistoryItem = (item: any) => {
      const data = item.data;
      setValidationRules(data.rules || []);
      setCdeContext(data.context || item.summary);
      setViewMode('dashboard');
      setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      deleteHistory(id);
      setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const handleExportExcel = () => {
    if (typeof window.XLSX === 'undefined') {
        alert("Excel library not loaded.");
        return;
    }
    const wb = window.XLSX.utils.book_new();

    const ruleData = validationRules.map(r => ({
        "Data Element": r.element,
        "Rule Name": r.name,
        "Technical Asset": r.informaticaAssetName,
        "Dimension": r.type,
        "Criticality": r.criticality,
        "Description": r.description,
        "Logic": r.logic || ''
    }));

    const ws = window.XLSX.utils.json_to_sheet(ruleData);
    const wscols = [{wch: 20}, {wch: 30}, {wch: 25}, {wch: 15}, {wch: 10}, {wch: 50}, {wch: 40}];
    ws['!cols'] = wscols;
    window.XLSX.utils.book_append_sheet(wb, ws, "DQ Rules");
    window.XLSX.writeFile(wb, `DataQuality_Rules.xlsx`);
  };

  // --- INPUT VIEW ---
  if (viewMode === 'input') {
      return (
        <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in items-center justify-center p-6">

            {/* History Dropdown */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Saved Rulesets</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                        {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                        historyItems.map((h, i) => (
                            <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                                <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                                <span className="text-slate-400 text-[10px]">{h.date}</span>
                                <div 
                                    className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                    onClick={(e) => handleDeleteHistory(h.id, e)}
                                >
                                    <Trash2 size={14} />
                                </div>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            <div className="w-full max-w-4xl bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden flex flex-col md:flex-row h-[600px] relative">

                {/* Header Actions */}
                <div className="absolute top-4 right-4 z-20">
                    <button onClick={() => setShowHistory(!showHistory)} className="p-2 bg-white/20 hover:bg-white/30 text-slate-500 hover:text-slate-800 rounded-lg backdrop-blur-md transition-colors">
                        <History size={20} />
                    </button>
                </div>

                {/* Left Panel: Branding */}
                <div className="md:w-1/3 bg-slate-900 p-8 flex flex-col justify-between text-white relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    <div className="absolute bottom-[-50px] left-[-50px] w-40 h-40 bg-emerald-500 rounded-full blur-[60px] opacity-30"></div>

                    <div className="relative z-10">
                        <div className="w-12 h-12 bg-emerald-600 rounded-xl flex items-center justify-center mb-6 shadow-lg shadow-emerald-900/50">
                            <ShieldCheck size={24} className="text-white"/>
                        </div>
                        <h2 className="text-2xl font-bold mb-2">Data Quality Studio</h2>
                        <p className="text-emerald-200 text-sm leading-relaxed">
                            Define validation logic and cleansing rules automatically from business requirements.
                        </p>
                    </div>

                    <div className="relative z-10 space-y-4 text-xs text-slate-400">
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Automated Rule Generation</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Dimension Classification</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Informatica CDQ Asset Naming</span>
                        </div>
                    </div>
                </div>

                {/* Right Panel: Form */}
                <div className="md:w-2/3 p-8 md:p-10 flex flex-col overflow-y-auto">
                    <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <BrainCircuit size={20} className="text-emerald-600"/> Rule Configuration
                    </h3>

                    <div className="space-y-6 flex-1">
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase">Input Requirements</label>
                            <textarea 
                                className="w-full h-64 p-4 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none text-sm leading-relaxed resize-none transition-all"
                                placeholder="Describe your data quality needs... E.g., 'Ensure Customer Email is valid format. Order Date cannot be in the future. Product ID must match the reference list.'"
                                value={cdeContext}
                                onChange={(e) => setCdeContext(e.target.value)}
                            />
                        </div>

                        <div className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-100">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-white rounded-lg border border-slate-200 text-slate-400">
                                    <UploadCloud size={18}/>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-700">{uploadedFileName || "Upload Specification"}</p>
                                    <p className="text-[10px] text-slate-400">PDF, DOCX, TXT</p>
                                </div>
                            </div>
                            <label className="cursor-pointer text-xs font-bold text-emerald-600 hover:text-emerald-700 bg-white px-3 py-1.5 rounded-lg border border-emerald-100 hover:border-emerald-200 transition-all shadow-sm">
                                Browse
                                <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.doc,.docx,.pdf"/>
                            </label>
                        </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-100">
                        {error && <div className="mb-4 text-xs text-red-500 bg-red-50 p-2 rounded flex items-center gap-2"><AlertTriangle size={14}/> {error}</div>}
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold shadow-lg shadow-emerald-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02]"
                        >
                            {isGenerating ? <Loader size={20} className="animate-spin"/> : <Sparkles size={20}/>}
                            Generate Rules
                        </button>
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">

        {/* Top Navigation Bar */}
        <div className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-4">
                <button onClick={() => setViewMode('input')} className="p-2 hover:bg-slate-100 rounded-lg text-slate-500 transition-colors">
                    <ArrowLeft size={20}/>
                </button>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                        DQ Studio <span className="text-slate-300">/</span> Ruleset
                    </h2>
                    <p className="text-xs text-slate-500">Automated Validation Logic</p>
                </div>
            </div>
            <div className="flex gap-3">
                <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-md transition-all hover:shadow-emerald-200">
                    <Download size={16} /> Export Excel
                </button>
                <button onClick={() => setViewMode('input')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-50 transition-all">
                    <RefreshCw size={16} /> New Ruleset
                </button>
            </div>
        </div>

        {/* Tab Bar */}
        <div className="bg-white border-b border-slate-200 px-6">
            <div className="flex gap-6">
                <button onClick={() => setActiveTab('summary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'summary' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <PieChartIcon size={16}/> Summary
                </button>
                <button onClick={() => setActiveTab('rules')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'rules' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <List size={16}/> Validation Rules
                </button>
                <button onClick={() => setActiveTab('cleanse')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'cleanse' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <Wand2 size={16}/> Cleansing Logic
                </button>
            </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 md:p-8">
            <div className="max-w-7xl mx-auto h-full">

                {/* --- TAB 1: SUMMARY DASHBOARD --- */}
                {activeTab === 'summary' && (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">

                        {/* Key Metrics */}
                        <div className="lg:col-span-2 grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Rules</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalRules}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">High Criticality</div>
                                <div className="text-3xl font-bold text-red-500 flex items-center gap-1">
                                    {stats.highCritCount} <AlertTriangle size={16}/>
                                </div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Data Elements</div>
                                <div className="text-3xl font-bold text-emerald-600">{stats.uniqueElements.length}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Medium Criticality</div>
                                <div className="text-3xl font-bold text-orange-500">{stats.medCritCount}</div>
                            </div>
                        </div>

                        {/* Chart: Dimensions */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <PieChartIcon size={18} className="text-emerald-500"/> Dimension Distribution
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={stats.dimensionData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                        >
                                            {stats.dimensionData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Legend verticalAlign="bottom" height={36} iconType="circle"/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Chart: Top Elements */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <BarChartIcon size={18} className="text-blue-500"/> Top Elements by Rule Count
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats.elementData} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                        <RechartsTooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Bar dataKey="value" fill="#3B82F6" radius={[0, 4, 4, 0]} barSize={20} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- TAB 2: RULES GRID (GROUPED) --- */}
                {activeTab === 'rules' && (
                    <div className="space-y-6 animate-fade-in">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-slate-800 text-lg">Grouped Validation Rules</h3>
                            <div className="relative w-72">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                                <input 
                                    type="text" 
                                    placeholder="Search rules..." 
                                    className="w-full pl-9 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 transition-all shadow-sm"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                        </div>

                        {Object.keys(groupedRules).length === 0 ? (
                            <div className="text-center py-20 text-slate-400">No rules generated yet.</div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {Object.entries(groupedRules).map(([element, rules]) => {
                                    // Apply search filter inside groups
                                    const visibleRules = rules.filter(r => 
                                        !searchTerm || 
                                        r.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                                        r.description.toLowerCase().includes(searchTerm.toLowerCase())
                                    );

                                    if (visibleRules.length === 0) return null;

                                    return (
                                        <div key={element} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col hover:shadow-md transition-shadow">
                                            <div className="bg-slate-50 px-5 py-3 border-b border-slate-200 flex justify-between items-center">
                                                <div className="flex items-center gap-2">
                                                    <div className="p-1.5 bg-white border border-slate-200 rounded-lg text-emerald-600">
                                                        <Database size={14} />
                                                    </div>
                                                    <h4 className="font-bold text-slate-800 text-sm">{element}</h4>
                                                </div>
                                                <span className="text-[10px] font-bold text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-200">
                                                    {visibleRules.length} Rules
                                                </span>
                                            </div>
                                            <div className="p-4 space-y-3 flex-1 overflow-y-auto max-h-96 custom-scrollbar">
                                                {visibleRules.map((rule, idx) => (
                                                    <div key={idx} className="bg-slate-50 border border-slate-100 rounded-xl p-3 hover:border-emerald-200 transition-colors group">
                                                        <div className="flex justify-between items-start mb-2">
                                                            <div className="text-xs font-bold text-slate-700">{rule.name}</div>
                                                            <span className={`text-[9px] uppercase font-bold px-1.5 py-0.5 rounded border ${
                                                                rule.criticality === 'High' ? 'bg-red-50 text-red-600 border-red-100' :
                                                                rule.criticality === 'Medium' ? 'bg-orange-50 text-orange-600 border-orange-100' :
                                                                'bg-blue-50 text-blue-600 border-blue-100'
                                                            }`}>
                                                                {rule.criticality}
                                                            </span>
                                                        </div>
                                                        <p className="text-[11px] text-slate-500 leading-relaxed mb-2">
                                                            {rule.description}
                                                        </p>
                                                        <div className="flex items-center justify-between pt-2 border-t border-slate-100">
                                                            <span className="text-[9px] font-mono text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-100 truncate max-w-[120px]">
                                                                {rule.informaticaAssetName}
                                                            </span>
                                                            <span className="text-[9px] font-bold text-indigo-500 bg-indigo-50 px-1.5 py-0.5 rounded">
                                                                {rule.type}
                                                            </span>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}

                {/* --- TAB 3: CLEANSE LOGIC --- */}
                {activeTab === 'cleanse' && (
                    <div className="flex flex-col h-full items-center justify-center bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-fade-in text-center">
                        <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mb-6">
                            <Wand2 size={40} />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Cleansing Logic Designer</h3>
                        <p className="text-slate-500 max-w-md mx-auto mb-8">
                            This module will allow for automated generation of standardization, parsing, and deduplication logic based on the validation rules.
                        </p>
                        <button disabled className="px-6 py-3 bg-slate-100 text-slate-400 rounded-xl font-bold cursor-not-allowed">
                            Coming Soon in v2.1
                        </button>
                    </div>
                )}

            </div>
        </div>
    </div>
  );
};

export default StandaloneDataQuality;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet,
  LayoutGrid,
  History,
  Trash2,
  PieChart as PieChartIcon,
  BarChart as BarChartIcon,
  ArrowLeft,
  Search,
  Download,
  AlertTriangle,
  List,
  ChevronDown,
  ChevronRight
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  Tooltip as RechartsTooltip, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Legend 
} from 'recharts';
import { generateDataQualityRules, saveHistory, getHistory, deleteHistory, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

// Restored Interface
interface GroupedRules { [element: string]: DataQualityRule[]; }

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

const StandaloneDataQuality: React.FC = () => {
  // View State
  const [viewMode, setViewMode] = useState<'input' | 'dashboard'>('input');
  const [activeTab, setActiveTab] = useState<'summary' | 'rules' | 'cleanse'>('summary');

  // Input State
  const [cdeContext, setCdeContext] = useState('');
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);

  // Data State
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);

  // Restored Grouping State
  const [groupedRules, setGroupedRules] = useState<GroupedRules>({});

  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // History State
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('DataQuality'));
  }, [validationRules]);

  // Restored Grouping Logic
  useEffect(() => {
    if (validationRules.length > 0) {
        const grouped: GroupedRules = {};
        validationRules.forEach(rule => {
            const key = rule.element || "General";
            if (!grouped[key]) grouped[key] = [];
            grouped[key].push(rule);
        });
        setGroupedRules(grouped);
    } else {
        setGroupedRules({});
    }
  }, [validationRules]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
      const totalRules = validationRules.length;
      const uniqueElements = Array.from(new Set(validationRules.map(r => r.element)));

      // Dimension Distribution (Validity, Completeness, etc.)
      const dimCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const type = r.type || 'General';
          dimCounts[type] = (dimCounts[type] || 0) + 1;
      });
      const dimensionData = Object.entries(dimCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

      // Rules per Element (Top 10)
      const elemCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const elem = r.element || 'Unknown';
          elemCounts[elem] = (elemCounts[elem] || 0) + 1;
      });
      const elementData = Object.entries(elemCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 10);

      // Criticality
      const highCritCount = validationRules.filter(r => r.criticality === 'High').length;
      const medCritCount = validationRules.filter(r => r.criticality === 'Medium').length;

      return { totalRules, uniqueElements, dimensionData, elementData, highCritCount, medCritCount };
  }, [validationRules]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);

      const reader = new FileReader();
      reader.onload = (evt) => {
          if (evt.target?.result) {
              const content = evt.target.result as string;
              // Simple text extraction attempt
              setCdeContext(prev => prev + `\n\n[Context from ${file.name}]:\n${content.substring(0, 3000)}...`);
          }
      };
      reader.readAsText(file);
    }
  };

  const handleGenerate = async () => {
    if (!cdeContext.trim()) {
        setError("Please describe your data or requirements.");
        return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const rules = await generateDataQualityRules(`User Requirements: ${cdeContext}`, "Informatica CDQ");

      if (rules && rules.length > 0) {
          setValidationRules(rules);
          saveHistory('DataQuality', cdeContext.substring(0, 40) + '...', { 
              rules, 
              context: cdeContext 
          });
          analyzeAndLearn(cdeContext, "DQ Rules", rules, ['Steward'], 'initial');
          setViewMode('dashboard');
          setActiveTab('summary');
      } else {
          setError("No rules could be generated. Please provide more specific requirements.");
      }
    } catch (e) {
      setError("Generation failed. Please try again.");
    } finally { 
        setIsGenerating(false); 
    }
  };

  const loadHistoryItem = (item: any) => {
      const data = item.data;
      setValidationRules(data.rules || []);
      setCdeContext(data.context || item.summary);
      setViewMode('dashboard');
      setShowHistory(false);
  };

  const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      deleteHistory(id);
      setHistoryItems(prev => prev.filter(h => h.id !== id));
  };

  const handleExportExcel = () => {
    if (typeof window.XLSX === 'undefined') {
        alert("Excel library not loaded.");
        return;
    }
    const wb = window.XLSX.utils.book_new();

    const ruleData = validationRules.map(r => ({
        "Data Element": r.element,
        "Rule Name": r.name,
        "Technical Asset": r.informaticaAssetName,
        "Dimension": r.type,
        "Criticality": r.criticality,
        "Description": r.description,
        "Logic": r.logic || ''
    }));

    const ws = window.XLSX.utils.json_to_sheet(ruleData);
    const wscols = [{wch: 20}, {wch: 30}, {wch: 25}, {wch: 15}, {wch: 10}, {wch: 50}, {wch: 40}];
    ws['!cols'] = wscols;
    window.XLSX.utils.book_append_sheet(wb, ws, "DQ Rules");
    window.XLSX.writeFile(wb, `DataQuality_Rules.xlsx`);
  };

  // --- INPUT VIEW ---
  if (viewMode === 'input') {
      return (
        <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in items-center justify-center p-6">

            {/* History Dropdown */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Saved Rulesets</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                        {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                        historyItems.map((h, i) => (
                            <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                                <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                                <span className="text-slate-400 text-[10px]">{h.date}</span>
                                <div 
                                    className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                    onClick={(e) => handleDeleteHistory(h.id, e)}
                                >
                                    <Trash2 size={14} />
                                </div>
                            </button>
                        ))}
                    </div>
                </div>
            )}

            <div className="w-full max-w-4xl bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden flex flex-col md:flex-row h-[600px] relative">

                {/* Header Actions */}
                <div className="absolute top-4 right-4 z-20">
                    <button onClick={() => setShowHistory(!showHistory)} className="p-2 bg-white/20 hover:bg-white/30 text-slate-500 hover:text-slate-800 rounded-lg backdrop-blur-md transition-colors">
                        <History size={20} />
                    </button>
                </div>

                {/* Left Panel: Branding */}
                <div className="md:w-1/3 bg-slate-900 p-8 flex flex-col justify-between text-white relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    <div className="absolute bottom-[-50px] left-[-50px] w-40 h-40 bg-emerald-500 rounded-full blur-[60px] opacity-30"></div>

                    <div className="relative z-10">
                        <div className="w-12 h-12 bg-emerald-600 rounded-xl flex items-center justify-center mb-6 shadow-lg shadow-emerald-900/50">
                            <ShieldCheck size={24} className="text-white"/>
                        </div>
                        <h2 className="text-2xl font-bold mb-2">Data Quality Studio</h2>
                        <p className="text-emerald-200 text-sm leading-relaxed">
                            Define validation logic and cleansing rules automatically from business requirements.
                        </p>
                    </div>

                    <div className="relative z-10 space-y-4 text-xs text-slate-400">
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Automated Rule Generation</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Dimension Classification</span>
                        </div>
                        <div className="flex items-center gap-3">
                            <CheckCircle size={16} className="text-emerald-500"/>
                            <span>Informatica CDQ Asset Naming</span>
                        </div>
                    </div>
                </div>

                {/* Right Panel: Form */}
                <div className="md:w-2/3 p-8 md:p-10 flex flex-col overflow-y-auto">
                    <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <BrainCircuit size={20} className="text-emerald-600"/> Rule Configuration
                    </h3>

                    <div className="space-y-6 flex-1">
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase">Input Requirements</label>
                            <textarea 
                                className="w-full h-64 p-4 border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none text-sm leading-relaxed resize-none transition-all"
                                placeholder="Describe your data quality needs... E.g., 'Ensure Customer Email is valid format. Order Date cannot be in the future. Product ID must match the reference list.'"
                                value={cdeContext}
                                onChange={(e) => setCdeContext(e.target.value)}
                            />
                        </div>

                        <div className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-100">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-white rounded-lg border border-slate-200 text-slate-400">
                                    <UploadCloud size={18}/>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-slate-700">{uploadedFileName || "Upload Specification"}</p>
                                    <p className="text-[10px] text-slate-400">PDF, DOCX, TXT</p>
                                </div>
                            </div>
                            <label className="cursor-pointer text-xs font-bold text-emerald-600 hover:text-emerald-700 bg-white px-3 py-1.5 rounded-lg border border-emerald-100 hover:border-emerald-200 transition-all shadow-sm">
                                Browse
                                <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.doc,.docx,.pdf"/>
                            </label>
                        </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-100">
                        {error && <div className="mb-4 text-xs text-red-500 bg-red-50 p-2 rounded flex items-center gap-2"><AlertTriangle size={14}/> {error}</div>}
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold shadow-lg shadow-emerald-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-[1.02]"
                        >
                            {isGenerating ? <Loader size={20} className="animate-spin"/> : <Sparkles size={20}/>}
                            Generate Rules
                        </button>
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- DASHBOARD VIEW ---
  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden animate-fade-in">

        {/* Top Navigation Bar */}
        <div className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center shadow-sm z-20 shrink-0">
            <div className="flex items-center gap-4">
                <button onClick={() => setViewMode('input')} className="p-2 hover:bg-slate-100 rounded-lg text-slate-500 transition-colors">
                    <ArrowLeft size={20}/>
                </button>
                <div>
                    <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                        DQ Studio <span className="text-slate-300">/</span> Ruleset
                    </h2>
                    <p className="text-xs text-slate-500">Automated Validation Logic</p>
                </div>
            </div>
            <div className="flex gap-3">
                <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-700 shadow-md transition-all hover:shadow-emerald-200">
                    <Download size={16} /> Export Excel
                </button>
                <button onClick={() => setViewMode('input')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-50 transition-all">
                    <RefreshCw size={16} /> New Ruleset
                </button>
            </div>
        </div>

        {/* Tab Bar */}
        <div className="bg-white border-b border-slate-200 px-6">
            <div className="flex gap-6">
                <button onClick={() => setActiveTab('summary')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'summary' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <PieChartIcon size={16}/> Summary
                </button>
                <button onClick={() => setActiveTab('rules')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'rules' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <List size={16}/> Validation Rules
                </button>
                <button onClick={() => setActiveTab('cleanse')} className={`py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all ${activeTab === 'cleanse' ? 'border-emerald-600 text-emerald-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
                    <Wand2 size={16}/> Cleansing Logic
                </button>
            </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 md:p-8">
            <div className="max-w-7xl mx-auto h-full">

                {/* --- TAB 1: SUMMARY DASHBOARD --- */}
                {activeTab === 'summary' && (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">

                        {/* Key Metrics */}
                        <div className="lg:col-span-2 grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Rules</div>
                                <div className="text-3xl font-bold text-slate-800">{stats.totalRules}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">High Criticality</div>
                                <div className="text-3xl font-bold text-red-500 flex items-center gap-1">
                                    {stats.highCritCount} <AlertTriangle size={16}/>
                                </div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Data Elements</div>
                                <div className="text-3xl font-bold text-emerald-600">{stats.uniqueElements.length}</div>
                            </div>
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Medium Criticality</div>
                                <div className="text-3xl font-bold text-orange-500">{stats.medCritCount}</div>
                            </div>
                        </div>

                        {/* Chart: Dimensions */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <PieChartIcon size={18} className="text-emerald-500"/> Dimension Distribution
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={stats.dimensionData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                        >
                                            {stats.dimensionData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Legend verticalAlign="bottom" height={36} iconType="circle"/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Chart: Top Elements */}
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-96 flex flex-col">
                            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <BarChartIcon size={18} className="text-blue-500"/> Top Elements by Rule Count
                            </h3>
                            <div className="flex-1 w-full min-h-0">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats.elementData} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                        <RechartsTooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}/>
                                        <Bar dataKey="value" fill="#3B82F6" radius={[0, 4, 4, 0]} barSize={20} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- TAB 2: RULES GRID (GROUPED) --- */}
                {activeTab === 'rules' && (
                    <div className="space-y-6 animate-fade-in">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-slate-800 text-lg">Grouped Validation Rules</h3>
                            <div className="relative w-72">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                                <input 
                                    type="text" 
                                    placeholder="Search rules..." 
                                    className="w-full pl-9 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 transition-all shadow-sm"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                        </div>

                        {Object.keys(groupedRules).length === 0 ? (
                            <div className="text-center py-20 text-slate-400">No rules generated yet.</div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {Object.entries(groupedRules).map(([element, rules]) => {
                                    // Apply search filter inside groups
                                    const visibleRules = (rules as DataQualityRule[]).filter(r => 
                                        !searchTerm || 
                                        r.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                                        r.description.toLowerCase().includes(searchTerm.toLowerCase())
                                    );

                                    if (visibleRules.length === 0) return null;

                                    return (
                                        <div key={element} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col hover:shadow-md transition-shadow">
                                            <div className="bg-slate-50 px-5 py-3 border-b border-slate-200 flex justify-between items-center">
                                                <div className="flex items-center gap-2">
                                                    <div className="p-1.5 bg-white border border-slate-200 rounded-lg text-emerald-600">
                                                        <Database size={14} />
                                                    </div>
                                                    <h4 className="font-bold text-slate-800 text-sm">{element}</h4>
                                                </div>
                                                <span className="text-[10px] font-bold text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-200">
                                                    {visibleRules.length} Rules
                                                </span>
                                            </div>
                                            <div className="p-4 space-y-3 flex-1 overflow-y-auto max-h-96 custom-scrollbar">
                                                {visibleRules.map((rule, idx) => (
                                                    <div key={idx} className="bg-slate-50 border border-slate-100 rounded-xl p-3 hover:border-emerald-200 transition-colors group">
                                                        <div className="flex justify-between items-start mb-2">
                                                            <div className="text-xs font-bold text-slate-700">{rule.name}</div>
                                                            <span className={`text-[9px] uppercase font-bold px-1.5 py-0.5 rounded border ${
                                                                rule.criticality === 'High' ? 'bg-red-50 text-red-600 border-red-100' :
                                                                rule.criticality === 'Medium' ? 'bg-orange-50 text-orange-600 border-orange-100' :
                                                                'bg-blue-50 text-blue-600 border-blue-100'
                                                            }`}>
                                                                {rule.criticality}
                                                            </span>
                                                        </div>
                                                        <p className="text-[11px] text-slate-500 leading-relaxed mb-2">
                                                            {rule.description}
                                                        </p>
                                                        <div className="flex items-center justify-between pt-2 border-t border-slate-100">
                                                            <span className="text-[9px] font-mono text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-100 truncate max-w-[120px]">
                                                                {rule.informaticaAssetName}
                                                            </span>
                                                            <span className="text-[9px] font-bold text-indigo-500 bg-indigo-50 px-1.5 py-0.5 rounded">
                                                                {rule.type}
                                                            </span>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}

                {/* --- TAB 3: CLEANSE LOGIC --- */}
                {activeTab === 'cleanse' && (
                    <div className="flex flex-col h-full items-center justify-center bg-white rounded-2xl shadow-sm border border-slate-200 p-8 animate-fade-in text-center">
                        <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mb-6">
                            <Wand2 size={40} />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Cleansing Logic Designer</h3>
                        <p className="text-slate-500 max-w-md mx-auto mb-8">
                            This module will allow for automated generation of standardization, parsing, and deduplication logic based on the validation rules.
                        </p>
                        <button disabled className="px-6 py-3 bg-slate-100 text-slate-400 rounded-xl font-bold cursor-not-allowed">
                            Coming Soon in v2.1
                        </button>
                    </div>
                )}

            </div>
        </div>
    </div>
  );
};

