             profile={userProfile}
             onSave={(p) => setUserProfile(p)}
          />

          <div className={`h-full ${activeTab === 'dashboard' ? 'block' : 'hidden'}`}>
            <DashboardView 
                requests={requests} 
                onSelectRequest={handleSelectRequest} 
