import React, { useState, useEffect, useMemo } from 'react';
import { 
  ShieldCheck, 
  Sparkles, 
  Loader, 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  RefreshCw, 
  X,
  BrainCircuit,
  Lock,
  Wand2,
  ArrowRight,
  Database,
  FileSpreadsheet,
  LayoutGrid,
  History,
  Trash2,
  PieChart as PieChartIcon,
  BarChart as BarChartIcon,
  ArrowLeft,
  Search,
  Download,
  AlertTriangle,
  List,
  ChevronDown,
  ChevronRight,
  MessageSquarePlus
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  Tooltip as RechartsTooltip, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Legend 
} from 'recharts';
import { generateDataQualityRules, saveHistory, getHistory, deleteHistory, analyzeAndLearn } from '../services/geminiService';
import { DataQualityRule } from '../types';

declare global {
  interface Window {
    XLSX: any;
  }
}

// Restored Interface
interface GroupedRules { [element: string]: DataQualityRule[]; }

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

const StandaloneDataQuality: React.FC = () => {
  // View State
  const [viewMode, setViewMode] = useState<'input' | 'dashboard'>('input');
  const [activeTab, setActiveTab] = useState<'summary' | 'rules' | 'cleanse'>('summary');

  // Input State
  const [cdeContext, setCdeContext] = useState('');
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);

  // Refinement State
  const [refinementInput, setRefinementInput] = useState('');
  const [showRefinement, setShowRefinement] = useState(true);

  // Data State
  const [validationRules, setValidationRules] = useState<DataQualityRule[]>([]);

  // Restored Grouping State
  const [groupedRules, setGroupedRules] = useState<GroupedRules>({});

  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // History State
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);

  useEffect(() => {
    setHistoryItems(getHistory('DataQuality'));
  }, [validationRules]);

  // Restored Grouping Logic
  useEffect(() => {
    if (validationRules.length > 0) {
        const grouped: GroupedRules = {};
        validationRules.forEach(rule => {
            const key = rule.element || "General";
            if (!grouped[key]) grouped[key] = [];
            grouped[key].push(rule);
        });
        setGroupedRules(grouped);
    } else {
        setGroupedRules({});
    }
  }, [validationRules]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
      const totalRules = validationRules.length;
      const uniqueElements = Array.from(new Set(validationRules.map(r => r.element)));

      // Dimension Distribution (Validity, Completeness, etc.)
      const dimCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const type = r.type || 'General';
          dimCounts[type] = (dimCounts[type] || 0) + 1;
      });
      const dimensionData = Object.entries(dimCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

      // Rules per Element (Top 10)
      const elemCounts: Record<string, number> = {};
      validationRules.forEach(r => {
          const elem = r.element || 'Unknown';
          elemCounts[elem] = (elemCounts[elem] || 0) + 1;
      });
      const elementData = Object.entries(elemCounts)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 10);

      // Criticality
      const highCritCount = validationRules.filter(r => r.criticality === 'High').length;
      const medCritCount = validationRules.filter(r => r.criticality === 'Medium').length;

      return { totalRules, uniqueElements, dimensionData, elementData, highCritCount, medCritCount };
  }, [validationRules]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFileName(file.name);

      const reader = new FileReader();

      // Excel Handling (Profile Exports or Data Samples)
      if (file.name.match(/\.(xlsx|xls|csv)$/i)) {
          if (typeof window.XLSX === 'undefined') {
              setCdeContext(prev => prev + `\n\n[Error: Excel library not loaded. Treating as binary.]`);
              return;
          }

          reader.onload = (evt) => {
              try {
                  const bstr = evt.target?.result;
                  const wb = window.XLSX.read(bstr, { type: 'binary' });

                  let extractedText = `\n\n[Analyzed Profile Export: ${file.name}]\n`;
                  let cdeFound: string[] = [];

                  wb.SheetNames.forEach((sheetName: string) => {
                      const ws = wb.Sheets[sheetName];
                      // Convert to JSON (Array of Arrays)
                      const data = window.XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

                      if (data && data.length > 0) {
                          extractedText += `\n--- Sheet: ${sheetName} ---\n`;

                          // Assuming Row 1 is headers
                          const headers = (data[0] as any[]).join(', ');
                          extractedText += `Columns: ${headers}\n`;

                          // Heuristic CDE Detection
                          (data[0] as any[]).forEach((col: string) => {
                              const c = col.toLowerCase();
                              if(c.includes('mail') || c.includes('phone') || c.includes('id') || c.includes('ssn') || c.includes('pan') || c.includes('dob') || c.includes('date') || c.includes('amount') || c.includes('name')) {
                                  cdeFound.push(col);
                              }
                          });

                          // Take a sample of up to 5 rows to understand data patterns
                          const sampleRows = data.slice(1, 6);
                          if (sampleRows.length > 0) {
                              extractedText += `Sample Values:\n`;
                              sampleRows.forEach((row: any) => {
                                  extractedText += `- ${JSON.stringify(row)}\n`;
                              });
                          }
                      }
                  });

                  if(cdeFound.length > 0) {
                      extractedText += `\n>>> DETECTED CRITICAL DATA ELEMENTS (PII/SPDI): ${Array.from(new Set(cdeFound)).join(', ')}. Generate specific Accuracy, Completeness and Validity rules for these.\n`;
                  }

                  setCdeContext(prev => prev + extractedText);
              } catch (err) {
                  console.error("Excel parse error", err);
                  setCdeContext(prev => prev + `\n\n[Error parsing Excel file: ${err}]`);
              }
          };
          reader.readAsBinaryString(file);
      } else {
          // Standard Text Handling
          reader.onload = (evt) => {
              if (evt.target?.result) {
                  const content = evt.target.result as string;
                  // Simple text extraction attempt
                  setCdeContext(prev => prev + `\n\n[Context from ${file.name}]:\n${content.substring(0, 3000)}...`);
              }
          };
          reader.readAsText(file);
      }
    }
  };

  const handleGenerate = async (refinementOverride?: string) => {
    const promptText = refinementOverride 
        ? `${cdeContext}\n\nUSER REFINEMENT REQUEST: The user has reviewed the initial rules and specifically requested focus on these Critical Data Elements (CDE): "${refinementOverride}". \nEnsure strict Completeness, Accuracy, Consistency, and Uniqueness rules are generated for these specific elements.` 
        : `User Requirements / Data Profile: ${cdeContext}`;

    if (!cdeContext.trim()) {
        setError("Please describe your data or requirements.");
        return;
    }
    setError(null);
    setIsGenerating(true);

    try {
      const rules = await generateDataQualityRules(promptText, "Informatica CDQ");

      if (rules && rules.length > 0) {
          setValidationRules(rules);
          saveHistory('DataQuality', cdeContext.substring(0, 40) + '...', { 
              rules, 
              context: cdeContext 
          });
          // Learn from the interaction if it was a refinement
          if (refinementOverride) {
              analyzeAndLearn(cdeContext, refinementOverride, rules, ['Steward'], 'refinement');
          } else {
              analyzeAndLearn(cdeContext, "DQ Rules", rules, ['Steward'], 'initial');
          }
          setViewMode('dashboard');
          setActiveTab('summary'); // Reset to summary or keep current? Summary is safer to show new stats.
          setShowRefinement(true); // Ensure refinement panel shows up
          if(refinementOverride) setRefinementInput(''); // Clear input on success
      } else {
          setError("No rules could be generated. Please provide more specific requirements.");
      }
    } catch (e) {
      setError("Generation failed. Please try again.");
    } finally { 
        setIsGenerating(false); 
    }
  };

