        name: 'High Level Design (HLD)',
        description: 'Strategic overview of system architecture.',
        sections: ['Executive Summary', 'Business Requirements', 'Solution Architecture', 'Technology Stack', 'Security & Compliance', 'Assumptions & Constraints']
    },
    {
        id: 'lld',
        name: 'Low Level Design (LLD)',
        description: 'Detailed component & data specifications.',
        sections: ['Component Specifications', 'Data Model (Schema)', 'API Interface Definitions', 'Error Handling', 'Logging & Monitoring', 'Deployment Specs']
    },
    {
        id: 'migration',
        name: 'Migration Strategy',
        description: 'Plan for legacy data migration.',
        sections: ['Current State Assessment', 'Migration Approach', 'Data Mapping Strategy', 'Cutover Plan', 'Rollback Strategy']
    }
];

const DocumentGenerator: React.FC<DocumentGeneratorProps> = ({ setHasUnsavedChanges }) => {
    // Phase: 'setup' (Unified) -> 'structure' (Review) -> 'workspace' (Edit/View)
    const [phase, setPhase] = useState<'setup' | 'structure' | 'workspace'>('setup');

    // Setup State
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('hld');
    const [projectContext, setProjectContext] = useState('');
    const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);

    // Learning State
    const [isLearning, setIsLearning] = useState(false);
    const [customTemplate, setCustomTemplate] = useState<DocumentTemplate | null>(null);
    const learningTimeoutRef = useRef<any>(null);

    // Structure State
    const [editableSections, setEditableSections] = useState<string[]>([]);
    const [newSectionName, setNewSectionName] = useState("");

    // Workspace State
    const [generatedSections, setGeneratedSections] = useState<DocumentSection[]>([]);
    const [activeSectionId, setActiveSectionId] = useState<string | null>(null); // For generation/viewing
    const [isGenerating, setIsGenerating] = useState(false);
    const [editContentBuffer, setEditContentBuffer] = useState("");
    const [editingSectionId, setEditingSectionId] = useState<string | null>(null); // For manual editing

    // Diagram State
    const [diagramType, setDiagramType] = useState<'table' | 'process'>('table');
    const [archFlowDesign, setArchFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [dataFlowDesign, setDataFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [isDiagramGenerating, setIsDiagramGenerating] = useState(false);
    const [activeWorkspaceTab, setActiveWorkspaceTab] = useState<'doc' | 'diagrams'>('doc');

    // History State
    const [showHistory, setShowHistory] = useState(false);
    const [historyItems, setHistoryItems] = useState<any[]>([]);

    useEffect(() => {
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === 'hld');
        if (t) setEditableSections([...t.sections]);
        setHistoryItems(getHistory('DocumentGenerator'));

        return () => {
            if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
        };
    }, []);

    // Watch for unsaved changes
    useEffect(() => {
        if (setHasUnsavedChanges) {
            const isDirty = (projectContext.trim().length > 0 && phase !== 'workspace') || editingSectionId !== null;
            setHasUnsavedChanges(isDirty);
        }
    }, [projectContext, phase, editingSectionId, setHasUnsavedChanges]);

    // --- HANDLERS: SETUP & LEARNING ---

    const handleTemplateSelect = (id: string) => {
        setSelectedTemplateId(id);
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === id);
        if (t) setEditableSections([...t.sections]);
        if (id === 'custom-learned' && customTemplate) setEditableSections([...customTemplate.sections]);
    };

    const readFileContent = (file: File): Promise<string> => {
        return new Promise((resolve) => {
            // Only attempt to read text-based files to avoid binary garbage
            if (file.name.match(/\.(txt|md|json|csv|xml|yml|yaml|html|js|ts|java|py|sql)$/i)) {
                const reader = new FileReader();
                reader.onload = (e) => resolve((e.target?.result as string) || "");
                reader.onerror = () => resolve(""); 
                reader.readAsText(file);
            } else {
                // For PDF/DOCX, we can't easily parse content without libraries.
                // Return empty string so we rely on filename inference.
                resolve(""); 
            }
        });
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const files = Array.from(e.target.files) as File[];
            setUploadedFiles(prev => [...prev, ...files]);

            // Auto-Learn Structure if it's the first upload and user is on default template
            if (!customTemplate) {
                setIsLearning(true);

                // Safety Timeout (30s)
                if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
                learningTimeoutRef.current = setTimeout(() => {
                    setIsLearning(false);
                    // Optionally alert user
                }, 30000);

                try {
                    // Read file contents (limit to first 3 files to avoid overload)
                    let combinedContext = "";
                    for (const file of files.slice(0, 3)) {
                        const content = await readFileContent(file);
                        if (content) {
                            combinedContext += `\n--- Content of ${file.name} ---\n${content.substring(0, 3000)}\n`;
                        } else {
                            combinedContext += `\n--- File: ${file.name} (Binary/Unreadable) ---\n`;
                        }
                    }

                    const prompt = `Files uploaded: ${files.map(f => f.name).join(', ')}. \n\nDocument Content Snippets:\n${combinedContext}\n\nAnalyze these filenames and content context to infer the Table of Contents (Structure).`;

                    const structure = await analyzeDocumentStructure(prompt);

                    const newTemplate = {
                        id: 'custom-learned',
                        name: 'Learned Structure',
                        description: 'Based on your uploaded files.',
                        sections: structure
                    };
                    setCustomTemplate(newTemplate);
                    setSelectedTemplateId('custom-learned');
                    setEditableSections(structure);
                } catch (e) {
                    console.error("Learning failed", e);
                } finally {
                    setIsLearning(false);
                    if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
                }
            }
        }
    };

    const cancelLearning = () => {
        setIsLearning(false);
        if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
    };

    // --- HANDLERS: STRUCTURE ---

    const addSection = () => {
        if (newSectionName.trim()) {
            setEditableSections([...editableSections, newSectionName.trim()]);
            setNewSectionName("");
        }
    };

    const removeSection = (index: number) => {
        const newSections = [...editableSections];
        newSections.splice(index, 1);
        setEditableSections(newSections);
    };

    const handleMoveSection = (index: number, direction: -1 | 1) => {
        if (index + direction < 0 || index + direction >= editableSections.length) return;
        const newSections = [...editableSections];
        const temp = newSections[index];
        newSections[index] = newSections[index + direction];
        newSections[index + direction] = temp;
        setEditableSections(newSections);
    };

    const goToWorkspace = () => {
        // Initialize sections
        const initialSections: DocumentSection[] = editableSections.map((title, idx) => ({
            id: `sec-${idx}`,
            title,
            content: '',
            status: 'pending'
        }));
        setGeneratedSections(initialSections);
        setPhase('workspace');

        // Trigger Generation
        const context = projectContext + " " + uploadedFiles.map(f=>f.name).join(' ');
        generateSectionsSequentially(initialSections, context);
        generateDiagrams(projectContext);

        if(setHasUnsavedChanges) setHasUnsavedChanges(false);
    };

    // --- HANDLERS: GENERATION ---

    const generateDiagrams = async (context: string) => {
        setIsDiagramGenerating(true);
        try {
            const arch = await generateTableArchitecture(context, "Infer schema and table architecture");
            setArchFlowDesign(arch);
            const data = await generateProcessArchitecture(context, "Infer data flow and processing steps");
            setDataFlowDesign(data);
        } catch (e) { console.error(e); } finally { setIsDiagramGenerating(false); }
    };

    const generateSectionsSequentially = async (sections: DocumentSection[], context: string) => {
        const allHeaders = sections.map(s => s.title);
        const newSections = [...sections];

        for (let i = 0; i < newSections.length; i++) {
            setActiveSectionId(newSections[i].id);
            setIsGenerating(true);
            const content = await generateDocumentContent(newSections[i].title, context, allHeaders);
            newSections[i] = { ...newSections[i], content, status: 'generated' };
            setGeneratedSections([...newSections]);
        }
        setIsGenerating(false);
        setActiveSectionId(null);

        // Save History when generation completes
        saveHistory('DocumentGenerator', projectContext.substring(0, 40) + '...', {
            context: projectContext,
            sections: newSections,
            archDesign: archFlowDesign,
            dataDesign: dataFlowDesign
        });
        setHistoryItems(getHistory('DocumentGenerator'));
    };

    const handleRegenerateSection = async (sectionId: string) => {
        const idx = generatedSections.findIndex(s => s.id === sectionId);
        if (idx === -1) return;
        setActiveSectionId(sectionId);
        setIsGenerating(true);
        const newContent = await generateDocumentContent(generatedSections[idx].title, projectContext, generatedSections.map(s => s.title));
        const newSections = [...generatedSections];
        newSections[idx] = { ...newSections[idx], content: newContent, status: 'generated' };
        setGeneratedSections(newSections);
        setIsGenerating(false);
        setActiveSectionId(null);
    };

    // --- HANDLERS: EDITING ---

    const startEditing = (section: DocumentSection) => {
        setEditingSectionId(section.id);
        setEditContentBuffer(section.content);
    };

    const saveEditing = () => {
        if (editingSectionId) {
            setGeneratedSections(prev => prev.map(s => s.id === editingSectionId ? { ...s, content: editContentBuffer, status: 'edited' } : s));
            setEditingSectionId(null);
        }
    };

    const handleRefineDiagram = async (prompt: string) => {
        setIsDiagramGenerating(true);
        try {
            if (diagramType === 'table') {
                const arch = await generateTableArchitecture(projectContext, prompt);
                setArchFlowDesign(arch);
            } else {
                const data = await generateProcessArchitecture(projectContext, prompt);
                setDataFlowDesign(data);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setIsDiagramGenerating(false);
        }
    };

    const exportToWord = () => {
        const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Export</title></head><body>`;
        const footer = "</body></html>";
        let bodyHTML = `<h1>Solution Document</h1><p><strong>Context:</strong> ${projectContext.substring(0, 200)}...</p><hr/>`;
        generatedSections.forEach(sec => {
            bodyHTML += `<h2>${sec.title}</h2><div>${sec.content.replace(/\n/g, '<br/>')}</div><br/>`;
        });
        const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(header + bodyHTML + footer);
        const link = document.createElement("a");
        link.href = source;
        link.download = `solution_${Date.now()}.doc`;
        link.click();
    };

    // --- HISTORY HANDLERS ---
    const loadHistoryItem = (item: any) => {
        const data = item.data;
        setProjectContext(data.context);
        setGeneratedSections(data.sections);
        if(data.archDesign) setArchFlowDesign(data.archDesign);
        if(data.dataDesign) setDataFlowDesign(data.dataDesign);
        setPhase('workspace');
        setShowHistory(false);
    };

    const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        deleteHistory(id);
        setHistoryItems(prev => prev.filter(h => h.id !== id));
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in overflow-hidden">

            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-20 shrink-0">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-pink-600 text-white rounded-lg shadow-sm"><FileText size={20}/></div>
                    <div>
                        <h2 className="font-bold text-slate-800 text-lg">Doc Generator</h2>
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                            <span className={phase === 'setup' ? 'font-bold text-indigo-600' : ''}>Setup</span>
                            <ChevronRight size={12}/>
                            <span className={phase === 'structure' ? 'font-bold text-indigo-600' : ''}>Structure</span>
                            <ChevronRight size={12}/>
                            <span className={phase === 'workspace' ? 'font-bold text-indigo-600' : ''}>Workspace</span>
                        </div>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-4 py-2 rounded-lg transition-colors shadow-sm border ${showHistory ? 'bg-pink-50 text-pink-600 border-pink-200' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}>
                        <History size={18} /> History
                    </button>
                    {phase === 'workspace' && (
                        <button onClick={exportToWord} className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-slate-800 shadow-md">
                            <Download size={14} /> Export Word
                        </button>
                    )}
                </div>
            </div>

            {/* History Panel */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Recent Documents</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                    {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                    historyItems.map((h, i) => (
                        <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                            <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                            <span className="text-slate-400 text-[10px]">{h.date}</span>
                            <div 
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                onClick={(e) => handleDeleteHistory(h.id, e)}
                            >
                                <Trash2 size={14} />
                            </div>
                        </button>
                    ))}
                    </div>
                </div>
            )}

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 overflow-hidden relative">

                {/* --- PHASE 1: UNIFIED SETUP --- */}
                {phase === 'setup' && (
                    <div className="h-full overflow-y-auto p-8 max-w-7xl mx-auto">
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
                            {/* Left: Template Selection */}
                            <div className="lg:col-span-4 space-y-6">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 mb-2">1. Choose Template</h3>
                                    <p className="text-xs text-slate-500 mb-4">Select a base structure or let AI learn from your files.</p>
                                    <div className="space-y-3">
                                        {DEFAULT_TEMPLATES.map(t => (
                                            <button 
                                                key={t.id}
                                                onClick={() => handleTemplateSelect(t.id)}
                                                className={`w-full text-left p-4 rounded-xl border-2 transition-all group ${selectedTemplateId === t.id ? 'border-pink-500 bg-pink-50 ring-1 ring-pink-200' : 'border-slate-200 hover:border-slate-300 bg-white'}`}
                                            >
                                                <div className="flex justify-between items-start">
                                                    <h4 className={`font-bold ${selectedTemplateId === t.id ? 'text-pink-700' : 'text-slate-700'}`}>{t.name}</h4>
                                                    {selectedTemplateId === t.id && <CheckCircle size={16} className="text-pink-600"/>}
                                                </div>
                                                <p className="text-xs text-slate-500 mt-1">{t.description}</p>
                                            </button>
                                        ))}
                                        {customTemplate && (
                                            <button 
                                                onClick={() => handleTemplateSelect('custom-learned')}
                                                className={`w-full text-left p-4 rounded-xl border-2 transition-all ${selectedTemplateId === 'custom-learned' ? 'border-pink-500 bg-pink-50' : 'border-slate-200 bg-white'}`}
                                            >
                                                <div className="flex justify-between items-start">
                                                    <h4 className="font-bold text-pink-700">Learned Template</h4>
                                                    <Sparkles size={16} className="text-pink-600"/>
                                                </div>
                                                <p className="text-xs text-slate-500 mt-1">Structure extracted from uploads.</p>
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Right: Context & Files */}
                            <div className="lg:col-span-8 flex flex-col h-full">
                                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex-1 flex flex-col">
                                    <div className="mb-6">
                                        <h3 className="text-lg font-bold text-slate-800 mb-2">2. Project Context</h3>
                                        <p className="text-xs text-slate-500 mb-4">Provide details to generate specific content.</p>
                                        <textarea 
                                            value={projectContext}
                                            onChange={(e) => setProjectContext(e.target.value)}
                                            className="w-full h-40 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-pink-500 outline-none text-sm leading-relaxed bg-white text-slate-900 placeholder:text-slate-400"
                                            placeholder="e.g. Migrating Oracle to Snowflake for a Retail client. Needs to handle 5TB data daily. Emphasis on GDPR and masking PII..."
                                        />
                                    </div>

                                    <div className="mb-6">
                                        <h3 className="text-lg font-bold text-slate-800 mb-2">3. Reference Files</h3>
                                        <div className="flex gap-4 items-start">
                                            <label className="flex-1 flex flex-col items-center justify-center h-32 border-2 border-dashed border-slate-300 rounded-xl cursor-pointer hover:bg-slate-50 hover:border-pink-400 transition-all bg-white relative overflow-hidden">
                                                {isLearning ? (
                                                    <div className="flex flex-col items-center justify-center pt-5 pb-6 animate-pulse w-full">
                                                        <Loader size={24} className="animate-spin text-pink-500 mb-2"/>
                                                        <p className="text-sm text-slate-600 font-bold">Analyzing Structure...</p>
                                                        <p className="text-xs text-slate-400 mb-2">Reading files to infer sections</p>
                                                        <button 
                                                            type="button" 
                                                            onClick={(e) => { e.preventDefault(); cancelLearning(); }}
                                                            className="text-xs text-red-500 hover:bg-red-50 px-2 py-1 rounded border border-red-100 flex items-center gap-1 z-20"
                                                        >
                                                            <XCircle size={12} /> Cancel
                                                        </button>
                                                    </div>
                                                ) : (
                                                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                                        <UploadCloud className="w-8 h-8 mb-3 text-slate-400" />
                                                        <p className="text-sm text-slate-600 font-bold">Click to Upload Docs</p>
                                                        <p className="text-xs text-slate-400">PDF, DOCX, TXT</p>
                                                    </div>
                                                )}
                                                <input type="file" className="hidden" multiple onChange={handleFileUpload} disabled={isLearning}/>
                                            </label>
                                            <div className="w-1/3 space-y-2">
                                                {uploadedFiles.map((f, i) => (
                                                    <div key={i} className="flex items-center gap-2 p-2 bg-slate-100 rounded-lg text-xs text-slate-600 border border-slate-200">
                                                        <FileText size={12}/> <span className="truncate">{f.name}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="mt-auto flex justify-end">
                                        <button 
                                            onClick={() => setPhase('structure')}
                                            disabled={!projectContext && uploadedFiles.length === 0}
                                            className="flex items-center gap-2 bg-pink-600 text-white px-8 py-4 rounded-xl font-bold hover:bg-pink-700 shadow-lg hover:shadow-pink-200 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                        >
                                            Next: Review Outline <ArrowRight size={18} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- PHASE 2: STRUCTURE REVIEW --- */}
                {phase === 'structure' && (
                    <div className="h-full p-8 max-w-4xl mx-auto flex flex-col">
                        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 flex-1 flex flex-col">
                            <div className="flex justify-between items-center mb-6">
                                <div>
                                    <h3 className="text-2xl font-bold text-slate-800">Review Document Outline</h3>
                                    <p className="text-slate-500 text-sm">Drag to reorder or add new sections before generating.</p>
                                </div>
                                <button onClick={() => setPhase('setup')} className="text-sm text-slate-500 hover:text-slate-800">Back</button>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 space-y-2 mb-6 custom-scrollbar">
                                {editableSections.map((sec, idx) => (
                                    <div key={idx} className="flex items-center gap-3 p-3 bg-white border border-slate-200 rounded-lg group hover:border-pink-300 hover:shadow-sm transition-all">
                                        <div className="text-slate-300 cursor-move hover:text-slate-500 flex flex-col gap-0.5">
                                            <button onClick={() => handleMoveSection(idx, -1)} className="hover:text-pink-500"><ChevronRight size={12} className="-rotate-90"/></button>
                                            <button onClick={() => handleMoveSection(idx, 1)} className="hover:text-pink-500"><ChevronRight size={12} className="rotate-90"/></button>
                                        </div>
                                        <div className="flex-1 font-bold text-sm text-slate-700">{idx + 1}. {sec}</div>
                                        <button onClick={() => removeSection(idx)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16} /></button>
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-2 pt-4 border-t border-slate-100">
                                <input 
                                    type="text" 
                                    value={newSectionName}
                                    onChange={(e) => setNewSectionName(e.target.value)}
                                    placeholder="Add new section title..."
                                    className="flex-1 border border-slate-300 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-pink-500 bg-white text-slate-900"
                                    onKeyDown={(e) => e.key === 'Enter' && addSection()}
                                />
                                <button onClick={addSection} className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl font-bold text-sm hover:bg-slate-200"><Plus size={18} /></button>
                                <button 
                                    onClick={goToWorkspace}
                                    className="ml-4 flex items-center gap-2 bg-pink-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-pink-700 shadow-lg transition-transform hover:scale-105 active:scale-95"
                                >
                                    <Sparkles size={18} /> Generate Document
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- PHASE 3: WORKSPACE (EDITOR) --- */}
                {phase === 'workspace' && (
                    <div className="flex h-full">
                        {/* Sidebar: Outline */}
                        <div className="w-72 bg-white border-r border-slate-200 flex flex-col shrink-0">
                            <div className="p-4 border-b border-slate-100">
                                <div className="flex bg-slate-100 p-1 rounded-lg mb-2">
                                    <button onClick={() => setActiveWorkspaceTab('doc')} className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${activeWorkspaceTab === 'doc' ? 'bg-white text-pink-600 shadow-sm' : 'text-slate-500'}`}>Content</button>
                                    <button onClick={() => setActiveWorkspaceTab('diagrams')} className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${activeWorkspaceTab === 'diagrams' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>Diagrams</button>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto p-2 space-y-1 custom-scrollbar">
                                {activeWorkspaceTab === 'doc' ? (
                                    generatedSections.map((sec, idx) => (
                                        <button 
                                            key={sec.id}
                                            onClick={() => document.getElementById(sec.id)?.scrollIntoView({ behavior: 'smooth' })}
                                            className={`w-full text-left p-3 rounded-lg text-xs font-medium flex justify-between items-center transition-all ${sec.status === 'generated' || sec.status === 'edited' ? 'bg-white border border-slate-200 text-slate-700 hover:border-pink-300' : 'bg-slate-50 border border-transparent text-slate-400'}`}
                                        >
                                            <span className="truncate">{idx + 1}. {sec.title}</span>
                                            {activeSectionId === sec.id ? <Loader size={12} className="animate-spin text-pink-500"/> : (sec.status === 'generated' || sec.status === 'edited') && <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>}
                                        </button>
                                    ))
                                ) : (
                                    <div className="p-4 text-xs text-slate-500 text-center">
                                        Use the main view to interact with diagrams.
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Main: Content Editor or Canvas */}
                        <div className="flex-1 overflow-y-auto bg-slate-50 p-8 relative">
                            {activeWorkspaceTab === 'doc' ? (
                                <div className="max-w-4xl mx-auto space-y-8 pb-20">
                                    {generatedSections.map((sec) => (
                                        <div key={sec.id} id={sec.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden group">
                                            <div className="bg-white px-8 py-6 border-b border-slate-100 flex justify-between items-center sticky top-0 z-10">
                                                <h4 className="font-bold text-slate-800 text-lg">{sec.title}</h4>
                                                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    {editingSectionId !== sec.id && (
                                                        <button onClick={() => startEditing(sec)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-blue-600 transition-colors" title="Edit Content">
                                                            <Pencil size={16} />
                                                        </button>
                                                    )}
                                                    <button onClick={() => handleRegenerateSection(sec.id)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-pink-600 transition-colors" title="Regenerate with AI">
                                                        <RefreshCw size={16} className={activeSectionId === sec.id ? 'animate-spin' : ''} />
                                                    </button>
                                                </div>
                                            </div>

                                            <div className="p-8 min-h-[200px]">
                                                {editingSectionId === sec.id ? (
                                                    <div className="animate-fade-in">
                                                        <textarea 
                                                            value={editContentBuffer}
                                                            onChange={(e) => setEditContentBuffer(e.target.value)}
                                                            className="w-full h-96 p-4 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-mono leading-relaxed bg-white text-slate-800 resize-y"
                                                        />
                                                        <div className="flex justify-end gap-2 mt-4">
                                                            <button onClick={() => setEditingSectionId(null)} className="px-4 py-2 text-sm rounded border border-slate-300 hover:bg-slate-50 text-slate-600 font-bold">Cancel</button>
                                                            <button onClick={saveEditing} className="px-4 py-2 text-sm rounded bg-indigo-600 hover:bg-indigo-700 text-white font-bold">Save Changes</button>
                                                        </div>
                                                    </div>
                                                ) : sec.status === 'pending' ? (
                                                    <div className="h-full flex flex-col items-center justify-center text-slate-300 py-12">
                                                        {activeSectionId === sec.id ? (
                                                            <>
                                                                <Loader size={32} className="animate-spin mb-3 text-pink-400"/>
                                                                <p className="text-sm font-medium">AI is writing content...</p>
                                                            </>
                                                        ) : (
                                                            <div className="flex flex-col items-center gap-2">
                                                                <div className="w-12 h-2 bg-slate-100 rounded-full"></div>
                                                                <div className="w-8 h-2 bg-slate-100 rounded-full"></div>
                                                                <p className="text-xs mt-2">Waiting in queue</p>
                                                            </div>
                                                        )}
                                                    </div>
                                                ) : (
                                                    <div className="prose prose-sm max-w-none text-slate-700 leading-relaxed" onDoubleClick={() => startEditing(sec)}>
                                                        {sec.content.split('\n').map((line, i) => (
                                                            <p key={i} className="mb-3">{line.replace(/^\*\*(.*?)\*\*$/, '$1')}</p> 
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                // Diagram View
                                <div className="h-full flex flex-col">
                                    <div className="mb-4 flex justify-center">
                                        <div className="bg-white p-1 rounded-lg shadow-sm border border-slate-200 inline-flex">
                                            <button onClick={() => setDiagramType('table')} className={`px-4 py-2 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'table' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <Table size={14} /> Architecture Flow
                                            </button>
                                            <button onClick={() => setDiagramType('process')} className={`px-4 py-2 rounded-md text-xs font-bold transition-all flex items-center gap-2 ${diagramType === 'process' ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:text-slate-700'}`}>
                                                <ArrowRightCircle size={14} /> Data Flow
                                            </button>
                                        </div>
                                    </div>
                                    <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative">
                                        {isDiagramGenerating ? (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/80 backdrop-blur-sm z-30">
                                                <Loader size={32} className="animate-spin text-pink-500 mb-2"/>
                                                <p className="text-sm text-slate-500">Generating diagram...</p>
                                            </div>
                                        ) : (
                                            <ArchitectureCanvas 
                                                aiNodes={diagramType === 'table' ? archFlowDesign.nodes : dataFlowDesign.nodes} 
                                                aiEdges={diagramType === 'table' ? archFlowDesign.edges : dataFlowDesign.edges} 
                                                isThinking={false} 
                                                thoughts={[]} 
                                                context={projectContext}
                                                onRefine={handleRefineDiagram}
                                                refinementPlaceholder={`Refine ${diagramType === 'table' ? 'Architecture' : 'Data'} Flow...`}
                                            />
                                        )}
                                        {(!isDiagramGenerating && (diagramType === 'table' ? archFlowDesign.nodes.length === 0 : dataFlowDesign.nodes.length === 0)) && (
                                            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400">
                                                <Network size={48} className="mb-4 opacity-20" />
                                                <p>No diagram generated yet.</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                )}

            </div>
        </div>
    );
};

export default DocumentGenerator;

import React, { useState, useEffect, useRef } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Loader, 
  Sparkles, 
  CheckCircle, 
  BookOpen, 
  Edit3, 
  Download, 
  LayoutTemplate,
  ArrowRight,
  RefreshCw,
  Plus,
  Trash2,
  Network,
  ArrowRightCircle,
  Table,
  GripVertical,
  Pencil,
  FileBox,
  Settings,
  ChevronRight,
  Maximize2,
  History,
  XCircle,
  AlertTriangle
} from 'lucide-react';
import { DocumentSection, DocumentTemplate, DesignData } from '../types';
import { analyzeDocumentStructure, generateDocumentContent, generateTableArchitecture, generateProcessArchitecture, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import ArchitectureCanvas from './ArchitectureCanvas';

interface DocumentGeneratorProps {
  setHasUnsavedChanges?: (val: boolean) => void;
}

const DEFAULT_TEMPLATES: DocumentTemplate[] = [
    {
        id: 'hld',
        name: 'High Level Design (HLD)',
        description: 'Strategic overview of system architecture.',
        sections: ['Executive Summary', 'Business Requirements', 'Solution Architecture', 'Technology Stack', 'Security & Compliance', 'Assumptions & Constraints']
    },
    {
        id: 'lld',
        name: 'Low Level Design (LLD)',
        description: 'Detailed component & data specifications.',
        sections: ['Component Specifications', 'Data Model (Schema)', 'API Interface Definitions', 'Error Handling', 'Logging & Monitoring', 'Deployment Specs']
    },
    {
        id: 'migration',
        name: 'Migration Strategy',
        description: 'Plan for legacy data migration.',
        sections: ['Current State Assessment', 'Migration Approach', 'Data Mapping Strategy', 'Cutover Plan', 'Rollback Strategy']
    }
];

const DocumentGenerator: React.FC<DocumentGeneratorProps> = ({ setHasUnsavedChanges }) => {
    // Phase: 'setup' (Unified) -> 'structure' (Review) -> 'workspace' (Edit/View)
    const [phase, setPhase] = useState<'setup' | 'structure' | 'workspace'>('setup');

    // Setup State
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('hld');
    const [projectContext, setProjectContext] = useState('');
    const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);

    // Learning State
    const [isLearning, setIsLearning] = useState(false);
    const [customTemplate, setCustomTemplate] = useState<DocumentTemplate | null>(null);
    const [analysisError, setAnalysisError] = useState<string | null>(null);
    const learningTimeoutRef = useRef<any>(null);

    // Structure State
    const [editableSections, setEditableSections] = useState<string[]>([]);
    const [newSectionName, setNewSectionName] = useState("");

    // Workspace State
    const [generatedSections, setGeneratedSections] = useState<DocumentSection[]>([]);
    const [activeSectionId, setActiveSectionId] = useState<string | null>(null); // For generation/viewing
    const [isGenerating, setIsGenerating] = useState(false);
    const [editContentBuffer, setEditContentBuffer] = useState("");
    const [editingSectionId, setEditingSectionId] = useState<string | null>(null); // For manual editing

    // Diagram State
    const [diagramType, setDiagramType] = useState<'table' | 'process'>('table');
    const [archFlowDesign, setArchFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [dataFlowDesign, setDataFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [isDiagramGenerating, setIsDiagramGenerating] = useState(false);
    const [activeWorkspaceTab, setActiveWorkspaceTab] = useState<'doc' | 'diagrams'>('doc');

    // History State
    const [showHistory, setShowHistory] = useState(false);
    const [historyItems, setHistoryItems] = useState<any[]>([]);

    useEffect(() => {
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === 'hld');
        if (t) setEditableSections([...t.sections]);
        setHistoryItems(getHistory('DocumentGenerator'));

        return () => {
            if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
        };
    }, []);

    // Watch for unsaved changes
    useEffect(() => {
        if (setHasUnsavedChanges) {
            const isDirty = (projectContext.trim().length > 0 && phase !== 'workspace') || editingSectionId !== null;
            setHasUnsavedChanges(isDirty);
        }
    }, [projectContext, phase, editingSectionId, setHasUnsavedChanges]);

    // --- HANDLERS: SETUP & LEARNING ---

    const handleTemplateSelect = (id: string) => {
        setSelectedTemplateId(id);
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === id);
        if (t) setEditableSections([...t.sections]);
        if (id === 'custom-learned' && customTemplate) setEditableSections([...customTemplate.sections]);
    };

    const readFileContent = (file: File): Promise<string> => {
        return new Promise((resolve) => {
            // Only attempt to read text-based files to avoid binary garbage
            if (file.name.match(/\.(txt|md|json|csv|xml|yml|yaml|html|js|ts|java|py|sql)$/i)) {
                const reader = new FileReader();
                reader.onload = (e) => resolve((e.target?.result as string) || "");
                reader.onerror = () => resolve(""); 
                reader.readAsText(file);
            } else {
                // For PDF/DOCX, we can't easily parse content without libraries.
                // Return empty string so we rely on filename inference.
                resolve(""); 
            }
        });
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (isLearning) return; // Prevent double trigger
        if (e.target.files && e.target.files.length > 0) {
            const files = Array.from(e.target.files) as File[];
            setUploadedFiles(prev => [...prev, ...files]);
            setAnalysisError(null);

            // Auto-Learn Structure if it's the first upload and user is on default template
            // Or if user explicitly wants to re-learn, they can clear and upload.
            // Here we trigger if no custom template exists yet.
            if (!customTemplate) {
                setIsLearning(true);

                // Safety Timeout (30s)
                if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
                learningTimeoutRef.current = setTimeout(() => {
                    setIsLearning(false);
                    setAnalysisError("Analysis timed out. Please try again or use a manual template.");
                }, 30000);

                try {
                    // Read file contents (limit to first 3 files to avoid overload)
                    let combinedContext = "";
                    for (const file of files.slice(0, 3)) {
                        const content = await readFileContent(file);
                        if (content) {
                            combinedContext += `\n--- Content of ${file.name} ---\n${content.substring(0, 3000)}\n`;
                        } else {
                            combinedContext += `\n--- File: ${file.name} (Binary Format - Structure inferred from name) ---\n`;
                        }
                    }

                    const prompt = `Files uploaded: ${files.map(f => f.name).join(', ')}. \n\nDocument Content Snippets:\n${combinedContext}\n\nAnalyze these filenames and content context to infer the Table of Contents (Structure).`;

                    const structure = await analyzeDocumentStructure(prompt);

                    // Fallback if AI returns empty
                    const finalStructure = structure && structure.length > 0 ? structure : DEFAULT_TEMPLATES[0].sections;

                    const newTemplate = {
                        id: 'custom-learned',
                        name: 'Learned Structure',
                        description: `Based on ${files.length} uploaded file(s).`,
                        sections: finalStructure
                    };
                    setCustomTemplate(newTemplate);
                    setSelectedTemplateId('custom-learned');
                    setEditableSections(finalStructure);

                    // AUTO ADVANCE TO STRUCTURE PHASE for better interactivity
                    setPhase('structure');

                } catch (e) {
                    console.error("Learning failed", e);
                    setAnalysisError("Failed to analyze structure. Using default template.");
                } finally {
                    setIsLearning(false);
                    if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
                }
            }
        }
    };

    const cancelLearning = () => {
        setIsLearning(false);
        if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
    };

    // --- HANDLERS: STRUCTURE ---

    const addSection = () => {
        if (newSectionName.trim()) {
            setEditableSections([...editableSections, newSectionName.trim()]);
            setNewSectionName("");
        }
    };

    const removeSection = (index: number) => {
        const newSections = [...editableSections];
        newSections.splice(index, 1);
        setEditableSections(newSections);
    };

    const handleMoveSection = (index: number, direction: -1 | 1) => {
        if (index + direction < 0 || index + direction >= editableSections.length) return;
        const newSections = [...editableSections];
        const temp = newSections[index];
        newSections[index] = newSections[index + direction];
        newSections[index + direction] = temp;
        setEditableSections(newSections);
    };

    const goToWorkspace = () => {
        if (editableSections.length === 0) {
            alert("Please ensure there is at least one section in the outline.");
            return;
        }

        // Initialize sections
        const initialSections: DocumentSection[] = editableSections.map((title, idx) => ({
            id: `sec-${idx}`,
            title,
            content: '',
            status: 'pending'
        }));
        setGeneratedSections(initialSections);
        setPhase('workspace');

        // Trigger Generation
        const context = projectContext + " " + uploadedFiles.map(f=>f.name).join(' ');
        generateSectionsSequentially(initialSections, context);
        generateDiagrams(projectContext);

        if(setHasUnsavedChanges) setHasUnsavedChanges(false);
    };

    // --- HANDLERS: GENERATION ---

    const generateDiagrams = async (context: string) => {
        setIsDiagramGenerating(true);
        try {
            const arch = await generateTableArchitecture(context, "Infer schema and table architecture");
            setArchFlowDesign(arch);
            const data = await generateProcessArchitecture(context, "Infer data flow and processing steps");
            setDataFlowDesign(data);
        } catch (e) { console.error(e); } finally { setIsDiagramGenerating(false); }
    };

    const generateSectionsSequentially = async (sections: DocumentSection[], context: string) => {
        const allHeaders = sections.map(s => s.title);
        const newSections = [...sections];

        for (let i = 0; i < newSections.length; i++) {
            setActiveSectionId(newSections[i].id);
            setIsGenerating(true);
            const content = await generateDocumentContent(newSections[i].title, context, allHeaders);
            newSections[i] = { ...newSections[i], content, status: 'generated' };
            setGeneratedSections([...newSections]);
        }
        setIsGenerating(false);
        setActiveSectionId(null);

        // Save History when generation completes
        saveHistory('DocumentGenerator', projectContext.substring(0, 40) + '...', {
            context: projectContext,
            sections: newSections,
            archDesign: archFlowDesign,
            dataDesign: dataFlowDesign
        });
        setHistoryItems(getHistory('DocumentGenerator'));
    };

    const handleRegenerateSection = async (sectionId: string) => {
        const idx = generatedSections.findIndex(s => s.id === sectionId);
        if (idx === -1) return;
        setActiveSectionId(sectionId);
        setIsGenerating(true);
        const newContent = await generateDocumentContent(generatedSections[idx].title, projectContext, generatedSections.map(s => s.title));
        const newSections = [...generatedSections];
        newSections[idx] = { ...newSections[idx], content: newContent, status: 'generated' };
        setGeneratedSections(newSections);
        setIsGenerating(false);
        setActiveSectionId(null);
    };

    // --- HANDLERS: EDITING ---

    const startEditing = (section: DocumentSection) => {
        setEditingSectionId(section.id);
        setEditContentBuffer(section.content);
    };

    const saveEditing = () => {
        if (editingSectionId) {
            setGeneratedSections(prev => prev.map(s => s.id === editingSectionId ? { ...s, content: editContentBuffer, status: 'edited' } : s));
            setEditingSectionId(null);
        }
    };

    const handleRefineDiagram = async (prompt: string) => {
        setIsDiagramGenerating(true);
        try {
            if (diagramType === 'table') {
                const arch = await generateTableArchitecture(projectContext, prompt);
                setArchFlowDesign(arch);
            } else {
                const data = await generateProcessArchitecture(projectContext, prompt);
                setDataFlowDesign(data);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setIsDiagramGenerating(false);
        }
    };

    const exportToWord = () => {
        const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Export</title></head><body>`;
        const footer = "</body></html>";
        let bodyHTML = `<h1>Solution Document</h1><p><strong>Context:</strong> ${projectContext.substring(0, 200)}...</p><hr/>`;
        generatedSections.forEach(sec => {
            bodyHTML += `<h2>${sec.title}</h2><div>${sec.content.replace(/\n/g, '<br/>')}</div><br/>`;
        });
        const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(header + bodyHTML + footer);
        const link = document.createElement("a");
        link.href = source;
        link.download = `solution_${Date.now()}.doc`;
        link.click();
    };

    // --- HISTORY HANDLERS ---
    const loadHistoryItem = (item: any) => {
        const data = item.data;
        setProjectContext(data.context);
        setGeneratedSections(data.sections);
        if(data.archDesign) setArchFlowDesign(data.archDesign);
        if(data.dataDesign) setDataFlowDesign(data.dataDesign);
        setPhase('workspace');
        setShowHistory(false);
    };

    const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        deleteHistory(id);
        setHistoryItems(prev => prev.filter(h => h.id !== id));
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in overflow-hidden">

            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-20 shrink-0">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-pink-600 text-white rounded-lg shadow-sm"><FileText size={20}/></div>
                    <div>
                        <h2 className="font-bold text-slate-800 text-lg">Doc Generator</h2>
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                            <span className={phase === 'setup' ? 'font-bold text-indigo-600' : ''}>Setup</span>
                            <ChevronRight size={12}/>
                            <span className={phase === 'structure' ? 'font-bold text-indigo-600' : ''}>Structure</span>
                            <ChevronRight size={12}/>
                            <span className={phase === 'workspace' ? 'font-bold text-indigo-600' : ''}>Workspace</span>
                        </div>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 text-sm font-medium px-4 py-2 rounded-lg transition-colors shadow-sm border ${showHistory ? 'bg-pink-50 text-pink-600 border-pink-200' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}>
                        <History size={18} /> History
                    </button>
                    {phase === 'workspace' && (
                        <button onClick={exportToWord} className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-slate-800 shadow-md">
                            <Download size={14} /> Export Word
                        </button>
                    )}
                </div>
            </div>

            {/* History Panel */}
            {showHistory && (
                <div className="absolute top-20 right-6 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                    <h3 className="font-bold text-sm mb-3 text-slate-800">Recent Documents</h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto">
                    {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center py-2">No history available</p> :
                    historyItems.map((h, i) => (
                        <button key={i} onClick={() => loadHistoryItem(h)} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg border border-slate-100 text-xs group relative transition-all">
                            <div className="truncate font-bold text-slate-700 mb-1">{h.summary}</div>
                            <span className="text-slate-400 text-[10px]">{h.date}</span>
                            <div 
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 rounded p-1 hover:text-red-500 cursor-pointer"
                                onClick={(e) => handleDeleteHistory(h.id, e)}
                            >
                                <Trash2 size={14} />
                            </div>
                        </button>
                    ))}
                    </div>
                </div>
            )}

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 overflow-hidden relative">

                {/* --- PHASE 1: UNIFIED SETUP --- */}
                {phase === 'setup' && (
                    <div className="h-full overflow-y-auto p-8 max-w-7xl mx-auto">
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
                            {/* Left: Template Selection */}
                            <div className="lg:col-span-4 space-y-6">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 mb-2">1. Choose Template</h3>
                                    <p className="text-xs text-slate-500 mb-4">Select a base structure or let AI learn from your files.</p>
                                    <div className="space-y-3">
                                        {DEFAULT_TEMPLATES.map(t => (
                                            <button 
                                                key={t.id}
                                                onClick={() => handleTemplateSelect(t.id)}
                                                className={`w-full text-left p-4 rounded-xl border-2 transition-all group ${selectedTemplateId === t.id ? 'border-pink-500 bg-pink-50 ring-1 ring-pink-200' : 'border-slate-200 hover:border-slate-300 bg-white'}`}
                                            >
                                                <div className="flex justify-between items-start">
                                                    <h4 className={`font-bold ${selectedTemplateId === t.id ? 'text-pink-700' : 'text-slate-700'}`}>{t.name}</h4>
                                                    {selectedTemplateId === t.id && <CheckCircle size={16} className="text-pink-600"/>}
                                                </div>
                                                <p className="text-xs text-slate-500 mt-1">{t.description}</p>
                                            </button>
                                        ))}
                                        {customTemplate && (
                                            <button 
                                                onClick={() => handleTemplateSelect('custom-learned')}
                                                className={`w-full text-left p-4 rounded-xl border-2 transition-all ${selectedTemplateId === 'custom-learned' ? 'border-pink-500 bg-pink-50' : 'border-slate-200 bg-white'}`}
                                            >
                                                <div className="flex justify-between items-start">
                                                    <h4 className="font-bold text-pink-700">Learned Template</h4>
                                                    <Sparkles size={16} className="text-pink-600"/>
                                                </div>
                                                <p className="text-xs text-slate-500 mt-1">Structure extracted from uploads.</p>
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Right: Context & Files */}
                            <div className="lg:col-span-8 flex flex-col h-full">
