                                                {analysisError && (
                                                    <div className="p-2 bg-red-50 border border-red-100 rounded-lg text-xs text-red-600 flex items-start gap-1">
                                                        <AlertTriangle size={12} className="shrink-0 mt-0.5"/> {analysisError}
                                                    </div>
