                                                    </div>
                                                )}
                                                <input type="file" className="hidden" multiple onChange={handleFileUpload} disabled={isLearning}/>
                                            </label>

                                            <div className="w-1/3 space-y-2 max-h-32 overflow-y-auto">
                                                {uploadedFiles.length === 0 && <p className="text-xs text-slate-400 italic p-2">No files attached.</p>}
