                                                        <button onClick={() => removeFile(i)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                                            <XCircle size={14} />
                                                        </button>
                                                    </div>
                                                ))}
                                                {analysisError && (
                                                    <div className="p-2 bg-red-50 border border-red-100 rounded-lg text-xs text-red-600 flex items-start gap-1">
                                                        <AlertTriangle size={12} className="shrink-0 mt-0.5"/> {analysisError}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="mt-auto flex justify-end">
                                        <button 
                                            onClick={handleAnalyzeAndProceed}
