                                                            newSecs[idx] = e.target.value;
                                                            setEditableSections(newSecs);
                                                        }}
                                                        className="flex-1 text-sm font-bold text-slate-700 bg-transparent outline-none focus:text-pink-600 focus:bg-pink-50/50 rounded px-1 -ml-1 transition-colors"
                                                    />
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => handleMoveSection(idx, -1)} className="p-1.5 hover:bg-slate-100 rounded text-slate-400 hover:text-slate-600" disabled={idx===0}><ChevronRight size={14} className="-rotate-90"/></button>
                                                <button onClick={() => handleMoveSection(idx, 1)} className="p-1.5 hover:bg-slate-100 rounded text-slate-400 hover:text-slate-600" disabled={idx===editableSections.length-1}><ChevronRight size={14} className="rotate-90"/></button>
                                                <div className="w-px h-4 bg-slate-200 mx-1"></div>
                                                <button onClick={() => removeSection(idx)} className="p-1.5 hover:bg-red-50 rounded text-slate-400 hover:text-red-500"><Trash2 size={14} /></button>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>

                            {/* Footer Actions - Fixed at bottom */}
                            <div className="p-6 border-t border-slate-100 bg-white shrink-0 z-10 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                                <div className="flex flex-col md:flex-row gap-4">
                                    <div className="flex-1 flex gap-2">
                                        <input 
                                            type="text" 
                                            value={newSectionName}
                                            onChange={(e) => setNewSectionName(e.target.value)}
                                            placeholder="Add new section title..."
                                            className="flex-1 border border-slate-300 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-pink-500 bg-slate-50 focus:bg-white transition-colors"
                                            onKeyDown={(e) => e.key === 'Enter' && addSection()}
                                        />
                                        <button onClick={addSection} className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl font-bold text-sm hover:bg-slate-200 border border-slate-200"><Plus size={18} /></button>
                                    </div>
                                    <button 
                                        onClick={goToWorkspace}
                                        className="flex items-center justify-center gap-2 bg-pink-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-pink-700 shadow-lg hover:shadow-pink-200 transition-all active:scale-95 whitespace-nowrap"
                                    >
