export const generateArchitectureDesign = async (context: string, type: string): Promise<DesignData> => {
    // 1. Retrieve Knowledge Base
    const relevantPatterns = retrieveRelevantPatterns(context);
    const knowledgeContext = relevantPatterns.length > 0 
        ? `\n\nAPPLY THESE PREVIOUSLY LEARNED PATTERNS:\n${relevantPatterns.join('\n')}\n` 
        : "";

    // 2. Solution Bundling Logic
    let bundlingInstruction = "";
    const lowerContext = (context + type).toLowerCase();

    // Check specifically for user-selected Integrated Solutions first
    if (type.includes('Integrated Governance Solution') || type.includes('DI + DQ + MDM + Gov')) {
        bundlingInstruction = `
        MANDATORY INTEGRATED BUNDLE (Governance Suite):
        The user explicitly selected an integrated solution. The design MUST represent a holistic Data Management Platform. 
        You MUST include specific nodes/layers for:
        1. Source System (Source Node)
        2. Data Integration / Ingestion (Process Node - e.g. "Cloud Data Integration")
        3. Data Quality Engine (Process Node - e.g. "Cloud Data Quality")
        4. Master Data Management Hub (Process Node - e.g. "MDM SaaS")
        5. Data Governance / Catalog (Process/Target Node - e.g. "Cloud Data Governance")
        6. Final Target (Target Node - e.g. "Snowflake")

        Ensure edges flow logically: Source -> DI -> DQ -> MDM -> Catalog -> Target.
        Do NOT merge these into one node. Show the flow of data through each component.
        `;
    } else if (type.includes('Integrated MDM Solution') || type.includes('DI + DQ + MDM')) {
        bundlingInstruction = `
        MANDATORY INTEGRATED BUNDLE (MDM Suite):
        The user explicitly selected an integrated MDM solution. An MDM solution is never standalone. 
        You MUST include:
        1. Source System (Source Node)
        2. Data Integration / ETL (Process Node - e.g. "Cloud Data Integration")
        3. Data Quality / Cleanse (Process Node - e.g. "Cloud Data Quality")
        4. MDM Hub (Process Node - e.g. "Master Data Management")
        5. Target System (Target Node)

        Ensure edges flow: Source -> DI -> DQ -> MDM -> Target.
        Do NOT merge these into one node. Show the distinct processing steps.
        `;
    } else if (lowerContext.includes('governance') || lowerContext.includes('catalog')) {
        // Fallback for generic text
        bundlingInstruction = `
        SUGGESTED BUNDLE (Governance):
        Consider including: DI -> DQ -> MDM -> Catalog/Target.
        `;
    } else if (lowerContext.includes('mdm') || lowerContext.includes('master data')) {
        // Fallback for generic text
        bundlingInstruction = `
        SUGGESTED BUNDLE (MDM):
        Consider including: DI -> DQ -> MDM -> Target.
        `;
    } else if (lowerContext.includes('quality') || lowerContext.includes('dq')) {
        bundlingInstruction = `
        SUGGESTED BUNDLE (Data Quality):
        Consider including: Source -> Profiling -> DI -> DQ -> Target.
        `;
    }

    const prompt = `
        Generate a High Level Design (Architecture Diagram) for: ${type}.
        Context: ${context}

        ${bundlingInstruction}
        ${knowledgeContext}

        Return nodes and edges for a flowchart/diagram.
        Nodes should have types: 'source', 'stage', 'process', 'target'.
        Ensure nodes have 'x' and 'y' coordinates for a flowchart layout (approx 0-800 width, 0-600 height).
    `;

    try {
        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        nodes: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    id: { type: Type.STRING },
                                    label: { type: Type.STRING },
                                    type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target', 'table'] },
                                    x: { type: Type.NUMBER },
                                    y: { type: Type.NUMBER },
                                    description: { type: Type.STRING }
                                },
                                required: ["id", "label", "type", "x", "y"]
                            }
                        },
                        edges: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    from: { type: Type.STRING },
                                    to: { type: Type.STRING },
                                    label: { type: Type.STRING }
                                },
                                required: ["from", "to", "label"]
                            }
                        }
                    },
                    required: ["nodes", "edges"]
                }
            }
        }));
        return safeJsonParse(response.text, { nodes: [], edges: [] });
    } catch (e) {
        console.error(e);
        return { nodes: [], edges: [] };
