export const generateSlideContent = async (slide: SlideStructure, projectContext: string): Promise<SlideContent> => {
    try {
        const prompt = `
            Act as a Consultant. Generate content for a PowerPoint slide.
            Slide Title: "${slide.title}"
            Slide Purpose: ${slide.description}

            Project Context: ${projectContext}

            Return JSON with:
            - 'bulletPoints': 3-5 punchy, professional bullet points for the slide body.
            - 'speakerNotes': A paragraph of text for the speaker to say.
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        bulletPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
                        speakerNotes: { type: Type.STRING }
                    },
                    required: ["bulletPoints", "speakerNotes"]
