const DocumentGenerator: React.FC<DocumentGeneratorProps> = ({ setHasUnsavedChanges, onNavigateToDashboard }) => {
    // Phase: 'setup' (Unified) -> 'structure' (Review) -> 'workspace' (Edit/View)
    const [phase, setPhase] = useState<'setup' | 'structure' | 'workspace'>('setup');

    // Setup State
    const [selectedTemplateId, setSelectedTemplateId] = useState<string>('hld');
    const [projectContext, setProjectContext] = useState('');
    const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);

    // Learning State
    const [isLearning, setIsLearning] = useState(false);
    const [customTemplate, setCustomTemplate] = useState<DocumentTemplate | null>(null);
    const [analysisError, setAnalysisError] = useState<string | null>(null);
    const learningTimeoutRef = useRef<any>(null);

    // Structure State
    const [editableSections, setEditableSections] = useState<string[]>([]);
    const [newSectionName, setNewSectionName] = useState("");

    // Workspace State
    const [generatedSections, setGeneratedSections] = useState<DocumentSection[]>([]);
    const [isGenerating, setIsGenerating] = useState(false);
    const [editContentBuffer, setEditContentBuffer] = useState("");
    const [editingSectionId, setEditingSectionId] = useState<string | null>(null); // For manual editing

    // Diagram State
    const [diagramType, setDiagramType] = useState<'architecture' | 'dataflow' | 'erd'>('architecture');
    const [archFlowDesign, setArchFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [dataFlowDesign, setDataFlowDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [erDesign, setErDesign] = useState<DesignData>({ nodes: [], edges: [] });
    const [isDiagramGenerating, setIsDiagramGenerating] = useState(false);
    const [activeWorkspaceTab, setActiveWorkspaceTab] = useState<'doc' | 'diagrams'>('doc');

    // History State
    const [showHistory, setShowHistory] = useState(false);
    const [historyItems, setHistoryItems] = useState<any[]>([]);

    useEffect(() => {
        // Initialize default sections
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === 'hld');
        if (t) setEditableSections([...t.sections]);
        setHistoryItems(getHistory('DocumentGenerator'));

        return () => {
            if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
        };
    }, []);

    // Watch for unsaved changes
    useEffect(() => {
        if (setHasUnsavedChanges) {
            // We do NOT flag dirty if generation is happening (isGenerating), 
            // allowing the user to switch modules in the sidebar without interruption.
            // We ONLY flag dirty if the user is in manual edit mode.
            const isDirty = editingSectionId !== null;
            setHasUnsavedChanges(isDirty);
        }
    }, [editingSectionId, setHasUnsavedChanges]);

    // --- HANDLERS: NAVIGATION ---
    const handleHomeClick = () => {
        if (onNavigateToDashboard) {
            if (isGenerating) {
                if (window.confirm("Document generation is currently active. Do you want to return to the Dashboard? The process will continue in the background.")) {
                    onNavigateToDashboard();
                }
            } else {
                onNavigateToDashboard();
            }
        }
    };

    // --- HANDLERS: SETUP & LEARNING ---

    const handleTemplateSelect = (id: string) => {
        setSelectedTemplateId(id);
        const t = DEFAULT_TEMPLATES.find(temp => temp.id === id);
        if (t) setEditableSections([...t.sections]);
        if (id === 'custom-learned' && customTemplate) setEditableSections([...customTemplate.sections]);
    };

    const readFileContent = (file: File): Promise<string> => {
        return new Promise((resolve) => {
            // Only attempt to read text-based files to avoid binary garbage
            if (file.name.match(/\.(txt|md|json|csv|xml|yml|yaml|html|js|ts|java|py|sql)$/i)) {
                const reader = new FileReader();
                reader.onload = (e) => resolve((e.target?.result as string) || "");
                reader.onerror = () => resolve(""); 
                reader.readAsText(file);
            } else {
                resolve(""); 
            }
        });
    };

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const files = Array.from(e.target.files) as File[];
            setUploadedFiles(prev => [...prev, ...files]);
        }
    };

    const removeFile = (index: number) => {
        setUploadedFiles(prev => prev.filter((_, i) => i !== index));
    };

    // Explicit function called when user clicks "Analyze & Continue"
    const handleAnalyzeAndProceed = async () => {
        // 1. If we have files, we MUST analyze them to get structure
        if (uploadedFiles.length > 0) {
            setIsLearning(true);
            setAnalysisError(null);

            // Safety Timeout
            if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
            learningTimeoutRef.current = setTimeout(() => {
                setIsLearning(false);
                setAnalysisError("Analysis timed out. Proceeding with default structure.");
                // Fallback to structure phase even on timeout
                setPhase('structure');
            }, 25000);

            try {
                let combinedContext = "";
                for (const file of uploadedFiles.slice(0, 3)) {
                    const content = await readFileContent(file);
                    if (content) {
                        combinedContext += `\n--- Content of ${file.name} ---\n${content.substring(0, 3000)}\n`;
                    } else {
                        combinedContext += `\n--- File: ${file.name} (Binary Format - Structure inferred from name) ---\n`;
                    }
                }

                const prompt = `Files uploaded: ${uploadedFiles.map(f => f.name).join(', ')}. \n\nDocument Content Snippets:\n${combinedContext}\n\nAnalyze these filenames and content context to infer the Table of Contents (Structure).`;

                const structure = await analyzeDocumentStructure(prompt);

                // Ensure we have a valid structure
                const finalStructure = structure && structure.length > 0 ? structure : DEFAULT_TEMPLATES[0].sections;

                const newTemplate = {
                    id: 'custom-learned',
                    name: 'Learned Structure',
                    description: `Based on ${uploadedFiles.length} uploaded file(s).`,
                    sections: finalStructure
                };
                setCustomTemplate(newTemplate);
                setSelectedTemplateId('custom-learned');
                setEditableSections(finalStructure);

            } catch (e) {
                console.error("Learning failed", e);
                setAnalysisError("Failed to analyze files. Using default template.");
            } finally {
                setIsLearning(false);
                if (learningTimeoutRef.current) clearTimeout(learningTimeoutRef.current);
                setPhase('structure'); // Proceed to next step
            }
        } else {
            // 2. No files, just proceed with selected template
            setPhase('structure');
        }
    };

    // --- HANDLERS: STRUCTURE ---

    const addSection = () => {
        if (newSectionName.trim()) {
            setEditableSections([...editableSections, newSectionName.trim()]);
            setNewSectionName("");
        }
    };

    const removeSection = (index: number) => {
        const newSections = [...editableSections];
        newSections.splice(index, 1);
        setEditableSections(newSections);
    };

    const handleMoveSection = (index: number, direction: -1 | 1) => {
        if (index + direction < 0 || index + direction >= editableSections.length) return;
        const newSections = [...editableSections];
        const temp = newSections[index];
        newSections[index] = newSections[index + direction];
        newSections[index + direction] = temp;
        setEditableSections(newSections);
    };

    const goToWorkspace = () => {
        if (editableSections.length === 0) {
            alert("Please ensure there is at least one section in the outline.");
            return;
        }

        // Initialize sections
        const initialSections: DocumentSection[] = editableSections.map((title, idx) => ({
            id: `sec-${idx}`,
            title,
            content: '',
            status: 'pending'
        }));
        setGeneratedSections(initialSections);
        setPhase('workspace');

        // Trigger Generation
        const context = projectContext + " " + uploadedFiles.map(f=>f.name).join(' ');
        generateSectionsParallel(initialSections, context);
        generateDiagrams(projectContext);

        if(setHasUnsavedChanges) setHasUnsavedChanges(false);
    };

    // --- HANDLERS: GENERATION ---

    const generateDiagrams = async (context: string) => {
        // Migration strategy typically doesn't need these diagrams according to requirements
        if (selectedTemplateId === 'migration') return;

        setIsDiagramGenerating(true);
        try {
            // HLD & LLD both get Architecture Flow
            if (selectedTemplateId === 'hld' || selectedTemplateId === 'lld') {
                const arch = await generateArchitectureDesign(context, "System Architecture");
                setArchFlowDesign(arch);
            }

            // LLD specifically gets Data Flow and ERD
            if (selectedTemplateId === 'lld') {
                const df = await generateProcessArchitecture(context, "Infer data flow and processing steps");
                setDataFlowDesign(df);

                const erd = await generateERD(context, "Infer database entity relationships");
                setErDesign(erd);
            }
        } catch (e) { 
            console.error(e); 
        } finally { 
            setIsDiagramGenerating(false); 
        }
    };

    const generateSectionsParallel = async (sections: DocumentSection[], context: string) => {
        const allHeaders = sections.map(s => s.title);
        setIsGenerating(true);

        const tasks = sections.map(async (section, index) => {
            // Stagger requests slightly to be gentle on rate limits
            await new Promise(r => setTimeout(r, index * 200)); 
            try {
                const content = await generateDocumentContent(section.title, context, allHeaders);
                setGeneratedSections(prev => prev.map(s => 
                    s.id === section.id ? { ...s, content, status: 'generated' } : s
                ));
            } catch (e) {
                console.error(`Error generating ${section.title}`, e);
                setGeneratedSections(prev => prev.map(s => 
                    s.id === section.id ? { ...s, content: "Generation failed. Please retry.", status: 'generated' } : s
                ));
            }
        });

        await Promise.all(tasks);
        setIsGenerating(false);

        // Save History when generation completes
        saveHistory('DocumentGenerator', projectContext.substring(0, 40) + '...', {
            context: projectContext,
            sections: sections, // Note: This might save before state update fully propogates if we use 'sections' arg, but it's okay for history summary
            archDesign: archFlowDesign,
            dataDesign: dataFlowDesign,
            erDesign: erDesign
        });
        setHistoryItems(getHistory('DocumentGenerator'));
    };

    const handleRegenerateSection = async (sectionId: string) => {
        const idx = generatedSections.findIndex(s => s.id === sectionId);
        if (idx === -1) return;

        // Set specific section to pending visual
        setGeneratedSections(prev => prev.map(s => s.id === sectionId ? { ...s, status: 'pending' } : s));
        setIsGenerating(true);

        const newContent = await generateDocumentContent(generatedSections[idx].title, projectContext, generatedSections.map(s => s.title));

        setGeneratedSections(prev => prev.map(s => s.id === sectionId ? { ...s, content: newContent, status: 'generated' } : s));
        setIsGenerating(false);
    };

    // --- HANDLERS: EDITING ---

    const startEditing = (section: DocumentSection) => {
        setEditingSectionId(section.id);
        setEditContentBuffer(section.content);
    };

    const saveEditing = () => {
        if (editingSectionId) {
            setGeneratedSections(prev => prev.map(s => s.id === editingSectionId ? { ...s, content: editContentBuffer, status: 'edited' } : s));
            setEditingSectionId(null);
        }
    };

    const handleRefineDiagram = async (prompt: string) => {
        setIsDiagramGenerating(true);
        try {
            if (diagramType === 'architecture') {
                const arch = await generateArchitectureDesign(projectContext, prompt);
                setArchFlowDesign(arch);
            } else if (diagramType === 'dataflow') {
                const data = await generateProcessArchitecture(projectContext, prompt);
                setDataFlowDesign(data);
            } else if (diagramType === 'erd') {
                const erd = await generateERD(projectContext, prompt);
                setErDesign(erd);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setIsDiagramGenerating(false);
        }
    };

    const exportToWord = () => {
        const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Export</title></head><body>`;
        const footer = "</body></html>";
        let bodyHTML = `<h1>Solution Document</h1><p><strong>Context:</strong> ${projectContext.substring(0, 200)}...</p><hr/>`;

        generatedSections.forEach(sec => {
            bodyHTML += `<h2>${sec.title}</h2><div>${sec.content.replace(/\n/g, '<br/>')}</div>`;

            // Highlight insertion points for diagrams
            if (selectedTemplateId === 'hld' && (sec.title.toLowerCase().includes('architecture') || sec.title.toLowerCase().includes('solution'))) {
                bodyHTML += `<br/><div style="border: 2px dashed #ccc; padding: 20px; text-align: center; color: #666; background-color: #f9f9f9;"><strong>[PLEASE INSERT ARCHITECTURE DIAGRAM IMAGE HERE]</strong><br/><i>(Export image from Architecture Lab tab)</i></div><br/>`;
            }
            if (selectedTemplateId === 'lld') {
                if (sec.title.toLowerCase().includes('architecture')) {
                    bodyHTML += `<br/><div style="border: 2px dashed #ccc; padding: 20px; text-align: center; color: #666; background-color: #f9f9f9;"><strong>[PLEASE INSERT ARCHITECTURE FLOW DIAGRAM HERE]</strong></div><br/>`;
                }
                if (sec.title.toLowerCase().includes('component') || sec.title.toLowerCase().includes('api')) {
                    bodyHTML += `<br/><div style="border: 2px dashed #ccc; padding: 20px; text-align: center; color: #666; background-color: #f9f9f9;"><strong>[PLEASE INSERT DATA FLOW DIAGRAM HERE]</strong></div><br/>`;
                }
                if (sec.title.toLowerCase().includes('data') || sec.title.toLowerCase().includes('schema') || sec.title.toLowerCase().includes('model')) {
                    bodyHTML += `<br/><div style="border: 2px dashed #ccc; padding: 20px; text-align: center; color: #666; background-color: #f9f9f9;"><strong>[PLEASE INSERT ER DIAGRAM HERE]</strong></div><br/>`;
                }
            }
            bodyHTML += `<br/>`;
        });
        const source = 'data:application/vnd.ms-word;charset=utf-8,' + encodeURIComponent(header + bodyHTML + footer);
        const link = document.createElement("a");
        link.href = source;
        link.download = `solution_${Date.now()}.doc`;
        link.click();
    };

    // --- HISTORY HANDLERS ---
    const loadHistoryItem = (item: any) => {
        const data = item.data;
        setProjectContext(data.context);
        setGeneratedSections(data.sections);
        if(data.archDesign) setArchFlowDesign(data.archDesign);
        if(data.dataDesign) setDataFlowDesign(data.dataDesign);
        if(data.erDesign) setErDesign(data.erDesign);
        setPhase('workspace');
        setShowHistory(false);
    };

    const handleDeleteHistory = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        deleteHistory(id);
        setHistoryItems(prev => prev.filter(h => h.id !== id));
    };

    // --- RENDER HELPERS ---
    const getProgressStep = () => {
        if (phase === 'setup') return 1;
        if (phase === 'structure') return 2;
        return 3;
    };

    const getCurrentDesign = () => {
        switch(diagramType) {
            case 'architecture': return archFlowDesign;
            case 'dataflow': return dataFlowDesign;
            case 'erd': return erDesign;
            default: return { nodes: [], edges: [] };
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 relative animate-fade-in overflow-hidden">

            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-20 shrink-0">
                <div className="flex items-center gap-4">
