export const analyzeDocumentStructure = async (filesContext: string): Promise<string[]> => {
    try {
        const prompt = `
            Act as an Expert Technical Writer and Solutions Architect.
            Analyze the provided input text/file summaries to reverse-engineer the Document Structure.

            **Knowledge Base / Pattern Recognition:**
            - If the content resembles a **High-Level Design (HLD)**, look for: Executive Summary, Solution Overview, Logical Architecture, Technology Stack, Security, Infrastructure.
            - If the content resembles a **Low-Level Design (LLD)**, look for: Component Specifications, Class Diagrams, API Contracts, Database Schema, Error Handling.
            - If the content resembles a **Migration Plan**, look for: Discovery, Migration Strategy (Rehost/Refactor), Roadmap, Rollback Plan, Testing & Validation.

            **Task:**
            1. Identify the *type* of document implied by the content or explicitly mentioned.
            2. Extract the likely **Table of Contents (Section Headers)**.
            3. If the input is unstructured notes, propose a *standard industry structure* (TOGAF or AWS Well-Architected) that fits the content best.
            4. Return a clean JSON array of strings for the Section Titles. Do not include sub-sections (e.g. 1.1), just top-level chapters.

            Documents Content/Summary: ${filesContext.substring(0, 15000)}
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING }
                }
            }
        }));
        return safeJsonParse(response.text, ["Executive Summary", "Solution Architecture", "Data Flow", "Security & Compliance", "Deployment Strategy"]);
    } catch (e) {
        return ["Executive Summary", "Solution Architecture", "Data Flow", "Security & Compliance", "Deployment Strategy"];
    }
};

