import React, { useState, useEffect, useRef } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Loader, 
  Sparkles, 
  ArrowRight,
  RefreshCw,
  Trash2,
  Network,
  ArrowRightCircle,
  Table,
  Pencil,
  ChevronRight,
  History,
  XCircle,
