                            <button onClick={(e) => { e.stopPropagation(); deleteHistory(h.id); setHistoryItems(prev => prev.filter(x => x.id !== h.id)); }} className="text-slate-400 hover:text-red-500"><Trash2 size={14}/></button>
                        </div>
