export interface DocumentStrategy {
    type: 'hld' | 'lld' | 'migration' | 'replica';
    title: string;
    reasoning: string;
    sections: string[];
    diagramMode: 'none' | 'architecture_only' | 'full'; 
}

export const determineDocumentStrategy = async (prompt: string, filesContext: string): Promise<DocumentStrategy | null> => {
    try {
        const aiPrompt = `
            Act as a Principal Solution Architect. Analyze the User's Request and the attached File Context.
            Determine the best Document Strategy.

            USER REQUEST: "${prompt}"
            FILE CONTEXT: "${filesContext.substring(0, 10000)}"

            RULES:
            1. **'replica' (LLD / Scan & Report)**: If the user says "scan the file", "generate a report of it", or asks for an LLD/Low Level Design based on the file.
               - STRATEGY: Replicate the file's structure 1:1. Do not invent new sections.
               - DIAGRAM MODE: 'full' (Show all diagram types found or implied).

            2. **'hld' (High Level Design)**: If the user asks for "HLD", "Architecture", or "Strategic Overview".
               - STRATEGY: Use standard HLD structure (Executive Summary, Architecture, Tech Stack, Security). Generate content based on input + AI Knowledge.
               - DIAGRAM MODE: 'architecture_only' (Only the high-level flow).

            3. **'migration' (Migration Strategy)**: If the user asks for "Migration Plan", "Move to Cloud", etc.
               - STRATEGY: Use standard Migration structure (Discovery, Assessment, Strategy, Roadmap, Cutover).
               - DIAGRAM MODE: 'none' (Strictly text-based plan, as per requirements).

            Output JSON:
            {
                "type": "hld" | "lld" | "migration" | "replica",
                "title": "Document Title",
                "reasoning": "Explanation...",
                "sections": ["Section 1", "Section 2", ...],
                "diagramMode": "none" | "architecture_only" | "full"
            }
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: aiPrompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        type: { type: Type.STRING, enum: ['hld', 'lld', 'migration', 'replica'] },
                        title: { type: Type.STRING },
                        reasoning: { type: Type.STRING },
                        sections: { type: Type.ARRAY, items: { type: Type.STRING } },
                        diagramMode: { type: Type.STRING, enum: ['none', 'architecture_only', 'full'] }
                    },
                    required: ["type", "title", "reasoning", "sections", "diagramMode"]
                }
            }
        }));

        return safeJsonParse(response.text, null);
    } catch (e) {
        console.error("Strategy determination failed", e);
        return {
            type: 'hld',
            title: 'Solution Document',
            reasoning: 'Fallback due to error',
            sections: ['Executive Summary', 'Solution Architecture'],
            diagramMode: 'architecture_only'
        };
    }
};

export const generateDocumentContent = async (section: string, projectContext: string, strategyType: string): Promise<string> => {
    try {
        let prompt = "";
        if (strategyType === 'replica' || strategyType === 'lld') {
            prompt = `
                Act as a Technical Documentation Specialist.
                You are strictly REPLICATING or EXTRACTING content for the section: "**${section}**" from the provided input context.

                Input Context: ${projectContext}

                - Do NOT invent new features.
                - Extract specific details, tables, APIs, schemas, or logic mentioned in the text for this section.
                - If the input context is missing details for this section, state "No information provided in source documents."
                - Format nicely in Markdown.
            `;
        } else if (strategyType === 'migration') {
            prompt = `
                Act as a Cloud Migration Architect.
                Generate a strategic, robust migration plan section: "**${section}**".

                Context: ${projectContext}

                - Apply industry best practices (Discovery -> Assess -> Migrate -> Validate).
                - Focus on risk mitigation, rollback plans, and data integrity.
                - Use professional, authoritative language.
            `;
        } else {
            // HLD / Default
            prompt = `
                Act as a Solution Architect.
                Generate a high-level, strategic description for: "**${section}**".

                Context: ${projectContext}

                - Focus on "Why" and "What".
                - Synthesize the input into a cohesive solution narrative.
            `;
        }

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 2048 } 
            }
        }));

        return response.text || "Content generation failed.";
    } catch (e) {
        return "Error generating section content.";
    }
};

