                     className={`flex items-center gap-2 px-4 py-3 border-b-2 text-sm font-medium transition-colors whitespace-nowrap ${activeSubTab === tab.id ? 'border-indigo-600 text-indigo-700 bg-indigo-50/50' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                   >
                     <tab.icon size={16} />
                     {tab.label}
                     {loadingMap[tab.id] && <Loader size={12} className="animate-spin text-slate-400" />}
                   </button>
