  // Tabs: 'dashboard' | 'design-module' | 'design' | 'doc-generator' | 'case-story' | 'adhoc-estimator' | 'adhoc-architecture' | 'adhoc-dataflow' | 'adhoc-dq' | 'adhoc-er' | 'project-describer' | 'adhoc-dictionary'
  const [activeTab, setActiveTab] = useState('dashboard');

  const [selectedRequest, setSelectedRequest] = useState<RequestData | null>(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [designCache, setDesignCache] = useState<DesignCache>({});
  const [showGuide, setShowGuide] = useState(false);

  // Navigation Guard State
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [showNavigationAlert, setShowNavigationAlert] = useState(false);
  const [pendingTab, setPendingTab] = useState<string | null>(null);

  // User Profile State
  const [showProfile, setShowProfile] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile>({
    name: 'Alex Architect',
    email: 'alex.arch@data.inc',
    role: 'Senior Solution Architect',
    preferences: {
      defaultProduct: '',
      defaultDeployment: 'Cloud'
    }
  });

  // Mock Data
  const [requests, setRequests] = useState<RequestData[]>([
    {
      id: 'REQ-1005',
      clientName: 'HealthCare Plus',
      product: 'Databricks',
      deploymentModel: 'Cloud',
      type: 'Unity Catalog',
      rfpFiles: ['lakehouse_governance_rfp.pdf', 'hipaa_compliance.docx'],
