    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  // Safe Navigation Handler
  const handleSwitchTab = (tab: string) => {
      if (hasUnsavedChanges) {
          setPendingTab(tab);
          setShowNavigationAlert(true);
      } else {
          setActiveTab(tab);
      }
  };

  const confirmNavigation = () => {
      if (pendingTab) {
          setActiveTab(pendingTab);
          setHasUnsavedChanges(false);
          setShowNavigationAlert(false);
          setPendingTab(null);
      }
  };

  const cancelNavigation = () => {
      setShowNavigationAlert(false);
      setPendingTab(null);
  };

  const handleCreateSubmit = (newRequest: any) => {
    const requestWithId: RequestData = {
      ...newRequest,
      id: `REQ-${nextId}`,
      status: 'Not Started'
    };
    setRequests([requestWithId, ...requests]);
    setNextId(prev => prev + 1);

    // Auto-redirect to design view for the new request
    setSelectedRequest(requestWithId);
    setActiveTab('design');
    setHasUnsavedChanges(false); // Reset dirty flag after creation
  };

  const handleSelectRequest = (req: RequestData) => {
    // Check for unsaved changes before switching contexts
    if (hasUnsavedChanges) {
        // Simple alert for intra-dashboard switches for now, or assume this is handled by tab switching if view changes
        if(!confirm("You have unsaved changes. Discard them?")) return;
        setHasUnsavedChanges(false);
    }
    setSelectedRequest(req);
    setActiveTab('design');
  };

  const handleDeleteRequest = (id: string) => {
    if (confirm("Are you sure you want to delete this request?")) {
        setRequests(prev => prev.filter(r => r.id !== id));
        if (selectedRequest?.id === id) {
            setSelectedRequest(null);
            setActiveTab('design-module');
        }
    }
  };

  const handleUpdateDesignCache = (reqId: string, designData: any) => {
    setDesignCache(prev => ({
      ...prev,
      [reqId]: designData
