            {activeSubTab === 'scoping' && (
                <div className="p-8 max-w-6xl mx-auto animate-fade-in">
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><ClipboardList className="text-orange-500" /> Scoping & Discovery</h3>
                        {loadingMap.scoping ? (
                            <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                <Loader size={24} className="animate-spin mb-4 text-orange-500" />
                                <p>AI is generating questionnaire...</p>
