                </div>
                <div>
                    <h3 className="text-2xl font-bold text-slate-900 mb-2">{status === 'thinking' ? 'Analyzing Request' : 'Awaiting Analysis'}</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">
                        {status === 'thinking' 
                           ? "The AI is processing your requirements to generate the solution design." 
                           : error || "To generate architecture blueprints, cost estimates, and technical requirements, the AI needs to process your request context first."}
                    </p>
                </div>
                {status !== 'thinking' && (
                    <button
                        onClick={() => handleGenerate(null, request.mode || 'design')}
                        className={`w-full text-white font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 hover:scale-[1.02] ${error ? 'bg-red-600 hover:bg-red-700' : 'bg-slate-900 hover:bg-indigo-600'}`}
                    >
                        {error ? <RefreshCw size={18} /> : <Sparkles size={18} />}
                        {error ? 'Retry Analysis' : 'Start Research'}
                    </button>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

