      case 'adhoc-dq': return 'Data Quality Studio';
      case 'adhoc-er': return 'ER Diagram Generator';
      case 'adhoc-dictionary': return 'Data Dictionary Generator';
      default: return 'DataArch AI Platform';
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden relative">

      {/* Global Navigation Alert Modal */}
      {showNavigationAlert && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in p-4">
              <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 relative border border-slate-200">
                  <div className="flex items-center gap-3 text-red-600 mb-4">
                      <div className="p-2 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
                      <h3 className="text-lg font-bold">Unsaved Changes</h3>
                  </div>
                  <p className="text-slate-600 text-sm mb-6 leading-relaxed">
                      You have unsaved work in progress. If you navigate away now, your current changes will be lost.
                  </p>
                  <div className="flex gap-3 justify-end">
                      <button 
                          onClick={cancelNavigation} 
                          className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg text-sm transition-colors"
                      >
                          Continue Editing
                      </button>
                      <button 
                          onClick={confirmNavigation} 
                          className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-bold rounded-lg text-sm transition-colors shadow-md"
                      >
                          Discard & Leave
                      </button>
                  </div>
              </div>
          </div>
      )}

      <Sidebar 
        activeTab={activeTab === 'design' ? 'design-module' : activeTab} 
        setActiveTab={setActiveTab} // Keeping for internal simple switches if needed
        handleSwitchTab={handleSwitchTab} // Use this for protected switches
        isMobileOpen={isMobileOpen}
