  }, []);

  const loadProjects = () => {
    const history = getHistory('Describer');
    const mapped: DescriberProject[] = history.map(h => ({
        id: h.id,
        title: h.data.title || h.summary.split('...')[0], // Fallback if title wasn't saved in older versions
        date: h.date,
        summary: h.summary,
        context: h.data.context || '',
        files: h.files || [],
        result: h.data.data
    }));
    setProjects(mapped);
  };

  // --- UTILS ---
  const extractTextFromDocx = async (file: File): Promise<string> => {
      if (!window.mammoth) return "[Error: Mammoth.js library not found]";
      try {
          const arrayBuffer = await file.arrayBuffer();
          const result = await window.mammoth.extractRawText({ arrayBuffer });
          return result.value || "[Empty DOCX]";
      } catch (e) {
          return `[Error parsing DOCX: ${file.name}]`;
      }
  };

  const extractTextFromPdf = async (file: File): Promise<string> => {
      if (!window.pdfjsLib) return "[Error: PDF.js library not found]";
      try {
          const arrayBuffer = await file.arrayBuffer();
          const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;
          let fullText = "";
          for (let i = 1; i <= pdf.numPages; i++) {
              const page = await pdf.getPage(i);
              const textContent = await page.getTextContent();
              const pageText = textContent.items.map((item: any) => item.str).join(' ');
              fullText += `[Page ${i}]\n${pageText}\n\n`;
          }
          return fullText || "[Empty PDF]";
      } catch (e) {
          return `[Error parsing PDF: ${file.name}]`;
      }
  };

  const processFiles = async (files: File[]) => {
      let allContent = "";
      for(const file of files) {
          const name = file.name.toLowerCase();
          let content = "";
          if (name.endsWith('.docx')) content = await extractTextFromDocx(file);
          else if (name.endsWith('.pdf')) content = await extractTextFromPdf(file);
          else {
              content = await new Promise<string>((resolve) => {
                  const reader = new FileReader();
                  reader.onload = (e) => resolve((e.target?.result as string) || "");
                  reader.readAsText(file);
              });
          }
          allContent += `\n--- File: ${file.name} ---\n${content}\n`;
      }
      return allContent;
  };

  const handleCreate = async () => {
    if (!formData.context.trim() && uploadedFiles.length === 0) return;

    setIsGenerating(true);
    setThoughtLog([]);

    // Simulation thoughts
    const thoughts = ["Ingesting documents...", "Extracting key entities...", "Analyzing technical constraints...", "Synthesizing executive summary..."];
    let tIndex = 0;
    const tInterval = setInterval(() => {
        if(tIndex < thoughts.length) {
            setThoughtLog(prev => [...prev, thoughts[tIndex]]);
            tIndex++;
        }
    }, 1200);

    try {
      const fileContext = await processFiles(uploadedFiles);
      const fullContext = (formData.context + "\n" + fileContext).trim();
      const finalTitle = formData.title || `Analysis ${new Date().toLocaleDateString()}`;

      const result = await generateProjectUnderstanding(fullContext);

      // Save
      const fileNames = uploadedFiles.map(f => f.name);
      saveHistory('Describer', finalTitle, { 
          title: finalTitle,
          context: fullContext,
          data: result 
      }, fileNames);

      loadProjects(); // Refresh list

      // Set active and switch view
      const newProject: DescriberProject = {
          id: Date.now().toString(), // Temp ID until reload
          title: finalTitle,
          date: new Date().toLocaleDateString(),
          summary: finalTitle,
          context: fullContext,
          files: fileNames,
          result: result
      };
      setActiveProject(newProject);
      setView('detail');

      // Reset Form
      setFormData({ title: '', context: '' });
      setUploadedFiles([]);

    } catch (e) {
      console.error(e);
      alert("Analysis failed. Please try again.");
    } finally {
      clearInterval(tInterval);
      setIsGenerating(false);
    }
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(window.confirm("Delete this analysis?")) {
          deleteHistory(id);
          loadProjects();
          if (activeProject?.id === id) {
              setActiveProject(null);
              setView('hub');
          }
      }
  };

  // --- VIEWS ---

  const HubView = () => {
      const filtered = projects.filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()));

      return (
          <div className="p-8 max-w-7xl mx-auto space-y-8 animate-fade-in">
              {/* Header */}
              <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
                  <div>
                      <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Project Intelligence Hub</h2>
                      <p className="text-slate-500 mt-1">AI-powered analysis of RFPs, requirements, and technical specifications.</p>
