                  <button onClick={() => setView('create')} className="flex items-center gap-2 px-5 py-2.5 bg-teal-600 text-white rounded-xl font-bold shadow-lg hover:bg-teal-700 transition-all hover:scale-105 active:scale-95">
                      <Plus size={18} /> New Analysis
