                      className="flex-1 outline-none text-sm text-slate-700"
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                  />
              </div>

              {/* Grid */}
              {filtered.length === 0 ? (
                  <div className="text-center py-20 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                      <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-slate-400"><Search size={24}/></div>
                      <h3 className="text-slate-600 font-bold">No projects found</h3>
                      <p className="text-slate-400 text-sm">Start a new analysis to see insights here.</p>
                  </div>
              ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {filtered.map(project => (
