                                  <div className="w-10 h-10 rounded-lg bg-teal-50 text-teal-600 flex items-center justify-center border border-teal-100">
                                      <BrainCircuit size={20} />
                                  </div>
                                  <div className="flex gap-2">
                                      <span className="text-[10px] font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded border border-slate-100">{project.date}</span>
