          {/* AI Side Panel */}
          <div className="hidden lg:flex w-[400px] bg-teal-900 text-white flex-col p-10 justify-center relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10"></div>
