export const generateArchitectureDesign = async (context: string, type: string): Promise<DesignData> => {
    const relevantPatterns = retrieveRelevantPatterns(context);
    const knowledgeContext = relevantPatterns.length > 0 
        ? `\n\nAPPLY THESE PREVIOUSLY LEARNED PATTERNS:\n${relevantPatterns.join('\n')}\n` 
        : "";

    let bundlingInstruction = "";
    if (type.includes('Integrated Governance Solution') || type.includes('DI + DQ + MDM + Gov')) {
        bundlingInstruction = `MANDATORY INTEGRATED BUNDLE: Source -> DI -> DQ -> MDM -> Catalog -> Target.`;
    } else if (type.includes('Integrated MDM Solution') || type.includes('DI + DQ + MDM')) {
        bundlingInstruction = `MANDATORY INTEGRATED BUNDLE: Source -> DI -> DQ -> MDM -> Target.`;
    }

    const prompt = `
        Generate a High Level Design (Architecture Diagram) for: ${type}.
        Context: ${context}
        ${bundlingInstruction}
        ${knowledgeContext}
        Return nodes and edges for a flowchart/diagram.
        Nodes types: 'source', 'stage', 'process', 'target', 'table'.
    `;

    const schema = {
        type: Type.OBJECT,
        properties: {
            nodes: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: {
                        id: { type: Type.STRING },
                        label: { type: Type.STRING },
                        type: { type: Type.STRING, enum: ['source', 'stage', 'process', 'target', 'table'] },
                        x: { type: Type.NUMBER },
                        y: { type: Type.NUMBER },
                        description: { type: Type.STRING }
                    },
                    required: ["id", "label", "type", "x", "y"]
                }
            },
            edges: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: {
                        from: { type: Type.STRING },
                        to: { type: Type.STRING },
                        label: { type: Type.STRING }
                    },
                    required: ["from", "to", "label"]
                }
            }
        },
        required: ["nodes", "edges"]
    };

    try {
        // Use Gemini 2.5 Flash for reliable, fast JSON generation
        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { responseMimeType: "application/json", responseSchema: schema }
        }));
        return safeJsonParse(response.text, { nodes: [], edges: [] });
    } catch (e) {
        console.error("Architecture generation failed", e);
        // Return a basic fallback graph to ensure UI doesn't break
        return { 
            nodes: [
                { id: "src", label: "Source System", type: "source", x: 0, y: 100, description: "External data source" },
                { id: "tgt", label: "Target System", type: "target", x: 400, y: 100, description: "Data destination" }
            ], 
            edges: [
                { from: "src", to: "tgt", label: "Data Flow" }
            ] 
        };
    }
};

