export const determineDocumentStrategy = async (prompt: string, filesContext: string): Promise<DocumentStrategy | null> => {
    try {
        const aiPrompt = `
            Act as a Principal Solution Architect. Analyze the User's Request and the attached File Context.
            Determine the best Document Strategy.

            USER REQUEST: "${prompt}"
            FILE CONTEXT: "${filesContext.substring(0, 10000)}"

            Output JSON:
            {
                "type": "hld" | "lld" | "migration" | "replica",
                "title": "Document Title",
                "reasoning": "Explanation...",
                "sections": ["Section 1", "Section 2", ...],
                "diagramMode": "none" | "architecture_only" | "full"
            }
        `;

        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: aiPrompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        type: { type: Type.STRING, enum: ['hld', 'lld', 'migration', 'replica'] },
                        title: { type: Type.STRING },
                        reasoning: { type: Type.STRING },
                        sections: { type: Type.ARRAY, items: { type: Type.STRING } },
                        diagramMode: { type: Type.STRING, enum: ['none', 'architecture_only', 'full'] }
                    },
                    required: ["type", "title", "reasoning", "sections", "diagramMode"]
                }
            }
        }));

        return safeJsonParse(response.text, null);
    } catch (e) {
        console.error("Strategy determination failed", e);
        return {
            type: 'hld',
            title: 'Solution Document',
            reasoning: 'Fallback due to error',
            sections: ['Executive Summary', 'Solution Architecture'],
            diagramMode: 'architecture_only'
        };
    }
};

