                              <h4 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 flex items-center gap-2">
                                  <Cpu size={16} className="text-purple-500"/> Implicit Requirements
                              </h4>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                  {(result.implicitRequirements || []).map((req, i) => (
                                      <div key={i} className="flex items-start gap-3 text-sm text-slate-600 bg-slate-50 p-3 rounded-lg border border-slate-100">
                                          <CheckCircle2 size={16} className="text-purple-500 shrink-0 mt-0.5"/>
                                          {req}
