import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  FileText, 
  UploadCloud, 
  Sparkles, 
  Loader, 
  ArrowRight, 
  BookOpen, 
  Info, 
  X, 
  History, 
  Trash2, 
  CheckCircle2, 
  BrainCircuit, 
  Target, 
  Layers, 
  AlertOctagon, 
  Eye, 
  Cpu,
  Plus,
  LayoutGrid,
  List as ListIcon,
  Search,
  Clock,
  ArrowLeft,
  Calendar,
  MessageSquare,
  Send,
  RefreshCw,
  Wand2,
  AlertCircle,
  MoreHorizontal,
  ChevronRight,
  Eraser,
  Home
} from 'lucide-react';
import { generateProjectUnderstanding, saveHistory, getHistory, deleteHistory } from '../services/geminiService';
import { ProjectDescriptionResponse } from '../types';

declare global {
  interface Window {
    mammoth: any;
    pdfjsLib: any;
  }
}

interface DescriberProject {
  id: string;
  title: string;
  date: string;
  summary: string; // Short text for card
  context: string;
  files: string[];
  result: ProjectDescriptionResponse;
}

const ProjectDescriber: React.FC = () => {
  // Navigation State
  const [view, setView] = useState<'hub' | 'create' | 'detail'>('hub');
  const [activeProject, setActiveProject] = useState<DescriberProject | null>(null);

  // Data State
  const [projects, setProjects] = useState<DescriberProject[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  // Create Form State
  const [formData, setFormData] = useState({ title: '', context: '' });
  const [nameError, setNameError] = useState<string | null>(null);
  const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [thoughtLog, setThoughtLog] = useState<string[]>([]);

  // Refinement State
  const [refinementInput, setRefinementInput] = useState('');
  const [isRefining, setIsRefining] = useState(false);

  // Load History on Mount
  useEffect(() => {
    loadProjects();
  }, []);

  const loadProjects = () => {
    const history = getHistory('Describer') || [];
    const mapped: DescriberProject[] = history.map(h => ({
        id: h.id,
        title: h.data?.title || h.summary?.split('...')[0] || 'Untitled Analysis',
        date: h.date,
        summary: h.summary || '',
        context: h.data?.context || '',
        files: h.files || [],
        result: h.data?.data || {} 
    }));
    setProjects(mapped);
  };

  // --- STRING SIMILARITY ALGORITHM (Levenshtein based similarity) ---
  const calculateSimilarity = (str1: string, str2: string): number => {
      const s1 = str1.toLowerCase().trim();
      const s2 = str2.toLowerCase().trim();
      if (!s1 || !s2) return 0;

      const len1 = s1.length;
      const len2 = s2.length;
      const maxLen = Math.max(len1, len2);

      if (maxLen === 0) return 1.0;

      const matrix: number[][] = [];
      for (let i = 0; i <= len2; i++) {
          matrix[i] = [i];
      }
      for (let j = 0; j <= len1; j++) {
          matrix[0][j] = j;
      }
      for (let i = 1; i <= len2; i++) {
          for (let j = 1; j <= len1; j++) {
              if (s2.charAt(i - 1) === s1.charAt(j - 1)) {
                  matrix[i][j] = matrix[i - 1][j - 1];
              } else {
                  matrix[i][j] = Math.min(
                      matrix[i - 1][j - 1] + 1,
                      Math.min(matrix[i][j - 1] + 1, matrix[i - 1][j] + 1)
                  );
              }
          }
      }
      const distance = matrix[len2][len1];
      return 1.0 - (distance / maxLen);
  };

  const validateProjectName = (name: string) => {
      if (!name.trim()) {
          setNameError("Project Name is mandatory.");
          return false;
      }

      // Check Exact Match
      const exactMatch = projects.find(p => p.title.toLowerCase() === name.toLowerCase());
      if (exactMatch) {
          setNameError("Project name already exists. Please choose a unique name.");
          return false;
      }

      // Check Similarity (> 40%)
      const similarProject = projects.find(p => calculateSimilarity(p.title, name) > 0.4);
      if (similarProject) {
          setNameError(`Name is too similar to existing project "${similarProject.title}". Please ensure uniqueness.`);
          return false;
      }

      setNameError(null);
      return true;
  };

  // --- UTILS ---
  const extractTextFromDocx = async (file: File): Promise<string> => {
      if (!window.mammoth) return "[Error: Mammoth.js library not found]";
      try {
          const arrayBuffer = await file.arrayBuffer();
          const result = await window.mammoth.extractRawText({ arrayBuffer });
          return result.value || "[Empty DOCX]";
      } catch (e) {
          return `[Error parsing DOCX: ${file.name}]`;
      }
  };

  const extractTextFromPdf = async (file: File): Promise<string> => {
      if (!window.pdfjsLib) return "[Error: PDF.js library not found]";
      try {
          const arrayBuffer = await file.arrayBuffer();
          const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;
          let fullText = "";
          for (let i = 1; i <= pdf.numPages; i++) {
              const page = await pdf.getPage(i);
              const textContent = await page.getTextContent();
              const pageText = textContent.items.map((item: any) => item.str).join(' ');
              fullText += `[Page ${i}]\n${pageText}\n\n`;
          }
          return fullText || "[Empty PDF]";
      } catch (e) {
          return `[Error parsing PDF: ${file.name}]`;
      }
  };

  const processFiles = async (files: File[]) => {
      let allContent = "";
      for(const file of files) {
          const name = file.name.toLowerCase();
          let content = "";
          if (name.endsWith('.docx')) content = await extractTextFromDocx(file);
          else if (name.endsWith('.pdf')) content = await extractTextFromPdf(file);
          else {
              content = await new Promise<string>((resolve) => {
                  const reader = new FileReader();
                  reader.onload = (e) => resolve((e.target?.result as string) || "");
                  reader.readAsText(file);
              });
          }
          allContent += `\n--- File: ${file.name} ---\n${content}\n`;
      }
      return allContent;
  };

  // --- ACTIONS ---

  const simulateThoughts = (type: 'initial' | 'refinement') => {
      setThoughtLog([]);
      const initialThoughts = ["Scanning document structure...", "Identifying critical requirements...", "Validating technical constraints...", "Synthesizing executive brief..."];
      const refinementThoughts = ["Processing user feedback...", "Re-evaluating context...", "Adjusting architectural focus...", "Regenerating insights..."];

      const thoughts = type === 'initial' ? initialThoughts : refinementThoughts;
      let tIndex = 0;

      // Clear any existing log first
      setThoughtLog([thoughts[0]]);

      const tInterval = setInterval(() => {
          tIndex++;
          if(tIndex < thoughts.length) {
              setThoughtLog(prev => [...prev, thoughts[tIndex]]);
          } else {
              clearInterval(tInterval);
          }
      }, 600);
      return tInterval;
  };

  const handleCreate = async () => {
    // 1. Validate Form Basics
    if ((!formData.context.trim() && uploadedFiles.length === 0)) return;

    // 2. Validate Name
    if (!validateProjectName(formData.title)) return;

    setIsGenerating(true);
    const tInterval = simulateThoughts('initial');

    try {
      const fileContext = await processFiles(uploadedFiles);
      const fullContext = (formData.context + "\n" + fileContext).trim();
      const finalTitle = formData.title; // Already validated

      const result = await generateProjectUnderstanding(fullContext);

      // Save
      const fileNames = uploadedFiles.map(f => f.name);
      saveHistory('Describer', finalTitle, { 
          title: finalTitle,
          context: fullContext,
          data: result 
      }, fileNames);

      loadProjects(); // Refresh list

      // Set active and switch view
      const newProject: DescriberProject = {
          id: Date.now().toString(), // Temp ID until reload
          title: finalTitle,
          date: new Date().toLocaleDateString(),
          summary: finalTitle,
          context: fullContext,
          files: fileNames,
          result: result
      };
      setActiveProject(newProject);
      setView('detail');

      // Reset Form
      setFormData({ title: '', context: '' });
      setUploadedFiles([]);
      setNameError(null);

    } catch (e) {
      console.error(e);
      alert("Analysis failed. Please try again.");
    } finally {
      clearInterval(tInterval);
      setIsGenerating(false);
    }
  };

  const handleRefine = async () => {
      if (!activeProject || !refinementInput.trim()) return;

      setIsRefining(true);
      const tInterval = simulateThoughts('refinement');

      try {
          // Append user feedback to the ORIGINAL context to maintain purity
          const refinedContext = `${activeProject.context}\n\n--- REFINEMENT REQUEST ---\nUser Feedback: ${refinementInput}\nInstruction: Regenerate the analysis strictly incorporating the above user feedback/context.`;

          const result = await generateProjectUnderstanding(refinedContext);

          // Update active project locally
          const updatedProject = { ...activeProject, result };
          setActiveProject(updatedProject);

          // Update History
          saveHistory('Describer', activeProject.title, { 
              title: activeProject.title,
              context: activeProject.context, 
              data: result 
          }, activeProject.files);

          loadProjects();
          setRefinementInput(''); // Clear input

      } catch (e) {
          console.error(e);
          alert("Refinement failed. Please try again.");
      } finally {
          clearInterval(tInterval);
          setIsRefining(false);
      }
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(window.confirm("Delete this analysis?")) {
          deleteHistory(id);
          loadProjects();
          if (activeProject?.id === id) {
              setActiveProject(null);
              setView('hub');
          }
      }
  };

  const handleClearAll = () => {
      if(window.confirm("Are you sure you want to remove ALL existing requests? This cannot be undone.")) {
          localStorage.removeItem('history_Describer');
          setProjects([]);
      }
  };

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData({...formData, title: val});
      if (val.trim()) {
          setNameError(null);
      }
  };

  // --- RENDER HELPERS ---

  const renderHubView = () => {
      const filtered = projects.filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()));

      return (
          <div className="p-8 max-w-7xl mx-auto space-y-8 animate-fade-in">
              {/* Header */}
              <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
                  <div>
                      <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Project Intelligence Hub</h2>
                      <p className="text-slate-500 mt-1">AI-powered analysis of RFPs, requirements, and technical specifications.</p>
                  </div>
                  <div className="flex gap-3">
                      {projects.length > 0 && (
                          <button onClick={handleClearAll} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-red-500 font-bold text-xs rounded-xl hover:bg-red-50 transition-colors">
                              <Eraser size={14}/> Clear History
                          </button>
                      )}
                  </div>
              </div>

              {/* Stats Bar */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
                      <div>
                          <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Analyses</div>
                          <div className="text-3xl font-bold text-slate-800">{projects.length}</div>
                      </div>
                      <div className="p-3 bg-teal-50 text-teal-600 rounded-xl"><BookOpen size={24}/></div>
                  </div>
                  <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
                      <div>
                          <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Documents Processed</div>
                          <div className="text-3xl font-bold text-slate-800">{projects.reduce((acc, p) => acc + (p.files?.length || 0), 0)}</div>
                      </div>
                      <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><FileText size={24}/></div>
                  </div>
                  <div className="bg-gradient-to-r from-teal-600 to-emerald-600 p-6 rounded-2xl shadow-lg text-white relative overflow-hidden group cursor-pointer" onClick={() => setView('create')}>
                      <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><BrainCircuit size={80}/></div>
                      <div className="relative z-10">
                          <h3 className="font-bold text-lg mb-1">Start Deep Analysis</h3>
                          <p className="text-teal-100 text-xs">Analyze new requirements</p>
                      </div>
                  </div>
              </div>

              {/* Filters */}
              <div className="flex items-center gap-4 bg-white p-2 rounded-xl border border-slate-200 shadow-sm">
                  <Search className="text-slate-400 ml-2" size={18} />
                  <input 
                      type="text" 
                      placeholder="Search projects..." 
                      className="flex-1 outline-none text-sm text-slate-700"
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                  />
              </div>

              {/* Grid */}
              {filtered.length === 0 ? (
                  <div className="text-center py-20 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                      <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-slate-400"><Search size={24}/></div>
                      <h3 className="text-slate-600 font-bold">No projects found</h3>
                      <p className="text-slate-400 text-sm">Start a new analysis to see insights here.</p>
                  </div>
              ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {filtered.map(project => (
                          <div 
                              key={project.id} 
                              onClick={() => { setActiveProject(project); setView('detail'); }}
                              className="bg-white p-6 rounded-2xl border border-slate-200 hover:border-teal-400 hover:shadow-md transition-all cursor-pointer group flex flex-col h-full relative"
