interface StandaloneEstimatorProps {
  embedded?: boolean;
  initialContext?: string;
  initialInputs?: EstimationInputs;
  onSave?: (inputs: EstimationInputs) => void;
}

const StandaloneEstimator: React.FC<StandaloneEstimatorProps> = ({ 
  embedded = false, 
  initialContext = '', 
  initialInputs, 
  onSave 
}) => {
  const [context, setContext] = useState(initialContext);
  const [showResults, setShowResults] = useState(embedded && initialInputs && Object.keys(initialInputs).length > 0 ? true : false);
  const [activeTab, setActiveTab] = useState<'drivers' | 'resources' | 'timeline' | 'assumptions'>('drivers');

  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});
  const [moduleConfigs, setModuleConfigs] = useState<ModuleConfig[]>(DEFAULT_MODULES_CONFIG);
  const [assumptions, setAssumptions] = useState<AssumptionData>({ inScope: [], outScope: [] });

  const [isGenerating, setIsGenerating] = useState(false);
  const [eta, setEta] = useState(0);

  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<any[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);
  const [aiRationale, setAiRationale] = useState<string>("Analyzing project requirements...");

  // Custom Driver State
  const [addingDriverToModule, setAddingDriverToModule] = useState<string | null>(null);
  const [newDriverData, setNewDriverData] = useState<{label: string, category: string, hours: number}>({ label: '', category: 'medium', hours: 8 });

  const [customResourceCounts, setCustomResourceCounts] = useState<Record<string, number>>({
    'pm': 1, 'arch': 1, 'lead': 1, 'dev': 2, 'qa': 1
  });

  useEffect(() => {
    if (initialInputs && Object.keys(initialInputs).length > 0) {
        setEstimationInputs(initialInputs);
    }
  }, [initialInputs]);

  // Load history on mount
  useEffect(() => {
      setHistoryItems(getHistory('Estimator'));
  }, [showResults]);

  // ETA Timer
  useEffect(() => {
    let interval: any;
    if (isGenerating && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isGenerating, eta]);

  // --- Calculations ---
  const totals = useMemo(() => {
    let totalHours = 0;
    moduleConfigs.forEach(mod => {
        mod.drivers.forEach(driver => {
            const count = estimationInputs[driver.id] || 0;
            totalHours += count * driver.multiplier;
        });
    });

    const contingency = Math.round(totalHours * 0.15); // 15% contingency
    const grandTotal = totalHours + contingency;

    // Resource sizing (simplified)
    const weeks = Math.max(8, Math.ceil(grandTotal / (40 * 3))); // Assume 3 devs avg
    const cost = grandTotal * 125; // $125/hr avg rate

    return { totalHours, contingency, grandTotal, weeks, cost };
  }, [estimationInputs, moduleConfigs]);

  const handleGenerate = async (refinement?: string) => {
      const input = refinement || context;
      if (!input.trim() && uploadedFiles.length === 0) return;

      setIsGenerating(true);
      setError(null);
      setEta(12);
      setShowResults(false);

      try {
          const fullContext = `${input} ${uploadedFiles.length > 0 ? `\n(Files: ${uploadedFiles.join(', ')})` : ''}`;

          // Parallel execution
          const [estResult, asmResult] = await Promise.all([
              generateDynamicEstimation(fullContext),
              generateAssumptions(fullContext)
          ]);

          setEstimationInputs(estResult.inputs);
          setAiRationale(estResult.rationale);
          setAssumptions(asmResult);

          setShowResults(true);

          if (onSave) onSave(estResult.inputs);

          saveHistory('Estimator', input.substring(0, 40) + '...', { 
              inputs: estResult.inputs, 
              assumptions: asmResult,
              context: fullContext 
          }, uploadedFiles);

          if (refinement) {
              analyzeAndLearn(fullContext, refinement, estResult.inputs, ['PM', 'Architect'], 'refinement');
          } else {
              analyzeAndLearn(fullContext, "Initial Estimate", estResult.inputs, ['PM', 'Architect'], 'initial');
          }

      } catch (e) {
          console.error(e);
          setError("Failed to generate estimate. Please try again.");
      } finally {
          setIsGenerating(false);
          setEta(0);
      }
  };

  const handleInputChange = (driverId: string, val: number) => {
      const newInputs = { ...estimationInputs, [driverId]: Math.max(0, val) };
      setEstimationInputs(newInputs);
      if (onSave) onSave(newInputs);
  };

  const loadHistoryItem = (item: any) => {
      setEstimationInputs(item.data.inputs);
      setAssumptions(item.data.assumptions || { inScope: [], outScope: [] });
      setContext(item.data.context || item.summary);
      setShowResults(true);
      setShowHistory(false);
      if (onSave) onSave(item.data.inputs);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setUploadedFiles(prev => [...prev, file.name]);
    }
  };

  const handleAddDriver = (moduleId: string) => {
      if (!newDriverData.label) return;

      const newDriver: EffortDriver = {
          id: `custom_${Date.now()}`,
          label: newDriverData.label,
          category: newDriverData.category as any,
          defaultValue: 0,
          multiplier: newDriverData.hours,
          description: 'Custom added driver'
      };

      setModuleConfigs(prev => prev.map(m => {
          if (m.id === moduleId) {
              return { ...m, drivers: [...m.drivers, newDriver] };
          }
          return m;
      }));

      // Initialize count to 1 for convenience
      setEstimationInputs(prev => ({...prev, [newDriver.id]: 1}));

      setAddingDriverToModule(null);
      setNewDriverData({ label: '', category: 'medium', hours: 8 });
  };

  return (
    <div className={`flex flex-col h-full bg-slate-50 relative ${embedded ? '' : 'p-6'}`}>

       {!embedded && (
           <div className="absolute top-4 right-4 z-20 flex gap-2">
               <button onClick={() => setShowHistory(!showHistory)} className="p-2 bg-white text-slate-500 rounded-lg shadow-sm border border-slate-200 hover:bg-slate-50">
                   <History size={20} />
               </button>
           </div>
       )}

       {showHistory && (
            <div className="absolute top-16 right-4 z-30 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 p-4 animate-fade-in-up">
                <h3 className="font-bold text-sm mb-3 text-slate-800">Recent Estimates</h3>
                <div className="space-y-2 max-h-60 overflow-y-auto">
                    {historyItems.length === 0 ? <p className="text-xs text-slate-400 text-center">No history</p> : 
                    historyItems.map((h, i) => (
                        <div key={i} onClick={() => loadHistoryItem(h)} className="p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-transparent hover:border-slate-200 group relative">
                            <div className="font-bold text-xs text-slate-700 truncate">{h.summary}</div>
                            <div className="text-[10px] text-slate-400">{h.date}</div>
                            <button 
                                onClick={(e) => { e.stopPropagation(); deleteHistory(h.id); setHistoryItems(prev => prev.filter(x => x.id !== h.id)); }} 
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-slate-400 hover:text-red-500"
                            >
                                <Trash2 size={12} />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
       )}

       {/* INPUT SECTION */}
       <div className={`${showResults && !embedded ? 'hidden md:flex' : 'flex'} flex-col gap-4 mb-6 transition-all`}>
           {!embedded && (
               <div className="flex items-center gap-3 mb-2">
                   <div className="p-3 bg-blue-600 rounded-xl text-white shadow-lg shadow-blue-200">
                       <Calculator size={24} />
                   </div>
                   <div>
                       <h2 className="text-2xl font-bold text-slate-800">Smart Estimator</h2>
                       <p className="text-slate-500 text-sm">AI-driven effort & cost analysis</p>
                   </div>
               </div>
           )}

           <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
               <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Project Context</label>
               <textarea 
                   className="w-full h-24 p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                   placeholder="Describe the project scope (e.g. 'Migrate 50 Oracle tables to Snowflake with medium transformations')..."
                   value={context}
                   onChange={(e) => setContext(e.target.value)}
               />
               <div className="flex justify-between items-center mt-3">
                   <label className="flex items-center gap-2 cursor-pointer text-xs font-bold text-slate-500 hover:text-blue-600 transition-colors">
                       <UploadCloud size={16} />
                       {uploadedFiles.length > 0 ? `${uploadedFiles.length} Files` : 'Attach Specs'}
                       <input type="file" className="hidden" onChange={handleFileUpload} multiple />
                   </label>
                   <button 
                       onClick={() => handleGenerate()} 
                       disabled={isGenerating || (!context && uploadedFiles.length === 0)}
                       className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-md"
                   >
                       {isGenerating ? <Loader size={16} className="animate-spin" /> : <Sparkles size={16} />}
                       {isGenerating ? `Analyzing (${eta}s)` : 'Calculate Estimate'}
                   </button>
               </div>
               {error && <div className="mt-2 text-xs text-red-500 flex items-center gap-1"><AlertTriangle size={12}/> {error}</div>}
           </div>
       </div>

       {/* RESULTS SECTION */}
       {showResults && (
           <div className="flex-1 overflow-y-auto animate-fade-in space-y-6">

               {/* Summary Cards */}
               <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
