interface SolutionDesignViewProps {
  request: RequestData | null;
  designCache: DesignCache;
  onUpdateDesignCache: (reqId: string, data: CachedRequestData) => void;
  onUpdateRequestStatus?: (reqId: string, status: 'Not Started' | 'In Progress' | 'Completed') => void;
  onDeleteRequest?: (reqId: string) => void;
  onBack?: () => void;
}

// Logic to extract context either from prompts or files
const getContextFromRequest = (req: RequestData): string => {
  if (req.requirementsPrompt && req.requirementsPrompt.length > 20) {
     const fileSummary = req.rfpFiles.length > 0 ? ` Additionally, consider these files: ${req.rfpFiles.join(', ')}.` : '';
     return `User Requirements: ${req.requirementsPrompt}.${fileSummary}`;
  }
  const files = req.rfpFiles;
  const combinedText = files.join(' ');
  // Mock contexts for demo
  if (combinedText.includes("AA Motors") || combinedText.includes("HANA")) return "Client: AA Motors. Source: SAP HANA (4.5M records). Requirement: Master Data Management for Customer (B2C). Logic: Ingress from HANA -> Landing (SQL) -> Staging -> MDM SaaS (Match & Merge) -> Egress to SQL. Governance: Mask mobile numbers. Volume: Daily delta.";
  if (combinedText.includes("Vehicle") || combinedText.includes("Adobe")) return "Client: Vehicle 360. Source: Adobe Analytics (CSV) & SAP. Integration: CDI Mappings for Product2, WorkOrder. Quality: Validate Campaign IDs. Error Handling: Route rejected rows to Azure Blob. Target: Salesforce CRM.";
  return "General IDMC Cloud Integration requirement. Source: On-Prem DB (Oracle). Target: Cloud Data Warehouse (Snowflake). Pattern: Batch ETL. Security: End-to-end encryption required.";
};

const SolutionDesignView: React.FC<SolutionDesignViewProps> = ({ request, designCache, onUpdateDesignCache, onUpdateRequestStatus, onDeleteRequest, onBack }) => {
  // Removed 'dataQuality' from activeSubTab type
  const [activeSubTab, setActiveSubTab] = useState<'overview' | 'blueprints' | 'requirements' | 'roadmap' | 'estimator' | 'scoping' | 'attachments'>('overview');
  const [status, setStatus] = useState<'idle' | 'thinking' | 'review' | 'accepted'>('idle');
  const [thoughts, setThoughts] = useState<string[]>([]);
  const [isLearning, setIsLearning] = useState(false);

  // ETA State
  const [eta, setEta] = useState(0);

  // Track progressive loading
  const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({});

  // Design States - ONLY HLD LEFT
  const [currentDesign, setCurrentDesign] = useState<DesignData>({ nodes: [], edges: [] });

  // Mermaid Context Input for blueprints
  const [mermaidContext, setMermaidContext] = useState("");

  const [questions, setQuestions] = useState<Question[]>([]);
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [initiationItems, setInitiationItems] = useState<InitiationItem[]>([]);
  // Kept dqRules in state for data consistency, even if tab is removed
  const [dqRules, setDqRules] = useState<DataQualityRule[]>([]);

  // New States for Research Mode
  const [projectStats, setProjectStats] = useState<ProjectStats | null>(null);
  const [roadmap, setRoadmap] = useState<RoadmapPhase[]>([]);

  // Estimator State
  const [estimationInputs, setEstimationInputs] = useState<EstimationInputs>({});

  const [localFiles, setLocalFiles] = useState<string[]>([]);
  const [refinementPrompt, setRefinementPrompt] = useState("");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (request) {
      setLocalFiles(request.rfpFiles || []); 
      setError(null);

      if (designCache[request.id]) {
        const cached = designCache[request.id];
        setCurrentDesign(cached.design);
        setQuestions(cached.questions);
        setRequirements(cached.requirements);
        setInitiationItems(cached.initiation || []);
        if (cached.dataQualityRules) setDqRules(cached.dataQualityRules);
        if (cached.estimationInputs) setEstimationInputs(cached.estimationInputs);
        if (cached.projectStats) setProjectStats(cached.projectStats);
        if (cached.roadmap) setRoadmap(cached.roadmap);
        setStatus(cached.status);
      } else {
        // No cache means NEW request.
        setStatus('idle');
        setProjectStats(null); // Reset for new request
        setRoadmap([]);
        setEstimationInputs({});
        setRequirements([]);
        setQuestions([]);
        setCurrentDesign({ nodes: [], edges: [] });
        setLoadingMap({});

        // Auto-Trigger Generation for new requests
        // Check if we are not already generating to avoid double call
        const timer = setTimeout(() => {
            if (status === 'idle') {
                handleGenerate(null, request.mode || 'design');
            }
        }, 100);
        return () => clearTimeout(timer);
      }
    }
  }, [request ? request.id : null]); // Depend only on ID to avoid loop

  // Timer Effect
  useEffect(() => {
    let interval: any;
    if (status === 'thinking' && eta > 0) {
      interval = setInterval(() => {
        setEta((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [status, eta]);

  // --- Helpers for learning triggers ---
  const triggerLearning = async (ctx: string, prompt: string | null, design: any, aud: string[], type: 'initial' | 'refinement' | 'acceptance') => {
      setIsLearning(true);
      try {
          await analyzeAndLearn(ctx, prompt, design, aud, type);
      } finally {
          setIsLearning(false);
      }
  };

  // --- Generation Handler ---
  const handleGenerate = async (promptOverride: string | null = null, forcedMode: 'design' | 'estimator' | 'dq' = 'design') => {
    if (!request) return;
    setStatus('thinking');
    setError(null);
    if (onUpdateRequestStatus) onUpdateRequestStatus(request.id, 'In Progress');
    setEta(15); // Set initial ETA to 15 seconds for main generation
    setThoughts([]);

    const audience = request.targetAudience || ['Developer']; 
    let context = getContextFromRequest(request) + (promptOverride ? ` Refinement: ${promptOverride}` : "");

    // Append Mermaid hints if available
    if (mermaidContext.trim()) {
        context += `\n[Reference Mermaid Structure]: ${mermaidContext}`;
    }

    // Dynamic thoughts array to show user we are learning
    const baseThoughts = [
          `Scanning Knowledge Base for similar patterns...`, // Added learning thought
          `Analyzing project scope...`,
          `Drafting technical architecture...`,
          "Identifying risks..."
    ];

    for (let i = 0; i < baseThoughts.length; i++) {
        await new Promise(r => setTimeout(r, 400)); 
        setThoughts(prev => [...prev, baseThoughts[i]]);
    }

    try {
      // Initialize loading indicators for secondary items
      setLoadingMap({
          roadmap: true,
          estimator: true,
          requirements: true,
          scoping: true,
          dq: true
      });

      // 1. CRITICAL PATH: Architecture & Stats (Block UI until these are ready)
      const pDesign = generateArchitectureDesign(context, request.type);
      const pStats = generateProjectStatistics(context);

      // 2. BACKGROUND PATH: Everything else (Update state progressively)
      const pRoadmap = generateFutureRoadmap(context).then(d => { 
          setRoadmap(d); 
          setLoadingMap(prev => ({...prev, roadmap: false})); 
      });

      const pEst = generateEstimation(context, request.type).then(d => { 
          setEstimationInputs(prev => ({...prev, ...d})); 
          setLoadingMap(prev => ({...prev, estimator: false})); 
      });

      const pReqs = generateProjectRequirements(context, request.type, audience).then(d => { 
          setRequirements(d); 
          setLoadingMap(prev => ({...prev, requirements: false})); 
      });

      const pQuest = generateIntelligentQuestionnaire(context, request.type, audience).then(d => { 
          setQuestions(d); 
          setLoadingMap(prev => ({...prev, scoping: false})); 
      });

      const pInit = generateInitiationChecklist(context, request.type, audience).then(d => setInitiationItems(d));

      // Even though DQ tab is removed, we might still generate rules for internal completeness or export
      const pDQ = generateDataQualityRules(context, request.type).then(d => { 
          setDqRules(d); 
          setLoadingMap(prev => ({...prev, dq: false})); 
      });

      // Await only critical items to make UI responsive faster
      const [design, stats] = await Promise.all([pDesign, pStats]);

      setCurrentDesign(design);

      // Ensure stats are never null to avoid empty state lock
      const safeStats = stats || { 
          executiveSummary: "AI stats generation incomplete.", 
          riskScore: 50, 
          complexityScore: 50, 
          technicalDebt: 'Medium', 
          keyRisks: ["Analysis incomplete"], 
          successProbability: 50 
      };
      setProjectStats(safeStats);

      setStatus('review'); // UNBLOCK UI NOW
      setEta(0); // Clear timer

      if (onUpdateRequestStatus) onUpdateRequestStatus(request.id, 'Completed');

      // Trigger Continuous Learning
      const type = promptOverride ? 'refinement' : 'initial';
      triggerLearning(context, promptOverride, design, audience, type);

    } catch (e) {
      console.error("Generation failed", e);
      setStatus('idle');
      // Set stats to a default error state so the UI shows SOMETHING instead of just spinning or resetting
      setProjectStats({
          executiveSummary: "AI Service Unavailable. Please verify connection and try again.",
          riskScore: 0,
          complexityScore: 0,
          technicalDebt: 'High',
          keyRisks: ["Service Error"],
          successProbability: 0
      });
      setError("AI Service Unavailable. Please verify API Key and try again.");
      setEta(0);
    }
  };

  const handleUpdateDesignFromRefinement = (newDesign: DesignData) => {
     setCurrentDesign(newDesign);
  };

  const saveToCache = () => {
    if (request) {
      const cacheData: CachedRequestData = {
        design: currentDesign,
        questions: questions,
        requirements: requirements,
        initiation: initiationItems,
        dataQualityRules: dqRules,
        estimationInputs: estimationInputs,
        projectStats: projectStats || undefined,
        roadmap: roadmap,
        status: 'accepted'
      };
      onUpdateDesignCache(request.id, cacheData);
    }
  };

  const handleAcceptDesign = () => {
    saveToCache();
    setStatus('accepted');
    const context = request ? getContextFromRequest(request) : "";
    if (request && request.mode !== 'estimator') {
         triggerLearning(context, "User Accepted Design", currentDesign, request.targetAudience, 'acceptance');
    }
  };

  const handleDelete = (e: React.MouseEvent) => {
      e.stopPropagation(); 
      if (request && onDeleteRequest) {
          onDeleteRequest(request.id);
      }
  };

  const handleAddFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFileName = e.target.files[0].name;
      if (!localFiles.includes(newFileName)) {
        setLocalFiles(prev => [...prev, newFileName]);
      }
    }
  };

  if (!request) return <div className="p-8 text-center text-slate-400">Select a request...</div>;

  const getCriticalityColor = (level: string) => {
    switch(level) {
      case 'High': return 'bg-red-100 text-red-700 border-red-200';
      case 'Medium': return 'bg-orange-100 text-orange-700 border-orange-200';
      default: return 'bg-blue-100 text-blue-700 border-blue-200';
    }
  };

  // Check if we have results to show (either cached or generated)
  // Modified to be true if projectStats exists (even error state)
  const hasResults = (status as string) !== 'idle' || projectStats !== null;

  // Nav Items - removed Data Quality
  const navItems = [
      { id: 'overview', label: 'Strategic Overview', icon: Target },
      { id: 'blueprints', label: 'Technical Blueprints', icon: Network },
      { id: 'estimator', label: 'Estimator & Costs', icon: Calculator },
      { id: 'roadmap', label: 'Future Roadmap', icon: Map },
      { id: 'requirements', label: 'Requirements', icon: List },
      { id: 'scoping', label: 'Scoping Q&A', icon: ClipboardList },
      { id: 'attachments', label: 'Files', icon: Paperclip },
  ];

  return (
    <div className="flex flex-col h-full bg-slate-50 animate-fade-in relative">
      <AiAssistant context={getContextFromRequest(request)} />

      {/* Deep Dive Header - Removed overflow-hidden for button visibility safety */}
      <div className="bg-white border-b border-slate-200 px-8 py-5 flex flex-wrap items-center justify-between gap-4 z-20 shadow-sm relative">
        {/* Abstract pattern background */}
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 pointer-events-none overflow-hidden"></div>
        <div className="absolute right-0 top-0 h-full w-1/3 bg-gradient-to-l from-slate-50 to-transparent pointer-events-none"></div>

        <div className="relative z-10 flex items-center gap-4">
          {onBack && (
             <button 
                onClick={onBack} 
                className="p-2 -ml-2 hover:bg-slate-100 rounded-full text-slate-500 hover:text-slate-800 transition-colors"
                title="Back to Hub"
             >
                <ArrowLeft size={24} />
             </button>
          )}

          <div className="flex items-center gap-3 mb-1">
            <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-lg shadow-indigo-200"><Box size={20}/></div>
            <div>
               <h2 className="text-xl font-bold text-slate-900 leading-tight">{request.clientName}</h2>
               <div className="flex items-center gap-2 text-xs text-slate-500">
                  <span className="font-semibold text-slate-700">{request.id}</span> • {request.type} ({request.deploymentModel})
               </div>
            </div>
            {isLearning && (
               <div className="ml-4 flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100 text-[10px] font-bold animate-pulse">
                  <BrainCircuit size={12} /> Learning Patterns...
               </div>
            )}
          </div>
        </div>

        {/* Project Health Indicators (Mock/Calculated) */}
        <div className="relative z-30 flex gap-4 items-center">
            {projectStats && (
                <div className="flex gap-6 mr-4 border-r border-slate-200 pr-6">
                    <div>
                        <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-0.5">Risk Score</div>
                        <div className="text-lg font-bold text-slate-700 flex items-center gap-1">
                            {projectStats.riskScore}%
                            <span className={`w-2 h-2 rounded-full ${projectStats.riskScore > 70 ? 'bg-red-500' : projectStats.riskScore > 30 ? 'bg-orange-500' : 'bg-emerald-500'}`}></span>
                        </div>
                    </div>
                    <div>
                        <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-0.5">Complexity</div>
                        <div className="text-lg font-bold text-slate-700">{projectStats.complexityScore}/100</div>
                    </div>
                    <div>
                        <div className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-0.5">Tech Debt</div>
                        <div className="text-lg font-bold text-slate-700">{projectStats.technicalDebt}</div>
                    </div>
                </div>
            )}

            {/* Delete Request Button - Bumped Z-Index, Type Button, and Pointer Events Logic */}
            {onDeleteRequest && (
                <button
                    type="button"
                    onClick={handleDelete}
                    className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-red-600 hover:bg-red-50 hover:border-red-300 rounded-xl transition-all shadow-sm cursor-pointer relative z-50 active:scale-95 flex-shrink-0"
                    title="Delete Request"
                >
                    <Trash2 size={18} className="pointer-events-none" />
                </button>
            )}

            {(status !== 'idle' || projectStats !== null) && (
                <button
                    onClick={() => handleGenerate(null, request.mode || 'design')}
                    disabled={status === 'thinking'}
                    className={`
                    flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white shadow-lg transition-all min-w-[160px] justify-center cursor-pointer active:scale-95 z-30
                    ${status === 'thinking' ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900 hover:bg-slate-800 hover:scale-105 hover:shadow-xl'}
                    `}
                >
                    {status === 'thinking' ? (
                        <>
                            <Loader size={16} className="animate-spin" />
                            <span>{eta > 0 ? `ETA: ${eta}s` : 'Analyzing...'}</span>
                        </>
                    ) : (
                        <>
                            <Sparkles size={16} className="text-indigo-300" />
                            <span>Update Analysis</span>
                        </>
                    )}
                </button>
            )}
        </div>
      </div>

      {/* CONDITIONAL RENDER: Only show content if data exists or thinking */}
      {hasResults ? (
        <>
          {/* Tabs */}
          <div className="bg-white border-b border-slate-200 px-8">
              <div className="flex gap-1 overflow-x-auto pb-0 hide-scrollbar">
                {navItems.map((tab) => (
                   <button 
                     key={tab.id}
                     onClick={() => setActiveSubTab(tab.id as any)}
                     className={`flex items-center gap-2 px-4 py-3 border-b-2 text-sm font-medium transition-colors whitespace-nowrap ${activeSubTab === tab.id ? 'border-indigo-600 text-indigo-700 bg-indigo-50/50' : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
                   >
                     <tab.icon size={16} />
                     {tab.label}
                     {loadingMap[tab.id] && <Loader size={12} className="animate-spin text-slate-400" />}
                   </button>
                ))}
              </div>
          </div>

          <div className="flex-1 overflow-y-auto bg-slate-50/50 relative">

            {/* --- 1. OVERVIEW TAB --- */}
            {activeSubTab === 'overview' && (
                <div className="p-8 max-w-7xl mx-auto animate-fade-in space-y-8">
                    {/* Executive Summary */}
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-6 opacity-5"><Target size={120} /></div>
                        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2"><Compass className="text-indigo-600"/> Executive Summary</h3>
                        {projectStats ? (
                            <div className="space-y-4 relative z-10">
                                <p className="text-slate-600 leading-relaxed text-sm md:text-base">{projectStats.executiveSummary}</p>
                                <div className="flex gap-3 mt-4">
                                    {projectStats.keyRisks.map((risk, i) => (
                                        <span key={i} className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-red-50 text-red-700 text-xs font-bold border border-red-100">
                                            <AlertTriangle size={12} /> {risk}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        ) : (
                            <div className="text-center py-10 text-slate-400">Run analysis to generate executive summary.</div>
                        )}
                    </div>

                    {/* Metrics Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                            <h4 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-6">Success Probability</h4>
                            <div className="relative h-4 bg-slate-100 rounded-full overflow-hidden">
                                <div className="absolute top-0 left-0 h-full bg-emerald-500 transition-all duration-1000" style={{width: `${projectStats?.successProbability || 0}%`}}></div>
                            </div>
                            <div className="mt-2 text-right font-bold text-slate-800">{projectStats?.successProbability || 0}%</div>
                        </div>
                        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                            <h4 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-6">Generated Artifacts</h4>
                            <div className="flex gap-4">
                                <div className="text-center">
                                    <div className="text-2xl font-bold text-indigo-600">{questions.length}</div>
                                    <div className="text-xs text-slate-400">Questions</div>
                                </div>
                                <div className="text-center">
                                    <div className="text-2xl font-bold text-indigo-600">{requirements.length}</div>
                                    <div className="text-xs text-slate-400">Reqs</div>
                                </div>
                                <div className="text-center">
                                    <div className="text-2xl font-bold text-indigo-600">{dqRules.length}</div>
                                    <div className="text-xs text-slate-400">DQ Rules</div>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col justify-center items-center text-center">
                            <div className="p-3 bg-blue-50 text-blue-600 rounded-full mb-3"><BarChart3 size={24}/></div>
                            <div className="text-sm font-medium text-slate-600">View Full Analytics</div>
                            <button onClick={() => setActiveSubTab('estimator')} className="text-xs text-blue-600 font-bold hover:underline mt-1">Go to Estimator &rarr;</button>
                        </div>
                    </div>
                </div>
            )}

            {/* --- 2. BLUEPRINTS TAB (Simple HLD Only) --- */}
            {activeSubTab === 'blueprints' && (
              <div className="h-full flex flex-col">
                 <div className="flex-1 relative">
                    <ArchitectureCanvas 
                        aiNodes={currentDesign.nodes} 
                        aiEdges={currentDesign.edges} 
                        isThinking={status === 'thinking'} 
                        thoughts={thoughts} 
                        context={getContextFromRequest(request)} 
                        audience={request.targetAudience} 
                        onApplyRefinement={handleUpdateDesignFromRefinement}
                        onRefine={(p) => {
                            setRefinementPrompt(p);
                            handleGenerate(p);
                        }}
                        refinementPlaceholder={`Refine High Level Design (e.g. 'Add a staging layer')...`}
                    />

                    <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-2xl flex flex-col gap-2 mx-4 z-0 pointer-events-none">
                        {/* Mermaid Code Input Wrapper - only show if not thinking */}
                        {status !== 'thinking' && (
                            <div className="bg-white/90 backdrop-blur-xl shadow-lg rounded-xl border border-white/50 p-2 flex items-center gap-2 mb-1 pointer-events-auto">
                                <div className="p-2 bg-slate-100 rounded-lg text-slate-500"><Code size={16} /></div>
                                <input 
                                    type="text" 
                                    placeholder="Paste optional Mermaid code/syntax hints here to guide the diagram..."
                                    className="flex-1 bg-transparent outline-none text-xs py-1 px-2 text-slate-600 placeholder:text-slate-400 font-mono" 
                                    value={mermaidContext} 
                                    onChange={(e) => setMermaidContext(e.target.value)} 
                                />
                            </div>
                        )}
                    </div>
                 </div>
              </div>
            )}

            {/* --- 3. ESTIMATOR (EMBEDDED) --- */}
            {activeSubTab === 'estimator' && (
                loadingMap.estimator ? (
                    <div className="flex flex-col items-center justify-center h-full text-slate-400">
                        <Loader size={32} className="animate-spin mb-4 text-indigo-500" />
                        <p>AI is calculating effort multipliers...</p>
                    </div>
                ) : (
                    <StandaloneEstimator 
                        embedded={true}
                        initialContext={getContextFromRequest(request)}
                        initialInputs={estimationInputs}
                        onSave={(inputs) => setEstimationInputs(inputs)}
                    />
                )
            )}

            {/* --- 4. ROADMAP --- */}
            {activeSubTab === 'roadmap' && (
                <div className="p-8 max-w-6xl mx-auto animate-fade-in">
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8">
                        <h3 className="text-xl font-bold text-slate-800 mb-8 flex items-center gap-2"><Map className="text-indigo-500"/> Strategic Implementation Roadmap</h3>
                        {loadingMap.roadmap ? (
                            <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                <Loader size={24} className="animate-spin mb-4 text-indigo-500" />
                                <p>AI is planning milestones...</p>
                            </div>
                        ) : roadmap.length === 0 ? (
                            <div className="text-center py-10 text-slate-400">Generate analysis to view roadmap.</div>
                        ) : (
                            <div className="relative border-l-2 border-slate-200 ml-4 space-y-10">
                                {roadmap.map((phase, i) => (
                                    <div key={i} className="relative pl-8">
                                        <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-white border-2 border-indigo-500"></div>
                                        <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 hover:shadow-md transition-shadow">
                                            <div className="flex justify-between items-start mb-3">
                                                <h4 className="text-lg font-bold text-indigo-900">{phase.phase}</h4>
                                                <span className="bg-white px-3 py-1 rounded border border-slate-200 text-xs font-bold text-slate-500 shadow-sm">{phase.duration}</span>
                                            </div>
                                            <p className="text-sm font-semibold text-slate-700 mb-4">{phase.focus}</p>
                                            <ul className="space-y-2">
                                                {phase.deliverables.map((d, idx) => (
                                                    <li key={idx} className="flex items-start gap-2 text-sm text-slate-600">
                                                        <CheckCircle size={14} className="mt-0.5 text-emerald-500 flex-shrink-0" />
                                                        {d}
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* --- EXISTING TABS (Styling Refreshed) --- */}
            {activeSubTab === 'requirements' && (
               <div className="p-8 max-w-6xl mx-auto space-y-6 animate-fade-in">
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                     <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><List className="text-blue-500" /> Technical Requirements</h3>
                     {loadingMap.requirements ? (
                        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                            <Loader size={24} className="animate-spin mb-4 text-blue-500" />
                            <p>AI is gathering requirements...</p>
                        </div>
                     ) : (
                         <div className="grid grid-cols-1 gap-4">
                              {requirements.map((req, i) => (
                                <div key={i} className="flex items-start gap-4 p-4 rounded-lg bg-slate-50 border border-slate-100">
                                  <div className="p-2 rounded-lg bg-white border border-slate-200 text-slate-600"><CheckCircle size={18} /></div>
                                  <div className="flex-1">
                                     <div className="flex justify-between items-start mb-1">
                                       <h4 className="font-semibold text-slate-800 text-sm">{req.item}</h4>
                                       <div className="flex gap-2">
                                          {req.audience && <span className="text-[10px] bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded border border-indigo-200">{req.audience}</span>}
                                          <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded border ${getCriticalityColor(req.criticality)}`}>{req.criticality}</span>
                                       </div>
                                     </div>
                                     <p className="text-sm text-slate-500">{req.description}</p>
                                  </div>
                                </div>
                              ))}
                         </div>
                     )}
                  </div>
               </div>
            )}

            {activeSubTab === 'scoping' && (
                <div className="p-8 max-w-6xl mx-auto animate-fade-in">
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><ClipboardList className="text-orange-500" /> Scoping & Discovery</h3>
                        {loadingMap.scoping ? (
                            <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                <Loader size={24} className="animate-spin mb-4 text-orange-500" />
                                <p>AI is generating questionnaire...</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {questions.map((q, i) => (
                                <div key={i} className="p-4 rounded-lg bg-slate-50 border border-slate-200">
                                    <label className="block text-sm font-bold text-slate-800 mb-2">{q.question}</label>
                                    <textarea className="w-full p-3 border border-slate-300 rounded-lg text-sm bg-white min-h-[80px]" placeholder="Response..." defaultValue={q.answer} />
                                </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}

            {activeSubTab === 'attachments' && (
              <div className="p-8 max-w-4xl mx-auto animate-fade-in">
                 <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
                   <div className="flex items-center justify-between mb-6">
                      <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><Paperclip className="text-indigo-500" /> Attached Documents</h3>
                      <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-medium transition-colors">
                          <Plus size={16} /> Add
                          <input type="file" className="hidden" onChange={handleAddFile} />
                      </label>
                   </div>
                   <div className="space-y-3">
                      {localFiles.map((file, idx) => (
                          <div key={idx} className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg border border-slate-200">
                            <FileText size={16} className="text-blue-500" />
                            <span className="text-sm font-medium text-slate-700">{file}</span>
                          </div>
                      ))}
                   </div>
                 </div>
              </div>
            )}
          </div>
        </>
      ) : (
        /* Empty State (Waiting for Auto-Start or Manual Trigger) */
        <div className="flex-1 flex flex-col items-center justify-center bg-slate-50 p-8">
            <div className="max-w-md text-center space-y-6">
                <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-6 relative">
                   <Rocket size={40} className="text-indigo-600" />
                   <div className="absolute -top-2 -right-2 bg-white rounded-full p-2 shadow-sm border border-slate-100">
                        <Sparkles size={16} className="text-orange-500" />
                    </div>
                </div>
                <div>
                    <h3 className="text-2xl font-bold text-slate-900 mb-2">Awaiting Analysis</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">
                        {error || "To generate architecture blueprints, cost estimates, and technical requirements, the AI needs to process your request context first."}
                    </p>
                </div>
                <button
                    onClick={() => handleGenerate(null, request.mode || 'design')}
                    className={`w-full text-white font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 hover:scale-[1.02] ${error ? 'bg-red-600 hover:bg-red-700' : 'bg-slate-900 hover:bg-indigo-600'}`}
                >
                    {error ? <RefreshCw size={18} /> : <Sparkles size={18} />}
                    {error ? 'Retry Analysis' : 'Start Research'}
                </button>
            </div>
        </div>
      )}
    </div>
  );
};

export default SolutionDesignView;
